import os as _os
def _pick_home():

    # is honoured ONLY where that directory already exists (the container, or a
    # machine whose earlier runs created it — continuity for existing data). It is
    # never CREATED on a user machine any more: on Windows it silently became

    # machine the home is now a .lazarus folder BESIDE THE ENGINE FILE, and the
    # banner prints the real, absolute, native path. LAZARUS_HOME env overrides
    # everything, always.
    cand = [_os.environ.get('LAZARUS_HOME'),
            _os.getcwd(),   # the directory this run was launched from
            _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '.lazarus'),
            _os.path.join(_os.getcwd(), '.lazarus')]
    for c in cand:
        if not c: continue
        try:
            _os.makedirs(c, exist_ok=True)
            t = _os.path.join(c, '.wtest')
            with open(t, 'w') as fh: fh.write('x')
            _os.remove(t)
            return _os.path.abspath(c)
        except Exception:
            continue
    import tempfile
    return tempfile.gettempdir()

LAZARUS_HOME = _pick_home()

def LAZ(*parts):
    """Join a path under LAZARUS_HOME without depending on any local `os` alias.

    Functions that do their own `import os` shadow the module-level `_os`, so a rewritten literal
    like `LAZ('x')` raised UnboundLocalError inside them. This helper is
    resolved at module scope and is immune to that."""
    import os as _o
    return _o.path.join(LAZARUS_HOME, *parts)
