def _resolve_chosen_weights():
    """Resolve CHOSEN_STRATEGIES_WEIGHT_MODE to concrete (profit, sharpe, consistency) weights."""
    presets = {
        'profit_focus':      (0.60, 0.30, 0.10),
        'sharpe_focus':      (0.25, 0.55, 0.20),
        'winrate_focus':     (0.25, 0.25, 0.50),
        'balanced':          (0.35, 0.35, 0.30),
        'consistency_focus': (0.20, 0.20, 0.60),
        'custom':            (CHOSEN_WEIGHT_PROFIT, CHOSEN_WEIGHT_SHARPE, CHOSEN_WEIGHT_CONSISTENCY),
    }
    w = presets.get(CHOSEN_STRATEGIES_WEIGHT_MODE, presets['custom'])
    total = sum(w)
    if abs(total - 1.0) > 0.01:
        print(f"[WARN] Chosen weights sum to {total:.2f}, not 1.0. Auto-normalizing.")
        w = tuple(v / total for v in w)
    return w

