# v74 NUMBA JIT ENGINE — Hot Loop Acceleration (10-100x inner loop)
# ═══════════════════════════════════════════════════════════════════════════════
def _sys_exe_for_numba_hint():
    """The running interpreter path, so a numba mismatch names itself."""
    import sys as _s
    return _s.executable


_NUMBA_AVAILABLE = False
_NUMBA_ERR = None
try:
    from numba import njit, prange
    _NUMBA_AVAILABLE = True
except BaseException as _ne:
    # Catch BaseException, not ImportError. numba can fail on a numpy ABI mismatch, an
    # llvmlite load error or a stale cache -- none of which are ImportError, and any of
    # which would otherwise propagate and kill the whole engine at import. Recording the
    # reason matters: a user whose `python3 -c "import numba"` succeeds while the engine
    # says "not installed" has no way to act on a message that names no cause.
    _NUMBA_ERR = f'{type(_ne).__name__}: {_ne}'
    # Graceful fallback: create no-op decorators that just return the function
    def njit(*args, cache=False, **kwargs):
        def decorator(f): return f
        return decorator if not args or not callable(args[0]) else decorator(args[0])
    prange = range
    print(f'[WARN] Numba unavailable — numpy fallback mode. Reason: {_NUMBA_ERR}')
    print('[WARN] If `python3 -c "import numba"` works but this line still appears, the '
          'engine is running on a DIFFERENT interpreter than the one holding numba.')
    print(f'[WARN] This interpreter: {_sys_exe_for_numba_hint()}')
    print("[WARN] For 10-100x speedup:  pip install numba")


def _encode_str_array(arr, mapping=None):
    """Encode string numpy array as int64 for numba compatibility."""
    if arr is None or len(arr) == 0:
        return np.zeros(0, dtype=np.int64), {}
    uniques = np.unique(arr)
    if mapping is None:
        mapping = {v: i for i, v in enumerate(uniques)}
    encoded = np.array([mapping.get(v, -1) for v in arr], dtype=np.int64)
    return encoded, mapping


