# PHASE 2B — PREMATCH SENSITIVITY ANALYZER (v69 Addition)
# ═══════════════════════════════════════════════════════════════════════════════
class PrematchSensitivityAnalyzer:
    """
    Discovers optimal prematch odds/spread combinations per strategy.
    Two approaches: Adaptive Zoom-In (2D peak detection + fine grid)
                    Dual 1D Sweep (sequential 1D optimization + 3x3 neighborhood)
    Two scoring modes: Pareto (hard filters + priority stack)
                       Weighted (composite score)
    """

    def __init__(self, engine, col_map, grid_values, mode='both', scoring='pareto', auto_apply=True):
        self.engine = engine
        self.col_map = col_map
        self.grid_values = grid_values
        self.mode = mode
        self.scoring = scoring
        self.auto_apply = auto_apply
        self.comparison_results = []
        self.reject_counts = {'n_bets': 0, 'p_value': 0, 'sharpe': 0, 'roi': 0}

    def _ensure_prematch_config(self, strategy_name, cfg):
        """Auto-enable prematch columns using PER-STRATEGY config (v74.1 PARTNER FIX).
        Each strategy gets its own grid ranges tailored to its betting logic.
        """
        strat_cfg = SENSITIVITY_STRATEGY_CONFIG.get(strategy_name)
        if strat_cfg is None:
            return cfg  # No sensitivity config for this strategy

        # Column 1: strategy-specific column, comparator, and grid
        c1_name, c1_comp, c1_vals = strat_cfg['col1']
        if 'prematch_odds_col' not in cfg:
            cfg['prematch_odds_col'] = c1_name
            cfg['prematch_comparator'] = c1_comp
            cfg['prematch_thresholds'] = list(c1_vals)

        # Column 2: strategy-specific secondary filter
        c2_name, c2_comp, c2_vals = strat_cfg['col2']
        if 'prematch_spread_col' not in cfg:
            cfg['prematch_spread_col'] = c2_name
            cfg['prematch_spread_comparator'] = c2_comp
            cfg['prematch_spread_thresholds'] = list(c2_vals)

        return cfg

    def _score_result(self, res, scoring_mode):
        """Score a sensitivity result. Returns -9999 if hard filters fail.
        v74.1: Uses configurable SENSITIVITY_MIN_* thresholds instead of hardcoded 15/10.
        """
        if res is None or res['n_bets'] < SENSITIVITY_MIN_BETS:
            self.reject_counts['n_bets'] += 1
            return -9999.0
        sharpe = res['sharpe_profit_per_dd']
        roi = res['roi']
        win_rate = res['win_rate']
        max_loss = res['max_consecutive_losses']
        pval = res['p_value_ttest']

        # v74.1: Configurable filters (loosened defaults for real-world data)
        if pval >= SENSITIVITY_MAX_PVALUE:
            self.reject_counts['p_value'] += 1
            return -9999.0
        if sharpe < SENSITIVITY_MIN_SHARPE:
            self.reject_counts['sharpe'] += 1
            return -9999.0
        if roi < SENSITIVITY_MIN_ROI:
            self.reject_counts['roi'] += 1
            return -9999.0

        if scoring_mode == 'pareto':
            # Priority stack: Sharpe_DD → ROI → -MaxConsecLoss → WinRate
            return (sharpe * 1e6) + (roi * 1e3) + (-max_loss * 10.0) + (win_rate * 0.01)
        else:
            # Weighted composite
            return (0.4 * sharpe) + (0.3 * roi) - (0.1 * max_loss) + (0.2 * win_rate)

    def _evaluate_combo(self, strategy_name, cfg, time_rule, league_filter, threshold,
                        col1_val, col2_val, features_is):
        """Evaluate a single prematch combination using lightweight metrics."""
        saved_features = self.engine.features
        self.engine.features = features_is
        try:
            pool = self.engine._build_pool(strategy_name, time_rule, league_filter, cfg=cfg)
            if pool is None or len(pool) == 0:
                return None
            res = self.engine._evaluate_variant_minimal(
                strategy_name, cfg, threshold, time_rule, league_filter, pool,
                prematch_threshold=col1_val, prematch_spread_threshold=col2_val
            )
            return res
        finally:
            self.engine.features = saved_features

    def _compute_fine_step(self, grid):
        """Compute fine grid step as 1/5 of average gap between coarse points.
        v74.2 FIX: Exclude 999.0 sentinel from gap calculation — it produces
        massive gaps (e.g., 5.0 -> 999.0 = 994.0) that make fine steps ~200+,
        which then generate absurd spread values like 25.0, 50.0 that kill all pools.
        """
        # Filter out sentinel values (>= 900) — only use realistic value gaps
        real_vals = [v for v in grid if v < 900]
        if len(real_vals) < 2:
            return 0.1
        gaps = [real_vals[i+1] - real_vals[i] for i in range(len(real_vals)-1) if real_vals[i+1] != real_vals[i]]
        if not gaps:
            return 0.1
        avg_gap = sum(gaps) / len(gaps)
        return max(avg_gap / 5.0, 0.05)

    def _run_zoom_in(self, strategy_name, cfg, time_rule, league_filter, threshold, features_is, scoring_mode):
        """Adaptive Zoom-In: coarse sweep → peak detection → fine micro-grid."""
        cols = self.col_map.get(strategy_name, [])
        if len(cols) < 2:
            return None

        col1, col2 = cols[0], cols[1]
        grid1 = self.grid_values.get(col1, [999.0])
        grid2 = self.grid_values.get(col2, [999.0])
        n1, n2 = len(grid1), len(grid2)

        # Phase 1A: Coarse sweep
        coarse_scores = np.full((n1, n2), -9999.0)
        for i, v1 in enumerate(grid1):
            for j, v2 in enumerate(grid2):
                res = self._evaluate_combo(strategy_name, cfg, time_rule, league_filter, threshold, v1, v2, features_is)
                coarse_scores[i, j] = self._score_result(res, scoring_mode)

        # Phase 2: Local maxima detection
        peaks = []
        for i in range(n1):
            for j in range(n2):
                if coarse_scores[i, j] <= -1000:
                    continue
                is_peak = True
                for di in [-1, 0, 1]:
                    for dj in [-1, 0, 1]:
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n1 and 0 <= nj < n2:
                            if coarse_scores[ni, nj] > coarse_scores[i, j]:
                                is_peak = False
                                break
                    if not is_peak:
                        break
                if is_peak:
                    peaks.append((i, j))

        if not peaks:
            best_idx = (np.unravel_index(_laz_argmax(coarse_scores), coarse_scores.shape)
                if np.asarray(coarse_scores).size else tuple(0 for _ in np.asarray(coarse_scores).shape))
            peaks = [best_idx]

        # Phase 3: Fine micro-grid around each peak
        fine_step1 = self._compute_fine_step(grid1)
        fine_step2 = self._compute_fine_step(grid2)
        best_score = -9999.0
        best_result = None
        best_vals = None

        for pi, pj in peaks:
            base_v1 = grid1[pi]
            base_v2 = grid2[pj]

            if base_v1 >= 900:
                fine1 = [base_v1]
            else:
                fine1 = [base_v1 + (k - 2) * fine_step1 for k in range(5)]
                fine1 = [max(grid1[0], min(grid1[-1], v)) for v in fine1]
                fine1 = sorted(list(set(fine1)))

            if base_v2 >= 900:
                fine2 = [base_v2]
            else:
                fine2 = [base_v2 + (k - 2) * fine_step2 for k in range(5)]
                fine2 = [max(grid2[0], min(grid2[-1], v)) for v in fine2]
                fine2 = sorted(list(set(fine2)))

            for fv1 in fine1:
                for fv2 in fine2:
                    res = self._evaluate_combo(strategy_name, cfg, time_rule, league_filter, threshold, fv1, fv2, features_is)
                    score = self._score_result(res, scoring_mode)
                    if score > best_score:
                        best_score = score
                        best_result = res
                        best_vals = (fv1, fv2)

        if best_result is None:
            return None

        return {
            'strategy': strategy_name, 'approach': 'zoom_in', 'scoring': scoring_mode,
            'col1_name': col1, 'col1_thresh': best_vals[0],
            'col2_name': col2, 'col2_thresh': best_vals[1],
            'score': best_score,
            **{k: best_result[k] for k in ['n_bets', 'wins', 'losses', 'win_rate', 'total_profit',
                                            'profit_per_bet', 'roi', 'max_drawdown', 'max_consecutive_losses',
                                            'sharpe_profit_per_dd', 'p_value_ttest']}
        }

    def _run_1d_sweep(self, strategy_name, cfg, time_rule, league_filter, threshold, features_is, scoring_mode):
        """Dual 1D Sweep: sweep col1 → fix best → sweep col2 → test 3x3 neighborhood."""
        cols = self.col_map.get(strategy_name, [])
        if len(cols) < 2:
            return None

        col1, col2 = cols[0], cols[1]
        grid1 = self.grid_values.get(col1, [999.0])
        grid2 = self.grid_values.get(col2, [999.0])

        # Step 1: Fix col2 at median, sweep col1
        mid2 = grid2[len(grid2) // 2]
        best_i = 0
        best_score = -9999.0
        for i, v1 in enumerate(grid1):
            res = self._evaluate_combo(strategy_name, cfg, time_rule, league_filter, threshold, v1, mid2, features_is)
            score = self._score_result(res, scoring_mode)
            if score > best_score:
                best_score = score
                best_i = i

        # Step 2: Fix col1 at best, sweep col2
        best_v1 = grid1[best_i]
        best_j = 0
        best_score = -9999.0
        for j, v2 in enumerate(grid2):
            res = self._evaluate_combo(strategy_name, cfg, time_rule, league_filter, threshold, best_v1, v2, features_is)
            score = self._score_result(res, scoring_mode)
            if score > best_score:
                best_score = score
                best_j = j

        # Step 3: Test 3x3 neighborhood around (best_i, best_j)
        best_score = -9999.0
        best_result = None
        best_vals = None
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                ni = best_i + di
                nj = best_j + dj
                if 0 <= ni < len(grid1) and 0 <= nj < len(grid2):
                    v1 = grid1[ni]
                    v2 = grid2[nj]
                    res = self._evaluate_combo(strategy_name, cfg, time_rule, league_filter, threshold, v1, v2, features_is)
                    score = self._score_result(res, scoring_mode)
                    if score > best_score:
                        best_score = score
                        best_result = res
                        best_vals = (v1, v2)

        if best_result is None:
            return None

        return {
            'strategy': strategy_name, 'approach': '1d_sweep', 'scoring': scoring_mode,
            'col1_name': col1, 'col1_thresh': best_vals[0],
            'col2_name': col2, 'col2_thresh': best_vals[1],
            'score': best_score,
            **{k: best_result[k] for k in ['n_bets', 'wins', 'losses', 'win_rate', 'total_profit',
                                            'profit_per_bet', 'roi', 'max_drawdown', 'max_consecutive_losses',
                                            'sharpe_profit_per_dd', 'p_value_ttest']}
        }

    def run(self, features_is, min_bets=100):
        """Run sensitivity analysis and return (discoveries, comparison_rows)."""
        print(f"[SENSITIVITY] Mode={self.mode} | Scoring={self.scoring} | AutoApply={self.auto_apply}")
        discoveries = []
        comparison = []

        scoring_modes = ['pareto', 'weighted'] if self.scoring == 'both' else [self.scoring]
        approaches = []
        if self.mode in ('zoom_in', 'both'):
            approaches.append('zoom_in')
        if self.mode in ('1d_sweep', 'both'):
            approaches.append('1d_sweep')

        for strategy_name in self.col_map:
            if strategy_name not in self.engine.grid:
                continue

            cfg = self.engine.grid[strategy_name].copy()
            cfg = self._ensure_prematch_config(strategy_name, cfg)

            # Fixed parameters for sensitivity scan
            time_rules = self.engine._expand_time_rules(cfg['time_rules'])
            time_rule = time_rules[0] if time_rules else {}
            league_filter = 'All'
            thresholds = cfg['thresholds']
            fixed_threshold = thresholds[len(thresholds) // 2]

            print(f"[SENSITIVITY] Scanning {strategy_name} | threshold={fixed_threshold} | time_rule={time_rule}")

            strategy_results = []
            for approach in approaches:
                for scoring_mode in scoring_modes:
                    if approach == 'zoom_in':
                        result = self._run_zoom_in(strategy_name, cfg, time_rule, league_filter,
                                                   fixed_threshold, features_is, scoring_mode)
                    else:
                        result = self._run_1d_sweep(strategy_name, cfg, time_rule, league_filter,
                                                    fixed_threshold, features_is, scoring_mode)

                    if result:
                        strategy_results.append(result)
                        comparison.append(result)
                        print(f"[SENSITIVITY] {approach}+{scoring_mode} | {result['col1_name']}={result['col1_thresh']} "
                              f"| {result['col2_name']}={result['col2_thresh']} | "
                              f"Bets={result['n_bets']} | Profit={result['total_profit']:.1f} | "
                              f"WR={result['win_rate']:.1f}% | Sharpe={result['sharpe_profit_per_dd']:.2f}")

            # Pick auto-winner for this strategy
            if strategy_results:
                winner = max(strategy_results,
                             key=lambda r: (r['sharpe_profit_per_dd'], r['roi'], -r['max_consecutive_losses']))
                winner['is_winner'] = True
                for r in strategy_results:
                    if r is not winner:
                        r['is_winner'] = False
                discoveries.append(winner)
                print(f"[SENSITIVITY] WINNER for {strategy_name}: {winner['approach']}+{winner['scoring']} | "
                      f"Bets={winner['n_bets']} | Profit={winner['total_profit']:.1f} | "
                      f"WR={winner['win_rate']:.1f}% | Sharpe={winner['sharpe_profit_per_dd']:.2f} | ROI={winner['roi']:.2f}")
            else:
                print(f"[SENSITIVITY] No valid combinations found for {strategy_name}")

        # v74.1: Phase 2 Summary
        total_evaluated = sum(self.reject_counts.values()) + len(comparison)
        if total_evaluated > 0:
            print(f"\n{'='*70}")
            print(f"[PHASE 2 SUMMARY] Prematch Sensitivity Analysis Complete")
            print(f"{'='*70}")
            print(f"  Strategies scanned:    {len(self.col_map)}")
            print(f"  Valid combinations:    {len(comparison)}")
            print(f"  Filter rejections:     {sum(self.reject_counts.values())}")
            print(f"    - Too few bets (<{SENSITIVITY_MIN_BETS}):      {self.reject_counts['n_bets']}")
            print(f"    - High p-value (>={SENSITIVITY_MAX_PVALUE}):     {self.reject_counts['p_value']}")
            print(f"    - Low Sharpe (<{SENSITIVITY_MIN_SHARPE}):      {self.reject_counts['sharpe']}")
            print(f"    - Low ROI (<{SENSITIVITY_MIN_ROI}):         {self.reject_counts['roi']}")
            print(f"  Auto-winners:          {len(discoveries)}")
            print(f"{'='*70}\n")

        return discoveries, comparison

    def apply_discovered_thresholds(self, engine, discoveries):
        """Update STRATEGY_GRID to use discovered thresholds only."""
        print(f"[SENSITIVITY] Applying {len(discoveries)} discovered threshold sets to STRATEGY_GRID...")

        # Deep-copy to avoid mutating the global STRATEGY_GRID permanently
        if engine.grid is STRATEGY_GRID:
            engine.grid = copy.deepcopy(STRATEGY_GRID)

        for disc in discoveries:
            sname = disc['strategy']
            if sname not in engine.grid:
                continue
            cfg = engine.grid[sname]
            col1_name = disc['col1_name']
            col2_name = disc['col2_name']

            cfg['prematch_odds_col'] = col1_name
            cfg['prematch_comparator'] = SENSITIVITY_DEFAULT_COMPARATORS.get(col1_name, 'le')
            cfg['prematch_thresholds'] = [disc['col1_thresh']]

            cfg['prematch_spread_col'] = col2_name
            cfg['prematch_spread_comparator'] = SENSITIVITY_DEFAULT_COMPARATORS.get(col2_name, 'ge')
            cfg['prematch_spread_thresholds'] = [disc['col2_thresh']]

            print(f"[SENSITIVITY] {sname} locked to {col1_name}<={disc['col1_thresh']} | {col2_name}>={disc['col2_thresh']}")


# ═══════════════════════════════════════════════════════════════════════════════
# v71 ADD-ON : Discovery Persistence — Save/Reload Discovered Conditions
# ═══════════════════════════════════════════════════════════════════════════════
class DiscoveryPersistence:
    """
    Save discovered conditions (from Phase 4 greedy discovery) to JSON.
    Loads previously discovered conditions to seed CONDITION_POOL on next run.
    """
    @staticmethod
    def save(overrides: dict, path: str = PERSIST_FILE) -> None:
        """Save override dict {strategy: {extra_conditions: [...], prematch: {...}}}"""
        import json
        try:
            with open(path, 'w') as fh:
                json.dump(overrides, fh, indent=2, default=str)
            print(f"[DISCOVERY PERSIST] Saved {len(overrides)} strategies to {path}")
        except Exception as e:
            print(f"[DISCOVERY PERSIST] Save failed: {e}")

    @staticmethod
    def load(path: str = PERSIST_FILE) -> dict:
        """Load previously discovered conditions. Returns {} if no file."""
        import json, os
        if not os.path.exists(path):
            print(f"[DISCOVERY PERSIST] No cache file found at {path}")
            return {}
        try:
            with open(path) as fh:
                loaded = json.load(fh)
            print(f"[DISCOVERY PERSIST] Loaded conditions for {len(loaded)} strategies from {path}")
            return loaded
        except Exception as e:
            print(f"[DISCOVERY PERSIST] Load failed: {e}")
            return {}


# ═══════════════════════════════════════════════════════════════════════════════
# v71 ADD-ON : Threshold Sensitivity Analyzer
# ═══════════════════════════════════════════════════════════════════════════════
class ThresholdSensitivityAnalyzer:
    """
    Pre-filter thresholds per strategy based on coarse (1d_sweep) evaluation.
    Only keep thresholds that produce Sharpe_DD >= min_sharpe_dd and a positive
    win rate.  This avoids wasting time on obviously poor thresholds in the
    full combinatorial backtest.
    """
    def __init__(self, min_sharpe_dd: float = 0.05):
        self.min_sharpe_dd = min_sharpe_dd

    def filter_thresholds(self, strategy_name: str, thresholds: list,
                          best: list, results_df: pd.DataFrame) -> list:
        """
        Return a SUBSET of *thresholds* that pass the coarse filter.

        Parameters
        ----------
        strategy_name : name of strategy being filtered
        thresholds    : FULL list of candidate thresholds (e.g. [1.18, 1.20, ...])
        best          : best rows from 1d_sweep for this strategy
        results_df    : DataFrame with at least 'sharpe_dd' and 'win_rate' columns

        Returns
        -------
        filtered list of thresholds
        """
        if not best:
            return thresholds
        best_row = best[0]
        best_sharpe = best_row.get('sharpe_dd', 0)

        if best_sharpe < self.min_sharpe_dd:
            print(f"[THRESHOLD FILTER] {strategy_name}: best Sharpe_DD={best_sharpe:.3f} < {self.min_sharpe_dd} — dropping all thresholds")
            return []

        accepted = []
        for t in thresholds:
            row = results_df[results_df['threshold'].astype(float).round(4) == round(t, 4)]
            if not row.empty and row.iloc[0].get('win_rate', 0) > 0:
                accepted.append(t)
        if len(accepted) < len(thresholds):
            print(f"[THRESHOLD FILTER] {strategy_name}: {len(thresholds)} → {len(accepted)} thresholds (Sharpe_DD >= {self.min_sharpe_dd})")
        return accepted


# ═══════════════════════════════════════════════════════════════════════════════
# PHASE 3 — COMBINATORIAL BACKTEST ENGINE
# ═══════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════
# WIN-RATE GATE — Strategy-dependent & Odds-dependent floors
# ═══════════════════════════════════════════════════════════════════════════════
class WinRateGate:
    """
    Replace hardcoded win_rate < 20 with configurable floors.
    Modes: 'legacy' (flat 20%), 'strategy' (per-strategy), 'odds' (by avg_odds)
    """
    STRATEGY_FLOORS = {
        'Leader': 45.0, 'HT_Leader_1': 35.0, 'HT_Leader_2': 35.0,
        'HT_Fav_Lead_Early': 35.0, 'Draw_Trap': 25.0, 'Draw': 25.0,
        'False_Favorite': 20.0, 'Fav_Up_1_Type1': 20.0, 'Fav_Up_1_Type2': 20.0,
        'Early_Hammer': 12.0, 'Fav_Down_1G': 12.0,
        'Loser_1G': 10.0, 'Loser_1G_Mid': 10.0, 'Loser_1G_Momentum': 10.0,
        'Loser_1G_Fresh': 10.0, 'Loser_2G': 5.0,
        'Double_Trouble': 8.0, 'Double_Trouble_Early': 8.0,
        'Hedge_1G': 3.0, 'Hedge_2GL': 3.0, 'Hedge_2GD': 3.0,
        'Leader_Trap': 25.0, 'Leader_Trap_Late': 25.0,
        'HT_Underdog_Fade': 20.0,
    }

    @classmethod
    def get_floor(cls, mode, strategy_name, avg_odds):
        if mode == 'legacy':
            raw = 20.0
        elif mode == 'strategy':
            raw = cls.STRATEGY_FLOORS.get(strategy_name, 10.0)
        elif mode == 'odds':
            if avg_odds >= 15.0:   raw = 5.0
            elif avg_odds >= 10.0: raw = 8.0
            elif avg_odds >= 5.0:  raw = 12.0
            elif avg_odds >= 3.0:  raw = 20.0
            else:                   raw = 25.0
        else:
            raise ValueError(f"Unknown mode: {mode}")
        # Clamp to global minimum — never go below MIN_WIN_RATE_FLOOR
        return max(raw, MIN_WIN_RATE_FLOOR)

    @classmethod
    def verdict(cls, mode, strategy_name, avg_odds, win_rate, sharpe_dd, oos_pass,
                p_value, vol_alert, drift_alert, stab_ratio):
        floor = cls.get_floor(mode, strategy_name, avg_odds)
        if not oos_pass or p_value >= 0.05 or win_rate < floor:
            return 'HOLD'
        if vol_alert == 'Adapted' or drift_alert == 'Adapted' or stab_ratio < 0.50:
            return 'MONITOR'
        # v33: Configurable DEPLOY threshold (was hardcoded 15.0)
        caution_threshold = DEPLOY_MIN_SHARPE * 0.70  # CAUTION at 70% of DEPLOY
        if sharpe_dd < caution_threshold or stab_ratio < 0.70:
            return 'CAUTION'
        if sharpe_dd < DEPLOY_MIN_SHARPE:
            return 'CAUTION'
        return 'DEPLOY'


# ═══════════════════════════════════════════════════════════════════════════════
# PROFIT MATH — Corrected dual-leg & Leader_Trap payout
# ═══════════════════════════════════════════════════════════════════════════════
class ProfitMath:
    """
    Standard:       1u stake, win = odds-1, loss = -1
    Leader_Trap:    Filter on leader_odds_rt, payout uses draw_odds
    Dual-leg:       0.5u on loser + 0.5u on draw = 1u total stake
    """
    @staticmethod
    def standard(bets, odds_col, won):
        return np.where(won, bets[odds_col] - 1, -1)

    @staticmethod
    def leader_trap(bets, payout_odds_col, won):
        return np.where(won, bets[payout_odds_col] - 1, -1)

    @staticmethod
    def dual_leg(bets, loser_odds_col, draw_odds_col, l_won, d_won):
        leg_l = np.where(l_won, 0.5 * (bets[loser_odds_col] - 1), -0.5)
        leg_d = np.where(d_won, 0.5 * (bets[draw_odds_col] - 1), -0.5)
        return leg_l + leg_d

    @staticmethod
    def dispatch(bets, cfg, odds_col, won, final_result):
        if cfg.get('is_dual_leg'):
            draw_col = cfg.get('draw_odds_col', 'draw_odds')
            d_won = final_result == 'Draw'
            return ProfitMath.dual_leg(bets, odds_col, draw_col, won, d_won)
        if 'payout_odds_col' in cfg:
            return ProfitMath.leader_trap(bets, cfg['payout_odds_col'], won)
        return ProfitMath.standard(bets, odds_col, won)


# ═══════════════════════════════════════════════════════════════════════════════
# VECTORIZED POOL & PARALLEL WORKER (Gate-Validated Identical to v60 Logic)
# ═══════════════════════════════════════════════════════════════════════════════

class VectorizedPool:
    """v74 Ultra: O(L+K) chronological trigger scan with 3-level cache + precomputed masks."""
    def __init__(self, features_df, prebuilt_arrs=None, strategy_names=None):
        # v16 OPT: strategy_names restricts extra_mask precompute to the ACTIVE
        # strategies (typically ~24-30) instead of all ~198 in STRATEGY_GRID.
        # None preserves the original behaviour (precompute everything).
        t0 = time.time()
        self.features = features_df.reset_index(drop=True)
        # [FIX v76_70] This guard was inverted in effect. It sorted by
        # ['match_id','timestamp'] ONLY when timestamp was NOT already
        # monotonic -- so a well-formed tick feed (monotonic by time) skipped
        # the sort entirely, leaving _match_ids interleaved across concurrent
        # matches. The run-length `boundaries` scan in the pool builder below
        # then cut a new "match" at every interleave point. The sort is
        # unconditional now: the pool builder REQUIRES contiguity by match, and
        # ['match_id','timestamp'] is a superset of time order within a match.
        self.features = self.features.sort_values(
            ['match_id', 'timestamp'], kind='mergesort').reset_index(drop=True)
        self._match_ids = self.features['match_id'].values
        self._leagues = self.features['league'].values
        self._minutes = self.features['minute'].values
        self._progress = self.features['league_time_progress'].values
        self._phase = self.features['phase_half_rt'].values
        # v16 FIX: use pandas' dtype check rather than np.issubdtype — under
        # pandas 3.x string columns are StringDtype, which np.issubdtype cannot
        # interpret and would raise TypeError. is_numeric_dtype is version-safe.
        _ts_series = self.features['timestamp']
        if pd.api.types.is_numeric_dtype(_ts_series):
            self._ts = _ts_series.values.astype(np.int64)
        else:
            self._ts = pd.to_datetime(_ts_series, format='mixed').astype(np.int64)
        self._col_cache = dict(prebuilt_arrs) if prebuilt_arrs else {}

        # v74 LAYER 1: Precompute strategy extra_masks ONCE as numpy bool arrays.
        # v16: only for the ACTIVE strategies when strategy_names is provided.
        self._extra_mask_cache = {}
        if strategy_names is None:
            _mask_items = list(STRATEGY_GRID.items())
        else:
            _mask_items = [(s, STRATEGY_GRID[s]) for s in strategy_names if s in STRATEGY_GRID]
        for sname, cfg in _mask_items:
            try:
                mask = cfg['extra_mask'](self.features).values.astype(np.bool_)
            except Exception as e:
                # V11 FIX: All-False is SAFE (strategy produces 0 bets), 
                # all-True is DANGEROUS (fires on every row producing garbage)
                print(f"[WARN] VectorizedPool: extra_mask for '{sname}' failed: {type(e).__name__}: {e}")
                print(f"[WARN]   Strategy '{sname}' will produce ZERO bets. Check required columns.")
                mask = np.zeros(len(self.features), dtype=np.bool_)
            self._extra_mask_cache[sname] = mask

        # v74 LAYER 2: 3-level pool cache
        self._l2_time_cache = {}   # (sname, tr_hash) → time_mask
        self._l3_league_cache = {} # (sname, tr_hash, league) → pool_indices
        dt = time.time() - t0
        print(f"[v74 POOL] Initialized {len(self.features):,} rows | {len(self._extra_mask_cache)} strategy masks precomputed | {dt:.2f}s")

    def _hash_time_rule(self, time_rule):
        if not time_rule:
            return 'empty'
        parts = []
        for k in sorted(time_rule.keys()):
            v = time_rule[k]
            if isinstance(v, list):
                parts.append(f"{k}={','.join(str(x) for x in sorted(v))}")
            else:
                parts.append(f"{k}={v}")
        return '|'.join(parts)

    def _get_col(self, col_name):
        if col_name not in self._col_cache:
            self._col_cache[col_name] = self.features[col_name].values
        return self._col_cache[col_name]

    def _apply_time_rule_vec(self, time_rule):
        mask = np.ones(len(self.features), dtype=bool)
        if 'min_abs' in time_rule:
            mask &= self._minutes >= time_rule['min_abs']
        if 'max_abs' in time_rule:
            mask &= self._minutes <= time_rule['max_abs']
        if 'min_pct' in time_rule:
            mask &= self._progress >= time_rule['min_pct']
        if 'max_pct' in time_rule:
            mask &= self._progress <= time_rule['max_pct']
        return mask

    def pool_size(self, strategy_name, time_rule, league_filter=None):
        """v16 OPT: cheap (total_rows, unique_matches) probe for the grid
        pre-filter. Reuses the cached extra_mask + time_mask and does a single
        boolean-AND + np.unique — no per-combo DataFrame copy and no re-running
        the extra_mask lambda (which the old main-process _build_pool did for
        every strategy x time_rule x league)."""
        extra_mask = self._extra_mask_cache.get(strategy_name)
        if extra_mask is None:
            return 0, 0
        tr_hash = self._hash_time_rule(time_rule)
        l2_key = (strategy_name, tr_hash)
        if l2_key in self._l2_time_cache:
            time_mask = self._l2_time_cache[l2_key]
        else:
            time_mask = self._apply_time_rule_vec(time_rule)
            self._l2_time_cache[l2_key] = time_mask
        m = extra_mask & time_mask
        if league_filter and league_filter != 'All':
            m = m & (self._leagues == league_filter)
        total = int(m.sum())
        if total == 0:
            return 0, 0
        uniq = int(np.unique(self._match_ids[m]).size)
        return total, uniq

    def build_pool(self, strategy_name, cfg, time_rule, league_filter=None,
                   prematch_threshold=None, prematch_spread_threshold=None,
                   diagnostics=None):
        # v74: 3-level hierarchical pool cache
        # diagnostics: optional dict to track which filter killed the pool
        tr_hash = self._hash_time_rule(time_rule)
        league_key = league_filter or 'All'
        l3_key = (strategy_name, tr_hash, league_key)
        total_rows = len(self.features)

        # v74.5 CRITICAL FIX: Always initialize diagnostic counters.
        # Path A (cache hit) skips the block that sets these — UnboundLocalError results.
        extra_count = 0
        time_count = 0
        league_count = 0

        if l3_key in self._l3_league_cache:
            pool_idx = self._l3_league_cache[l3_key]
            # v74.5: Cache hit — we do not have per-filter breakdown, so
            # approximate all pre-prematch counters as the cached pool size.
            extra_count = time_count = league_count = len(pool_idx)
        else:
            extra_mask = self._extra_mask_cache.get(strategy_name)
            extra_count = int(extra_mask.sum()) if extra_mask is not None else 0
            if extra_mask is None:
                if diagnostics is not None:
                    diagnostics.update({
                        'total': total_rows, 'extra_mask': 0, 'time_rule': 0,
                        'league': 0, 'prematch_odds': 0, 'prematch_spread': 0,
                        'killer': 'extra_mask', 'reason': f'extra_mask returned None for {strategy_name}'
                    })
                return {}
            l2_key = (strategy_name, tr_hash)
            if l2_key in self._l2_time_cache:
                time_mask = self._l2_time_cache[l2_key]
            else:
                time_mask = self._apply_time_rule_vec(time_rule)
                self._l2_time_cache[l2_key] = time_mask
            time_count = int((extra_mask & time_mask).sum())
            if league_filter and league_filter != 'All':
                league_mask = self._leagues == league_filter
            else:
                league_mask = np.ones(len(self.features), dtype=np.bool_)
            pool_mask = league_mask & time_mask & extra_mask
            league_count = int(pool_mask.sum())
            pool_idx = np.where(pool_mask)[0] if pool_mask.any() else np.array([], dtype=np.int64)
            self._l3_league_cache[l3_key] = pool_idx

        cached_count = len(pool_idx)

        # Apply prematch filters on indices (vary per threshold, not cached)
        pm_after = cached_count
        if prematch_threshold is not None and 'prematch_odds_col' in cfg and len(pool_idx) > 0:
            pm_col = cfg['prematch_odds_col']
            pm_comp = cfg.get('prematch_comparator', 'le')
            pm_vals = self._get_col(pm_col)[pool_idx]
            if pm_comp == 'le':
                pool_idx = pool_idx[pm_vals <= prematch_threshold]
            elif pm_comp == 'ge':
                pool_idx = pool_idx[pm_vals >= prematch_threshold]
            elif pm_comp == 'gt':
                pool_idx = pool_idx[pm_vals > prematch_threshold]
            elif pm_comp == 'lt':
                pool_idx = pool_idx[pm_vals < prematch_threshold]
            pm_after = len(pool_idx)

        ps_after = pm_after
        # v74.2 FIX: Spread threshold >= 900 is the pass-all sentinel — skip it.
        if prematch_spread_threshold is not None and prematch_spread_threshold < 900 and 'prematch_spread_col' in cfg and len(pool_idx) > 0:
            ps_col = cfg['prematch_spread_col']
            ps_comp = cfg.get('prematch_spread_comparator', 'ge')
            ps_vals = self._get_col(ps_col)[pool_idx]
            if ps_comp == 'ge':
                pool_idx = pool_idx[ps_vals >= prematch_spread_threshold]
            elif ps_comp == 'le':
                pool_idx = pool_idx[ps_vals <= prematch_spread_threshold]
            elif ps_comp == 'gt':
                pool_idx = pool_idx[ps_vals > prematch_spread_threshold]
            elif ps_comp == 'lt':
                pool_idx = pool_idx[ps_vals < prematch_spread_threshold]
            ps_after = len(pool_idx)

        # Determine which filter actually killed the pool
        if len(pool_idx) == 0:
            if diagnostics is not None:
                diag = {
                    'total': total_rows,
                    'extra_mask': extra_count,
                    'time_rule': time_count,
                    'league': league_count,
                    'prematch_odds': pm_after,
                    'prematch_spread': ps_after,
                }
                # Identify the actual killer
                if extra_count == 0:
                    diag['killer'] = 'extra_mask'
                    diag['reason'] = f'extra_mask killed all {total_rows} rows (strategy logic incompatible with data)'
                elif time_count == 0:
                    diag['killer'] = 'time_rule'
                    diag['reason'] = f'time_rule killed all {extra_count} rows passing extra_mask'
                elif cached_count == 0:
                    diag['killer'] = 'league'
                    diag['reason'] = f'league filter killed all {time_count} rows (no "{league_filter}" matches)'
                elif pm_after == 0:
                    diag['killer'] = 'prematch_odds'
                    pm_col = cfg.get('prematch_odds_col', 'N/A')
                    pm_comp = cfg.get('prematch_comparator', 'le')
                    diag['reason'] = f'prematch_odds ({pm_col} {pm_comp} {prematch_threshold}) killed all {cached_count} cached rows'
                elif ps_after == 0:
                    diag['killer'] = 'prematch_spread'
                    ps_col = cfg.get('prematch_spread_col', 'N/A')
                    ps_comp = cfg.get('prematch_spread_comparator', 'ge')
                    diag['reason'] = f'prematch_spread ({ps_col} {ps_comp} {prematch_spread_threshold}) killed all {pm_after} rows'
                else:
                    diag['killer'] = 'unknown'
                    diag['reason'] = 'pool became empty through unknown path'
                diagnostics.update(diag)
            return {}
        sub_idx = pool_idx
        sub_match_ids = self._match_ids[pool_idx]
        sub_ts = self._ts[pool_idx]
        sub_odds = self._get_col(cfg['odds_col'])[pool_idx]
        win_col = cfg['win_col']
        sub_win = self._get_col(win_col)[pool_idx] if win_col in self.features.columns else np.full(len(pool_idx), 'N/A')
        payout_col = cfg.get('payout_odds_col', cfg['odds_col'])
        sub_payout = self._get_col(payout_col)[pool_idx] if payout_col in self.features.columns else sub_odds
        draw_col = cfg.get('draw_odds_col', 'draw_odds')
        sub_draw = self._get_col(draw_col)[pool_idx] if draw_col in self.features.columns else np.full(len(pool_idx), np.nan)
        pools = {}
        n = len(sub_match_ids)
        if n == 0:
            return pools
        boundaries = np.concatenate([[0], np.where(sub_match_ids[1:] != sub_match_ids[:-1])[0] + 1, [n]])
        for i in range(len(boundaries) - 1):
            start = boundaries[i]
            end = boundaries[i+1]
            mid = sub_match_ids[start]
            chunk_len = end - start
            arr = np.empty(chunk_len, dtype=[
                ('idx', np.int64), ('ts', np.int64), ('odds', np.float32),
                ('win_val', object), ('payout_odds', np.float32), ('draw_odds', np.float32),
            ])
            arr['idx'] = sub_idx[start:end]
            arr['ts'] = sub_ts[start:end]
            arr['odds'] = sub_odds[start:end]
            arr['win_val'] = sub_win[start:end]
            arr['payout_odds'] = sub_payout[start:end]
            arr['draw_odds'] = sub_draw[start:end]
            pools[mid] = arr
        return pools

    def find_triggers(self, pool_dict, thresholds, comparator):
        if not pool_dict:
            return {float(t): np.array([], dtype=np.int64) for t in thresholds}
        thresholds_arr = np.array(thresholds, dtype=np.float32)
        K = len(thresholds_arr)
        N_matches = len(pool_dict)
        sort_order = np.argsort(thresholds_arr, kind='mergesort')
        sorted_t = thresholds_arr[sort_order]
        result = np.full((K, N_matches), -1, dtype=np.int64)
        for match_i, (mid, arr) in enumerate(sorted(pool_dict.items())):
            odds = arr['odds']
            idx = arr['idx']
            L = len(arr)
            if L == 0:
                continue
            if comparator == 'gt':
                k_ptr = 0
                for i in range(L):
                    while k_ptr < K and odds[i] > sorted_t[k_ptr]:
                        result[k_ptr, match_i] = idx[i]
                        k_ptr += 1
                    if k_ptr == K:
                        break
            elif comparator == 'ge':
                k_ptr = 0
                for i in range(L):
                    while k_ptr < K and odds[i] >= sorted_t[k_ptr]:
                        result[k_ptr, match_i] = idx[i]
                        k_ptr += 1
                    if k_ptr == K:
                        break
            elif comparator == 'le':
                k_ptr = K - 1
                for i in range(L):
                    while k_ptr >= 0 and odds[i] <= sorted_t[k_ptr]:
                        result[k_ptr, match_i] = idx[i]
                        k_ptr -= 1
                    if k_ptr < 0:
                        break
            elif comparator == 'lt':
                k_ptr = K - 1
                for i in range(L):
                    while k_ptr >= 0 and odds[i] < sorted_t[k_ptr]:
                        result[k_ptr, match_i] = idx[i]
                        k_ptr -= 1
                    if k_ptr < 0:
                        break
        inv_order = np.empty_like(sort_order)
        inv_order[sort_order] = np.arange(K)
        out = {}
        for orig_k, t in enumerate(thresholds):
            sk = inv_order[orig_k]
            triggers = result[sk]
            valid = triggers[triggers != -1]
            out[float(t)] = valid
        return out


def compute_metrics_vectorized(pool_dict, trigger_dict, thresholds, cfg, features_df):
    """Gate 2 validated: identical metrics to v60 per-threshold loop."""
    results = {}
    win_col = cfg['win_col']
    is_dual = cfg.get('is_dual_leg', False)
    payout_col_name = cfg.get('payout_odds_col', cfg['odds_col'])
    draw_col_name = cfg.get('draw_odds_col', 'draw_odds')
    win_vals = features_df[win_col].values if win_col in features_df.columns else np.full(len(features_df), 'N/A')
    final_result = features_df['final_result'].values if 'final_result' in features_df.columns else np.full(len(features_df), 'N/A')
    payout_odds = features_df[payout_col_name].values if payout_col_name in features_df.columns else np.zeros(len(features_df))
    draw_odds = features_df[draw_col_name].values if draw_col_name in features_df.columns else np.full(len(features_df), np.nan)
    for thresh in thresholds:
        trigger_idx = trigger_dict.get(float(thresh), np.array([], dtype=np.int64))
        n = len(trigger_idx)
        if n == 0:
            results[float(thresh)] = None
            continue
        trigger_won = np.zeros(n, dtype=bool)
        trigger_profit = np.zeros(n, dtype=np.float64)
        trigger_odds = np.zeros(n, dtype=np.float64)
        if is_dual:
            # V11 OPT: vectorized trigger processing (numpy array indexing)
            won = (win_vals[trigger_idx] == final_result[trigger_idx])
            leg_l_profit = np.where(won, payout_odds[trigger_idx] - 1, -1)
            leg_d_won = (final_result[trigger_idx] == 'Draw')
            leg_d_profit = np.where(leg_d_won, draw_odds[trigger_idx] - 1, -1)
            trigger_won = won
            trigger_profit = (leg_l_profit + leg_d_profit) / 2
            trigger_odds = payout_odds[trigger_idx]
        else:
            # V11 OPT: vectorized trigger processing (numpy array indexing)
            win_value = cfg.get('win_value')
            if win_value is not None:
                won = (final_result[trigger_idx] == win_value)
            else:
                won = (win_vals[trigger_idx] == final_result[trigger_idx])
            trigger_won = won
            trigger_profit = np.where(won, payout_odds[trigger_idx] - 1, -1)
            trigger_odds = payout_odds[trigger_idx]
        wins = int(trigger_won.sum())
        losses = n - wins
        win_rate = (wins / n * 100) if n > 0 else 0.0
        total_profit = float(trigger_profit.sum())
        profit_per_bet = total_profit / n if n > 0 else 0.0
        avg_odds = float(trigger_odds.mean()) if n > 0 else 0.0
        roi = profit_per_bet * 100
        cum = np.cumsum(trigger_profit)
        running_max = np.maximum.accumulate(cum)
        drawdowns = running_max - cum
        max_dd = float(np.max(drawdowns)) if len(drawdowns) > 0 else 0.0
        # V11 OPT: vectorized loss streak using np.diff (no Python loop)
        if len(trigger_won) == 0:
            max_consec_loss = 0
        else:
            padded = np.concatenate([[True], trigger_won, [True]])
            diff = np.diff(padded.astype(np.int8))
            starts = np.where(diff == -1)[0]
            ends = np.where(diff == 1)[0]
            if len(starts) > 0:
                streaks = ends - starts
                max_consec_loss = int(streaks.max())
            else:
                max_consec_loss = 0
        sharpe_dd = (total_profit / max_dd) if max_dd > 0 else (total_profit if total_profit > 0 else 0.0)
        std_profit = float(np.std(trigger_profit, ddof=1)) if len(trigger_profit) > 1 else 0.0
        sharpe_trad = (profit_per_bet / std_profit) if std_profit > 0 else 0.0
        if n < 2 or std_profit == 0 or std_profit != std_profit:
            p_value = 1.0
        else:
            t_stat = profit_per_bet / (std_profit / math.sqrt(n))
            p = 2 * (1 - 0.5 * (1 + math.erf(abs(t_stat) / math.sqrt(2))))
            p_value = max(min(p, 1.0), 0.0)
        implied_prob = float((1 / trigger_odds).mean()) if n > 0 else 0.0
        actual_prob = win_rate / 100.0
        results[float(thresh)] = {
            'n_bets': n, 'wins': wins, 'losses': losses, 'win_rate': win_rate,
            'total_profit': total_profit, 'profit_per_bet': profit_per_bet,
            'avg_odds': avg_odds, 'roi': roi, 'max_drawdown': max_dd,
            'max_consecutive_losses': max_consec_loss,
            'sharpe_profit_per_dd': sharpe_dd, 'sharpe_traditional': sharpe_trad,
            'p_value_ttest': p_value, 'implied_probability': implied_prob,
            'actual_probability': actual_prob,
        }
    return results



def _evaluate_variant_numba_multi(features_arrs, pool_dict, cfg, thresholds, comparator_str):
    """v16 OPT: evaluate ALL odds thresholds for a pool in a SINGLE numba
    trigger pass. Returns {float(threshold): metrics_dict | None}.

    Numerically identical to calling _evaluate_variant_numba once per threshold,
    but the per-pool concatenation of match indices and the pd.factorize of
    match ids happen ONCE instead of K times (K = number of thresholds).
    _find_triggers_numba already supports K thresholds in one scan, so this just
    stops throwing that capability away."""
    out = {float(t): None for t in thresholds}
    if not pool_dict or len(thresholds) == 0:
        return out
    all_idx = np.concatenate([pool_dict[k]['idx'] for k in sorted(pool_dict.keys())]).astype(np.int64)
    if len(all_idx) == 0:
        return out

    odds = features_arrs[cfg['odds_col']][all_idx].astype(np.float64)
    thresholds_arr = np.array([float(t) for t in thresholds], dtype=np.float64)
    match_ids_all = features_arrs['match_id'][all_idx]
    match_ints = pd.factorize(match_ids_all, sort=True)[0].astype(np.int64)

    comp_map = {'gt': 0, 'ge': 1, 'le': 2, 'lt': 3}
    comp_int = comp_map.get(comparator_str, 1)

    # One numba scan resolves every threshold (rows == thresholds, in input order)
    triggers_2d = _find_triggers_numba(odds, thresholds_arr, comp_int, match_ints)

    payout_col = cfg.get('payout_odds_col', cfg['odds_col'])
    win_col_name = cfg['win_col']
    win_value = cfg.get('win_value')
    is_dual = cfg.get('is_dual_leg', False)

    for k, t in enumerate(thresholds):
        trigger_flat = triggers_2d[k]
        valid_triggers = trigger_flat[trigger_flat >= 0]
        if len(valid_triggers) == 0:
            out[float(t)] = None
            continue
        trig_idx = all_idx[valid_triggers]
        payout_odds = features_arrs[payout_col][trig_idx].astype(np.float64)
        avg_odds = float(payout_odds.mean()) if len(payout_odds) > 0 else 0.0

        final_result = features_arrs['final_result'][trig_idx]
        final_enc, final_mapping = _encode_str_array(final_result)

        win_value_int = -1
        win_enc = None
        if win_value is not None:
            win_value_int = final_mapping.get(win_value, -1)
        else:
            win_vals = features_arrs[win_col_name][trig_idx]
            win_enc, _ = _encode_str_array(win_vals)

        draw_odds = features_arrs['draw_odds'][trig_idx].astype(np.float64) if is_dual else np.zeros(len(trig_idx), dtype=np.float64)
        draw_enc_int = final_mapping.get('Draw', -1)

        profits, won = _compute_profits_numba(payout_odds,
            win_enc if win_enc is not None else final_enc,
            final_enc, 1 if is_dual else 0, draw_odds, win_value_int, draw_enc_int)

        (total_profit, profit_per_bet, win_rate, max_dd, max_cl,
         sharpe_dd, std, p_value, wins_float, n_float,
         implied_prob, actual_prob, roi, odds_efficiency) = _calc_metrics_numba(profits, won, avg_odds)

        n = int(n_float)
        wins = int(wins_float)
        if n == 0:
            out[float(t)] = None
            continue

        out[float(t)] = {
            'n_bets': n, 'wins': wins, 'losses': n - wins,
            'win_rate': win_rate, 'total_profit': total_profit,
            'profit_per_bet': profit_per_bet, 'avg_odds': avg_odds,
            'roi': roi, 'max_drawdown': max_dd,
            'max_consecutive_losses': max_cl,
            'sharpe_profit_per_dd': sharpe_dd,
            'sharpe_traditional': profit_per_bet / std if std > 0 else 0.0,
            'p_value_ttest': p_value,
            'implied_probability': implied_prob,
            'actual_probability': actual_prob,
            'odds_efficiency': odds_efficiency,
        }
    return out


# ═══════════════════════════════════════════════════════════════════════════════
# v16 OPT: Per-PROCESS worker state + initializer.
# The heavy setup (read features parquet, extract numpy arrays, build the
# VectorizedPool and its strategy masks) now happens ONCE per worker process via
# the ProcessPoolExecutor `initializer`, instead of once per chunk (~4x/process).
# ═══════════════════════════════════════════════════════════════════════════════
_WORKER_STATE = {}


def _init_worker_v74(features_payload, use_shm, grid_path):
    """Runs once per worker process. Populates the module-global _WORKER_STATE."""
    import pandas as pd
    # Shared-memory path removed (see _run_grid_core) — always parquet/pickle here.
    if isinstance(features_payload, str) and features_payload.endswith('.parquet'):
        features = _laz_decat(pd.read_parquet(features_payload))
    else:
        features = pd.read_pickle(features_payload)

    # Rebuild worker grid (honours Phase-1/2 threshold overrides passed from main)
    if grid_path is not None:
        import pickle
        with open(grid_path, 'rb') as f:
            loaded_grid = pickle.load(f)
        worker_grid = {}
        for sname, scfg in loaded_grid.items():
            base_cfg = STRATEGY_GRID.get(sname, {}).copy()
            for k, v in scfg.items():
                if v is not None:  # None marker means "keep the STRATEGY_GRID lambda"
                    base_cfg[k] = v
            worker_grid[sname] = base_cfg
    else:
        worker_grid = STRATEGY_GRID

    features_arrs = {col: features[col].values for col in features.columns}
    # Only precompute masks for the strategies this run actually evaluates.
    vpool = VectorizedPool(features, prebuilt_arrs=features_arrs,
                           strategy_names=list(worker_grid.keys()))
    if not _NUMBA_AVAILABLE:
        features_arrs = None

    _WORKER_STATE['features'] = features
    _WORKER_STATE['features_arrs'] = features_arrs
    _WORKER_STATE['vpool'] = vpool
    _WORKER_STATE['worker_grid'] = worker_grid


def _worker_evaluate_chunk_v74(chunk):
    """v16: lightweight per-chunk worker. All heavy setup (features load, numpy
    array extraction, VectorizedPool + strategy masks, worker grid) is done ONCE
    per process in _init_worker_v74 and read from _WORKER_STATE here."""
    import hashlib
    st = _WORKER_STATE
    features      = st['features']
    features_arrs = st['features_arrs']
    vpool         = st['vpool']
    worker_grid   = st['worker_grid']
    results = []

    for task in chunk:
        sname = task['strategy']
        cfg = worker_grid.get(sname, STRATEGY_GRID.get(sname))
        tr = task['time_rule']
        league = task['league']
        pm = task['pm']
        ps = task['ps']
        effective_min = task['effective_min']
        diag = {}
        pool_dict = vpool.build_pool(sname, cfg, tr, league, prematch_threshold=pm, prematch_spread_threshold=ps, diagnostics=diag)
        if not pool_dict:
            # v74.1: Use ACTUAL diagnostics from build_pool to report correct killer
            reason = diag.get('reason', f'Pool empty (unknown reason)')
            killer = diag.get('killer', 'unknown')
            print(f"[SKIP] {sname} | {league or 'All'} | PM={pm} PS={ps} | REASON: {reason} [killer={killer}]")
            continue

        thresholds = cfg['thresholds']
        # v16: resolve EVERY threshold for this pool in a single pass.
        if _NUMBA_AVAILABLE and features_arrs is not None:
            metrics_by_t = _evaluate_variant_numba_multi(features_arrs, pool_dict, cfg, thresholds, cfg['comparator'])
        else:
            trigger_dict = vpool.find_triggers(pool_dict, thresholds, cfg['comparator'])
            metrics_by_t = compute_metrics_vectorized(pool_dict, trigger_dict, thresholds, cfg, features)

        for thresh in thresholds:
            m = metrics_by_t.get(float(thresh))
            if m is None:
                print(f"[SKIP] {sname} | {league or 'All'} | PM={pm} PS={ps} | threshold={thresh} | REASON: No triggers found in pool of {len(pool_dict)} rows")
                continue
            if m['n_bets'] < effective_min:
                print(f"[SKIP] {sname} | {league or 'All'} | PM={pm} PS={ps} | threshold={thresh} | REASON: Too few bets ({m['n_bets']} < {effective_min})")
                continue

            params = {
                'odds_threshold': thresh, 'time_rule': tr,
                'prematch_threshold': pm if pm is not None else 'N/A',
                'prematch_spread_threshold': ps if ps is not None else 'N/A',
            }
            variant_id = hashlib.blake2b(f"{sname}|{params}|{league or 'All'}".encode(), digest_size=6).hexdigest()
            total_eligible = len(pool_dict)
            total_triggered = m['n_bets']
            trigger_rate = (total_triggered / total_eligible * 100) if total_eligible > 0 else 0.0

            res = {
                'strategy': sname, 'league': league or 'All',
                'odds_threshold': thresh, 'time_rule': str(tr), 'time_rule_raw': tr,
                'prematch_threshold': pm if pm is not None else 'N/A',
                'prematch_spread_threshold': ps if ps is not None else 'N/A',
                'variant_id': variant_id,
                'n_bets': m['n_bets'], 'wins': m['wins'], 'losses': m['losses'],
                'win_rate': m['win_rate'], 'total_profit': m['total_profit'],
                'profit_per_bet': m['profit_per_bet'], 'avg_odds': m['avg_odds'],
                'roi': m['roi'], 'max_drawdown': m['max_drawdown'],
                'max_consecutive_losses': m['max_consecutive_losses'],
                'sharpe_profit_per_dd': m['sharpe_profit_per_dd'],
                'sharpe_traditional': m['sharpe_traditional'],
                'p_value_ttest': m['p_value_ttest'],
                'implied_probability': m['implied_probability'],
                'actual_probability': m['actual_probability'],
                'odds_efficiency': 0.0, 'is_rejected': False,
                'total_eligible': total_eligible,
                'total_triggered': total_triggered,
                'trigger_rate': round(trigger_rate, 2),
            }
            print(f"[PASS] {sname} | {league or 'All'} | Bets={m['n_bets']} | Profit={m['total_profit']:.1f} | WR={m['win_rate']:.1f}%")
            results.append(res)
    return results


class CombinatorialBacktestEngine:
    def __init__(self, features_df, grid=None):
        self.features = features_df.copy()
        if grid is not None:
            self.grid = grid
        elif GRID_MODE == 'minimal':
            self.grid = STRATEGY_GRID_MINIMAL
            print("[GRID] Using MINIMAL core masks — discovery engine will find optimal filters")
        else:
            self.grid = STRATEGY_GRID
            print("[GRID] Using CURRENT hardcoded masks")
        self.results = []

        # PRECOMPUTE: Match timelines for fast opportunity window calc
        feat = self.features[['match_id', 'timestamp']].copy()
        feat['timestamp'] = pd.to_datetime(feat['timestamp'], format='mixed')
        feat = feat.drop_duplicates(subset=['match_id', 'timestamp'])
        feat = feat.sort_values(['match_id', 'timestamp'])

        self._match_timelines = {}
        self._match_last_ts = {}
        for mid, group in feat.groupby('match_id'):
            ts_arr = group['timestamp'].astype(np.int64).values
            self._match_timelines[mid] = ts_arr
            self._match_last_ts[mid] = ts_arr[-1]

    def _expand_time_rules(self, time_rules):
        if isinstance(time_rules, list):
            return time_rules
        if isinstance(time_rules, dict):
            if not time_rules:
                return [{}]
            keys = list(time_rules.keys())
            values = [time_rules[k] for k in keys]
            return [dict(zip(keys, combo)) for combo in product(*values)]
        return [{}]

    def _apply_time_rule(self, f, rule):
        mask = pd.Series(True, index=f.index)
        if 'min_abs' in rule:
            mask &= f['minute'] >= rule['min_abs']
        if 'max_abs' in rule:
            mask &= f['minute'] <= rule['max_abs']
        if 'min_pct' in rule:
            mask &= f['league_time_progress'] >= rule['min_pct']
        if 'max_pct' in rule:
            mask &= f['league_time_progress'] <= rule['max_pct']
        return mask

    def _build_pool(self, strategy_name, time_rule, league_filter, cfg=None):
        f = self.features
        total = len(f)
        # Track which filter actually kills the pool
        after_league = total
        if league_filter and league_filter != 'All':
            f = f[f['league'] == league_filter]
            after_league = len(f)
        cfg = cfg or self.grid[strategy_name]
        time_mask = self._apply_time_rule(f, time_rule)
        after_time = int(time_mask.sum())
        extra_mask = cfg['extra_mask'](f)
        after_extra = int((time_mask & extra_mask).sum())
        pool_mask = time_mask & extra_mask
        pool = f[pool_mask]
        if len(pool) == 0:
            # v74.1: Identify the ACTUAL killer, not generic blame
            if after_league == 0:
                reason = f'league filter killed all {total} rows (no "{league_filter}" matches)'
                killer = 'league'
            elif after_time == 0:
                reason = f'time_rule killed all {after_league} rows passing league filter'
                killer = 'time_rule'
            elif after_extra == 0:
                reason = f'extra_mask killed all {after_time} rows passing time_rule (strategy logic incompatible with data)'
                killer = 'extra_mask'
            else:
                reason = f'combined filters killed all {total} rows'
                killer = 'combined'
            print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM=N/A PS=N/A | REASON: {reason} [killer={killer}]")
            return None
        return pool

    def _get_active_conditions(self, strategy_name):
        """Return list of active condition names for a strategy (for metadata)."""
        compatible = STRATEGY_COMPATIBLE_CONDITIONS.get(strategy_name, [])
        desc = EXTRA_MASK_DESC.get(strategy_name, '')
        return compatible, desc

    def _get_day_metrics(self, bets_df):
        """Return day-of-week profit/bets breakdown."""
        if len(bets_df) == 0:
            return {}
        df = bets_df.copy()
        df['dow'] = pd.to_datetime(df['timestamp'], errors='coerce').dt.dayofweek
        day_names = {0: 'Mon', 1: 'Tue', 2: 'Wed', 3: 'Thu', 4: 'Fri', 5: 'Sat', 6: 'Sun'}
        df['day_name'] = df['dow'].map(day_names)
        daily_profit = df.groupby('day_name')['profit'].sum().to_dict()
        daily_bets = df.groupby('day_name').size().to_dict()
        return {d: {'profit': round(daily_profit.get(d, 0.0), 2), 'bets': daily_bets.get(d, 0)}
                for d in ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']}

    def _daily_metrics(self, trigger_df):
        if len(trigger_df) == 0:
            return {'avg_n_bets_daily': 0.0, 'avg_profit_daily': 0.0, 'avg_dd_daily': 0.0, 'n_days': 0,
                    'daily_win_rate': 0.0, 'std_daily_win_rate': 0.0}
        df = trigger_df.copy()
        df['date'] = pd.to_datetime(df['timestamp'], errors='coerce').dt.date
        daily_bets = df.groupby('date').size()
        daily_profit = df.groupby('date')['profit'].sum()
        avg_n_bets = daily_bets.mean()
        avg_profit = daily_profit.mean()
        n_days = df['date'].nunique()
        daily_dd_list = []
        for _, group in df.groupby('date'):
            cumsum = group['profit'].cumsum()
            peak = cumsum.cummax()
            dd = (peak - cumsum).max()
            daily_dd_list.append(dd)
        avg_dd = np.mean(daily_dd_list) if daily_dd_list else 0.0
        daily_wins = df.groupby('date')['won'].sum()
        daily_bets_count = df.groupby('date').size()
        daily_win_rate = (daily_wins / daily_bets_count * 100).replace([np.inf, -np.inf], np.nan).dropna()
        avg_daily_win_rate = daily_win_rate.mean() if len(daily_win_rate) > 0 else 0.0
        std_daily_win_rate = daily_win_rate.std(ddof=1) if len(daily_win_rate) > 1 else 0.0

        return {
            'avg_n_bets_daily': round(avg_n_bets, 2),
            'avg_profit_daily': round(avg_profit, 2),
            'avg_dd_daily': round(avg_dd, 2),
            'n_days': n_days,
            'daily_win_rate': round(avg_daily_win_rate, 2),
            'std_daily_win_rate': round(std_daily_win_rate, 2),
        }

    def _calc_opportunity_windows(self, candidates):
        if len(candidates) == 0:
            return {'min_opp_window': 0.0, 'avg_opp_window': 0.0, 'max_opp_window': 0.0}

        # V11.4 FIX: Explicit sort by match_id + timestamp ASC before ANY time
        # calculation. Ensures trigger ordering and timeline alignment are correct.
        candidates = candidates.sort_values(['match_id', 'timestamp']).reset_index(drop=True)

        trig = candidates.groupby('match_id')['timestamp'].min().reset_index()
        trig.columns = ['match_id', 'trigger_ts']
        trig['trigger_int'] = pd.to_datetime(trig['trigger_ts'], format='mixed').astype(np.int64)

        cand_ts = candidates[['match_id', 'timestamp']].copy()
        cand_ts['ts_int'] = pd.to_datetime(cand_ts['timestamp'], format='mixed').astype(np.int64)
        cand_mids = cand_ts['match_id'].values
        cand_vals = cand_ts['ts_int'].values

        cand_lookup = {}
        for i in range(len(cand_mids)):
            mid = cand_mids[i]
            if mid not in cand_lookup:
                cand_lookup[mid] = set()
            cand_lookup[mid].add(cand_vals[i])

        windows = []
        trig_mids = trig['match_id'].values
        trig_ints = trig['trigger_int'].values

        for i in range(len(trig_mids)):
            mid = trig_mids[i]
            trigger_int = trig_ints[i]
            timeline = self._match_timelines.get(mid)
            if timeline is None or len(timeline) == 0:
                continue
            idx = np.searchsorted(timeline, trigger_int)
            if idx >= len(timeline):
                idx = len(timeline) - 1
            if timeline[idx] < trigger_int:
                idx += 1
            # v74.6 FIX: idx can equal len(timeline) after increment — guard before assert.
            if idx >= len(timeline):
                idx = len(timeline) - 1
            assert 0 <= idx < len(timeline), f"Trigger index out of bounds for match {mid}"
            cand_set = cand_lookup.get(mid, set())
            found = False
            for j in range(idx, len(timeline)):
                if timeline[j] not in cand_set:
                    expiry_int = timeline[j]
                    found = True
                    break
            if found:
                window = (expiry_int - trigger_int) / 1e9
            else:
                window = (self._match_last_ts[mid] - trigger_int) / 1e9
            # V11.4 FIX: Clamp tiny negative windows to 0. Timestamp ordering
            # jitter within a match can produce small negatives — clamp silently.
            windows.append(max(window, 0.0))

        if not windows:
            return {'min_opp_window': 0.0, 'avg_opp_window': 0.0, 'max_opp_window': 0.0}

        n = len(windows)
        if n >= 5:
            bottom_n = max(1, int(n * 0.2))
            top_n = max(1, int(n * 0.2))
            sorted_w = np.sort(np.array(windows))
            min_opp_window = sorted_w[:bottom_n].mean()
            max_opp_window = sorted_w[-top_n:].mean()
        else:
            min_opp_window = min(windows)
            max_opp_window = max(windows)

        return {
            'min_opp_window': round(float(min_opp_window), 1),
            'avg_opp_window': round(float(np.mean(windows)), 1),
            'max_opp_window': round(float(max_opp_window), 1),
        }

    def _evaluate_discovery_trial(self, strategy_name, cfg, threshold, time_rule, league_filter, features_subset, min_bets=100):
        saved_features = self.features
        self.features = features_subset
        try:
            pool = self._build_pool(strategy_name, time_rule, league_filter, cfg=cfg)
            if pool is None or len(pool) == 0:
                return None
            res = self._evaluate_variant_fast(strategy_name, cfg, threshold, time_rule, league_filter, pool)
            # Reject non-causal stacks IN THE LOOP, before they can be scored.
            if not laz_discovery_causal_ok(getattr(cfg, 'conditions', None)
                                           or (cfg.get('conditions') if isinstance(cfg, dict)
                                               else None)):
                return None
            if res and res['n_bets'] >= min_bets:
                return res
            return None
        finally:
            self.features = saved_features

    def _build_combined_mask(self, base_mask, condition_names, features_df):
        """Build a combined mask from base + list of condition names."""
        mask = base_mask(features_df)
        for cn in condition_names:
            if cn in CONDITION_POOL:
                mask &= CONDITION_POOL[cn](features_df)
        return mask

    def _discovery_score(self, res):
        """Score a discovery result for tiered selection."""
        if res is None or res.get('n_bets', 0) < 50:
            return -9999.0
        sharpe = res.get('sharpe_profit_per_dd', 0)
        profit = res.get('total_profit', 0)
        pval = res.get('p_value_ttest', 1)
        if pval >= 0.05:
            return -9999.0
        return sharpe + (profit / 1000.0)

    def discover_best_conditions(self, base_variant, features_is=None, features_oos=None,
                                 min_bets=100, max_depth=None, oos_margin=0.0, beam=None,
                                 permute_order=None):
        # None means "use the module setting", which --beam / --max-depth / --no-permute
        # write. An explicit argument still wins, so callers can override per invocation.
        max_depth = LAZ_SEARCH_MAX_DEPTH if max_depth is None else max_depth
        beam = LAZ_SEARCH_BEAM if beam is None else beam
        permute_order = LAZ_SEARCH_PERMUTE if permute_order is None else permute_order
        """OOS-gated stepwise discovery. v73_7 raises the ceiling and widens the search.

        max_depth 3 -> 5: the loop is already OOS-gated and stops the moment a condition
        stops earning held-out value, so a higher ceiling costs search time rather than
        overfitting -- depth is chosen by the data, not by the constant.

        beam: how many branches survive each depth. The original kept ONE -- the
        best-scoring candidate -- so a stack whose first move is second-best but whose
        SECOND move is far stronger could never be reached. Keeping the top `beam` lets
        finished stacks compete instead of first steps.

        permute_order: a finished AND-stack gives identical bets in any order, but the
        greedy PATH depends on order completely, because each step is chosen against what
        is already there. A + B can stall at depth 2 while B + A runs to depth 4.
        """
        strategy_name = base_variant['strategy']
        threshold = base_variant['odds_threshold']
        time_rule = base_variant.get('time_rule_raw')
        if time_rule is None:
            time_rule = ast.literal_eval(base_variant['time_rule'])
        league_filter = base_variant['league'] if base_variant['league'] != 'All' else None

        base_cfg = {
            'odds_col': self.grid[strategy_name]['odds_col'],
            'comparator': self.grid[strategy_name]['comparator'],
            'thresholds': [threshold],
            'win_col': self.grid[strategy_name]['win_col'],
            'extra_mask': self.grid[strategy_name]['extra_mask'],
        }
        for opt_key in ['win_value', 'is_dual_leg', 'draw_odds_col', 'draw_threshold', 'payout_odds_col']:
            opt_val = self.grid[strategy_name].get(opt_key)
            if opt_val is not None:
                base_cfg[opt_key] = opt_val

        pool = self._build_pool(strategy_name, time_rule, league_filter, cfg=base_cfg)
        if pool is None:
            return None
        base_res = self._evaluate_variant_fast(strategy_name, base_cfg, threshold, time_rule, league_filter, pool)
        if base_res is None or base_res['n_bets'] < min_bets:
            return None

        fg_profit = base_variant.get('total_profit', 0)
        fg_bets = base_variant.get('n_bets', 0)
        profit_diff = abs(base_res['total_profit'] - fg_profit)
        bets_diff = abs(base_res['n_bets'] - fg_bets)

        if profit_diff > 1.0 or bets_diff > 5:
            print("[WARN] " + strategy_name + " | Base evaluation diverges from fixed grid!")
            print("       Fixed: Profit=" + str(round(fg_profit, 1)) + " Bets=" + str(fg_bets) + " | Base: Profit=" + str(round(base_res['total_profit'], 1)) + " Bets=" + str(base_res['n_bets']))
            return None

        best_cfg = base_cfg
        best_res = base_res
        available = STRATEGY_COMPATIBLE_CONDITIONS.get(strategy_name, []).copy()
        added_conditions = []

        # ═══════════════════════════════════════════════════════════════════════
        # v20.1 GREEDY OPTIMIZATION — gate the DECISION on held-out (OOS) data.
        # Original behaviour selected each condition by IN-SAMPLE score and only
        # checked OOS once, on the finished stack — so it could overfit a 3-deep
        # stack and then discard it whole. Now: a condition is stacked only if it
        # (a) improves in-sample AND (b) improves OUT-OF-SAMPLE, and candidates are
        # RANKED BY OOS score, not IS. This selects for durability rather than
        # sample-fit, and AUTO-REGULARIZES depth: the loop stops the moment no
        # condition helps OOS, so it won't over-stack. Falls back to the original
        # IS-only greedy when no OOS features are supplied (backward compatible).
        # ═══════════════════════════════════════════════════════════════════════
        _gated = (features_is is not None) and (features_oos is not None)

        def _score(r):
            return (r['sharpe_profit_per_dd'] + r['total_profit'] / 1000.0) if r else -1e18

        best_oos_res = None
        if _gated:
            best_oos_res = self._evaluate_variant_on_features(
                strategy_name, best_cfg, threshold, time_rule, league_filter,
                features_oos, min_bets=min_bets)

        # ═══════════════════════════════════════════════════════════════════════
        # v22 ULTIMA FINDER — stepwise: forward-add + backward-prune + OOS-gated swap.
        # Stacks a signal only while it adds held-out value, prunes any element that
        # stops earning its place, and swaps in a stronger element for a weaker one —
        # every move gated on OOS improvement by SWAP_MARGIN (so it converges instead
        # of thrashing on noise), capped by MAX_SWAPS. This is the market+timing+
        # trajectory combiner: it stops at the element where accuracy stops improving.
        # ═══════════════════════════════════════════════════════════════════════
        _stepwise_done = False
        if _gated and DISCOVERY_MODE == 'stepwise':
            pool_conds = [c for c in available if c in CONDITION_POOL]

            def _build_cfg(cond_names):
                mask = base_cfg['extra_mask']
                for cn in cond_names:
                    cm = CONDITION_POOL[cn]
                    mask = (lambda f, p=mask, c=cm: p(f).fillna(False) & c(f).fillna(False))
                cfg = base_cfg.copy(); cfg['extra_mask'] = mask
                return cfg

            def _oos(cond_names):
                r = self._evaluate_variant_on_features(strategy_name, _build_cfg(cond_names),
                                                       threshold, time_rule, league_filter, features_oos, min_bets=min_bets)
                return _score(r), r

            def _is(cond_names):
                r = self._evaluate_variant_on_features(strategy_name, _build_cfg(cond_names),
                                                       threshold, time_rule, league_filter, features_is, min_bets=min_bets)
                return _score(r), r

            current = []
            cur_oos, cur_oos_r = _oos(current)
            cur_is, _ = _is(current)
            swaps = 0
            for _it in range(STEPWISE_MAX_ITER):
                changed = False
                # 1) FORWARD — best OOS-improving (by margin) addition that also helps IS
                best = None
                for cn in pool_conds:
                    if cn in current:
                        continue
                    is_s, _ir = _is(current + [cn])
                    if _ir is None or is_s <= cur_is:
                        continue
                    oos_s, oos_r = _oos(current + [cn])
                    if oos_r is not None and oos_s > cur_oos + SWAP_MARGIN and (best is None or oos_s > best[1]):
                        best = (cn, oos_s, oos_r)
                if best is not None:
                    current.append(best[0]); cur_oos, cur_oos_r = best[1], best[2]; cur_is, _ = _is(current); changed = True
                    print(f"[STEPWISE] +{best[0]} | OOS_Sharpe {cur_oos_r['sharpe_profit_per_dd']:.2f} | bets {cur_oos_r['n_bets']}")
                # 2) BACKWARD — drop any element whose removal does NOT reduce OOS (dead weight / now redundant)
                for cn in list(current):
                    oos_s, oos_r = _oos([c for c in current if c != cn])
                    if oos_r is not None and oos_s >= cur_oos - 1e-9:
                        current = [c for c in current if c != cn]; cur_oos, cur_oos_r = oos_s, oos_r; cur_is, _ = _is(current); changed = True
                        print(f"[STEPWISE] -{cn} (redundant, OOS held) | OOS_Sharpe {cur_oos_r['sharpe_profit_per_dd']:.2f}")
                # 3) SWAP — replace a weaker element with a stronger available one (OOS by margin, capped)
                if swaps < MAX_SWAPS:
                    swapped = False
                    for a in list(current):
                        for b in pool_conds:
                            if b in current:
                                continue
                            trial = [c for c in current if c != a] + [b]
                            is_s, _ir = _is(trial)
                            if _ir is None or is_s <= cur_is:
                                continue
                            oos_s, oos_r = _oos(trial)
                            if oos_r is not None and oos_s > cur_oos + SWAP_MARGIN:
                                current, cur_oos, cur_oos_r, cur_is = trial, oos_s, oos_r, is_s
                                swaps += 1; changed = swapped = True
                                print(f"[STEPWISE] swap {a}->{b} (stronger OOS) | OOS_Sharpe {cur_oos_r['sharpe_profit_per_dd']:.2f}")
                                break
                        if swapped:
                            break
                if not changed or len(current) >= max_depth + 2:
                    break
            added_conditions = current
            if added_conditions:
                best_cfg = _build_cfg(current)
                best_res = self._evaluate_variant_on_features(strategy_name, best_cfg, threshold, time_rule, league_filter, features_is, min_bets=min_bets)
                best_oos_res = cur_oos_r
            _stepwise_done = True

        for depth in (range(0) if _stepwise_done else range(max_depth)):
            improvements = []
            if not _gated:
                # ── original IS-only greedy (unchanged path) ──
                _base_pool_depth = self._build_pool(strategy_name, time_rule, league_filter, cfg=best_cfg)
                base_pool_size = len(_base_pool_depth) if _base_pool_depth is not None else 0
                for cond_name in available:
                    if cond_name not in CONDITION_POOL:
                        print(f"[WARN] Discovery: '{cond_name}' not in CONDITION_POOL — skipping")
                        continue
                    cond_mask = CONDITION_POOL[cond_name]
                    trial_cfg = best_cfg.copy()
                    old_mask = best_cfg['extra_mask']
                    trial_cfg['extra_mask'] = lambda f, b=old_mask, c=cond_mask: b(f).fillna(False) & c(f).fillna(False)
                    pool = self._build_pool(strategy_name, time_rule, league_filter, cfg=trial_cfg)
                    if pool is None or len(pool) == base_pool_size:
                        continue
                    res = self._evaluate_variant_fast(strategy_name, trial_cfg, threshold, time_rule, league_filter, pool)
                    if res is None or res['n_bets'] < min_bets:
                        continue
                    if _score(res) > _score(best_res):
                        improvements.append((cond_name, _score(res), res, None, trial_cfg))
                if not improvements:
                    break
                cond_name, _, best_res, _, best_cfg = max(improvements, key=lambda x: x[1])
            else:
                # ── v20.1 OOS-gated greedy: choose the condition that best survives held-out data ──
                base_is_score = _score(best_res)
                base_oos_score = _score(best_oos_res)
                for cond_name in available:
                    if cond_name not in CONDITION_POOL:
                        print(f"[WARN] Discovery: '{cond_name}' not in CONDITION_POOL — skipping")
                        continue
                    cond_mask = CONDITION_POOL[cond_name]
                    trial_cfg = best_cfg.copy()
                    old_mask = best_cfg['extra_mask']
                    trial_cfg['extra_mask'] = lambda f, b=old_mask, c=cond_mask: b(f).fillna(False) & c(f).fillna(False)
                    is_res = self._evaluate_variant_on_features(
                        strategy_name, trial_cfg, threshold, time_rule, league_filter, features_is, min_bets=min_bets)
                    if is_res is None or _score(is_res) <= base_is_score:
                        continue                                  # (a) must improve in-sample
                    oos_res = self._evaluate_variant_on_features(
                        strategy_name, trial_cfg, threshold, time_rule, league_filter, features_oos, min_bets=min_bets)
                    if oos_res is None or _score(oos_res) <= base_oos_score + oos_margin:
                        continue                                  # (b) must ALSO improve out-of-sample (>=min_bets both)
                    # ── IN-LOOP CAUSALITY ─────────────────────────────────────────────
                    # Reject the COMBINATION before it can be scored. This is where
                    # BBT03/04/06 were born: `q <= 1` stacked with `q1_margin`, which is
                    # Q1's FINAL margin broadcast backwards onto every tick. The backtest
                    # read an outcome that had not happened, and the after-the-fact gate
                    # caught it only once they were registered and reported.
                    _stack_now = list(added_conditions) + [cond_name]
                    if not laz_discovery_causal_ok(_stack_now):
                        continue
                    improvements.append((cond_name, _score(oos_res), is_res, oos_res, trial_cfg))
                if not improvements:
                    break                                         # no condition helps OOS -> stop (auto-regularize depth)
                # ── BEAM, NOT max() ───────────────────────────────────────────────────
                # `max(improvements)` committed to the single best candidate at every
                # depth. The second and third best were evaluated and thrown away, so a
                # stack whose FIRST move is second-best but whose SECOND move is far
                # stronger could never be reached -- the path was decided one step at a
                # time and never revisited.
                # Keep the top `beam` alive, extend each, and let the FINISHED stacks
                # compete on out-of-sample score. With beam=3 this explores roughly
                # 3^depth paths instead of one, at 3x the evaluation cost per depth.
                # ── ORDER PERMUTATION ─────────────────────────────────────────────────
                # A finished AND-stack gives identical bets in any order, but the greedy
                # PATH depends on order completely: each step is chosen against what is
                # already there, so A+B can stall at depth 2 while B+A runs to depth 4.
                # Ties in OOS score are broken by trying the alternative order first on
                # alternating depths, which reaches paths a fixed order never visits.
                if permute_order and len(improvements) > 1:
                    _eps = 1e-9
                    _top = improvements[0][1] if improvements else 0
                    _ties = [t for t in improvements if abs(t[1] - _top) <= _eps]
                    if len(_ties) > 1 and (depth % 2 == 1):
                        improvements = _ties[::-1] + [t for t in improvements
                                                      if t not in _ties]
                improvements.sort(key=lambda x: -x[1])
                _beam_k = max(1, int(beam or 1))
                _branches = improvements[:_beam_k]
                if _beam_k > 1 and len(_branches) > 1:
                    # Score each branch one step deeper, then take the branch whose
                    # CONTINUATION is strongest rather than whose first step was.
                    _scored = []
                    for _cn, _os, _ir, _or_, _cfg in _branches:
                        _look = _os
                        try:
                            _nxt = self._build_pool(strategy_name, time_rule, league_filter,
                                                    cfg=_cfg)
                            for _c2, _m2 in list(_nxt.items())[:12]:
                                if _c2 == _cn or _c2 not in available:
                                    continue
                                _t2 = _cfg.copy()
                                _om = _t2.get('extra_mask') or (lambda f: True)
                                _t2['extra_mask'] = (lambda f, b=_om, c=_m2:
                                                     b(f).fillna(False) & c(f).fillna(False))
                                _r2 = self._evaluate_variant_on_features(
                                    strategy_name, _t2, threshold, time_rule, league_filter,
                                    features_oos, min_bets=min_bets)
                                if _r2 is not None:
                                    _look = max(_look, _score(_r2))
                        except Exception:
                            pass
                        _scored.append((_look, _cn, _ir, _or_, _cfg))
                    _scored.sort(key=lambda t: -t[0])
                    _, cond_name, best_res, best_oos_res, best_cfg = _scored[0]
                else:
                    cond_name, _, best_res, best_oos_res, best_cfg = _branches[0]
            available.remove(cond_name)
            added_conditions.append(cond_name)
            if _gated and best_oos_res is not None:
                print(f"[DISCOVER] {strategy_name} | {league_filter or 'All'} | +'{cond_name}' (depth {depth+1}) | "
                      f"IS_Sharpe: {best_res['sharpe_profit_per_dd']:.2f} | OOS_Sharpe: {best_oos_res['sharpe_profit_per_dd']:.2f} | "
                      f"OOS_Profit: {best_oos_res['total_profit']:.1f} | OOS_Bets: {best_oos_res['n_bets']}  [OOS-gated]")
            else:
                print(f"[DISCOVER] {strategy_name} | {league_filter or 'All'} | +'{cond_name}' (depth {depth+1}) | "
                      f"Sharpe: {best_res['sharpe_profit_per_dd']:.2f} | Profit: {best_res['total_profit']:.1f} | Bets: {best_res['n_bets']}")

        if not added_conditions:
            return None

        if features_is is not None and features_oos is not None:
            is_res = self._evaluate_discovery_trial(
                strategy_name, best_cfg, threshold, time_rule, league_filter, features_is, min_bets=min_bets
            )
            oos_res = self._evaluate_discovery_trial(
                strategy_name, best_cfg, threshold, time_rule, league_filter, features_oos, min_bets=min_bets
            )
            if is_res is None or oos_res is None:
                print("[DISCOVER-SKIP] " + strategy_name + " | IS or OOS evaluation failed")
                return None
            is_profit = is_res.get('total_profit', 0)
            oos_profit = oos_res.get('total_profit', 0)
            is_sharpe = is_res.get('sharpe_profit_per_dd', 0)
            oos_sharpe = oos_res.get('sharpe_profit_per_dd', 0)
            is_pval = is_res.get('p_value_ttest', 1)
            oos_pval = oos_res.get('p_value_ttest', 1)
            stability_ratio = round(oos_profit / is_profit, 2) if is_profit != 0 else 0.0
            oos_pass = (stability_ratio >= 0.30) and (oos_pval < 0.05) and (is_pval < 0.05)
            if not oos_pass:
                print("[DISCOVER-SKIP] " + strategy_name + " | OOS FAILED | Ratio=" + str(stability_ratio) + " IS_p=" + str(round(is_pval, 4)) + " OOS_p=" + str(round(oos_pval, 4)))
                return None
            print("[DISCOVER-PASS] " + strategy_name + " | OOS validated | Ratio=" + str(stability_ratio) + " IS_S=" + str(round(is_sharpe, 2)) + " OOS_S=" + str(round(oos_sharpe, 2)))
            oos_keys = ['n_bets', 'wins', 'losses', 'win_rate', 'total_profit', 'profit_per_bet', 'roi',
                        'avg_odds', 'max_drawdown', 'max_consecutive_losses',
                        'sharpe_profit_per_dd', 'sharpe_traditional', 'p_value_ttest',
                        'implied_probability', 'actual_probability']
            for k in oos_keys:
                best_res['is_' + k] = is_res.get(k, 0)
                best_res['oos_' + k] = oos_res.get(k, 0)
            best_res['stability_ratio'] = stability_ratio
            best_res['oos_pass'] = True
        else:
            best_res['oos_pass'] = False
            best_res['stability_ratio'] = 0.0

        discovery_result = best_res.copy()
        discovery_result['discovered_conditions'] = added_conditions
        discovery_result['base_variant_id'] = base_variant['variant_id']
        discovery_result['base_sharpe'] = base_res['sharpe_profit_per_dd']
        discovery_result['base_profit'] = base_res['total_profit']
        discovery_result['base_n_bets'] = base_res['n_bets']
        discovery_result['sharpe_improvement'] = round(best_res['sharpe_profit_per_dd'] - base_res['sharpe_profit_per_dd'], 2)
        discovery_result['profit_improvement'] = round(best_res['total_profit'] - base_res['total_profit'], 2)
        discovery_result['strategy'] = strategy_name
        discovery_result['league'] = base_variant['league']
        discovery_result['odds_threshold'] = threshold
        discovery_result['time_rule'] = str(time_rule)
        discovery_result['time_rule_raw'] = time_rule
        discovery_result['variant_id'] = self._hash_variant(
            strategy_name,
            {'odds_threshold': threshold, 'time_rule': time_rule, 'conditions': ','.join(added_conditions)},
            league_filter or 'All'
        )
        return discovery_result

    def run_tiered_discovery(self, top_variants, features_is=None, features_oos=None, min_bets=100, max_depth=3, top_n_pool=50):
        """Progressive depth-first discovery with rolling top-N pool (from v33)."""
        if not top_variants:
            return []
        print("[TIERED_DISCOVERY] Running progressive depth-first discovery on " + str(len(top_variants)) + " variants...")
        if features_is is not None and features_oos is not None:
            print("[TIERED_DISCOVERY] OOS validation ENABLED")
        else:
            print("[TIERED_DISCOVERY] OOS validation DISABLED")

        discovered = []
        rolling_pool = []
        for variant in top_variants:
            res = self.discover_best_conditions(variant, features_is=features_is, features_oos=features_oos,
                                                  min_bets=min_bets, max_depth=max_depth)
            if res:
                discovered.append(res)
                rolling_pool.append(res)
                rolling_pool.sort(key=lambda x: self._discovery_score(x), reverse=True)
                rolling_pool = rolling_pool[:top_n_pool]
                print(f"[TIERED_DISCOVERY] Pool size: {len(rolling_pool)} | Best score: {self._discovery_score(rolling_pool[0]):.2f}")

        print("[TIERED_DISCOVERY] Complete. " + str(len(discovered)) + " variants passed OOS validation.")
        return discovered

    def run_discovery_grid(self, top_variants, features_is=None, features_oos=None, min_bets=100, max_depth=3):
        if not top_variants:
            return []
        print("[DISCOVERY] Running greedy condition discovery on " + str(len(top_variants)) + " top variants...")
        if features_is is not None and features_oos is not None:
            print("[DISCOVERY] OOS validation ENABLED")
        else:
            print("[DISCOVERY] OOS validation DISABLED")

        discovered = []
        for variant in top_variants:
            res = self.discover_best_conditions(variant, features_is=features_is, features_oos=features_oos,
                                                  min_bets=min_bets, max_depth=max_depth)
            if res:
                discovered.append(res)

        print("[DISCOVERY] Complete. " + str(len(discovered)) + " variants passed OOS validation.")
        return discovered

    def _format_hours(self, hours_list):
        if not hours_list:
            return 'None'
        hours = sorted([int(h) for h in hours_list])
        groups = []
        current = [hours[0]]
        for h in hours[1:]:
            if h == current[-1] + 1:
                current.append(h)
            else:
                groups.append(current)
                current = [h]
        groups.append(current)

        parts = []
        standalone = []
        for g in groups:
            if len(g) >= 2:
                parts.append(f"[{g[0]:02d}:00 - {g[-1]:02d}:00]")
            else:
                standalone.extend(g)

        if standalone:
            standalone_str = ', '.join(f"{h:02d}" for h in standalone)
            parts.append(f"[{standalone_str}]")

        return ' '.join(parts) if parts else 'None'

    def _hourly_metrics(self, bets_df):
        if len(bets_df) == 0:
            return {'best_hours': '', 'worst_hours': '', 'hourly_profit': {h: 0.0 for h in range(24)}}
        df = bets_df.copy()
        df['match_hour'] = pd.to_datetime(df['first_observed_timestamp'], errors='coerce').dt.hour
        hourly_profit = df.groupby('match_hour')['profit'].sum().to_dict()
        hourly_bets = df.groupby('match_hour').size().to_dict()
        full_hourly = {h: round(hourly_profit.get(h, 0.0), 2) for h in range(24)}
        best = [str(h) for h in range(24) if full_hourly[h] > 0 and hourly_bets.get(h, 0) >= 5]
        worst = [str(h) for h in range(24) if full_hourly[h] < 0 and hourly_bets.get(h, 0) >= 5]
        return {
            'best_hours': self._format_hours(best),
            'worst_hours': self._format_hours(worst),
            'hourly_profit': full_hourly,
        }

    def _evaluate_variant_fast(self, strategy_name, cfg, threshold, time_rule, league_filter, pool,
                                prematch_threshold=None, prematch_spread_threshold=None):
        odds_col = cfg['odds_col']
        comp = cfg['comparator']
        pool_in_count = len(pool)

        # Apply pre-match filters BEFORE odds threshold (v74.2: track per-stage counts)
        pm_after = pool_in_count
        if prematch_threshold is not None and 'prematch_odds_col' in cfg:
            pm_col = cfg['prematch_odds_col']
            pm_comp = cfg.get('prematch_comparator', 'le')
            if pm_comp == 'le':
                pool = pool[pool[pm_col] <= prematch_threshold]
            elif pm_comp == 'ge':
                pool = pool[pool[pm_col] >= prematch_threshold]
            elif pm_comp == 'gt':
                pool = pool[pool[pm_col] > prematch_threshold]
            elif pm_comp == 'lt':
                pool = pool[pool[pm_col] < prematch_threshold]
            pm_after = len(pool)

        ps_after = pm_after
        # v74.2 FIX: Spread threshold >= 900 is the pass-all sentinel — skip it.
        # 'ge 999.0' literally means "spread >= 999" which NO match has, killing every pool.
        if prematch_spread_threshold is not None and prematch_spread_threshold < 900 and 'prematch_spread_col' in cfg:
            ps_col = cfg['prematch_spread_col']
            ps_comp = cfg.get('prematch_spread_comparator', 'ge')
            if ps_comp == 'ge':
                pool = pool[pool[ps_col] >= prematch_spread_threshold]
            elif ps_comp == 'le':
                pool = pool[pool[ps_col] <= prematch_spread_threshold]
            elif ps_comp == 'gt':
                pool = pool[pool[ps_col] > prematch_spread_threshold]
            elif ps_comp == 'lt':
                pool = pool[pool[ps_col] < prematch_spread_threshold]
            ps_after = len(pool)

        if len(pool) == 0:
            # v74.2: Identify the ACTUAL prematch filter killer
            if pool_in_count == 0:
                reason = f'pool already empty before prematch filters (extra_mask/time_rule/league killed all)'
                killer = 'pre-prematch'
            elif pm_after == 0:
                pm_col = cfg.get('prematch_odds_col', 'N/A')
                pm_comp = cfg.get('prematch_comparator', 'le')
                reason = f'prematch_odds ({pm_col} {pm_comp} {prematch_threshold}) killed all {pool_in_count} rows'
                killer = 'prematch_odds'
            elif ps_after == 0:
                ps_col = cfg.get('prematch_spread_col', 'N/A')
                ps_comp = cfg.get('prematch_spread_comparator', 'ge')
                reason = f'prematch_spread ({ps_col} {ps_comp} {prematch_spread_threshold}) killed all {pm_after} rows'
                killer = 'prematch_spread'
            else:
                reason = f'unknown filter killed all {pool_in_count} rows'
                killer = 'unknown'
            print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | REASON: {reason} [killer={killer}]")
            return None

        if comp == 'gt':
            odds_mask = pool[odds_col] > threshold
        elif comp == 'ge':
            odds_mask = pool[odds_col] >= threshold
        elif comp == 'le':
            odds_mask = pool[odds_col] <= threshold
        elif comp == 'lt':
            odds_mask = pool[odds_col] < threshold
        else:
            odds_mask = pool[odds_col] >= threshold

        candidates = pool[odds_mask]
        if len(candidates) == 0:
            print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | threshold={threshold} | REASON: No triggers found in pool of {len(pool)} rows")
            return None

        win_col = cfg['win_col']
        # v74 LAYER 5: Early termination — abort if obviously losing after 50 bets
        if EARLY_TERMINATION_ENABLED and len(candidates) >= EARLY_TERM_MIN_BETS:
            early_idx = candidates.groupby('match_id', observed=True)['timestamp'].idxmin()
            early_bets = candidates.loc[early_idx].head(EARLY_TERM_MIN_BETS).copy()
            _win_val = cfg.get('win_value')
            if _win_val is not None:
                early_bets['won'] = early_bets[win_col].astype(str) == str(_win_val)
            else:
                early_bets['won'] = early_bets[win_col].astype(str) == early_bets['final_result'].astype(str)
            early_bets['profit'] = ProfitMath.dispatch(early_bets, cfg, odds_col, early_bets['won'], early_bets['final_result'])
            # v74.6 FIX: Max drawdown = peak - trough (cumsum.max() - cumsum.min()),
            # not total_profit - cumsum.min() which gives wrong results.
            cumsum = early_bets['profit'].cumsum()
            early_sharpe = early_bets['profit'].sum() / max(1, cumsum.max() - cumsum.min())
            if early_sharpe < EARLY_TERM_SHARPE_FLOOR and early_bets['profit'].sum() < 0:
                print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | REASON: Early termination (sharpe={early_sharpe:.2f} < {EARLY_TERM_SHARPE_FLOOR}, profit={early_bets['profit'].sum():.1f})")
                return None  # Abort this variant early

        opp_metrics = self._calc_opportunity_windows(candidates)

        eligible_dates = pd.to_datetime(pool['timestamp'], errors='coerce').dt.date
        eligible_daily = pool.groupby(eligible_dates)['match_id'].nunique().to_dict()
        total_eligible = pool['match_id'].nunique()

        trigger_idx = candidates.groupby('match_id', observed=True)['timestamp'].idxmin()
        bets = candidates.loc[trigger_idx].copy()
        bets = bets.sort_values('timestamp').reset_index(drop=True)

        triggered_dates = pd.to_datetime(bets['timestamp'], errors='coerce').dt.date
        triggered_daily = bets.groupby(triggered_dates)['match_id'].nunique().to_dict()
        total_triggered = len(bets)

        if 'win_value' in cfg:
            bets['won'] = bets[win_col].astype(str) == str(cfg['win_value'])
        else:
            bets['won'] = bets[win_col].astype(str) == bets['final_result'].astype(str)

        bets['profit'] = ProfitMath.dispatch(bets, cfg, odds_col, bets['won'], bets['final_result'])

        bets['cumulative_profit'] = bets['profit'].cumsum()

        payout_col = cfg.get('payout_odds_col', odds_col)
        metrics = self._calc_metrics(bets, payout_col)
        metrics.update(opp_metrics)
        metrics['total_eligible'] = total_eligible
        metrics['eligible_daily'] = eligible_daily
        metrics['total_triggered'] = total_triggered
        metrics['triggered_daily'] = triggered_daily
        metrics['trigger_rate'] = (total_triggered / total_eligible * 100) if total_eligible > 0 else 0.0

        hourly = self._hourly_metrics(bets)
        metrics['best_hours'] = hourly['best_hours']
        metrics['worst_hours'] = hourly['worst_hours']
        metrics['hourly_profit'] = hourly['hourly_profit']

        total_eligible = pool['match_id'].nunique()
        total_triggered = len(bets)
        trigger_rate = (total_triggered / total_eligible * 100) if total_eligible > 0 else 0.0

        metrics['strategy'] = strategy_name
        metrics['league'] = league_filter or 'All'
        metrics['odds_threshold'] = threshold
        metrics['time_rule'] = str(time_rule)
        metrics['time_rule_raw'] = time_rule
        metrics['prematch_threshold'] = prematch_threshold if prematch_threshold is not None else 'N/A'
        metrics['prematch_spread_threshold'] = prematch_spread_threshold if prematch_spread_threshold is not None else 'N/A'
        metrics['variant_id'] = self._hash_variant(
            strategy_name,
            {
                'odds_threshold': threshold,
                'time_rule': time_rule,
                'prematch_threshold': prematch_threshold if prematch_threshold is not None else 'N/A',
                'prematch_spread_threshold': prematch_spread_threshold if prematch_spread_threshold is not None else 'N/A'
            },
            league_filter
        )
        metrics['n_bets'] = len(bets)
        metrics['bets_df'] = bets
        metrics['total_eligible'] = total_eligible
        metrics['total_triggered'] = total_triggered
        metrics['trigger_rate'] = round(trigger_rate, 2)
        print(f"[PASS] {strategy_name} | {league_filter or 'All'} | Bets={len(bets)} | Profit={metrics.get('total_profit', 0):.1f} | WR={metrics.get('win_rate', 0):.1f}%")
        return metrics

    # ── v69 ADDITION: Lightweight variant evaluation for sensitivity pre-processor ──
    def _evaluate_variant_minimal(self, strategy_name, cfg, threshold, time_rule, league_filter, pool,
                                  prematch_threshold=None, prematch_spread_threshold=None):
        """Lightweight evaluation for sensitivity analysis. No opp windows, hourly, or daily metrics."""
        odds_col = cfg['odds_col']
        comp = cfg['comparator']
        pool_in_count = len(pool)

        # Apply pre-match filters (v74.2: track per-stage counts)
        pm_after = pool_in_count
        if prematch_threshold is not None and 'prematch_odds_col' in cfg:
            pm_col = cfg['prematch_odds_col']
            pm_comp = cfg.get('prematch_comparator', 'le')
            if pm_comp == 'le':
                pool = pool[pool[pm_col] <= prematch_threshold]
            elif pm_comp == 'ge':
                pool = pool[pool[pm_col] >= prematch_threshold]
            elif pm_comp == 'gt':
                pool = pool[pool[pm_col] > prematch_threshold]
            elif pm_comp == 'lt':
                pool = pool[pool[pm_col] < prematch_threshold]
            pm_after = len(pool)

        ps_after = pm_after
        # v74.2 FIX: Spread threshold >= 900 is the pass-all sentinel — skip it.
        if prematch_spread_threshold is not None and prematch_spread_threshold < 900 and 'prematch_spread_col' in cfg:
            ps_col = cfg['prematch_spread_col']
            ps_comp = cfg.get('prematch_spread_comparator', 'ge')
            if ps_comp == 'ge':
                pool = pool[pool[ps_col] >= prematch_spread_threshold]
            elif ps_comp == 'le':
                pool = pool[pool[ps_col] <= prematch_spread_threshold]
            elif ps_comp == 'gt':
                pool = pool[pool[ps_col] > prematch_spread_threshold]
            elif ps_comp == 'lt':
                pool = pool[pool[ps_col] < prematch_spread_threshold]
            ps_after = len(pool)

        if len(pool) == 0:
            # v74.2: Identify the ACTUAL prematch filter killer
            if pool_in_count == 0:
                reason = f'pool already empty before prematch filters (extra_mask/time_rule/league killed all)'
                killer = 'pre-prematch'
            elif pm_after == 0:
                pm_col = cfg.get('prematch_odds_col', 'N/A')
                pm_comp = cfg.get('prematch_comparator', 'le')
                reason = f'prematch_odds ({pm_col} {pm_comp} {prematch_threshold}) killed all {pool_in_count} rows'
                killer = 'prematch_odds'
            elif ps_after == 0:
                ps_col = cfg.get('prematch_spread_col', 'N/A')
                ps_comp = cfg.get('prematch_spread_comparator', 'ge')
                reason = f'prematch_spread ({ps_col} {ps_comp} {prematch_spread_threshold}) killed all {pm_after} rows'
                killer = 'prematch_spread'
            else:
                reason = f'unknown filter killed all {pool_in_count} rows'
                killer = 'unknown'
            print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | REASON: {reason} [killer={killer}]")
            return None

        # Odds mask
        if comp == 'gt':
            odds_mask = pool[odds_col] > threshold
        elif comp == 'ge':
            odds_mask = pool[odds_col] >= threshold
        elif comp == 'le':
            odds_mask = pool[odds_col] <= threshold
        elif comp == 'lt':
            odds_mask = pool[odds_col] < threshold
        else:
            odds_mask = pool[odds_col] >= threshold

        candidates = pool[odds_mask]
        if len(candidates) == 0:
            print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | threshold={threshold} | REASON: No triggers found in pool of {len(pool)} rows")
            return None

        trigger_idx = candidates.groupby('match_id', observed=True)['timestamp'].idxmin()
        bets = candidates.loc[trigger_idx].copy()
        bets = bets.sort_values('timestamp').reset_index(drop=True)

        win_col = cfg['win_col']
        if 'win_value' in cfg:
            bets['won'] = bets[win_col].astype(str) == str(cfg['win_value'])
        else:
            bets['won'] = bets[win_col].astype(str) == bets['final_result'].astype(str)

        bets['profit'] = ProfitMath.dispatch(bets, cfg, odds_col, bets['won'], bets['final_result'])

        n = len(bets)
        if n == 0:
            print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | threshold={threshold} | REASON: Zero bets after trigger selection from {len(candidates)} candidates")
            return None

        wins = int(bets['won'].sum())
        win_rate = (wins / n * 100) if n > 0 else 0.0
        total_profit = bets['profit'].sum()
        profit_per_bet = total_profit / n
        roi = profit_per_bet * 100

        cum = np.cumsum(bets['profit'].values)
        running_max = np.maximum.accumulate(cum)
        drawdowns = running_max - cum
        max_dd = float(np.max(drawdowns)) if len(drawdowns) > 0 else 0.0

        loss_streaks = []
        current = 0
        for w in bets['won']:
            if not w:
                current += 1
            else:
                loss_streaks.append(current)
                current = 0
        loss_streaks.append(current)
        max_consec_loss = max(loss_streaks) if loss_streaks else 0

        sharpe_dd = (total_profit / max_dd) if max_dd > 0 else (total_profit if total_profit > 0 else 0.0)

        profits = bets['profit'].values
        std_profit = float(np.std(profits, ddof=1)) if len(profits) > 1 else 0.0
        sharpe_trad = (profit_per_bet / std_profit) if std_profit > 0 else 0.0

        p_value = self._ttest_pvalue(profit_per_bet, std_profit, n)

        return {
            'n_bets': n, 'wins': wins, 'losses': n - wins, 'win_rate': win_rate,
            'total_profit': total_profit, 'profit_per_bet': profit_per_bet,
            'roi': roi, 'max_drawdown': max_dd,
            'max_consecutive_losses': max_consec_loss,
            'sharpe_profit_per_dd': sharpe_dd, 'sharpe_traditional': sharpe_trad,
            'p_value_ttest': p_value,
        }

    def _evaluate_pool_thresholds(self, strategy_name, cfg, time_rule, league_filter, pool, thresholds, min_bets):
        results = []
        pm_thresholds = cfg.get('prematch_thresholds', [None])
        ps_thresholds = cfg.get('prematch_spread_thresholds', [None])
        for threshold in thresholds:
            for pm_thresh in pm_thresholds:
                for ps_thresh in ps_thresholds:
                    res = self._evaluate_variant_fast(strategy_name, cfg, threshold, time_rule, league_filter, pool,
                                                        prematch_threshold=pm_thresh, prematch_spread_threshold=ps_thresh)
                    if res and res['n_bets'] >= min_bets:
                        res['prematch_threshold'] = pm_thresh if pm_thresh is not None else 'N/A'
                        res['prematch_spread_threshold'] = ps_thresh if ps_thresh is not None else 'N/A'
                        results.append(res)
                    elif res:
                        print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={pm_thresh} PS={ps_thresh} | threshold={threshold} | REASON: Too few bets ({res['n_bets']} < {min_bets})")
        return results

    def _calc_metrics(self, bets, odds_col):
        n = len(bets)
        wins = int(bets['won'].sum())
        losses = n - wins
        win_rate = (wins / n * 100) if n > 0 else 0.0
        total_profit = bets['profit'].sum()
        profit_per_bet = total_profit / n if n > 0 else 0.0
        avg_odds = bets[odds_col].mean()
        roi = (total_profit / n * 100) if n > 0 else 0.0

        cum = bets['cumulative_profit'].values
        running_max = np.maximum.accumulate(cum)
        drawdowns = running_max - cum
        max_dd = float(np.max(drawdowns)) if len(drawdowns) > 0 else 0.0

        loss_streaks = []
        current = 0
        for w in bets['won']:
            if not w:
                current += 1
            else:
                loss_streaks.append(current)
                current = 0
        loss_streaks.append(current)
        max_consec_loss = max(loss_streaks) if loss_streaks else 0

        sharpe_dd = (total_profit / max_dd) if max_dd > 0 else (total_profit if total_profit > 0 else 0.0)

        profits = bets['profit'].values
        std_profit = float(np.std(profits, ddof=1)) if len(profits) > 1 else 0.0
        sharpe_trad = (profit_per_bet / std_profit) if std_profit > 0 else 0.0

        p_value = self._ttest_pvalue(profit_per_bet, std_profit, n)

        implied_prob = (1 / bets[odds_col]).mean() if n > 0 else 0.0
        actual_prob = win_rate / 100.0

        avg_odds_minus_1 = avg_odds - 1.0
        odds_efficiency = (avg_odds_minus_1 / max_consec_loss) if max_consec_loss > 0 else 999.0
        # v33: Configurable is_rejected gate
        if IS_REJECTED_ENABLED and avg_odds_minus_1 > 0:
            is_rejected = (max_dd > IS_REJECTED_MULTIPLIER * avg_odds_minus_1)
        elif IS_REJECTED_ENABLED:
            is_rejected = True
        else:
            is_rejected = False

        return {
            'wins': wins, 'losses': losses, 'win_rate': win_rate,
            'total_profit': total_profit, 'profit_per_bet': profit_per_bet,
            'avg_odds': avg_odds, 'roi': roi,
            'max_drawdown': max_dd, 'max_consecutive_losses': max_consec_loss,
            'sharpe_profit_per_dd': sharpe_dd, 'sharpe_traditional': sharpe_trad,
            'p_value_ttest': p_value,
            'implied_probability': implied_prob, 'actual_probability': actual_prob,
            'odds_efficiency': odds_efficiency,
            'is_rejected': is_rejected,
        }

    def _ttest_pvalue(self, mean, std, n):
        if n < 2 or std == 0 or std != std:
            return 1.0
        t_stat = mean / (std / math.sqrt(n))
        p = 2 * (1 - 0.5 * (1 + math.erf(abs(t_stat) / math.sqrt(2))))
        return max(min(p, 1.0), 0.0)

    def _hash_variant(self, strategy, params, league):
        s = f"{strategy}|{params}|{league}"
        return hashlib.md5(s.encode()).hexdigest()[:12]

    def _run_grid_core(self, min_bets=100, max_workers=None):
        """ProcessPoolExecutor vectorized grid evaluation. 4-8 min target on 8 cores."""
        start_time = time.time()
        start_ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        print(f"[START] Grid evaluation started at {start_ts}")
        leagues = ['All'] + sorted(self.features['league'].dropna().unique().tolist())
        league_counts = self.features.groupby('league')['match_id'].nunique().to_dict()
        total_matches = self.features['match_id'].nunique()
        print("Building variant parameter list...")
        variant_tasks = []
        skipped = 0
        skipped_pool_empty = 0
        skipped_min_matches = 0
        # V11 DIAGNOSTIC: Track variant task creation for v11 strategies
        v11_strategies = ['Loser_SustainedOdds', 'Loser_SustainedOdds_RoleReversal',
                          'Loser_PlayerExperience', 'Loser_Form5', 'Loser_Form10',
                          'Loser_Form20', 'Loser_WR_Asymmetry', 'Loser_DailyForm',
                          'SustOdds_PlayerWR']
        v11_task_counts = {s: 0 for s in v11_strategies}
        v11_pool_sizes = {s: [] for s in v11_strategies}

        # v16 OPT: build ONE VectorizedPool for cheap pool-size probing instead
        # of calling _build_pool (a full-DataFrame boolean mask + copy, and a fresh
        # extra_mask lambda evaluation) for every strategy x time_rule x league.
        # Masks are precomputed once and reused across all combos.
        probe_vpool = VectorizedPool(self.features, strategy_names=list(self.grid.keys()))

        for sname, cfg in self.grid.items():
            expanded_rules = self._expand_time_rules(cfg['time_rules'])
            for tr in expanded_rules:
                for league in leagues:
                    total_rows, unique_matches = probe_vpool.pool_size(sname, tr, league)
                    if total_rows == 0:
                        skipped += 1
                        skipped_pool_empty += 1
                        continue
                    if league != 'All' and league in league_counts:
                        scaled_min = max(50, int(min_bets * (league_counts[league] / total_matches)))
                        effective_min = min(min_bets, scaled_min)
                    else:
                        effective_min = min_bets
                    if unique_matches < effective_min:
                        skipped += 1
                        skipped_min_matches += 1
                        continue
                    pm_thresholds = cfg.get('prematch_thresholds', [None])
                    ps_thresholds = cfg.get('prematch_spread_thresholds', [None])
                    for pm in pm_thresholds:
                        for ps in ps_thresholds:
                            variant_tasks.append({
                                'strategy': sname, 'time_rule': tr, 'league': league,
                                'pm': pm, 'ps': ps, 'effective_min': effective_min,
                            })
                            if sname in v11_task_counts:
                                v11_task_counts[sname] += 1
                                v11_pool_sizes[sname].append(unique_matches)

        # Release the probe pool before spawning workers (each builds its own).
        del probe_vpool
        import gc as _gc_probe
        _gc_probe.collect()
        
        # V11 DIAGNOSTIC: Report v11 strategy task counts
        print("[V11 DIAGNOSTIC] Variant task counts:")
        for s in v11_strategies:
            count = v11_task_counts.get(s, 0)
            if s in self.grid:
                if count > 0:
                    avg_pool = sum(v11_pool_sizes[s]) // len(v11_pool_sizes[s]) if v11_pool_sizes[s] else 0
                    print(f"[V11 DIAGNOSTIC]   {s}: {count} tasks, avg_pool={avg_pool} matches")
                else:
                    print(f"[V11 DIAGNOSTIC]   {s}: NO TASKS — pool empty or below min_bets")
            else:
                print(f"[V11 DIAGNOSTIC]   {s}: NOT IN engine.grid")
        
        total_variants = sum(len(self.grid[t['strategy']]['thresholds']) for t in variant_tasks)
        print(f"Pool tasks: {len(variant_tasks)} valid, {skipped} skipped.")
        print(f"Grid size: {total_variants} variants to evaluate...")
        if max_workers is None:
            max_workers = WORKERS_OVERRIDE or max(1, int(os.cpu_count() * 0.60))
        # v16 FIX: The old "zero pickle I/O" shared-memory branch was broken —
        # it did `pd.DataFrame(shared.buf)`, which cannot reconstruct a mixed-dtype
        # DataFrame from a raw byte buffer (no columns / dtypes / shape), so any
        # worker that took that path received garbage. It is removed here. With the
        # per-process initializer the features file is now read only ONCE per worker
        # process anyway (not once per chunk), so SHM bought us nothing. We always
        # serialize once to a compact parquet (lz4) and let each process load it once.
        use_shm = False
        shm_name = None
        features_path = None
        # BIG DATA OPT: Use parquet (2-5x faster, 50-80% smaller than pickle)
        if _PYARROW_AVAILABLE:
            features_path = tempfile.mktemp(suffix='_v74_features.parquet')
            self.features.to_parquet(features_path, compression=FEATURE_PARQUET_COMPRESSION)
            print(f"[v74 FEAT] Serialized {len(self.features):,} rows to parquet "
                  f"(compression={FEATURE_PARQUET_COMPRESSION}) ({features_path})")
        else:
            features_path = tempfile.mktemp(suffix='_v74_features.pkl')
            self.features.to_pickle(features_path)
        features_payload = features_path

        chunk_size = max(1, len(variant_tasks) // (max_workers * 4))
        chunks = [variant_tasks[i:i+chunk_size] for i in range(0, len(variant_tasks), chunk_size)]
        print(f"[v74 POOL] {len(chunks)} chunks | {max_workers} workers | chunk_size={chunk_size}")

        # v74.1 FIX: Serialize modified grid so workers use engine.grid (not stale STRATEGY_GRID)
        # If grid contains unpicklable lambdas (test env), pass None and worker falls back to STRATEGY_GRID
        grid_path = tempfile.mktemp(suffix='_v74_grid.pkl')
        grid_serializable = True
        try:
            import pickle
            # V11 FIX: Create serializable grid by replacing unpicklable lambdas with None marker
            serializable_grid = {}
            for sname, cfg in self.grid.items():
                serializable_cfg = {}
                for k, v in cfg.items():
                    if k == 'extra_mask' and callable(v):
                        serializable_cfg[k] = None  # Marker: use STRATEGY_GRID lambda
                    else:
                        serializable_cfg[k] = v
                serializable_grid[sname] = serializable_cfg
            with open(grid_path, 'wb') as f:
                pickle.dump(serializable_grid, f)
            print(f"[v74 GRID] Serialized {len(serializable_grid)} strategies")
        except (pickle.PicklingError, TypeError, AttributeError) as e:
            print(f"[v74 GRID] Serialization failed: {e}. Workers will use STRATEGY_GRID.")
            grid_serializable = False

        all_results = []
        # v74.1 FIX: Single-threaded fallback for max_workers=1 (no pickling needed)
        # Pass grid_path only if serializable; else worker falls back to STRATEGY_GRID
        worker_grid_path = grid_path if grid_serializable else None
        if max_workers == 1:
            print("[v74] Single-threaded mode — no multiprocessing")
            # v16: populate the process-global worker state ONCE, then reuse it.
            _init_worker_v74(features_payload, use_shm, worker_grid_path)
            for i, chunk in enumerate(chunks):
                chunk_results = _worker_evaluate_chunk_v74(chunk)
                all_results.extend(chunk_results)
                if (i + 1) % max(1, len(chunks)//10) == 0 or i + 1 == len(chunks):
                    pct = (i + 1) / len(chunks) * 100
                    print(f"[POOL] {i+1}/{len(chunks)} chunks | {pct:.0f}% | {len(all_results)} variants")
        else:
            # v16: heavy per-process setup runs ONCE via `initializer` instead of
            # being repeated for every chunk. Chunks are now tiny payloads (task lists).
            # Results are collected in SUBMISSION order (NOT as_completed) so the raw
            # result ordering is deterministic and matches pre-v16 behaviour — this
            # keeps tie-breaking in the final ranking bit-for-bit reproducible.
            import multiprocessing as _mpx
            _ctx_grid = _mpx.get_context('fork') if 'fork' in _mpx.get_all_start_methods() else None   # [v192 K13] no fork -> the sequential branch above; the workers are not importable under an exec-loaded engine
            if _ctx_grid is None:
                # [v192 Q2] LOUD, NEVER SILENT. Without fork the children cannot re-import an exec-loaded engine,
                # so the pool would either hang or fall back to one core while the log still said max_workers.
                # The caller catches this and takes the sequential branch, which prints the reason.
                raise RuntimeError('LEGACY GRID: no fork on this platform — the pool cannot start; the sequential branch runs instead (same results, one core)')
            print(f'[grid] {len(chunks)} chunk(s) across {max_workers} process(es) (fork) — a failure here falls to SERIAL and says so, never to a silent single core')
            _unused_v190 = None   # [v190] default is spawn on macOS: the child cannot re-import an exec-loaded engine
            with ProcessPoolExecutor(max_workers=max_workers, mp_context=_ctx_grid,
                                     initializer=_init_worker_v74,
                                     initargs=(features_payload, use_shm, worker_grid_path)) as executor:
                futures = [executor.submit(_worker_evaluate_chunk_v74, chunk) for chunk in chunks]
                completed = 0
                total_futs = len(futures)
                for future in futures:
                    chunk_results = future.result()
                    all_results.extend(chunk_results)
                    completed += 1
                    if completed % max(1, total_futs//10) == 0 or completed == total_futs:
                        pct = completed / total_futs * 100
                        print(f"[POOL] {completed}/{total_futs} chunks | {pct:.0f}% | {len(all_results)} variants")
        
        # V11 DIAGNOSTIC: Report raw results for v11 strategies BEFORE ranking gates
        v11_strategies = ['Loser_SustainedOdds', 'Loser_SustainedOdds_RoleReversal',
                          'Loser_PlayerExperience', 'Loser_Form5', 'Loser_Form10',
                          'Loser_Form20', 'Loser_WR_Asymmetry', 'Loser_DailyForm',
                          'SustOdds_PlayerWR']
        print("[V11 DIAGNOSTIC] Raw results BEFORE ranking gates:")
        v11_found = False
        for s in v11_strategies:
            s_results = [r for r in all_results if r.get('strategy') == s]
            if s_results:
                v11_found = True
                best = max(s_results, key=lambda x: x.get('sharpe_profit_per_dd', 0))
                print(f"[V11 DIAGNOSTIC]   {s}: {len(s_results)} variants | best: N={best.get('n_bets',0)}, Sharpe={best.get('sharpe_profit_per_dd',0):.2f}, Profit={best.get('total_profit',0):.1f}, p={best.get('p_value_ttest',1):.4f}")
        if not v11_found:
            print("[V11 DIAGNOSTIC]   NO v11 strategies in raw results — they failed at pool/worker level")
        
        if use_shm and shm_name:
            try:
                import multiprocessing.shared_memory as shm
                shared = shm.SharedMemory(name=shm_name)
                shared.close()
                shared.unlink()
                print(f"[v74 SHM] Shared memory cleaned up")
            except Exception:
                pass
        elif features_path:
            try:
                os.remove(features_path)
            except Exception:
                pass
        # v74.1: Clean up serialized grid file
        try:
            os.remove(grid_path)
        except Exception:
            pass
        for res in all_results:
            avg_odds_minus_1 = res['avg_odds'] - 1.0
            res['odds_efficiency'] = avg_odds_minus_1 / res['max_consecutive_losses'] if res['max_consecutive_losses'] > 0 else 999.0
            res['is_rejected'] = res['max_drawdown'] > 5 * avg_odds_minus_1 if avg_odds_minus_1 > 0 else True
        self.results = all_results
        # BIG DATA OPT: Force garbage collection to free memory from pool building
        import gc
        gc.collect()
        end_time = time.time()
        elapsed = end_time - start_time
        n_passed = len(self.results)
        n_skipped = skipped
        print(f"[GRID] SUMMARY: {n_passed} passed, {n_skipped} skipped during pool build (pool_empty={skipped_pool_empty}, min_matches={skipped_min_matches})")
        print(f"[DONE] Grid evaluation finished at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        print(f"[TIME] Elapsed: {elapsed:.2f} seconds ({elapsed/60:.2f} minutes)")
        print(f"Done. {len(self.results)} variants passed min_bets={min_bets}.")
        return pd.DataFrame([{k: v for k, v in r.items() if k != 'bets_df'} for r in self.results])

    def run_grid(self, min_bets=100, max_workers=None):
        self.results = []
        return self._run_grid_core(min_bets=min_bets, max_workers=max_workers)

    def _rank_and_select_core(self, top_n=50, roi_weight=0.35, sharpe_weight=0.30, win_rate_weight=0.20, odds_efficiency_weight=0.15):
        if len(self.results) == 0:
            return [], pd.DataFrame()

        df = pd.DataFrame([{k: v for k, v in r.items() if k != 'bets_df'} for r in self.results])

        # ═══════════════════════════════════════════════════════════════════════
        # v74.10 GUARDRAIL: Abort immediately if ranking depends on missing cols
        # ═══════════════════════════════════════════════════════════════════════
        required_cols = {
            'v27':  ['roi', 'sharpe_profit_per_dd', 'win_rate', 'odds_efficiency'],
            'v31':  ['total_profit', 'sharpe_profit_per_dd'],
            'v33':  ['profit_per_bet', 'sharpe_profit_per_dd', 'win_rate', 'avg_odds'],
            'v39':  ['profit_per_bet', 'win_rate', 'avg_odds', 'n_bets'],
            'v69':  ['profit_per_bet', 'win_rate', 'avg_odds', 'n_bets'],
        }
        mode_cols = required_cols.get(RANKING_MODE, [])
        missing = [c for c in mode_cols if c not in df.columns]
        if missing:
            raise RuntimeError(
                f"[RANKING GUARDRAIL] RANKING_MODE='{RANKING_MODE}' requires missing columns: {missing}. "
                f"Available columns: {sorted(df.columns.tolist())}. Aborting before sort."
            )
        # ═══════════════════════════════════════════════════════════════════════

        # ── IMPROVEMENT #1: Auto-cull Adapted variants before ranking ──
        if 'volume_alert' in df.columns and 'drift_alert' in df.columns:
            pre_cull = len(df)
            df = df[~((df['volume_alert'] == 'Adapted') | (df['drift_alert'] == 'Adapted'))]
            culled = pre_cull - len(df)
            if culled > 0:
                print(f"[CULL] Auto-removed {culled} 'Adapted' variants before ranking.")

        df['roi_score'] = 0.0
        df['sharpe_score'] = 0.0
        df['win_rate_score'] = 0.0
        df['odds_efficiency_score'] = 0.0

        for sname in df['strategy'].unique():
            mask = df['strategy'] == sname
            sub = df[mask]

            r_min, r_max = sub['roi'].min(), sub['roi'].max()
            s_min, s_max = sub['sharpe_profit_per_dd'].min(), sub['sharpe_profit_per_dd'].max()
            w_min, w_max = sub['win_rate'].min(), sub['win_rate'].max()
            oe_min, oe_max = sub['odds_efficiency'].min(), sub['odds_efficiency'].max()

            if r_max > r_min:
                df.loc[mask, 'roi_score'] = (sub['roi'] - r_min) / (r_max - r_min)
            if s_max > s_min:
                df.loc[mask, 'sharpe_score'] = (sub['sharpe_profit_per_dd'] - s_min) / (s_max - s_min)
            if w_max > w_min:
                df.loc[mask, 'win_rate_score'] = (sub['win_rate'] - w_min) / (w_max - w_min)
            if oe_max > oe_min:
                df.loc[mask, 'odds_efficiency_score'] = (sub['odds_efficiency'] - oe_min) / (oe_max - oe_min)

        df['composite_score'] = (
            (roi_weight * df['roi_score']) +
            (sharpe_weight * df['sharpe_score']) +
            (win_rate_weight * df['win_rate_score']) +
            (odds_efficiency_weight * df['odds_efficiency_score'])
        )

        # ── RANKING MODE SWITCH ──────────────────────────────────────────
        if RANKING_MODE == 'v31':
            # v31 profit-first: total profit primary, Sharpe secondary, no win_rate penalty
            df['profit_score'] = 0.0
            df['sharpe_score_v31'] = 0.0
            for sname in df['strategy'].unique():
                mask = df['strategy'] == sname
                sub = df[mask]
                p_min, p_max = sub['total_profit'].min(), sub['total_profit'].max()
                s_min, s_max = sub['sharpe_profit_per_dd'].min(), sub['sharpe_profit_per_dd'].max()
                if p_max > p_min:
                    df.loc[mask, 'profit_score'] = (sub['total_profit'] - p_min) / (p_max - p_min)
                if s_max > s_min:
                    df.loc[mask, 'sharpe_score_v31'] = (sub['sharpe_profit_per_dd'] - s_min) / (s_max - s_min)
            df['ranking_score'] = (0.60 * df['profit_score']) + (0.40 * df['sharpe_score_v31'])
            print(f"[RANK] v31 profit-first mode | profit_weight=0.60 | sharpe_weight=0.40")
        elif RANKING_MODE == 'v33':
            # v33 HYBRID: configurable weights — profit / sharpe / consistency
            # Consistency = win_rate relative to strategy's survival floor
            w_profit, w_sharpe, w_consistency = _resolve_chosen_weights()
            df['profit_score_v33'] = 0.0
            df['sharpe_score_v33'] = 0.0
            df['consistency_score_v33'] = 0.0
            for sname in df['strategy'].unique():
                mask = df['strategy'] == sname
                sub = df[mask]
                # Pillar 1: profit_per_bet normalized within strategy
                ppb_min, ppb_max = sub['profit_per_bet'].min(), sub['profit_per_bet'].max()
                if ppb_max > ppb_min:
                    df.loc[mask, 'profit_score_v33'] = (sub['profit_per_bet'] - ppb_min) / (ppb_max - ppb_min)
                # Pillar 2: Sharpe normalized within strategy
                s_min, s_max = sub['sharpe_profit_per_dd'].min(), sub['sharpe_profit_per_dd'].max()
                if s_max > s_min:
                    df.loc[mask, 'sharpe_score_v33'] = (sub['sharpe_profit_per_dd'] - s_min) / (s_max - s_min)
                # Pillar 3: V11.2 OPT — vectorized consistency score (no iterrows)
                _floors = sub['avg_odds'].apply(lambda o: WinRateGate.get_floor('odds', sname, o))
                _cons   = np.where(_floors > 0,
                            np.maximum((sub['win_rate'].values - _floors.values) / _floors.values, -1.0),
                            0.0)
                df.loc[mask, 'consistency_score_v33'] = _cons
            df['ranking_score'] = (
                (w_profit * df['profit_score_v33']) +
                (w_sharpe * df['sharpe_score_v33']) +
                (w_consistency * df['consistency_score_v33'].clip(lower=-1.0))
            )
            print(f"[RANK] v33 HYBRID mode | profit={w_profit:.2f} | sharpe={w_sharpe:.2f} | consistency={w_consistency:.2f} | preset={CHOSEN_STRATEGIES_WEIGHT_MODE}")
        elif RANKING_MODE == 'v27':
            # v27 BALANCED QUAD: 35% roi / 30% sharpe / 20% win_rate / 15% odds_efficiency
            # Proven across many historical backtests — different weighting surfaces different strategies.
            df['roi_score_v27'] = 0.0
            df['sharpe_score_v27'] = 0.0
            df['wr_score_v27'] = 0.0
            df['oe_score_v27'] = 0.0
            for sname in df['strategy'].unique():
                mask = df['strategy'] == sname
                sub = df[mask]
                roi_min, roi_max = sub['roi'].min(), sub['roi'].max()
                if roi_max > roi_min:
                    df.loc[mask, 'roi_score_v27'] = (sub['roi'] - roi_min) / (roi_max - roi_min)
                s_min, s_max = sub['sharpe_profit_per_dd'].min(), sub['sharpe_profit_per_dd'].max()
                if s_max > s_min:
                    df.loc[mask, 'sharpe_score_v27'] = (sub['sharpe_profit_per_dd'] - s_min) / (s_max - s_min)
                wr_min, wr_max = sub['win_rate'].min(), sub['win_rate'].max()
                if wr_max > wr_min:
                    df.loc[mask, 'wr_score_v27'] = (sub['win_rate'] - wr_min) / (wr_max - wr_min)
                oe_min, oe_max = sub['odds_efficiency'].min(), sub['odds_efficiency'].max()
                if oe_max > oe_min:
                    df.loc[mask, 'oe_score_v27'] = (sub['odds_efficiency'] - oe_min) / (oe_max - oe_min)
            df['ranking_score'] = (
                0.35 * df['roi_score_v27'] +
                0.30 * df['sharpe_score_v27'] +
                0.20 * df['wr_score_v27'] +
                0.15 * df['oe_score_v27']
            )
            print(f"[RANK] v27 balanced-quad mode | roi=0.35 | sharpe=0.30 | wr=0.20 | oe=0.15")
        elif RANKING_MODE == 'v39':
            # v39 QUALITY-FIRST: PPB * (WR/100) * ln(1+avg_odds) / ln(1+n_bets/100)
            # Rewards SELECTIVITY — strategies with fewer but higher-quality bets score better.
            # Clips PPB to 0 (unlike v69 which allows negative) so only profitable strategies rank.
            df['quality_score_v39'] = (
                df['profit_per_bet'].clip(lower=0.0) *
                (df['win_rate'] / 100.0).clip(lower=0.001) *
                np.log1p(df['avg_odds'].clip(lower=1.0)) /
                np.log1p(df['n_bets'] / 100.0).clip(lower=0.001)
            )
            df['ranking_score'] = df['quality_score_v39']
            print(f"[RANK] v39 quality-first mode (selectivity rewards high PPB + high WR + high odds, penalizes volume)")
        else:
            # v69 quality_score (multiplicative — strict)
            df['quality_score'] = (
                df['profit_per_bet'].clip(lower=-999) *
                (df['win_rate'] / 100.0).clip(lower=0.001) *
                np.log1p(df['avg_odds'].clip(lower=1.0)) /
                np.log1p(df['n_bets'] / 100.0)
            )
            df['ranking_score'] = df['quality_score']
            print(f"[RANK] v69 quality_score mode (strict)")
        # ── END RANKING MODE SWITCH ────────────────────────────────────────

        # ═══════════════════════════════════════════════════════════════════
        # MAX DRAWDOWN BONUS — applied after ALL ranking modes
        # ═══════════════════════════════════════════════════════════════════
        # When max_drawdown < avg_odds it means a single win fully recovers
        # the worst losing streak. That is exceptional structural robustness —
        # the strategy is self-healing. When this holds in BOTH IS and OOS the
        # property is real and stable, not a lucky artefact of one data split.
        #
        # Bonus tiers:
        #   IS only:       +20% score boost   (good but unconfirmed in OOS)
        #   IS + OOS both: +50% score boost   (confirmed structural property)
        # ═══════════════════════════════════════════════════════════════════
        _is_dd   = df.get('max_drawdown',     pd.Series(999.0, index=df.index)).fillna(999.0)
        _oos_dd  = df.get('oos_max_drawdown', pd.Series(999.0, index=df.index)).fillna(999.0)
        _avg_o   = df['avg_odds'].fillna(1.0)

        _dd_bonus_is      = (_is_dd  < _avg_o)
        _dd_bonus_oos     = (_oos_dd < _avg_o)
        _dd_bonus_both    = _dd_bonus_is & _dd_bonus_oos

        df['dd_bonus'] = 1.0
        df.loc[_dd_bonus_is,   'dd_bonus'] = 1.20   # IS only:       +20%
        df.loc[_dd_bonus_both, 'dd_bonus'] = 1.50   # IS + OOS both: +50%

        df['ranking_score'] = df['ranking_score'] * df['dd_bonus']

        _bonus_is_ct   = int(_dd_bonus_is.sum())
        _bonus_both_ct = int(_dd_bonus_both.sum())
        if _bonus_both_ct > 0 or _bonus_is_ct > 0:
            print(f"[RANK] DD Bonus applied: {_bonus_both_ct} strategies with max_dd < avg_odds in BOTH IS+OOS (+50%), "
                  f"{_bonus_is_ct - _bonus_both_ct} in IS only (+20%)")
        # ── END DD BONUS ────────────────────────────────────────────────────

        df.loc[df['p_value_ttest'] >= 0.05, 'ranking_score'] *= 0.01
        df.loc[df['n_bets'] < 100, 'ranking_score'] *= 0.01
        df.loc[df['is_rejected'] == True, 'ranking_score'] *= 0.01

        df_sorted = df.sort_values('ranking_score', ascending=False).reset_index(drop=True)

        # V11.2 OPT: vectorized deduplication — no iterrows
        _pm  = df_sorted.get('prematch_threshold',       pd.Series('N/A', index=df_sorted.index)).fillna('N/A').astype(str)
        _ps  = df_sorted.get('prematch_spread_threshold', pd.Series('N/A', index=df_sorted.index)).fillna('N/A').astype(str)
        _fp_df = (
            df_sorted['strategy'].astype(str) + '|' +
            df_sorted['league'].astype(str)   + '|' +
            _pm + '|' + _ps + '|' +
            df_sorted['n_bets'].astype(str)   + '|' +
            df_sorted['wins'].astype(str)     + '|' +
            df_sorted['losses'].astype(str)   + '|' +
            df_sorted['total_profit'].round(2).astype(str)         + '|' +
            df_sorted['win_rate'].round(2).astype(str)             + '|' +
            df_sorted['avg_odds'].round(2).astype(str)             + '|' +
            df_sorted['max_drawdown'].round(2).astype(str)         + '|' +
            df_sorted['max_consecutive_losses'].astype(str)        + '|' +
            df_sorted['sharpe_profit_per_dd'].round(2).astype(str) + '|' +
            df_sorted['odds_efficiency'].round(4).astype(str)      + '|' +
            df_sorted['p_value_ttest'].round(4).astype(str)
        )
        _seen_mask = ~_fp_df.duplicated(keep='first')
        duplicates_skipped = int((~_seen_mask).sum())
        # Build top_ids as variant_id list, capped at top_n, matching original behaviour
        _deduped = df_sorted[_seen_mask]
        top_ids = _deduped['variant_id'].iloc[:top_n].tolist()

        seen_fingerprints = set()  # kept for any downstream references
        _dedup_done = True
        if False:  # original loop preserved for reference — never executes
         for idx, row in df_sorted.iterrows():
            fp = (
                row['strategy'],
                row['league'],
                row.get('prematch_threshold', 'N/A'),
                row.get('prematch_spread_threshold', 'N/A'),
                row['n_bets'],
                row['wins'],
                row['losses'],
                round(row['total_profit'], 2),
                round(row['win_rate'], 2),
                round(row['avg_odds'], 2),
                round(row['max_drawdown'], 2),
                row['max_consecutive_losses'],
                round(row['sharpe_profit_per_dd'], 2),
                round(row['odds_efficiency'], 4),
                round(row['p_value_ttest'], 4),
            )
            # (dead code — vectorized above; kept for structure)
            if fp not in seen_fingerprints:
                seen_fingerprints.add(fp)
                # top_ids.append(row['variant_id'])  # handled vectorized above
            else:
                pass
            if len(top_ids) >= top_n:
                break

        if duplicates_skipped > 0:
            print(f"[DEDUP] Skipped {duplicates_skipped} duplicate variants with identical metrics.")

        # V11 DIAGNOSTIC: Show v11 strategies after ranking gates, before top_n truncation
        v11_strategies = ['Loser_SustainedOdds', 'Loser_SustainedOdds_RoleReversal',
                          'Loser_PlayerExperience', 'Loser_Form5', 'Loser_Form10',
                          'Loser_Form20', 'Loser_WR_Asymmetry', 'Loser_DailyForm',
                          'SustOdds_PlayerWR']
        print("[V11 DIAGNOSTIC] After ranking gates, before top_n truncation:")
        for s in v11_strategies:
            s_in_results = [r for r in self.results if r.get('strategy') == s]
            s_ranked = df_sorted[df_sorted['strategy'] == s] if 'strategy' in df_sorted.columns else []
            if len(s_ranked) > 0:
                best_idx = s_ranked['ranking_score'].idxmax()
                best = s_ranked.loc[best_idx]
                in_top_n = best['variant_id'] in top_ids
                print(f"[V11 DIAGNOSTIC]   {s}: ranked={len(s_ranked)} | best_score={best['ranking_score']:.4f} | in_top_{top_n}={in_top_n} | n_bets={best.get('n_bets',0)} | p={best.get('p_value_ttest',1):.4f} | rejected={best.get('is_rejected',False)}")
            elif s_in_results:
                print(f"[V11 DIAGNOSTIC]   {s}: {len(s_in_results)} raw results but ZERO after ranking gates (all killed by p>=0.05 or n_bets<100 or is_rejected)")
            else:
                print(f"[V11 DIAGNOSTIC]   {s}: No raw results (failed at pool/worker level)")

        selected = [r for r in self.results if r['variant_id'] in top_ids]
        score_map = dict(zip(df_sorted['variant_id'], df_sorted['ranking_score']))
        selected.sort(key=lambda x: score_map.get(x['variant_id'], 0), reverse=True)
        return selected, df_sorted

    def rank_and_select(self, top_n=50, roi_weight=0.35, sharpe_weight=0.30, win_rate_weight=0.20, odds_efficiency_weight=0.15):
        selected, df_sorted = self._rank_and_select_core(top_n, roi_weight, sharpe_weight, win_rate_weight, odds_efficiency_weight)
        for r in selected:
            if 'bets_df' not in r or len(r.get('bets_df', pd.DataFrame())) == 0:
                strategy_name = r['strategy']
                cfg = self.grid[strategy_name]
                threshold = r['odds_threshold']
                time_rule = r.get('time_rule_raw')
                if time_rule is None:
                    time_rule = ast.literal_eval(r['time_rule'])
                league_filter = r['league'] if r['league'] != 'All' else None
                pm = r.get('prematch_threshold')
                ps = r.get('prematch_spread_threshold')
                if pm == 'N/A': pm = None
                if ps == 'N/A': ps = None
                pool = self._build_pool(strategy_name, time_rule, league_filter, cfg=cfg)
                if pool is not None and len(pool) > 0:
                    enriched = self._evaluate_variant_fast(strategy_name, cfg, threshold, time_rule, league_filter, pool, prematch_threshold=pm, prematch_spread_threshold=ps)
                    if enriched:
                        r.update({k: v for k, v in enriched.items() if k != 'variant_id'})
            daily = self._daily_metrics(r['bets_df'])
            r.update(daily)
        return selected, df_sorted

    def _split_features_chronological(self, split_pct=0.5):
        match_ts = self.features.groupby('match_id')['first_observed_timestamp'].min()
        sorted_matches = match_ts.sort_values().index.tolist()
        split_idx = int(len(sorted_matches) * split_pct)
        is_matches = sorted_matches[:split_idx]
        oos_matches = sorted_matches[split_idx:]
        features_is = self.features[self.features['match_id'].isin(is_matches)].copy()
        features_oos = self.features[self.features['match_id'].isin(oos_matches)].copy()
        return features_is, features_oos, is_matches, oos_matches

    def _evaluate_variant_on_features(self, strategy_name, cfg, threshold, time_rule, league_filter, features_subset, min_bets=100, prematch_threshold=None, prematch_spread_threshold=None):
        saved_features = self.features
        self.features = features_subset
        try:
            pool = self._build_pool(strategy_name, time_rule, league_filter, cfg=cfg)   # v22 FIX: apply the trial cfg's extra_mask
            if pool is None or len(pool) == 0:
                return None
            res = self._evaluate_variant_fast(strategy_name, cfg, threshold, time_rule, league_filter, pool, prematch_threshold=prematch_threshold, prematch_spread_threshold=prematch_spread_threshold)
            if res and res['n_bets'] >= min_bets:
                return res
            elif res:
                print(f"[SKIP] {strategy_name} | {league_filter or 'All'} | PM={prematch_threshold} PS={prematch_spread_threshold} | threshold={threshold} | REASON: Too few bets ({res['n_bets']} < {min_bets})")
            return None
        finally:
            self.features = saved_features

    def run_grid_with_oos(self, min_bets=100, max_workers=None, split_pct=0.5, top_n=50):
        original_features = self.features.copy()
        total_matches = original_features['match_id'].nunique()
        if total_matches < 2 * min_bets:
            print(f"[WARN] Only {total_matches} unique matches. OOS split may produce insufficient sample size.")

        features_is, features_oos, is_matches, oos_matches = self._split_features_chronological(split_pct)
        self._features_is = features_is
        self._features_oos = features_oos
        print(f"[OOS] Split: {len(is_matches)} matches IS ({split_pct*100:.0f}%), {len(oos_matches)} matches OOS ({(1-split_pct)*100:.0f}%)")

        # Phase 1: In-Sample discovery
        self.features = features_is
        self.results = []
        print("[OOS] === IN-SAMPLE DISCOVERY ===")
        self._run_grid_core(min_bets=min_bets, max_workers=max_workers)
        selected_is, _ = self._rank_and_select_core(top_n=top_n)

        if len(selected_is) == 0:
            print("[OOS] No variants passed IS selection.")
            self.features = original_features
            return pd.DataFrame()

        print(f"[OOS] {len(selected_is)} variants selected from IS. Validating on OOS...")

        # Phase 2: Out-of-Sample validation + FULL operational
        # v16 OPT: the OOS + full-sample base pool depends only on
        # (strategy, time_rule, league) — NOT on threshold / prematch. The old loop
        # rebuilt both full-frame pools for every one of the ~top_n variants. We now
        # build each base pool ONCE per distinct group, evaluate every variant that
        # shares it, and free the pools before the next group (so at most one OOS +
        # one FULL pool is held at a time — memory-safe on big data). Variants are
        # reassembled in the original ranking order so downstream (e.g. Phase-4
        # top-20 selection from engine.results) is unchanged.
        from collections import defaultdict as _defaultdict
        _groups = _defaultdict(list)
        for _vi, variant in enumerate(selected_is):
            sname = variant['strategy']
            _tr = variant.get('time_rule_raw')
            if _tr is None:
                _tr = ast.literal_eval(variant['time_rule'])
            _lf = variant['league'] if variant['league'] != 'All' else None
            _groups[(sname, str(_tr), variant['league'])].append((_vi, variant, _tr, _lf))

        _eval_by_idx = {}   # original index -> (oos_res, full_res)
        _saved_feats = self.features
        for _key, _members in _groups.items():
            _sname = _members[0][1]['strategy']
            _cfg = self.grid[_sname]
            _tr = _members[0][2]
            _lf = _members[0][3]
            # Build the two base pools ONCE for this group.
            self.features = features_oos
            _oos_pool = self._build_pool(_sname, _tr, _lf, cfg=_cfg)
            self.features = original_features
            _full_pool = self._build_pool(_sname, _tr, _lf, cfg=_cfg)
            self.features = _saved_feats
            for _vi, variant, _vtr, _vlf in _members:
                threshold = variant['odds_threshold']
                pm = variant.get('prematch_threshold')
                ps = variant.get('prematch_spread_threshold')
                if isinstance(pm, str) and pm == 'N/A':
                    pm = None
                if isinstance(ps, str) and ps == 'N/A':
                    ps = None
                oos_res = None
                if _oos_pool is not None and len(_oos_pool) > 0:
                    _r = self._evaluate_variant_fast(_sname, _cfg, threshold, _vtr, _vlf, _oos_pool,
                                                     prematch_threshold=pm, prematch_spread_threshold=ps)
                    if _r is not None and _r['n_bets'] >= min_bets:
                        oos_res = _r
                full_res = None
                if _full_pool is not None and len(_full_pool) > 0:
                    _r = self._evaluate_variant_fast(_sname, _cfg, threshold, _vtr, _vlf, _full_pool,
                                                     prematch_threshold=pm, prematch_spread_threshold=ps)
                    if _r is not None and _r['n_bets'] >= min_bets:
                        full_res = _r
                _eval_by_idx[_vi] = (oos_res, full_res)
            del _oos_pool, _full_pool
        self.features = original_features

        merged_results = []
        for _vi, variant in enumerate(selected_is):
            strategy_name = variant['strategy']
            cfg = self.grid[strategy_name]
            threshold = variant['odds_threshold']
            time_rule = variant.get('time_rule_raw')
            if time_rule is None:
                time_rule = ast.literal_eval(variant['time_rule'])
            league_filter = variant['league'] if variant['league'] != 'All' else None

            oos_res, full_res = _eval_by_idx.get(_vi, (None, None))
            if oos_res is None or full_res is None:
                continue

            merged = full_res.copy()
            merged['strategy'] = strategy_name
            merged['league'] = variant['league']
            merged['odds_threshold'] = threshold
            merged['time_rule'] = str(time_rule)
            merged['time_rule_raw'] = time_rule
            merged['variant_id'] = variant['variant_id']

            is_keys = ['n_bets', 'wins', 'losses', 'win_rate', 'total_profit', 'profit_per_bet', 'roi',
                       'avg_odds', 'max_drawdown', 'max_consecutive_losses',
                       'sharpe_profit_per_dd', 'sharpe_traditional', 'p_value_ttest',
                       'implied_probability', 'actual_probability', 'odds_efficiency']
            for k in is_keys:
                merged[f'is_{k}'] = variant.get(k, 0)
                merged[f'oos_{k}'] = oos_res.get(k, 0)

            is_profit = variant.get('total_profit', 0)
            oos_profit = oos_res.get('total_profit', 0)
            is_sharpe = variant.get('sharpe_profit_per_dd', 0)
            oos_sharpe = oos_res.get('sharpe_profit_per_dd', 0)
            is_pval = variant.get('p_value_ttest', 1)
            oos_pval = oos_res.get('p_value_ttest', 1)

            merged['stability_ratio'] = round(oos_profit / is_profit, 2) if is_profit != 0 else 0.0
            merged['sharpe_decay'] = round((is_sharpe - oos_sharpe) / is_sharpe, 2) if is_sharpe != 0 else 1.0
            merged['oos_pass'] = (merged['stability_ratio'] >= 0.30) and (oos_pval < 0.05) and (is_pval < 0.05)

            is_eligible = variant.get('total_eligible', 0)
            oos_eligible = oos_res.get('total_eligible', 0)
            is_triggered = variant.get('total_triggered', 0)
            oos_triggered = oos_res.get('total_triggered', 0)
            is_rate = (is_triggered / is_eligible * 100) if is_eligible > 0 else 0.0
            oos_rate = (oos_triggered / oos_eligible * 100) if oos_eligible > 0 else 0.0
            rate_ratio = round(oos_rate / is_rate, 2) if is_rate > 0 else 0.0

            merged['is_total_eligible'] = is_eligible
            merged['is_total_triggered'] = is_triggered
            merged['is_trigger_rate'] = round(is_rate, 2)
            merged['oos_total_eligible'] = oos_eligible
            merged['oos_total_triggered'] = oos_triggered
            merged['oos_trigger_rate'] = round(oos_rate, 2)
            merged['rate_ratio'] = rate_ratio
            merged['drift_alert'] = 'Stable' if rate_ratio >= 0.85 else ('Caution' if rate_ratio >= 0.70 else 'Adapted')

            eligible_count_ratio = round(oos_eligible / is_eligible, 2) if is_eligible > 0 else 0.0
            eligible_change_pct = round((oos_eligible - is_eligible) / is_eligible * 100, 1) if is_eligible > 0 else 0.0
            merged['eligible_count_ratio'] = eligible_count_ratio
            merged['eligible_change_pct'] = eligible_change_pct
            merged['volume_alert'] = 'Stable' if eligible_count_ratio >= 0.85 else ('Caution' if eligible_count_ratio >= 0.70 else 'Adapted')

            daily = self._daily_metrics(merged['bets_df'])
            merged.update(daily)

            # v74.1 FIX: Store WinRateGate verdict in result dict (was only in Excel)
            merged['verdict'] = WinRateGate.verdict(
                'odds', merged['strategy'], merged.get('avg_odds', 0.0),
                merged.get('win_rate', 0.0), merged.get('sharpe_profit_per_dd', 0.0),
                merged.get('oos_pass', False), merged.get('p_value_ttest', 1.0),
                merged.get('volume_alert', 'N/A'), merged.get('drift_alert', 'N/A'),
                merged.get('stability_ratio', 0.0)
            )

            merged_results.append(merged)

        # Drop variants with negative full-sample profit
        merged_results = [r for r in merged_results if r.get('total_profit', 0) >= 0]

        self.features = original_features
        self.results = merged_results

        n_pass = sum(1 for r in merged_results if r.get('oos_pass', False))
        print(f"[OOS] === VALIDATION COMPLETE ===")
        print(f"[OOS] {len(merged_results)} profit-positive variants evaluated on OOS.")
        print(f"[OOS] {n_pass} variants passed stability filter (ratio>=0.30, p<0.05 on both IS and OOS).")

        return pd.DataFrame([{k: v for k, v in r.items() if k != 'bets_df'} for r in merged_results])


