        c.font = Font(bold=True, size=14, color='FFFFFF')
        c.fill = PatternFill(start_color='1F4788', end_color='1F4788', fill_type='solid')
        c.alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[1].height = 30

        hdrs = [
            'Rank', 'Strategy', 'League', 'Threshold', 'Time_Rule',
            'IS_N_Bets', 'IS_Profit', 'IS_ROI_%', 'IS_Sharpe_DD', 'IS_P_Value',
            'OOS_N_Bets', 'OOS_Profit', 'OOS_ROI_%', 'OOS_Sharpe_DD', 'OOS_P_Value',
            'Stability_Ratio', 'Sharpe_Decay', 'OOS_Pass'
        ]
        for ci, h in enumerate(hdrs, 1):
            cell = ws.cell(row=3, column=ci, value=h)
            cell.font = Font(bold=True, color='FFFFFF', size=10)
            cell.fill = PatternFill(start_color='2C3E50', end_color='2C3E50', fill_type='solid')
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.row_dimensions[3].height = 35

        thin_border = Border(
            left=Side(style='thin'), right=Side(style='thin'),
            top=Side(style='thin'), bottom=Side(style='thin')
        )

        is_sharpe_list = []
        oos_sharpe_list = []
        pass_list = []

        for rank, res in enumerate(self.top, 1):
            row = rank + 3
            m = {k: v for k, v in res.items() if k != 'bets_df'}

            is_sharpe = m.get('is_sharpe_profit_per_dd', 0)
            oos_sharpe = m.get('oos_sharpe_profit_per_dd', 0)
            is_sharpe_list.append(is_sharpe)
            oos_sharpe_list.append(oos_sharpe)
            oos_pass = m.get('oos_pass', False)
            pass_list.append(oos_pass)

            vals = [
                rank, m['strategy'], m['league'], m['odds_threshold'], m['time_rule'],
                m.get('is_n_bets', 0), round(m.get('is_total_profit', 0), 2), round(m.get('is_roi', 0), 2),
                round(is_sharpe, 2), round(m.get('is_p_value_ttest', 1), 4),
                m.get('oos_n_bets', 0), round(m.get('oos_total_profit', 0), 2), round(m.get('oos_roi', 0), 2),
                round(oos_sharpe, 2), round(m.get('oos_p_value_ttest', 1), 4),
                m.get('stability_ratio', 0), m.get('sharpe_decay', 0), 'PASS' if oos_pass else 'FAIL'
            ]
            for col_idx, v in enumerate(vals, 1):
                cell = ws.cell(row=row, column=col_idx, value=v)
                cell.border = thin_border
                cell.alignment = Alignment(horizontal='center')
                if col_idx == 16 and isinstance(v, (int, float)):
                    if v >= 0.70:
                        cell.fill = PatternFill(start_color='C6EFCE', end_color='C6EFCE', fill_type='solid')
                        cell.font = Font(color='006100', bold=True)
                    elif v >= 0.30:
                        cell.fill = PatternFill(start_color='FFEB9C', end_color='FFEB9C', fill_type='solid')
                        cell.font = Font(color='9C5700', bold=True)
                    else:
                        cell.fill = PatternFill(start_color='FFC7CE', end_color='FFC7CE', fill_type='solid')
                        cell.font = Font(color='9C0006', bold=True)
                if col_idx == 18:
                    if v == 'PASS':
                        cell.fill = PatternFill(start_color='C6EFCE', end_color='C6EFCE', fill_type='solid')
                        cell.font = Font(color='006100', bold=True)
                    else:
                        cell.fill = PatternFill(start_color='FFC7CE', end_color='FFC7CE', fill_type='solid')
                        cell.font = Font(color='9C0006', bold=True)

        for ci in range(1, len(hdrs) + 1):
            ws.column_dimensions[get_column_letter(ci)].width = 14
        ws.column_dimensions['B'].width = 18
