    def _create_overlap_matrix_sheet(self, wb):
        """Detect concentration risk: which top variants bet on the same matches."""
        if len(self.top) < 2:
            return

        ws = wb.create_sheet("Overlap_Matrix")
        ws.sheet_properties.tabColor = "F39C12"

        ws.merge_cells('A1:F1')
        c = ws['A1']
        c.value = "STRATEGY OVERLAP MATRIX -- Concentration Risk Detection"
        c.font = Font(bold=True, size=14, color='FFFFFF')
        c.fill = PatternFill(start_color='1F4788', end_color='1F4788', fill_type='solid')
        c.alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[1].height = 30

        ws.merge_cells('A2:F2')
        c2 = ws['A2']
        c2.value = "Overlap = shared match_ids between two variants. High overlap = concentration risk if both lose."
        c2.font = Font(italic=True, size=10)
        c2.alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[2].height = 20

        top_n = min(20, len(self.top))
        variants = []
        for i in range(top_n):
            res = self.top[i]
            bets = res.get('bets_df', pd.DataFrame())
            mids = set(bets['match_id'].astype(str).unique()) if len(bets) > 0 else set()
            variants.append({
                'rank': i + 1,
                'strategy': res['strategy'],
                'league': res['league'],
                'match_ids': mids,
                'n_bets': len(bets)
            })

        hdrs = ['Rank_A', 'Strategy_A', 'League_A', 'Rank_B', 'Strategy_B', 'League_B',
                'Overlap_Count', 'Overlap_%_A', 'Overlap_%_B', 'Risk_Level']
        row = 4
        for ci, h in enumerate(hdrs, 1):
            cell = ws.cell(row=row, column=ci, value=h)
            cell.font = Font(bold=True, color='FFFFFF', size=10)
            cell.fill = PatternFill(start_color='2C3E50', end_color='2C3E50', fill_type='solid')
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.row_dimensions[row].height = 25

        thin_border = Border(
            left=Side(style='thin'), right=Side(style='thin'),
            top=Side(style='thin'), bottom=Side(style='thin')
        )

        for i in range(top_n):
            for j in range(i + 1, top_n):
                va = variants[i]
                vb = variants[j]
                if len(va['match_ids']) == 0 or len(vb['match_ids']) == 0:
                    continue
                overlap = len(va['match_ids'] & vb['match_ids'])
                if overlap == 0:
                    continue
                pct_a = round(overlap / len(va['match_ids']) * 100, 1)
                pct_b = round(overlap / len(vb['match_ids']) * 100, 1)
                max_pct = max(pct_a, pct_b)
                if max_pct > 30:
                    risk = 'HIGH'
                elif max_pct > 15:
                    risk = 'MEDIUM'
                else:
                    risk = 'LOW'

                row += 1
                vals = [
                    va['rank'], va['strategy'], va['league'],
                    vb['rank'], vb['strategy'], vb['league'],
                    overlap, pct_a, pct_b, risk
                ]
                for col_idx, v in enumerate(vals, 1):
                    cell = ws.cell(row=row, column=col_idx, value=v)
                    cell.border = thin_border
                    cell.alignment = Alignment(horizontal='center')
                    if col_idx == 10:
                        if v == 'HIGH':
                            cell.fill = PatternFill(start_color='FFC7CE', end_color='FFC7CE', fill_type='solid')
                            cell.font = Font(color='9C0006', bold=True)
                        elif v == 'MEDIUM':
                            cell.fill = PatternFill(start_color='FFEB9C', end_color='FFEB9C', fill_type='solid')
                            cell.font = Font(color='9C5700', bold=True)
                        elif v == 'LOW':
                            cell.fill = PatternFill(start_color='C6EFCE', end_color='C6EFCE', fill_type='solid')
                            cell.font = Font(color='006100', bold=True)

        for ci in range(1, len(hdrs) + 1):
            ws.column_dimensions[get_column_letter(ci)].width = 12
        ws.column_dimensions['B'].width = 16
        ws.column_dimensions['E'].width = 16

    # ── v69 NEW SHEET: Sensitivity Comparison ──
    def _create_sensitivity_comparison_sheet(self, wb):
        """Compare Zoom-In vs 1D-Sweep vs Pareto vs Weighted per strategy."""
        if not self.sensitivity_comparison:
            return

        ws = wb.create_sheet("Sensitivity_Comparison")
        ws.sheet_properties.tabColor = "9B59B6"

        ws.merge_cells('A1:Q1')
        c = ws['A1']
        c.value = "SENSITIVITY ANALYSIS COMPARISON -- Zoom-In vs 1D-Sweep | Pareto vs Weighted"
        c.font = Font(bold=True, size=14, color='FFFFFF')
        c.fill = PatternFill(start_color='1F4788', end_color='1F4788', fill_type='solid')
        c.alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[1].height = 30

        ws.merge_cells('A2:Q2')
        c2 = ws['A2']
        c2.value = "Auto_Winner = highest IS_Sharpe_DD. Tie-breaker: IS_ROI. Green = winner per strategy."
        c2.font = Font(italic=True, size=10)
        c2.alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[2].height = 20

        hdrs = [
            'Rank', 'Strategy', 'Approach', 'Scoring',
            'Col1_Thresh', 'Col2_Thresh',
            'IS_N_Bets', 'IS_WinRate', 'IS_ROI', 'IS_Sharpe_DD', 'IS_MaxLoss', 'IS_PValue',
            'Auto_Winner', 'Notes'
        ]
        row = 4
        for ci, h in enumerate(hdrs, 1):
            cell = ws.cell(row=row, column=ci, value=h)
            cell.font = Font(bold=True, color='FFFFFF', size=10)
            cell.fill = PatternFill(start_color='2C3E50', end_color='2C3E50', fill_type='solid')
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.row_dimensions[row].height = 30

        thin_border = Border(
            left=Side(style='thin'), right=Side(style='thin'),
            top=Side(style='thin'), bottom=Side(style='thin')
        )

        # Group by strategy
        from collections import defaultdict
        grouped = defaultdict(list)
        for r in self.sensitivity_comparison:
            grouped[r['strategy']].append(r)

        rank = 0
        for sname in sorted(grouped.keys()):
            entries = grouped[sname]
            # Find winner
            winner = max(entries, key=lambda r: (r.get('sharpe_profit_per_dd', 0), r.get('roi', 0)))
            for r in entries:
                rank += 1
                row += 1
                is_winner = (r is winner)
                vals = [
                    rank, r['strategy'], r['approach'], r['scoring'],
                    round(r['col1_thresh'], 2), round(r['col2_thresh'], 2),
                    r['n_bets'], round(r['win_rate'], 2), round(r['roi'], 2),
                    round(r['sharpe_profit_per_dd'], 2), r['max_consecutive_losses'],
                    round(r['p_value_ttest'], 4),
                    'YES' if is_winner else 'NO',
                    'Winner' if is_winner else ''
                ]
                for col_idx, v in enumerate(vals, 1):
                    cell = ws.cell(row=row, column=col_idx, value=v)
                    cell.border = thin_border
                    cell.alignment = Alignment(horizontal='center')
                    if is_winner:
                        cell.fill = PatternFill(start_color='C6EFCE', end_color='C6EFCE', fill_type='solid')
                        if col_idx == 13:
                            cell.font = Font(color='006100', bold=True)

        for ci in range(1, len(hdrs) + 1):
            ws.column_dimensions[get_column_letter(ci)].width = 14
        ws.column_dimensions['B'].width = 18
        ws.column_dimensions['E'].width = 14
        ws.column_dimensions['F'].width = 14
        ws.column_dimensions['N'].width = 12
        ws.column_dimensions['O'].width = 20

    def _get_active_conditions_meta(self, strategy_name):
        """Helper for scheduler sheet -- returns compatible conditions and description."""
        compatible = STRATEGY_COMPATIBLE_CONDITIONS.get(strategy_name, [])
        desc = EXTRA_MASK_DESC.get(strategy_name, '')
        return compatible, desc

