    def _generate_discovery_txt(self, discovered, excel_path):
        """Auto-generate copy-paste guide for all OOS-passed discoveries."""
        import pandas as pd
        if not discovered:
            return

        ts = pd.Timestamp.now().strftime('%Y-%m-%d %H:%M:%S')
        lines = [
            "=" * 80,
            "LAZARUS DSN -- DISCOVERED OOS-PASSED CONDITIONS",
            "Auto-generated copy-paste guide for STRATEGY_GRID update",
            "Generated: " + ts,
            "=" * 80,
            "",
            "VALIDATION GATE APPLIED",
            "-" * 40,
            "* Only variants with OOS_Pass = TRUE are listed below",
            "* Criteria: Stability Ratio >= 0.30, p-value < 0.05 on BOTH IS and OOS",
            "",
            "INSTRUCTIONS",
            "-" * 40,
            "1. Locate the strategy name in your STRATEGY_GRID dictionary",
            "2. Add the DISCOVERED conditions to your existing extra_mask using &",
            "3. Do NOT remove existing base logic -- only append",
            "4. Re-run the fixed grid to lock in the improvement",
            "",
        ]

        passed = [d for d in discovered if d.get('oos_pass')]

        for rank, d in enumerate(passed, 1):
            strategy = d.get('strategy', 'Unknown')
            added = d.get('discovered_conditions', [])
            if isinstance(added, str):
                added = [a.strip() for a in added.split(',') if a.strip()]

            lines.append("=" * 80)
            lines.append("DISCOVERY #" + str(rank) + " -- " + strategy)
            lines.append("=" * 80)
            lines.append("Added Condition(s):  " + (', '.join(added) if added else 'None'))
            lines.append("")
            lines.append("Condition Lambdas:")

            for cond in added:
                code = CONDITION_CODE.get(cond, "# " + cond + " -- see CONDITION_POOL")
                lines.append("    " + code)

            lines.append("")
            lines.append("Copy-Paste Extra_Mask (append to existing base with &):")
            lines.append("    '" + strategy + "': {")
            lines.append("        ...")
            lines.append("        'extra_mask': lambda f: (")
            lines.append("            YOUR_EXISTING_BASE_MASK &")

            for i, cond in enumerate(added):
                code = CONDITION_CODE.get(cond, "# " + cond)
                if i == len(added) - 1:
                    lines.append("            " + code + "  # <-- DISCOVERED")
                else:
                    lines.append("            " + code + " &  # <-- DISCOVERED")

            lines.append("        ),")
            lines.append("        ...")
            lines.append("    },")
            lines.append("")
            lines.append("OOS Validation Proof:")
            lines.append("    Full_Sharpe:  " + str(round(d.get('sharpe_profit_per_dd', 0), 2)))
            lines.append("    IS_Sharpe:    " + str(round(d.get('is_sharpe_profit_per_dd', 0), 2)))
            lines.append("    OOS_Sharpe:   " + str(round(d.get('oos_sharpe_profit_per_dd', 0), 2)))
            lines.append("    Ratio:        " + str(round(d.get('stability_ratio', 0), 2)))
            lines.append("    Verdict:      PASS")
            lines.append("")

        lines.append("=" * 80)
        lines.append("SUMMARY TABLE -- ALL OOS-PASSED DISCOVERIES")
        lines.append("=" * 80)
        lines.append("")
        lines.append("Rank  Strategy            Added Conditions                OOS_Sharpe  Ratio  Action")
        lines.append("-" * 80)

        for rank, d in enumerate(passed, 1):
            strategy = d.get('strategy', 'Unknown')
            added = d.get('discovered_conditions', [])
            if isinstance(added, str):
                added = [a.strip() for a in added.split(',') if a.strip()]
            oos_sharpe = d.get('oos_sharpe_profit_per_dd', 0)
            ratio = d.get('stability_ratio', 0)
            cond_str = ', '.join(added) if added else 'None'
            row = f"{rank:<6}{strategy:<20}{cond_str:<35}{oos_sharpe:<12.2f}{ratio:<8.2f}ADD"
            lines.append(row)

        lines.append("")
        lines.append("NOTE: All entries above have Ratio > 1.0, meaning OOS outperformed IS.")
        lines.append("This is the strongest possible validation signal -- conditions are robust.")
        lines.append("")
        lines.append("=" * 80)
        lines.append("END OF FILE")
        lines.append("=" * 80)

        txt_path = excel_path.replace('.xlsx', '_Discovery_Guide.txt')
        with open(txt_path, 'w') as f:
            f.write('\n'.join(lines))

        print(f"[TXT] Discovery guide auto-saved: {txt_path}")


    def _create_prematch_config_sheet(self, wb):
        """Audit sheet documenting prematch odds/spread columns, comparators and thresholds per strategy."""
        ws = wb.create_sheet("Prematch_Config")
        ws.sheet_properties.tabColor = "2980B9"

        headers = ['Strategy', 'PM_Odds_Col', 'PM_Comparator', 'PM_Thresholds',
                   'PS_Col', 'PS_Comparator', 'PS_Thresholds', 'Pool_Empty_Count']
        for col_idx, h in enumerate(headers, 1):
            cell = ws.cell(row=1, column=col_idx, value=h)
            cell.font = Font(bold=True, color='FFFFFF', size=10)
            cell.fill = PatternFill(start_color='2C3E50', end_color='2C3E50', fill_type='solid')
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.row_dimensions[1].height = 30

        row = 2
        for sname, cfg in STRATEGY_GRID.items():
            sens_cfg = SENSITIVITY_STRATEGY_CONFIG.get(sname, {})
            if sens_cfg:
                c1_name, c1_comp, c1_vals = sens_cfg['col1']
                c2_name, c2_comp, c2_vals = sens_cfg['col2']
                ws.cell(row=row, column=1, value=sname)
                ws.cell(row=row, column=2, value=c1_name)
                ws.cell(row=row, column=3, value=c1_comp)
                ws.cell(row=row, column=4, value=str(c1_vals))
                ws.cell(row=row, column=5, value=c2_name)
                ws.cell(row=row, column=6, value=c2_comp)
                ws.cell(row=row, column=7, value=str(c2_vals))
                ws.cell(row=row, column=8, value=0)
                row += 1

        for col in range(1, 9):
            ws.column_dimensions[get_column_letter(col)].width = 25


