        mode = 'explore' if rng.random() < explore_bias else 'exploit'
        sp = rng.choice(sports)
        # ── [v75_61] EXPLOIT MEANS REFINE, NOT RE-ROLL ────────────────────────────────
        # The old "exploit" was a uniform random pick over market/entry combos -- it
