def _summary(led):
    p=led['profit'].values; c=np.cumsum(p); dd=(np.maximum.accumulate(c)-c)
    import itertools
    st=max((sum(1 for _ in grp) for k,grp in itertools.groupby(led['outcome']=='WIN') if not k),default=0)
    rng=np.random.default_rng(1); idx=rng.integers(0,len(p),size=(2000,len(p)))
    return dict(n=len(led), wr=round(100*(led['outcome']=='WIN').mean(),1), odds=round(led['odds'].mean(),2),
        roi=round(100*p.mean(),1), profit=round(p.sum(),0), maxdd=round(dd.max(),1),
        ci_lo=round(float(_laz_pct(100*p[idx].mean(axis=1), 2.5)),1), streak=int(st))

