def lay_favorite_ledger(matches_parquet, comm=0.02, band=None, holdout_only=True, period=None):
    """eFootball LAY-THE-FAVOURITE ledger (exchange-gated strategy). For each match, lay the
    1X2 favourite (lowest back-odds) at its odds O. Lay wins (+1*(1-comm)) if the favourite does
    NOT win; loses -(O-1) (liability) if it does. band=(lo,hi) restricts to a favourite-odds band.
    Returns a per-bet ledger (build_report-compatible)."""
    M=_laz_decat(pd.read_parquet(matches_parquet)).dropna(subset=['h_odds','a_odds','res']).sort_values('ts').reset_index(drop=True)
    per = period if period is not None else ('oos' if holdout_only else 'all')
    if per in ('oos','is'):
        cut=M['ts'].quantile(0.5)
        M = M[M['ts']>cut] if per=='oos' else M[M['ts']<=cut]
    M=M.copy(); M['fav']=np.where(M['h_odds']<=M['a_odds'],'H','A')
    M['fav_odds']=np.minimum(M['h_odds'],M['a_odds'])
    if band is not None: M=M[(M['fav_odds']>=band[0])&(M['fav_odds']<band[1])]
    M=M.sort_values('ts').reset_index(drop=True)
    rows=[]
    for _,r in M.iterrows():
        O=float(r['fav_odds']); fav_won=(r['res']==r['fav']); lay_win=not fav_won
        profit=(1-comm) if lay_win else -(O-1)
        rows.append(dict(match_id=r['mid'], placed=r['ts'], league='eFootball',
            favourite=('Home' if r['fav']=='H' else 'Away'), fav_odds=round(O,2),
            market=f'LAY favourite @ {O:.2f}', odds=round(O,2), stake=1.0,
            liability=round(O-1,2), commission=comm,
            outcome=('WIN' if lay_win else 'LOSS'),
            profit=round(profit,3),
            match_result={'H':'Home','A':'Away','D':'Draw'}[r['res']],
            trigger_reason=f"Laid {'Home' if r['fav']=='H' else 'Away'} favourite @ {O:.2f}; "
                           f"{'favourite lost -> lay WINS' if lay_win else 'favourite won -> lay loses liability'}"))
    return pd.DataFrame(rows)



