def _sec(ws,r,txt,colr=DARK,width=10):
    ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=width)
    c=ws.cell(r,1,txt); c.font=AF(bold=True,size=12,color='FFFFFF'); c.fill=PatternFill('solid',fgColor=colr)
    c.alignment=Alignment(horizontal='left'); return r+1



def _seg(s):
    """Metrics for a ledger slice: n, win%, roi, floor."""
    if s is None or len(s)<25: return None
    pr=s['profit'].to_numpy(float); n=len(pr)
    rng=np.random.default_rng(1); idx=rng.integers(0,n,(600,n))
    return dict(n=n, wr=round(100*(s['outcome']=='WIN').mean(),1), roi=round(100*pr.mean(),1),
                floor=round(float(_laz_pct(100*pr[idx].mean(1), 2.5)),1))


