# ═══════════════════════════════════════════════════════════════════════════════════════
#  v44 SECTION B — 25 NEW STRATEGIES (5 per sport), fusing both engines
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Each new strategy pairs a v43 mechanism with a v15-v40 mechanism. The v43 spec vocabulary
#  is extended with three odds-development keys carried over from v34-v40:
#      price_flat  |price move since match open| <= x     (market inactivity)
#      price_short  price has SHORTENED by >= x           (steam / confirmation)
#      price_drift  price has LENGTHENED by >= x          (contrarian drift-out)
# ═══════════════════════════════════════════════════════════════════════════════════════
"""v44 NEW STRATEGIES — extends the v43 declarative spec vocabulary with odds-development keys
carried over from LazarusEV v34-v40 (price flat / steam / drift), then defines 5 new strategies
per sport that fuse a v43 mechanism with a v40_1 mechanism."""

# ── new spec keys added on top of v43's vocabulary ──
#   price_flat : |(open_odds - live_odds)/open_odds| <= x   (v40_1 market-inactivity)
#   price_short: (open_odds - live_odds)/open_odds >= x     (v40_1 shortening / steam)
#   price_drift: (open_odds - live_odds)/open_odds <= -x    (v40_1 drift-out)
def _pdev(df, oc):
    g = df.groupby('match_id', sort=False)[oc].transform('first')
    return (g - df[oc]) / g

def _apply_pdev(df, m, spec, oc):
    if not any(k in spec for k in ('price_flat','price_short','price_drift')): return m
    r = _pdev(df, oc)
    if spec.get('price_flat')  is not None: m &= r.abs() <= spec['price_flat']
    if spec.get('price_short') is not None: m &= r >= spec['price_short']
    if spec.get('price_drift') is not None: m &= r <= -spec['price_drift']
    return m

def fire_basketball_v44(df, spec):
    """v43 fire_basketball + odds-development keys."""
    base = fire_basketball(df, {k: v for k, v in spec.items()
                                    if k not in ('price_flat','price_short','price_drift','why','name')} | {'name': spec['name']})
    if base is None or not any(k in spec for k in ('price_flat','price_short','price_drift')): return base
    oc = 'total_points_under'
    m = pd.Series(True, index=df.index)
    m = _apply_pdev(df, m, spec, oc)
    keep = df.index[m.fillna(False)]
    out = base[base.index.isin(keep)]
    return out if len(out) else None

def fire_efootball_v44(df, spec):
    base_spec = {k: v for k, v in spec.items() if k not in ('price_flat','price_short','price_drift','fatigue_min','why')}
    base = fire_efootball(df, base_spec)
    if base is None: return None
    oc = {'loser':'loser_odds_rt','draw':'draw_odds','tgu':'total_goals_under'}[spec['market']]
    m = pd.Series(True, index=df.index)
    m = _apply_pdev(df, m, spec, oc)
    if spec.get('fatigue_min') is not None:
        m &= (df['leader_games_24h'].fillna(0) + df['loser_games_24h'].fillna(0)) >= spec['fatigue_min']
    keep = df.index[m.fillna(False)]
    out = base[base.index.isin(keep)]
    return out if len(out) else None

def fire_real_football_v44(df, spec):
    base = fire_real_football(df, {k: v for k, v in spec.items() if k not in ('price_flat','price_short','price_drift','why')})
    if base is None or not any(k in spec for k in ('price_flat','price_short','price_drift')): return base
    m = pd.Series(True, index=df.index)
    m = _apply_pdev(df, m, spec, 'leader_odds_rt')
    keep = df.index[m.fillna(False)]
    out = base[base.index.isin(keep)]
    return out if len(out) else None

def fire_tennis_v44(df, spec):
    base = fire_tennis(df, {k: v for k, v in spec.items() if k not in ('price_short','price_flat','why')})
    if base is None or 'price_short' not in spec: return base
    oc = 'dog_ml'
    m = pd.Series(True, index=df.index)
    m = _apply_pdev(df, m, {'price_short': spec['price_short']}, oc)
    keep = df.index[m.fillna(False)]
    out = base[base.index.isin(keep)]
    return out if len(out) else None

