# ═══════════════════════════════════════════════════════════════════════════════════════
#  v44 SECTION C — RECONSTRUCTED LEGACY STRATEGIES
# ═══════════════════════════════════════════════════════════════════════════════════════
"""v44 RECONSTRUCTION of the legacy CSV strategy families as first-class, LOW-DRAWDOWN strategies.

The legacy artifacts (MASTER_strategy_map.csv, FINAL_strategy_ranking.csv, live_log_strategy_ranking)
carried 123 strategies. Most were high-odds comeback bets: 6-16% strike rate at 15-51 odds, with
maximum losing streaks of 61 to 543 bets. Those are not tradeable at sane stake sizes regardless of
their headline ROI, so they are reconstructed here by INVERTING or RE-ANCHORING the same signal onto
a high-strike-rate side, and every one is scored on drawdown as well as return."""

def dd_metrics(fr, n_boot=1500):
    """v43 metrics + drawdown, longest losing run, and return-per-drawdown."""
    if fr is None or len(fr) == 0:
        return dict(n=0, wr=np.nan, odds=np.nan, roi=np.nan, ci=np.nan, maxdd=np.nan, streak=np.nan, rpd=np.nan)
    m = g43_metrics(fr)
    p = fr.sort_values('ts')['_profit'].to_numpy(float) if 'ts' in fr.columns else fr['_profit'].to_numpy(float)
    eq = np.cumsum(p); peak = np.maximum.accumulate(eq)
    maxdd = float((peak - eq).max())
    lose = (p < 0).astype(int); streak = mx = 0
    for x in lose:
        streak = streak + 1 if x else 0
        mx = max(mx, streak)
    m['maxdd'] = round(maxdd, 1)
    m['streak'] = int(mx)
    m['rpd'] = round(float(eq[-1] / maxdd), 2) if maxdd > 0 else np.inf
    return m

def fire_recon_efootball(df, spec):
    """Reconstructed eFootball signals. Every one settles on the FIRST trigger per match."""
    k = spec['kind']
    if k == 'ht_leader_hold':
        # LEGACY: HT_Leader — reconstructed as backing the half-time leader to WIN, at a capped price,
        # which is the high-strike-rate side of the same signal.
        m = (df['rt_score_difference'] >= spec.get('sd_min', 1)) & df['is_second_half'] \
            & df['leader_odds_rt'].notna() & (df['leader_odds_rt'] >= spec['lo']) & (df['leader_odds_rt'] < spec['hi'])
        oc = 'leader_odds_rt'; side = 'leader'
    elif k == 'fav_lead_early':
        # LEGACY: HT_Fav_Lead_Early — the favourite leading; back it rather than fading it.
        m = (df['rt_score_difference'] >= 1) & (df['leading_team_rt'] == df['favourite_Prematch']) \
            & df['leader_odds_rt'].notna() & (df['leader_odds_rt'] >= spec['lo']) & (df['leader_odds_rt'] < spec['hi'])
        oc = 'leader_odds_rt'; side = 'leader'
    elif k == 'two_goal_hold':
        # LEGACY: Double_Trouble / Hedge_2GL / Loser_2G were the 6-9% comeback side of a two-goal gap.
        # Reconstructed onto the LEADER side: a two-goal lead held, which is the ~90% side.
        m = (df['rt_score_difference'] >= 2) & df['leader_odds_rt'].notna() \
            & (df['leader_odds_rt'] >= spec['lo']) & (df['leader_odds_rt'] < spec['hi'])
        oc = 'leader_odds_rt'; side = 'leader'
    elif k == 'draw_lean':
        # LEGACY: DrawLean / Draw_g0_p70 — kept as a draw bet but with a price cap and a form wall,
        # which is what turns it from a 25-45% lottery into a strike-rate strategy.
        m = df['tied'] & df['draw_odds'].notna() & (df['draw_odds'] >= spec['lo']) & (df['draw_odds'] < spec['hi'])
        if spec.get('pair_g5_max') is not None: m &= df['pair_g5'] <= spec['pair_g5_max']
        if spec.get('second_half'): m &= df['is_second_half']
        oc = 'draw_odds'; side = 'draw'
    elif k == 'loser_form_draw':
        # LEGACY: Loser_Form5 / Loser_1G_Momentum — the trailing-side signal, re-anchored onto the
        # DRAW instead of the comeback win. Same read, far shorter price, far shallower drawdown.
        m = (df['rt_score_difference'] == 1) & df['is_second_half'] & df['draw_odds'].notna() \
            & (df['draw_odds'] >= spec['lo']) & (df['draw_odds'] < spec['hi'])
        if spec.get('loser_wr_edge'): m &= df['loser_player_wr'] >= df['leader_player_wr']
        if spec.get('leader_games_min') is not None: m &= df['leader_games_24h'] >= spec['leader_games_min']
        oc = 'draw_odds'; side = 'draw'
    elif k == 'early_hammer_under':
        # LEGACY: Early_Hammer was a 14% / 26-odds bet with a 149-bet losing run. Re-anchored onto the
        # UNDER at 0-0 with a form wall — the same "this game is not going to explode" read.
        m = df['score_is_0v0'] & df['total_goals_under'].notna() \
            & (df['total_goals_under'] >= spec['lo']) & (df['total_goals_under'] < spec['hi'])
        if spec.get('pair_g5_max') is not None: m &= df['pair_g5'] <= spec['pair_g5_max']
        oc = 'total_goals_under'; side = 'under'
    else:
        raise ValueError(k)
    if spec.get('p') is not None:
        m &= (df['prog'] >= spec['p'][0]) & (df['prog'] <= spec['p'][1])
    if spec.get('league'): m &= df['league'].isin(spec['league'])
    s = df[m.fillna(False)]
    if len(s) == 0: return None
    fr = s.groupby('match_id', sort=False).head(1).copy()
    if side == 'leader':   won = fr['final_result'] == fr['leading_team_rt']
    elif side == 'draw':   won = fr['final_result'] == 'Draw'
    else:                  won = fr['final_tg'] < fr['total_goals_handicap']
    fr['_won'] = won.values; fr['_odds'] = fr[oc].values
    fr['_profit'] = np.where(won, fr[oc] - 1, -1.0)
    return fr

