def v44_placeability(df, mask, min_s=20.0):
    """Vectorised placeability. Equivalent to g43_placeability but O(n) instead of O(matches x n).

    For each match that triggers: find the FIRST row where the condition holds, then the first row
    at or after it where the condition stops holding (or the match's last row). The gap between
    those timestamps is the window in which the bet could actually be struck. Returns the percentage
    of triggering matches whose window is at least min_s seconds.

    The reference implementation is retained as g43_placeability and the two are checked for
    equivalence in the self-audit, because a faster function that quietly disagrees with the one it
    replaced is worse than no speed-up at all."""
    m = mask.reindex(df.index).fillna(False).to_numpy(bool)
    if not m.any():
        return 0.0
    mid = df['match_id'].to_numpy()
    ts = df['ts'].to_numpy('datetime64[ns]')
    order = np.lexsort((np.arange(len(df)), mid))
    mid_s, ts_s, m_s = mid[order], ts[order], m[order]
    # match boundaries in the sorted view
    newg = np.empty(len(mid_s), bool); newg[0] = True; newg[1:] = mid_s[1:] != mid_s[:-1]
    gid = np.cumsum(newg) - 1
    ng = gid[-1] + 1
    pos = np.arange(len(mid_s))
    gstart = np.zeros(ng, np.int64); gstart[gid[newg]] = pos[newg]
    gend = np.zeros(ng, np.int64)
    lastmask = np.empty(len(mid_s), bool); lastmask[-1] = True; lastmask[:-1] = mid_s[1:] != mid_s[:-1]
    gend[gid[lastmask]] = pos[lastmask]
    # first True per match
    first_t = np.full(ng, -1, np.int64)
    idx_t = pos[m_s]
    np.minimum.at(first_t, gid[m_s], idx_t) if False else None
    ft = np.full(ng, np.iinfo(np.int64).max, np.int64)
    np.minimum.at(ft, gid[m_s], idx_t)
    has = ft != np.iinfo(np.int64).max
    # first False at or after the first True, within the match
    after = np.zeros(len(mid_s), bool)
    valid = np.where(has)[0]
    if len(valid) == 0:
        return 0.0
    after[np.concatenate([np.arange(ft[g], gend[g] + 1) for g in valid])] = True
    bad = after & (~m_s)
    fb = np.full(ng, np.iinfo(np.int64).max, np.int64)
    if bad.any():
        np.minimum.at(fb, gid[bad], pos[bad])
    end_pos = np.where(fb[valid] != np.iinfo(np.int64).max, fb[valid], gend[valid])
    win = (ts_s[end_pos] - ts_s[ft[valid]]) / np.timedelta64(1, 's')
    return round(100.0 * float((win >= min_s).mean()), 1)


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v44 SPEC FINGERPRINT — pins every declarative strategy's NAME and PARAMETERS
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Added after a mutation test exposed a real gap: renaming or silently re-parameterising a
#  declarative spec passed the audit undetected. AUDIT_CLAIMS pins only the imperative builders
#  (19 of 179 strategies, 11% coverage); the REGISTRY check counted specs but never inspected
#  them; and the LINEAGE check compares FUNCTION names, so dict-based specs were invisible to it.
#  Every spec is now hashed on its parameters, so a changed threshold, a changed odds band or a
#  renamed strategy fails the audit.
