# ═══════════════════════════════════════════════════════════════════════════════
# FIRE / SETTLEMENT — one bet per match = first trigger row, payout at trigger row
# ═══════════════════════════════════════════════════════════════════════════════
def ab_fire_efootball(df, spec):
    down1 = (df['rt_score_difference'] == 1) & ~df['losing_team_rt'].isin(['Draw', 'N/A'])
    if spec['market'] == 'loser':
        m = down1 & df['loser_odds_rt'].notna() & (df['loser_odds_rt'] > 1.01) & (df['loser_odds_rt'] >= spec['thr'])
        oc = 'loser_odds_rt'
        if spec.get('early_goal'):      m &= df['early_first_goal'] == True
        if spec.get('wr_gap'):          m &= df['loser_player_wr'] >= df['leader_player_wr']
        if spec.get('leader_games_min') is not None: m &= df['leader_games_24h'] >= spec['leader_games_min']
        if spec.get('rest_max') is not None:         m &= df['min_rest_min'] <= spec['rest_max']
        if spec.get('trailer_high'):    m &= df['trailer_at_high'] == True
        if spec.get('league'):          m &= df['league'].isin(spec['league'])
        # ── v44 heritage keys ──
        if spec.get('one_h'):           m &= df['is_first_half']
        if spec.get('min_minute') is not None: m &= df['minute'] >= spec['min_minute']
        if spec.get('form5_min') is not None:  m &= df['loser_form5'] >= spec['form5_min']
        if spec.get('form10_min') is not None: m &= df['loser_form10'] >= spec['form10_min']
        if spec.get('form20_min') is not None: m &= df['loser_form20'] >= spec['form20_min']
        if spec.get('form_diff_min') is not None: m &= (df['loser_form10'] - df['leader_form10']) >= spec['form_diff_min']
        if spec.get('wr_loser_min') is not None: m &= df['loser_player_wr'] >= spec['wr_loser_min']
        if spec.get('wr_asym_min') is not None:  m &= (df['loser_player_wr'] - df['leader_player_wr']) >= spec['wr_asym_min']
        if spec.get('consec_min') is not None:   m &= df['consec_loser_odds_high'] >= spec['consec_min']
        if spec.get('h2h_wr_min') is not None:   m &= df['h2h_wr_loser'] >= spec['h2h_wr_min']
        if spec.get('elo_adv_min') is not None:  m &= df['elo_advantage_loser'] >= spec['elo_adv_min']
        if spec.get('fgs_underdog'):    m &= df['FGS_Fav_or_Underdog'] == 'Underdog_FGS'
        if spec.get('fgs_fav'):         m &= df['FGS_Fav_or_Underdog'] == 'FavTeam_FGS'
        if spec.get('role_reversal'):   m &= df['fav_rt'] != df['favourite_Prematch']
        if spec.get('combined_mg_min') is not None: m &= df['combined_avg_matchgoals'] >= spec['combined_mg_min']
        if spec.get('hour_max') is not None: m &= df['hour'] < spec['hour_max']
        if spec.get('won_last2'):       m &= df['loser_won_last2'] == 1
        if spec.get('veteran_hold'):    m &= (df['veteran_leader_side'] != 'N/A') & df['veteran_leader_odds'].notna() & (df['veteran_leader_odds'] > 2.0)
        if spec.get('fav_down'):        m &= df['favourite_Prematch'] == df['losing_team_rt']
    elif spec['market'] == 'draw':
        m = df['draw_odds'].notna() & (df['draw_odds'] > 1.01) & (df['draw_odds'] >= spec['thr'])
        oc = 'draw_odds'
        if spec.get('band_hi'): m &= df['draw_odds'] < spec['band_hi']
        if spec.get('tied_2h'): m &= df['tied'] & df['is_second_half']
        if spec.get('tied_any'): m &= df['tied']
        if spec.get('s00'): m &= df['score_is_0v0']
        if spec.get('s11'): m &= df['score_is_1v1']
        if spec.get('h2h_max') is not None:      m &= df['pair_h2h5'].astype('float64') <= spec['h2h_max'] + _EPS
        if spec.get('pair_l10_max') is not None: m &= df['pair_g10'] <= spec['pair_l10_max']
        if spec.get('pair_g5_max') is not None:  m &= df['pair_g5'].astype('float64') <= spec['pair_g5_max'] + _EPS
        if spec.get('wall'):                     m &= df['both_wall'] == True
        if spec.get('pmD') is not None:          m &= df['prematch_draw_odds'] <= spec['pmD']
        if spec.get('pm_ratio_max') is not None: m &= df['pm_ratio'] <= spec['pm_ratio_max']
    else:  # tgu
        m = df['total_goals_under'].notna() & (df['total_goals_under'] > 1.01) & (df['total_goals_under'] >= spec['thr'])
        oc = 'total_goals_under'
        if spec.get('wall'): m &= df['both_wall'] == True
        if spec.get('s00'): m &= df['score_is_0v0']
        if spec.get('gap_abs') is not None:
            # float64 + tolerance. In float32 a pair_g5 of 1.8 against a 2.5 line lands EXACTLY on a
            # gap_abs=0.7 boundary, and the last bits of the representation decide whether the bet fires.
            # That produced a 1.5% discrepancy between two frames holding identical underlying values.
            m &= (df['pair_g5'].astype('float64') - df['total_goals_handicap'].astype('float64')) <= -spec['gap_abs'] + _EPS
        if spec.get('pair_g5_max') is not None: m &= df['pair_g5'].astype('float64') <= spec['pair_g5_max'] + _EPS
        if spec.get('u_flat_max') is not None: m &= df['u_ratio'].abs() <= spec['u_flat_max']
        if spec.get('l_move_max') is not None: m &= df['l_move'] <= spec['l_move_max']
        if spec.get('u_ratio_ge') is not None: m &= df['u_ratio'] >= spec['u_ratio_ge']
    m &= (df['prog'] >= spec['p'][0]) & (df['prog'] <= spec['p'][1])
    _V44_LAST_MASK['mask'] = m; _V44_LAST_MASK['spec'] = spec.get('name')
    s = df[m]
    if len(s) == 0:
        return None
    fr = s.groupby('match_id', sort=False).head(1).copy()
    if spec.get('veteran_hold'):
        fr['_odds'] = fr['veteran_leader_odds'].values
        fr['_profit'] = np.where(fr['final_result'] == fr['veteran_leader_side'], fr['veteran_leader_odds'] - 1, -1.0)
        fr['_won'] = (fr['final_result'] == fr['veteran_leader_side']).values
        return fr
    if spec.get('fav_down'):
        fr['_odds'] = fr['favourite_team_rt_odds'].values
        fr['_profit'] = np.where(fr['final_result'] == fr['favourite_Prematch'], fr['favourite_team_rt_odds'] - 1, -1.0)
        fr['_won'] = (fr['final_result'] == fr['favourite_Prematch']).values
        return fr
    if spec['market'] == 'loser':
        won = fr['final_result'] == fr['losing_team_rt']
    elif spec['market'] == 'draw':
        won = fr['final_result'] == 'Draw'
    else:
        if spec.get('line_corr'):
            _line = fr['total_goals_handicap'].values.astype(float)
            _line = np.where(_line == np.floor(_line), _line + 0.5, _line)  # truncated integer -> raise 0.5 (no pushes)
            won = pd.Series(fr['final_tg'].values < _line, index=fr.index)
        else:
            won = fr['final_tg'] < fr['total_goals_handicap']
    fr['_won'] = won.values; fr['_odds'] = fr[oc].values
    fr['_profit'] = np.where(won, fr[oc] - 1, -1.0)
    return fr

def ab_fire_real_football(df, spec):
    m = (df['sd'] == 1) & df['is_second_half'] & df['leader_odds_rt'].notna() & (df['leader_odds_rt'] > 1.01) \
        & (df['leader_odds_rt'] >= spec['lo']) & (df['leader_odds_rt'] < spec['hi']) \
        & (df['prog'] >= spec['p'][0]) & (df['prog'] <= spec['p'][1])
    if spec.get('pmD') is not None:   m &= df['prematch_draw_odds'] <= spec['pmD']
    if spec.get('tg_max') is not None: m &= df['tg'] <= spec['tg_max']
    if spec.get('hour_max') is not None: m &= df['hour'] < spec['hour_max']
    if spec.get('dog_lead'):          m &= df['leading_team_rt'] != df['favourite_Prematch']
    if spec.get('home_lead'):         m &= df['leading_team_rt'] == 'Home_team'
    if spec.get('ht_lead1'):          m &= df['ht_diff'] == 1
    if spec.get('line_max') is not None: m &= df['total_goals_handicap'] <= spec['line_max']
    if spec.get('msg_min') is not None:  m &= df['min_since_goal'] >= spec['msg_min']
    if spec.get('pm_ratio_max') is not None: m &= df['pm_ratio'] <= spec['pm_ratio_max']
    _V44_LAST_MASK['mask'] = m; _V44_LAST_MASK['spec'] = spec.get('name')
    s = df[m]
    if len(s) == 0:
        return None
    fr = s.groupby('match_id', sort=False).head(1).copy()
    won = fr['final_result'] == fr['leading_team_rt']
    fr['_won'] = won.values; fr['_odds'] = fr['leader_odds_rt'].values
    fr['_profit'] = np.where(won, fr['leader_odds_rt'] - 1, -1.0)
    return fr

def ab_fire_basketball(df, spec):
    m = df['total_points_under'].notna() & (df['total_points_under'] > 1.01) \
        & (df['total_points_under'] >= spec['odds_min']) & df['total_points_handicap'].notna() \
        & (df['q'] >= spec['q'][0]) & (df['q'] <= spec['q'][1])
    if spec.get('lead_min') is not None:     m &= df['lead'] >= spec['lead_min']
    if spec.get('pace_le') is not None:      m &= df['run_tot'] <= (spec['q'][0] / 4.0) * df['total_points_handicap'] * spec['pace_le']
    if spec.get('proj_gap') is not None:     m &= (df['total_points_handicap'] - df['run_tot'] / (df['q'] * 0.25)) >= spec['proj_gap']
    if spec.get('dead_ml') is not None:      m &= np.maximum(df['home_odds'], df['away_odds']) >= spec['dead_ml']
    if spec.get('steam_up') is not None:     m &= (df['total_points_handicap'] - df['open_line']) >= spec['steam_up']
    if spec.get('steam_down') is not None:   m &= (df['open_line'] - df['total_points_handicap']) >= spec['steam_down']
    if spec.get('anchor_ge') is not None:    m &= df['under_anchor_ratio'] >= spec['anchor_ge']
    if spec.get('line_ge') is not None:      m &= df['total_points_handicap'] >= spec['line_ge']
    if spec.get('line_p90'):                 m &= df['total_points_handicap'] >= df['total_points_handicap'].quantile(0.90)
    if spec.get('league_not') is not None:   m &= ~df['league'].astype(str).str.contains(spec['league_not'], na=False)
    if spec.get('league_contains') is not None: m &= df['league'].astype(str).str.contains(spec['league_contains'], na=False)
    if spec.get('conc_bottom_q') is not None: m &= df['pair_conc5'] <= df['pair_conc5'].quantile(spec['conc_bottom_q'])
    if spec.get('cold_form'):                m &= (df['hp_avg_matchgoals_lastgame'] < df['hp_avg_matchgoals_10']) & (df['ap_avg_matchgoals_lastgame'] < df['ap_avg_matchgoals_10'])
    if spec.get('feed_gap') is not None:     m &= (df['total_points_handicap'] - df['pair_g10']) >= spec['feed_gap']
    if spec.get('h2h_gap') is not None:      m &= (df['total_points_handicap'] - df['pair_h2h5']) >= spec['h2h_gap']
    if spec.get('h2h_l10_gap') is not None:  m &= (df['total_points_handicap'] - (df['hp_h2h_avg_matchggoals_l10g'] + df['ap_h2h_avg_matchggoals_l10g'])) >= spec['h2h_l10_gap']
    if spec.get('rest_max') is not None:     m &= df['min_rest_min'] <= spec['rest_max']
    if spec.get('q1_lead_min') is not None:  m &= df['q1_lead'] >= spec['q1_lead_min']
    if spec.get('q1_tot_max') is not None:   m &= df['q1_tot'] <= spec['q1_tot_max']
    if spec.get('frozen'):                   m &= df['open_line'] == df['total_points_handicap']
    if spec.get('hour_max') is not None:     m &= df['hour'] < spec['hour_max']
    # ── v40_1 keys ──
    if spec.get('pace_max') is not None:     m &= df['pace_ratio'] <= spec['pace_max']
    if spec.get('need_min') is not None:     m &= df['need_vs_expected'] >= spec['need_min']
    if spec.get('imbal_max') is not None and 'imbal' in df.columns: m &= df['imbal'] <= spec['imbal_max']
    if spec.get('u_flat_max') is not None:   m &= (df['under_anchor_ratio'] - 1).abs() <= spec['u_flat_max']
    if spec.get('l_move_max') is not None:   m &= df['l_move'] <= spec['l_move_max']
    if spec.get('u_ratio_ge') is not None:   m &= df['under_anchor_ratio'] >= 1 + spec['u_ratio_ge']
    _V44_LAST_MASK['mask'] = m; _V44_LAST_MASK['spec'] = spec.get('name')
    s = df[m]
    if len(s) == 0:
        return None
    fr = s.groupby('match_id', sort=False).head(1).copy()
    won = fr['final_tp'] < fr['total_points_handicap']
    fr['_won'] = won.values; fr['_odds'] = fr['total_points_under'].values
    fr['_profit'] = np.where(won, fr['total_points_under'] - 1, -1.0)
    return fr

def ab_fire_tennis(df, spec):
    st = df['h_score'] + df['a_score']
    # ── v40_1 SET-1 MARKETS: win SET 1, settled from the score (no circularity) ──
    if spec.get('set1_market'):
        _g = df.groupby('match_id', sort=False)
        _op = df[(df['home_odds'] > 1) & (df['away_odds'] > 1)].groupby('match_id').first()[['home_odds', 'away_odds']]
        d = df.join(_op.rename(columns={'home_odds': 'o_ho', 'away_odds': 'o_ao'}), on='match_id')
        d['fav_home'] = d['o_ho'] < d['o_ao']
        d['fav_now'] = np.where(d['fav_home'], d['home_odds'], d['away_odds'])
        d['fav_open'] = np.where(d['fav_home'], d['o_ho'], d['o_ao'])
        d['drift'] = d['fav_now'] - d['fav_open']
        d['dog_now'] = np.where(d['fav_home'], d['away_odds'], d['home_odds'])
        d['dog_open'] = np.where(d['fav_home'], d['o_ao'], d['o_ho'])
        d['dog_ratio'] = (d['dog_open'] - d['dog_now']) / d['dog_open']
        s1 = d[d['sets'] == 0].copy() if 'sets' in d.columns else d[st.loc[d.index] == 0].copy()
        s1['k'] = s1.groupby('match_id').cumcount(); s1['kn'] = s1.groupby('match_id')['k'].transform('max') + 1
        s1['pos'] = (s1['k'] + 1) / s1['kn']
        lo, hi = spec['set1_pos']
        s1 = s1[(s1['pos'] >= lo) & (s1['pos'] < hi)]
        e1 = d[st.loc[d.index] == 1].groupby('match_id').first()[['h_score']] if 'sets' not in d.columns else d[d['sets'] == 1].groupby('match_id').first()[['h_score']]
        e1['s1_home'] = e1['h_score'] >= 1
        sub = s1.sort_values(['match_id', 'k']).groupby('match_id').last()
        J = sub.join(e1[['s1_home']], how='inner')
        if spec['set1_market'] == 'fav':
            J = J[(J['drift'] <= spec['set1_drift_max']) & (J['fav_now'] >= spec['set1_odds_lo']) & (J['fav_now'] <= spec['set1_odds_hi'])]
            won = np.where(J['fav_home'], J['s1_home'], ~J['s1_home'].astype(bool))
            odds = J['fav_now']
        else:
            J = J[(J['dog_ratio'] >= spec['set1_ratio_min']) & (J['dog_now'] >= spec['set1_odds_lo']) & (J['dog_now'] <= spec['set1_odds_hi'])]
            won = ~np.where(J['fav_home'], J['s1_home'], ~J['s1_home'].astype(bool)).astype(bool)
            odds = J['dog_now']
        if len(J) == 0:
            return None
        J['_won'] = won; J['_odds'] = odds.values
        J['_profit'] = np.where(won, J['_odds'] - 1, -1.0)
        return J
    if spec.get('any_set1'):
        m = (st == 1) & df['dog_ml'].notna() & (df['dog_ml'] > 1.01)
        m &= ((df['set1_winner'] == 'Home') & (df['home_odds'] >= spec['odds_min'])) | ((df['set1_winner'] == 'Away') & (df['away_odds'] >= spec['odds_min']))
        if spec.get('odds_hi'):
            m &= ((df['set1_winner'] == 'Home') & (df['home_odds'] < spec['odds_hi'])) | ((df['set1_winner'] == 'Away') & (df['away_odds'] < spec['odds_hi']))
    else:
        m = (st == 1) & (df['set1_winner'] == df['dog']) & df['dog_ml'].notna() & (df['dog_ml'] > 1.01) & (df['dog_ml'] >= spec['odds_min'])
        if spec.get('odds_hi'): m &= df['dog_ml'] < spec['odds_hi']
        if spec.get('pm_dog_min') is not None: m &= df['pm_dog_odds'] >= spec['pm_dog_min']
        if spec.get('pm_ratio_min') is not None: m &= df['pm_ratio'] >= spec['pm_ratio_min']
        if spec.get('dog_anchor_ge') is not None: m &= df['dog_anchor'] >= spec['dog_anchor_ge']
        if spec.get('hour_max') is not None: m &= df['hour'] < spec['hour_max']
    if spec.get('minute_max') is not None:
        m &= df['minute'] <= spec['minute_max']
    _V44_LAST_MASK['mask'] = m; _V44_LAST_MASK['spec'] = spec.get('name')
    s = df[m]
    if len(s) == 0:
        return None
    fr = s.groupby('match_id', sort=False).head(1).copy()
    if spec.get('any_set1'):
        side = np.where(fr['set1_winner'] == 'Home', 'Home', 'Away')
        won = fr['final_winner'].values == side
        odds = np.where(fr['set1_winner'] == 'Home', fr['home_odds'], fr['away_odds'])
    else:
        won = fr['final_winner'] == fr['dog']
        odds = fr['dog_ml'].values
    fr['_won'] = won; fr['_odds'] = odds
    fr['_profit'] = np.where(won, odds - 1, -1.0)
    return fr

