from openpyxl.styles import PatternFill, Font, Alignment
from openpyxl.utils import get_column_letter

def _ab_prep_from_files(sport, prep, pattern, **prep_kwargs):
    """Run the sport's prep over a comma-separated glob pattern by loading each piece
    and concatenating the resulting feature frames."""
    pieces = [p for p in pattern.split(',') if p.strip()]
    dfs = []
    for p in pieces:
        if glob.glob(p):
            dfs.append(prep(p, **prep_kwargs))
    if not dfs:
        raise FileNotFoundError(pattern)
    if len(dfs) == 1:
        return dfs[0]
    df = pd.concat(dfs, ignore_index=True)
    if 'id' in df.columns:
        df = df.drop_duplicates(subset=['id'])
    return df.sort_values(['match_id', 'ts']).reset_index(drop=True)




