def v46_frame(sport):
    import os
    fp = V46_FRAMES[sport]
    if not os.path.exists(fp):
        raise FileNotFoundError(f"frame missing for {sport}: {fp}")
    return pd.read_parquet(fp)

def v46_certify(sport, split=0.5, with_placeability=True, verbose=False, frame=None):
    """Certifies every registered strategy for a sport: AB specs, v44 fusion, V5 set and
    reconstructions, all on the AB frames, with drawdown and placeability."""
    reg = V46_REGISTRY[sport]
    df = v46_frame(sport) if frame is None else frame
    cut = df['mstart'].quantile(split)
    is_d, oos = df[df['mstart'] <= cut], df[df['mstart'] > cut]
    groups = [('v44_AB', reg['specs'], reg['fire'])]
    if reg.get('extra'): groups.append(('v46_extra', reg['extra'], reg['wrap']))
    if reg.get('recon'): groups.append(('v46_recon', reg['recon'], reg['reconfire']))
    out = []
    for origin, specs, fire in groups:
        for spec in specs:
            try:
                fi, fo = fire(is_d, spec), fire(oos, spec)
            except Exception as e:
                out.append(dict(sport=sport, origin=origin, name=spec['name'], verdict='ERROR',
                                err=f"{type(e).__name__}: {str(e)[:60]}"))
                continue
            mi, mo = dd_metrics(fi), dd_metrics(fo)
            pl = None
            if with_placeability and fo is not None and len(fo):
                mask = _V44_LAST_MASK.get('mask')
                if mask is not None and len(mask) == len(oos):
                    try: pl = v44_placeability(oos, mask)
                    except Exception: pl = None
            out.append(dict(sport=sport, origin=origin, name=spec['name'], spec=spec, IS=mi, OOS=mo,
                            placeable_pct=pl, verdict=g43_gate(mi, mo, pl),
                            why=spec.get('why') or spec.get('legacy')))
            if verbose:
                print(f"  {out[-1]['verdict']:5} [{origin:9}] {spec['name']:30} "
                      f"OOS n={mo['n']:>5} WR={mo['wr']:5.1f}% @{mo['odds']:.2f} ROI={mo['roi']:+7.1f} DD={mo['maxdd']:>6.1f}")
    return out


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v46 SECTION H — THE HEAVYWEIGHT DESIGNATION
# ═══════════════════════════════════════════════════════════════════════════════════════
#  A strategy earns HEAVYWEIGHT only by clearing every criterion at once. Most strategies that look
#  spectacular fail one of them, and it is almost always the same one: the eFootball comeback family
#  returns +177% but at a 13% strike rate with a 33-unit drawdown, and the high-strike eFootball
#  walls are barely placeable. Passing four tests simultaneously is a much higher bar than topping
#  any single leaderboard.
HEAVYWEIGHT_CRITERIA = dict(
    min_bets       = 150,    # decent VOLUME out of sample, not a handful of lucky triggers
    min_win_rate   = 60.0,   # decent STRIKE RATE
    min_odds       = 1.80,   # decent ODDS; no shortening the price to buy a win rate
    max_drawdown   = 15.0,   # LOW DRAWDOWN in units, at flat stakes
    min_ci_floor   = 0.0,    # bootstrap confidence floor still positive
    min_placeable  = 90.0,   # and you can actually get the bet on
)

def heavyweight(rec, criteria=None):
    """True if a certification record clears every heavyweight criterion."""
    c = dict(HEAVYWEIGHT_CRITERIA, **(criteria or {}))
    m = rec['OOS'] if 'OOS' in rec else rec
    pl = rec.get('placeable_pct') if isinstance(rec, dict) else None
    def ok(v, lo=None, hi=None):
        if v is None or (isinstance(v, float) and not np.isfinite(v)): return False
        if lo is not None and v < lo: return False
        if hi is not None and v > hi: return False
        return True
    return (rec.get('verdict') == 'PASS'
            and ok(m.get('n'), c['min_bets'])
            and ok(m.get('wr'), c['min_win_rate'])
            and ok(m.get('odds'), c['min_odds'])
            and ok(m.get('maxdd'), None, c['max_drawdown'])
            and ok(m.get('ci'), c['min_ci_floor'])
            and (pl is None or ok(pl, c['min_placeable'])))

def v46_heavyweights(sport, **kw):
    """Certifies a sport and returns only the strategies that clear every heavyweight criterion,
    ranked by return per unit of drawdown."""
    recs = v46_certify(sport, **kw)
    hw = [r for r in recs if 'OOS' in r and heavyweight(r)]
    return sorted(hw, key=lambda r: -(r['OOS']['rpd'] if np.isfinite(r['OOS']['rpd']) else -1))


# ── v46: de-duplicate the uploaded spec lists ────────────────────────────────────────────
#  LazarusEV_Engine_v44_AB.py defines DogUpSet1_Early_o5plus twice (source lines 540 and 548) with
#  identical parameters. Harmless at runtime, but it inflates the tennis count from 21 distinct
#  strategies to 22 listed, and it collapses a fingerprint key. Removed here, once, by identity.
def _dedup_specs(lst):
    seen=set(); out=[]
    for sp in lst:
        k=(sp['name'], tuple(sorted((k2, str(v2)) for k2, v2 in sp.items() if k2 != 'name')))
        if k in seen: continue
        seen.add(k); out.append(sp)
    return out

