def _discovery_fire(sport):
    return {'football': fire_real_football_v46, 'tennis': fire_tennis_v46,
            'ebasketball': fire_basketball_v46, 'basketball': fire_basketball_v46,
            'efootball': fire_efootball_v46}[sport]

def v46_discover(sport, frame=None, max_conditions=DISCOVERY_MAX_CONDITIONS,
                 min_bets=40, pool=None, base=None, verbose=False):
    """Stepwise discovery on a strict three-way split.

    fit third   — where candidate conditions are proposed
    select third— every kept condition must ALSO improve here, which is the anti-overfitting guard
    test third  — never touched during the search; the number reported back

    Returns a dict with the discovered spec and its metrics in all three segments."""
    pool = pool or CONDITION_POOL[sport]
    base = base or DISCOVERY_BASE[sport]
    fire = _discovery_fire(sport)
    df = v46_frame(sport) if frame is None else frame
    q40, q70 = df['mstart'].quantile(0.40), df['mstart'].quantile(0.70)
    FIT  = df[df['mstart'] <= q40]
    SEL  = df[(df['mstart'] > q40) & (df['mstart'] <= q70)]
    TEST = df[df['mstart'] > q70]
    def build(conds):
        s = dict(base)
        for c in conds: s.update(pool[c])
        return s
    def ev(d, conds, minn=min_bets):
        try: m = dd_metrics(fire(d, build(conds)))
        except Exception: return None
        if m['n'] < minn or not np.isfinite(m.get('odds', np.nan)): return None
        m['edge'] = edge_over_breakeven(m)
        return m
    def score(m):
        if m is None or not np.isfinite(m.get('edge', np.nan)): return -1e9
        return m['edge'] * np.log1p(m['n']) / max(1.0, np.sqrt(max(m['maxdd'], 0.5)))
    cur = []; bf, bs = ev(FIT, cur), ev(SEL, cur); log = []
    for _ in range(max_conditions):
        cand = []
        for c in pool:
            if c in cur: continue
            f, s2 = ev(FIT, cur+[c]), ev(SEL, cur+[c])
            if f is None or s2 is None: continue
            if score(f) > score(bf) + 1e-9 and score(s2) > score(bs) + 1e-9:
                cand.append((score(f)+score(s2), c, f, s2))
        if not cand: break
        cand.sort(key=lambda t: -t[0])
        _, c, f, s2 = cand[0]
        cur.append(c); bf, bs = f, s2
        log.append(('add', c, round(f['edge'],1), round(s2['edge'],1)))
        if verbose: print(f"   + {c:14} FIT edge {f['edge']:+.1f}  SEL edge {s2['edge']:+.1f}")
    improved = True
    while improved and len(cur) > 1:
        improved = False
        for c in list(cur):
            trial = [x for x in cur if x != c]
            f, s2 = ev(FIT, trial), ev(SEL, trial)
            if f and s2 and score(f) >= score(bf) and score(s2) >= score(bs):
                cur = trial; bf, bs = f, s2; improved = True
                log.append(('prune', c, round(f['edge'],1), round(s2['edge'],1))); break
    return dict(sport=sport, conditions=cur, spec=build(cur), log=log,
                FIT=ev(FIT,cur,1), SEL=ev(SEL,cur,1), TEST=ev(TEST,cur,1))

# ── ODDS-ADJUSTED TIER CRITERIA ──────────────────────────────────────────────────────────
#  The original tiers used a flat 65% win rate, which is odds-blind: it rejects a 52% strike at 3.01
#  (a +19 point edge, the largest in the book) while accepting a 66% strike at 1.55 (+1.5 points).
#  These criteria test the edge over break-even instead, which is comparable at every price.
# TIER 2 uses a 50% strike floor, not 65%. The 65% bar is odds-blind: it rejected V5_TEN_S1W_18_40
# (55.6% at 2.16 — a +9.3 point edge) while a 66% strike at 1.55 is only +1.5 points. What matters
# is the edge over the price's break-even, which is what these criteria test.
TIER2_MIN_WIN_RATE = 50.0
TIER1_MIN_WIN_RATE = 65.0

TIER_CRITERIA_ODDS_ADJUSTED = dict(
    min_bets_per_segment = 100,
    min_edge             = 5.0,    # percentage points over break-even, in EVERY segment
    require_positive_ci  = True,
    require_positive_roi = True,
    min_odds             = 1.20,   # low prices allowed IF the edge and placeability hold up
    min_placeable        = 90.0,
)

def tier_of(segments, criteria=None, placeable=None):
    """TIER 1 needs every segment (IS, OOS, FORWARD, BACKWARD, FREEZE) to pass.
    TIER 2 needs the IS/OOS pair only. Segments is a dict of name -> metrics dict."""
    c = dict(TIER_CRITERIA_ODDS_ADJUSTED, **(criteria or {}))
    def ok(m):
        if m is None or m.get('n',0) < c['min_bets_per_segment']: return False
        e = edge_over_breakeven(m)
        if not np.isfinite(e) or e < c['min_edge']: return False
        if c['require_positive_roi'] and not (m.get('roi',0) > 0): return False
        if c['require_positive_ci'] and not (m.get('ci',0) > 0): return False
        if m.get('odds',0) < c['min_odds']: return False
        return True
    if placeable is not None and placeable < c['min_placeable']: return 'NOT VALIDATED'
    core = all(ok(segments.get(k)) for k in ('IS','OOS'))
    full = core and all(ok(segments.get(k)) for k in ('FORWARD','BACKWARD','FREEZE'))
    return 'TIER 1 — OMEGA' if full else ('TIER 2 — CHALLENGE' if core else 'NOT VALIDATED')


