# ═══════════════════════════════════════════════════════════════════════════════════════
#  v48 SECTION L — MULTI-SPORT INGESTION, ROUTING AND ONE-CALL PIPELINE
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Until v47 the operating model was: prep each sport by hand, run certification per sport, then
#  assemble the book with a series of scripts. That is fine for one person who remembers the order
#  and fatal for anyone who does not. Section L collapses it: drop every sport's raw export into one
#  folder and call run_pipeline(). The router identifies each file, sends it to the right prep, and
#  the orchestrator carries it through to the finished master book.
#
#  ROUTING IS BY CONTENT, NOT FILENAME. Filenames are inconsistent across exports ("Total_Bets_File"
#  is eFootball; "Complete_Data" is also eFootball) and a misrouted sport would silently produce
#  meaningless strategies. Two signals decide it, both read from the data:
#     1. the PHASE vocabulary  — "Quarter" -> basketball family, "Set" -> tennis, "half" -> football family
#     2. the LEAGUE vocabulary — esports leagues carry a duration marker ("10 mins play", "8 mins play")
#                                or an esports tag (H2H, GT League, 4x4), real ones do not
#  Where the two disagree the file is quarantined rather than guessed at.

SPORT_ROUTE_SAMPLE_ROWS = 4000

ESPORTS_LEAGUE_MARKERS = ('mins play', 'min play', 'h2h', 'gt league', 'esoccer', 'efootball',
                          '4x4', 'ebasketball', 'cyber')

def _phase_kind(series):
    """Reduces a phase column to the vocabulary that identifies the sport family."""
    kinds = set()
    for v in pd.Series(series).dropna().astype(str).unique()[:400]:
        lv = v.lower()
        if 'quarter' in lv: kinds.add('QUARTER')
        elif 'set' in lv:   kinds.add('SET')
        elif 'half' in lv:  kinds.add('HALF')
    return kinds

def _is_esports_league(leagues):
    if not len(leagues): return None
    hits = sum(any(m in str(l).lower() for m in ESPORTS_LEAGUE_MARKERS) for l in leagues)
    return hits / float(len(leagues)) > 0.5

def detect_sport(path, sample_rows=SPORT_ROUTE_SAMPLE_ROWS):
    """Identifies which sport a raw export belongs to, from its content.
    Returns (sport, confidence, reason). sport is None when the signals conflict."""
    try:
        d = pd.read_csv(path, nrows=sample_rows, low_memory=False)
    except Exception as e:
        return None, 0.0, f'unreadable: {e}'
    cols = set(d.columns)
    if 'phase' not in cols:
        return None, 0.0, 'no phase column — not a LazarusEV tick export'
    kinds = _phase_kind(d['phase'])
    leagues = d['league'].dropna().unique()[:60] if 'league' in cols else []
    espt = _is_esports_league(leagues)
    has_player = 'home_team_player' in cols
    if 'SET' in kinds:
        return 'tennis', 0.95, 'phase vocabulary contains Set'
    if 'QUARTER' in kinds:
        if espt is True: return 'ebasketball', 0.90, 'Quarter phases with esports league markers'
        if espt is False: return 'basketball', 0.90, 'Quarter phases with real-world leagues'
        return 'basketball', 0.60, 'Quarter phases, league signal unclear — defaulting to real basketball'
    if 'HALF' in kinds:
        if espt is True or has_player:
            return 'efootball', 0.92, 'half phases with esports league markers or a player column'
        if espt is False: return 'football', 0.90, 'half phases with real-world leagues'
        return None, 0.3, 'half phases but the league signal is ambiguous — quarantined'
    return None, 0.0, f'phase vocabulary not recognised: {sorted(kinds)}'

AB_PREP_FOR_SPORT = {
    'efootball':   'ab_prep_efootball',
    'ebasketball': 'ab_prep_basketball',
    'basketball':  'ab_prep_basketball',
    'football':    'ab_prep_real_football',
    'tennis':      'ab_prep_tennis',
    # ── [v76_48] eTENNIS INGESTS FROM ITS OWN EXPORT ────────────────────────
    # It used to be DERIVED by splitting the tennis frame, so no direct-ingest
    # path existed and ingest_sport('etennis', ...) died on KeyError: 'etennis'
    # mid-batch -- the owner's warehouse now exports it separately and the
    # registry had not caught up. Verified against his two real files: eTennis
    # carries all 96 tennis columns plus home_team_player / away_team_player,
    # so it is a strict SUPERSET and the tennis prep handles it unchanged.
    # (final_result and set1_winner are absent from BOTH raw exports -- the
    # prep derives them, which is why the shared column count is 96.)
    'etennis':     'ab_prep_tennis',
    'tabletennis': 'ab_prep_tabletennis',      # [v76_28]
    'esports':     'ab_prep_esports',          # [v76_28]
}

# eBasketball and real basketball share ab_prep_basketball but need DIFFERENT settings: the esports
# feed is player-based (per-player history, head-to-head, rest) while the real feed is team-based.
# Passing the wrong flag produces a frame that loads fine and yields meaningless strategies, so the
# routing carries the flag explicitly rather than relying on the prep to guess.
PREP_KWARGS_FOR_SPORT = {
    'tabletennis': {},                          # [v76_28]
    'esports':     {},                          # [v76_28]
    'efootball':   {},
    'ebasketball': {'player_feed': True},
    'basketball':  {'player_feed': False},
    'football':    {},
    'tennis':      {},
}

def ingest_sport(sport, files, out_path=None, verbose=True):
    """Runs the correct prep for a sport over its routed files and writes the feature frame."""
    prep = globals()[AB_PREP_FOR_SPORT[sport]]
    kw   = PREP_KWARGS_FOR_SPORT.get(sport, {})
    pattern = ','.join(files)
    if verbose:
        print(f'[ingest] {sport}: {len(files)} files -> {AB_PREP_FOR_SPORT[sport]}'
              + (f' {kw}' if kw else ''))
    df = _ab_prep_from_files(sport, prep, pattern, **kw)
    for c in df.columns:
        if df[c].dtype == 'float64': df[c] = df[c].astype('float32')
    out_path = out_path or V46_FRAMES[sport]
    df.to_parquet(out_path)
    if verbose:
        print(f'[ingest] {sport}: {len(df):,} rows, '
              f"{df['match_id'].nunique():,} matches -> {out_path}")
    _n_rows = len(df)
    del df
    # [v75_62] THE INGEST GRAFTS ITS OWN OUTPUT (owner's directive). The old
    # column selection dropped market prices and player history; rather than
    # trusting it, every freshly built frame is immediately re-grafted from the
    # very files it was built from — over/spread prices joined as-of, hp_/ap_
    # player stats attached, post-match leaks excluded. One pipeline.
    if sport in LAZ_GRAFT_PRICES:
        try:
            laz_graft_frames(sport, list(files), frame=out_path, backup=False,
                             verbose=verbose)
        except Exception as _ge:
            if verbose:
                print(f'[ingest] {sport}: post-build graft skipped '
                      f'({type(_ge).__name__}: {str(_ge)[:70]})')
    return out_path, _n_rows

PIPELINE_STAGES = ('route', 'prep', 'certify', 'deployment gate', 'discovery',
                   'walk-forward', 'tiers', 'master book')


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v49 SECTION M — THE MASTER BOOK BUILDER, INSIDE THE ENGINE
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Through v48 the book was assembled by external scripts. That made run_pipeline() a half-promise:
#  it carried the data through analysis and then stopped, and anyone without those scripts had an
#  engine that could not produce its own deliverable. Section M folds the builder in.
from openpyxl import Workbook, load_workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter
from openpyxl.chart import BarChart, PieChart, LineChart, Reference
from openpyxl.chart.label import DataLabelList
from openpyxl.chart.legend import Legend
from openpyxl.chart.shapes import GraphicalProperties

BK_NAVY='1F3864'; BK_BLUE='2E5C9A'; BK_DARK='27405E'; BK_GREEN='1E7B4F'
BK_RED='8B1A1A'; BK_AMBER='B8860B'; BK_PURPLE='7B1FA2'; BK_GREY='F2F4F7'
BK_BOX=Border(*[Side(style='thin',color='D9D9D9')]*4)
BK_PALETTE=['2E5C9A','1E7B4F','B8860B','8B1A1A','6B4E9E','1F3864','C1666B','4E8098']

def _bk_title(ws,text,sub,ncol,row=1):
    ws.merge_cells(start_row=row,start_column=1,end_row=row,end_column=max(ncol,2))
    c=ws.cell(row,1,text); c.font=Font(bold=True,size=15,color='FFFFFF')
    c.fill=PatternFill('solid',fgColor=BK_NAVY); c.alignment=Alignment(vertical='center')
    ws.row_dimensions[row].height=26
    ws.merge_cells(start_row=row+1,start_column=1,end_row=row+1,end_column=max(ncol,2))
    c=ws.cell(row+1,1,sub); c.font=Font(size=10,italic=True,color='333333')
    c.alignment=Alignment(wrap_text=True,vertical='top')
    ws.row_dimensions[row+1].height=max(30,14*(1+len(sub)//120))
    return row+3

def _bk_section(ws,row,text,ncol):
    ws.merge_cells(start_row=row,start_column=1,end_row=row,end_column=max(ncol,2))
    c=ws.cell(row,1,text); c.font=Font(bold=True,size=12,color='FFFFFF')
    c.fill=PatternFill('solid',fgColor=BK_DARK); ws.row_dimensions[row].height=19
    return row+1

def _bk_note(ws,row,text,ncol,colour=BK_BLUE,height=32):
    ws.merge_cells(start_row=row,start_column=1,end_row=row,end_column=max(ncol,2))
    c=ws.cell(row,1,text); c.font=Font(size=10,color='FFFFFF')
    c.fill=PatternFill('solid',fgColor=colour); c.alignment=Alignment(wrap_text=True,vertical='center')
    ws.row_dimensions[row].height=height
    return row+2

def _bk_table(ws,row,headers,rows,widths,wrapcols=(),colour_col=None):
    for j,h in enumerate(headers,1):
        c=ws.cell(row,j,h); c.font=Font(bold=True,size=10,color='FFFFFF')
        c.fill=PatternFill('solid',fgColor=BK_BLUE); c.border=BK_BOX
        c.alignment=Alignment(horizontal='center',wrap_text=True,vertical='center')
    ws.row_dimensions[row].height=28
    for i,rv in enumerate(rows):
        r=row+1+i
        for j,v in enumerate(rv,1):
            c=ws.cell(r,j,v); c.border=BK_BOX; c.font=Font(size=10)
            if j in wrapcols: c.alignment=Alignment(wrap_text=True,vertical='top')
            if colour_col and j==colour_col and isinstance(v,(int,float)):
                c.fill=PatternFill('solid',fgColor='E8F5EC' if v>0 else 'FCEAE8')
    for j,w in enumerate(widths,1):
        ws.column_dimensions[get_column_letter(j)].width=w
    return row+len(rows)+2

def _bk_chart_bar(ws,title,cat_ref,val_ref,anchor,ncat,x_title,y_title,horizontal=False,numfmt='0.0'):
    ch=BarChart(); ch.type='bar' if horizontal else 'col'; ch.title=title; ch.style=2
    ch.add_data(val_ref,titles_from_data=True); ch.set_categories(cat_ref)
    # sized so the title, axis titles and legend each have room; a cramped chart is why labels
    # collide, not the label settings themselves
    if horizontal:
        ch.height=max(9.0,min(28.0,3.6+0.46*ncat)); ch.width=max(14.0,min(22.0,14.0+0.06*ncat))
    else:
        ch.width=max(14.0,min(32.0,7.5+0.68*ncat)); ch.height=11.5
    ch.gapWidth=40 if ncat>14 else 70
    for ax,t in ((ch.x_axis,x_title),(ch.y_axis,y_title)):
        ax.delete=False; ax.title=t; ax.majorTickMark='out'
    ch.y_axis.numFmt=numfmt
    if ncat<=16:
        ch.dataLabels=DataLabelList(); ch.dataLabels.showVal=True; ch.dataLabels.numFmt=numfmt
    ch.legend=None
    for i,se in enumerate(ch.series):
        se.graphicalProperties=GraphicalProperties(solidFill=BK_PALETTE[i%len(BK_PALETTE)])
    ws.add_chart(ch,anchor); return ch

SPORT_LABEL={'ebasketball':'eBASKETBALL','basketball':'REAL BASKETBALL','efootball':'eFOOTBALL',
             'tennis':'TENNIS','football':'REAL FOOTBALL'}

def _bk_backlink(ws,col):
    """Places the back-link clear of any merged title band. Writing into a merged range raises
    'MergedCell object attribute value is read-only', which is how this was caught."""
    merged_max=0
    for rng in ws.merged_cells.ranges:
        if rng.min_row<=1<=rng.max_row: merged_max=max(merged_max,rng.max_col)
    col=max(col,merged_max+2)
    c=ws.cell(1,col,'← Dashboard'); c.hyperlink="#'Dashboard'!A1"
    c.font=Font(size=10,color='0563C1',underline='single',bold=True)


CHECKPOINT_DIR = LAZ('_lz_ckpt')

def _frame_fingerprint(sport):
    """Cheap content signature for a sport's frame. Checkpoints keyed only on sport name would
    silently reuse stale results after new data arrived — the one way this pipeline can quietly
    return a wrong answer. The fingerprint makes that impossible: change the data and the
    checkpoint stops matching."""
    try:
        path = V46_FRAMES[sport]
        st = os.stat(path)
        import pyarrow.parquet as _pq
        md = _pq.ParquetFile(path).metadata
        return f'{md.num_rows}_{md.num_columns}_{int(st.st_size)}'
    except Exception:
        return 'nofp'

def _ckpt_path(kind, sport):
    """Checkpoint path. The key includes ENGINE_VERSION as well as the data fingerprint.

    Keying on data alone meant a CODE change that altered evaluation silently reused stale
    results — 7 football specs kept reappearing as missing after the bug producing them was
    already fixed."""
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    # ── CODE FINGERPRINT, not just a hand-bumped version string ────────────────────────
    # ENGINE_VERSION was left at v65_13 through every v66-v70 change, and then at v70_1
    # through four more. Both times a run reused ledgers computed before the fixes existed,
    # reported success, and produced a stale book. A human-maintained constant is the wrong
    # mechanism for a correctness guarantee.
    # _laz_code_fingerprint() hashes the functions that actually decide what a ledger
    # contains. Change any of them and the key changes automatically; change a comment or
    # a sheet colour and it does not.
    return os.path.join(CHECKPOINT_DIR,
                        f'{ENGINE_VERSION}_{_laz_code_fingerprint()}_{kind}_{sport}'
                        f'_{_frame_fingerprint(sport)}.pkl')

def assemble_book_inputs(sports, report=None, min_bets_per_segment=100,
                         tier1_wr=None, tier2_wr=None, verbose=True,
                         checkpoint=True, resume=True):
    """Runs the segment evaluation every sport needs for tiering, extracts the bet ledgers for
    whatever validates, and returns the frames build_master_book expects. This is the join between
    the analysis stages and the book, and it is what made the builder external until v49."""
    tier1_wr = TIER1_MIN_WIN_RATE if tier1_wr is None else tier1_wr
    tier2_wr = TIER2_MIN_WIN_RATE if tier2_wr is None else tier2_wr
    rows, trig_rows, ledgers, wf_rows = [], [], {}, []
    import pickle as _pk
    for si, sport in enumerate(sports, 1):
        # A five-sport run takes well over half an hour on a large feed. Checkpointing means a
        # timeout, an OOM or a crash costs one sport, not the whole job.
        ck = _ckpt_path('seg', sport)
        if resume and not os.path.exists(ck):
            import glob as _g
            stale = [x for x in _g.glob(os.path.join(CHECKPOINT_DIR, f'seg_{sport}_*.pkl'))]
            if stale and verbose:
                print(f'[book] ({si}/{len(sports)}) {sport}: data changed since the last run — '
                      f'{len(stale)} stale checkpoint(s) ignored, recomputing')
                for x in stale:
                    try: os.remove(x)
                    except Exception: pass
        if resume and os.path.exists(ck):
            try:
                d = _pk.load(open(ck,'rb'))
                rows += d['rows']; trig_rows += d['trig']; wf_rows += d['wf']
                if verbose: print(f'[book] ({si}/{len(sports)}) {sport}: resumed from checkpoint '
                                  f"({len(d['rows'])} specs)")
                continue
            except Exception:
                pass
        t_sport = time.time()
        if verbose: print(f'[book] ({si}/{len(sports)}) {sport}: evaluating segments...', flush=True)
        _r0, _t0, _w0 = len(rows), len(trig_rows), len(wf_rows)
        _df_fire = None
        if ASSESS_SINGLE_PASS:
            # Fire each spec ONCE against the whole frame and bucket its bets into the five
            # segments afterwards. Verified against the five-slice path: bet counts IDENTICAL,
            # win rates agreeing to the legacy path's own 1-decimal rounding (this path does not
            # round, so it is the more precise of the two). Measured 3-5x faster.
            try:
                _df = decat_for_firing(v46_frame(sport))
                A = assess_single_pass(sport, _df, verbose=verbose)
                for _, r_ in A.iterrows(): rows.append(r_.to_dict())
                reg = V46_REGISTRY[sport]
                for origin, key in (('v44_AB','specs'),('v46_extra','extra'),('v46_recon','recon')):
                    for spec in (reg.get(key) or []):
                        if excluded_for_market(sport, spec): continue
                        trig_rows.append(dict(sport=sport, name=spec['name'],
                            market=spec.get('market','(sport default)'),
                            conditions=[f'{k} = {v_}' for k, v_ in spec.items()
                                        if k not in ('name','why','legacy')],
                            raw=json.dumps({k: v_ for k, v_ in spec.items()
                                            if k not in ('name','why','legacy')},
                                           sort_keys=True, default=str)))
                try:
                    for w in v46_walk_forward(sport): wf_rows.append(w)
                except Exception: pass
                del _df, A; gc.collect()
                if checkpoint:
                    try: _pk.dump(dict(rows=rows[_r0:], trig=trig_rows[_t0:], wf=wf_rows[_w0:]),
                                  open(ck,'wb'))
                    except Exception: pass
                if verbose:
                    print(f'[book]   {sport}: {len(rows)-_r0} specs in {time.time()-t_sport:.0f}s '
                          f'(single pass)', flush=True)
                continue
            except Exception as e:
                if verbose:
                    print(f'[book]   {sport}: single-pass failed ({type(e).__name__}: {e}) '
                          f'-> falling back to five-slice', flush=True)
        df = decat_for_firing(v46_frame(sport))
        # PROJECTION IS OFF BY DEFAULT. Narrowing to the columns inspection says firing needs cut
        # basketball from 46 evaluated specs to ZERO — the fire functions read columns the source
        # scan does not see (built names, indirect lookups). A 40-52% slicing saving is worthless
        # if it silently produces no results, so this is opt-in and must be re-validated per sport
        # against a full-column run before being trusted.
        if ASSESS_PROJECT_COLUMNS:
            df = project_for_assessment(df, sport, verbose=verbose)
        # A 2.7M-row frame read with pandas defaults is float64 throughout plus object strings.
        # Optimising on load rather than after the first slice is copied is what keeps the peak down.
        _optimise_dtypes(df)
        gc.collect()
        if verbose:
            print(f'[book]   {sport}: frame {len(df):,} rows x {df.shape[1]} cols, '
                  f'{df.memory_usage(deep=True).sum()/1024**3:.2f} GB · '
                  f'RSS {memory_report()["rss_gb"]} GB', flush=True)
        q40, q70 = df['mstart'].quantile(0.40), df['mstart'].quantile(0.70)
        half = df['mstart'].quantile(0.50)
        # MEMORY: holding all five segment slices at once OOM-killed a 1.7M-row feed in a 4GB
        # container. Segments are built ONE AT A TIME from boolean masks and released immediately,
        # so peak memory is the frame plus one slice rather than the frame plus five.
        SEG_MASKS = {
            'is':  df['mstart'] <= half,
            'oos': df['mstart'] >  half,
            'bwd': df['mstart'] <= q40,
            'frz': (df['mstart'] > q40) & (df['mstart'] <= q70),
            'fwd': df['mstart'] >  q70,
        }
        reg = V46_REGISTRY[sport]
        groups = [('v44_AB', reg['specs'], reg['fire'])]
        if reg.get('extra'): groups.append(('v46_extra', reg['extra'], reg['wrap']))
        if reg.get('recon'): groups.append(('v46_recon', reg['recon'], reg['reconfire']))
        allspecs = [(o, sp, f) for o, specs, f in groups for sp in specs]
        # eBasketball handicap/totals cannot be staked, so they are not carried into the output.
        # Every other sport is untouched, and handicap VALUES remain usable as conditions.
        _before = len(allspecs)
        allspecs = [(o, sp, f) for o, sp, f in allspecs if not excluded_for_market(sport, sp)]
        if verbose and len(allspecs) != _before:
            print(f'[book]   {sport}: {_before-len(allspecs)} spec(s) excluded — market not '
                  f'accepted by the book', flush=True)
        acc = {sp['name']: dict(sport=sport, origin=o, name=sp['name'])
               for o, sp, f in allspecs}
        dead = set()
        for k, mask in SEG_MASKS.items():
            d = df[mask]
            for o, spec, fire in allspecs:
                if spec['name'] in dead: continue
                try: m = dd_metrics(fire(d, spec))
                except Exception:
                    dead.add(spec['name']); continue
                for f in ('n','wr','odds','roi','ci','maxdd'):
                    acc[spec['name']][f'{k}_{f}'] = m.get(f, np.nan)
            del d; gc.collect()
            if verbose:
                print(f'[book]     {sport} segment {k} done · RSS {memory_report()["rss_gb"]} GB',
                      flush=True)
        del SEG_MASKS; gc.collect()
        del df; gc.collect()
        for o, spec, fire in allspecs:
            if spec['name'] in dead: continue
            rec = acc[spec['name']]
            if not all(f'{k}_n' in rec for k in ('is','oos','fwd','bwd','frz')): continue
            rows.append(rec)
            trig_rows.append(dict(sport=sport, name=spec['name'],
                                  market=spec.get('market','(sport default)'),
                                  conditions=[f'{k} = {v}' for k, v in spec.items()
                                              if k not in ('name','why','legacy')],
                                  raw=json.dumps({k: v for k, v in spec.items()
                                                  if k not in ('name','why','legacy')},
                                                 sort_keys=True, default=str)))
        try:
            for w in v46_walk_forward(sport): wf_rows.append(w)
        except Exception as e:
            if verbose: print(f'[book]   walk-forward failed for {sport}: {type(e).__name__}')
        gc.collect()
        if checkpoint:
            try:
                _pk.dump(dict(rows=rows[_r0:], trig=trig_rows[_t0:], wf=wf_rows[_w0:]),
                         open(ck,'wb'))
            except Exception as e:
                if verbose: print(f'[book]   checkpoint failed: {type(e).__name__}')
        if verbose:
            print(f'[book]   {sport}: {len(rows)-_r0} specs in {time.time()-t_sport:.0f}s', flush=True)
    T = pd.DataFrame(rows)
    seg = ['is','oos','fwd','bwd','frz']
    # A sport can legitimately produce ZERO registry rows — eBasketball's 30 specs all settle on a
    # market the book rejects, so every one is excluded. That is a valid outcome, not an error, and
    # the frame must still carry the expected schema so downstream sheets and tiering work.
    if not len(T):
        cols = ['sport','origin','name'] + [f'{a}_{b}' for a in seg
                                            for b in ('n','wr','odds','roi','ci','maxdd')]
        T = pd.DataFrame(columns=cols)
        for c in cols:
            if c not in ('sport','origin','name'): T[c] = T[c].astype('float64')
        if verbose:
            print(f'[book] no registry specs evaluated for these sports — '
                  f'discovered strategies still assessed')
    for s_ in seg:
        T[f'{s_}_edge'] = (T[f'{s_}_wr'] - 100.0/T[f'{s_}_odds']) if len(T) else pd.Series(dtype='float64')
    if not len(T):
        T['tier'] = pd.Series(dtype='object')
        opwin, hourly, disc = None, None, None
        try: disc, _dm = evaluate_discovered(sports, verbose=verbose)
        except Exception: pass
        return dict(tiers=T, triggers=pd.DataFrame(trig_rows),
                    walkforward=pd.DataFrame(wf_rows) if wf_rows else None,
                    ledgers={}, catalog=T, opwin=None, hourly=None,
                    discovered=disc, _failures=[])
    minn  = T[[f'{s_}_n'    for s_ in seg]].min(axis=1)
    minwr = T[[f'{s_}_wr'   for s_ in seg]].min(axis=1)
    mined = T[[f'{s_}_edge' for s_ in seg]].min(axis=1)
    allroi= (T[[f'{s_}_roi' for s_ in seg]] > 0).all(axis=1)
    allci = (T[[f'{s_}_ci'  for s_ in seg]] > 0).all(axis=1)
    c = TIER_CRITERIA_ODDS_ADJUSTED
    t1 = (minn>=min_bets_per_segment)&(minwr>=tier1_wr)&(mined>=c['min_edge'])&allroi&allci
    t2 = (minn>=min_bets_per_segment)&(minwr> tier2_wr)&(mined>=c['min_edge'])&allroi&(T.oos_ci>0)
    T['tier'] = np.where(t1,'TIER 1 — OMEGA', np.where(t2,'TIER 2 — CHALLENGE','NOT VALIDATED'))
    T = apply_manual_tiers(T, verbose=verbose)   # owner-designated TIER 3
    # v65_v15: the Tier 4/5 ladder used to run only on the combined dashboard table, AFTER the
    # per-sport ledger extraction — so Tier 4/5 strategies never received a one-to-one sheet.
    # Running it here (it never demotes, and is idempotent when the dashboard runs it again)
    # means EVERY tier 1-5 strategy earns a sheet.
    T = assign_high_roi_tiers(T, verbose=verbose)
    val = T[T.tier != 'NOT VALIDATED']
    if verbose:
        print(f'[book] tiering: {int(t1.sum())} Tier 1, {int(t2.sum())} Tier 2, '
              f'{int((T.tier=="NOT VALIDATED").sum())} not validated')
    for sport in sports:                      # ledgers only for what validated
        want = set(val[val.sport==sport]['name'])
        # DO NOT SKIP A SPORT THAT VALIDATED NOTHING. `want` comes from the v44_AB tiering
        # table. Real basketball and real football tiered 0 Tier 1 / 0 Tier 2 / all NOT
        # VALIDATED, so `want` was empty and this line skipped the sport entirely -- before
        # the laz_registry group below ever ran. Their logs show `tiering: 0 Tier 1...`
        # followed straight by `discovered:`, with no REGISTERED line at all, while tennis
        # and eBasketball (which did validate) stored 37 and 158.
        # The registered book does not depend on the v44_AB tiering, so an empty `want`
        # must not stop it. Only skip when there is nothing registered EITHER.
        if not want:
            try:
                _has_reg = any(x.get('enabled') for x in laz_registry().get(sport, []))
            except Exception:
                _has_reg = False
            if not _has_reg:
                continue
            if verbose:
                print(f'[book] {sport}: nothing validated in the tiering table, but the '
                      f'registry has entries — continuing for those', flush=True)
        lck = _ckpt_path('led', sport)
        if resume and os.path.exists(lck):
            try:
                for k, vv in _pk.load(open(lck,'rb')).items(): ledgers[k] = vv
                if verbose: print(f'[book] {sport}: ledgers resumed from checkpoint')
                continue
            except Exception: pass
        if verbose: print(f'[book] {sport}: extracting {len(want)} ledgers...', flush=True)
        _before = dict(ledgers)
        df = v46_frame(sport)
        for cc in df.columns:
            if df[cc].dtype == 'float64': df[cc] = df[cc].astype('float32')
        oos = df[df['mstart'] > df['mstart'].quantile(0.5)]
        reg = V46_REGISTRY[sport]
        # ── v69: the 427 REGISTERED strategies belong in this book too ──────────────
        # The book was built from reg['specs'] plus whatever the discovery pass found on
        # the day. laz_registry() -- 427 entries, each carrying conditions, min_odds and
        # settles, all 14 gates passing -- was never read by the CSV pipeline at all. A
        # completed four-hour run reported "136 strategies" from the production registry
        # and not one of these. They fire here with the same evaluator the rest use, so
        # their ledgers and market labels come out identical in kind.
        groups = [('v44_AB', reg['specs'], reg['fire'])]
        try:
            _lz = [x for x in laz_registry().get(sport, []) if x.get('enabled')]
            if _lz:
                # The pipeline frame does not carry the features these strategies were
                # built against -- nine of tennis's ten are absent. Compute them here with
                # the SAME live engine gate 12 verified at 0.000000, so the book's numbers
                # can match the registered metrics rather than silently firing nothing.
                _want = {c.split()[0] for x in _lz
                         for c in x.get('conditions', []) if isinstance(c, str)}
                oos = _laz_augment_frame(oos, sport, needed=_want, verbose=verbose)
                def _laz_backed_price(frame, spec, sport=sport):
                    """The price of the side this strategy BACKS, as a column.

                    The prepared frame has home_odds and away_odds but no `_o`: which one
                    applies depends on what the strategy backs, and that differs per entry.
                    Tennis S1W backs the SET-1 WINNER; the leader families back whichever
                    side is ahead; totals back the under or the over. Without this every
                    registered strategy was dropped by the odds floor for want of a price
                    column, and the log read "0 ledger(s) stored".
                    """
                    import numpy as _n
                    _b = str(spec.get('backs', '') or '').lower()
                    _m = str(spec.get('market', '') or '').lower()
                    _get = lambda c: (pd.to_numeric(frame[c], errors='coerce')
                                      if c in frame.columns else None)
                    if 'under' in _m or 'under' in _b:
                        for c in ('total_points_under', 'total_goals_under', 'u_odds'):
                            v = _get(c)
                            if v is not None:
                                return v
                    if 'over' in _m or 'over' in _b:
                        for c in ('total_points_over', 'total_goals_over', 'o_odds'):
                            v = _get(c)
                            if v is not None:
                                return v
                    if 'draw' in _m:
                        v = _get('draw_odds')
                        if v is not None:
                            return v
                    _ho, _ao = _get('home_odds'), _get('away_odds')
                    if _ho is None or _ao is None:
                        return None
                    if sport == 'tennis':
                        for _cn in ('set1_winner', 's1_winner', 'set_winner_side'):
                            if _cn in frame.columns:
                                _sl = frame[_cn].astype(str).str.strip().str.lower()
                                return pd.Series(_n.where(_sl == 'home', _ho,
                                                          _n.where(_sl == 'away', _ao, _n.nan)),
                                                 index=frame.index)
                    _h, _a = _get('h_score'), _get('a_score')
                    if _h is not None and _a is not None:
                        _sd = _h - _a
                        return pd.Series(_n.where(_sd > 0, _ho,
                                                  _n.where(_sd < 0, _ao, _n.nan)),
                                         index=frame.index)
                    return _ho

                def _laz_fire(frame, spec):
                    conds = [c for c in (spec.get('conditions') or []) if isinstance(c, str)]
                    try:
                        m = v67_cond_mask(frame, conds)
                    except Exception:
                        return None
                    if m is None:
                        return None
                    # VECTORISED SELECTION. `frame[mask]` copies EVERY column through
                    # pandas take_nd -- profiling 40 eBasketball strategies over 200k rows
                    # showed take_nd alone at 0.508s of 0.676s total. eBasketball ran at
                    # 0.68 ms/tick against eFootball's 0.27 for exactly this reason: it
                    # carries more columns, so every mask copies more.
                    # Resolving the first row per match on numpy indices and taking ONLY
                    # those rows is 2.7x faster and allocates once instead of per column.
                    m = np.asarray(m)
                    # PRICE FIRST. The prepared frame has home_odds/away_odds but no `_o`:
                    # which one applies depends on what this strategy BACKS. Reading `_o`
                    # directly left o_all as None, so min_odds was never applied here and
                    # the row was dropped by the floor further down instead -- every
                    # registered strategy reported "no rows after the odds floor" while its
                    # mask matched perfectly well.
                    _bp = _laz_backed_price(frame, spec)
                    o_all = (pd.to_numeric(frame['_o'], errors='coerce').to_numpy()
                             if '_o' in frame.columns
                             else (pd.to_numeric(_bp, errors='coerce').to_numpy()
                                   if _bp is not None else None))
                    if o_all is not None:
                        lo, hi = spec.get('min_odds'), spec.get('max_odds')
                        if lo is not None:
                            m = m & (o_all >= float(lo) - 1e-9)
                        if hi is not None:
                            m = m & (o_all <= float(hi) + 1e-9)
                    idx = np.flatnonzero(m)
                    if not idx.size:
                        return None
                    mid_all = frame['match_id'].to_numpy()
                    _, pos = np.unique(mid_all[idx], return_index=True)
                    fr = frame.take(np.sort(idx[pos])).copy()
                    if '_o' not in fr.columns and o_all is not None:
                        fr['_o'] = o_all[np.sort(idx[pos])]
                    # SAME SCHEMA AS THE OTHER FIRE FUNCTIONS. Downstream code reads
                    # _odds/_won/_profit and raised KeyError: '_odds' without them -- the
                    # registry ledgers fired correctly and then killed the sport.
                    _oc = next((c for c in ('_o', 'odds_taken', 'odds') if c in fr.columns), None)
                    if _oc is None:
                        return None
                    _odds = pd.to_numeric(fr[_oc], errors='coerce')
                    # SETTLEMENT PER MARKET. Falling through to all-False made every
                    # registered ledger a total loss: the sheet was written, then dropped as
                    # empty. Each market settles differently and the frame carries what each
                    # one needs.
                    if '_w' in fr.columns:
                        _won = fr['_w'].astype(bool)
                    else:
                        _mk2 = str(spec.get('market', '') or '').lower()
                        _bk2 = str(spec.get('backs', '') or '').lower()
                        _fin = next((c for c in ('final_tg', 'final_tp') if c in fr.columns), None)
                        _lin = next((c for c in ('total_goals_handicap_ffill',
                                                 'total_goals_handicap', 'total_points_handicap',
                                                 'open_line') if c in fr.columns), None)
                        if ('under' in _mk2 or 'under' in _bk2) and _fin and _lin:
                            _won = (pd.to_numeric(fr[_fin], errors='coerce')
                                    < pd.to_numeric(fr[_lin], errors='coerce'))
                        elif ('over' in _mk2 or 'over' in _bk2) and _fin and _lin:
                            _won = (pd.to_numeric(fr[_fin], errors='coerce')
                                    > pd.to_numeric(fr[_lin], errors='coerce'))
                        else:
                            # The outcome column is named differently per sport:
                            # final_result in eFootball/eBasketball, final_winner in tennis.
                            # Testing only for final_result left tennis with _won = False on
                            # every row, so 37 ledgers were stored and every one of them was
                            # a total loss -- the numbers looked plausible and were wrong,
                            # which is worse than an empty sheet.
                            _rc = next((c for c in ('final_result', 'final_winner',
                                                    'match_winner', 'winner')
                                        if c in fr.columns), None)
                            _fr2 = (fr[_rc].astype(str).str.strip().str.lower()
                                    if _rc else None)
                            # Which SIDE did this strategy back? Tennis backs the set-1
                            # winner; the leader families back whoever is ahead.
                            _side = None
                            for _cn in ('set1_winner', 's1_winner', 'set_winner_side',
                                        'side_lead', 'leading_team_rt'):
                                if _cn in fr.columns:
                                    _side = fr[_cn].astype(str).str.strip().str.lower()
                                    break
                            if _side is None and {'h_score', 'a_score'}.issubset(fr.columns):
                                _sd2 = (pd.to_numeric(fr['h_score'], errors='coerce')
                                        - pd.to_numeric(fr['a_score'], errors='coerce'))
                                _side = pd.Series(np.where(_sd2 > 0, 'home',
                                                           np.where(_sd2 < 0, 'away', '')),
                                                  index=fr.index)
                            _won = ((_fr2 == _side)
                                    if (_fr2 is not None and _side is not None)
                                    else pd.Series(False, index=fr.index))
                    fr['_odds'] = _odds.values
                    fr['_won'] = _won.values
                    fr['_profit'] = np.where(_won.values, _odds.values - 1.0, -1.0)
                    if 'ts' not in fr.columns:
                        fr['ts'] = pd.RangeIndex(len(fr))
                    return fr
                groups.append(('laz_registry', _lz, _laz_fire))
                # AUGMENT THE FRAME BEFORE FIRING. _laz_fire evaluates conditions against
                # `oos`, which is the PREPARED frame -- it does not carry anchor, s1w_pre,
                # wall_min, cb_prog or any of the other registered features. Without this
                # every registered strategy queued, matched nothing, and the log read
                # "37 REGISTERED strategies queued" followed by "0 ledger(s) stored".
                # The features are computed once here, not per strategy.
                try:
                    _rw = {c.split()[0] for x in _lz for c in x.get('conditions', [])
                           if isinstance(c, str)}
                    oos = _laz_augment_frame(oos, sport, needed=_rw, verbose=verbose)
                except Exception as _ae:
                    print(f'[book]   {sport}: augment failed '
                          f'({type(_ae).__name__}: {str(_ae)[:70]}) — registered strategies '
                          f'will not fire')
                print(f'[book]   {sport}: {len(_lz)} REGISTERED strategies queued')
        except Exception as _e:
            print(f'[book]   {sport}: laz_registry not attached '
                  f'({type(_e).__name__}: {str(_e)[:70]})')
        if reg.get('extra'): groups.append(('v46_extra', reg['extra'], reg['wrap']))
        if reg.get('recon'): groups.append(('v46_recon', reg['recon'], reg['reconfire']))
        for origin, specs, fire in groups:
            for spec in specs:
                # laz_registry entries are not in `want` -- that set comes from the
                # v44_AB tiering table. They have already cleared 14 gates; do not
                # re-filter them out of their own book.
                if origin != 'laz_registry' and spec['name'] not in want: continue
                try:
                    fr = fire(oos, spec)
                except Exception as _fe:
                    # NEVER SILENT for the registered book. A bare `continue` hid the reason
                    # 427 strategies produced no ledgers: they fired, then died on a schema
                    # mismatch, and the run still reported success.
                    if origin == 'laz_registry':
                        print(f'[book]   {sport}/{spec.get("name","?")}: fire FAILED '
                              f'{type(_fe).__name__}: {str(_fe)[:80]}')
                    continue

                # COLUMN NAME. The v44_AB fire functions emit `_odds`; _laz_fire returns the
                # prepared frame, whose price column is `_o`. Applying the floor against a
                # column that is not there silently produced an empty frame, so every
                # registered strategy fired, matched, and was then dropped one line later --
                # "37 REGISTERED strategies queued ... 0 ledger(s) stored".
                if origin == 'laz_registry' and fr is not None and '_odds' not in fr.columns:
                    _oc = next((c for c in ('_o', 'odds_taken', 'odds') if c in fr.columns), None)
                    if _oc:
                        fr = fr.copy()
                        fr['_odds'] = fr[_oc]
                fr = _apply_global_odds_floor(fr, '_odds')   # v65_v15 entry floor
                if fr is None or len(fr)==0:
                    if origin == 'laz_registry':
                        print(f'[book]   {sport}/{spec.get("name","?")}: no rows after the '
                              f'odds floor')
                    continue
                if 'match_id' not in fr.columns: fr = fr.reset_index()
                L = pd.DataFrame({'match_id': fr['match_id'].values, 'placed': fr['ts'].values})
                L['phase'] = fr['phase'].astype(str).values if 'phase' in fr.columns else None
                L['odds'] = fr['_odds'].values; L['stake'] = 1.0
                L['outcome'] = np.where(fr['_won'].values,'WIN','LOSS')
                L['profit'] = np.round(fr['_profit'].values,2)
                ledgers[(sport,spec['name'])] = (origin, spec, L.sort_values('placed').reset_index(drop=True))
        _n_reg = sum(1 for _k, _v in ledgers.items()
                     if isinstance(_v, (tuple, list)) and len(_v) == 3
                     and _v[0] == 'laz_registry')
        if verbose:
            print(f'[book]   {sport}: {_n_reg} REGISTERED ledger(s) stored')
        del df, oos; gc.collect()
        if checkpoint:
            try:
                new = {k: vv for k, vv in ledgers.items() if k not in _before}
                with open(lck, 'wb') as _fhp:   # [v246-HND]
                    _pk.dump(new, _fhp)
            except Exception: pass
    # EVERY discovered strategy from EVERY version is fired here. Without this the registry is
    # storage, not evaluation: 431 of 631 strategies never ran in a pipeline pass.
    disc = None
    _disc_rows = []
    try:
        disc, dmiss = (evaluate_discovered_fast(sports, verbose=verbose)
                       if EVALUATE_DISCOVERED_FAST else evaluate_discovered(sports, verbose=verbose))
        # DISCOVERED strategies need ledgers too, or they get no one-to-one sheet. eBasketball's
        # entire tradeable set is discovered — it produced 26 registry sheets and none for its 103.
        for _sp in sports:
            try:
                _dl, _dr = build_discovered_ledgers(_sp, disc, verbose=verbose)
                ledgers.update(_dl)
                if _dr: _disc_rows.extend(_dr)
            except Exception as _e:
                if verbose: print(f'[book]   {_sp}: discovered ledgers failed ({type(_e).__name__})')
        if verbose:
            print(f'[book] discovered strategies evaluated: {len(disc)} '
                  f'({len(dmiss)} could not be evaluated)')
    except Exception as e:
        if verbose: print(f'[book] discovered evaluation failed: {type(e).__name__}: {e}')
    opwin, hourly = None, None
    try:
        opwin, hourly = compute_sheet_extras(sports, T, verbose=verbose)
    except Exception as e:
        if verbose: print(f'[book] extras unavailable: {type(e).__name__}: {e}')
    if _disc_rows:
        T = pd.concat([T, pd.DataFrame(_disc_rows)], ignore_index=True, sort=False)
    return dict(tiers=T, triggers=pd.DataFrame(trig_rows),
                walkforward=pd.DataFrame(wf_rows) if wf_rows else None,
                ledgers=ledgers, catalog=T, opwin=opwin, hourly=hourly,
                discovered=disc, _failures=[])


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v50 SECTION N — THE REMAINING SHEET BUILDERS, AND FAULT ISOLATION
# ═══════════════════════════════════════════════════════════════════════════════════════
#  A book build over five sports and a large feed is a long job. Losing it at sheet 30 because one
#  table hit an unexpected null is unacceptable, so every sheet here is built inside its own guard:
#  a failure is recorded and skipped, and the rest of the book still ships. The failures are returned
#  in the build report rather than swallowed, so nothing fails silently.

def _bk_guard(wb, name, fn, failures, verbose=True):
    """Builds one sheet. On failure records it and moves on rather than losing the whole run."""
    try:
        fn()
        return True
    except Exception as e:
        failures.append((name, f'{type(e).__name__}: {e}'))
        if verbose: print(f'[book]   ! {name} skipped — {type(e).__name__}: {e}')
        if name in wb.sheetnames:
            try: del wb[name]
            except Exception: pass
        return False

def compute_sheet_extras(sports, tiers, verbose=True):
    """Derives what the analysis sheets need but the tier pass does not produce: opportunity-window
    durations from the fired masks, and profit by hour of the feed clock."""
    opwin, hourly = [], []
    val = tiers[tiers.tier != 'NOT VALIDATED'] if 'tier' in tiers.columns else tiers
    for sport in sports:
        want = set(val[val.sport == sport]['name'])
        if not want: continue
        df = v46_frame(sport)
        for c in df.columns:
            if df[c].dtype == 'float64': df[c] = df[c].astype('float32')
        oos = df[df['mstart'] > df['mstart'].quantile(0.5)].reset_index(drop=True)
        del df; gc.collect()
        mid, ts = oos['match_id'].values, oos['ts'].values
        reg = V46_REGISTRY[sport]
        groups = [('v44_AB', reg['specs'], reg['fire'])]
        if reg.get('extra'): groups.append(('v46_extra', reg['extra'], reg['wrap']))
        if reg.get('recon'): groups.append(('v46_recon', reg['recon'], reg['reconfire']))
        for origin, specs, fire in groups:
            for spec in specs:
                if spec['name'] not in want: continue
                try: fr = fire(oos, spec)
                except Exception: continue
                if fr is None or len(fr) == 0: continue
                h = pd.DataFrame({'hr': pd.to_datetime(fr['ts']).dt.hour,
                                  'profit': fr['_profit'].astype(float)})
                g = h.groupby('hr')['profit'].agg(['size','sum'])
                rec = dict(sport=sport, name=spec['name'])
                for hh in range(24):
                    rec[f'h{hh}'] = round(float(g['sum'].get(hh, 0.0)), 2)
                    rec[f'n{hh}'] = int(g['size'].get(hh, 0))
                q = g[g['size'] >= max(5, 0.01*len(h))]
                rec['best_hours']  = sorted(q.index[q['sum'] > 0].tolist())
                rec['worst_hours'] = sorted(q.index[q['sum'] < 0].tolist())
                hourly.append(rec)
                m = _V44_LAST_MASK.get('mask')
                if m is not None and len(m) == len(oos):
                    mv = np.asarray(m.fillna(False) if hasattr(m, 'fillna') else m, dtype=bool)
                    if mv.any():
                        d = pd.DataFrame({'mid': mid[mv], 'ts': ts[mv]})
                        gg = d.groupby('mid')['ts'].agg(['min','max','size'])
                        dur = (gg['max'] - gg['min']).dt.total_seconds()/60.0
                        opwin.append(dict(sport=sport, name=spec['name'],
                                          min_win=float(dur.min()), med_win=float(dur.median()),
                                          avg_win=float(dur.mean()), max_win=float(dur.max()),
                                          avg_ticks=float(gg['size'].mean()), n_matches=int(len(gg))))
                gc.collect()
        del oos; gc.collect()
    if verbose:
        print(f'[book] extras: {len(hourly)} hourly profiles, {len(opwin)} opportunity windows')
    return (pd.DataFrame(opwin) if opwin else None), (pd.DataFrame(hourly) if hourly else None)

def _fmt_hours(v):
    v = list(v) if isinstance(v, (list, tuple, np.ndarray)) else []
    if not v: return 'none'
    out, a, p = [], v[0], v[0]
    for h in list(v[1:]) + [None]:
        if h is not None and h == p+1: p = h; continue
        out.append(f'{a:02d}:00-{p:02d}:59' if a != p else f'{a:02d}:00')
        a = p = h if h is not None else a
    return ' '.join(out)

