    if hourly is not None:
        M = M.merge(hourly[['sport','name','best_hours','worst_hours']], on=['sport','name'], how='left')
    for c in ('min_win','med_win','avg_win','max_win','avg_ticks','n_matches','best_hours','worst_hours'):
        if c not in M.columns: M[c] = np.nan

