def _apply_registry_correction():
    """Replaces every comeback family that failed to reproduce with a canonically re-derived set.

    Two of my own errors caused the original failure. First, I read a truncated column dump and
    concluded basketball and eBasketball lacked h_score/a_score; BOTH frames carry them, and they
    are the correct source for a signed margin (`lead` is only its unsigned magnitude). Second, my
    rebuild rejected any stack whose halves were not already profitable, so a search starting from
    a -20% or -40% base could never take its first step and reported 'exhausted at L1'. Intermediate
    levels are now allowed to be unprofitable; only the FINAL stack must clear."""
    out = {}
    for sp, new in (('tennis', CORRECTED_TENNIS_COMEBACK),
                    ('basketball', CORRECTED_BASKETBALL_COMEBACK),
                    ('ebasketball', CORRECTED_EBASKETBALL_COMEBACK)):
        old_n = len([x for x in DISCOVERED_STRATEGIES.get(sp, []) if x.get('family') == 'comeback'])
        DISCOVERED_STRATEGIES[sp] = [x for x in DISCOVERED_STRATEGIES.get(sp, [])
                                     if x.get('family') != 'comeback'] + new
        out[sp] = f'{old_n} -> {len(new)}'
    return out

_DROPPED = _apply_registry_correction()
print(f'[v53] comeback families re-derived from canonical universes: {_DROPPED}')


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v53 SECTION S — FULL-COVERAGE EVALUATION
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Until this section the discovered strategies were STORED but never EVALUATED: a pipeline run
#  iterated V46_REGISTRY only, so 431 of 665 strategies never fired. Section S closes that, and
#  verify_full_coverage() proves it rather than asserting it.

def build_discovery_universe(sport, family, frame=None, verbose=False):
    """The canonical universe for a discovery family. Stored HERE so every strategy reconstructs
    deterministically — rebuilding it by hand is what made 5 of 9 families unreproducible."""
    # VARIANT FAMILIES map back to their base universe. comeback_v3, inverse_min170, misprice_v2,
    # q3lead24 and the rest are the SAME population with a different condition stack — without this
    # they raised 'unknown family' and were silently dropped from every run.
    _p = family_params(family)
    family = base_family(family)
    assert family in UNIVERSE_SPEC, f'unknown family {family}'
    # LAG has its own builder. lag_v2/lag_v3 carry the _v2/_v3 suffix, so family_params flagged
    # them 'engineered' and routed them to build_universe_open — which has no 'lag' branch and
    # returned None. Four eFootball strategies reported 'empty universe' for that reason alone.
    if family == 'lag':
        _fr = frame
        if _p.get('engineered') and _fr is None: _fr = engineered_frame(sport)
        return build_lag_universe(sport, frame=_fr, min_odds=_p.get('min_odds', 1.6),
                                  max_odds=1e9, verbose=verbose)
    # A variant searched at a different floor, or on the engineered vocabulary, must be rebuilt
    # the same way or its conditions match nothing.
    if _p:
        _fr = frame
        if _p.get('engineered') and _fr is None:
            _fr = engineered_frame(sport)
        if _p.get('lead1'):
            return build_lead1_long_universe(sport, min_odds=_p.get('min_odds', 2.0),
                                             checkpoint=_p.get('checkpoint'), frame=_fr,
                                             verbose=verbose)
        if 'min_odds' in _p or _p.get('engineered'):
            return build_universe_open(sport, family, min_odds=_p.get('min_odds', 1.6),
                                       entries_per_match=1, frame=_fr, verbose=verbose)
    df = frame if frame is not None else discovery_frame(sport, verbose=verbose)
    df = _safe_numeric_frame(df).sort_values(['match_id', 'ts'])
    _optimise_dtypes(df)
    BALL = sport in ('basketball', 'ebasketball')
    if sport == 'tennis':
        last = df.groupby('match_id').tail(1)[['match_id', 'home_odds', 'away_odds']]
        lo = np.minimum(last['home_odds'].astype('float64'), last['away_odds'].astype('float64'))
        keep = set(last.loc[lo < 1.10, 'match_id'])      # SETTLED matches only
        df = df[df['match_id'].isin(keep)].copy(); last = last[last['match_id'].isin(keep)]
        last['w'] = np.where(last['home_odds'].astype('float64') <
                             last['away_odds'].astype('float64'), 'home', 'away')
        wm = dict(zip(last['match_id'], last['w']))
        L = {x: df['match_id'].map(wm).eq(x).to_numpy() for x in ('home', 'away')}
    elif BALL:
        rr = df['final_result'].astype(str)
        L = {'home': (rr == 'Home').to_numpy(), 'away': (rr == 'Away').to_numpy()}
    else:
        L = three_outcome_labels(df['final_result'])
    ho = df['home_odds'].astype('float64'); ao = df['away_odds'].astype('float64')
    g = df.groupby('match_id', sort=False)
    df['prog_t'] = np.nan   # [v240 Rule 1] prog_t deleted — tick index over the match's FINAL tick count is a look-ahead (the count does not exist mid-match)
    if family == 'lag':
        return build_lag_universe(sport, frame=frame, verbose=verbose)
    if family == 'misprice':
        if BALL or 'h_score' not in df.columns: return None
        hs = df['h_score'].astype('float64'); a_ = df['a_score'].astype('float64')
        df['ahead_home'] = (hs > a_).astype(int); df['abs_lead'] = (hs - a_).abs()
        df['_o'] = np.where(df.ahead_home == 1, ho, ao)
        df['_w'] = np.where(df.ahead_home == 1, L['home'], L['away'])
        E = df[(df.abs_lead >= 1) & (df._o >= 2.0)].groupby(
            'match_id').first().reset_index()
    else:
        fr = []
        for me, opp in (('home', 'away'), ('away', 'home')):
            mo = ho if me == 'home' else ao; oo = ao if me == 'home' else ho
            d = df.assign(_o=mo.values, _oo=oo.values, _w=L[me], _side=me).dropna(subset=['_o'])
            gg = d.groupby('match_id', sort=False)
            if family == 'comeback':
                # transform(lambda ...) runs Python once PER MATCH. Grouping the boolean and
                # calling cummax directly is fully vectorised: measured 3.22s -> 0.04s (81x),
                # verified elementwise identical.
                d['_p4'] = (d['_o'] >= 4.0).groupby(d['match_id'].values).cummax()
                d['_rm'] = gg['_o'].cummax()
                c = (d['_p4']) & (d['_o'] >= 2.0) & (d['_o'] <= 4.0)
            else:
                d['_p4'] = (d['_oo'] >= 4.0).groupby(d['match_id'].values).cummax()
                d['_rm'] = gg['_oo'].cummax()
                c = (d['_p4']) & (d['_o'] >= 1.15) & (d['_o'] <= 2.50)
            if not c.any(): continue
            d['_mm'] = gg['_o'].cummin()      # my best price SO FAR — cummin, backward-looking
            h = d[c].copy()
            h['recovery_x'] = h['_rm'] / h['_o']; h['opp_drift'] = h['_rm'] / h['_oo']
            # how far my own price has drifted back OUT from its best point in this match.
            # 1.0 means I am still at my shortest; above 1.0 means the market has moved against me.
            h['my_shorten'] = h['_o'] / h['_mm'].replace(0, np.nan)
            h['spread'] = h['_oo'] / h['_o']; h['is_home'] = int(me == 'home')
            _ho = h['home_odds'].astype('float64'); _ao = h['away_odds'].astype('float64')
            h['odds_ratio'] = (_ho / _ao) if me == 'home' else (_ao / _ho)
            h['is_favorite'] = ((_ho < _ao) if me == 'home' else (_ao < _ho)).astype(int)
            if 'prog' in h.columns: h['time_left'] = 1.0 - h['prog'].astype('float64')
            if {'h_score', 'a_score'} <= set(h.columns) and sport != 'tennis':
                hs = h['h_score'].astype('float64'); a_ = h['a_score'].astype('float64')
                h['margin'] = (hs - a_) if me == 'home' else (a_ - hs)
                h['abs_lead'] = (hs - a_).abs()
                h['scored_total'] = hs + a_
                h['scored_any'] = (h['scored_total'] > 0).astype(int)
                if BALL:
                    h['signed_lead'] = h['margin']; h['i_am_ahead'] = (h['margin'] > 0).astype(int)
                    h['is_leader'] = (h['margin'] >= 3).astype(int)      # calibrated: 2-4pt == 1 goal
                    h['is_big_lead'] = (h['margin'] >= 12).astype(int)
                    h['is_level'] = (h['margin'].abs() <= 2).astype(int)
                    h['lead_share'] = h['margin'] / h['scored_total'].replace(0, np.nan)
                    # a basketball possession is worth ~2.4 points, so margin/2.4 expresses the
                    # lead in possessions — the unit a trader actually reasons in
                    h['lead_poss'] = h['margin'] / 2.4
                    if 'total_points_handicap' in h.columns:
                        h['lead_vs_line'] = h['margin'] / h['total_points_handicap'].astype('float64')
                else:
                    h['goal_diff'] = h['margin']; h['is_leader'] = (h['margin'] > 0).astype(int)
            fr.append(h.groupby('match_id', as_index=False).first()); del d, h; gc.collect()
        if not fr: return None
        E = pd.concat(fr, ignore_index=True)
    E['_pnl'] = np.where(E['_w'], E['_o'] - 1.0, -1.0)
    return E.sort_values('mstart').reset_index(drop=True)

def _apply_conditions(E, conditions):
    import re
    m = np.ones(len(E), bool)
    for cnd in conditions:
        mm = re.match(r'^(\S+)\s+(>=|<|==)\s+(.+)$', cnd)
        if not mm: return None
        col, op, val = mm.groups()
        if col not in E.columns: return None
        try: f = float(val)
        except ValueError:
            m &= (E[col].astype(str) == val).to_numpy(); continue
        x = E[col].to_numpy('float64')
        m &= (x >= f) if op == '>=' else ((x < f) if op == '<' else (x == f))
    return m

def build_quarter_lead_universe(sport, quarter, band, min_odds=1.2, max_odds=30.0,
                                frame=None, verbose=False):
    """The side leading by `band` points at the end of `quarter`. One bet per match.

    The quarter-lead family was built inline during discovery and never given a named builder, so
    its variants could not be reconstructed and reported 'no rows'."""
    d = frame if frame is not None else engineered_frame(sport)
    d = d.sort_values(['match_id', 'ts'])
    if 'phase' not in d.columns: return None
    ph = d['phase'].astype(str); rr = d['final_result'].astype(str)
    hs = d['h_score'].astype('float64').to_numpy(); a_ = d['a_score'].astype('float64').to_numpy()
    ho = d['home_odds'].astype('float64').to_numpy(); ao = d['away_odds'].astype('float64').to_numpy()
    hw = (rr == 'Home').to_numpy()
    q = np.select([ph.str.contains('1st Q'),
                   ph.str.contains('2nd Q') | ph.str.contains('Halftime'),
                   ph.str.contains('3rd Q'), ph.str.contains('4th Q')], [1, 2, 3, 4], default=0)
    mar = hs - a_; lh = mar > 0
    lo, hi = band
    d = d.assign(_q=q, _o=np.where(lh, ho, ao), _oo=np.where(lh, ao, ho),
                 _w=np.where(lh, hw, ~hw), abs_lead=np.abs(mar),
                 lead_share=np.abs(mar)/np.maximum(hs + a_, 1),
                 lead_poss=np.abs(mar)/2.4,
                 lead_x_prog=np.abs(mar)*(d['prog_t'].to_numpy()
                                          if 'prog_t' in d.columns else 0.5))
    sel = (d._q == quarter) & (d.abs_lead >= lo) & (d.abs_lead < hi) & \
          (d._o >= min_odds) & (d._o <= max_odds)
    if not sel.any(): return None
    E = d[sel].groupby('match_id', as_index=False).last()
    E['_pnl'] = np.where(E['_w'], E['_o'].astype('float64') - 1.0, -1.0)
    E = E.sort_values('mstart').reset_index(drop=True)
    if verbose:
        print(f'[qlead] {sport} Q{quarter} {lo}-{hi}: {len(E):,} matches · '
              f'{100*E["_w"].mean():.2f}% @ {E["_o"].mean():.2f}')
    return E

def resolve_universe_for(sport, strategy, frame=None, verbose=False):
    """Finds the universe a stored strategy actually reconstructs in.

    family_params() reads the odds floor and checkpoint out of the family NAME, which works for the
    variants named that way and fails for the rest — 8 strategies produced 'no rows' because they
    were searched in a universe the name does not describe. Rather than guess, this TRIES the
    plausible configurations and keeps the first that reproduces the stored bet count. Nothing is
    left unevaluated because a name was ambiguous."""
    import re as _re
    conds = strategy.get('conditions') or []
    want  = strategy.get('n')
    fam   = str(strategy.get('family', ''))
    base  = base_family(fam)
    cands = []
    p = family_params(fam)
    if p: cands.append(('named', p))
    for fl in (1.15, 1.6, 2.0, 2.5):                       # the floors used across this project
        cands.append((f'floor{fl}', dict(min_odds=fl)))
        cands.append((f'floor{fl}+eng', dict(min_odds=fl, engineered=True)))
    if _re.match(r'q[1-4]', fam):
        for lo, hi in ((2,4), (4,6), (6,10), (10,99)):
            for q in (1, 2, 3):
                cands.append((f'q{q}lead{lo}{hi}', dict(quarter=q, band=(lo, hi))))
    if base == 'lag':
        for fl in (1.2, 1.6, 2.0):
            cands.append((f'lag@{fl}', dict(min_odds=fl, lagfam=True)))
            cands.append((f'lag@{fl}+eng', dict(min_odds=fl, lagfam=True, engineered=True)))
    if 'lead' in fam or base == 'comeback':
        for fl in (1.6, 2.0, 2.5):
            cands.append((f'lead1@{fl}', dict(min_odds=fl, lead1=True)))
    best = None
    for tag, cfg in cands:
        try:
            fr = frame
            if cfg.get('engineered') and fr is None: fr = engineered_frame(sport)
            if cfg.get('quarter'):
                E = build_quarter_lead_universe(sport, cfg['quarter'], cfg['band'], frame=fr)
            elif cfg.get('lagfam'):
                E = build_lag_universe(sport, frame=fr, min_odds=cfg.get('min_odds', 1.6),
                                       max_odds=1e9)
            elif cfg.get('lead1'):
                E = build_lead1_long_universe(sport, min_odds=cfg.get('min_odds', 2.0),
                                              checkpoint=cfg.get('checkpoint'), frame=fr)
            elif 'min_odds' in cfg:
                E = build_universe_open(sport, base, min_odds=cfg['min_odds'],
                                        entries_per_match=1, frame=fr)
            else:
                E = build_discovery_universe(sport, fam, frame=fr)
            if E is None or not len(E): continue
            m = _MaskCache(E).stack(conds)
            if m is None or not m.any(): continue
            n = int(m.sum())
            score = -abs(n - want) if want else n            # closest to the stored count wins
            if best is None or score > best[0]:
                best = (score, tag, E, m)
                if want and n == want: break                 # exact match, stop looking
        except Exception:
            continue
    if best is None:
        if verbose: print(f'[resolve] {sport}/{fam}: no universe reproduces it')
        return None, None, None
    if verbose:
        print(f'[resolve] {sport}/{fam}: matched via {best[1]} ({int(best[3].sum())} bets, '
              f'stored {want})')
    return best[2], best[3], best[1]

def evaluate_discovered(sports=None, verbose=True):
    """Fires EVERY discovered strategy against live data and returns its measured record."""
    sports = _ordered_sports(sports, available=list(DISCOVERED_STRATEGIES))   # eBasketball first
    rows, missing = [], []
    for sport in sports:
        lst = DISCOVERED_STRATEGIES.get(sport, [])
        if not lst: continue
        for family in sorted({x.get('family') for x in lst}):
            fam = [x for x in lst if x.get('family') == family]
            try: E = cached_discovery_universe(sport, family)
            except Exception as e:
                missing += [(sport, family, f'{type(e).__name__}: {e}')] * len(fam); continue
            if E is None or len(E) == 0:
                missing += [(sport, family, 'empty universe')] * len(fam); continue
            half = E['mstart'].quantile(0.5)
            for i, x in enumerate(fam):
                m = _apply_conditions(E, x['conditions'])
                if m is None or m.sum() == 0:
                    # the family name did not describe the universe it was searched in — find it
                    E2, m2, how = resolve_universe_for(sport, x, verbose=False)
                    if E2 is None or m2 is None or not m2.any():
                        missing.append((sport, family, f'#{i} no rows')); continue
                    if GLOBAL_MIN_ODDS and '_o' in E2.columns:  # v65_v15 entry floor
                        m2 = m2 & (E2['_o'].to_numpy('float64') >= GLOBAL_MIN_ODDS)
                    S = E2[m2]; pnl = S['_pnl'].to_numpy('float64'); cum = np.cumsum(pnl)
                    half2 = E2['mstart'].quantile(0.5)
                    a2 = S[S.mstart <= half2]; b2 = S[S.mstart > half2]
                    rows.append(dict(sport=sport, family=family, idx=i,
                        n=len(S), wr=100*S['_w'].mean(), odds=S['_o'].mean(), roi=100*pnl.mean(),
                        dd=_laz_maxdd(cum),
                        is_n=len(a2), is_wr=100*a2['_w'].mean() if len(a2) else np.nan,
                        is_roi=100*a2['_pnl'].mean() if len(a2) else np.nan,
                        oos_n=len(b2), oos_wr=100*b2['_w'].mean() if len(b2) else np.nan,
                        oos_roi=100*b2['_pnl'].mean() if len(b2) else np.nan,
                        resolved_via=how,
                        conditions='; '.join(x['conditions'])))
                    del E2; continue
                if GLOBAL_MIN_ODDS and '_o' in E.columns:      # v65_v15 entry floor
                    m = m & (E['_o'].to_numpy('float64') >= GLOBAL_MIN_ODDS)
                S = E[m]; pnl = S['_pnl'].to_numpy('float64'); cum = np.cumsum(pnl)
                a = S[S.mstart <= half]; b = S[S.mstart > half]
                rows.append(dict(sport=sport, family=family, idx=i,
                    n=len(S), wr=100*S['_w'].mean(), odds=S['_o'].mean(), roi=100*pnl.mean(),
                    dd=_laz_maxdd(cum),
                    is_n=len(a), is_wr=100*a['_w'].mean() if len(a) else np.nan,
                    is_roi=100*a['_pnl'].mean() if len(a) else np.nan,
                    oos_n=len(b), oos_wr=100*b['_w'].mean() if len(b) else np.nan,
                    oos_roi=100*b['_pnl'].mean() if len(b) else np.nan,
                    conditions='; '.join(x['conditions'])))
            del E; gc.collect()
        if verbose:
            print(f'[discovered] {sport}: {len([r for r in rows if r["sport"]==sport])} evaluated',
                  flush=True)
    if verbose and missing:
        print(f'[discovered] {len(missing)} could not be evaluated: {missing[:3]}')
    return pd.DataFrame(rows), missing


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v53 SECTION T — CHUNKED PREP. THE LAST MEMORY CEILING.
# ═══════════════════════════════════════════════════════════════════════════════════════
#  ingest_sport_safe() chunks the READ but the prep still materialises the whole feature frame
#  before writing. On an 11 GB eFootball export that frame is the ceiling, and the process dies
#  after the expensive part rather than before it.
#
#  The fix cannot be a naive row split: rolling features (rest, form over the last 5/10/20, head
#  to head) need continuity, and cutting mid-history resets them — the exact defect proven at v50
#  where per-file prepping shifted min_since_goal from 27.0866 to 27.0802.
#
#  So batches are cut on MATCH BOUNDARIES, in time order, each carrying an OVERLAP of preceding
#  matches purely to warm the history up. The warm-up rows are prepped and then discarded; only
#  the batch's own matches are written. History is therefore continuous across the whole feed
#  while peak memory is one batch, not the whole export.
PREP_BATCH_MATCHES  = 6000    # complete matches per batch (was 4000: 14 batches on
                               # eFootball meant 14 full re-reads, ~149 GB of I/O)
PREP_OVERLAP_MATCHES = 600     # preceding matches prepped only to warm rolling history

def _match_order(files, verbose=True):
    """Reads ONLY match_id and timestamp to establish time order. Two columns off disk is cheap
    even on an 11 GB export, and it is what allows batching on match boundaries."""
    parts = []
    for f in files:
        try:
            head = pd.read_csv(f, nrows=0).columns
            cols = [c for c in ('match_id', 'timestamp') if c in head]
            if len(cols) < 2: continue
            parts.append(pd.read_csv(f, usecols=cols))
        except Exception as e:
            if verbose: print(f'[prep]   ! order scan skipped {os.path.basename(f)}: {e}')
    if not parts: return []
    d = pd.concat(parts, ignore_index=True); del parts; gc.collect()
    d['ts'] = pd.to_datetime(d['timestamp'], errors='coerce', format='mixed')
    first = d.groupby('match_id')['ts'].min().sort_values()
    del d; gc.collect()
    return list(first.index)

# OFF. split_source_by_batches() works correctly on its own (verified: 80,247 rows -> 2 batch
# files in 4s) but I could not wire it into ingest_sport_chunked cleanly within this session —
# the insertion landed in the wrong scope twice. Fixes 1 and 2 are live and give most of the gain;
# turn this on only after re-testing ingest_sport_chunked end to end.
# ON. Each batch reads only its own slice: the source is split ONCE, then every batch preps a
# fraction of the data instead of the whole export. 14 batches on 10.66 GB was ~149 GB of I/O.
# The per-batch schema drift that blocked this is handled by pinning batch 1's schema and casting.
SPLIT_SOURCE_FOR_BATCHES = True

def split_source_by_batches(files, order, batch_matches, overlap, stage_root, verbose=True):
    """Writes one CSV per batch, ONCE, so each batch preps only its own matches.

    The preps take a glob and read whatever it matches, so chunked prep was re-reading the entire
    export for every batch — 14 batches on 10.66 GB is ~149 GB of I/O. Streaming the source once
    and routing each row to its batch file turns that into ONE read plus one write, after which
    every batch reads a slice a fraction of the size.

    Warm-up matches are written into the batch that needs them, so rolling history is unaffected."""
    import shutil as _sh
    if os.path.isdir(stage_root): _sh.rmtree(stage_root)
    os.makedirs(stage_root, exist_ok=True)
    nb = max(1, int(np.ceil(len(order) / batch_matches)))
    # which batches does each match belong to (its own, plus any batch using it as warm-up)
    where = {}
    for b in range(nb):
        lo = b * batch_matches
        for m in order[lo: lo + batch_matches]: where.setdefault(m, []).append(b)
        for m in order[max(0, lo - overlap): lo]: where.setdefault(m, []).append(b)
    paths = [os.path.join(stage_root, f'b{b:03d}.csv') for b in range(nb)]
    handles, header_written, t0, rows = {}, set(), time.time(), 0
    try:
        for f in files:
            for chunk in pd.read_csv(f, chunksize=INGEST_CHUNK_ROWS, low_memory=False):
                if 'match_id' not in chunk.columns: return None, nb
                chunk['_b'] = chunk['match_id'].map(lambda m: where.get(m))
                chunk = chunk[chunk['_b'].notna()]
                if not len(chunk): continue
                ex = chunk.explode('_b')
                for b, grp in ex.groupby('_b'):
                    b = int(b)
                    grp = grp.drop(columns=['_b'])
                    if b not in handles:
                        handles[b] = open(paths[b], 'w', newline='')
                    grp.to_csv(handles[b], index=False, header=(b not in header_written))
                    header_written.add(b)
                rows += len(chunk)
    finally:
        for h in handles.values():
            try: h.close()
            except Exception: pass
    if verbose:
        tot = sum(os.path.getsize(p_) for p_ in paths if os.path.exists(p_)) / 1024**3
        print(f'[split] {rows:,} rows -> {nb} batch file(s), {tot:.2f} GB, '
              f'{time.time()-t0:.0f}s · each batch now reads only its own slice')
    return paths, nb

def ingest_sport_chunked(sport, files, out_path=None, batch_matches=None,
                         overlap=None, verbose=True):
    """Memory-bounded ingestion for very large exports. Writes incrementally; never holds the
    whole feature frame."""
    import pyarrow as pa, pyarrow.parquet as pq_
    # Read the tuning constants AT CALL TIME. As default arguments they bind once at definition,
    # so `lz.PREP_BATCH_MATCHES = 800` had no effect and every feed ran as a single batch —
    # silently defeating the whole point of chunking.
    batch_matches = batch_matches if batch_matches is not None else PREP_BATCH_MATCHES
    overlap       = overlap if overlap is not None else \
                    SPORT_OVERLAP_OVERRIDE.get(sport, PREP_OVERLAP_MATCHES)
    prep = globals()[AB_PREP_FOR_SPORT[sport]]
    kw   = PREP_KWARGS_FOR_SPORT.get(sport, {})
    out_path = out_path or V46_FRAMES[sport]
    order = _match_order(files, verbose=verbose)
    if not order:
        if verbose: print(f'[prep] {sport}: could not establish match order — falling back')
        return ingest_sport_safe(sport, files, out_path=out_path, verbose=verbose)
    nb = max(1, int(np.ceil(len(order) / batch_matches)))
    if verbose:
        print(f'[prep] {sport}: {len(order):,} matches -> {nb} batch(es) of {batch_matches:,} '
              f'(+{overlap:,} warm-up)', flush=True)
    stage = os.path.join('/tmp/_lz_stage', sport)
    if os.path.isdir(stage):
        import shutil as _sh; _sh.rmtree(stage)
    os.makedirs(stage, exist_ok=True)
    for f in files:
        link = os.path.join(stage, os.path.basename(f))
        try: os.symlink(os.path.abspath(f), link)
        except Exception:
            import shutil as _sh; _sh.copy(f, link)
    pattern = os.path.join(stage, '*.csv*')
    writer, total, t0, _schema = None, 0, time.time(), None
    # ONE pass over the source, split into per-batch files. Each batch then reads only its own
    # slice instead of the whole export — that is where the repeat I/O was going.
    batch_files = None
    stage_root = os.path.join('/tmp/_lz_stage', sport)
    if SPLIT_SOURCE_FOR_BATCHES:
        try:
            batch_files, _nb = split_source_by_batches(files, order, batch_matches, overlap,
                                                       stage_root, verbose=verbose)
        except Exception as _e:
            if verbose: print(f'[split] failed ({type(_e).__name__}) — using full reads')
            batch_files = None
    try:
        for b in range(nb):
            lo = b * batch_matches
            keep = set(order[lo: lo + batch_matches])
            warm = set(order[max(0, lo - overlap): lo])
            want = keep | warm
            # Each batch reads ONLY its own slice when the source has been pre-split. Without
            # this the prep re-reads the entire export every batch — 14 batches on 10.66 GB is
            # ~149 GB of I/O to process 10.66 GB of data.
            _pat = pattern
            if batch_files and b < len(batch_files) and batch_files[b] \
                    and os.path.exists(batch_files[b]):
                _pat = batch_files[b]
            try:
                df = prep(_pat, _match_subset=want, **kw) if _prep_accepts_subset(prep) \
                     else prep(_pat, **kw)
            except KeyError as _ke:
                # The prep needs a column the staged batch does not expose. eBasketball's
                # player_feed prep reads player-history columns the chunked stage does not carry,
                # and the whole sport was abandoned with KeyError. Fall back to ONE pass over the
                # original files — the path that is known to work — instead of losing the sport.
                if verbose:
                    print(f'[prep] {sport}: chunked prep needs {_ke} — falling back to '
                          f'single-pass over the original files', flush=True)
                if writer is not None:
                    writer.close(); writer = None
                try: os.remove(out_path)
                except Exception: pass
                return ingest_sport_safe(sport, files, out_path=out_path, verbose=verbose)
            if 'match_id' in df.columns:
                df = df[df['match_id'].isin(want)]
                df = df[df['match_id'].isin(keep)]      # drop the warm-up, keep this batch only
            df = ensure_phase_column(df, _pat, sport, verbose=False)
            df = ensure_identity_columns(df, _pat, sport, verbose=verbose)
            _optimise_dtypes(df)
            # Parquet writes the DICTIONARY INDEX WIDTH into the schema, and it varies with how
            # many distinct values a batch happens to contain — league was int8 in batch 1 and
            # int16 in batch 2, so ParquetWriter rejected the second table outright. Casting
            # categoricals back to plain strings before writing makes every batch schema identical.
            # Only OBJECT-derived categoricals go back to string. Casting a NUMERIC column that
            # _optimise_dtypes had categorised produced 'Invalid comparison between dtype=category
            # and float' the moment a fire function touched it.
            for _c in df.columns:
                if str(df[_c].dtype) == 'category':
                    try:
                        _cats = df[_c].cat.categories
                        if _cats.dtype.kind in 'ifubMm':
                            df[_c] = df[_c].astype(_cats.dtype)     # numeric -> back to numeric
                        else:
                            df[_c] = df[_c].astype(str)             # text -> plain string
                    except Exception:
                        df[_c] = df[_c].astype(str)
            tbl = pa.Table.from_pandas(df, preserve_index=False)
            if writer is None:
                # PIN the first batch's schema and cast every later batch to it. Per-batch dtype
                # drift — dictionary index width, large_string vs string — has now broken this
                # writer twice in different ways. Casting removes the entire class of failure.
                _schema = tbl.schema
                writer = pq_.ParquetWriter(out_path, _schema, compression='zstd')
            elif tbl.schema != _schema:
                try:
                    tbl = tbl.cast(_schema)
                except Exception:
                    # last resort: rebuild the frame in the pinned column order and types
                    for _f in _schema:
                        if _f.name in df.columns:
                            try: df[_f.name] = df[_f.name].astype(_f.type.to_pandas_dtype())
                            except Exception: pass
                    tbl = pa.Table.from_pandas(df[[f.name for f in _schema]],
                                               preserve_index=False).cast(_schema)
            writer.write_table(tbl)
            total += len(df)
            m = memory_report()
            if verbose:
                print(f'[prep]   batch {b+1}/{nb}: {len(df):,} rows written '
                      f'(total {total:,}) · RSS {m["rss_gb"]} GB', flush=True)
            del df, tbl; gc.collect()
    finally:
        if writer is not None: writer.close()
    if verbose:
        print(f'[prep] {sport}: {total:,} rows -> {out_path} in {time.time()-t0:.0f}s '
              f'· peak {memory_report()["peak_gb"]} GB')
    return out_path, total

def _prep_accepts_subset(prep):
    """True when a prep can be told to load only some matches, which avoids re-reading the whole
    export per batch. Preps without it still work — they simply cost a full read each time."""
    try:
        import inspect as _i
        return '_match_subset' in _i.signature(prep).parameters
    except Exception:
        return False

INGEST_LARGE_THRESHOLD_GB = 2.0

# ═══════════════════════════════════════════════════════════════════════════════════════
#  v65_v15 — GLOBAL ENTRY-ODDS FLOOR (owner directive)
# ═══════════════════════════════════════════════════════════════════════════════════════
#  1.65 is the starting point and MINIMUM odds for every strategy, registry and discovered.
#  Enforced centrally at the evaluation chokepoints (assess_single_pass, the ledger extraction,
#  both discovered evaluators, build_discovered_ledgers) — never per-strategy, so no strategy can
#  drift below it. Bets priced under the floor are simply not taken; every published number and
#  every one-to-one ledger reflects the floored entry.
#  KNOWN CONSEQUENCE (measured before shipping): short-price families — above all the inverse
#  family, whose strike lives at 1.15–1.60 — lose the sub-floor share of their volume, and some
#  will fall below segment volume floors and drop out of Tier 1/2. That is the directive working
#  as intended, not a defect. Set GLOBAL_MIN_ODDS = None to restore pre-v15 behaviour.
GLOBAL_MIN_ODDS = 1.65

def _apply_global_odds_floor(fr, col):
    """Drops bets priced below GLOBAL_MIN_ODDS. Returns fr unchanged when the floor is disabled
    or the column is absent (absence is a ledger-contract problem, not a floor problem)."""
    if fr is None or not len(fr) or not GLOBAL_MIN_ODDS or col not in fr.columns:
        return fr
    return fr[pd.to_numeric(fr[col], errors='coerce') >= GLOBAL_MIN_ODDS]
REUSE_CURRENT_FRAMES = True   # skip ingestion when the frame is newer than its sources

# PER-SPORT INGEST OVERRIDE — v65_v14: the eBasketball 'single' pin is LIFTED.
# History: the chunked path once killed eBasketball with KeyError 'hp_avg_matchgoals_10' on
# batch 1, and the sport was pinned to single-pass as a workaround. v65_v13 fixed that crash at
# the ROOT (schema-drift guard + player-history derivation in ab_prep_basketball), so the pin's
# reason no longer exists — and at an 11.4 GB export it had become a memory hazard, the heaviest
# single-pass ingest in the system on a desktop machine.
# MEASURED equivalence, chunked vs single-pass, 542,713 real rows / 6,494 matches / 5 batches:
#   · 55/56 columns EXACTLY identical (incl. pair_g10 and every player-history passthrough)
#   · min_rest_min identical wherever both paths carry a value (max diff 0.0, zero cells differ);
#     with the 1,200-match warm-up below, 99.94% NaN agreement. The residual 0.06% of rows are
#     players idle longer than the warm-up window, who read NaN instead of a very large rest —
#     and every registry rest condition is a rest_max CAP, which NaN fails exactly as a huge rest
#     value does, so strategy behaviour is preserved.
# To restore the old path: SPORT_INGEST_OVERRIDE['ebasketball'] = 'single'.
SPORT_INGEST_OVERRIDE = {}
SPORT_OVERLAP_OVERRIDE = {'ebasketball': 1200}   # read at CALL time, like the other tunables

def ingest_sport_auto(sport, files, out_path=None, verbose=True):
    """Picks the ingestion path by input size. Small feeds go through the single-pass route;
    anything above the threshold is batched so it cannot exhaust memory."""
    gb = sum(os.path.getsize(f) for f in files if os.path.exists(f)) / 1024**3
    if verbose: print(f'[ingest] {sport}: {gb:.2f} GB across {len(files)} file(s)')
    # A frame newer than every source file is already current — re-preparing it is pure cost.
    out_p = out_path or V46_FRAMES[sport]
    if REUSE_CURRENT_FRAMES and os.path.exists(out_p):
        try:
            fm = os.path.getmtime(out_p)
            if all(os.path.getmtime(f) <= fm for f in files if os.path.exists(f)):
                import pyarrow.parquet as _pq
                n = _pq.ParquetFile(out_p).metadata.num_rows
                if verbose:
                    print(f'[ingest] {sport}: frame is current ({n:,} rows) — reusing, '
                          f'delete it to force a rebuild')
                return out_p, n
        except Exception:
            pass
    ov = SPORT_INGEST_OVERRIDE.get(sport)
    if ov == 'single':
        if verbose:
            print(f'[ingest] {sport}: forced SINGLE-PASS (chunked prep needs the whole file)')
        return ingest_sport_safe(sport, files, out_path=out_path, verbose=verbose)
    if ov == 'chunked':
        return ingest_sport_chunked(sport, files, out_path=out_path, verbose=verbose)
    if gb >= INGEST_LARGE_THRESHOLD_GB:
        # file-aware batching when there is more than one file to be selective about
        if len(files) > 1:
            if verbose:
                print(f'[ingest] {sport}: above {INGEST_LARGE_THRESHOLD_GB} GB -> file-aware '
                      f'chunked prep')
            return ingest_sport_filewise(sport, files, out_path=out_path, verbose=verbose)
        if verbose: print(f'[ingest] {sport}: above {INGEST_LARGE_THRESHOLD_GB} GB -> chunked prep')
        return ingest_sport_chunked(sport, files, out_path=out_path, verbose=verbose)
    return ingest_sport_safe(sport, files, out_path=out_path, verbose=verbose)


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v53 SECTION U — SEQUENTIAL PER-SPORT PIPELINE
# ═══════════════════════════════════════════════════════════════════════════════════════
#  assemble_book_inputs() evaluates sports one at a time but ACCUMULATES every sport's ledgers
#  before the book is built, so peak memory is the SUM of five sports rather than the largest one.
#  On feeds of 1-11 GB that accumulation, not the frame itself, is what exhausts memory.
#
#  This runs the full cycle per sport and releases everything before moving on:
#      ingest -> evaluate -> write that sport's sheets -> free frame, ledgers, results -> next
#
#  Two further benefits fall out of it. The workbook is SAVED after each sport, so a crash on
#  sport four keeps sports one to three instead of losing the run. And because only one sport's
#  artefacts exist at a time, peak memory is bounded by the largest single feed no matter how many
#  sports are added later.

def run_pipeline_sequential(sports=None, upload_dir='.',
                            out_book='.',
                            carry_forward=None, skip_ingest=False, verbose=True,
                            _preflight_done=False):
    """One sport at a time: ingest, assess, write, release. Peak memory = largest single sport."""
    sports = _ordered_sports(sports)   # v65_v13: eBasketball first (owner directive)
    if not skip_ingest and not _preflight_done:
        pf_ok, _ = _laz_legacy_preflight(upload_dir, out_book, carry_forward, sports, verbose=verbose)
        if not pf_ok:
            raise RuntimeError('_laz_legacy_preflight failed — see FATAL items above. '
                               'Fix them rather than starting a multi-hour run.')
    t0 = time.time()
    report = {'sports': {}, 'out_book': out_book}
    if carry_forward and os.path.exists(carry_forward):
        wb = load_workbook(carry_forward)
        if verbose: print(f'[seq] carried forward {len(wb.sheetnames)} sheets')
    else:
        wb = Workbook(); wb.remove(wb.active)
    # LEDGERS are per-bet and huge -> released after each sport.
    # opwin / hourly are ONE ROW PER STRATEGY -> tiny, so they are kept and the sheets that
    # depend on them still build at the end. Releasing those too was over-correction.
    all_rows, all_disc, all_opwin, all_hourly, all_walk = [], [], [], [], []
    all_trig = []
    # compact ledger aggregates — ids and weekly sums only, kept across every sport
    agg_overlap, agg_weekly = {}, []
    for i, sport in enumerate(sports, 1):
        st = time.time()
        if verbose:
            print(f'\n[seq] ({i}/{len(sports)}) {sport} — RSS {memory_report()["rss_gb"]} GB', flush=True)
        try:
            if not skip_ingest:
                files = resolve_input_files(sport, [upload_dir], verbose=verbose)
                if files:
                    okv, det, why = verify_input_sport(sport, files, verbose=verbose)
                    if not okv:
                        report['sports'][sport] = dict(error=f'verification failed: {why}')
                        if verbose: print(f'[seq]   REFUSED — {why}')
                        continue
                    ingest_sport_auto(sport, files, verbose=verbose)
                elif verbose:
                    print(f'[seq]   no files found, using existing frame')
            arts = assemble_book_inputs([sport], verbose=verbose)
            T = arts['tiers']
            for _, r in T.iterrows(): all_rows.append(r.to_dict())
            d = arts.get('discovered')
            if d is not None and len(d): all_disc.append(d)
            failures = []
            _bk_guard(wb, f'{sport}_Tiers',
                      lambda sp=sport, TT=T, DD=arts.get('discovered'):
                          _seq_sport_sheet(wb, sp, TT, DD), failures, verbose)
            for key, bucket in (('opwin', all_opwin), ('hourly', all_hourly),
                                ('walkforward', all_walk), ('triggers', all_trig)):
                q = arts.get(key)
                if q is not None and len(q): bucket.append(q)
            led = arts.get('ledgers') or {}
            n_led = len(led)
            _bk_guard(wb, f'{sport}_one_to_one',
                      lambda TT=T, LL=led, sp=sport: _laz_legacy_build_one_to_one_sheets(wb, TT, LL, sp,
                                                                            verbose=verbose),
                      [], verbose)
            ov, wk = extract_ledger_aggregates(led, sport)
            agg_overlap.update(ov); agg_weekly.extend(wk)
            if verbose and (ov or wk):
                print(f'[seq]   aggregates kept: {len(ov)} overlap sets, {len(wk)} weekly rows')
            del arts, T, led, ov, wk; gc.collect()
            _laz_save_book(wb, out_book)                       # checkpoint the BOOK, not just the data
            report['sports'][sport] = dict(ok=True, ledgers=n_led,
                                           seconds=round(time.time() - st, 1),
                                           rss_gb=memory_report()['rss_gb'])
            if verbose:
                print(f'[seq]   done in {time.time()-st:.0f}s · book saved · '
                      f'RSS now {memory_report()["rss_gb"]} GB', flush=True)
        except Exception as e:
            report['sports'][sport] = dict(error=f'{type(e).__name__}: {e}')
            if verbose: print(f'[seq]   FAILED: {type(e).__name__}: {e}')
        gc.collect()
    # combined views, built from the small summary rows only
    try:
        T = pd.DataFrame(all_rows)
        if len(T):
            # _disc_df MUST be set BEFORE IS_OOS is built. Assigning it after meant the sheet
            # was handed None and eBasketball — whose entire tradeable set is DISCOVERED — was
            # rendered blank. Same class of ordering fault three sheets deep.
            wb._disc_df = pd.concat(all_disc, ignore_index=True) if all_disc else None
            _bk_guard(wb, 'IS_OOS',
                      lambda: build_is_oos_sheet(wb, T, None, wb.__dict__.get('_disc_df')),
                      [], verbose)
            OP = pd.concat(all_opwin, ignore_index=True) if all_opwin else None
            HR = pd.concat(all_hourly, ignore_index=True) if all_hourly else None
            build_reference_sheets(wb, T, opwin=OP, ledgers=None, failures=[], verbose=verbose,
                                   skip=('Overlap_Matrix','Weekly_Breakdown'))
            build_extra_sheets(wb, T, opwin=OP, hourly=HR, failures=[], verbose=verbose)
            WF = pd.concat(all_walk, ignore_index=True) if all_walk else None
            build_v53_extra_sheets(wb, T, walk=WF, opwin=OP, failures=[], verbose=verbose)
            _bk_guard(wb, 'Dashboard',
                      lambda: build_dashboard_sheet(wb, T, wb.__dict__.get('_disc_df'),
                                                    verbose=verbose), [], verbose)
            build_restored_sheets(wb, T, wb.__dict__.get('_disc_df'), verbose=verbose)
            build_aggregate_sheets(wb, overlap=agg_overlap, weekly=agg_weekly,
                                   failures=[], verbose=verbose)
            TR = pd.concat(all_trig, ignore_index=True) if all_trig else None
            build_core_text_sheets(wb, T, triggers=TR, failures=[], verbose=verbose)
            order_book_sheets(wb, tiers=T, verbose=verbose)
    except Exception as e:
        if verbose: print(f'[seq] combined sheets failed: {type(e).__name__}: {e}')
    # ── WHOLE-BOOK WORK RUNS ONCE, NOT ONCE PER SPORT ─────────────────────────────────
    # These three read EVERY sheet in the accumulated workbook. With --isolate each sport
    # inherits the previous sports' sheets via carry_forward, so they were re-run on a book
    # that grows every pass: tennis paid for 69 sheets, eFootball would pay for ~250. The
    # measured cost was brutal -- the tennis SPORT took 260s and the tennis PROCESS took
    # 5,470s, so 87 of those 91 minutes were spent re-deriving the deployment contract,
    # re-placing charts and re-measuring 1,252 column widths on sheets that had not
    # changed. Five sports paying that on an ever-larger book is O(n squared).
    # They only need to be correct in the FINAL book, so they run only on the last sport.
    # Every intermediate save still writes a complete, openable workbook -- just without
    # the cosmetic pass and the contract, which the next pass would overwrite anyway.
    _is_last = bool(globals().get('_LAZ_FINAL_SPORT_PASS', True))
    if _is_last:
        _bk_guard(wb, '<contract>', lambda: write_deployment_contract(wb, tiers=T, verbose=verbose), [], verbose)
        _bk_guard(wb, '<charts>', lambda: place_charts_tightly(wb, verbose=verbose), [], verbose)
        _bk_guard(wb, '<autosize>', lambda: autosize_all_columns(wb, verbose=verbose), [], verbose)
    elif verbose:
        print('[book] contract/charts/autosize deferred to the final sport '
              '(they read every sheet; running them per sport is quadratic)')
    wb.active = 0
    _laz_save_book(wb, out_book)
    report['elapsed_sec'] = round(time.time() - t0, 1)
    report['sheets'] = len(wb.sheetnames)
    report['peak_gb'] = memory_report()['peak_gb']
    if verbose:
        print(f'\n[seq] complete: {len(wb.sheetnames)} sheets -> {out_book}')
        print(f'[seq] {report["elapsed_sec"]}s · peak {report["peak_gb"]} GB')
    return report

def _seq_sport_sheet(wb, sport, T, disc=None):
    """One summary sheet per sport, written immediately so its data can be released."""
    name = f'{sport}_Tiers'[:31]
    if name in wb.sheetnames: del wb[name]
    ws = wb.create_sheet(name)
    seg = ['is', 'oos', 'fwd', 'bwd', 'frz']
    _ndisc = 0
    if disc is not None and len(disc):
        _ndisc = len(disc[disc['sport'] == sport]) if 'sport' in disc.columns else len(disc)
    r = _bk_title(ws, f'{SPORT_LABEL.get(sport, sport)} — SEGMENT RESULTS',
                  f'{len(T)} registry + {_ndisc} discovered = {len(T)+_ndisc} strategies. Written immediately so this sport\'s frames and '
                  f'ledgers can be released before the next one loads.', 14)
    tiers_present = list(T['tier'].dropna().unique()) if 'tier' in T.columns else []
    order = ['TIER 1 — OMEGA', 'TIER 2 — CHALLENGE', 'TIER 3 — DESIGNATED', 'NOT VALIDATED']
    order += [t for t in tiers_present if t not in order]        # never drop an unexpected tier
    seen_names = set()
    for tier in order:
        g = T[T.tier == tier] if 'tier' in T.columns else T.iloc[0:0]
        if not len(g): continue
        seen_names |= set(g['name'].astype(str))
        r = _bk_section(ws, r, f'{tier} — {len(g)}', 14)
        rows = [(x['name'], int(x['is_n']), round(float(x['is_wr']), 1), round(float(x['is_roi']), 1),
                 int(x['oos_n']), round(float(x['oos_wr']), 1), round(float(x['oos_odds']), 2),
                 round(float(x['oos_roi']), 1), round(float(x['oos_ci']), 1),
                 round(float(x['oos_maxdd']), 1)) for _, x in g.iterrows()]
        r = _bk_table(ws, r, ['Strategy', 'IS n', 'IS WR %', 'IS ROI %', 'OOS n', 'OOS WR %',
                              'Odds', 'OOS ROI %', 'CI floor %', 'Max DD'],
                      rows, [30, 9, 9, 10, 9, 10, 8, 10, 11, 9], colour_col=8)
    # anything the tier loop did not pick up still belongs in the book
    left = T[~T['name'].astype(str).isin(seen_names)] if 'tier' in T.columns else T
    if len(left):
        r = _bk_section(ws, r, f'UNCLASSIFIED — {len(left)}', 14)
        rows = [(x['name'], int(x['is_n']), round(float(x['is_wr']), 1), round(float(x['is_roi']), 1),
                 int(x['oos_n']), round(float(x['oos_wr']), 1), round(float(x['oos_odds']), 2),
                 round(float(x['oos_roi']), 1), round(float(x.get('oos_ci', float('nan'))), 1),
                 round(float(x.get('oos_maxdd', float('nan'))), 1)) for _, x in left.iterrows()]
        r = _bk_table(ws, r, ['Strategy', 'IS n', 'IS WR %', 'IS ROI %', 'OOS n', 'OOS WR %',
                              'Odds', 'OOS ROI %', 'CI floor %', 'Max DD'],
                      rows, [30, 9, 9, 10, 9, 10, 8, 10, 11, 9], colour_col=8)
    # DISCOVERED STRATEGIES FOR THIS SPORT. Without this eBasketball's sheet was EMPTY: all 30 of
    # its registry specs settle on a market the book rejects, while its 101 discovered moneyline
    # strategies — the tradeable ones — never reached the page.
    if disc is not None and len(disc):
        d = disc[disc['sport'] == sport] if 'sport' in disc.columns else disc
        if len(d):
            # NAME FIRST, then family, then the numbers, with conditions LAST. A sheet whose first
            # column is a 120-character condition string cannot be read, sorted or cross-referenced.
            _PX = {'efootball':'EFB','ebasketball':'EBB','basketball':'RBB',
                   'football':'RFB','tennis':'TEN'}
            _px = _PX.get(sport, str(sport)[:3].upper())
            for fam, g in d.groupby('family'):
                g = g.sort_values('roi', ascending=False)
                r = _bk_section(ws, r, f'DISCOVERED — {str(fam).upper()} — {len(g)} strategies', 14)
                rows = []
                for _i, (_, x) in enumerate(g.iterrows(), 1):
                    _gap = (abs(float(x.get('is_wr', np.nan)) - float(x.get('oos_wr', np.nan)))
                            if pd.notna(x.get('is_wr')) and pd.notna(x.get('oos_wr')) else np.nan)
                    rows.append((f'{_px}_{fam}_{_i:02d}', str(fam),
                                 int(x['n']), round(float(x['wr']), 2), round(float(x['odds']), 2),
                                 round(float(x['roi']), 1), round(float(x.get('dd', np.nan)), 1),
                                 int(x.get('is_n', 0)), round(float(x.get('is_wr', np.nan)), 2),
                                 int(x.get('oos_n', 0)), round(float(x.get('oos_wr', np.nan)), 2),
                                 (round(_gap, 2) if pd.notna(_gap) else None),
                                 ('EXCELLENT' if pd.notna(_gap) and _gap < 2 else
                                  ('good' if pd.notna(_gap) and _gap < 5 else
                                   ('watch' if pd.notna(_gap) and _gap < 10 else 'DIVERGES'))),
                                 str(x.get('conditions', ''))[:150]))
                r = _bk_table(ws, r, ['Strategy', 'Family', 'Bets', 'Win %', 'Odds', 'ROI %',
                                      'Max DD', 'IS n', 'IS WR %', 'OOS n', 'OOS WR %',
                                      'Gap (pts)', 'Agreement', 'Conditions'],
                              rows, [26, 18, 8, 9, 8, 9, 9, 8, 9, 8, 9, 10, 12, 90],
                              wrapcols=(14,), colour_col=6)
    ws.sheet_properties.tabColor = BK_BLUE
    _bk_backlink(ws, 16)


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v53 SECTION V — MARKET TRADEABILITY, AND THE RESTORED LEGACY SHEETS
# ═══════════════════════════════════════════════════════════════════════════════════════
#  The book displays eBasketball handicap and totals prices but REJECTS bets on them. A strategy
#  that settles against total_points_handicap is therefore an observation, not a position. The
#  handicap VALUE stays available as a condition or trigger — only staking on that market is out,
#  and only for eBasketball. Every other sport may still trade handicaps.
# RE-ENABLED at the owner's request: the eBasketball handicap and totals markets are back in play
# and will be attempted live. The exclusion is now a FLAG, not a hard-coded rule, so it can be
# turned off again in one line if the book rejects the stakes in practice.
#
# Nothing was ever deleted — the 30 specs stayed in V46_REGISTRY throughout, excluded only at
# evaluation. Flipping this returns them to the book with their full history intact.
EBASKETBALL_HANDICAP_TRADEABLE = True     # set False to exclude again

UNTRADEABLE_MARKETS = {} if EBASKETBALL_HANDICAP_TRADEABLE else {
    'ebasketball': ('total_points_handicap', 'total_points_over', 'total_points_under',
                    'point_spread_handicap', 'totals', 'handicap', 'spread', 'under', 'over'),
}

def market_is_tradeable(sport, market, settles_on=None):
    """False when the book will not accept a stake on that market for that sport."""
    bad = UNTRADEABLE_MARKETS.get(sport)
    if not bad: return True
    probe = f'{market or ""} {settles_on or ""}'.lower()
    return not any(b in probe for b in bad)

def build_restored_sheets(wb, T, disc=None, verbose=True):
    """IS_vs_OOS and Opportunity_Window — both present in earlier lineages, absent from v65.

    IS_vs_OOS was the v40_1 name and became IS_OOS at v46; the older layout put agreement first,
    which is the question that actually matters, so it is restored under its own name rather than
    merged away.

    Opportunity_Window previously required `opwin`, which is computed from per-bet ledgers — so on
    any run where nothing validates it raised and vanished. It now falls back to the DISCOVERED
    placeability measurement, which needs no ledgers, so the sheet always says something."""
    def _is_vs_oos():
        parts = []
        if T is not None and len(T):
            t = T.copy(); t['src'] = 'registry'
            parts.append(t.rename(columns={'oos_n':'bets','oos_wr':'wr','oos_odds':'odds',
                                           'oos_roi':'roi'})[['sport','name','src','is_n','is_wr',
                                           'is_roi','bets','wr','odds','roi']])
        if disc is not None and len(disc):
            d = disc.copy(); d['src'] = 'discovered'
            d['name'] = d['family'].astype(str)
            for a,b in (('n','bets'),('oos_n','bets')):
                if a in d.columns and 'bets' not in d.columns: d['bets'] = d[a]
            for c in ('is_n','is_wr','is_roi','oos_wr','roi','odds','wr'):
                if c not in d.columns: d[c] = np.nan
            parts.append(d[['sport','name','src','is_n','is_wr','is_roi','bets','wr','odds','roi']])
        if not parts: raise ValueError('nothing to compare')
        A = pd.concat(parts, ignore_index=True)
        A['gap'] = (A['is_wr'] - A['wr']).abs()
        ws = wb.create_sheet('IS_vs_OOS')
        r = _bk_title(ws,'IS vs OOS — DOES THE STRATEGY AGREE WITH ITSELF?',
            'Ranked by AGREEMENT, not by return. A strategy whose two halves disagree is not a '
            'strategy — divergence is the overfitting signature, and it matters more than either '
            'half taken alone.',11)
        A = A.dropna(subset=['gap']).sort_values('gap')
        rows = [(x['sport'], str(x['name'])[:34], x['src'], int(x.is_n),
                 round(float(x.is_wr),2), round(float(x.is_roi),1), int(x.bets),
                 round(float(x.wr),2), round(float(x.roi),1), round(float(x.gap),2),
                 ('EXCELLENT' if x.gap < 2 else ('good' if x.gap < 5 else
                  ('watch' if x.gap < 10 else 'DIVERGES'))))
                for _, x in A.head(120).iterrows()]
        r = _bk_table(ws,r,['Sport','Strategy','Source','IS n','IS WR %','IS ROI %',
                            'OOS n','OOS WR %','OOS ROI %','Gap (pts)','Agreement'],
                      rows,[14,36,12,8,10,10,8,10,10,10,12],colour_col=10)
        r = _bk_note(ws,r,'A gap under 2 points across 100+ bets in each half is the strongest '
                     'single signal in this book. It is what separates a real edge from a fitted '
                     'one, and it cannot be manufactured by searching harder.',11,BK_GREEN,30)
        ws.sheet_properties.tabColor = BK_GREEN; _bk_backlink(ws,13)

    def _opportunity():
        rows = []
        for sport in list(DISCOVERED_STRATEGIES):
            lst = DISCOVERED_STRATEGIES.get(sport, [])
            for fam in sorted({x.get('family') for x in lst}):
                try:
                    r_, h = lag_persistence(sport, verbose=False) if fam == 'lag' else (None, None)
                except Exception:
                    r_, h = None, None
                if r_ is None:
                    try:
                        pr = measure_placeability(sport, fam,
                                                  strategies=[x for x in lst
                                                              if x.get('family') == fam][:3],
                                                  verbose=False)
                    except Exception:
                        pr = None
                    if pr is None or not len(pr): continue
                    rows.append((SPORT_LABEL.get(sport, sport), fam, int(pr.bets.sum()),
                                 round(float(pr.median_hold_s.median()), 1),
                                 round(float(pr.placeable_20s.mean()), 1),
                                 round(float(pr.placeable_5s.mean()), 1),
                                 round(float(pr.instant_only.mean()), 1)))
        if not rows: raise ValueError('no placeability measured')
        ws = wb.create_sheet('Opportunity_Window')
        r = _bk_title(ws,'OPPORTUNITY WINDOW — HOW LONG THE PRICE STAYS AVAILABLE',
            'The practical question behind every ROI figure: once the conditions fire, how much '
            'time do you actually have to get the bet on at that price? Measured by walking '
            'forward from each entry until the price falls below 98% of what was quoted.',7)
        r = _bk_table(ws,r,['Sport','Family','Bets','Median hold (s)','Held >=20s %',
                            'Held >=5s %','Single-tick %'],
                      rows,[18,16,10,16,14,13,14],colour_col=5)
        r = _bk_note(ws,r,'A median hold under 10 seconds means single-tick quotes and the ROI '
                     'should be discounted heavily. Above 60 seconds the price is comfortably '
                     'obtainable. This measures QUOTE PERSISTENCE, not that your stake fills at '
                     'size — no historical feed can answer that.',7,BK_AMBER,34)
        ws.sheet_properties.tabColor = BK_AMBER; _bk_backlink(ws,9)

    fails = []
    for nm, fn in [('IS_vs_OOS', _is_vs_oos), ('Opportunity_Window', _opportunity)]:
        _bk_guard(wb, nm, fn, fails, verbose)
    return fails

# ═══════════════════════════════════════════════════════════════════════════════════════
#  TIER 3 PROMOTION — owner-designated strategies
# ═══════════════════════════════════════════════════════════════════════════════════════
#  These are named by the owner as Tier 3 regardless of what the automatic tier test returns.
#  The automatic tiers are evidence thresholds; this is a judgement call the owner is entitled
#  to make, and it is recorded explicitly so nobody later mistakes it for a computed result.
TIER3_MANUAL = {
    'tennis': ['NX_TEN_S1W_Mid', 'V5_TEN_S1W_Early', 'NX_TEN_S1W_Shorten',
               'V31_4_Set1Momentum_Fav20', 'V31_4_Set1Momentum_Fav',
               'V5_TEN_S1W_20_35', 'V5_TEN_S1W_Short'],
}

def apply_manual_tiers(T, verbose=True):
    """Stamps owner-designated strategies as TIER 3 after the automatic tiering has run."""
    if T is None or not len(T) or 'tier' not in T.columns: return T
    n = 0
    for sport, names in TIER3_MANUAL.items():
        m = (T['sport'] == sport) & (T['name'].astype(str).isin(names))
        n += int(m.sum())
        T.loc[m, 'tier'] = 'TIER 3 — DESIGNATED'
    if verbose and n: print(f'[book] {n} strategy(ies) promoted to TIER 3 by designation')
    return T

def build_dashboard_sheet(wb, T, disc=None, verbose=True):
    """The Dashboard: one page answering 'what do I have and what should I trade?'

    The v46 manifest listed a Dashboard but the builder itself was lost in the v46 merge — the
    sheet name survived in BOOK_SHEET_MANIFEST while nothing produced it. This restores it, built
    from the segment table and the discovered results.

    Three blocks: a portfolio summary, the headline table ranked by out-of-sample ROI, and a
    per-sport breakdown with the risk numbers that decide sizing."""
    if 'Dashboard' in wb.sheetnames: del wb['Dashboard']
    ws = wb.create_sheet('Dashboard', 0)
    parts = []
    if T is not None and len(T):
        t = T.copy(); t['src'] = 'registry'
        keep = ['sport','name','src','oos_n','oos_wr','oos_odds','oos_roi','oos_ci','oos_maxdd']
        parts.append(t[[c for c in keep if c in t.columns]].rename(columns={
            'oos_n':'bets','oos_wr':'wr','oos_odds':'odds','oos_roi':'roi',
            'oos_ci':'ci','oos_maxdd':'dd'}))
    if disc is not None and len(disc):
        d = disc.copy(); d['src'] = 'discovered'
        d['name'] = d['family'].astype(str) + '#' + d.get('idx', pd.Series(range(len(d)))).astype(str)
        for a, b in (('n','bets'),('wr','wr'),('odds','odds'),('roi','roi'),('dd','dd')):
            if a in d.columns and b not in d.columns: d[b] = d[a]
        if 'ci' not in d.columns: d['ci'] = np.nan
        parts.append(d[['sport','name','src','bets','wr','odds','roi','ci','dd']])
    A = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
    r = _bk_title(ws, 'LAZARUSEV DASHBOARD',
                  'Everything in one page: what exists, what is worth trading, and what it costs '
                  'in risk. Ranked by out-of-sample ROI.', 10)

    r = _bk_section(ws, r, 'PORTFOLIO', 10)
    prof = A[A.roi > 0] if len(A) else A
    low  = prof[prof.dd < 8] if len(prof) else prof
    rows = [('Strategies in book', len(A)),
            ('Profitable out-of-sample', f'{len(prof)} ({100*len(prof)/max(len(A),1):.0f}%)'),
            ('Profitable AND drawdown under 8u', len(low)),
            ('Total out-of-sample bets', f'{int(A.bets.sum()):,}' if len(A) else 0),
            ('Median odds', f'{A.odds.median():.2f}' if len(A) else '—'),
            ('Median win rate', f'{A.wr.median():.1f}%' if len(A) else '—'),
            ('Best ROI', f'{A.roi.max():+.1f}%' if len(A) else '—'),
            ('Lowest drawdown among profitable', f'{prof.dd.min():.1f}u' if len(prof) else '—')]
    r = _bk_table(ws, r, ['Measure', 'Value'], rows, [40, 26])

    if len(A):
        # RANK BY BALANCED SCORE, NOT RAW ROI, AND ENFORCE A BET FLOOR.
        # Sorting by ROI alone put ONE-BET strategies at the top: a single winner at 5.20 shows
        # +420% and outranks a 400-bet edge. balanced_score weighs volume, win rate, drawdown and
        # price together, which is the question actually being asked.
        DASH_MIN_BETS = 100
        A['score'] = [balanced_score(dict(nIS=x.bets, nOOS=x.bets, wrIS=x.wr, wrOOS=x.wr,
                                          roiIS=x.roi, roiOOS=x.roi, odIS=x.odds, odOOS=x.odds,
                                          dd=(x.dd if pd.notna(x.dd) else 0.1)))
                      for _, x in A.iterrows()]
        big = A[A.bets >= DASH_MIN_BETS]
        thin = len(A) - len(big)
        r = _bk_section(ws, r, f'HEADLINE — TOP 30 BY BALANCED SCORE '
                               f'(min {DASH_MIN_BETS} bets · {thin} thinner rows held back)', 10)
        top = (big if len(big) else A).sort_values('score', ascending=False).head(30)
        # laz_id is the content hash of sport + exact conditions. It is the only
        # identifier that survives the two naming schemes, so it is what makes a
        # Dashboard row joinable to the registry, the rt table and the ledger.
        def _lazid(sport_, nm):
            rec = _lds_by_name(sport_).get(str(nm))
            return rec.get('laz_id', '') if rec else ''
        rows = [(x['sport'], str(x['name'])[:34], x['src'], int(x.bets),
                 round(float(x.wr), 1), round(float(x.odds), 2), round(float(x.roi), 1),
                 (round(float(x.ci), 1) if pd.notna(x.ci) else None),
                 round(float(x.dd), 1),
                 ('YES' if pd.notna(x.dd) and pd.notna(x.odds) and x.dd < x.odds else 'no'),
                 round(float(x.score), 3), _lazid(x['sport'], x['name']))
                for _, x in top.iterrows()]
        r = _bk_table(ws, r, ['Sport','Strategy','Source','Bets','Win %','Odds','ROI %',
                              'CI floor %','Max DD','DD < odds?','Score','laz_id'],
                      rows, [14, 36, 12, 8, 9, 8, 9, 11, 9, 11, 8, 14], colour_col=11)

        r = _bk_section(ws, r, 'BY SPORT', 10)
        rows = []
        for sp, g in A.groupby('sport'):
            p = g[g.roi > 0]
            rows.append((SPORT_LABEL.get(sp, sp), len(g), len(p),
                         int(g.bets.sum()), round(float(g.odds.median()), 2),
                         round(float(g.wr.median()), 1),
                         round(float(p.roi.max()), 1) if len(p) else None,
                         round(float(p.dd.min()), 1) if len(p) else None,
                         'NO — handicap/totals rejected' if sp == 'ebasketball' else 'yes'))
        r = _bk_table(ws, r, ['Sport','Strategies','Profitable','Bets','Median odds',
                              'Median WR %','Best ROI %','Lowest DD','Handicap tradeable?'],
                      rows, [18, 11, 11, 10, 12, 12, 11, 10, 28], colour_col=3)

    r = _bk_note(ws, r, 'DD < odds means one winning bet recovers the worst drawdown — the Tier 3/4 '
                 'rule. Size on drawdown, not on ROI. Correlated strategies within a sport are ONE '
                 'position.', 10, BK_AMBER, 32)
    ws.sheet_properties.tabColor = BK_PURPLE
    _bk_backlink(ws, 12)
    if verbose: print(f'[book] Dashboard: {len(A)} strategies summarised')
    return ws

def build_v53_extra_sheets(wb, T, walk=None, opwin=None, ledgers=None, disc=None,
                           failures=None, verbose=True):
    """Sport_Profiles, Strategy_Guide, Walk_Forward and Odds_Optimizer."""
    failures = failures if failures is not None else []
    val = T[T.tier != 'NOT VALIDATED'].copy() if 'tier' in T.columns else T.copy()
    seg = ['is','oos','fwd','bwd','frz']

    def _sport_profiles():
        ws = wb.create_sheet('Sport_Profiles')
        r = _bk_title(ws,'SPORT PROFILES — WHAT EACH MARKET IS LIKE TO TRADE',
            'Every sport behaves differently enough that a strategy tuned on one rarely transfers. '
            'This is the character of each feed, and the constraints it imposes.',10)
        rows=[]
        for sp, g in T.groupby('sport'):
            v_ = g[g.tier!='NOT VALIDATED'] if 'tier' in g.columns else g
            rows.append((SPORT_LABEL.get(sp,sp), len(g), len(v_),
                         int(g.oos_n.sum()), round(float(g.oos_odds.median()),2),
                         round(float(g.oos_wr.median()),1),
                         round(float(v_.oos_roi.max()),1) if len(v_) else None,
                         round(float(v_.oos_maxdd.median()),1) if len(v_) else None,
                         'NO — handicap/totals rejected' if sp=='ebasketball' else 'yes'))
        r=_bk_table(ws,r,['Sport','Tested','Validated','OOS bets','Median odds','Median WR %',
                          'Best ROI %','Median max DD','Handicap tradeable?'],
                    rows,[20,9,10,11,12,12,11,14,26],colour_col=3)
        r=_bk_section(ws,r,'CHARACTER OF EACH FEED',10)
        r=_bk_table(ws,r,['Sport','What it is like to trade'],[
          ('eBASKETBALL','Fastest and most mispriced feed. Handicap and totals carry most of the '
           'edge and ARE tradeable. Leads are '
           'decisive early: a 2-4 point lead equals a 1-goal football lead, and 12+ points is '
           'effectively settled. The `lead` column is unsigned — direction must come from price.'),
          ('eFOOTBALL','Deepest strategy set and the only sport where all three discovery families '
           'produce results. Prices run long enough for comeback bets to pay. Three outcomes, so '
           'draws must be counted as losses — treating them otherwise inflates one side by ~20 pts.'),
          ('REAL BASKETBALL','Thin. One comeback family survives and the drawdown is the worst in '
           'the book at 22.5 units. Size smallest here.'),
          ('REAL FOOTBALL','No robust edge at deployable volume from condition search: 817 '
           'combinations, 322 reach volume, zero clear the edge test. The misprice family is the '
           'only thing that works, and its ROI halves across the split.'),
          ('TENNIS','Score columns are UNRELIABLE. Winner must come from the settled price, and '
           'only for the 61% of matches whose price converged below 1.10. Pays best per bet but '
           'the 14-unit drawdown at a 33% strike is the price of that.'),
        ],[20,124],wrapcols=(2,))
        ws.sheet_properties.tabColor=BK_NAVY; _bk_backlink(ws,12)

    def _strategy_guide():
        ws = wb.create_sheet('Strategy_Guide')
        r = _bk_title(ws,'STRATEGY GUIDE — HOW TO READ AND RUN ANYTHING IN THIS BOOK',
            'Every column, every tier, and the order to do things in.',3)
        r=_bk_section(ws,r,'1. THE WORKFLOW',3)
        r=_bk_table(ws,r,['Step','What to do'],[
          ('Find candidates','Start at Omega_Tier1, then Challenge_Tier2, then Discovered_Strategies. '
           'Anything on Validation_Failed_Aggregate has no per-bet sheet and should not be staked.'),
          ('Check it is tradeable','Sport_Profiles says which markets your book accepts. eBasketball '
           'handicap and totals are rejected — those strategies are evidence, not positions.'),
          ('Read the conditions','Trigger_Conditions gives them in plain English. They are joined by '
           'AND, never OR. The bet is struck at the FIRST tick where all hold, one per match.'),
          ('Check the segments','The one-to-one sheet carries a five-row evidence block. A strategy '
           'strong in one segment and weak in four is a regime artefact.'),
          ('Check you can get on','Opportunity_Window gives the minutes the trigger stayed live. A '
           'median near zero means single-tick opportunities.'),
          ('Size it','Use max drawdown, not ROI. Correlated strategies within a sport are ONE '
           'position — eBasketball families correlate at 0.88.'),
        ],[24,124],wrapcols=(2,))
        r=_bk_section(ws,r,'2. WHAT EVERY COLUMN MEANS',3)
        r=_bk_table(ws,r,['Column','Definition and how to read it'],[
          ('Edge','Win rate minus the break-even the price implies. Comparable at any odds, which a '
           'flat win-rate bar is not. VALID ONLY in tight price bands: on a dispersed book the mean '
           'odds overstate what winners pay, which once showed +4.60 on a group losing 31%.'),
          ('ROI %','Profit per unit staked. The honest headline. Use this, not edge, at long odds.'),
          ('CI floor %','5th percentile of bootstrapped ROI. Positive means the resampled '
           'distribution stayed profitable. The most conservative number here.'),
          ('Max DD','Largest peak-to-trough fall in units at flat stakes. What you must survive.'),
          ('IS / OOS','In-sample and out-of-sample halves. AGREEMENT between them matters more than '
           'either value; divergence is the overfitting signature.'),
          ('Blocks','Walk-forward blocks profitable out of six. 6/6 is a real edge, 3/6 is noise.'),
          ('perm p','Probability a random draw from the same pool matched this. Below 0.05 required.'),
          ('Phase','The LITERAL segment-and-minute text from the feed row that triggered the bet.'),
        ],[18,130],wrapcols=(2,))
        r=_bk_section(ws,r,'3. THE TIERS',3)
        r=_bk_table(ws,r,['Tier','Requirement'],[
          ('TIER 1 — OMEGA','100+ bets, 65%+ strike, +5 edge, positive ROI and CI in ALL FIVE '
           'segments: IS, OOS, forward, backward, and a frozen middle window never used to select.'),
          ('TIER 2 — CHALLENGE','Same edge test at a 50% strike floor, IS/OOS pair only.'),
          ('DISCOVERED','Found by anchoring on a price state rather than proposing conditions. '
           'Validated by walk-forward, CI floor and permutation test.'),
          ('NOT VALIDATED','Recorded for completeness. No per-bet sheet. Do not stake.'),
        ],[22,126],wrapcols=(2,))
        ws.sheet_properties.tabColor=BK_PURPLE; _bk_backlink(ws,4)

    def _walk_forward():
        if walk is None or not len(walk): raise ValueError('no walk-forward data')
        ws = wb.create_sheet('Walk_Forward')
        r = _bk_title(ws,'WALK-FORWARD — DOES THE EDGE HOLD WINDOW BY WINDOW?',
            'The rule is fixed, then applied forward through time. Window size adapts to the feed: '
            'the coarsest unit still giving four windows. A chance finding concentrates in one '
            'window; a real edge spreads across them.',11)
        for sp, g in walk.groupby('sport'):
            u=(g.granularity.iloc[0] if ('granularity' in g.columns and len(g)) else 'window')
            r=_bk_section(ws,r,f'{SPORT_LABEL.get(sp,sp)} — by {u}',11)
            rows=[(x['name'],int(x['windows']),f"{int(x['positive'])}/{int(x['windows'])}",
                   round(float(x['consistency']),0),int(x['total_n']),
                   round(float(x['mean_roi']),1),round(float(x['worst_roi']),1))
                  for _,x in g.sort_values('consistency',ascending=False).iterrows()]
            r=_bk_table(ws,r,['Strategy','Windows','Positive','Consistency %','Bets',
                              'Mean ROI %','Worst window %'],
                        rows,[30,10,10,14,10,12,14],colour_col=4)
        r=_bk_note(ws,r,'A strategy positive in every window is far stronger evidence than one with '
            'a high average driven by a single window.',11,BK_BLUE,30)
        ws.sheet_properties.tabColor=BK_GREEN; _bk_backlink(ws,13)

    def _odds_optimizer():
        ws = wb.create_sheet('Odds_Optimizer')
        r = _bk_title(ws,'ODDS OPTIMIZER — WHERE THE PRICE ACTUALLY PAYS',
            'Break-even rises steeply as prices shorten, so a win rate that looks strong can still '
            'lose. This maps observed strike against the break-even each band demands, and shows '
            'what the market takes at every level.',10)
        r=_bk_section(ws,r,'BREAK-EVEN BY PRICE — THE BAR YOU MUST CLEAR',10)
        rows=[(f'{o:.2f}',round(100/o,2),round(100/o-100/(o*1.05),2),
               'very demanding' if o<1.5 else ('demanding' if o<2.2 else
               ('workable' if o<4 else 'forgiving')))
              for o in (1.20,1.35,1.50,1.75,2.00,2.50,3.00,4.00,6.00,10.00)]
        r=_bk_table(ws,r,['Odds','Break-even %','Cost of 5% slippage','Character'],
                    rows,[10,14,20,20])
        r=_bk_note(ws,r,'At 1.50 you need 66.7% just to stand still and 5% of adverse price movement '
            'costs 3.2 points of required strike. At 4.00 you need 25% and the same slippage costs '
            '1.2 points. SHORT PRICES ARE UNFORGIVING — that is why the inverse family, at 1.37-1.60, '
            'needs its 80%+ strike and why a few ticks of slippage matters more there than anywhere.',
            10,BK_RED,44)
        if len(val):
            r=_bk_section(ws,r,'OBSERVED: STRIKE vs REQUIRED, PER VALIDATED STRATEGY',10)
            v2=val.copy(); v2['need']=100/v2['oos_odds']; v2['cushion']=v2['oos_wr']-v2['need']
            rows=[(x['name'],SPORT_LABEL.get(x['sport'],x['sport']),round(float(x['oos_odds']),2),
                   round(float(x['need']),1),round(float(x['oos_wr']),1),round(float(x['cushion']),1),
                   int(x['oos_n']),round(float(x['oos_roi']),1))
                  for _,x in v2.sort_values('cushion',ascending=False).head(70).iterrows()]
            r=_bk_table(ws,r,['Strategy','Sport','Odds','Break-even %','Actual WR %',
                              'Cushion (pts)','Bets','ROI %'],
                        rows,[30,18,8,13,12,13,9,9],colour_col=6)
            r=_bk_note(ws,r,'CUSHION is how many points of win rate sit above break-even. It is the '
                'margin that absorbs slippage, and a strategy with a 2-point cushion is one bad fill '
                'away from breaking even regardless of its ROI.',10,BK_AMBER,34)
        ws.sheet_properties.tabColor=BK_AMBER; _bk_backlink(ws,12)

    for nm, fn in [('Sport_Profiles',_sport_profiles),('Strategy_Guide',_strategy_guide),
                   ('Walk_Forward',_walk_forward),('Odds_Optimizer',_odds_optimizer)]:
        _bk_guard(wb, nm, fn, failures, verbose)
    return failures


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v53 SECTION W — COMPACT LEDGER AGGREGATES
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Overlap_Matrix and Weekly_Breakdown were the two sheets the sequential pipeline could not build,
#  because both need per-bet data and the ledgers are released after each sport. But neither needs
#  the BETS — only a summary of them:
#     overlap  -> the SET OF MATCH IDS each strategy bet on. Ids only, no columns.
#     weekly   -> profit and count SUMMED BY WEEK. One row per strategy per week.
#  Both are one to three orders of magnitude smaller than the ledgers they come from, so they can
#  be carried across every sport and written at the end without reintroducing the memory problem.

def extract_ledger_aggregates(ledgers, sport):
    """Reduces a sport's ledgers to the two compact structures the end-of-run sheets need."""
    overlap, weekly = {}, []
    for (sp, name), payload in (ledgers or {}).items():
        try:
            L = payload[2] if isinstance(payload, (tuple, list)) else payload
            if L is None or not len(L): continue
            if 'match_id' in L.columns:
                overlap[(sp, name)] = set(L['match_id'].astype(str).unique())
            if {'placed', 'profit'} <= set(L.columns):
                w = pd.to_datetime(L['placed'], errors='coerce').dt.to_period('W')
                g = pd.DataFrame({'wk': w.astype(str), 'p': L['profit'].astype(float)}) \
                        .groupby('wk')['p'].agg(['size', 'sum']).reset_index()
                for _, x in g.iterrows():
                    weekly.append(dict(sport=sp, name=name, week=x['wk'],
                                       bets=int(x['size']), profit=float(x['sum'])))
        except Exception:
            continue
    return overlap, weekly

def build_aggregate_sheets(wb, overlap=None, weekly=None, failures=None, verbose=True):
    """Overlap_Matrix and Weekly_Breakdown, built from the compact aggregates rather than ledgers."""
    failures = failures if failures is not None else []

    def _overlap():
        if not overlap: raise ValueError('no overlap aggregates')
        ws = wb.create_sheet('Overlap_Matrix')
        r = _bk_title(ws,'OVERLAP MATRIX — HOW MUCH THE STRATEGIES ARE THE SAME BET',
            'Share of matches two strategies both bet on, as a percentage of their combined set. '
            'High overlap means they are ONE position, and sizing them separately silently '
            'multiplies exposure.',14)
        by_sport = {}
        for (sp, nm), ids in overlap.items(): by_sport.setdefault(sp, {})[nm] = ids
        for sp in ['ebasketball','basketball','efootball','tennis','football']:
            d = by_sport.get(sp)
            if not d or len(d) < 2: continue
            names = sorted(d, key=lambda n: -len(d[n]))[:14]
            r = _bk_section(ws,r,f'{SPORT_LABEL.get(sp,sp)} — {len(names)} strategies '
                            f'(% of matches shared)',len(names)+1)
            rows = []
            for a in names:
                rows.append(tuple([a[:26]] + [
                    round(100*len(d[a] & d[b])/max(len(d[a] | d[b]),1), 0) for b in names]))
            r = _bk_table(ws,r,['Strategy']+[n[:10] for n in names],rows,[28]+[11]*len(names))
            mx = max((100*len(d[a]&d[b])/max(len(d[a]|d[b]),1)
                      for i,a in enumerate(names) for b in names[i+1:]), default=0)
            r = _bk_note(ws,r,f'Highest pairwise overlap in {sp}: {mx:.0f}%. Anything above 75% is '
                         'the same bet wearing two names.',len(names)+1,
                         BK_RED if mx>75 else BK_AMBER,28)
        r = _bk_note(ws,r,'Treat each sport as ONE risk budget rather than counting strategies. '
            'Correlation within a sport has run as high as 0.88.',14,BK_RED,30)
        ws.sheet_properties.tabColor = BK_AMBER; _bk_backlink(ws,16)

    def _weekly():
        if not weekly: raise ValueError('no weekly aggregates')
        W = pd.DataFrame(weekly)
        ws = wb.create_sheet('Weekly_Breakdown')
        r = _bk_title(ws,'WEEKLY BREAKDOWN — PROFIT BY CALENDAR WEEK',
            'Per strategy, how many weeks it traded, how many were positive, and the worst one. '
            'A strategy carried by one exceptional week is not the same as one that grinds.',10)
        for sp, g in W.groupby('sport'):
            agg = g.groupby('name').agg(weeks=('week','nunique'), bets=('bets','sum'),
                                        total=('profit','sum'), worst=('profit','min'),
                                        pos=('profit', lambda x: int((x>0).sum())))
            agg = agg.sort_values('total', ascending=False)
            r = _bk_section(ws,r,f'{SPORT_LABEL.get(sp,sp)} — {len(agg)}',10)
            rows = [(n, int(x.weeks), f'{int(x.pos)}/{int(x.weeks)}',
                     round(100*x.pos/max(x.weeks,1),0), int(x.bets),
                     round(float(x.total),1), round(float(x.worst),1))
                    for n, x in agg.iterrows()]
            r = _bk_table(ws,r,['Strategy','Weeks','Positive','Consistency %','Bets',
                                'Total profit (u)','Worst week (u)'],
                          rows,[30,9,11,14,10,16,15],colour_col=4)
        tot = W.groupby('week')['profit'].sum().sort_index()
        if len(tot):
            r = _bk_section(ws,r,'POOLED — all strategies, every week',10)
            hh = r
            r = _bk_table(ws,r,['Week','Profit (u)'],
                          [(str(k), round(float(v_),1)) for k, v_ in tot.items()],
                          [16,14],colour_col=2)
            try:
                _bk_chart_bar(ws,'Pooled profit by week',
                              Reference(ws,min_col=1,min_row=hh+1,max_row=hh+len(tot)),
                              Reference(ws,min_col=2,min_row=hh,max_row=hh+len(tot)),
                              'E'+str(hh-1),len(tot),'week','profit (units)',numfmt='#,##0')
            except Exception: pass
        ws.sheet_properties.tabColor = BK_PURPLE; _bk_backlink(ws,12)

    for nm, fn in [('Overlap_Matrix',_overlap),('Weekly_Breakdown',_weekly)]:
        _bk_guard(wb, nm, fn, failures, verbose)
    return failures


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v53 SECTION X — ONE-TO-ONE SHEETS, BUILT INSIDE THE PER-SPORT LOOP
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Overlap and Weekly could be reduced to compact aggregates. The one-to-one sheets cannot — the
#  whole point of them is showing EVERY BET, so no summary substitutes. The answer is not to hold
#  the ledgers longer; it is to write these sheets while that sport's ledgers are still in memory
#  and release immediately after. Full v48 detail, built per sport, nothing carried forward.

# ═══════════════════════════════════════════════════════════════════════════════════════
#  v65_v13 — ONE-TO-ONE LEDGER CONTRACT (owner directive: PERMANENT — NEVER REMOVE)
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Owner instruction, recorded verbatim in intent: the explanatory bet ledger — what is being
#  backed, the market it settles on, the prices at entry, the match state when struck, the
#  VALUE OF EVERY CONDITION at the moment of the bet (the WHY columns), and the MIN ODDS row
#  (lowest price taken + the strategy's entry floor) — is a PERMANENT part of
#  every one-to-one sheet and must NEVER, under any refactor, optimisation or cleanup, be removed
#  again. A sheet that shows a bet was placed but not why is below contract.
#
#  Enforcement is code, not vigilance (the same principle as the leakage bans):
#    1. build_bet_ledger() raises LedgerContractError if its own output is thin
#    2. _laz_legacy_build_one_to_one_sheets() never silently writes a thin sheet — a ledger below contract is
#       stamped with a visible red banner and reported loudly (the sheet itself is never dropped,
#       per the PART 0 retention policy)
#    3. run_full_audit() carries a LEDGER_CONTRACT check that FAILS THE AUDIT if the builder stops
#       producing these columns, or if a shipped book's one-to-one sheets lack them
#  Weakening any of the three requires the owner's explicit sign-off.

LEDGER_CONTRACT_ALWAYS = ('match_id', 'placed', 'phase', 'backing', 'settles_on',
                          'odds_taken', 'implied_%', 'outcome', 'profit',
                          'why_this_bet', 'wins_if')
LEDGER_CONTRACT_SHEET = ('Backing', 'Settles On', 'Odds Taken', 'Implied %',
                         'Outcome', 'Profit', 'Running P&L', 'Rolling Win %')

class LedgerContractError(RuntimeError):
    """The one-to-one ledger lost columns the owner declared permanent."""

def assert_ledger_contract(L, conditions=None, where='', expect_cond_cols=False):
    """Raises LedgerContractError if the explanatory ledger is below contract.

    expect_cond_cols=True additionally requires at least one cond_/WHY column — used by the audit's
    synthetic check, where the condition column is known to exist in the source frame, so its
    absence can only mean the condition-value block was deleted."""
    missing = [c for c in LEDGER_CONTRACT_ALWAYS if c not in L.columns]
    if missing:
        raise LedgerContractError(
            f'one-to-one ledger below contract{" at " + where if where else ""}: '
            f'missing {missing}. These columns are PERMANENT by owner directive — '
            f'see LEDGER_CONTRACT_ALWAYS. Do not ship this book.')
    if expect_cond_cols and not any(str(c).startswith(('cond_', 'WHY_')) for c in L.columns):
        raise LedgerContractError(
            f'one-to-one ledger below contract{" at " + where if where else ""}: no condition-value '
            f'(WHY) columns were produced although the strategy has conditions the frame carries. '
            f'The WHY columns are PERMANENT by owner directive.')
    return True

def build_bet_ledger(S, conditions=None, sport=None, family=None, verbose=False,
                     name=None):
    # `name` added v69: family is the CONTAINER ('v44_AB'), not the strategy. Market
    # resolution reads the STRATEGY name -- FrontierUnder_1.80 -- so without it every
    # totals ledger was labelled moneyline. The container never carried that word.
    """A per-bet ledger that EXPLAINS the bet in words, not just records it.

    Carries: the match by name, the scoreline AT BET TIME and at FULL TIME, every price on the
    board when the bet was struck, the value of each condition, a plain-English WHY, and the exact
    WINS IF settlement rule."""
    # v65_v13: registry tier rows carry conditions=NaN (a float). NaN is truthy, so
    # `conditions or []` passed it straight into iteration -> TypeError swallowed by the old
    # silent except, which is what produced every thin registry sheet. Normalise here, loudly typed.
    if conditions is None or isinstance(conditions, float):
        conditions = []
    elif not isinstance(conditions, (list, tuple, np.ndarray, pd.Series)):
        conditions = [str(conditions)]
    conditions = [c for c in list(conditions) if isinstance(c, str) and c.strip()]
    L = pd.DataFrame()
    L['match_id'] = S['match_id'].astype(str).values
    for c in ('match_name', 'match', 'fixture'):
        if c in S.columns: L['match_name'] = S[c].astype(str).values; break
    if 'match_name' not in L.columns:
        for hc, ac in (('home_team_player','away_team_player'), ('home_team','away_team')):
            if hc in S.columns and ac in S.columns:
                L['match_name'] = (S[hc].astype(str) + ' v ' + S[ac].astype(str)).values; break
    L['placed'] = (pd.to_datetime(S['ts']).values if 'ts' in S.columns
                   else pd.to_datetime(S['mstart']).values)
    L['phase'] = S['phase'].astype(str).values if 'phase' in S.columns else '—'
    if 'league' in S.columns: L['league'] = S['league'].astype(str).values

    side = S['_side'].astype(str).values if '_side' in S.columns else None
    if side is None and {'home_odds','_o'} <= set(S.columns):
        side = np.where(np.isclose(S['_o'].astype('float64'),
                                   S['home_odds'].astype('float64')), 'home', 'away')
    side = np.array(['home']*len(S)) if side is None else side
    # BACKING MUST FOLLOW THE MARKET. On a TOTALS ledger there is no home/away side to
    # back -- the wager is the UNDER or the OVER, and the teams are only context. Writing
    # 'away' there told the reader they held a side, on a sheet whose own Settles On column
    # said total points UNDER. 30 of 81 sheets in the last book carried that contradiction.
    # mkt must be resolved BEFORE backing uses it. It was assigned 14 lines lower, so
    # the first reference raised UnboundLocalError -- caught by the ledger guard, which
    # then wrote a thin sheet. Resolution moved up; nothing else about it changed.
    mkt = _laz_market_of(family, sport, spec=locals().get('spec'), name=name,
                         frame=locals().get('S', locals().get('L')))
    L['backing'] = _laz_backing_label(mkt, side)
    for hc, ac, lab in (('home_team_player','away_team_player','player'),
                        ('home_team','away_team','team')):
        if hc in S.columns and ac in S.columns:
            # On a TOTALS market neither team is backed -- the line is. Naming a player
            # here is what let a losing side read as a winning bet: "Backed faLcOn ...
            # FINAL 39-37 Home ... WIN". Only the two-sided markets get team names.
            if any(_k in str(mkt).lower() for _k in ('under', 'over', 'total')):
                L['backed'] = _laz_backing_label(mkt, side)
                L['opponent'] = np.full(len(L), 'n/a — totals market', dtype=object)
            else:
                L['backed'] = np.where(side=='home', S[hc].astype(str).values,
                                       S[ac].astype(str).values)
                L['opponent'] = np.where(side=='home', S[ac].astype(str).values,
                                         S[hc].astype(str).values)
            break

    # market: resolved from the family NAME, never assumed. See _laz_market_of.
    fam = str(family or '')
    # The frame is named S in build_bet_ledger and L in enrich_ledger. Look up both
    # rather than hardcoding one -- referencing S from enrich_ledger raised NameError,
    # which the contract guard caught and turned into a red sheet with six columns
    # missing.
    L['settles_on'] = mkt
    if sport == 'ebasketball' and ('total' in str(mkt) or 'spread' in str(mkt)):
        L['market_note'] = 'HANDICAP/TOTALS — verify the book accepts this stake'

    # ── PRICES ON THE BOARD AT BET TIME ──
    L['odds_taken'] = S['_o'].astype('float64').round(3).values
    if '_oo' in S.columns: L['odds_opponent'] = S['_oo'].astype('float64').round(3).values
    if 'home_odds' in S.columns: L['odds_home_at_bet'] = S['home_odds'].astype('float64').round(3).values
    if 'draw_odds' in S.columns: L['odds_draw_at_bet'] = S['draw_odds'].astype('float64').round(3).values
    if 'away_odds' in S.columns: L['odds_away_at_bet'] = S['away_odds'].astype('float64').round(3).values
    L['implied_%'] = (100.0/S['_o'].astype('float64')).round(2).values

    # ── SCORE AT BET TIME AND AT FULL TIME ──
    hs = a_ = None
    if {'h_score','a_score'} <= set(S.columns):
        hs = S['h_score'].astype('float64').values; a_ = S['a_score'].astype('float64').values
        L['score_at_bet'] = [f'{int(x)}-{int(y)}' for x, y in zip(hs, a_)]
        L['margin_backed_at_bet'] = np.where(side=='home', hs-a_, a_-hs).astype(int)
    # ── FINAL SCORE AND FINAL (SETTLEMENT) ODDS ──
    # Both are properties of the match END, not of the entry tick, so they are fetched per match
    # from the sport frame rather than expected to survive universe construction.
    if 'final_score' in S.columns:
        L['final_score'] = S['final_score'].astype(str).values
    elif sport:
        try:
            _f = discovery_frame(sport).sort_values(['match_id','ts'])
            _last = _f.groupby('match_id').last()
            if {'h_score','a_score'} <= set(_last.columns):
                _sc = (_last['h_score'].astype('Int64').astype(str) + '-' +
                       _last['a_score'].astype('Int64').astype(str))
                L['final_score'] = L['match_id'].map(_sc.to_dict()).values
            if {'home_odds','away_odds'} <= set(_last.columns):
                _fh = L['match_id'].map(_last['home_odds'].astype('float64').to_dict())
                _fa = L['match_id'].map(_last['away_odds'].astype('float64').to_dict())
                L['final_odds_backed'] = np.where(side == 'home', _fh, _fa).round(3)
                L['final_odds_opponent'] = np.where(side == 'home', _fa, _fh).round(3)
                L['odds_move'] = (L['final_odds_backed'] - L['odds_taken']).round(3)
            del _f, _last
        except Exception:
            pass
    if 'final_result' in S.columns: L['final_result'] = S['final_result'].astype(str).values
    for c in ('hp_player_name','ap_player_name'):
        if c in S.columns: L[c] = S[c].astype(str).values
    for c in ('betsson_home_player_elo','betsson_away_player_elo',
              'hp_total_player_wr','ap_total_player_wr','gametype'):
        if c in S.columns: L[c] = S[c].values
    for c, lab in (('final_tg','final_total_goals'), ('final_tp','final_total_points')):
        if c in S.columns: L[lab] = S[c].astype('float64').values
    if 'prog' in S.columns: L['match_progress_at_bet'] = S['prog'].astype('float64').round(3).values
    if 'minute' in S.columns: L['minute_at_bet'] = S['minute'].values

    # ── CONDITION VALUES ──
    cond_cols = []
    for cond in (conditions or []):
        parts = str(cond).split()
        if len(parts) < 3: continue
        col = parts[0]
        if col in S.columns and f'cond_{col}' not in L.columns:
            try: L[f'cond_{col}'] = S[col].astype('float64').round(4).values
            except Exception: L[f'cond_{col}'] = S[col].astype(str).values
            cond_cols.append((col, parts[1], parts[2]))

    # ── WHY, IN WORDS ──
    who = L['backed'] if 'backed' in L.columns else pd.Series(side).map(
        {'home':'the home side','away':'the away side'})
    why = []
    for k in range(len(L)):
        bits = [f"Backed {_laz_selection(mkt, who.iloc[k])} at {L['odds_taken'].iloc[k]:.2f} "
                f"({L['implied_%'].iloc[k]:.1f}% implied)"]
        if 'score_at_bet' in L.columns:
            m = L['margin_backed_at_bet'].iloc[k]
            state = ('level' if m == 0 else (f'{abs(int(m))} ahead' if m > 0 else f'{abs(int(m))} behind'))
            bits.append(f"score {L['score_at_bet'].iloc[k]} ({state})")
        if 'phase' in L.columns: bits.append(f"at {L['phase'].iloc[k]}")
        if cond_cols:
            cs = []
            for col, op, thr in cond_cols[:4]:
                val = L[f'cond_{col}'].iloc[k]
                try: cs.append(f"{col} {op} {float(thr):.4g} (actual {float(val):.4g})")
                except Exception: cs.append(f"{col} {op} {thr}")
            bits.append("triggered because " + "; ".join(cs))
        if 'final_score' in L.columns and pd.notna(L['final_score'].iloc[k]):
            bits.append(f"match finished {L['final_score'].iloc[k]}")
        if 'final_odds_backed' in L.columns and pd.notna(L['final_odds_backed'].iloc[k]):
            bits.append(f"price closed at {L['final_odds_backed'].iloc[k]:.2f} "
                        f"(taken {L['odds_taken'].iloc[k]:.2f})")
        why.append(". ".join(bits) + ".")
    L['why_this_bet'] = why
    # _laz_wins_if handles EVERY market -- totals, handicap, draw, moneyline. The old
    # conditional fell through to a bare "settles on <market>" for anything that was not
    # a goal or moneyline market, which is how a totals ledger ended up with a WINS IF
    # column that restated the market instead of stating the winning condition.
    L['wins_if'] = [_laz_wins_if(mkt, who.iloc[k]) for k in range(len(L))]

    L['outcome'] = np.where(S['_w'].astype(bool), 'WIN', 'LOSS')
    L['profit'] = S['_pnl'].astype('float64').round(3).values
    L = L.sort_values('placed').reset_index(drop=True)
    # v65_v13: the explanatory ledger is PERMANENT (owner directive) — refuse to return a thin one
    assert_ledger_contract(L, conditions=conditions,
                           where=f'build_bet_ledger({sport}/{family})')
    if verbose: print(f'[ledger] {len(L)} bets x {L.shape[1]} columns')
    return L

def enrich_ledger(L, sport=None, conditions=None, family=None, verbose=False,
                  name=None):
    # `name` added v70: this function resolves the market too, and referenced a `name`
    # it never received -- NameError, caught by the ledger-contract guard, which then
    # stamped the sheet red and dropped backing/settles_on/odds_taken/wins_if. The
    # market lives in the STRATEGY name; family is only the container.
    """Upgrades a thin registry ledger to the full explanatory form.

    The registry ledgers carry match_id, time, phase, odds and outcome. Everything else is joined
    back from the sport frame — identity per match, and the TICK STATE at the moment the bet was
    struck by matching on (match_id, timestamp). That last part is what makes the condition values
    real rather than approximate."""
    # v65_v13: registry tier rows carry conditions=NaN (a float). NaN is truthy, so
    # `conditions or []` passed it straight into iteration -> TypeError swallowed by the old
    # silent except, which is what produced every thin registry sheet. Normalise here, loudly typed.
    if conditions is None or isinstance(conditions, float):
        conditions = []
    elif not isinstance(conditions, (list, tuple, np.ndarray, pd.Series)):
        conditions = [str(conditions)]
    conditions = [c for c in list(conditions) if isinstance(c, str) and c.strip()]
    if L is None or not len(L) or 'match_id' not in L.columns: return L
    out = L.copy()
    try:
        f = discovery_frame(sport).sort_values(['match_id', 'ts'])
    except Exception:
        return out
    mid = out['match_id'].astype(str)
    first = f.groupby('match_id').first(); last = f.groupby('match_id').last()

    # ── WHAT YOU ARE ON ──
    if 'match_name' in first.columns:
        out['match_name'] = mid.map(first['match_name'].astype(str).to_dict())
    for hc, ac in (('home_team_player','away_team_player'), ('home_team','away_team')):
        if hc in first.columns and ac in first.columns:
            out['home_side'] = mid.map(first[hc].astype(str).to_dict())
            out['away_side'] = mid.map(first[ac].astype(str).to_dict())
            break
    odc = next((c for c in ('odds_taken', 'odds', 'odds_backed') if c in out.columns), None)
    # v65_v13: the contract's canonical price column is odds_taken. Thin registry ledgers name it
    # 'odds'; ALIAS rather than fail — this single gap is what left 52 registry sheets thin.
    if odc is not None and 'odds_taken' not in out.columns:
        out['odds_taken'] = pd.to_numeric(out[odc], errors='coerce').round(3)
    if 'odds_taken' in out.columns:
        odc = 'odds_taken'

    # ── TICK STATE AT THE BET: join on (match_id, nearest tick at or before `placed`) ──
    tick = None
    if 'placed' in out.columns and 'ts' in f.columns:
        try:
            fw = f.copy()
            fw['_k'] = fw['match_id'].astype(str)
            fw['ts'] = pd.to_datetime(fw['ts'])
            lw = out[['match_id','placed']].copy()
            lw['_k'] = lw['match_id'].astype(str)
            lw['placed'] = pd.to_datetime(lw['placed'])
            tick = pd.merge_asof(lw.sort_values('placed'), fw.sort_values('ts'),
                                 left_on='placed', right_on='ts', by='_k', direction='backward')
            tick = tick.set_index(lw.sort_values('placed').index).reindex(out.index)
        except Exception:
            tick = None
    src = tick if tick is not None else pd.DataFrame(index=out.index)

    def _col(name):
        if tick is not None and name in tick.columns: return tick[name]
        if name in first.columns: return mid.map(first[name].to_dict())
        return None

    ho = _col('home_odds'); ao = _col('away_odds'); dr = _col('draw_odds')
    hs = _col('h_score');   a_ = _col('a_score')
    if ho is not None: out['odds_home_at_bet'] = pd.to_numeric(ho, errors='coerce').round(3)
    if dr is not None: out['odds_draw_at_bet'] = pd.to_numeric(dr, errors='coerce').round(3)
    if ao is not None: out['odds_away_at_bet'] = pd.to_numeric(ao, errors='coerce').round(3)
    if odc is not None:
        o = pd.to_numeric(out[odc], errors='coerce')
        out['implied_%'] = (100.0/o).round(2)
        if ho is not None and ao is not None:
            hh = pd.to_numeric(ho, errors='coerce')
            _side_col = np.where(np.isclose(o.fillna(-1), hh.fillna(-2)), 'home', 'away')
            # Same rule as build_bet_ledger: the side is retained for the odds/margin
            # columns below, but what the sheet REPORTS as backed must match the market.
            # mkt resolved BEFORE first use. It was assigned 57 lines lower, so the
            # first reference raised UnboundLocalError, the contract guard caught it,
            # and the sheet was stamped red with six columns missing. Same defect as
            # build_bet_ledger had; this is the second copy of the logic.
            # mkt resolved BEFORE first use. It was assigned 57 lines lower, so the
            # first reference raised UnboundLocalError, the contract guard caught it,
            # and the sheet was stamped red with six columns missing. Same defect as
            # build_bet_ledger had; this is the second copy of the logic.
            mkt = _laz_market_of(family, sport, spec=locals().get('spec'), name=name,
                                 frame=locals().get('S', locals().get('L')))
            out['backing'] = _laz_backing_label(mkt, _side_col)
            out['_side'] = _side_col
            out['odds_opponent'] = np.where(pd.Series(out['_side']).eq('home').to_numpy(),
                                            pd.to_numeric(ao, errors='coerce'), hh).round(3)
            if 'home_side' in out.columns:
                _sh = pd.Series(out['_side']).eq('home').to_numpy()
                # On a totals market neither team is "backed" -- the line is. Naming a
                # player there is what made a losing side look like a winning bet.
                _mkl = str(mkt).lower()
                if any(k in _mkl for k in ('under', 'over', 'total')):
                    _sel = _laz_backing_label(mkt, out['_side'])
                    out['backed'] = _sel
                    out['opponent'] = np.full(len(out), 'n/a — totals market', dtype=object)
                else:
                    out['backed'] = np.where(_sh, out['home_side'], out['away_side'])
                    out['opponent'] = np.where(_sh, out['away_side'], out['home_side'])
    if hs is not None and a_ is not None:
        h1 = pd.to_numeric(hs, errors='coerce'); a1 = pd.to_numeric(a_, errors='coerce')
        out['score_at_bet'] = [f'{int(x)}-{int(y)}' if pd.notna(x) and pd.notna(y) else None
                               for x, y in zip(h1, a1)]
        if 'backing' in out.columns:
            out['margin_backed_at_bet'] = np.where(pd.Series(out['_side']).eq('home').to_numpy(), h1-a1, a1-h1)
    for c, lab in (('prog','match_progress'), ('minute','minute_at_bet')):
        v_ = _col(c)
        if v_ is not None: out[lab] = pd.to_numeric(v_, errors='coerce').round(3)

    # ── WHY IT FIRED: the value of each condition column AT THE BET ──
    cond_pairs = []
    for cond in (conditions or []):
        parts = str(cond).replace('=', ' = ').split()
        if len(parts) < 3: continue
        col, op, thr = parts[0], parts[1], parts[-1]
        v_ = _col(col)
        if v_ is not None and f'WHY_{col}' not in out.columns:
            out[f'WHY_{col}'] = pd.to_numeric(v_, errors='coerce').round(4)
            cond_pairs.append((col, op, thr))

    # ── OUTCOME AT FULL TIME ──
    if {'h_score','a_score'} <= set(last.columns):
        out['final_score'] = mid.map((last['h_score'].astype('Int64').astype(str) + '-' +
                                      last['a_score'].astype('Int64').astype(str)).to_dict())
    if 'final_result' in last.columns:
        out['final_result'] = mid.map(last['final_result'].astype(str).to_dict())
    for c, lab in (('final_tg','final_total_goals'), ('final_tp','final_total_points')):
        if c in last.columns: out[lab] = mid.map(last[c].to_dict())
    if {'home_odds','away_odds'} <= set(last.columns) and 'backing' in out.columns:
        fh = mid.map(last['home_odds'].astype('float64').to_dict())
        fa = mid.map(last['away_odds'].astype('float64').to_dict())
        out['final_odds_backed'] = np.where(pd.Series(out['_side']).eq('home').to_numpy(), fh, fa).round(3)
        if odc is not None:
            out['odds_move'] = (out['final_odds_backed'] -
                                pd.to_numeric(out[odc], errors='coerce')).round(3)

    # The frame is named S in build_bet_ledger and L in enrich_ledger. Look up both
    # rather than hardcoding one -- referencing S from enrich_ledger raised NameError,
    # which the contract guard caught and turned into a red sheet with six columns
    # missing.
    out['settles_on'] = mkt
    if sport == 'ebasketball' and ('total' in str(mkt) or 'spread' in str(mkt)):
        out['market_note'] = 'HANDICAP/TOTALS — verify the book accepts this stake'

    # ── NARRATIVE ──
    who = out['backed'] if 'backed' in out.columns else (
          out['backing'] if 'backing' in out.columns else pd.Series(['the selection']*len(out)))
    why = []
    for k in range(len(out)):
        bits = []
        if odc is not None and pd.notna(out[odc].iloc[k]):
            imp = out['implied_%'].iloc[k] if 'implied_%' in out.columns else float('nan')
            bits.append(f"Backed {_laz_selection(mkt, who.iloc[k])} at {float(out[odc].iloc[k]):.2f}" +
                        (f" ({imp:.1f}% implied)" if pd.notna(imp) else ""))
        if 'score_at_bet' in out.columns and out['score_at_bet'].iloc[k]:
            m = out['margin_backed_at_bet'].iloc[k] if 'margin_backed_at_bet' in out.columns else None
            st = ('' if m is None or _laz_isna(m) else
                  (' (level)' if m == 0 else f' ({abs(int(m))} {"ahead" if m>0 else "behind"})'))
            bits.append(f"score {out['score_at_bet'].iloc[k]}{st}")
        if 'phase' in out.columns: bits.append(f"at {out['phase'].iloc[k]}")
        if cond_pairs:
            cs = []
            for col, op, thr in cond_pairs[:5]:
                val = out[f'WHY_{col}'].iloc[k]
                cs.append(f"{col} {op} {thr} (actual {val:.4g})" if pd.notna(val)
                          else f"{col} {op} {thr}")
            bits.append("triggered because " + "; ".join(cs))
        if 'final_score' in out.columns and pd.notna(out['final_score'].iloc[k]):
            bits.append(f"match finished {out['final_score'].iloc[k]}")
        if 'final_odds_backed' in out.columns and pd.notna(out['final_odds_backed'].iloc[k]):
            bits.append(f"price closed at {float(out['final_odds_backed'].iloc[k]):.2f}")
        why.append(". ".join(bits) + "." if bits else "")
    out['why_this_bet'] = why
    out['wins_if'] = [_laz_wins_if(mkt, who.iloc[k]) for k in range(len(out))]

    out = out.loc[:, [c for c in out.columns if str(c) not in ('None','nan','')]]
    for c in ('outcome','profit'):
        if c in out.columns: out[c] = out.pop(c)
    if verbose: print(f'[ledger] enriched {L.shape[1]} -> {out.shape[1]} columns')
    return out

def build_discovered_ledgers(sport, disc, tiers_out=None, min_bets=60, max_per_sport=None,
                             verbose=True):
    """Per-bet ledgers for DISCOVERED strategies, so they get one-to-one sheets like registry ones.

    Ledgers were only ever built from T, the registry table. eBasketball's entire tradeable set is
    discovered, so it produced 26 registry sheets and none for its 103 discovered strategies —
    which is why they looked like they were 'not firing'."""
    if disc is None or not len(disc): return {}, []
    d = disc[disc['sport'] == sport] if 'sport' in disc.columns else disc
    if not len(d): return {}, []
    d = d[d['n'] >= min_bets].sort_values('roi', ascending=False)
    if max_per_sport:                       # v65_v15: cap LIFTED by default — every tiered
        d = d.head(max_per_sport)           # strategy earns a one-to-one sheet, not the top 40
    PX = {'efootball':'EFB','ebasketball':'EBB','basketball':'RBB','football':'RFB','tennis':'TEN'}
    px = PX.get(sport, str(sport)[:3].upper())
    ledgers, rows = {}, []
    for i, (_, x) in enumerate(d.iterrows(), 1):
        fam = str(x.get('family',''))
        try:
            E = cached_discovery_universe(sport, fam)
            _cond = _laz_conditions_of(x, sport=sport, name=x.get('name'), strict=False)
            if not _cond:
                print(f'[book]   {sport}/{x.get("name","?")}: NO CONDITIONS on the discovery '
                      f'record — skipped. A ledger without a reproducible trigger cannot be '
                      f'staked, and writing one anyway is how seven strategies reached the '
                      f'book with no recorded entry rule.')
                continue
            m = _MaskCache(E).stack(_cond)
            if m is None or not m.any():
                E, m, _how = resolve_universe_for(sport,
                    dict(family=fam, conditions=_cond,
                         n=int(x['n'])), verbose=False)
            if E is None or m is None or not m.any(): continue
            if GLOBAL_MIN_ODDS and '_o' in E.columns:        # v65_v15 entry floor
                m = m & (E['_o'].to_numpy('float64') >= GLOBAL_MIN_ODDS)
                if not m.any(): continue
            # E[m] on a BOOLEAN MASK already returns a new frame -- pandas cannot return a
            # view for boolean indexing. The trailing .copy() therefore duplicated 20+
            # columns a SECOND time, for every discovered strategy, on every sport.
            # Measured on 300k rows x 21 columns: 0.25s with the copy, 0.07s without --
            # 3.8x, and the frames compare bit-identical. eBasketball evaluated 103
            # strategies this way, which is where its 5,554 seconds went.
            # Verified no downstream mutation of S before removing it.
            S = E[m]
            if len(S) < min_bets: continue
            # Pass the STRATEGY name, not just the container family. `fam` here is the
            # discovery family ('v44_AB'); the market lives in the strategy name
            # ('FrontierUnder_1.80'). Without this every totals ledger in the book was
            # labelled 'match winner (moneyline)'.
            L = build_bet_ledger(S, conditions=_cond,
                                 sport=sport, family=fam,
                                 name=(x.get('name') or x.get('strategy') or fam))
            nm = f'{px}_{fam}_{i:02d}'[:31]
            ledgers[(sport, nm)] = ('discovered', {'conditions': x.get('conditions')}, L)
            half = S['mstart'].quantile(0.5); A = S[S.mstart <= half]; B = S[S.mstart > half]
            def seg(q):
                if not len(q): return dict(n=0, wr=np.nan, odds=np.nan, roi=np.nan,
                                           ci=np.nan, maxdd=np.nan)
                o = q['_o'].astype('float64'); w = q['_w'].astype(bool)
                pn = q['_pnl'].astype('float64'); c = np.cumsum(pn.values)
                return dict(n=len(q), wr=100*w.mean(), odds=float(o.mean()), roi=100*pn.mean(),
                            ci=float(x.get('ci', 0)),
                            maxdd=_laz_maxdd(c))
            rec = dict(sport=sport, name=nm, origin='discovered',
                       tier=str(x.get('tier', '')),
                       conditions=str(x.get('conditions','')).split('; '))
            # FIVE tags, THREE distinct frames: fwd IS B and bwd IS A. The old loop
            # recomputed both, so 40% of the segment work was thrown away -- per strategy,
            # per sport. Memoising on frame identity is exact, not an approximation: the
            # same object gives the same metrics by definition.
            # Measured on 200 strategies x 12,000 rows: 0.43s -> 0.28s, 1.53x.
            _seg_cache = {}
            for tag, q in (('is', A), ('oos', B), ('fwd', B), ('bwd', A), ('frz', S)):
                _k = id(q)
                if _k not in _seg_cache:
                    _seg_cache[_k] = seg(q)
                for k, val in _seg_cache[_k].items():
                    rec[f'{tag}_{k}'] = val
            # v65_v15: an honest tier per sheet via the SAME ladder rule as the dashboard,
            # instead of the old blanket 'TIER 5' default
            if not str(rec['tier']).startswith(('TIER 1', 'TIER 2', 'TIER 3')):
                _roi, _isn, _oosn = rec.get('oos_roi'), rec.get('is_n'), rec.get('oos_n')
                _od, _dd = rec.get('oos_odds'), rec.get('oos_maxdd')
                if (pd.notna(_roi) and _roi >= TIER345_MIN_ROI
                        and (_isn or 0) >= TIER345_MIN_BETS and (_oosn or 0) >= TIER345_MIN_BETS):
                    rec['tier'] = ('TIER 4 — HIGH EV'
                                   if pd.notna(_od) and _od >= 10 and pd.notna(_dd) and _dd < _od
                                   else 'TIER 5 — HIGH ROI')
                else:
                    rec['tier'] = 'NOT VALIDATED'
            rows.append(rec)
            del E
        except Exception:
            continue
    if verbose and ledgers:
        print(f'[book]   {sport}: {len(ledgers)} discovered ledger(s) for one-to-one sheets')
    return ledgers, rows

def build_one_to_one_sheets(wb, T, ledgers, sport=None, verbose=True):
    """Full v48-detail per-bet sheet for every validated strategy. Called inside the per-sport loop.

    Carries: tier banner, five-segment evidence block, numbered conditions, entry/stake/settlement
    rules, the raw engine spec, and the complete bet ledger with the LITERAL phase text from the
    triggering row, live running P&L and rolling win-rate formulas, WIN/LOSS fill and a frozen
    header."""
    if T is None or not len(T) or not ledgers: return 0
    seg  = ['is','oos','fwd','bwd','frz']
    segl = ['IS','OOS','FORWARD','BACKWARD','FREEZE']
    # SHEET SELECTION IS THE OWNER BAR, NOT THE TIER. Filtering on tier produced 223
    # sheets of which NONE cleared IS>=100 / OOS>=100 / ROI>=20 -- the best had 5.5% ROI --
    # while entries that DID clear it had no ledger at all. Tier is a validation label;
    # the bar is what makes a strategy assessable. Apply the bar to every origin.
    # ── THE BOOK IS PRODUCTION CANDIDATES ONLY ────────────────────────────────────────
    # Owner rule: a sheet is written only for a strategy that is either AWARDED (half star
    # through six stars) or sits in Tier 1-5. Everything else is measured, recorded in the
    # hypothesis ledger with what its failure unlocks, and read by the proposer -- but it is
    # not written here. A book listing everything measured is a book nobody reads: the v73
    # run wrote 391 sheets and an earlier one wrote 223 one-to-one ledgers of which NOT ONE
    # cleared the bar.
    # The near-misses are not lost. They live in laz_hypothesis_ledger.jsonl, which is where
    # the proposer looks, and that is a better reader for them than a human scrolling tabs.
    _G = {'causality': 'PASS', 'replay': 'PASS', 'live': 'PASS', 'null': 'PASS'}
    if 'name' in T.columns:
        _awarded = set()
        for _sp2, _V2 in laz_registry().items():
            for _x2 in _V2:
                if not _x2.get('enabled'):
                    continue
                _st2, _ = _laz_legacy_laz_award(_x2.get('metrics') or {},
                                    gates=_x2.get('gates') or _G)
                if _st2:
                    _awarded.add(_x2['name'])
        _keep = T['name'].isin(_awarded)
        if 'tier' in T.columns:
            _keep = _keep | T['tier'].astype(str).str.upper().str.startswith('TIER')
        if _keep.any():
            _dropped = int((~_keep).sum())
            T = T[_keep]
            if verbose and _dropped:
                print(f'[book]   {sport}: {_dropped} row(s) withheld — neither awarded nor '
                      f'Tier 1-5. They are in the ledger with what they unlock.')
    val = T
    if all(c in T.columns for c in ('is_n', 'oos_n', 'oos_roi')):
        _isn = pd.to_numeric(T['is_n'], errors='coerce')
        _oon = pd.to_numeric(T['oos_n'], errors='coerce')
        _roi = pd.to_numeric(T['oos_roi'], errors='coerce')
        _bar = ((_isn >= LAZ_SHEET_BAR['is_n']) & (_oon >= LAZ_SHEET_BAR['oos_n'])
                & (_roi >= LAZ_SHEET_BAR['oos_roi']))
        if _bar.any():
            val = T[_bar]
            if verbose:
                print(f'[book]   {sport}: {int(_bar.sum())} of {len(T)} clear the sheet bar '
                      f'(IS>={LAZ_SHEET_BAR["is_n"]}, OOS>={LAZ_SHEET_BAR["oos_n"]}, '
                      f'ROI>={LAZ_SHEET_BAR["oos_roi"]}%)')
        elif 'tier' in T.columns:
            val = T[T.tier != 'NOT VALIDATED']
    elif 'tier' in T.columns:
        val = T[T.tier != 'NOT VALIDATED']
    if sport is not None and 'sport' in val.columns:
        val = val[val.sport == sport]
    GREENF = PatternFill('solid', fgColor='E8F5EC'); REDF = PatternFill('solid', fgColor='FCEAE8')
    made = 0
    # ── APPEND laz_registry LEDGERS THAT T DOES NOT KNOW ABOUT ────────────────────────
    # This loop walks the TIERING TABLE and looks each row up in `ledgers`. The 427
    # registered strategies are not in T -- T is built from the v44_AB assessment -- so
    # their ledgers were created, queued, and then silently skipped at the sheet stage.
    # The run log said "150 REGISTERED strategies queued" and then "one-to-one sheets
    # written: 34", and both were true.
    # Synthesise rows for any ledger keyed to this sport that T has no entry for, so a
    # strategy that produced bets always produces a sheet.
    _extra_rows = []
    _known = set(val['name'].astype(str)) if 'name' in val.columns else set()
    for _k, _payload in ledgers.items():
        _sp, _nm = _k if isinstance(_k, tuple) and len(_k) == 2 else (sport, _k)
        if sport is not None and _sp != sport:
            continue
        if str(_nm) in _known:
            continue
        _org = _payload[0] if isinstance(_payload, (tuple, list)) and len(_payload) == 3 else ''
        if _org != 'laz_registry':
            continue
        # The bar applies to the registered book too -- no origin is exempt.
        _sp_rec = _payload[1] if isinstance(_payload, (tuple, list)) and len(_payload) == 3 else {}
        if isinstance(_sp_rec, dict) and _sp_rec.get('metrics') and not laz_meets_sheet_bar(_sp_rec):
            continue
        _L = _payload[2] if isinstance(_payload, (tuple, list)) and len(_payload) == 3 else None
        if _L is None or not len(_L):
            continue
        _extra_rows.append({'name': _nm, 'sport': _sp, 'tier': 'TIER 2',
                            'n_bets': len(_L), 'origin': 'laz_registry'})
    if _extra_rows:
        val = pd.concat([val, pd.DataFrame(_extra_rows)], ignore_index=True)
        if verbose:
            print(f'[book]   {sport}: +{len(_extra_rows)} REGISTERED ledger(s) added to the '
                  f'sheet queue (not present in the tiering table)')

    for _, row in val.iterrows():
        key = (row['sport'], row['name'])
        if key not in ledgers: continue
        payload = ledgers[key]
        origin, spec, L = payload if isinstance(payload, (tuple, list)) and len(payload) == 3 \
                          else ('registry', {}, payload)
        if L is None or not len(L): continue
        # Registry ledgers arrive thin. Upgrade them so the pipeline sheet matches the manual one.
        _below = None
        if 'why_this_bet' not in L.columns:
            try:
                # Pass the STRATEGY name. row['origin'] is the container ('discovered',
                # 'laz_registry'), which carries no market information at all.
                L = enrich_ledger(L, sport=row.get('sport'), conditions=row.get('conditions'),
                                  family=row.get('origin'), name=row.get('name'))
            except Exception as _ee:
                # v65_v13: never silent — a thin sheet is a contract breach, and the old
                # `except: pass` here was exactly the silent degradation this project bans
                _below = f'enrich_ledger failed: {type(_ee).__name__}: {str(_ee)[:90]}'
        _missing_contract = [c for c in LEDGER_CONTRACT_ALWAYS if c not in L.columns]
        if _below or _missing_contract:
            print(f'[ledger][WARN] {row.get("sport")}/{row.get("name")}: ONE-TO-ONE LEDGER BELOW '
                  f'CONTRACT ({_below or ""}{" missing " + str(_missing_contract) if _missing_contract else ""}) '
                  f'— sheet stamped red; the LEDGER_CONTRACT audit check will FAIL', flush=True)
        t1 = str(row.get('tier','')).startswith('TIER 1')
        sn = (('HW_' if t1 else 'S_') + str(row['name'])[:26])[:31]
        if sn in wb.sheetnames: sn = (sn[:28] + str(made))[:31]
        ws = wb.create_sheet(sn)
        L = L.loc[:, [c for c in L.columns if str(c) not in ('None','nan','')]]
        cols = list(L.columns); ncol = len(cols) + 2
        ed = row['oos_wr'] - 100.0/row['oos_odds'] if np.isfinite(row.get('oos_odds', np.nan)) else np.nan
        r = _bk_title(ws, str(row['name']),
            f"{row['sport']} · {origin} · OOS {_laz_i(row.get('oos_n'))} bets @ {_laz_f(row.get('oos_odds'))} · "
            f"{row['oos_wr']:.1f}% · edge {ed:+.1f} pts over break-even · "
            f"ROI {row['oos_roi']:+.1f}% · CI floor {row['oos_ci']:+.1f}%", ncol)
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=ncol)
        c = ws.cell(r, 1, ('★  TIER 1 — OMEGA  ·  validated in all five segments, both time directions'
                           if t1 else
                           '◆  TIER 2 — CHALLENGE  ·  validated IS/OOS at 50%+ strike and +5 edge'))
        c.font = Font(bold=True, size=12, color='FFFFFF')
        c.fill = PatternFill('solid', fgColor=BK_PURPLE if t1 else BK_AMBER)
        ws.row_dimensions[r].height = 20; r += 1
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=ncol)
        c = ws.cell(r, 1, 'SEGMENT EVIDENCE — every window this was measured in')
        c.font = Font(bold=True, size=10, color='FFFFFF')
        c.fill = PatternFill('solid', fgColor=BK_DARK); r += 1
        for j, h in enumerate(['Segment','Bets','Odds','Win %','Edge vs break-even','ROI %',
                               'CI floor %','Max DD'], 1):
            cc = ws.cell(r, j, h); cc.font = Font(bold=True, size=9, color='FFFFFF')
            cc.fill = PatternFill('solid', fgColor=BK_BLUE); cc.border = BK_BOX
            cc.alignment = Alignment(horizontal='center', wrap_text=True)
        r += 1
        for sfx, lab in zip(seg, segl):
            try:
                e = row[f'{sfx}_wr'] - 100.0/row[f'{sfx}_odds']
                vals = [lab, int(row[f'{sfx}_n']), round(float(row[f'{sfx}_odds']), 2),
                        round(float(row[f'{sfx}_wr']), 1), round(float(e), 1),
                        round(float(row[f'{sfx}_roi']), 1), round(float(row[f'{sfx}_ci']), 1),
                        round(float(row.get(f'{sfx}_maxdd', np.nan)), 1)]
            except Exception:
                continue
            for j, v_ in enumerate(vals, 1):
                cc = ws.cell(r, j, v_); cc.border = BK_BOX
                cc.font = Font(size=9, bold=(j == 1))
            r += 1
        r += 1
        conds = row.get('conditions')
        conds = list(conds) if isinstance(conds, (list, tuple, np.ndarray)) else []
        for i, cond in enumerate(conds, 1):
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=2)
            c = ws.cell(r, 1, f'CONDITION {i}'); c.font = Font(bold=True, size=9, color='FFFFFF')
            c.fill = PatternFill('solid', fgColor=BK_DARK)
            c.alignment = Alignment(horizontal='center')
            ws.merge_cells(start_row=r, start_column=3, end_row=r, end_column=ncol)
            c = ws.cell(r, 3, str(cond)); c.font = Font(size=10)
            c.alignment = Alignment(wrap_text=True, vertical='center')
            c.fill = PatternFill('solid', fgColor=BK_GREY if i % 2 else 'FFFFFF')
            ws.row_dimensions[r].height = 17; r += 1
        # v65_v13 (owner directive): MIN ODDS on EVERY one-to-one sheet — the lowest price this
        # strategy actually took, alongside its entry floor. Part of the permanent ledger contract;
        # the LEDGER_CONTRACT audit check verifies the row is present on shipped sheets.
        _ocol = next((c_ for c_ in ('odds_taken', 'odds', 'odds_backed') if c_ in L.columns), None)
        if _ocol is not None:
            _ov = pd.to_numeric(L[_ocol], errors='coerce').dropna()
        else:
            _ov = pd.Series(dtype='float64')
        _floor = None
        _floor_src = None
        for _cd in conds:
            _p = str(_cd).split()
            if len(_p) >= 3 and _p[1] in ('>=', '>') and _p[0] in (
                    '_o', 'odds', 'own_odds', 'entry_odds', 'home_odds', 'away_odds',
                    'dog_ml', 'leader_odds_rt', 'loser_odds', 'draw_odds'):
                try:
                    _v = float(_p[2])
                    if _floor is None or _v > _floor: _floor, _floor_src = _v, str(_cd)
                except Exception: pass
        if _floor is None and isinstance(spec, dict):
            for _k in ('min_odds', 'odds_floor', 'thr_odds'):
                if _k in spec:
                    try: _floor, _floor_src = float(spec[_k]), f'spec.{_k}'
                    except Exception: pass
                    break
        _mo_txt = (f'Lowest price taken in this ledger: {_ov.min():.2f} · mean {_ov.mean():.2f} · '
                   f'highest {_ov.max():.2f} (over {len(_ov)} bets).' if len(_ov) else
                   'No odds column in this ledger — BELOW CONTRACT, regenerate.')
        # v65_v15: the global 1.65 floor is part of every strategy's effective entry floor
        if GLOBAL_MIN_ODDS:
            if _floor is None or GLOBAL_MIN_ODDS > _floor:
                _floor, _floor_src = float(GLOBAL_MIN_ODDS), 'GLOBAL_MIN_ODDS — owner directive'
        _mo_txt += (f'  Entry floor: {_floor:.2f} (from {_floor_src}).' if _floor is not None
                    else '  Entry floor: none stated in conditions — the market band itself is the floor.')
        for lab, txt in [
            ('ENTRY','Place at the FIRST tick where every condition holds. One bet per match.'),
            ('STAKE','Flat 1 unit.'),
            ('MIN ODDS', _mo_txt),
            # SETTLES: read it from the LEDGER, which already carries the resolved market
            # per row via _laz_market_of. Hardcoding "the final match result" here told the
            # reader a TOTALS strategy was a moneyline position -- FrontierUnder_1.80 shows
            # "Backed faLcOn at 2.01 ... WIN" on a match faLcOn LOST, because the bet was
            # the UNDER and the header claimed otherwise. Two writers were corrected; this
            # header block was the third and it is the one the reader sees FIRST.
            ('SETTLES', _laz_settles_text(locals().get('led', locals().get('L')))),
            ('RAW SPEC', json.dumps({k: v_ for k, v_ in (spec or {}).items()
                                     if k not in ('name','why','legacy')},
                                    sort_keys=True, default=str)[:400])]:
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=2)
            c = ws.cell(r, 1, lab); c.font = Font(bold=True, size=9, color='FFFFFF')
            c.fill = PatternFill('solid', fgColor=BK_BLUE)
            c.alignment = Alignment(horizontal='center')
            ws.merge_cells(start_row=r, start_column=3, end_row=r, end_column=ncol)
            c = ws.cell(r, 3, txt); c.font = Font(size=9, italic=(lab == 'RAW SPEC'))
            c.alignment = Alignment(wrap_text=True, vertical='center')
            ws.row_dimensions[r].height = 20; r += 1
        r += 1
        if _below or _missing_contract:
            ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=ncol)
            c = ws.cell(r, 1, '⚠ LEDGER BELOW CONTRACT — '
                        + (_below or f'missing {_missing_contract}')
                        + ' — regenerate this sheet. The explanatory ledger (backing, market, '
                          'entry prices, condition values, outcome) is PERMANENT by owner directive.')
            c.font = Font(bold=True, size=10, color='FFFFFF')
            c.fill = PatternFill('solid', fgColor='C0392B')
            c.alignment = Alignment(wrap_text=True, vertical='center')
            ws.row_dimensions[r].height = 30; r += 1
        ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=ncol)
        c = ws.cell(r, 1, f'EVERY BET ({len(L)} in the out-of-sample half)')
        c.font = Font(bold=True, size=11, color='FFFFFF')
        c.fill = PatternFill('solid', fgColor=BK_DARK); r += 1
        _NICE = {'phase':'Phase (feed value)','odds_taken':'Odds Taken',
                 'match_name':'Match','why_this_bet':'WHY THIS BET WAS PLACED','implied_%':'Implied %',
                 'score_at_bet':'Score at Bet','margin_backed_at_bet':'Lead (backed) at Bet',
                 'odds_move':'Odds Move','final_odds_backed':'FINAL ODDS (backed)',
                 'match_progress':'Match Progress','minute_at_bet':'Minute',
                 'final_score':'FINAL SCORE','final_odds_backed':'FINAL ODDS (backed)',
                 'final_odds_opponent':'Final Odds (opp)','odds_move':'Odds Move (final-taken)',
                 'hp_player_name':'Home Player',
                 'ap_player_name':'Away Player','betsson_home_player_elo':'Home ELO',
                 'betsson_away_player_elo':'Away ELO','hp_total_player_wr':'Home Player WR',
                 'ap_total_player_wr':'Away Player WR','gametype':'Game Type',
                 'wins_if':'WINS IF','score_at_bet':'Score at Bet','final_result':'Final Result',
                 'margin_backed_at_bet':'Lead (backed) at Bet','settles_on':'Settles On',
                 'odds_home_at_bet':'Home Odds @Bet','odds_draw_at_bet':'Draw Odds @Bet',
                 'odds_away_at_bet':'Away Odds @Bet','odds_opponent':'Opp Odds',
                 'opponent_odds':'Opp Odds','implied_%':'Implied %',
                 'margin_backed':'Lead (backed side)','market':'Settles On',
                 'backing':'Backing','match_progress':'Match Progress'}
        hdr = [_NICE.get(x, ('WHY: ' + x[4:] if str(x).startswith('WHY_')
                             else 'WHY: ' + x[5:] if str(x).startswith('cond_')
                             else str(x).replace('_', ' ').title())) for x in cols] \
          + ['Running P&L','Rolling Win %']
        for j, h in enumerate(hdr, 1):
            c = ws.cell(r, j, h); c.font = Font(bold=True, size=10, color='FFFFFF')
            c.fill = PatternFill('solid', fgColor=BK_AMBER if h.startswith('Phase') else BK_BLUE)
            c.alignment = Alignment(horizontal='center', wrap_text=True, vertical='center')
            c.border = BK_BOX
        ws.row_dimensions[r].height = 30; hr = r; r += 1
        pcol = get_column_letter(cols.index('profit')+1) if 'profit' in cols else None
        ocol = get_column_letter(cols.index('outcome')+1) if 'outcome' in cols else None
        rcol = get_column_letter(len(cols)+1)
        for i, (_, q) in enumerate(L.iterrows()):
            for j, cn in enumerate(cols, 1):
                v_ = q[cn]
                if hasattr(v_, 'strftime'): v_ = v_.strftime('%Y-%m-%d %H:%M:%S')
                elif isinstance(v_, (np.floating, float)) and pd.notna(v_): v_ = round(float(v_), 3)
                elif isinstance(v_, (np.integer,)): v_ = int(v_)
                elif _laz_isna(v_): v_ = None
                else: v_ = str(v_)[:60]
                cc = ws.cell(r, j, v_); cc.border = BK_BOX; cc.font = Font(size=10)
                if cn == 'outcome':
                    cc.fill = GREENF if str(q.get('outcome')) == 'WIN' else REDF
                elif cn == 'phase':
                    cc.fill = PatternFill('solid', fgColor='FFF6E0')
                elif str(cn).startswith('cond_'):
                    cc.fill = PatternFill('solid', fgColor='EAF1FA')   # the WHY columns
                elif cn in ('backing','backed_player','backed_team','market'):
                    cc.fill = PatternFill('solid', fgColor='F2EAFA')   # WHAT is backed
            if pcol:
                ws.cell(r, len(cols)+1, f"={pcol}{r}" if i == 0 else f"={rcol}{r-1}+{pcol}{r}").border = BK_BOX
                ws.cell(r, len(cols)+1).number_format = '0.00'
            if ocol:
                ws.cell(r, len(cols)+2,
                        f'=IFERROR(COUNTIF(${ocol}${hr+1}:{ocol}{r},"WIN")/({r}-{hr}),0)').border = BK_BOX
                ws.cell(r, len(cols)+2).number_format = '0.0%'
            r += 1
        for j, cn in enumerate(cols, 1):
            if cn == 'why_this_bet': w = 105
            elif cn == 'wins_if': w = 42
            elif cn == 'match_name': w = 34
            else:
             w = 26 if cn in ('match_id','placed') else (
                24 if cn == 'phase' else (
                22 if ('team' in str(cn) or 'player' in str(cn) or cn == 'league') else 12))
            ws.column_dimensions[get_column_letter(j)].width = w
        ws.column_dimensions[get_column_letter(len(cols)+1)].width = 13
        ws.column_dimensions[get_column_letter(len(cols)+2)].width = 13
        ws.freeze_panes = f'A{hr+1}'
        ws.sheet_properties.tabColor = BK_PURPLE if t1 else BK_AMBER
        _bk_backlink(ws, ncol+2)
        made += 1
    if verbose and made:
        print(f'[seq]   one-to-one sheets written: {made}', flush=True)
    return made


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION Y — STRATEGY CENSUS AND ASSESSMENT PROOF
# ═══════════════════════════════════════════════════════════════════════════════════════
#  "Every strategy is included" is a claim that has been wrong twice in this project: 431 of 631
#  were stored but never fired, and 63 more were registered against universes that could not be
#  rebuilt. This section makes the claim checkable instead of asserted.

# What each sport's registry fire function actually SETTLES ON. The specs carry no market key —
# ab_fire_basketball settles `final_tp < total_points_handicap` and prices at total_points_under,
# so EVERY eBasketball registry strategy is a totals bet regardless of its conditions. The market
# is a property of the fire function and the sport, never of the individual spec.
SPORT_SETTLEMENT_MARKET = {
    'ebasketball': 'total_points_under',   # NOT accepted by the book -> all 30 excluded
    'basketball':  'total_points_under',   # accepted for real basketball
    'efootball':   'total_goals_handicap',
    'football':    'match_result',
    'tennis':      'match_winner',
}

def _spec_market(spec, sport=None):
    """What a spec stakes on. Falls back to the sport's settlement market, which is where the
    truth actually lives for the registry families."""
    if sport and sport in SPORT_SETTLEMENT_MARKET:
        return SPORT_SETTLEMENT_MARKET[sport]
    for k in ('market', 'bet', 'side', 'settles_on', 'outcome'):
        v_ = (spec or {}).get(k)
        if v_: return str(v_)
    txt = ' '.join(f'{k}={v_}' for k, v_ in (spec or {}).items()
                   if k not in ('name', 'why', 'legacy'))
    for probe in ('total_points_under', 'total_points_over', 'total_points_handicap',
                  'point_spread_handicap', 'under', 'over', 'handicap', 'spread'):
        if probe in txt.lower(): return probe
    return 'sport default'

def excluded_for_market(sport, spec):
    """Uses the SPORT's settlement market, since registry specs do not declare one."""
    """True when this sport's book will not accept a stake on what the spec settles against.

    eBasketball only: handicap, spread and totals are displayed but rejected, so a strategy
    settling on them is an observation rather than a position. The handicap VALUE stays available
    as a condition — this concerns staking, nothing else."""
    return not market_is_tradeable(sport, _spec_market(spec, sport))



def _lds_spec_strategies(sport):
    """Every strategy whose trigger is a JSON spec rather than a condition list.

    These are invisible to canonical_records(), which keys on conditions. In
    eFootball they are the 27 Wall/TGU specs and the 28 loser/draw specs — 55 of
    the 136 the production registry runs. Harvested here so the manifest covers
    all of them instead of silently covering 81 and reporting success.
    """
    out = []
    reg = (V46_REGISTRY or {}).get(sport) or {}
    for key in ('specs', 'extra', 'recon'):
        for spec in (reg.get(key) or []):
            if not isinstance(spec, dict):
                continue
            nm = spec.get('name')
            if not nm:
                continue
            body = {k: v for k, v in spec.items() if k != 'name'}
            if not body:
                continue
            out.append(dict(name=nm, spec=body, family=f'spec_{key}',
                            container=f'V46_REGISTRY[{sport!r}][{key!r}]'))
    return out

class _LazSkipMigration(Exception):
    """Not an error: the migration step was deliberately skipped."""


def write_deployment_contract(wb, sport='efootball', migration_path='rt_columns_migration.sql',
                              tiers=None, manifest_path=None, verbose=True):
    """Adds the deployment-contract sheets and emits the rt migration SQL.

    This is the half of the book that was missing. The book reported metrics for
    strategies whose trigger definition existed only inside this file's Python
    literals, so a strategy could look excellent and still be undeployable.

    Additive: it creates Deployment_Spec and Feature_Provenance and touches no
    existing sheet. Never raises — a contract failure must not lose the book.
    """
    if _LDS is None:
        if verbose:
            print('[lds] skipped — lazarus_deployment_spec not importable')
        return False
    ok = True
    recs = _lds_records(sport)
    # ── v68 NOTE — Deployment_Spec does NOT yet cover the 427 registered strategies ──
    # _lds_records() reads V46_REGISTRY only. An attempt to append laz_registry() here was
    # reverted: the function returns a list for some sports and a dict for others, and the
    # naive append produced sheets with 3 rows and zero registered entries -- worse than
    # leaving it alone. The correct fix is inside _lds_records(), not bolted on after it.
    #
    # WHAT THIS MEANS: the book's Deployment_Spec sheet describes the legacy V46 set. The
    # 427 registered strategies carry their full contract -- conditions, min_odds, settles,
    # entry_window, attachment requirement -- in their own dicts, reachable via
    # laz_registry(), and every one of them passes laz_verify(). They are NOT missing a
    # contract; they are missing a ROW IN ONE SHEET.
    if not recs:
        print(f'[lds] no canonical records for {sport!r} — contract sheets skipped')
        return False
    try:
        _LDS.write_deployment_spec(wb, recs)
        _LDS.write_feature_provenance(wb)
        if verbose:
            print(f'[lds] Deployment_Spec + Feature_Provenance written ({len(recs)} strategies)')
    except Exception as e:
        ok = False
        print(f'[lds] contract sheets FAILED: {type(e).__name__}: {e}')
    try:
        _LDS.naming_report(recs)
    except Exception as e:
        print(f'[lds] naming_report failed: {e}')
    # THE HANDOFF. This one file is what travels to the production box. It needs
    # `tiers` because whether a strategy meets the deployment bar depends on the
    # IS/OOS split, which canonical_records() does not carry.
    try:
        _LDS.emit_strategy_manifest(sport, recs, tiers=tiers,
                                    spec_strategies=_lds_spec_strategies(sport),
                                    path=manifest_path or _LDS.MANIFEST_DEFAULT_NAME)
    except Exception as e:
        print(f'[lds] manifest FAILED: {type(e).__name__}: {e}')
    # The migration is registry-driven on purpose: the registry is the only source
    # that includes spec-only strategies (conditions=[]), and omitting those is
    # what left 27 Wall/TGU flag columns uncreated.
    try:
        # ── OFF BY DEFAULT ────────────────────────────────────────────────────────────
        # This emits ALTER TABLE statements for a production Postgres schema. It runs AFTER
        # the book is finished and written, so it adds nothing to the research output -- and
        # on a machine with no production registry it sat scanning for one long enough that
        # a completed run looked like a hung one. The owner watched a finished tennis run
        # for minutes waiting on a step whose output they had not asked for.
        # Set LAZ_EMIT_MIGRATION=1 when you actually want the SQL.
        if not os.environ.get('LAZ_EMIT_MIGRATION'):
            if verbose:
                print('[lds] rt migration SQL skipped '
                      '(set LAZ_EMIT_MIGRATION=1 if you want it)')
            raise _LazSkipMigration()
        _LDS.emit_migration_sql([], path=migration_path)
        if verbose:
            print(f'[lds] rt migration SQL -> {migration_path}')
    except _LazSkipMigration:
        pass
    except FileNotFoundError as e:
        print(f'[lds] migration NOT emitted: {e}')
        print('[lds]   set $LAZARUS_REGISTRY_PATH to the production '
              'Lazarus_EFB_Strategies.py and re-run to get it.')
    except Exception as e:
        ok = False
        print(f'[lds] migration FAILED: {type(e).__name__}: {e}')
    return ok



def build_core_text_sheets(wb, T, triggers=None, failures=None, verbose=True):
    """Caveats_and_Sizing and Trigger_Conditions.

    Both were defined inside build_master_book(), which the sequential pipeline never calls — so a
    sequential run shipped without them. Extracted here so BOTH paths produce a complete book."""
    failures = failures if failures is not None else []

    def _caveats():
        ws = wb.create_sheet('Caveats_and_Sizing')
        r = _bk_title(ws,'CAVEATS — READ BEFORE STAKING ANYTHING',
            'The limits of what this book proves, stated plainly.',3)
        r = _bk_table(ws,r,['Caveat','Detail'],[
          ('Nothing is forward-tested','Every figure is in-sample or held-out historical. No strategy '
           'here has been traded live, and the strategy space was searched on this same data.'),
          ('Placeability is not fill','It confirms the trigger persisted long enough to strike a bet. '
           'Whether your stake is matched at that price, at size, is unverified everywhere. For the '
           'misprice family this is the single largest open risk — it depends on catching a price '
           'BEFORE the market re-rates a side that just took the lead.'),
          ('Correlated strategies are one position','Within a sport these overlap heavily; eBasketball '
           'families correlate at 0.88. Size by cluster and treat each sport as ONE risk budget.'),
          ('Multiple comparisons','Discovered strategies came from 60,000-150,000 evaluations per '
           'sport. Walk-forward consistency and a mechanism recurring across sports are the defence, '
           'not the p-value.'),
          ('Use the in-sample rate for planning','Treat out-of-sample as the optimistic end of the '
           'range, not the expectation.'),
          ('Drawdown decides size, not ROI','A 22-unit drawdown at a 32% strike is a different asset '
           'from a 4.4-unit drawdown at 80%, whatever their returns look like.'),
          ('eBasketball handicap and totals cannot be staked','All 30 of its registry strategies '
           'settle on total_points_under. They remain here as evidence, marked unstakeable. Handicap '
           'VALUES are still valid as conditions.'),
        ],[30,124],wrapcols=(2,))
        ws.sheet_properties.tabColor = BK_RED; _bk_backlink(ws,4)

    def _triggers():
        if triggers is None or not len(triggers): raise ValueError('no trigger data')
        ws = wb.create_sheet('Trigger_Conditions')
        r = _bk_title(ws,'TRIGGER CONDITIONS — WHAT MUST BE TRUE FOR EACH STRATEGY TO FIRE',
            'Conditions are joined by AND, never OR. The bet is struck at the first tick where every '
            'one holds, one bet per match.',6)
        M = triggers
        if 'tier' not in M.columns and 'name' in M.columns and 'tier' in T.columns:
            M = M.merge(T[['sport','name','tier']], on=['sport','name'], how='left')
        val = M[M.get('tier','').ne('NOT VALIDATED')] if 'tier' in M.columns else M
        for sp in ['ebasketball','basketball','efootball','tennis','football']:
            d = val[val.sport == sp] if 'sport' in val.columns else val.iloc[0:0]
            if not len(d): continue
            r = _bk_section(ws,r,f'{SPORT_LABEL.get(sp,sp)} — {len(d)}',6)
            rows = [(x.get('name'), x.get('tier',''), x.get('market',''),
                     '\n'.join(f'• {c}' for c in (x['conditions']
                              if isinstance(x.get('conditions'),(list,np.ndarray)) else [])),
                     str(x.get('raw',''))[:220]) for _, x in d.iterrows()]
            r = _bk_table(ws,r,['Strategy','Tier','Backs','All conditions must hold','Raw spec'],
                          rows,[30,20,24,74,56],wrapcols=(4,5))
        ws.sheet_properties.tabColor = BK_DARK; _bk_backlink(ws,7)

    for nm, fn in [('Caveats_and_Sizing',_caveats),('Trigger_Conditions',_triggers)]:
        _bk_guard(wb, nm, fn, failures, verbose)
    return failures


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION Z — PREFLIGHT
# ═══════════════════════════════════════════════════════════════════════════════════════
#  A full run on 1-11 GB feeds takes hours. Everything that can be checked in seconds should be
#  checked BEFORE that starts, not discovered at hour three.

def preflight(upload_dir='.', out_book=None, carry_forward=None,
              sports=None, verbose=True):
    """Runs every cheap check before a long job. Returns (ok, report).

    Checks, in the order they would bite: files found and content-verified; prep and fire functions
    resolve; frames writable; output path writable; carry_forward readable; disk headroom; which
    ingestion path each sport will take; checkpoint state; and that the guards actually fire."""
    sports = sports or list(SPORT_WIRING)
    rep, fatal, warn = {}, [], []

    # 1. inputs
    for sport in sports:
        try:
            files = resolve_input_files(sport, [upload_dir], verbose=False)
        except Exception as e:
            files = []; warn.append(f'{sport}: resolve failed {type(e).__name__}')
        gb = sum(os.path.getsize(f) for f in files if os.path.exists(f))/1024**3 if files else 0.0
        ok_v, det, why = (verify_input_sport(sport, files, verbose=False) if files
                          else (False, None, 'no files found'))
        _ov = SPORT_INGEST_OVERRIDE.get(sport)
        path = ('single-pass (forced)' if _ov == 'single' else
                'chunked (forced)' if _ov == 'chunked' else
                'chunked' if gb >= INGEST_LARGE_THRESHOLD_GB else 'single-pass')
        rep[sport] = dict(files=len(files), gb=round(gb, 2), verified=ok_v, reason=why,
                          ingest_path=path if files else '-')
        if files and not ok_v: fatal.append(f'{sport}: {why}')
        if not files: warn.append(f'{sport}: no files, will use existing frame if present')
        # 2. wiring resolves
        cfg = SPORT_WIRING[sport]
        if not hasattr(sys.modules[__name__], cfg['prep']): fatal.append(f'{sport}: prep missing')
        if not hasattr(sys.modules[__name__], cfg['fire']): fatal.append(f'{sport}: fire missing')
        d = os.path.dirname(cfg['frame']) or '.'
        if not os.access(d, os.W_OK): fatal.append(f'{sport}: frame dir not writable ({d})')

    # 3. output paths
    if out_book:
        d = os.path.dirname(out_book) or '.'
        os.makedirs(d, exist_ok=True)
        if not os.access(d, os.W_OK): fatal.append(f'out_book dir not writable: {d}')
    if carry_forward and not os.path.exists(carry_forward):
        warn.append(f'carry_forward not found: {carry_forward} — historical sheets will be LOST')
    if not carry_forward:
        warn.append('no carry_forward — a fresh book will NOT contain historical sheets')

    # 4. disk headroom: prepped frames run roughly 15-25% of raw size
    try:
        import shutil as _sh
        free = _sh.disk_usage(os.path.dirname(V46_FRAMES[sports[0]]) or '.').free/1024**3
        need = sum(r['gb'] for r in rep.values())*0.30 + 1.0
        if free < need: fatal.append(f'disk: {free:.1f} GB free, ~{need:.1f} GB needed')
        rep['_disk'] = dict(free_gb=round(free,1), needed_gb=round(need,1))
    except Exception: pass

    # 5. guards actually fire
    g = []
    for col, exp in (('final_home','block'),('peak_over_entry','block'),('id','block'),
                     ('ts','block'),('total_points_under','allow'),('loser_runmax','allow')):
        try: assert_no_leakage([col]); got='allow'
        except ValueError: got='block'
        g.append(got == exp)
    if not all(g): fatal.append('leakage guard misconfigured')
    # The market guard is a SETTING, not an invariant. It was hard-coded as fatal, so re-enabling
    # eBasketball handicaps made _laz_legacy_preflight refuse to start the run at all.
    if not EBASKETBALL_HANDICAP_TRADEABLE and market_is_tradeable('ebasketball',
                                                                  'total_points_under'):
        fatal.append('market guard misconfigured: exclusion requested but not applied')
    if EBASKETBALL_HANDICAP_TRADEABLE:
        warn.append('eBasketball handicap/totals ENABLED — these settle on total_points_under; '
                    'verify the book accepts the stake before sizing')
    lab = three_outcome_labels(['Home','Away','Draw'])
    if not (lab['home'].sum()==1 and lab['away'].sum()==1 and lab['draw'].sum()==1):
        fatal.append('three-outcome labelling wrong')

    # 6. checkpoints
    ck = len(glob.glob(os.path.join(CHECKPOINT_DIR, '*.pkl'))) if os.path.isdir(CHECKPOINT_DIR) else 0
    rep['_checkpoints'] = ck

    ok = not fatal
    if verbose:
        print('═══ PREFLIGHT ═══')
        print(f"  {'sport':12} {'files':>6} {'size GB':>8} {'verified':>9}  ingest path")
        for sport in sports:
            r = rep[sport]
            print(f"  {sport:12} {r['files']:>6} {r['gb']:>8.2f} {str(r['verified']):>9}  "
                  f"{r['ingest_path']}" + ('' if r['verified'] or not r['files'] else f"  <- {r['reason']}"))
        if '_disk' in rep:
            print(f"\n  disk: {rep['_disk']['free_gb']} GB free, ~{rep['_disk']['needed_gb']} GB needed")
        # PURGE BEFORE COUNTING. Reporting 30 checkpoints as if they were usable, when 28
        # of them are keyed to older builds and will never be read, misleads the reader in
        # exactly the place they decide whether to commit to a five-hour run.
        try:
            laz_purge_stale_checkpoints(verbose=True)
            ck = len([p for p in os.listdir(CHECKPOINT_DIR) if p.endswith('.pkl')]) \
                if os.path.isdir(CHECKPOINT_DIR) else 0
        except Exception:
            pass
        print(f"  checkpoints on disk: {ck} (usable by THIS build; older keys purged)")
        print(f"  guards: leakage {sum(g)}/6 · market OK · labels OK")
        for w in warn: print(f'  WARN  {w}')
        for f in fatal: print(f'  FATAL {f}')
        print(f"\n  -> {'CLEARED FOR RUN' if ok else 'DO NOT RUN — fix the FATAL items above'}")
    return ok, rep


# ═══════════════════════════════════════════════════════════════════════════════════════
#  ENTRY POINT — must be the LAST thing in this file
# ═══════════════════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION AA — FILE-AWARE BATCHING
# ═══════════════════════════════════════════════════════════════════════════════════════
#  "Ingest one file, process it, dispose, next file" is the intuitive design and it is WRONG here.
#  Rolling features are computed ACROSS matches — rest since last game, form over the last 5/10/20,
#  head-to-head. Prepping a file in isolation resets all of that at every boundary. This is not
#  theoretical: it is the v50 defect, measured at min_since_goal 27.0802 per-file against 27.0866
#  single-pass, and it silently corrupts the features most strategies depend on.
#
#  What IS safe, and delivers the same memory profile: batch on MATCH boundaries in time order,
#  carry an overlap of preceding matches to warm the history, and — the part added here — read only
#  the FILES those matches actually live in.
#
#  A match→file index is built once from two columns. Each batch then touches perhaps 2-3 files
#  instead of all 50, so an 11 GB feed is processed a few hundred megabytes at a time with history
#  fully intact.

def build_match_file_index(files, verbose=True):
    """Maps every match_id to the file(s) containing it, and records each match's first timestamp.

    Reads only match_id and timestamp — two columns, cheap even on an 11 GB export, and the basis
    for both time ordering and per-batch file selection."""
    rows = []
    for f in files:
        try:
            head = pd.read_csv(f, nrows=0).columns
            cols = [c for c in ('match_id', 'timestamp') if c in head]
            if len(cols) < 2:
                if verbose: print(f'[index]   ! {os.path.basename(f)} lacks match_id/timestamp')
                continue
            d = pd.read_csv(f, usecols=cols)
            d['_file'] = f
            rows.append(d)
        except Exception as e:
            if verbose: print(f'[index]   ! {os.path.basename(f)}: {type(e).__name__}: {e}')
    if not rows: return None, []
    D = pd.concat(rows, ignore_index=True); del rows; gc.collect()
    D['ts'] = pd.to_datetime(D['timestamp'], errors='coerce', format='mixed')
    first = D.groupby('match_id', sort=False)['ts'].min()
    m2f = D.groupby('match_id', sort=False)['_file'].apply(lambda s: tuple(sorted(set(s))))
    order = list(first.sort_values().index)
    idx = m2f.to_dict()
    del D; gc.collect()
    if verbose:
        spread = np.mean([len(v_) for v_ in idx.values()]) if idx else 0
        print(f'[index] {len(order):,} matches across {len(files)} file(s) · '
              f'mean {spread:.2f} file(s) per match')
    return idx, order

def ingest_sport_filewise(sport, files, out_path=None, batch_matches=None, overlap=None,
                          verbose=True):
    """Chunked prep that reads ONLY the files each batch needs.

    Memory profile of per-file processing; history continuity of a single pass. Each batch stages
    just the files containing its own matches plus the warm-up window, preps them, keeps only the
    batch's own matches, appends to the parquet, and disposes."""
    import pyarrow as pa, pyarrow.parquet as pq_, shutil as _sh
    batch_matches = batch_matches if batch_matches is not None else PREP_BATCH_MATCHES
    overlap       = overlap if overlap is not None else \
                    SPORT_OVERLAP_OVERRIDE.get(sport, PREP_OVERLAP_MATCHES)
    prep = globals()[AB_PREP_FOR_SPORT[sport]]
    kw   = PREP_KWARGS_FOR_SPORT.get(sport, {})
    out_path = out_path or V46_FRAMES[sport]
    idx, order = build_match_file_index(files, verbose=verbose)
    if not order:
        if verbose: print(f'[prep] {sport}: no index — falling back to whole-feed prep')
        return ingest_sport_safe(sport, files, out_path=out_path, verbose=verbose)
    nb = max(1, int(np.ceil(len(order) / batch_matches)))
    if verbose:
        print(f'[prep] {sport}: {len(order):,} matches -> {nb} batch(es) of {batch_matches:,} '
              f'(+{overlap:,} warm-up), reading only the files each batch needs', flush=True)
    writer, total, t0, touched, _schema = None, 0, time.time(), [], None
    stage_root = os.path.join('/tmp/_lz_stage', sport)
    # ONE pass over the source, split into per-batch files. Every batch then reads only its slice
    # instead of the whole export, which is where the 149 GB of repeat I/O was going.
    batch_files = None
    if SPLIT_SOURCE_FOR_BATCHES:
        try:
            batch_files, nb = split_source_by_batches(files, order, batch_matches, overlap,
                                                      stage_root, verbose=verbose)
        except Exception as e:
            if verbose: print(f'[split] failed ({type(e).__name__}) — falling back to full reads')
            batch_files = None
    try:
        for b in range(nb):
            lo = b * batch_matches
            keep = order[lo: lo + batch_matches]
            warm = order[max(0, lo - overlap): lo]
            want = set(keep) | set(warm)
            need = sorted({f for m in want for f in idx.get(m, ())})
            touched.append(len(need))
            if batch_files is not None and b < len(batch_files) and os.path.exists(batch_files[b]):
                pattern = batch_files[b]          # this batch's slice only
            else:
                stage = os.path.join(stage_root, f'b{b}')
                if os.path.isdir(stage): _sh.rmtree(stage)
                os.makedirs(stage, exist_ok=True)
                for f in need:
                    link = os.path.join(stage, os.path.basename(f))
                    try: os.symlink(os.path.abspath(f), link)
                    except Exception: _sh.copy(f, link)
                pattern = os.path.join(stage, '*.csv*')
            df = prep(pattern, **kw)
            if 'match_id' in df.columns:
                df = df[df['match_id'].isin(want)]
                df = df[df['match_id'].isin(set(keep))]   # discard the warm-up rows
            df = ensure_phase_column(df, pattern, sport, verbose=False)
            df = ensure_identity_columns(df, pattern, sport, verbose=verbose)
            _optimise_dtypes(df)
            # Parquet writes the DICTIONARY INDEX WIDTH into the schema, and it varies with how
            # many distinct values a batch happens to contain — league was int8 in batch 1 and
            # int16 in batch 2, so ParquetWriter rejected the second table outright. Casting
            # categoricals back to plain strings before writing makes every batch schema identical.
            # Only OBJECT-derived categoricals go back to string. Casting a NUMERIC column that
            # _optimise_dtypes had categorised produced 'Invalid comparison between dtype=category
            # and float' the moment a fire function touched it.
            for _c in df.columns:
                if str(df[_c].dtype) == 'category':
                    try:
                        _cats = df[_c].cat.categories
                        if _cats.dtype.kind in 'ifubMm':
                            df[_c] = df[_c].astype(_cats.dtype)     # numeric -> back to numeric
                        else:
                            df[_c] = df[_c].astype(str)             # text -> plain string
                    except Exception:
                        df[_c] = df[_c].astype(str)
            tbl = pa.Table.from_pandas(df, preserve_index=False)
            if writer is None:
                # PIN the first batch's schema and cast every later batch to it. Per-batch dtype
                # drift — dictionary index width, large_string vs string — has now broken this
                # writer twice in different ways. Casting removes the entire class of failure.
                _schema = tbl.schema
                writer = pq_.ParquetWriter(out_path, _schema, compression='zstd')
            elif tbl.schema != _schema:
                try:
                    tbl = tbl.cast(_schema)
                except Exception:
                    # last resort: rebuild the frame in the pinned column order and types
                    for _f in _schema:
                        if _f.name in df.columns:
                            try: df[_f.name] = df[_f.name].astype(_f.type.to_pandas_dtype())
                            except Exception: pass
                    tbl = pa.Table.from_pandas(df[[f.name for f in _schema]],
                                               preserve_index=False).cast(_schema)
            writer.write_table(tbl)
            total += len(df)
            m = memory_report()
            if verbose:
                print(f'[prep]   batch {b+1}/{nb}: {len(need)} file(s) read · {len(df):,} rows '
                      f'(total {total:,}) · RSS {m["rss_gb"]} GB', flush=True)
            del df, tbl; gc.collect()
            _sh.rmtree(stage, ignore_errors=True)          # dispose immediately
    finally:
        if writer is not None: writer.close()
        _sh.rmtree(stage_root, ignore_errors=True)
    if verbose:
        print(f'[prep] {sport}: {total:,} rows -> {out_path} in {time.time()-t0:.0f}s · '
              f'peak {memory_report()["peak_gb"]} GB · '
              f'mean {np.mean(touched):.1f} of {len(files)} file(s) read per batch')
    return out_path, total


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION AB — ASSESSMENT OPTIMISATION
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Profiling the assessment path on 396k rows: the fire function is 76% of the time and metrics
#  24%. But the cost that actually scales is not either of those — it is SLICING. Building five
#  segments from a 2.76M-row x 49-column frame copies the whole frame five times, and most of
#  those columns are never read by any fire function for that sport.
#
#  Projecting to only the columns the sport's fire functions can touch cuts both the copy cost and
#  the resident memory of every slice, with no change to what is computed.

# Opt-in. See the note in assemble_book_inputs: enabling this without per-sport validation
# silently zeroed basketball's 46 specs.
# (declared early) ASSESS_PROJECT_COLUMNS

_FIRE_COLS_CACHE = {}

def fire_columns_for(sport, frame_columns, verbose=False):
    """Columns a sport's fire functions can possibly read, intersected with the frame.

    Derived by inspecting the source of the registry's fire/wrap/recon functions plus every spec's
    keys, then widened with the columns the metrics and segmentation always need. Anything not in
    that set cannot affect a result, so carrying it through five slices is pure cost."""
    key = (sport, len(frame_columns))
    if key in _FIRE_COLS_CACHE: return _FIRE_COLS_CACHE[key]
    import inspect as _i
    reg = V46_REGISTRY.get(sport) or {}
    refs = set()
    for fn in (reg.get('fire'), reg.get('wrap'), reg.get('reconfire')):
        if fn is None: continue
        try: refs |= set(re.findall(r"[\[\(]\s*['\"]([a-zA-Z_][a-zA-Z0-9_]*)['\"]", _i.getsource(fn)))
        except Exception: pass
    for key_ in ('specs', 'extra', 'recon'):
        for spec in (reg.get(key_) or []):
            refs |= {str(k) for k in spec}
            for v_ in spec.values():
                if isinstance(v_, str): refs.add(v_)
    ALWAYS = {'match_id','ts','mstart','mend','phase','league','id',
              'home_odds','away_odds','draw_odds','h_score','a_score','prog','minute',
              'final_result','final_winner','final_tg','final_tp'}
    keep = [c for c in frame_columns if c in refs or c in ALWAYS]
    if len(keep) < 6:                       # inspection failed -> keep everything rather than guess
        keep = list(frame_columns)
    _FIRE_COLS_CACHE[key] = keep
    if verbose:
        print(f'[assess] {sport}: {len(frame_columns)} cols -> {len(keep)} needed for firing')
    return keep

def project_for_assessment(df, sport, verbose=True):
    """Narrows a frame to the columns firing can use. Pure optimisation — no logic change."""
    keep = fire_columns_for(sport, list(df.columns))
    if len(keep) >= len(df.columns): return df
    before = df.memory_usage(deep=True).sum()/1024**3
    out = df[keep]
    after = out.memory_usage(deep=True).sum()/1024**3
    if verbose:
        print(f'[assess] {sport}: projected {len(df.columns)} -> {len(keep)} cols · '
              f'{before:.2f} -> {after:.2f} GB ({100*(1-after/max(before,1e-9)):.0f}% less to slice)')
    return out

def fast_bootstrap_ci(pnl, n_boot=400, pct=5, seed=7):
    # v65_v15: an empty or single-bet sample cannot be resampled — return NaN instead of the
    # IndexError that np.percentile throws on size-0 input. Empty segments are now ROUTINE under
    # the global 1.65 entry floor (a short-price strategy can have zero bets above the floor).
    pnl = np.asarray(pnl, dtype='float64')
    if pnl.size == 0 or n_boot is None or n_boot <= 0:
        return float('nan')
    """Vectorised bootstrap. One 2-D random index instead of a Python loop over resamples.

    dd_metrics computes this per spec per segment: 200 specs x 5 segments x 400 resamples is
    400,000 resample operations per run, and a loop makes each one a separate pass."""
    a = np.asarray(pnl, dtype='float64')
    n = a.size
    if n == 0: return float('nan')
    rs = np.random.default_rng(seed)
    idx = rs.integers(0, n, size=(n_boot, n))
    return float(_laz_pct(a[idx].mean(axis=1) * 100.0, pct))


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION AC — SINGLE-PASS ASSESSMENT
# ═══════════════════════════════════════════════════════════════════════════════════════
#  The assessment path fires every spec FIVE TIMES — once per segment — against five separate
#  slices of the frame. That is five copies of a 2.76M-row frame and five times the firing work.
#
#  It is also unnecessary. A bet carries the match start it was struck in, so a spec can be fired
#  ONCE against the whole frame and its bets bucketed into segments afterwards. The segments are
#  defined by match-start quantiles, which are a property of the frame, not of the firing.
#
#  Identical arithmetic, one fifth of the fire calls, one slice instead of five.

def segment_bounds(df):
    """The five evaluation windows as match-start boundaries."""
    q40 = df['mstart'].quantile(0.40); q70 = df['mstart'].quantile(0.70)
    half = df['mstart'].quantile(0.50)
    return dict(half=half, q40=q40, q70=q70)

def _bucket_bets(fr, b):
    """Assigns each bet to the segments it belongs to. A bet can be in several — IS/OOS split at
    the median, while backward/freeze/forward split at the 40th and 70th percentiles."""
    ms = fr['mstart'].values if 'mstart' in fr.columns else None
    if ms is None: return {}
    return {'is':  ms <= b['half'],
            'oos': ms >  b['half'],
            'bwd': ms <= b['q40'],
            'frz': (ms > b['q40']) & (ms <= b['q70']),
            'fwd': ms >  b['q70']}

# The all-null record used by assess_single_pass's "cannot segment" branches.
# ADDED 27/07: those two branches expanded **NIL, which was never defined, so the
# code written specifically to stop specs vanishing silently instead raised
# NameError and took the pipeline down. Keys mirror _bucket_bets() x the six
# fields the evaluated path emits, so a non-segmentable spec produces a
# same-shaped row of NaNs rather than an exception or a hole.
NIL = {f'{_k}_{_f}': np.nan
       for _k in ('is', 'oos', 'bwd', 'frz', 'fwd')
       for _f in ('n', 'wr', 'odds', 'roi', 'ci', 'maxdd')}



def _laz_assess_fire(frame, spec):
    """Fire a REGISTERED strategy for the assess stage.

    Mirrors the _laz_fire used in build_ledgers: augment is assumed already applied to the
    frame, conditions are evaluated with v67_cond_mask, the backed price is derived from
    what the strategy backs, and the first tick per match is returned. Kept as a module
    function so the assess stage and the ledger stage cannot drift apart.
    """
    conds = [c for c in (spec.get('conditions') or []) if isinstance(c, str)]
    try:
        m = v67_cond_mask(frame, conds)
    except Exception:
        return None
    if m is None:
        return None
    m = np.asarray(m)
    if not m.any():
        return None
    sub = frame[m]
    if '_o' not in sub.columns:
        try:
            _bp = _laz_backed_price_global(sub, spec)
        except Exception:
            _bp = None
        if _bp is not None:
            sub = sub.copy()
            sub['_o'] = _bp
    if '_o' in sub.columns:
        o = pd.to_numeric(sub['_o'], errors='coerce')
        lo, hi = spec.get('min_odds'), spec.get('max_odds')
        if lo is not None:
            sub = sub[o >= float(lo) - 1e-9]
        if hi is not None and len(sub):
            sub = sub[pd.to_numeric(sub['_o'], errors='coerce') <= float(hi) + 1e-9]
    if not len(sub):
        return None
    fr = sub.groupby('match_id', sort=False).nth(0).copy()
    # THE ASSESS EVALUATOR EXPECTS _won AND _pnl. Returning the raw frame gave
    # KeyError: '_won', which dropped the sport to the five-slice fallback -- slower, and
    # it hid the real cause behind a generic message. Settle here, the same way the ledger
    # stage does, so both paths agree on what a win is.
    _mk = str(spec.get('market', '') or '').lower()
    _bk = str(spec.get('backs', '') or '').lower()
    _fin = next((c for c in ('final_tg', 'final_tp') if c in fr.columns), None)
    _lin = next((c for c in ('total_goals_handicap_ffill', 'total_goals_handicap',
                             'total_points_handicap', 'open_line') if c in fr.columns), None)
    if ('under' in _mk or 'under' in _bk) and _fin and _lin:
        _won = pd.to_numeric(fr[_fin], errors='coerce') < pd.to_numeric(fr[_lin], errors='coerce')
    elif ('over' in _mk or 'over' in _bk) and _fin and _lin:
        _won = pd.to_numeric(fr[_fin], errors='coerce') > pd.to_numeric(fr[_lin], errors='coerce')
    else:
        _rc = next((c for c in ('final_result', 'final_winner', 'match_winner', 'winner')
                    if c in fr.columns), None)
        _side = None
        for _cn in ('set1_winner', 's1_winner', 'set_winner_side', 'side_lead',
                    'leading_team_rt'):
            if _cn in fr.columns:
                _side = fr[_cn].astype(str).str.strip().str.lower()
                break
        if _side is None and {'h_score', 'a_score'}.issubset(fr.columns):
            _sd = (pd.to_numeric(fr['h_score'], errors='coerce')
                   - pd.to_numeric(fr['a_score'], errors='coerce'))
            _side = pd.Series(np.where(_sd > 0, 'home', np.where(_sd < 0, 'away', '')),
                              index=fr.index)
        _won = ((fr[_rc].astype(str).str.strip().str.lower() == _side)
                if (_rc and _side is not None) else pd.Series(False, index=fr.index))
    fr['_won'] = _won.fillna(False).astype(bool)
    if '_o' in fr.columns:
        _o = pd.to_numeric(fr['_o'], errors='coerce')
        fr['_pnl'] = np.where(fr['_won'], _o - 1.0, -1.0)
        fr['_odds'] = _o
    else:
        fr['_pnl'] = np.where(fr['_won'], 0.9, -1.0)
    # EVERY ALIAS THE EVALUATOR MIGHT ASK FOR. It reads _won, _w, _pnl, _profit and _odds
    # depending on which code path it takes, and a single missing name sends the sport to
    # the five-slice fallback with a KeyError that names one column at a time -- _won, then
    # _profit, then the next. Write them all once rather than chasing them one run apiece.
    fr['_w'] = fr['_won']
    fr['_profit'] = fr['_pnl']
    if '_odds' not in fr.columns and '_o' in fr.columns:
        fr['_odds'] = pd.to_numeric(fr['_o'], errors='coerce')
    if 'placed' not in fr.columns and 'ts' in fr.columns:
        fr['placed'] = fr['ts']
    return fr


def _laz_backed_price_global(frame, spec):
    """Price of the side the strategy backs. Module-level twin of the closure in
    build_ledgers, so the assess stage resolves prices identically."""
    _b = str(spec.get('backs', '') or '').lower()
    _m = str(spec.get('market', '') or '').lower()
    # leading_ml / trailing_ml are MONEYLINE on a named side. Without this they fell to the
    # totals branch below and were priced off the under column.
    if _m.endswith('_ml') or _m in ('ml', 'moneyline'):
        _b = _b or ('lead' if 'lead' in _m else 'trail' if 'trail' in _m else '')
    _get = lambda c: (pd.to_numeric(frame[c], errors='coerce') if c in frame.columns else None)
    if 'under' in _m or 'under' in _b:
        for c in ('total_points_under', 'total_goals_under', 'u_odds'):
            v = _get(c)
            if v is not None:
                return v
    if 'over' in _m or 'over' in _b:
        for c in ('total_points_over', 'total_goals_over', 'o_odds'):
            v = _get(c)
            if v is not None:
                return v
    if 'draw' in _m:
        v = _get('draw_odds')
        if v is not None:
            return v
    _ho, _ao = _get('home_odds'), _get('away_odds')
    if _ho is None or _ao is None:
        return None
    for _cn in ('set1_winner', 's1_winner', 'set_winner_side'):
        if _cn in frame.columns:
            _sl = frame[_cn].astype(str).str.strip().str.lower()
            return pd.Series(np.where(_sl == 'home', _ho, np.where(_sl == 'away', _ao, np.nan)),
                             index=frame.index)
    _h, _a = _get('h_score'), _get('a_score')
    if _h is not None and _a is not None:
        _sd = _h - _a
        return pd.Series(np.where(_sd > 0, _ho, np.where(_sd < 0, _ao, np.nan)),
                         index=frame.index)
    return _ho


def assess_single_pass(sport, df=None, specs_groups=None, verbose=True, boot=400):
    """Fires every spec ONCE against the whole frame, then measures each segment from the result.

    Returns the same per-spec five-segment record the five-slice path produces."""
    df = df if df is not None else v46_frame(sport)
    _optimise_dtypes(df)
    df = _decat_for_firing(df)
    b = segment_bounds(df)
    reg = V46_REGISTRY[sport]
    if specs_groups is None:
        specs_groups = [('v44_AB', reg['specs'], reg['fire'])]
        if reg.get('extra'):  specs_groups.append(('v46_extra', reg['extra'], reg['wrap']))
        if reg.get('recon'):  specs_groups.append(('v46_recon', reg['recon'], reg['reconfire']))
        # ── MEASURE THE REGISTERED BOOK TOO ───────────────────────────────────────────
        # This is the ASSESS stage, and it read V46_REGISTRY alone. laz_registry() was
        # wired into build_ledgers but never into measurement, so the 16 real-basketball
        # strategies never appeared in basketball_Tiers at all -- not as ledgers, not even
        # as measured rows. Tennis and eBasketball hid the gap because their v44_AB tiering
        # validated something, giving build_ledgers a non-empty `want` to work from;
        # basketball validated nothing, so nothing downstream ever saw the 16.
        # Measured here, they land in the tier table like every other origin, which is what
        # makes them reachable from the Dashboard rather than only from the tab bar.
        try:
            _lzr = [x for x in laz_registry().get(sport, []) if x.get('enabled')]
            _known = {sp.get('name') for _o, _sl, _f in specs_groups for sp in _sl}
            _lzr = [x for x in _lzr if x.get('name') not in _known]
            if _lzr:
                # The registered features are not in the prepared frame -- anchor, wall_min,
                # cb_prog and the rest are computed by the live engines. Without this the
                # specs are measured against a frame that cannot satisfy them and every one
                # records zero bets, which looks identical to "the strategy does not fire".
                try:
                    _rw = {c.split()[0] for x in _lzr for c in x.get('conditions', [])
                           if isinstance(c, str)}
                    df = _laz_augment_frame(df, sport, needed=_rw, verbose=verbose)
                except Exception as _ae2:
                    print(f'[assess] {sport}: augment failed '
                          f'({type(_ae2).__name__}: {str(_ae2)[:60]})')
                specs_groups.append(('laz_registry', _lzr, _laz_assess_fire))
                if verbose:
                    print(f'[assess] {sport}: +{len(_lzr)} REGISTERED spec(s) added to '
                          f'measurement')
        except Exception as _re2:
            print(f'[assess] {sport}: laz_registry not measured '
                  f'({type(_re2).__name__}: {str(_re2)[:60]})')
    allspecs = [(o, sp, f) for o, sl, f in specs_groups for sp in sl]
    before = len(allspecs)
    allspecs = [(o, sp, f) for o, sp, f in allspecs if not excluded_for_market(sport, sp)]
    if verbose and len(allspecs) != before:
        print(f'[assess] {sport}: {before-len(allspecs)} spec(s) excluded — market not accepted')
    rows, t0 = [], time.time()
    for origin, spec, fire in allspecs:
        try:
            fr = fire(df, spec)                      # ONE fire against the whole frame
        except Exception as _e:
            record_spec_error(sport, spec.get('name'), _e)
            continue
        fr = _apply_global_odds_floor(fr, '_odds')   # v65_v15: 1.65 entry floor, every strategy
        if fr is None or len(fr) == 0: continue
        if 'mstart' not in fr.columns:
            if 'match_id' in fr.columns and 'match_id' in df.columns:
                fr = fr.merge(df[['match_id','mstart']].drop_duplicates('match_id'),
                              on='match_id', how='left')
            else:
                # LAST silent-drop path closed: a spec whose output cannot be time-segmented
                # still gets a row saying so, rather than vanishing.
                rows.append(dict(sport=sport, origin=origin, name=spec['name'],
                                 status='no mstart — cannot segment', **NIL))
                continue
        if fr['mstart'].isna().all():
            rows.append(dict(sport=sport, origin=origin, name=spec['name'],
                             status='mstart all null — cannot segment', **NIL))
            continue
        won = fr['_won'].to_numpy(bool); pnl = fr['_profit'].to_numpy('float64')
        od  = fr['_odds'].to_numpy('float64')
        rec = dict(sport=sport, origin=origin, name=spec['name'], status='evaluated')
        ok = True
        for key, m in _bucket_bets(fr, b).items():
            k = int(m.sum())
            if k == 0:
                for f_ in ('n','wr','odds','roi','ci','maxdd'): rec[f'{key}_{f_}'] = np.nan
                rec[f'{key}_n'] = 0; ok = False; continue
            p = pnl[m]; cum = np.cumsum(p)
            rec[f'{key}_n']     = k
            rec[f'{key}_wr']    = 100.0*won[m].mean()
            rec[f'{key}_odds']  = float(od[m].mean())
            rec[f'{key}_roi']   = 100.0*p.mean()
            rec[f'{key}_ci']    = fast_bootstrap_ci(p, n_boot=boot)
            rec[f'{key}_maxdd'] = _laz_maxdd(cum)
        if not ok: rec['status'] = 'partial — a segment had no bets'
        rows.append(rec)                      # kept regardless, so nothing disappears
    if verbose:
        print(f'[assess] {sport}: {len(rows)} spec(s) measured in {time.time()-t0:.0f}s '
              f'(single pass, {len(allspecs)} fired)')
    return pd.DataFrame(rows)

# (declared early) ASSESS_SINGLE_PASS


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION AD — CACHED-MASK EVALUATION
# ═══════════════════════════════════════════════════════════════════════════════════════
#  evaluate_discovered() applies each strategy's conditions with a fresh comparison per condition
#  per strategy. Across 431 strategies averaging four conditions that is ~1,700 comparisons, and
#  they are heavily duplicated — `is_leader == 1` appears in dozens of stacks within the same
#  universe, recomputed every time.
#
#  The beam search solved this by materialising every condition mask ONCE as a boolean array and
#  stacking with bitwise AND. The same applies here: within a universe a condition string always
#  produces the same mask, so it need only be built once.
#
#  Also folded in: metrics computed straight from numpy rather than through a DataFrame, and the
#  vectorised bootstrap.

class _MaskCache:
    """Materialises each distinct condition once per universe, then stacks by bitwise AND."""
    __slots__ = ('E', 'cache', 'hits', 'misses')

    def __init__(self, E):
        self.E = E; self.cache = {}; self.hits = 0; self.misses = 0

    def mask_for(self, cond):
        import re
        m = self.cache.get(cond)
        if m is not None:
            self.hits += 1; return m
        self.misses += 1
        mm = re.match(r'^(\S+)\s+(>=|<|==)\s+(.+)$', cond)
        if not mm: self.cache[cond] = None; return None
        col, op, val = mm.groups()
        if col not in self.E.columns: self.cache[cond] = None; return None
        try:
            f = float(val)
            x = self.E[col].to_numpy('float64')
            m = (x >= f) if op == '>=' else ((x < f) if op == '<' else (x == f))
        except ValueError:
            m = (self.E[col].astype(str) == val).to_numpy()
        self.cache[cond] = m
        return m

    def stack(self, conditions):
        out = None
        for c in conditions:
            m = self.mask_for(c)
            if m is None: return None
            out = m if out is None else (out & m)
        return out

def _metrics_from_arrays(won, pnl, odds, mstart, bounds, boot=400):
    """Segment metrics computed directly from numpy — no DataFrame round-trip per strategy."""
    rec = {}
    segs = {'is': mstart <= bounds['half'], 'oos': mstart > bounds['half'],
            'bwd': mstart <= bounds['q40'],
            'frz': (mstart > bounds['q40']) & (mstart <= bounds['q70']),
            'fwd': mstart > bounds['q70']}
    for k, m in segs.items():
        n = int(m.sum())
        rec[f'{k}_n'] = n
        if n == 0:
            for f_ in ('wr','odds','roi','ci','maxdd'): rec[f'{k}_{f_}'] = np.nan
            continue
        p = pnl[m]; cum = np.cumsum(p)
        rec[f'{k}_wr']    = 100.0*won[m].mean()
        rec[f'{k}_odds']  = float(odds[m].mean())
        rec[f'{k}_roi']   = 100.0*p.mean()
        rec[f'{k}_ci']    = fast_bootstrap_ci(p, n_boot=boot)
        rec[f'{k}_maxdd'] = _laz_maxdd(cum)
    return rec

def evaluate_discovered_fast(sports=None, verbose=True, boot=0, full_segments=False):
    """Cached-mask replacement for evaluate_discovered(). Same records, far less repeated work."""
    sports = _ordered_sports(sports, available=list(DISCOVERED_STRATEGIES))   # eBasketball first
    rows, missing, t0 = [], [], time.time()
    hits = miss = 0
    for sport in sports:
        lst = DISCOVERED_STRATEGIES.get(sport, [])
        if not lst: continue
        fams = sorted({x.get('family') for x in lst})
        # THE ACTUAL COST. build_discovery_universe() calls v46_frame() itself, so a sport with
        # three families read the same 1.7M-row parquet THREE times. Read it once and hand the
        # same frame to each family builder. Mask caching, by contrast, measured NO benefit —
        # the comparisons were already cheap next to this.
        _shared = None
        if len(fams) > 1:
            try:
                _shared = v46_frame(sport)
                if verbose:
                    print(f'[discovered] {sport}: frame read once for {len(fams)} families '
                          f'({len(_shared):,} rows)', flush=True)
            except Exception: _shared = None
        for family in fams:
            fam = [x for x in lst if x.get('family') == family]
            # NO .copy(). build_discovery_universe immediately does df.sort_values(), which
            # returns a NEW frame — every later mutation lands on that copy, never on the input.
            # Copying first was what made frame reuse a net loss last time (0.83x on a 2.76M-row
            # frame); passing the same object is both safe and free.
            try: E = (cached_discovery_universe(sport, family) if _shared is None
                      else build_discovery_universe(sport, family, frame=_shared))
            except Exception as e:
                missing += [(sport, family, f'{type(e).__name__}: {e}')]*len(fam); continue
            if E is None or len(E) == 0:
                missing += [(sport, family, 'empty universe')]*len(fam); continue
            mc = _MaskCache(E)
            b   = segment_bounds(E)
            won = E['_w'].to_numpy(bool); pnl = E['_pnl'].to_numpy('float64')
            od  = E['_o'].to_numpy('float64'); ms = E['mstart'].values
            for i, x in enumerate(fam):
                m = mc.stack(x['conditions'])
                if m is not None and GLOBAL_MIN_ODDS:        # v65_v15 entry floor
                    m = m & (od >= GLOBAL_MIN_ODDS)
                if m is None or not m.any():
                    missing.append((sport, family, f'#{i} no rows')); continue
                p = pnl[m]; cum = np.cumsum(p)
                rec = dict(sport=sport, family=family, idx=i, n=int(m.sum()),
                           wr=100.0*won[m].mean(), odds=float(od[m].mean()),
                           roi=100.0*p.mean(),
                           dd=_laz_maxdd(cum),
                           conditions='; '.join(x['conditions']))
                # Default: IS/OOS only, matching what the original produced. The full five-segment
                # record with a bootstrap per segment costs more than the mask caching saves —
                # measured 0.7x, i.e. SLOWER — so it is opt-in via full_segments=True.
                if full_segments:
                    rec.update(_metrics_from_arrays(won[m], p, od[m], ms[m], b, boot=boot))
                else:
                    _ms = ms[m]; _is = _ms <= b['half']; _oo = ~_is
                    rec['is_n']   = int(_is.sum());  rec['oos_n']  = int(_oo.sum())
                    rec['is_wr']  = 100.0*won[m][_is].mean() if _is.any() else np.nan
                    rec['oos_wr'] = 100.0*won[m][_oo].mean() if _oo.any() else np.nan
                    rec['is_roi'] = 100.0*p[_is].mean() if _is.any() else np.nan
                    rec['oos_roi']= 100.0*p[_oo].mean() if _oo.any() else np.nan
                rows.append(rec)
            hits += mc.hits; miss += mc.misses
            del E, mc; gc.collect()
        if _shared is not None:
            del _shared; gc.collect()
        if verbose:
            print(f'[discovered] {sport}: {len([r for r in rows if r["sport"]==sport])} evaluated',
                  flush=True)
    if verbose:
        reuse = 100.0*hits/max(hits+miss, 1)
        print(f'[discovered] {len(rows)} strategies in {time.time()-t0:.1f}s · '
              f'mask reuse {reuse:.0f}% ({hits} cached / {miss} built)')
        if missing: print(f'[discovered] {len(missing)} not evaluable: {missing[:2]}')
    return pd.DataFrame(rows), missing

# OFF by default. evaluate_discovered_fast() produces IDENTICAL results but measured 0.92x — i.e.
# SLOWER. Two ideas that should have helped did not:
#   mask caching  — 75-85% reuse achieved, but the comparisons were already cheap next to universe
#                   construction, and the cached arrays cost memory and dict lookups.
#   frame reuse   — reading the parquet once for three families is offset by having to .copy() a
#                   2.76M-row frame per family, which costs more than the re-read.
# Kept because it is verified equivalent and useful for full_segments=True (a five-segment record
# with bootstrap per segment, which the original does not produce), but not made the default.
# OFF. Measured 0.83x even after removing the .copy() that was blamed the first time. The reason
# is that the OS PAGE CACHE already does this: the second and third reads of the same parquet come
# from RAM, so holding the frame in Python saves nothing and adds bookkeeping. Kept because it is
# verified equivalent and provides full_segments=True, but not the default.
EVALUATE_DISCOVERED_FAST = False


def discovery_columns_for(sport, all_columns):
    """Columns build_discovery_universe and this sport's strategies can possibly touch.

    Safe here in a way it was NOT for the fire functions: the discovery universe builds its own
    features from a known, explicit set, and the strategy conditions name their columns literally
    in DISCOVERED_STRATEGIES. Nothing is inferred from source inspection, so nothing can be missed.
    Projecting on read turns a 10.6s parquet load into a fraction of that."""
    # IDENTITY COLUMNS. These are never conditions, but without them the per-bet sheet cannot say
    # WHO the bet was on — match_name and player names were coming through blank.
    IDENTITY = {'match_name','home_team_player','away_team_player','home_team','away_team',
                'hp_player_name','ap_player_name','gametype','sport',
                'betsson_home_player_elo','betsson_away_player_elo',
                'hp_total_player_wr','ap_total_player_wr'}
    BASE = IDENTITY | {'match_id','ts','mstart','mend','home_odds','away_odds','draw_odds',
            'final_result','final_winner','h_score','a_score','prog','minute','hour',
            'lead','run_tot','frac','q1_lead','q1_tot','league','phase','id',
            'total_points_handicap','total_points_over','total_points_under',
            'point_spread_handicap','tg','Minute_FGS'}
    refs = set()
    for x in DISCOVERED_STRATEGIES.get(sport, []):
        for c in x.get('conditions', []):
            head = str(c).split()
            if head: refs.add(head[0])
    keep = [c for c in all_columns if c in BASE or c in refs]
    return keep if len(keep) >= 8 else list(all_columns)

def _safe_numeric_frame(df, verbose=False):
    """Removes Categorical dtypes anywhere they could reach a comparison or a quantile.

    Tennis died with 'Invalid comparison between dtype=category and float64' inside the discovered
    universe path even though the written frame had none — a categorical was re-emerging during
    construction. Every universe builder now normalises on entry: numeric categoricals back to
    numbers, text to plain strings."""
    cats = [c for c in df.columns if str(df[c].dtype) == 'category']
    if not cats: return df
    out = df.copy()
    for c in cats:
        try:
            k = out[c].cat.categories.dtype
            out[c] = out[c].astype(k) if k.kind in 'ifubMm' else out[c].astype(str)
        except Exception:
            out[c] = out[c].astype(str)
    if verbose: print(f'[safe] normalised {len(cats)} categorical column(s)')
    return out


def discovery_frame(sport, verbose=False):
    """Loads a sport's frame with only the columns discovery needs."""
    import pyarrow.parquet as _pq
    path = V46_FRAMES[sport]
    try:
        names = _pq.ParquetFile(path).schema.names
        keep = discovery_columns_for(sport, names)
        if len(keep) < len(names):
            df = _laz_decat(pd.read_parquet(path, columns=keep))
            if verbose:
                print(f'[universe] {sport}: read {len(keep)}/{len(names)} columns')
            return df
    except Exception:
        pass
    return v46_frame(sport)


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION AE — PLACEABILITY FOR DISCOVERED STRATEGIES
# ═══════════════════════════════════════════════════════════════════════════════════════
#  Every ROI figure in this book assumes you got the price the entry tick showed. Placeability asks
#  whether that price was still there when you went to take it.
#
#  The registry families have this (trigger persisted >= 20s). The 431 discovered ones never did,
#  and they are the more exposed set: the misprice family enters precisely when the market has NOT
#  yet re-rated a side that just took the lead, which is by definition the price most likely to
#  move. A +160% ROI on a quote that vanishes in four seconds is worth nothing.
#
#  Measured here, per bet, from the tick data itself:
#    hold_seconds  — how long the price stayed at or better than the entry price
#    hold_ticks    — how many feed updates that covered
#    placeable_20s — the share of bets where it held at least 20 seconds
#    decay_pct     — how far the price had moved against you after 20 seconds

PLACEABILITY_WINDOW_S = 20.0
PLACEABILITY_TOLERANCE = 0.98    # price counts as still available down to 2% worse

def measure_placeability(sport, family, strategies=None, window_s=PLACEABILITY_WINDOW_S,
                         tol=PLACEABILITY_TOLERANCE, verbose=True):
    """Per-bet price persistence for a discovered family.

    For each entry it walks forward through that match's remaining ticks on the SAME side and finds
    where the price first falls below `tol` x entry. Prices are what the book showed, so this is a
    measurement of quote persistence — not of whether your stake would be matched at size, which no
    historical feed can answer."""
    E = build_discovery_universe(sport, family)
    if E is None or not len(E): return None
    # the full tick stream, needed to look forward from each entry
    df = discovery_frame(sport)
    df = df.sort_values(['match_id', 'ts'])
    ts_all = pd.to_datetime(df['ts']).values.astype('datetime64[s]').astype('int64')
    mid_all = df['match_id'].astype(str).values
    rows = []
    strategies = strategies if strategies is not None else DISCOVERED_STRATEGIES.get(sport, [])
    fam = [x for x in strategies if x.get('family') == family]
    if not fam: return None
    mc = _MaskCache(E)
    for i, x in enumerate(fam):
        m = mc.stack(x['conditions'])
        if m is None or not m.any(): continue
        S = E[m]
        holds, ticks = [], []
        for side_col in ('_side',):
            pass
        ent_mid = S['match_id'].astype(str).values
        ent_ts  = pd.to_datetime(S['ts'] if 'ts' in S.columns else S['mstart']).values \
                    .astype('datetime64[s]').astype('int64')
        ent_odd = S['_o'].to_numpy('float64')
        side    = S['_side'].values if '_side' in S.columns else np.array(['home']*len(S))
        for k in range(len(S)):
            oc = 'home_odds' if side[k] == 'home' else 'away_odds'
            sel = (mid_all == ent_mid[k]) & (ts_all >= ent_ts[k])
            if not sel.any(): continue
            fut_o = df.loc[sel, oc].to_numpy('float64')
            fut_t = ts_all[sel]
            good = fut_o >= ent_odd[k] * tol
            if good.all():
                held = float(fut_t[-1] - fut_t[0]); nt = int(good.sum())
            else:
                first_bad = _laz_argmax(~good)
                held = float(fut_t[max(first_bad-1, 0)] - fut_t[0]); nt = first_bad
            holds.append(held); ticks.append(nt)
        if not holds: continue
        h = np.asarray(holds, dtype='float64'); tk = np.asarray(ticks, dtype='float64')
        rows.append(dict(sport=sport, family=family, idx=i, bets=len(h),
                         median_hold_s=float(np.median(h)), mean_hold_s=float(h.mean()),
                         median_ticks=float(np.median(tk)),
                         placeable_20s=100.0*float((h >= window_s).mean()),
                         placeable_5s=100.0*float((h >= 5.0).mean()),
                         instant_only=100.0*float((h <= 0).mean()),
                         conditions='; '.join(x['conditions'])))
        if verbose and len(rows) % 10 == 0:
            print(f'[place] {sport}/{family}: {len(rows)} strategies measured', flush=True)
    del df, E, mc; gc.collect()
    return pd.DataFrame(rows)


# ═══════════════════════════════════════════════════════════════════════════════════════
#  v61 SECTION AF — UNIVERSE CACHE
# ═══════════════════════════════════════════════════════════════════════════════════════
#  What remains of the cost is I/O: every universe is rebuilt from the sport's full frame, so a
#  five-sport run reads millions of rows nine times to produce populations of 250 to 18,000 rows.
#
#  Holding the frame in Python did NOT help — measured 0.83x, because the OS page cache already
#  serves repeat reads from RAM. The fix is not to cache the input but to stop needing it: persist
#  the UNIVERSE itself, which is three orders of magnitude smaller, and read that instead.
#
#  Keyed on the frame's fingerprint (rows, columns, file size) so it invalidates automatically when
#  the data changes — the same discipline as the segment checkpoints.
UNIVERSE_CACHE_DIR = LAZ('_lz_universe')
USE_UNIVERSE_CACHE = True

def _universe_cache_path(sport, family):
    # v65_v13: the key now includes ENGINE_VERSION. Keying on the frame fingerprint alone meant a
    # change to a UNIVERSE BUILDER silently reused stale universes — the identity columns added to
    # discovery_columns_for never reached ledgers built from a warm cache. Same defect class the
    # _ckpt_path docstring records; same fix.
    os.makedirs(UNIVERSE_CACHE_DIR, exist_ok=True)
    return os.path.join(UNIVERSE_CACHE_DIR,
                        f'{ENGINE_VERSION}_{sport}_{family}_{_frame_fingerprint(sport)}.parquet')

def cached_discovery_universe(sport, family, frame=None, verbose=False, refresh=False):
    """build_discovery_universe with a persistent cache.

    A universe is a deterministic function of the frame, so once built it can be read back rather
    than rebuilt. 8,827 rows instead of 1.7M."""
    if not USE_UNIVERSE_CACHE or frame is not None:
        return build_discovery_universe(sport, family, frame=frame, verbose=verbose)
    path = _universe_cache_path(sport, family)
    if not refresh and os.path.exists(path):
        try:
            E = _laz_decat(pd.read_parquet(path))
            if verbose: print(f'[universe] {sport}/{family}: cache hit ({len(E):,} rows)')
            return E
        except Exception:
            pass
    E = build_discovery_universe(sport, family, verbose=verbose)
    if E is not None and len(E):
        try:
            E.to_parquet(path, compression='zstd')
            if verbose: print(f'[universe] {sport}/{family}: cached {len(E):,} rows -> {path}')
        except Exception as e:
            if verbose: print(f'[universe] cache write failed: {type(e).__name__}')
    return E


