def _merge_new_inverse():
    """Folds the tennis and football inverse families into the registry."""
    out = {}
    for sport, lst in NEW_INVERSE_STRATEGIES.items():
        if not lst: continue
        DISCOVERED_STRATEGIES.setdefault(sport, [])
        have = {tuple(sorted(x.get('conditions', []))) for x in DISCOVERED_STRATEGIES[sport]}
        added = 0
        for x in lst:
            if tuple(sorted(x['conditions'])) in have: continue
            DISCOVERED_STRATEGIES[sport].append(x); added += 1
        out[sport] = added
    return out

