    formula='home_odds if h_score > a_score, away_odds if a_score > h_score, else undefined (tie -> no bet)',
    backtest_expr="np.where(df['h_score']>df['a_score'], df['home_odds'], np.where(df['a_score']>df['h_score'], df['away_odds'], np.nan))",
    live_expr="f['leading_ml'] = ho if sd>0 else ao if sd<0 else None",
