# ═══ TENNIS LIVE LAYER ═════════════════════════════════════════════════════════════════
class V67TenTickState:
    """Per-match state from the first tick. The set-1 winner is latched once and never
    revised — a later set changing hands does NOT change who this strategy backs."""
    __slots__ = ('ph', 'pa', 's1_winner', 's1_seen', 'ticks', 'last_ts', 'first_sets')

    def __init__(self):
        self.ph = self.pa = None          # PRE-MATCH prices, from the first tick seen
        self.s1_winner = None             # 'home' | 'away', latched
        self.s1_seen = False
        self.ticks = 0
        self.last_ts = None
        self.first_sets = None

    def update(self, ts, ho, ao, h, a):
        self.ticks += 1
        gap = (ts - self.last_ts) if (ts and self.last_ts) else 0.0
        self.last_ts = ts
        if self.ph is None and ho is not None:
            self.ph = ho
        if self.pa is None and ao is not None:
            self.pa = ao
        if h is not None and a is not None:
            if self.first_sets is None:
                self.first_sets = h + a
            # latch the set-1 winner at the FIRST tick where the set total reaches 1
            if not self.s1_seen and (h + a) >= 1:
                self.s1_winner = 'home' if h > a else 'away'
                self.s1_seen = True
        return gap


class V67TenFeatureEngine:
    REQUIRED_STATE_KEYS = ['match_id', 'epoch_ts', 'phase', 'league',
                           'h_score', 'a_score', 'home_odds', 'away_odds', 'market_status']

    def __init__(self):
        import threading
        self._st = {}
        self._lock = threading.Lock()

    def _s(self, mid):
        with self._lock:
            if mid not in self._st:
                self._st[mid] = V67TenTickState()
            return self._st[mid]

    def drop(self, mid):
        with self._lock:
            self._st.pop(mid, None)

    @staticmethod
    def mins_of(phase):
        import re as _r
        m = _r.search(r'(\d+)(?=\s*min)', str(phase or ''))
        return float(m.group(1)) if m else None

    @staticmethod
    def set_no_of(phase):
        import re as _r
        m = _r.search(r'(\d)(?:st|nd|rd|th)\s*Set', str(phase or ''))
        return float(m.group(1)) if m else None

    def compute(self, st):
        def num(k):
            v = st.get(k)
            try:
                fv = float(v) if v is not None else None
            except Exception:
                return None
            return None if (fv is not None and fv != fv) else fv    # NaN -> None

        f = {}
        ts = st.get('epoch_ts')
        ho, ao = num('home_odds'), num('away_odds')
        h, a = num('h_score'), num('a_score')
        S = self._s(st['match_id'])
        gap = S.update(ts, ho, ao, h, a)

        lg = str(st.get('league') or '').lower()
        f['is_e'] = 1.0 if V67_TEN_LEAGUE_TOKEN in lg else 0.0
        f['mins'] = self.mins_of(st.get('phase'))
        f['set_no'] = self.set_no_of(st.get('phase'))
        f['sets'] = (h + a) if (h is not None and a is not None) else None
        f['_s1_winner'] = S.s1_winner
        f['_post_s1'] = bool(S.s1_seen)
        # ATTACHMENT: the pre-match price anchors s1w_pre and dog. A match first seen with a
        # set already decided has the wrong anchor -- drop it rather than bet it.
        f['_attached_at_start'] = (S.first_sets is not None and S.first_sets == 0)
        if S.s1_winner == 'home':
            f['_o'], f['opp'] = ho, ao
            f['s1w_pre'] = S.ph
            opp_pre = S.pa
        elif S.s1_winner == 'away':
            f['_o'], f['opp'] = ao, ho
            f['s1w_pre'] = S.pa
            opp_pre = S.ph
        else:
            f['_o'] = f['opp'] = f['s1w_pre'] = None
            opp_pre = None
        o_, op_ = f['_o'], f['opp']
        f['anchor'] = ((1 / o_) / ((1 / o_) + (1 / op_))) if (o_ and op_) else None
        f['dog'] = (1.0 if (f['s1w_pre'] is not None and opp_pre is not None
                            and f['s1w_pre'] >= opp_pre) else 0.0) if f['s1w_pre'] else None
        f['s1w_ratio'] = (1 - o_ / f['s1w_pre']) if (o_ and f['s1w_pre']) else None
        # ── v68: WITHOUT THESE the v68 S1W book fires in the backtest and NEVER in
        # production. Both anchor on state already latched above, so no new attachment
        # requirement is introduced. Caught by gate 11 and re-applied after a file loss.
        if S.s1_winner == 'home':
            f['s1w_sd'] = (h - a) if (h is not None and a is not None) else None
            f['jump_s1w'] = (ho / S.ph) if (ho and S.ph) else None
            f['jump_opp'] = (ao / S.pa) if (ao and S.pa) else None
        elif S.s1_winner == 'away':
            f['s1w_sd'] = (a - h) if (h is not None and a is not None) else None
            f['jump_s1w'] = (ao / S.pa) if (ao and S.pa) else None
            f['jump_opp'] = (ho / S.ph) if (ho and S.ph) else None
        else:
            f['s1w_sd'] = f['jump_s1w'] = f['jump_opp'] = None
        f['pm_ratio'] = (op_ / o_) if (o_ and op_) else None
        # ── v75: FEATURES THE TNQ BOOK NEEDS ─────────────────────────────────────────
        # Gate 11 refused TNQ02-05 because these five existed only in the backtest frame,
        # never in the live engine: they would have fired in the book and NEVER in
        # production. Every one is built from values already on this tick or from running
        # extremes over ticks already seen, so nothing here looks forward.
        #   ten_pm_ratio   sport-prefixed alias of pm_ratio, identical value. The namespace
        #                  migration rewrote the TNQ conditions to the prefixed form.
        #   ten_minute     elapsed minutes, same source as mins.
        #   ten_mins       alias the older tennis containers use.
        #   pm_dog_odds    the PRE-MATCH price of the longer side. Latched at the first tick
        #                  of the match and never recomputed, so it is fixed before play.
        #   ten_dog_ml     the underdog's LIVE price at this tick -- the longer of the two.
        #   dog_anchor     how far the underdog has shortened inside its own observed range:
        #                  (open - now) / (open - running_min). 0 means it has not moved off
        #                  its opening price; 1 means it is at the shortest price seen so
        #                  far this match. Running extremes over ticks ALREADY SEEN.
        f['ten_pm_ratio'] = f.get('pm_ratio')
        f['ten_minute'] = f.get('mins')
        f['ten_mins'] = f.get('mins')
        # V67TenTickState declares __slots__, so new attributes cannot be attached to it --
        # two attempts to latch dog_open there raised AttributeError and the selftest caught
        # both. The pre-match prices are ALREADY latched as S.ph / S.pa at the first tick,
        # which is exactly what pm_dog_odds needs, so nothing new has to be stored.
        # dog_anchor is then measured against that fixed opening rather than a running
        # minimum: how far the underdog has shortened FROM ITS OPENING PRICE, bounded to
        # [0,1]. Both values are causal -- ph/pa come from the first tick of this match.
        try:
            # The dog's OPENING price is that same fixed side's first quote.
            _pm_dog = (max(float(S.ph), float(S.pa))
                       if (S.ph is not None and S.pa is not None) else None)
            f['pm_dog_odds'] = _pm_dog
            if ho is not None and ao is not None:
                # THE DOG IS A FIXED PRE-MATCH ROLE, NOT A PER-TICK MAXIMUM. The backtest
                # sets it once from the pre-match favourite:
                #     dog_ml = away_odds if pm_fav == 'Home' else home_odds
                # Taking max(ho, ao) at every tick SWITCHES SIDES the moment the prices
                # cross -- which is exactly when an underdog is winning, so the feature
                # flipped precisely in the situations these strategies select. Replay
                # measured 1.58 divergence after the ratio fix; this is the remaining half.
                # S.ph / S.pa are the pre-match prices latched at the first tick, so the
                # role is decided there and never changes.
                _dog_is_away = (S.ph is not None and S.pa is not None
                                and float(S.ph) < float(S.pa))
                _dog_now = float(ao) if _dog_is_away else float(ho)
                f['ten_dog_ml'] = _dog_now
                # MATCH THE BACKTEST EXACTLY. The backtest builds this at line 21586 as
                #     df['dog_anchor'] = dog_ml / first dog_ml of the match
                # -- a RATIO with no bound. My first version returned a normalised distance
                # clipped to [0,1], which is a different quantity entirely: the replay test
                # measured a maximum divergence of 5.43 against a backtest range of
                # 0.378..5.435. The strategy conditions (dog_anchor >= 0.7857) were tuned
                # against the ratio, so a clipped version would have selected a different
                # population while looking correct.
                # Above 1 the underdog has DRIFTED OUT since the open; below 1 it has come
                # in. TNQ03's floor of 0.786 admits both, excluding only sharp shorteners.
                f['dog_anchor'] = ((_dog_now / _pm_dog) if (_pm_dog and _pm_dog > 1e-9)
                                   else None)
            else:
                f['ten_dog_ml'] = None
                f['dog_anchor'] = None
        except (TypeError, ValueError):
            f['ten_dog_ml'] = f['pm_dog_odds'] = f['dog_anchor'] = None
        f['ovr2'] = ((1 / ho) + (1 / ao)) if (ho and ao) else None
        # match progress for tennis = set number / 3. Required by the placeability lever;
        # without it every prog-based uplift on this book is refused.
        f['prog'] = (f['set_no'] / 3.0) if f.get('set_no') is not None else None
        f['tick_gap_s'] = gap
        f['_mk_open'] = str(st.get('market_status') or 'Open').lower() == 'open'
        # ── SPORT-NAMESPACED ALIASES ─────────────────────────────────────────────
        # `prog` is minute/lmin in eFootball, quarter/4 in eBasketball and set/3 in
        # tennis -- three different quantities under one name. A patch meant for one
        # engine was once applied to another and blanked prog for 20+ strategies, every
        # one failing closed. Registered conditions use the PREFIXED name; the canonical
        # name is kept only so older specs still parse. laz_feature_collision_audit()
        # fails the build if a shared name is ever computed two different ways again.
        f['ten_prog'] = f.get('prog')
        f['ten_o'] = f.get('_o')
        f['ten_set_no'] = f.get('set_no')
        f['ten_mins'] = f.get('mins')
        return f


class V67TenEvaluator:
    """One bet per (match, strategy), struck at the FIRST tick after set 1 is decided at
    which the strategy's conditions all hold and the price is inside its band."""

    def __init__(self, mode='shadow', require_attach=False):
        import threading
        self.mode = mode
        self.require_attach = require_attach
        self.feats = V67TenFeatureEngine()
        self._fired = set()
        self._lock = threading.Lock()

    def evaluate_tick(self, st):
        f = self.feats.compute(st)
        out = []
        if not f['_mk_open'] or not f['_post_s1']:
            return out
        if f.get('tick_gap_s') is None or f['tick_gap_s'] > 300:
            return out
        if self.require_attach and not f['_attached_at_start']:
            return out
        for s in V67_TEN_STRATEGIES:
            if not s.get('enabled'):
                continue
            key = (st['match_id'], s['laz_id'])
            if key in self._fired:
                continue
            odds = f.get('_o')
            if odds is None or odds < s['min_odds'] - V67_ODDS_EPS \
                    or odds > s['max_odds'] + V67_ODDS_EPS:
                continue
            vals, ok = {}, True
            for c in s['conditions']:
                g = _V67_CRE.match(c)
                if not g:
                    ok = False
                    break
                feat, op, val = g.group(1), g.group(2), float(g.group(3))
                v = f.get(feat)
                if v is None:
                    ok = False
                    break
                vals[feat] = v
                if not _V67_OPS[op](v, val):
                    ok = False
                    break
            if not ok:
                continue
            with self._lock:
                if key in self._fired:
                    continue
                self._fired.add(key)
            out.append(dict(laz_id=s['laz_id'], name=s['name'], tier=s['tier'],
                            family=s['family'], market=s['market'], entry_odds=odds,
                            backs=f['_s1_winner'], min_odds=s['min_odds'],
                            conditions=list(s['conditions']), laz_condition_values=vals,
                            mode=self.mode, engine_version=V67_VERSION))
        return out

    def finalize_match(self, mid):
        self.feats.drop(mid)
        with self._lock:
            self._fired = {k for k in self._fired if k[0] != mid}


