# ═══════════════════════════════════════════════════════════════════════════════════════
#  v67 — THE OVERREACTION FEATURE FAMILY                                     [ADDITIVE]
# ═══════════════════════════════════════════════════════════════════════════════════════
#  ONE IDEA, REUSABLE ACROSS EVERY MARKET: current price divided by a reference price.
#  It measures how far the book has MOVED, not where the price sits. u_rank tells you the
#  position in a range; jump tells you the distance travelled to get there.
#
#  ── THE DIRECTION FLIPS BY MARKET, AND THAT IS THE POINT ────────────────────────────
#  BACKING A COMEBACK  we want the book to have moved AWAY from our side. A trailing
#      player drifting out 3-4x has been over-punished for one goal. Measured, eFootball
#      GT+Adriatic, trailing side, odds>=8, trail_by<=1, prog<=0.50:
#          jump >= 3.0   1,761 bets  14.1% WR  +163.3% ROI  o=22.24
#          jump >= 5.0     679 bets  11.6% WR  +226.5% ROI  o=31.80
#          jump <= 2.0   1,621 bets  11.1% WR   +49.8% ROI  o=13.69   <- no overreaction,
#                                                                        far less edge
#      The gradient IS the evidence: bigger overreaction, bigger edge.
#
#  BACKING AN UNDER    we want the book to have moved TOWARD our side. A shortening under
#      price is the market confirming the game has gone cold, and it still under-shoots.
#          eFootball, odds>=1.90, base 54.7% WR / +12.6% ROI:
#              u_jump <= 0.90      1,227 bets  62.4% WR  +21.8% ROI   <- +7.7 WR points
#              u_goal_jump <= 0.95 2,734 bets  59.6% WR  +18.1% ROI
#              u_jump >= 1.30      9,113 bets  49.9% WR  +17.5% ROI   <- lower WR, ROI from odds
#          eBasketball, odds>=1.85, base 75.5% WR / +42.9% ROI:
#              u_jump >= 1.10      2,308 bets  74.0% WR  +46.9% ROI
#              u_jump_low <= 1.01  6,248 bets  77.0% WR  +43.8% ROI
#
#  A price drifting AGAINST the side you are backing is an overreaction to fade.
#  A price drifting TOWARD it is confirmation to follow. Same arithmetic, opposite sign,
#  and which one applies is a property of the MARKET, not of the feature.
#
#  ── ATTACHMENT: THIS FEATURE IS WRONG IF YOU CONNECT LATE ───────────────────────────
#  jump is anchored on the FIRST TICK SEEN. Connect at 60% of the match and the
#  denominator is a mid-match price, not the opening one, and every threshold shifts.
#  Set _attached_at_start and DROP the match rather than bet it.
# ═══════════════════════════════════════════════════════════════════════════════════════

def laz_jump(price_now, price_ref):
    """THE canonical overreaction ratio. Returns None on any missing or non-positive
    input so the condition fails closed rather than firing on a bad number."""
    try:
        p, r = float(price_now), float(price_ref)
    except (TypeError, ValueError):
        return None
    if p != p or r != r or r <= 0 or p <= 0:
        return None
    return p / r


V67_JUMP_LINEAGE = {
 'jump': _l(tier='B_INMATCH', units='ratio',
    definition='how far the BACKED side\'s price has drifted from THAT SIDE\'S OWN first '
               'observed price. >1 means the book has moved against us.',
    source_cols=['home_odds', 'away_odds'],
    formula='current backed price / backed price at the first observed tick',
    backtest_expr="d._o / d.groupby(match_id + '|' + side)._o.transform('first')  # PER SIDE",
    live_expr='laz_jump(current_backed_price, S.o_open)',
    nan_policy='reference price missing or <=0 -> None -> condition FAILS CLOSED',
    requires='ATTACHMENT AT THE FIRST TICK. A late connect makes the denominator a '
             'mid-match price and every threshold shifts. Drop the match, do not bet it.',
    note='On the comeback market the edge RISES with jump: >=2.0 gives +137%, >=3.0 gives '
         '+163%, >=5.0 gives +226%, while <=2.0 gives only +50%.'),

 'jump_from_low': _l(tier='B_INMATCH', units='ratio',
    definition='drift from the CHEAPEST the backed side has been this match',
    source_cols=['home_odds', 'away_odds'],
    formula='current backed price / running minimum of that price',
    backtest_expr="d._o / g._o.cummin()",
    live_expr='laz_jump(current_backed_price, S.o_runmin)',
    nan_policy='no observed minimum -> None -> FAILS CLOSED',
    requires='attachment at the first tick',
    note='Stricter than jump: measures drift from the best price actually seen rather than '
         'from the opening quote.'),

 'u_jump': _l(tier='B_INMATCH', units='ratio',
    definition='drift of the UNDER price from its opening quote',
    source_cols=['total_goals_under', 'total_points_under'],
    formula='current under price / under price at the first observed tick',
    backtest_expr="d.u_odds / d.match_id.map(g.u_odds.first())",
    live_expr='laz_jump(u, S.u_open)',
    nan_policy='opening under price missing -> None -> FAILS CLOSED',
    requires='ATTACHMENT AT KICK-OFF, and the anchor must come from the RAW TICK STREAM, '
             'not the filtered universe. The live engine sees every tick, so u_open is the '
             'first non-null under price of the MATCH. Computing it from a frame already '
             'filtered on completeness/quarter/overround shifts the denominator and breaks '
             'parity by a handful of bets -- measured, 1 of 20 eBasketball strategies.',
    note='DIRECTION IS OPPOSITE to `jump`. u_jump <= 0.90 (price shortening, market '
         'confirming the under) lifts eFootball from 54.7% to 62.4% WR. On eBasketball the '
         'higher-ROI cut is u_jump >= 1.10 at 74.0% WR / +46.9%. Test both directions per '
         'sport rather than assuming.'),

 'u_goal_jump': _l(tier='B_INMATCH', units='ratio',
    definition='how far the under price moved in response to the LAST goal',
    source_cols=['total_goals_under', 'h_score', 'a_score'],
    formula='current under price / the under price immediately before the last score change',
    backtest_expr="d.u_odds / d.u_odds.where(~score_changed).groupby(match).ffill()",
    live_expr='laz_jump(u, S.u_before_last_goal)',
    nan_policy='no goal observed yet in this process -> None -> FAILS CLOSED',
    requires='attachment at kick-off; a mid-match connect misses earlier goals',
    note='Event-anchored rather than match-anchored. u_goal_jump <= 0.95 gives 59.6% WR / '
         '+18.1% ROI on eFootball unders against a 54.7% base.'),

 'secs_since_goal': _l(tier='B_INMATCH', units='seconds',
    definition='seconds since the scoreline last changed',
    source_cols=['h_score', 'a_score', 'timestamp'],
    formula='now - timestamp of the last observed score change',
    backtest_expr="(d.ts - d.ts.where(score_changed).groupby(match).ffill()).dt.total_seconds()",
    live_expr='ts - S.last_score_ts',
    nan_policy='no score change seen IN THIS PROCESS -> None -> FAILS CLOSED. A restart '
               'resets it.',
    requires='attachment at kick-off',
    note='secs_since_goal <= 30 gives 15.3% WR on the comeback core against 13.3% base — '
         'betting inside the window before the book settles.'),
}

