# ═══ SIGNED TRAILER-RELATIVE LINEAGE — the comeback feature class ══════════════════════
#  These are computed RELATIVE TO THE TRAILING SIDE, not as absolute differences. That
#  distinction is the whole family: |elo_home - elo_away| >= 100 says there is a mismatch
#  but not WHO is behind. elo_adv_loser >= 0 says the STRONGER player is the one trailing,
#  which is the comeback thesis. Measured on the comeback core, that single sign flip took
#  the win rate from 7.9% to 16.9% and ROI from +33.9% to +179.5% -- more than every
#  price-and-pace condition tested put together.
V67_COMEBACK_LINEAGE = {
 'trail_by': _l(tier='A_TICK', units='goals',
    definition='how many goals the backed (trailing) side is behind by',
    source_cols=['h_score', 'a_score'], formula='abs(h_score - a_score)',
    backtest_expr="d.sd.abs()", live_expr='abs(h - a)',
    note='trail_by <= 1 is load-bearing: a side two or three behind at 20+ odds is priced '
         'correctly, a side ONE behind is not.'),
 'elo_adv_loser': _l(tier='A_TICK', units='Elo points',
    definition='how much STRONGER the trailing player is than the leader. >0 means the '
               'better player is the one behind.',
    source_cols=['betsson_home_player_elo', 'betsson_away_player_elo', 'h_score', 'a_score'],
    formula='elo of the trailing side minus elo of the leading side',
    backtest_expr="np.where(lead_home, elo_away, elo_home) - np.where(lead_home, elo_home, elo_away)",
    live_expr='S.trailing_elo - S.leading_elo',
    nan_policy='either Elo missing or scores level -> None -> FAILS CLOSED',
    note='SIGNED, not absolute. Alone it lifts the comeback core from 7.9% to 16.9% WR.'),
 'form_adv_loser': _l(tier='A_TICK', units='fraction',
    definition='trailing player last-10 win rate minus the leader\'s',
    source_cols=['hp_winrate_l10g', 'ap_winrate_l10g', 'h_score', 'a_score'],
    formula='loser_form10 - leader_form10',
    backtest_expr="loser_form10 - leader_form10", live_expr='same, selected by who trails'),
 'loser_form10': _l(tier='A_TICK', units='fraction 0-1',
    definition='the TRAILING player\'s win rate over their last 10 games',
    source_cols=['hp_winrate_l10g', 'ap_winrate_l10g'], formula='winrate_l10g of the trailing side',
    backtest_expr="np.where(lead_home, ap_winrate_l10g, hp_winrate_l10g)",
    live_expr='winrate_l10g of whichever side trails'),
 'loser_h2h': _l(tier='A_TICK', units='fraction 0-1',
    definition='the trailing player\'s head-to-head win rate against THIS opponent',
    source_cols=['hp_h2h_winrate_l10g', 'ap_h2h_winrate_l10g'],
    formula='h2h winrate of the trailing side',
    backtest_expr="np.where(lead_home, ap_h2h_winrate_l10g, hp_h2h_winrate_l10g)",
    live_expr='h2h winrate of whichever side trails',
    note='loser_h2h >= 0.5 -- the trailer has beaten this specific opponent before -- gives '
         '16.3% WR / +136.4% on the core.'),
 'loser_att': _l(tier='A_TICK', units='goals per game',
    definition='the trailing player\'s goals scored per game, last 5',
    source_cols=['hp_avggoals_scored_5', 'ap_avggoals_scored_5'],
    formula='avggoals_scored_5 of the trailing side',
    backtest_expr="np.where(lead_home, ap_avggoals_scored_5, hp_avggoals_scored_5)",
    live_expr='avggoals_scored_5 of whichever side trails'),
 'leader_def': _l(tier='A_TICK', units='goals per game',
    definition='the LEADING player\'s goals conceded per game, last 5',
    source_cols=['hp_avggoals_conceded_5', 'ap_avggoals_conceded_5'],
    formula='avggoals_conceded_5 of the leading side',
    backtest_expr="np.where(lead_home, hp_avggoals_conceded_5, ap_avggoals_conceded_5)",
    live_expr='avggoals_conceded_5 of whichever side leads'),
 'comeback_fuel': _l(tier='A_TICK', units='goals per game',
    definition='the trailer\'s attack plus the leader\'s leaky defence',
    source_cols=['hp_avggoals_scored_5', 'ap_avggoals_scored_5',
                 'hp_avggoals_conceded_5', 'ap_avggoals_conceded_5'],
    formula='loser_att + leader_def', backtest_expr="d.loser_att + d.leader_def",
    live_expr='same', depends_on=['loser_att', 'leader_def'],
    note='The capability term. jump says the book overreacted; comeback_fuel says the '
         'trailer can actually punish it. Paired, they cut drawdown from 39u to 23u.'),
 'strength': _l(tier='A_TICK', units='composite score',
    definition='single composite of the trailer\'s advantage in Elo, form and head-to-head',
    source_cols=['betsson_*_elo', 'hp_winrate_l10g', 'ap_winrate_l10g',
                 'hp_h2h_winrate_l10g', 'ap_h2h_winrate_l10g'],
    formula='clip(elo_adv_loser/100, -3, 3) + form_adv_loser*2 + (loser_h2h - 0.5)*2',
    backtest_expr="(d.elo_adv_loser/100).clip(-3,3) + d.form_adv_loser*2 + (d.loser_h2h-0.5)*2",
    live_expr='same', depends_on=['elo_adv_loser', 'form_adv_loser', 'loser_h2h'],
    note='Weights are FIXED, not fitted: Elo scaled to roughly one unit per 100 points, form '
         'and h2h to roughly one unit per 50 percentage points. strength >= 0.3 on two '
         'conditions gives 455 bets at 19.8% / +281%.'),
 'loser_exp': _l(tier='A_TICK', units='games',
    definition='career games played by the trailing player',
    source_cols=['home_player_total_games', 'away_player_total_games'],
    formula='total_games of the trailing side',
    backtest_expr="np.where(lead_home, away_player_total_games, home_player_total_games)",
    live_expr='total_games of whichever side trails'),
 'fat_adv_loser': _l(tier='A_TICK', units='games',
    definition='how much MORE tired the leader is than the trailer, last 24h',
    source_cols=['hp_count_games_last_24_hours', 'ap_count_games_last_24_hours'],
    formula='leader_fat - loser_fat. >0 means the leader has played more.',
    backtest_expr="d.leader_fat - d.loser_fat", live_expr='same'),
 'att_vs_def': _l(tier='A_TICK', units='ratio',
    definition='trailer\'s attack divided by the leader\'s defensive record',
    source_cols=['hp_avggoals_scored_5', 'ap_avggoals_scored_5',
                 'hp_avggoals_conceded_5', 'ap_avggoals_conceded_5'],
    formula='loser_att / leader_def', backtest_expr="d.loser_att / d.leader_def",
    live_expr='same', nan_policy='leader_def zero or missing -> None -> FAILS CLOSED'),
 'tp': _l(tier='A_TICK', units='goals', definition='total goals scored so far by both sides',
    source_cols=['h_score', 'a_score'], formula='h_score + a_score',
    backtest_expr="d.h_score + d.a_score", live_expr='h + a',
    note='On the COMEBACK market tp >= 2 means the match demonstrably produces goals, so a '
         'one-goal deficit is more recoverable than the price implies -- the mirror of the '
         'unders logic, where a cold game stays cold.'),
}

V67_FEATURE_LINEAGE_FULL.update(V67_COMEBACK_LINEAGE)

