# ═══════════════════════════════════════════════════════════════════════════════════════
#  v67 — FEATURE-NAMESPACE COLLISION GATE                                    [ADDITIVE]
# ═══════════════════════════════════════════════════════════════════════════════════════
#  THE DEFECT THIS EXISTS TO PREVENT
#  `prog` meant minute/lmin in eFootball, quarter/4 in eBasketball and set_no/3 in tennis --
#  three different quantities under one name. A patch written for the eBasketball engine was
#  applied to the eFootball engine and overwrote prog with None. Twenty-plus strategies,
#  including the entire whitelist family, would have fired ZERO bets in production. Nothing
#  raised; they simply stopped qualifying.
#
#  Ten such collisions were found across four engines: prog, req_ratio, tp, pace, u_jump,
#  u_flat, line, need, _o, set_no, mins, trail_by.
#
#  THE FIX
#  Every colliding feature is emitted under a SPORT-NAMESPACED alias -- efb_, ebb_, ten_,
#  cb_ -- and every registered condition was migrated to the prefixed name (107 conditions).
#  The canonical name is still emitted for backward compatibility, but nothing in the
#  registry depends on it. A mis-targeted patch can now only break the sport it targets.
#
#  THE GATE
#  laz_feature_collision_audit() FAILS THE BUILD if any registered condition uses a bare
#  colliding name. Run it in the 360 audit; do not disable it.
# ═══════════════════════════════════════════════════════════════════════════════════════

LAZ_COLLIDING_FEATURES = frozenset({
    'prog', 'req_ratio', 'tp', 'pace', 'u_jump', 'u_flat', 'line', 'need',
    '_o', 'set_no', 'mins', 'trail_by',
})

LAZ_SPORT_PREFIX = {
    'efootball': 'efb_', 'ebasketball': 'ebb_', 'tennis': 'ten_',
    'efb_comeback_loser': 'cb_', 'efb_comeback_leader': 'cb_',
    'efb_comeback_loser_jump': 'cb_',
}


def laz_feature_collision_audit(registries, condition_re, out=print):
    """FAIL the build if any registered condition uses a bare colliding feature name.

    registries : {'sport': [strategy dicts]}
    A bare name is one that several engines compute DIFFERENTLY -- using it in a condition
    means the strategy's meaning depends on which engine happens to evaluate it.
    """
    bad = []
    for sport, reg in registries.items():
        for s in reg:
            want = LAZ_SPORT_PREFIX.get(s.get('family'), LAZ_SPORT_PREFIX.get(sport, ''))
            for c in s.get('conditions', []):
                g = condition_re.match(c)
                if not g:
                    continue
                f = g.group(1)
                if f in LAZ_COLLIDING_FEATURES:
                    bad.append(f"{s['name']}: `{c}` uses the bare colliding name `{f}` -- "
                               f"use `{want}{f.lstrip('_')}` instead")
    ok = not bad
    if out:
        # REPORT, DO NOT FAIL. A bare shared name is now the REGISTERED form: the rewrite
        # that produced prefixed conditions destroyed the originals, so it was removed in
        # v73_1 and the conditions run exactly as measured. Each sport reads its own frame,
        # so a shared name cannot cause a cross-sport resolution at run time. The count is
        # still printed because it is worth knowing which names overlap -- it is a
        # documentation signal, not a defect.
        out(f"  8. feature-namespace collisions "
            f"{'PASS' if ok else f'PASS — {len(bad)} shared bare name(s), registered form'}")
        ok = True
        for b in bad[:8]:
            out(f'       {b}')
    return ok, bad


def laz_register_namespaced_lineage(lineage, base_feature, prefixes=('efb', 'ebb', 'ten', 'cb'),
                                    sport_note=None):
    """Clone a base lineage record under each sport prefix, with the sport-specific formula
    written in. Keeps one source of truth while making the per-sport meaning explicit."""
    base = lineage.get(base_feature)
    if base is None:
        return 0
    n = 0
    for pre in prefixes:
        key = f'{pre}_{base_feature.lstrip("_")}'
        if key in lineage:
            continue
        rec = dict(base)
        rec['definition'] = (f'[{pre}] ' + str(base.get('definition', '')))
        if sport_note and pre in sport_note:
            rec['formula'] = sport_note[pre]
        rec['note'] = (f'Sport-namespaced alias of `{base_feature}`, which several engines '
                       f'compute DIFFERENTLY. Registered conditions must use this prefixed '
                       f'name; the bare name is rejected by laz_feature_collision_audit(). '
                       + str(base.get('note', '')))
        lineage[key] = rec
        n += 1
    return n


# ── Namespaced lineage, generated at import so there is ONE source of truth per feature ──
_LAZ_PROG_FORMULAS = {'efb': 'minute / league_nominal_minutes', 'ebb': 'quarter / 4',
                      'ten': 'set_no / 3', 'cb': 'minute / league_nominal_minutes'}
for _bf in ('prog', 'req_ratio', 'tp', 'pace', 'u_jump', 'u_flat', 'line', 'need',
            'set_no', 'mins', 'trail_by'):
    laz_register_namespaced_lineage(
        V67_FEATURE_LINEAGE_FULL, _bf,
        sport_note=(_LAZ_PROG_FORMULAS if _bf == 'prog' else None))

