for _qf, _qd in (
    ('ebb_q1_margin', dict(
        definition='the POINT MARGIN by which the Q1 winner took the first quarter, measured '
                   'at the LAST tick of Q1.',
        formula='abs(h_score - a_score) at the final tick of the 1st Quarter',
        backtest_expr="d[d.q==1].groupby('match_id').sd.last().abs()",
        live_expr='abs(S.q1_h - S.q1_a) latched when the phase leaves 1st Quarter',
        source_cols=['h_score', 'a_score', 'phase'],
        note='THE CARRIER OF THE EDGE. Monotone: 4+ gives +1.3, 6+ gives +5.4, 8+ gives +9.8.')),
    ('ebb_pre_o', dict(
        definition="the Q1 winner's PRE-MATCH price, latched at the first tick",
        formula='home_odds_open if home won Q1 else away_odds_open',
        backtest_expr="np.where(q1_winner=='home', ho_open, ao_open)",
        live_expr="S.ho_open if q1_winner == 'home' else S.ao_open",
        source_cols=['home_odds', 'away_odds', 'h_score', 'a_score', 'phase'],
        note='Mirrors the tennis s1w_pre <= 8.0 cap. Excludes rank outsiders, where a strong '
             'quarter is more likely variance than signal.')),
    ('ebb_q1_fav', dict(
        definition='1.0 if the Q1 winner was ALSO the pre-match favourite',
        formula='1.0 if q1_winner_open_price <= opponent_open_price',
        backtest_expr='(pre_o <= opponent_open).astype(float)',
        live_expr='1.0 if q1_winner_open <= opponent_open else 0.0',
        source_cols=['home_odds', 'away_odds', 'h_score', 'a_score', 'phase'],
        note='Setting this to 0 (the Q1 winner was NOT the favourite) isolates the upset: '
             '685 bets, IS 58.5% and OOS 51.7%, +10.3% ROI.')),
):
    V67_FEATURE_LINEAGE_FULL[_qf] = _l(
        tier='A_TICK', units='points' if _qf == 'ebb_q1_margin' else (
            'decimal odds' if _qf == 'ebb_pre_o' else 'flag'),
        nan_policy='Q1 not yet complete, or the quarter ended level -> None -> FAILS CLOSED',
        requires='ATTACHMENT AT THE FIRST TICK -- the Q1 result and the opening prices must '
                 'both be latched. A match joined in Q2 has neither.',
        window_semantics='anchor', **_qd)

