                      seg_is={'n': 109, 'wr': np.float64(58.7), 'roi': np.float64(26.0), 'ci': 4.6},
                      seg_oos={'n': 100, 'wr': np.float64(63.0), 'roi': np.float64(44.5), 'ci': 19.9},
