                      seg_is={'n': 107, 'wr': np.float64(57.0), 'roi': np.float64(21.2), 'ci': -1.1},
                      seg_oos={'n': 107, 'wr': np.float64(62.6), 'roi': np.float64(25.4), 'ci': 10.2},
