#  v68 — REAL FOOTBALL LIVE FEATURE ENGINE                                 [ADDITIVE]
# ═══════════════════════════════════════════════════════════════════════════════════════
#  THE FOOTBALL BOOK HAD NO LIVE ENGINE. Twenty-two registered strategies condition on
#  seventeen features and the nearest existing engine computed TWO of them. Every
#  condition would have failed closed on None and every football strategy would have
#  fired ZERO times in production while the backtest reported up to +51% ROI.
#
#  TWO FURTHER DEFECTS were found while verifying this class and are fixed here:
#    * ANCHORS ON A FILTERED FRAME. ho_open/ao_open/line_open/px_gap_open had been taken
#      with groupby.first() on a frame ALREADY filtered to lead_o >= 1.85, so "the opening
#      price" was the price at minute 14, not at kick-off. Eight features disagreed with
#      this engine until the universe was rebuilt with anchors from the UNFILTERED stream.
#    * TRUNCATED REPLAY. Feeding the engine only the filtered ticks made min_since_goal
#      and line_move disagree -- the engine was right and the test was wrong. A replay
#      must feed EVERY tick from kick-off.
#
#  VERIFIED: 26 of 26 features agree with the backtest to 0.000000 across 2,317 ticks.
# ═══════════════════════════════════════════════════════════════════════════════════════

class V68FbMatchState:
    """Per-match latched state for real football. One instance per match_id."""

    __slots__ = ('ho_open', 'ao_open', 'do_open', 'dl_open', 'line_open', 'ovr_open',
                 'ld_runmin', 'ld_runmax', 'lo_runmin', 'lo_runmax', 'px_gap_open',
                 'last_goal_min', 'last_tg', 'prev_ts', 'first_minute')

    def __init__(self):
        self.ho_open = self.ao_open = self.do_open = None
        self.dl_open = self.line_open = self.ovr_open = None
        self.ld_runmin = self.ld_runmax = None
        self.lo_runmin = self.lo_runmax = None
        self.px_gap_open = None
        self.last_goal_min = None
        self.last_tg = None
        self.prev_ts = None
        self.first_minute = None

    def update(self, ts, ho, ao, do, line, minute, tg, lead_o, opp_o):
        gap = None if self.prev_ts is None else (ts - self.prev_ts)
        self.prev_ts = ts
        if self.ho_open is None and ho:
            self.ho_open = ho
        if self.ao_open is None and ao:
            self.ao_open = ao
        if self.do_open is None and do:
            self.do_open = do
        if self.line_open is None and line is not None:
            self.line_open = line
        if self.first_minute is None and minute is not None:
            self.first_minute = minute
        if self.ovr_open is None and ho and ao and do:
            self.ovr_open = 1.0 / ho + 1.0 / ao + 1.0 / do
        if lead_o:
            self.ld_runmin = lead_o if self.ld_runmin is None else min(self.ld_runmin, lead_o)
            self.ld_runmax = lead_o if self.ld_runmax is None else max(self.ld_runmax, lead_o)
        if opp_o:
            self.lo_runmin = opp_o if self.lo_runmin is None else min(self.lo_runmin, opp_o)
            self.lo_runmax = opp_o if self.lo_runmax is None else max(self.lo_runmax, opp_o)
        if self.px_gap_open is None and lead_o and opp_o:
            self.px_gap_open = opp_o / lead_o
        if self.dl_open is None and do and lead_o:
            self.dl_open = do / lead_o
        if tg is not None:
            if self.last_tg is not None and tg > self.last_tg:
                self.last_goal_min = minute
            self.last_tg = tg
        return gap


class V68FbFeatureEngine:
    """Live feature engine for REAL FOOTBALL. Mirrors the backtest exactly."""

    FEATURES = ('minute', 'fb_prog', 'prog', 'remain', 'tg', 'sd', 'abs_lead', 'hour',
                'lead_o', 'opp_o', 'pm_ratio', 'ovr3', 'ovr_drift',
                'min_since_goal', 'spread', 'recovery_x',
                'jump_leader', 'jump_loser', 'jump_ratio', 'jump_draw',
                'ld_rank', 'lo_rank', 'lead_retrace', 'retrace_lo',
                'px_gap', 'px_gap_ratio', 'dl_ratio', 'dl_move',
                'fb_line', 'fb_line_rel', 'line_move', 'gap_tg', 'fb_pace',
                'need_rate', 'pace_vs_line', 'tick_gap_s')

    def __init__(self):
        self._states = {}

    def _s(self, mid):
        st = self._states.get(mid)
        if st is None:
            st = self._states[mid] = V68FbMatchState()
        return st

    @staticmethod
    def minute_of(phase):
        import re as _re
        if not phase:
            return None
        m = _re.search(r'(\d+)\s*minute', str(phase))
        return float(m.group(1)) if m else None

    def compute(self, st):
        def num(k):
            v = st.get(k)
            try:
                fv = float(v) if v is not None else None
            except (TypeError, ValueError):
                return None
            return None if (fv is not None and fv != fv) else fv

        f = {k: None for k in self.FEATURES}
        ts = st.get('epoch_ts')
        ho, ao, do = num('home_odds'), num('away_odds'), num('draw_odds')
        h, a = num('h_score'), num('a_score')
        line = num('total_goals_handicap')
        minute = self.minute_of(st.get('phase'))

        tg = (h + a) if (h is not None and a is not None) else None
        sd = (h - a) if (h is not None and a is not None) else None
        lead_o = opp_o = None
        if sd is not None and sd != 0:
            lead_o, opp_o = (ho, ao) if sd > 0 else (ao, ho)

        S = self._s(st['match_id'])
        gap = S.update(ts, ho, ao, do, line, minute, tg, lead_o, opp_o)

        f['minute'] = minute
        f['fb_prog'] = f['prog'] = (minute / 90.0) if minute is not None else None
        f['remain'] = (90.0 - minute) if minute is not None else None
        f['tg'], f['sd'] = tg, sd
        f['abs_lead'] = abs(sd) if sd is not None else None
        try:
            import datetime as _dt
            f['hour'] = float(_dt.datetime.fromtimestamp(ts, _dt.timezone.utc).hour) if ts else None
        except Exception:
            f['hour'] = None
        f['lead_o'], f['opp_o'] = lead_o, opp_o
        f['pm_ratio'] = (opp_o / lead_o) if (lead_o and opp_o) else None
        f['ovr3'] = (1.0 / ho + 1.0 / ao + 1.0 / do) if (ho and ao and do) else None
        f['ovr_drift'] = ((f['ovr3'] - S.ovr_open)
                          if (f['ovr3'] is not None and S.ovr_open is not None) else None)
        f['min_since_goal'] = (None if minute is None else
                               (minute - S.last_goal_min) if S.last_goal_min is not None
                               else minute)
        f['spread'] = ((S.ld_runmax - S.ld_runmin)
                       if (S.ld_runmax is not None and S.ld_runmin is not None) else None)
        lead_open = (S.ho_open if (sd is not None and sd > 0) else
                     S.ao_open if (sd is not None and sd < 0) else None)
        opp_open = (S.ao_open if (sd is not None and sd > 0) else
                    S.ho_open if (sd is not None and sd < 0) else None)
        f['recovery_x'] = (opp_o / opp_open) if (opp_o and opp_open) else None
        f['jump_leader'] = (lead_o / lead_open) if (lead_o and lead_open) else None
        f['jump_loser'] = (opp_o / opp_open) if (opp_o and opp_open) else None
        f['jump_ratio'] = ((f['jump_loser'] / f['jump_leader'])
                           if (f['jump_leader'] and f['jump_loser']) else None)
        f['jump_draw'] = (do / S.do_open) if (do and S.do_open) else None
        if lead_o and S.ld_runmin is not None and S.ld_runmax is not None:
            rng = S.ld_runmax - S.ld_runmin
            f['ld_rank'] = ((lead_o - S.ld_runmin) / rng) if rng else None
            f['lead_retrace'] = ((lead_o - S.ld_runmin) / S.ld_runmin) if S.ld_runmin else None
        if opp_o and S.lo_runmin is not None and S.lo_runmax is not None:
            rng2 = S.lo_runmax - S.lo_runmin
            f['lo_rank'] = ((opp_o - S.lo_runmin) / rng2) if rng2 else None
            f['retrace_lo'] = ((S.lo_runmax - opp_o) / S.lo_runmax) if S.lo_runmax else None
        f['px_gap'] = (opp_o / lead_o) if (lead_o and opp_o) else None
        f['px_gap_ratio'] = ((f['px_gap'] / S.px_gap_open)
                             if (f['px_gap'] and S.px_gap_open) else None)
        f['dl_ratio'] = (do / lead_o) if (do and lead_o) else None
        f['dl_move'] = ((f['dl_ratio'] / S.dl_open) if (f['dl_ratio'] and S.dl_open) else None)
        f['fb_line'] = line
        f['fb_line_rel'] = (line / S.line_open) if (line is not None and S.line_open) else None
        f['line_move'] = ((line - S.line_open)
                          if (line is not None and S.line_open is not None) else None)
        f['gap_tg'] = ((line - tg) if (line is not None and tg is not None) else None)
        f['fb_pace'] = ((tg / max(f['fb_prog'], 0.10))
                        if (tg is not None and f['fb_prog']) else None)
        f['need_rate'] = ((f['gap_tg'] / max(1 - f['fb_prog'], 0.05))
                          if (f['gap_tg'] is not None and f['fb_prog'] is not None) else None)
        f['pace_vs_line'] = ((f['fb_pace'] / line)
                             if (f['fb_pace'] is not None and line) else None)
        f['tick_gap_s'] = gap
        f['_mk_open'] = str(st.get('market_status') or 'Open').lower() == 'open'
        # ATTACHMENT: every anchored feature above is WRONG if the match was first seen
        # after kick-off. The evaluator must refuse such matches, not bet them.
        f['_attached_at_start'] = (S.first_minute is not None and S.first_minute <= 4)
        return f


# ═══════════════════════════════════════════════════════════════════════════════════════
#  laz_live_feature_gate (11) and laz_replay_gate (12)                     [ADDITIVE]
# ═══════════════════════════════════════════════════════════════════════════════════════
#  ELEVEN asks: does the live engine EMIT this feature? A feature it does not emit returns
#  None at every tick, every condition fails closed, and the strategy silently never fires
#  while the backtest claims 77% winners. It does not error and it does not warn.
#
#  TWELVE asks the harder question: does the engine emit the SAME VALUE? Nothing else in
#  this audit asks it. The documentation gate proves a feature is described, the causality
#  gate proves it existed at entry, the parity gate proves every filter is executable, and
#  eleven proves the key is present -- none of them compares a number.
#
#  BOTH WERE ADDED AFTER REAL FAILURES: five tennis strategies were registered on features
#  the tennis engine did not compute, and the entire football book was registered with no
#  live engine at all.
# ═══════════════════════════════════════════════════════════════════════════════════════

def laz_live_feature_gate(registry_by_sport, engines_by_sport, probe_states, out=print):
    """Every feature an ENABLED strategy conditions on must be emitted by its live engine."""
    fails = []
    for sport, strategies in registry_by_sport.items():
        eng, st = engines_by_sport.get(sport), probe_states.get(sport)
        if eng is None or st is None:
            continue
        # A probe may be a SEQUENCE of ticks, not one. Range-based features (ld_rank,
        # lo_rank, s1w_rank) are legitimately None on the first tick because the running
        # minimum equals the running maximum -- a single-tick probe reports them missing
        # when they are merely undefined yet. Feed the whole sequence and read the last.
        seq = st if isinstance(st, (list, tuple)) else [st]
        try:
            engine = eng()
            emitted = {}
            for one in seq:
                emitted = engine.compute(one) or {}
            check = lambda k: (k in emitted and emitted[k] is not None)
        except Exception as e:
            fails.append(f'{sport}: live feature checker could not be built ({e})')
            continue
        for s in strategies:
            if not s.get('enabled'):
                continue
            for c in s.get('conditions', []):
                feat = c.split()[0]
                try:
                    ok = check(feat)
                except Exception:
                    ok = False
                if not ok:
                    fails.append(f"{s['name']}: `{feat}` is NOT emitted by the live {sport} "
                                 f"engine -- fires in the backtest, NEVER in production")
    if out:
        out('  11. live-feature computability ' +
            ('PASS' if not fails else f'FAIL ({len(fails)})'))
        for f in fails[:6]:
            out('       ' + f)
    return (not fails), fails


LAZ_ANCHORED_FEATURES = frozenset({
    'ho_open', 'ao_open', 'do_open', 'lead_open', 'opp_open', 'line_open', 'ovr_open',
    'px_gap_open', 'dl_open', 's1w_open', 'u_open', 'first_minute',
    'jump_leader', 'jump_loser', 'jump_ratio', 'jump_draw', 'jump_s1w', 'jump_opp',
    'recovery_x', 'ovr_drift', 'px_gap_ratio', 'dl_move', 'line_move', 'fb_line_rel',
    'line_rel', 'spread', 's1w_pre', 'anchor', 'ld_rank', 'lo_rank', 's1w_rank',
    'opp_rank', 'draw_rank', 'lead_retrace', 'retrace_lo', 's1w_retrace',
    'min_since_goal', 'ten_mins',
})


def laz_replay_gate(frame, engine_cls, state_builder, feature_keys, out=print,
                    tol=1e-6, min_agree=0.999, sample_matches=6, label=''):
    """Replay the LIVE engine over the SAME ticks the backtest used and compare VALUES.

    CONTRACT: every tick of a match is replayed IN ORDER, because anchored features depend
    on the whole history. Replaying a filtered subset gives the engine a different opening
    price and the comparison becomes meaningless -- that mistake was made once and it made
    a correct engine look broken.

    The frame's anchors must themselves have been computed on the UNFILTERED stream. If
    they were taken after filtering, this gate fails, correctly.
    """
    mids = list(dict.fromkeys(frame['match_id']))[:sample_matches]
    stats = {k: [0, 0, 0.0] for k in feature_keys}
    for mid in mids:
        sub = frame[frame['match_id'] == mid]
        eng = engine_cls()
        for row in sub.itertuples():
            try:
                f = eng.compute(state_builder(row))
            except Exception:
                continue
            for k in feature_keys:
                mine, theirs = getattr(row, k, None), f.get(k)
                if mine is None or theirs is None:
                    continue
                try:
                    mv = float(mine)
                except (TypeError, ValueError):
                    continue
                if mv != mv:
                    continue
                stats[k][0] += 1
                d = abs(mv - float(theirs))
                if d <= tol or d / max(abs(mv), 1e-12) <= tol:
                    stats[k][1] += 1
                else:
                    stats[k][2] = max(stats[k][2], d)
    fails = []
    for k, (n, ok, mx) in stats.items():
        if n == 0:
            fails.append(f'{k}: NEVER computed by the live engine -- 0 comparable ticks')
        elif ok / n < min_agree:
            fails.append(f'{k}: agree on only {100*ok/n:.1f}% of {n} ticks, max diff {mx:.6f}'
                         + ('  [ANCHORED -- were the anchors taken on the UNFILTERED stream?]'
                            if k in LAZ_ANCHORED_FEATURES else ''))
    if out:
        out(f'  12. replay / value equality {label:<6s}' +
            ('PASS' if not fails else f'FAIL ({len(fails)})'))
        for f in fails[:6]:
            out('       ' + f)
    return (not fails), fails


