laz_owner__ALIASES = {'efbig': 'efootball', 'ef': 'efootball', 'eff': 'efootball', 'tt': 'tabletennis', 'etennis': 'etennis'}

def laz_owner__canon(sport):
    """One spelling per sport. `efbig` is the frame filename and `efootball`
    is the registry key; hunt() translated between them internally and nothing
    else did, so prepare('efbig') raised FrameMissing with path None."""
    s = str(sport).lower()
    return laz_owner__ALIASES.get(s, s)

def laz_owner__frame_path(sport):
    """The assigned parquet for a sport."""
    f = laz_owner__LAZ_OWNER['frames'].get(laz_owner__canon(sport))
    if not f:
        return None
    return os.path.join(laz_owner__LAZ_OWNER['paths']['parquet_dir'], f['parquet'])

def laz_owner__frame_exists(sport):
    p = laz_owner__frame_path(sport)
    return bool(p and os.path.exists(p))

def laz_owner__resolve_frame(sport, allow_rebuild=True, log=print):
    """USE THE ASSIGNED PARQUET IF IT EXISTS. Only rebuild when it does not.

    The rebuild scripts (csv_football.py and siblings) exist to CREATE a
    missing parquet, not to run alongside one. Returning early here is what
    makes that true rather than assumed.
    """
    sport = laz_owner__canon(sport)
    p = laz_owner__frame_path(sport)
    spec = laz_owner__LAZ_OWNER['frames'].get(laz_owner__canon(sport))
    if p and os.path.exists(p):
        log(f'  [frame] {sport}: using assigned parquet {p} (rebuild SKIPPED)')
        return (p, 'assigned')
    if not allow_rebuild or not spec:
        log(f'  [frame] {sport}: NO PARQUET at {p} and rebuild not permitted')
        return (None, 'missing')
    log(f'  [frame] {sport}: parquet absent -> rebuild via {spec['rebuild_script']}')
    return (p, 'needs_rebuild')

def laz_owner__source_table(sport):
    s = laz_owner__LAZ_OWNER['frames'].get(laz_owner__canon(sport))
    return s['source_table'] if s else None

def laz_owner__rule(name, default=None):
    return laz_owner__LAZ_OWNER['rules'].get(name, default)

def laz_owner__min_odds_for_mode(mode, override=None):
    """Mode 3 overrides the floor; everything else uses it."""
    m = laz_owner__LAZ_OWNER['modes'].get(mode, {})
    if override is not None:
        return float(override)
    if m.get('override_min_odds'):
        return laz_owner__LAZ_OWNER['rules']['min_odds_hard']
    return laz_owner__LAZ_OWNER['rules']['min_odds']

def laz_owner__summary():
    return dict(frames=len(laz_owner__LAZ_OWNER['frames']), modes=len(laz_owner__LAZ_OWNER['modes']), families=len(laz_owner__LAZ_OWNER['families']), source_tables=list(laz_owner__LAZ_OWNER['source_tables']), min_odds=laz_owner__LAZ_OWNER['rules']['min_odds'], min_odds_hard=laz_owner__LAZ_OWNER['rules']['min_odds_hard'])

