# ==========================================================================
# LAZ_BRAIN MODULE: laz_log
# §laz_log   <- grep this anchor to land here
# ==========================================================================
"""laz_log.py — THE LOG IS THE ONLY DIAGNOSTIC.

Every line carries a wall-clock stamp, elapsed since the run began, and a
stage tag:

    [14:22:07.481] [+03:12] [mode3.bases]  15 registry bases · 48 specs

WHY THIS EXISTS

The operator runs on their own machine and pastes the log back. A defect that
is not visible in the log costs a full round trip. Three modules this session
ran for hours doing nothing — the tick scanner in Mode 3 (wrong signature),
the causality guard in the embed (stripped import swallowed by a bare except),
laz_specs.arm() (never called) — and each was invisible because nothing logged
a count or an exception.

So: a COUNT at every stage, and every `except` reports its type and message.
`guard()` exists to make that the easy path rather than the disciplined one.
"""
import os, sys, time, traceback
from datetime import datetime
laz_log___T0 = time.time()
laz_log___STAGE = []
laz_log___COUNTS = {}
laz_log___SINK = []

def laz_log__reset(t0=None):
    global _T0, _COUNTS, _SINK, _SWALLOWED
    laz_log___T0 = t0 or time.time()
    laz_log___COUNTS = {}
    laz_log___SINK = []
    laz_log___SWALLOWED = []

def laz_log__elapsed():
    return time.time() - laz_log___T0

def laz_log___fmt_elapsed():
    e = int(laz_log__elapsed())
    return f'{e // 60:02d}:{e % 60:02d}'

def laz_log__rss_mb():
    """Current resident set in MB, correct on Linux AND macOS.

    /proc/self/statm does not exist on macOS, so the fallback ran — and
    ru_maxrss is BYTES on Darwin but KILOBYTES on Linux. Dividing by 1024
    either way reported 2,292,528 MB on a machine with 32 GB. A number that
    absurd is easy to dismiss, which is exactly why it must be right: nobody
    reads a memory figure they have learned to ignore.
    """
    try:
        with open('/proc/self/statm') as _sm:
            return int(_sm.read().split()[1]) * 4096 / 1000000.0
    except Exception:
        pass
    try:
        import resource, sys as _s
        r = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        return r / 1000000.0 if _s.platform == 'darwin' else r / 1024.0
    except Exception:
        return float('nan')

def laz_log__line(msg, stg=None, n=None, **kv):
    st = stg or ('.'.join(laz_log___STAGE) if laz_log___STAGE else 'run')
    now = datetime.now().strftime('%H:%M:%S.') + f'{int(time.time() % 1 * 1000):03d}'
    extra = ''
    if n is not None:
        extra += f' · n={n:,}' if isinstance(n, int) else f' · n={n}'
    if kv:
        extra += ' · ' + ' · '.join((f'{k}={v}' for k, v in kv.items()))
    s = f'[{now}] [+{laz_log___fmt_elapsed()}] [{st}] {msg}{extra}'
    print(s, flush=True)
    laz_log___SINK.append(s)
    return s

def laz_log__count(key, value, stg=None):
    """Record a stage count so the run can be summarised at the end."""
    laz_log___COUNTS[key] = value
    return laz_log__line(f'{key}', stg=stg, n=value)

def laz_log__stage(name):

    class _S:

        def __enter__(s):
            laz_log___STAGE.append(name)
            s.t = time.time()
            laz_log__line('START', stg='.'.join(laz_log___STAGE))
            return s

        def __exit__(s, et, ev, tb):
            dt = time.time() - s.t
            if et is not None:
                laz_log__line(f'FAILED {et.__name__}: {str(ev)[:160]}', stg='.'.join(laz_log___STAGE))
                for ln in traceback.format_exception(et, ev, tb)[-3:]:
                    laz_log__line('  ' + ln.strip()[:160], stg='.'.join(laz_log___STAGE))
            else:
                laz_log__line(f'DONE in {dt:.1f}s · rss {laz_log__rss_mb():.0f} MB', stg='.'.join(laz_log___STAGE))
            laz_log___STAGE.pop()
            return False
    return _S()

def laz_log__guard(what, fn, *a, default=None, stg=None, **kw):
    """Run fn, and if it raises, LOG THE TYPE AND MESSAGE and return default.

    Never a bare except. A swallowed exception is why the tick scanner sat
    dead for three sessions.
    """
    try:
        return fn(*a, **kw)
    except Exception as e:
        _rec = dict(what=what, exc=type(e).__name__, msg=str(e)[:150], stg=stg)
        tb = traceback.format_exc().strip().splitlines()
        if len(tb) >= 2:
            _rec['at'] = tb[-2].strip()[:140]
        _sym = None
        if isinstance(e, NameError):
            import re as _re
            _mm = _re.search("name '(\\w+)'", str(e))
            _sym = _mm.group(1) if _mm else None
        _rec['benign'] = bool(_sym and _sym in laz_log__BENIGN_SYMBOLS)
        laz_log___SWALLOWED.append(_rec)
        laz_log__line(f'{what}: {type(e).__name__}: {str(e)[:150]}' + (' (benign — named)' if _rec['benign'] else ''), stg=stg)
        if 'at' in _rec:
            laz_log__line(f'  at {_rec['at']}', stg=stg)
        return default
laz_log__BENIGN_SYMBOLS = set()
laz_log___SWALLOWED = []

def laz_log__swallowed():
    return list(laz_log___SWALLOWED)

def laz_log__sink_report():
    """Every exception a guard swallowed this run, real ones first."""
    if not laz_log___SWALLOWED:
        laz_log__line('sink: no swallowed exceptions this run', stg='sink')
        return
    real = [r for r in laz_log___SWALLOWED if not r.get('benign')]
    ben = [r for r in laz_log___SWALLOWED if r.get('benign')]
    laz_log__line(f'sink: {len(laz_log___SWALLOWED)} swallowed · {len(real)} real · {len(ben)} named-benign', stg='sink')
    for r in real[:20]:
        laz_log__line(f'  {r['exc']} in {r['what']}: {r['msg'][:80]}' + (f'  @ {r['at'][:60]}' if r.get('at') else ''), stg='sink')

def laz_log__summary(title='RUN SUMMARY'):
    laz_log__line('=' * 60, stg='summary')
    laz_log__line(title, stg='summary')
    for k, v in laz_log___COUNTS.items():
        laz_log__line(f'  {k:44s} {v:,}' if isinstance(v, int) else f'  {k:44s} {v}', stg='summary')
    laz_log__line(f'  {'total elapsed':44s} {laz_log___fmt_elapsed()}', stg='summary')
    laz_log__line(f'  {'peak rss (MB)':44s} {laz_log__rss_mb():.0f}', stg='summary')
    laz_log__line('=' * 60, stg='summary')

def laz_log__dump(path):
    try:
        with open(path, 'w') as f:
            f.write('\n'.join(laz_log___SINK) + '\n')
        return path
    except Exception as e:
        laz_log__line(f'dump failed: {type(e).__name__}: {e}')
        return None
