# LAZ_BRAIN MODULE: laz_frames
# §laz_frames   <- grep this anchor to land here
# OBJECTIVE : ONE WAY TO OPEN A FRAME
# PURPOSE   : load(sport) is the only entry point. Uses the ASSIGNED parquet and SKIPS the csv_* rebuild entirely when it exists; raises rather than falling back silently.
# HOW       : Resolves via LAZ_OWNER, applies the causality guard to the column list BEFORE reading so a denied term is never loaded, returns the frame with its lineage attached.
# VALUE     : Replaced 28 hardcoded paths across 6 runners. A path change is now one edit, and a runner cannot open a different file from the one the owner assigned.
# IF SKIPPED: A runner silently reads the wrong frame, or a rebuild runs alongside an existing parquet.
# ==========================================================================
"""laz_frames.py — ROUND 2: ONE WAY TO OPEN A FRAME.

Every runner was resolving its own path — `frames/AB_football.parquet` written
into the code in a dozen places. That means a path change needs a dozen edits,
and a runner can silently open a different file from the one the owner assigned.

load(sport) is now the ONLY entry point. It:
  · resolves the ASSIGNED parquet from LAZ_OWNER, skipping the csv_* rebuild
    entirely when the file exists
  · raises if the file is absent and rebuild is not permitted, rather than
    quietly falling back
  · applies the causality guard to the column list BEFORE reading
  · returns the frame together with its LINEAGE — source table, parquet, sport,
    elapsed column — so every strategy documented downstream inherits it
"""
import os, gc
import numpy as np, pandas as pd, pyarrow.parquet as pq

class laz_frames__FrameMissing(Exception):
    pass

def laz_frames___owner():
    return _m('laz_owner')

def laz_frames__lineage(sport):
    _OW = laz_frames___owner()
    sport = _OW.canon(sport) if hasattr(_OW, 'canon') else sport
    'The provenance record attached to everything built from this frame.'
    OW = laz_frames___owner()
    spec = OW.LAZ_OWNER['frames'].get(sport)
    if not spec:
        return {}
    tbl = spec['source_table']
    st = {k: v for k, v in OW.LAZ_OWNER['source_tables'].items() if v['db_table'] == tbl}
    return dict(sport=sport, parquet=OW.frame_path(sport), source_table=tbl, source_table_key=list(st)[0] if st else None, elapsed_col=spec.get('elapsed_col'), days=spec.get('days'), note=list(st.values())[0]['note'] if st else '')

def laz_frames__columns_for(sport, entry=1.01):
    """Causality-guarded column list. A denied term is never read at all."""
    OW = laz_frames___owner()
    p = OW.frame_path(sport)
    if not p or not os.path.exists(p):
        raise laz_frames__FrameMissing(f'{sport}: {p}')
    names = set(pq.ParquetFile(p).schema_arrow.names)
    _CG = _m('causality_guard')
    if _CG is None:
        raise laz_frames__FrameMissing('causality_guard unreachable — refusing to read columns unguarded')
    cert = _CG._certified(sport)
    # [AmunEV V2.25] THE 155-SECOND FIRST LOAD, named by the load timings: classifying the frame's columns at the pool door
    # (check_term per column) — 0.0 s on every later call in the process, 155 s in every new process. The verdict for a column
    # name is a function of the name, the sport, the entry price and the guard's tables, not of the data: it is remembered in
    # laz_memory_columns_<sport>.json keyed by exactly those, and a new process reuses it. Any change to the guard tables or
    # the frame's columns changes the key and re-classifies.
    import hashlib as _hcf, json as _jcf
    _key = _hcf.sha256(('|'.join(sorted(names)) + '#' + str(entry) + '#' + str(sport) + '#' + '|'.join(sorted(map(str, cert))) + '#' + str(globals().get('LAZ_ENGINE_VERSION', '')) + '#' + str(len(getattr(_CG, 'PRODUCTION_TERMS', ()) or ())) + '#' + str(len(getattr(_CG, 'STATE_SCOPED', {}) or {}))).encode()).hexdigest()[:16]
    _OWc = laz_frames___owner(); _memp = os.path.join(((_OWc.LAZ_OWNER.get('paths', {}) or {}).get('output_dir') if _OWc else None) or os.getcwd(), f'laz_memory_columns_{sport}.json')
    feat = None
    try:
        if os.path.exists(_memp):
            with open(_memp) as _mf:
                _rec = _jcf.load(_mf)
            if _rec.get('key') == _key and isinstance(_rec.get('feat'), list):
                feat = [c for c in _rec['feat'] if c in names]
    except Exception:
        feat = None
    if feat is None:
        feat = [c for c in names if _CG.check_term(c, sport, entry, cert)[0]]
        try:
            with open(_memp, 'w') as _mf:
                _jcf.dump(dict(key=_key, sport=str(sport), feat=sorted(feat), n_columns=len(names)), _mf)
        except Exception:
            pass
    spec = OW.LAZ_OWNER['frames'][sport]
    core = ['match_id', 'ts', 'timestamp', 'h_score', 'a_score', 'home_odds', 'away_odds', 'draw_odds', 'final_result', 'final_winner', 'tg', 'minute', 'Minute_FGS', 'first_goal_prog', 'open_line', 'pm_fav', 'sets', 'set1_winner', 'map2_winner', 'q1_h', 'q1_a', 'h1_h', 'h1_a']   # [v246-MAP]
    if spec.get('elapsed_col'):
        core.append(spec['elapsed_col'])
    return ([c for c in dict.fromkeys(core + feat) if c in names], feat)

# ── [v187 C1] laz_cleanse — abrupt endings that leave the final score open are REMOVED at the door ──
laz_cleanse__DECIDED_MARGIN = {'football': 3, 'efootball': 3, 'efbig': 3, 'basketball': 20, 'ebasketball': 20,
                               'tennis': 2, 'etennis': 2, 'tabletennis': 2, 'esports': 2}
laz_cleanse__EARLY_FRAC = 0.85       # a clocked match whose last tick is before 85% of nominal length ended early
laz_cleanse__EARLY_TICKS = 0.40      # a clockless match with fewer than 40% of the sport's median ticks ended early
laz_cleanse__CLOCKED = ('football', 'efootball', 'efbig', 'ebasketball')   # only these carry a match clock (prog/minute); set/point sports use the tick proxy

def laz_cleanse__apply(d, sport, log=None, write_report=True):
    """THE RULE (implementable in SQL, see DATA_CLEANSE.md written by --docs):
      1. COMPLETE   — the last tick is at or past 85% of nominal length (clocked sports: prog/minute), or the
                      match carries at least 40% of the sport's median tick count (clockless): KEEP.
      2. DECIDED    — ended early, but the score margin at the last tick is >= the sport's decided margin
                      (3 goals, 20 points, 2 sets): the bookmaker closed a decided market; the result is the
                      last-tick leader: KEEP.
      3. AMBIGUOUS  — ended early with a margin below the decided margin: the scrape stopped, the final
                      score cannot be inferred: REMOVE.
      4. INCONSISTENT — a recorded final_winner that contradicts the last-tick leader of an early-ended
                      match: REMOVE.
    market_status at the last tick is REPORTED, not used to decide: a closed market with a level score
    says nothing about the result. LAZ_CLEANSE=0 disables; LAZ_CLEANSE_MARGIN_<SPORT> overrides the margin."""
    import os as _os
    if _os.environ.get('LAZ_CLEANSE', '1') == '0' or 'match_id' not in d.columns:
        return (d, None)
    sp = str(sport).lower()
    margin = float(_os.environ.get(f'LAZ_CLEANSE_MARGIN_{sp.upper()}') or laz_cleanse__DECIDED_MARGIN.get(sp, 3))
    g = d.groupby('match_id', sort=False)
    last = g.tail(1).set_index('match_id')
    n_ticks = g.size()
    hs = pd.to_numeric(last.get('h_score', pd.Series(np.nan, index=last.index)), errors='coerce')
    as_ = pd.to_numeric(last.get('a_score', pd.Series(np.nan, index=last.index)), errors='coerce')
    lead = hs - as_
    # ended early?
    if sp in laz_cleanse__CLOCKED and 'prog' in last.columns and pd.to_numeric(last['prog'], errors='coerce').notna().mean() > 0.5:
        early = pd.to_numeric(last['prog'], errors='coerce') < laz_cleanse__EARLY_FRAC
        how = 'prog < 0.85'
    elif sp in laz_cleanse__CLOCKED and 'minute' in last.columns and pd.to_numeric(last['minute'], errors='coerce').notna().mean() > 0.5:
        nominal = float(np.nanpercentile(pd.to_numeric(last['minute'], errors='coerce'), 95)) or 90.0
        early = pd.to_numeric(last['minute'], errors='coerce') < laz_cleanse__EARLY_FRAC * nominal
        how = f'minute < 0.85 x {nominal:.0f}'
    else:
        med = float(n_ticks.median()) if len(n_ticks) else 0.0
        early = (n_ticks.reindex(last.index) < laz_cleanse__EARLY_TICKS * med)
        how = f'ticks < 0.40 x median {med:.0f}'
    early = early.fillna(False).astype(bool)
    decided = early & (lead.abs() >= margin)
    ambiguous = early & ~(lead.abs() >= margin)
    if sp not in laz_cleanse__CLOCKED:
        # set/point sports: the tick proxy alone is too blunt to call a short match 'cut off' — require BOTH a short
        # tick count (< 40% of median) AND fewer than 20% of the median, i.e. clearly truncated, before removing
        _very_short = (n_ticks.reindex(last.index) < 0.20 * float(n_ticks.median())).fillna(False)
        ambiguous = ambiguous & _very_short
        decided = early & ~ambiguous
    inconsistent = pd.Series(False, index=last.index)
    if 'final_winner' in last.columns:
        fw = last['final_winner'].astype(str).str.lower()
        leader = np.where(lead > 0, 'home', np.where(lead < 0, 'away', 'draw'))
        inconsistent = early & fw.isin(['home', 'away']) & (fw.values != leader) & lead.notna()
    remove = ambiguous | inconsistent
    status = last['market_status'].astype(str).str.lower() if 'market_status' in last.columns else pd.Series('n/a', index=last.index)
    rep = dict(sport=sp, matches=int(len(last)), complete=int((~early).sum()), early=int(early.sum()), decided_kept=int((decided & ~inconsistent).sum()),
               ambiguous_removed=int(ambiguous.sum()), inconsistent_removed=int((inconsistent & ~ambiguous).sum()), removed=int(remove.sum()), margin=margin, early_rule=how,
               early_open_market=int((early & status.isin(['open', 'active', 'in_play', 'true', '1'])).sum()))
    if log is not None:
        log(f"[cleanse] {sp}: {rep['matches']:,} matches · complete {rep['complete']:,} · ended early {rep['early']:,} ({how}) · DECIDED kept {rep['decided_kept']:,} (margin >= {margin:g}) · AMBIGUOUS removed {rep['ambiguous_removed']:,} · INCONSISTENT removed {rep['inconsistent_removed']:,} · market still open at the last tick on {rep['early_open_market']:,} of the early ones")
    if write_report and remove.any():
        try:
            out = pd.DataFrame(dict(match_id=last.index[remove.values], reason=np.where(inconsistent[remove], 'inconsistent_winner', 'ambiguous_early_end'),
                                    ticks=n_ticks.reindex(last.index)[remove].values, last_margin=lead[remove].values, last_status=status[remove].values))
            out.to_csv(f'{sp}_cleanse_removed.csv', index=False)
            if log is not None:
                log(f"[cleanse]   removed match_ids -> {sp}_cleanse_removed.csv (batch-delete list for the warehouse)")
        except Exception as _e:
            if log is not None:
                log(f'[cleanse]   could not write the removed list: {type(_e).__name__}')
    keep_ids = last.index[~remove.values]
    return (d[d['match_id'].isin(keep_ids)], rep)

def laz_cleanse__status_era(d, sport, log=None, write_report=True):
    """[v187 E1] market_status exists only from the moment the scraper started tracking it (ebasketball: July
    2026). LAZ_STATUS_ERA=tracked (default) keeps the matches whose rows carry a status; the untracked era is
    written to <sport>_pre_status_era.csv for a later evaluation. LAZ_STATUS_ERA=all keeps everything."""
    import os as _os
    if _os.environ.get('LAZ_STATUS_ERA', 'tracked') != 'tracked' or 'market_status' not in d.columns or 'match_id' not in d.columns:
        return (d, None)
    share = d.groupby('match_id', sort=False)['market_status'].apply(lambda x: float(x.notna().mean()))
    if share.max() == 0 or share.min() > 0.5:          # nothing tracked, or everything tracked: nothing to split
        return (d, None)
    keep = share[share >= 0.5].index; drop = share[share < 0.5].index
    first = pd.to_datetime(d.groupby('match_id', sort=False)['ts'].min()) if 'ts' in d.columns else None
    rep = dict(kept=int(len(keep)), dropped=int(len(drop)), tracked_from=str(first.reindex(keep).min())[:10] if first is not None else '?', untracked_until=str(first.reindex(drop).max())[:10] if first is not None else '?')
    if log is not None:
        log(f"[cleanse] {sport}: STATUS ERA — market_status tracked from {rep['tracked_from']}: {rep['kept']:,} matches KEPT · {rep['dropped']:,} untracked matches (until {rep['untracked_until']}) set aside (LAZ_STATUS_ERA=all to keep them)")
    if write_report and len(drop):
        try:
            pd.DataFrame(dict(match_id=drop, first_ts=first.reindex(drop).values if first is not None else None)).to_csv(f'{sport}_pre_status_era.csv', index=False)
        except Exception:
            pass
    return (d[d['match_id'].isin(keep)], rep)

def laz_slice__apply(d, sport, log=None):
    """[v187 C2] THE 1-CORE METHODOLOGY. LAZ_SLICE_DAYS=N keeps one contiguous window of N days holding
    at least LAZ_SLICE_MIN_MATCHES whole matches (default 300; seed LAZ_SLICE_SEED), so every stage from
    A to Z runs on a sample that is large enough to conclude and small enough to run in minutes."""
    import os as _os
    days = _os.environ.get('LAZ_SLICE_DAYS')
    if not days or 'match_id' not in d.columns or 'ts' not in d.columns:
        return (d, None)
    days = float(days); need = int(_os.environ.get('LAZ_SLICE_MIN_MATCHES', '300')); seed = int(_os.environ.get('LAZ_SLICE_SEED', '0'))
    first = pd.to_datetime(d.groupby('match_id', sort=False)['ts'].min())
    if len(first) <= need:
        if log is not None:
            log(f'[slice] {sport}: only {len(first):,} matches — no slice taken')
        return (d, None)
    t0, t1 = first.min(), first.max() - pd.Timedelta(days=days)
    rng = np.random.default_rng(seed)
    for _ in range(50):
        start = t0 + (t1 - t0) * float(rng.random()) if t1 > t0 else t0
        ids = first[(first >= start) & (first < start + pd.Timedelta(days=days))].index
        if len(ids) >= need:
            break
    else:
        ids = first.sort_values().index[:need]; start = first[ids].min()
    out = d[d['match_id'].isin(ids)]
    rep = dict(start=str(start)[:16], end=str(start + pd.Timedelta(days=days))[:16], matches=int(len(ids)), of=int(len(first)))
    if log is not None:
        log(f"[slice] {sport}: window {rep['start']} .. {rep['end']} · {rep['matches']:,} of {rep['of']:,} matches (LAZ_SLICE_DAYS={days:g}) — the 1-core methodology")
    return (out, rep)

# ═══ [v187 B1] laz_batch — WALK-FORWARD BATCHING. Buckets of matches in time order; batch b trains on bucket b
# (IS) and validates on bucket b+1 (OOS); the book carries every strategy forward so batch b+1 re-arms them; every
# batch writes its own legs/ledger/workbook under batch<b>_; the cross-batch Strategy Assessment reads them all. ═══
def laz_batch__first_ts(parquet_path):
    """Per-match first timestamp, aggregated in Arrow one row group at a time (never the whole frame)."""
    import pyarrow.parquet as _pq, pyarrow as _pa
    pf = _pq.ParquetFile(parquet_path); parts = []
    for i in range(pf.metadata.num_row_groups):
        t = pf.read_row_group(i, columns=['match_id', 'ts']); parts.append(t.group_by('match_id').aggregate([('ts', 'min')])); del t
    allg = _pa.concat_tables(parts).group_by('match_id').aggregate([('ts_min', 'min')])
    return pd.to_datetime(allg.to_pandas().set_index('match_id')['ts_min_min']).sort_values()

laz_batch__FLOOR = 700          # IS+OOS pair: IS-B is 15% of it and the gate needs n >= 100
laz_batch__LADDER = 10000       # IS matches per bucket on massive frames: ladder whole with margin; efootball 6 buckets, ebasketball 5
laz_batch__MASSIVE = 20000      # from here a frame is walked in ladder-sized buckets; below, at most 3 batches
laz_batch__ROWS_CAP = 4000000   # rows an IS+OOS pair may hold at stride 1 (memory on a 16 GB machine; the sweep runs at the sport stride)

def laz_batch__auto(parquet_path, log=None, sport=''):
    """[v187 B2] THE BATCH ARITHMETIC — the owner never picks the number.
      matches < 2 x FLOOR              -> 0 batches: one normal run (batching would starve the gate)
      matches < MASSIVE                -> buckets = clamp(matches // FLOOR, 2, 4), even split -> 1..3 batches
      matches >= MASSIVE               -> bucket = LADDER, capped so an IS+OOS pair stays under ROWS_CAP rows
                                          (from the frame's rows per match) -> as many batches as the frame gives
    Returns (bucket_matches, n_batches, reason). Env: LAZ_BATCH_FLOOR/LADDER/MASSIVE/ROWS_CAP override."""
    import os as _os, pyarrow.parquet as _pq
    F = int(_os.environ.get('LAZ_BATCH_FLOOR', laz_batch__FLOOR)); L = int(_os.environ.get('LAZ_BATCH_LADDER', laz_batch__LADDER))
    M = int(_os.environ.get('LAZ_BATCH_MASSIVE', laz_batch__MASSIVE)); R = int(_os.environ.get('LAZ_BATCH_ROWS_CAP', laz_batch__ROWS_CAP))
    pf = _pq.ParquetFile(parquet_path); rows = pf.metadata.num_rows
    n = int(laz_batch__first_ts(parquet_path).shape[0]); rpm = rows / max(n, 1)
    if n < 2 * F:
        bucket, nb, why = n, 0, f'{n:,} matches < {2 * F:,}: a single run (an IS+OOS pair could not reach n>=100 in both halves)'
    elif n < M:
        buckets = max(2, min(4, n // F)); bucket = -(-n // buckets); nb = buckets - 1
        why = f'{n:,} matches (normal): {buckets} even buckets of ~{bucket:,} -> {nb} batch(es)'
    else:
        cap = int(R // (2 * rpm)); bucket = min(L, cap) if cap >= F else F
        buckets = max(2, -(-n // bucket)); bucket = -(-n // buckets); nb = buckets - 1
        why = f'{n:,} matches (MASSIVE, {rpm:.0f} rows/match): ladder bucket {L:,}' + (f' capped to {cap:,} by the {R:,}-row budget' if cap < L else '') + f' -> {buckets} even buckets of ~{bucket:,} -> {nb} batches'
    if log is not None:
        log(f'[batch] {sport}: {why}')
    return (int(bucket), int(nb), why)

def laz_batch__plan(parquet_path, bucket_matches, max_batches=None, log=None, min_window=700, params=None):
    """Windows planned the way laz_sweep_mini plans them: as many matches as possible per bucket up to
    `bucket_matches`, split EVENLY (nwin = ceil(n / bucket), size = ceil(n / nwin)), no wasted tail. Batch b is
    the sliding pair (bucket b = IS, bucket b+1 = OOS), so mode 3's 50/50 split by match start falls on the
    bucket boundary and each OOS becomes the next batch's IS. A batch whose two buckets hold fewer than
    `min_window` matches cannot reach n>=100 in both halves (IS-B is 15% of the pair) and is not planned.
    Every batch carries a key from__to__nN (resume by key) and the plan carries provenance."""
    import hashlib as _hl, datetime as _dt, os as _os
    first = laz_batch__first_ts(parquet_path); ids = list(first.index); n = len(ids)
    nwin = max(1, -(-n // int(bucket_matches))); size = -(-n // nwin)
    buckets = [ids[i:i + size] for i in range(0, n, size)]
    plan = []
    for b in range(len(buckets) - 1):
        is_ids, oos_ids = buckets[b], buckets[b + 1]
        if len(is_ids) + len(oos_ids) < min_window:
            continue
        q = dict(batch=b + 1, is_ids=is_ids, oos_ids=oos_ids, is_from=str(first[is_ids[0]])[:16], is_to=str(first[is_ids[-1]])[:16], oos_from=str(first[oos_ids[0]])[:16], oos_to=str(first[oos_ids[-1]])[:16], n_is=len(is_ids), n_oos=len(oos_ids))
        q['key'] = f"{q['is_from'][:10]}__{q['oos_to'][:10]}__n{len(is_ids) + len(oos_ids)}"
        plan.append(q)
        if max_batches and len(plan) >= max_batches:
            break
    prov = dict(source_frame=_os.path.basename(parquet_path), frame_sha256=_hl.sha256(open(parquet_path, 'rb').read(1 << 22)).hexdigest()[:16], generated_at=_dt.datetime.now().isoformat(timespec='seconds'), matches=n, buckets=len(buckets), bucket_size=size, min_window=min_window,
                split='IS = bucket b, OOS = bucket b+1, by match start time, never shuffled; the OOS bucket becomes the next batch\'s IS', carry='every strategy in the book is re-armed in the next batch (supply = ENGINE_BOOK.csv + LAZ_BOOK.json)', params=params or {})
    if log is not None:
        log(f'[batch] {n:,} matches -> {len(buckets)} bucket(s) of ~{size:,} · {len(plan)} batch(es) (floor {min_window})' + ''.join(f"\n[batch]   batch {q['batch']} [{q['key']}]: IS {q['is_from']}..{q['is_to']} ({q['n_is']}) | OOS {q['oos_from']}..{q['oos_to']} ({q['n_oos']})" for q in plan))
    return plan, prov

def laz_batch___inherit_sidecar(parquet_dir, out_dir, sport, ids, n_rows_written, log=None):
    """[v192 K12] THE BATCH INHERITS THE LIBRARY.

    Each batch is materialised into its own directory, which the loop deletes when the batch ends. The library
    sidecar lives beside the frame, so before this every batch rebuilt the owner's feature library from scratch
    and then threw the cache away — the single most expensive stage, paid five times on efootball for no reason.

    The library is a per-tick function of the frame, so the rows for a batch's matches are exactly the rows of the
    SOURCE frame's library for those matches. Here we slice them the same way the frame rows were sliced, in the
    same order, and write them into the batch directory with the batch frame's own stamp. `prepare()` then finds
    every term already built and skips the walk entirely.

    If the source sidecar is missing or does not line up, nothing is written and the batch builds its own library
    exactly as before — this is a shortcut that can always be declined, never a dependency."""
    import os as _os
    src_p = _os.path.join(parquet_dir, f'AB_{sport}.library.parquet')
    src_j = _os.path.join(parquet_dir, f'AB_{sport}.library.json')
    src_f = _os.path.join(parquet_dir, f'AB_{sport}.parquet')
    dst_p = _os.path.join(out_dir, f'AB_{sport}.library.parquet')
    dst_j = _os.path.join(out_dir, f'AB_{sport}.library.json')
    if not (_os.path.exists(src_p) and _os.path.exists(src_j) and _os.path.exists(src_f)):
        return 0
    try:
        import pyarrow.parquet as _pq
        key_col = _pq.ParquetFile(src_f).schema_arrow.names
        if 'match_id' not in key_col:
            return 0
        lib = pd.read_parquet(src_p)
        want = set(str(x) for x in ids)
        if '__mid' in lib.columns:
            cut = lib.loc[lib['__mid'].astype(str).isin(want)].reset_index(drop=True)   # [v192 K13] by key, never by position
            if log is not None:
                log(f'  [batch]   library slice {len(cut):,} rows for {len(want)} matches — the batch aligns it by (match, tick) at prepare()')
        else:
            mids = pd.read_parquet(src_f, columns=['match_id'])['match_id'].astype(str)
            if len(lib) != len(mids):
                if log is not None:
                    log(f'  [batch]   the source library carries no keys and does not line up ({len(lib):,} vs {len(mids):,}) — rebuild it once with this engine to enable inheritance')
                return 0
            cut = lib.loc[mids.isin(want).to_numpy()].reset_index(drop=True)
        if not len(cut):
            return 0
        cut.to_parquet(dst_p, index=False)
        stamps = _laz_json_read(src_j)
        key = None
        _old = _os.environ.get('LAZ_PARQUET_DIR')
        _os.environ['LAZ_PARQUET_DIR'] = out_dir
        try:
            OW = _m('laz_owner')
            _prev = (OW.LAZ_OWNER.get('paths', {}) or {}).get('parquet_dir') if OW is not None else None
            if OW is not None:
                OW.LAZ_OWNER['paths']['parquet_dir'] = out_dir
            key = laz_sidecar__key(sport, len(cut))   # stamped against the BATCH frame, so it validates there
        finally:
            if _old is not None:
                _os.environ['LAZ_PARQUET_DIR'] = _old
            if OW is not None and _prev is not None:
                OW.LAZ_OWNER['paths']['parquet_dir'] = _prev
        _laz_json_write(dst_j, {t: (dict(key, _absent=True) if isinstance(v, dict) and v.get('_absent') else key) for t, v in stamps.items()})
        if log is not None:
            log(f'  [batch]   library INHERITED from the source frame: {len(cut.columns)} terms x {len(cut):,} rows — this batch skips the library build entirely')
        return len(cut.columns)
    except Exception as e:
        if log is not None:
            log(f'  [batch]   library not inherited ({type(e).__name__}: {str(e)[:70]}) — the batch will build its own')
        return 0

def laz_batch__materialise(parquet_dir, sport, out_dir, ids, log=None, h2h_names=()):
    """The batch's frame (IS + OOS buckets, chronological) as a dataset, written with the same column-sliced Arrow
    reader as the slice — and then the source frame's LIBRARY rows for those same matches, so the batch does not
    rebuild what has already been built once (K12)."""
    import os as _os
    _os.environ['LAZ_SLICE_MAX_MATCHES'] = str(len(ids) + 1)
    dst, rep = laz_slice__materialise(parquet_dir, sport, out_dir, days=1.0, min_matches=len(ids), seed=0, log=log, h2h_names=h2h_names, max_matches=len(ids), ids_override=set(ids))
    try:
        if dst and rep:
            rep['library_terms_inherited'] = laz_batch___inherit_sidecar(parquet_dir, out_dir, sport, ids, rep.get('rows', 0), log=log)
    except Exception as _e:
        if log is not None:
            log(f'  [batch]   sidecar inheritance skipped: {type(_e).__name__}')
    return (dst, rep)

def laz_batch__assess(sport, out_dir='.', log=print):
    """Cross-batch sheets from the per-batch ledgers: Strategy_Assessment (strategy x batch: n_bets, win_rate, roi),
    Base_Performance and Feature_Performance per batch, Implementation (every strategy with the batch it was FOUND in),
    Front (dates, matches, legs per batch). Written to LAZARUS_<SPORT>_BATCHES.xlsx."""
    import os as _os, glob as _glob, json as _json
    led = sorted(_glob.glob(_os.path.join(out_dir, f'batch*_mode3_{sport}.parquet')), key=lambda f: int(re.search(r'batch(\d+)_', _os.path.basename(f)).group(1)))
    if not led:
        log(f'[batch] {sport}: no batch ledgers to assess'); return None
    plan, prov = {}, {}
    pj = _os.path.join(out_dir, f'batch_plan_{sport}.json')
    if _os.path.exists(pj):
        _doc = _laz_json_read(pj); plan = {int(k): v for k, v in _doc.get('batches', {}).items()}; prov = _doc.get('provenance', {})
    rows, impl, base_rows, feat_rows, front = [], [], [], [], []
    for f in led:
        b = int(re.search(r'batch(\d+)_', _os.path.basename(f)).group(1)); L = pd.read_parquet(f)
        legs_p = _os.path.join(out_dir, f'batch{b}_mode3_{sport}_legs.csv'); legs = pd.read_csv(legs_p) if _os.path.exists(legs_p) else pd.DataFrame()
        L['batch_nr'] = b
        g = L.groupby(['strategy_name', 'base', 'market'], as_index=False).agg(n_bets=('won', 'size'), wins=('won', 'sum'), avg_odds=('price', 'mean'), profit=('price', lambda x: float((x[L.loc[x.index, 'won']] - 1).sum() - (~L.loc[x.index, 'won'].astype(bool)).sum())))
        g['win_rate'] = g['wins'] / g['n_bets']; g['roi'] = g['profit'] / g['n_bets']; g['batch_nr'] = b; rows.append(g)
        bg = L.groupby('base', as_index=False).agg(n_bets=('won', 'size'), wins=('won', 'sum'), strategies=('strategy_name', 'nunique')); bg['win_rate'] = bg['wins'] / bg['n_bets']; bg['batch_nr'] = b; base_rows.append(bg)
        if len(legs):
            legs = legs.copy(); legs['batch_nr'] = b; impl.append(legs)
            terms = legs['conditions'].astype(str).str.split(' AND ').explode().str.extract(r'^\s*([A-Za-z0-9_:.]+)')[0]
            fg = pd.DataFrame(dict(term=terms.values, oos_win=legs.loc[terms.index, 'oos_win'].values, oos_roi=legs.loc[terms.index, 'oos_roi'].values)).groupby('term', as_index=False).agg(legs=('oos_win', 'size'), mean_oos_win=('oos_win', 'mean'), mean_oos_roi=('oos_roi', 'mean')); fg['batch_nr'] = b; feat_rows.append(fg)
        q = plan.get(b, {}); front.append(dict(batch_nr=b, is_from=q.get('is_from'), is_to=q.get('is_to'), oos_from=q.get('oos_from'), oos_to=q.get('oos_to'), matches=int(L['mid'].nunique()), strategies_in_pool=int(L['strategy_name'].nunique()), legs_found=int(len(legs)), bets=int(len(L))))
    A = pd.concat(rows, ignore_index=True)
    piv = A.pivot_table(index=['strategy_name', 'base', 'market'], columns='batch_nr', values=['n_bets', 'win_rate', 'roi'], aggfunc='first')
    piv.columns = [f'{v}_b{b}' for v, b in piv.columns]; piv = piv.reset_index()
    found_in = pd.concat(impl, ignore_index=True)[['strategy_name', 'batch_nr']].drop_duplicates('strategy_name').rename(columns={'batch_nr': 'found_in_batch'}) if impl else pd.DataFrame(columns=['strategy_name', 'found_in_batch'])
    piv = piv.merge(found_in, on='strategy_name', how='left')
    # SURVIVORS (laz_sweep_mini): a strategy that cleared the bar in CONSECUTIVE batches is the one worth trusting
    _cleared = {b: set(l['strategy_name'].astype(str)) for b, l in ((int(re.search(r'batch(\d+)_', _os.path.basename(f)).group(1)), pd.read_csv(_os.path.join(out_dir, f'batch{int(re.search(r"batch(\d+)_", _os.path.basename(f)).group(1))}_mode3_{sport}_legs.csv'))) for f in led if _os.path.exists(_os.path.join(out_dir, f'batch{int(re.search(r"batch(\d+)_", _os.path.basename(f)).group(1))}_mode3_{sport}_legs.csv')))}
    _bs = sorted(_cleared); surv = []
    for nm in set().union(*_cleared.values()) if _cleared else set():
        run = best = 0
        for b in _bs:
            run = run + 1 if nm in _cleared[b] else 0; best = max(best, run)
        surv.append(dict(strategy_name=nm, batches_cleared=sum(nm in _cleared[b] for b in _bs), longest_consecutive=best, cleared_in=','.join(str(b) for b in _bs if nm in _cleared[b])))
    S = pd.DataFrame(surv).sort_values(['longest_consecutive', 'batches_cleared'], ascending=False) if surv else pd.DataFrame(columns=['strategy_name', 'batches_cleared', 'longest_consecutive', 'cleared_in'])
    piv = piv.merge(S[['strategy_name', 'batches_cleared', 'longest_consecutive']], on='strategy_name', how='left')
    wb = _os.path.join(out_dir, f'LAZARUS_{sport.upper()}_BATCHES.xlsx')
    with pd.ExcelWriter(wb, engine='openpyxl') as xw:
        _fr = pd.DataFrame(front)
        if prov:
            _fr = pd.concat([_fr, pd.DataFrame([{'batch_nr': 'PROVENANCE', **{k: (str(v)[:120]) for k, v in prov.items() if k != 'params'}}])], ignore_index=True)
        _fr.to_excel(xw, sheet_name='Batch Front page', index=False)
        S.to_excel(xw, sheet_name='Survivors', index=False)
        (pd.concat(impl, ignore_index=True) if impl else pd.DataFrame()).to_excel(xw, sheet_name='Implementation', index=False)
        piv.to_excel(xw, sheet_name='Strategy Assessment', index=False)
        A.to_excel(xw, sheet_name='Strategy per batch', index=False)
        pd.concat(base_rows, ignore_index=True).to_excel(xw, sheet_name='Base performance', index=False)
        (pd.concat(feat_rows, ignore_index=True) if feat_rows else pd.DataFrame()).to_excel(xw, sheet_name='Feature performance', index=False)
    log(f'[batch] {sport}: assessment -> {wb} · {len(front)} batches · {piv.shape[0]} strategies assessed across batches')
    return wb

def laz_slice__materialise(parquet_dir, sport, out_dir, days=2.0, min_matches=300, seed=0, log=None, h2h_names=(), max_matches=None, ids_override=None):
    """[v187 C2b] THE 1-CORE WINDOW AS A DATASET. For frames too large to load (efootball: 10.5 M rows x 215
    columns), the window is chosen from the match_id+ts columns alone, the frame is read row-group by
    row-group keeping only the window's matches, and the h2h CSVs are filtered to the same matches.
    Writes <out_dir>/AB_<sport>.parquet (+ filtered h2h files) and returns (path, report)."""
    import os as _os, pyarrow.parquet as _pq
    src = _os.path.join(parquet_dir, f'AB_{sport}.parquet')
    if not _os.path.exists(src):
        return (None, dict(sport=sport, note='no frame'))
    _os.makedirs(out_dir, exist_ok=True)
    import pyarrow as _pa0
    pf = _pq.ParquetFile(src)
    _firsts = []                                             # per-match first ts, aggregated in Arrow one row group at a time (248 MB on 10.5 M rows)
    for _i in range(pf.metadata.num_row_groups):
        _tb = pf.read_row_group(_i, columns=['match_id', 'ts'])
        _firsts.append(_tb.group_by('match_id').aggregate([('ts', 'min')])); del _tb
    _allg = _pa0.concat_tables(_firsts).group_by('match_id').aggregate([('ts_min', 'min')]); del _firsts
    first = pd.to_datetime(_allg.to_pandas().set_index('match_id')['ts_min_min']); del _allg
    rng = np.random.default_rng(int(seed))
    if ids_override is not None:                       # [v187 B1] a batch hands the exact match set: no window search
        ids = set(str(x) for x in ids_override); start = first[[i for i in ids if i in first.index]].min() if len(ids) else first.min()
    elif len(first) <= min_matches:
        ids = set(first.index); start = first.min()
    else:
        t0, t1 = first.min(), first.max() - pd.Timedelta(days=days)
        ids = set(); start = t0
        for _ in range(60):
            start = t0 + (t1 - t0) * float(rng.random()) if t1 > t0 else t0
            ids = set(first[(first >= start) & (first < start + pd.Timedelta(days=days))].index)
            if len(ids) >= min_matches:
                break
        if len(ids) < min_matches:
            ids = set(first.sort_values().index[:min_matches]); start = first[list(ids)].min()
    _cap = int(max_matches or _os.environ.get('LAZ_SLICE_MAX_MATCHES') or max(2 * min_matches, 600))
    if len(ids) > _cap:   # the window is sized by MATCHES: enough to conclude (>= min), small enough to run (<= cap) — on efootball 600 matches is ~3 hours of play
        ids = set(first[list(ids)].sort_values().index[:_cap])
    import pyarrow as _pa, pyarrow.compute as _pc
    _want = _pa.array(sorted(str(x) for x in ids), type=_pa.string())
    names = pf.schema_arrow.names; CH = 8
    parts = []
    for i in range(pf.metadata.num_row_groups):
        # the mask from ONE column, then the row group in ~24-column slices, each filtered before it is
        # converted: peak memory is one slice (~200 MB on 1 M rows), never the row group (~1.7 GB)
        mask = _pc.is_in(_pc.cast(pf.read_row_group(i, columns=['match_id']).column('match_id'), _pa.string()), value_set=_want)
        if not _pc.any(mask).as_py():
            continue
        cols = []
        for j in range(0, len(names), CH):
            sub = pf.read_row_group(i, columns=names[j:j + CH], use_threads=False).filter(mask)
            cols.append(sub.to_pandas()); del sub
            _pa.default_memory_pool().release_unused()
        parts.append(pd.concat(cols, axis=1)); del cols
    d = pd.concat(parts, ignore_index=True) if parts else pf.read_row_group(0, columns=names[:1]).slice(0, 0).to_pandas(); del parts
    d = d.sort_values(['match_id', 'ts'], kind='stable').reset_index(drop=True)
    dst = _os.path.join(out_dir, f'AB_{sport}.parquet'); d.to_parquet(dst, index=False)
    rep = dict(sport=sport, start=str(first[list(ids)].min())[:16], end=str(first[list(ids)].max())[:16], matches=int(len(ids)), of=int(len(first)), rows=int(len(d)), of_rows=int(pf.metadata.num_rows), h2h=[])
    for name in h2h_names:
        hp = _os.path.join(parquet_dir, name)
        if not _os.path.exists(hp):
            continue
        try:
            try:
                h = _pq.read_table(hp).to_pandas(); is_csv = False
            except Exception:
                h = pd.concat([c[c['match_id'].astype(str).isin({str(x) for x in ids})] for c in pd.read_csv(hp, chunksize=500000, low_memory=False)], ignore_index=True); is_csv = True
            if not is_csv:
                h = h[h['match_id'].astype(str).isin({str(x) for x in ids})]
            out = _os.path.join(out_dir, name)
            (h.to_csv(out, index=False) if is_csv else h.to_parquet(out, index=False))
            rep['h2h'].append((name, int(len(h))))
        except Exception as e:
            rep['h2h'].append((name, f'{type(e).__name__}: {str(e)[:60]}'))
    if log is not None:
        log(f"[slice] {sport}: materialised window {rep['start']} .. {rep['end']} · {rep['matches']:,} of {rep['of']:,} matches · {rep['rows']:,} of {rep['of_rows']:,} rows -> {dst}" + (f" · h2h {rep['h2h']}" if rep['h2h'] else ''))
    del d
    return (dst, rep)

# ═══ [v187 M1] laz_mini — automated_bet_mini: every validated strategy's bets, one parquet, all sports ═══
# [v191 M3c] TERM LISTS, corrected against the ACTUAL builders in this engine (7 Sep 2026).
#
# HARD — the column IS the result, or a checkpoint that only exists once the match is over. No builder can make
# these available at an entry tick, so no strategy naming one is deployable, whatever its numbers say.
laz_mini__DENY_TERMS = (
    'final_outcome', 'new_win_flag', 'actual_score', 'final_h_score', 'final_a_score', 'player_actual_score',
    'final_winner', 'final_result', 'final_tg', 'tot_under_won', 'tot_over_won',
    'sd_at_q4_100', 'absd_at_q4_100')
#
# NOT on the hard list, and here is why — each was checked against its builder in this file:
#   prog            = league_time_progress from the feed, or minute/nominal, or quarter/4 (lines 33563, 38089,
#                     38165, 33714). All clock-based and known at the tick. The 2026 leak was prog = cumcount /
#                     transform('size') — a ROW COUNT — which no longer exists. Implementable.
#   price_rank_in_match = (price - cummin) / (cummax - cummin) with EXPANDING cummin/cummax over the match so far
#                     (line 60380). Causal. The old full-match version was the leak; a leg from a pre-fix ledger
#                     can still carry it, which is what the entry-position test below catches.
#   pace_ratio, need_frac, proj_gap_n = divided by gfl = (4 - floor(quarter))/4, the remaining share of the match,
#                     known live (lines 62581-62585). Implementable. Their historical failure was WHERE they fired,
#                     not what they read — measured below, not guessed from the name.
#
# SOFT — a live price level or its implied probability: on your screen at the entry tick, so implementable. The
# risk is that an extreme level selects an already-decided match, which the price screen catches. FLAGGED only.
laz_mini__SOFT_TERMS = (
    'p_lead','p_trail','p_spread','live_ovr','ovr','o_live','drift_lead','p_lead_pos_in_range','o_lead_vs_takeover',
    'lead_tension','p_lead_since_score','rk_fav_odds','rk_dog_odds','rk_odds_ratio','rk_implied_edge','ml_spread',
    'home_odds','away_odds','draw_odds','open_vs_now_lead','imp_home','imp_away','imp_draw','imp_fav','imp_dog',
    'implied','betsite_probability','market_active','total_goals_market_active','moneyline_market_active',
    'price_rank_in_match','ld_rank','lo_rank','prog','prog_nominal','pace_ratio','need_frac','proj_gap_n',
    'lead_per_remain','scoring_rate','mp_required_rate')
laz_mini__REVIEW_TERMS = ('point_spread_handicap', 'total_goals_handicap', 'total_points_handicap', 'line_open', 'line_gap')

def laz_mini__terms_of(conditions):
    """Every column name a condition string references, with manufactured names (ix_a_m_b, a__over__b)
    resolved to BOTH parents — a manufactured term inherits its parents' lineage (leak class 10)."""
    out = set()
    for atom in str(conditions).split(' AND '):
        t = re.match(r'\s*([A-Za-z_][A-Za-z0-9_:.]*)', atom)
        if not t:
            continue
        nm = t.group(1)
        out.add(nm)
        for part in re.split(r'__over__|__minus__|__x__', nm[2:] if nm.startswith('X_') else nm):   # [v192 P4] strip the X_ manufacturing prefix before naming parents
            if part:
                out.add(part)
        m2 = re.match(r'^ix_(.+?)_(?:m|o|x)_(.+)$', nm)
        if m2:
            out.update(m2.groups())
    return out

def laz_mini__screen_terms(conditions):
    """(deny_hits, review_hits) for one condition string. A hit is exact or a suffix match on the term name."""
    ts = laz_mini__terms_of(conditions)
    import re as _re
    _HARD = None
    _SOFT = _re.compile(r'(^|_)(imp|implied|prob)_|_(imp|implied|prob)$|(^|_)market_active($|_)')
    def _hit(t, names, pat=None):
        return t in names or any(t.endswith('_' + d) or t == d for d in names) or bool(pat and pat.search(t))
    deny = sorted({t for t in ts if _hit(t, laz_mini__DENY_TERMS, _HARD)})
    soft = sorted({t for t in ts if _hit(t, laz_mini__SOFT_TERMS, _SOFT)})
    return (deny, soft or sorted({t for t in ts if t in laz_mini__REVIEW_TERMS}))

laz_mini__SIDE_LABEL = {'home': 'Home', 'away': 'Away', 'draw': 'Draw', 'over': 'Total_over', 'under': 'Total_under', 'tgover': 'Total_over', 'tgunder': 'Total_under', 'tpover': 'Total_over', 'tpunder': 'Total_under', 'tg_over': 'Total_over', 'tg_under': 'Total_under', 'tp_over': 'Total_over', 'tp_under': 'Total_under'}

def laz_mini__entry_prog(phase, league, sport=''):
    """[v191 M3d] How far into the match a tick is, for the quarter sports, read from the columns that carry it.

    The clock lives in `phase` and the match LENGTH lives in `league`:
        phase  '3rd Quarter, 15 minutes'
        league 'Ebasketball H2H GG League - 4 x 5 mins'   ->  4 x 5 = 20 total  ->  prog = 15/20 = 0.75
    eBasketball states its own format, so the elapsed minutes are exact and prog is exact.

    Real basketball states no format, and its minutes are WALL-CLOCK since tip-off (stoppages included), so the
    minutes cannot be divided by anything meaningful. There the QUARTER is the honest progress measure:
        '1st Quarter, 20 minutes'  ->  quarter 1 of 4  ->  prog = 0.25 (the quarter that has been reached),
    which is coarse but never wrong, and never claims the match is over when it is not.
    Returns NaN when neither is present."""
    import re as _re
    ph = '' if phase is None else str(phase)
    lg = '' if league is None else str(league)
    m = _re.search(r'(\d+)\s*x\s*(\d+)\s*min', lg, _re.I)
    mins = _re.search(r',\s*(\d+(?:\.\d+)?)\s*min', ph, _re.I)
    if m and mins:
        total = float(m.group(1)) * float(m.group(2))
        if total > 0:
            return min(float(mins.group(1)) / total, 1.3)
    # [v240 Rule 1] the quarter/half-index fallbacks are deleted: entry progress is
    # the exact stated league format (e.g. '4 x 5 mins') or timestamp arithmetic —
    # never a fabricated period index ('1st Quarter' is NOT 0.25 of anything real).
    return float('nan')

def laz_mini___odds_col(sport, side, cols, market=None, base=None):
    # [v191] 'under', 'TGUnder', 'tg_under', 'TPUnder' are the same market under different base labels; normalise
    # before the lookup. A totals bet whose column is missed keeps its row but loses playable-seconds and the
    # last-observation columns — that is what left the TGUnder legs undocumented, never excluded.
    sd = str(side).lower().replace('-', '_')
    # [v246-SPR] A BET'S PRICE COLUMN DEPENDS ON ITS MARKET, NOT ONLY ITS SIDE. Every home/away bet was mapped to
    # home_odds/away_odds — so a spread or map bet was exported as a MONEYLINE bet. A market this function cannot
    # map returns None (the row is kept, flagged unpriced) rather than a moneyline column it does not trade.
    mk = str(market or '').lower()
    if sd in ('home', 'away') and mk in ('spread', 'handicap'):
        for c in (f'point_spread_{sd}', f'goal_spread_{sd}'):
            if c in cols:
                return c
        return None
    if sd in ('home', 'away') and mk == 'map_handicap':
        return f'maps_handicap_{sd}' if f'maps_handicap_{sd}' in cols else None
    if sd in ('home', 'away') and mk == 'map_winner':
        import re as _rem
        _mn = _rem.search(r'map(\d)', str(base or '').lower())
        c = f'map_{_mn.group(1)}_winner_{sd}' if _mn else None
        return c if c and c in cols else None
    if sd in ('home', 'away', 'draw'):
        return f'{sd}_odds' if f'{sd}_odds' in cols else None
    kind = 'under' if 'under' in sd else ('over' if 'over' in sd else sd)
    for c in (f'total_goals_{kind}', f'total_points_{kind}', f'total_{kind}', f'{kind}_odds'):
        if c in cols:
            return c
    return None

laz_rescore__OPS = {'__over__': 'ratio', '__minus__': 'diff', '__x__': 'prod'}

def laz_rescore__manufacture(pool, conditions_iter, log=None, _sport_hint=None, _depth=0):
    """[v192 M1] REBUILD THE MANUFACTURED TERMS A RE-SCORE NEEDS.

    THE HOLE THIS CLOSES. A manufactured term (`X_a__over__b`, `X_a__minus__b`, `X_a__x__b`, and the short
    `ix_*` aliases) is built during the SWEEP by laz_corr.materialise from its two parents. `--rescore` does not
    sweep, so nothing built them, so the pool door correctly refused a term with no recipe, so every strategy
    naming one failed to arm — 3 of 3 on eTennis, 10 of 84 on eSports. Each step was behaving correctly and the
    chain had a hole: a term that IS reproducible was treated as if it were not.

    This resolves every manufactured name in the strategies about to be re-armed, verifies BOTH parents are in
    the pool, and rebuilds the term through `laz_corr.materialise` — THE SAME FUNCTION THE SWEEP CALLS. The
    value is therefore identical by construction, not by a second implementation agreeing with the first.

    Both the long name (`X_a__over__b`) and the short alias (`ix_a_o_b`) are written into the pool, because a
    strategy's conditions may carry either.

    REFUSES only what genuinely cannot be built — a parent that is itself absent — and names THE PARENT, so the
    log states the actual cause rather than the manufactured name.

    IMPACT: without this, every strategy using an interaction term is unrecoverable on a re-score, and the
    owner's rule that every element must be reproducible is not met."""
    import re as _re
    CR = _m('laz_corr')
    if CR is None:
        return (0, {})
    want = set()
    for cond in conditions_iter:
        for atom in str(cond).split(' AND '):
            m0 = _re.match(r'\s*([A-Za-z_][A-Za-z0-9_:.]*)', atom)
            if m0:
                want.add(m0.group(1))
    if _depth == 0 and _sport_hint:
        laz_corr__load_parentage(_sport_hint, out_dir=None, log=log)   # [v193 N1] definitions from disk before anything else
    made, refused = {}, {}
    pairs = []
    for nm in sorted(want):
        if nm in pool:
            continue
        defn = None
        if nm.startswith('X_'):
            for tok, kind in laz_rescore__OPS.items():
                if tok in nm:
                    a, _, b = nm[2:].partition(tok)
                    defn = (a, b, tok)
                    break
        if defn is None:
            d2 = CR.SHORT_TO_LONG.get(nm)          # a short alias whose parentage the engine already knows
            if d2:
                defn = (d2[0], d2[1], d2[2])
        if defn is None:
            continue
        a, b, tok = defn
        missing = [x for x in (a, b) if x not in pool]
        if missing and _depth < 6:
            # [v193 N2] NESTED INTERACTIONS. `ix2_ix2uprico_o_ix2ixflim2` is an interaction OF interactions:
            # its parents are themselves manufactured. Build the parents first, recursively, until real
            # columns are reached. Depth is capped so a corrupt definition cannot loop forever.
            laz_rescore__manufacture(pool, [f'{x} >= 0' for x in missing], log=None, _sport_hint=_sport_hint, _depth=_depth + 1)
            missing = [x for x in (a, b) if x not in pool]
        if missing:
            refused[nm] = missing                   # name the PARENT, not the manufactured term
            continue
        pairs.append(dict(a=a, b=b, tok=tok, name=nm))
    for tok, kind in laz_rescore__OPS.items():
        sel = [q for q in pairs if q['tok'] == tok]
        if not sel:
            continue
        built = CR.materialise(pool, pd.DataFrame([dict(a=q['a'], b=q['b']) for q in sel]), kinds=(kind,), out=None)
        for q in sel:
            short = CR.short_name(q['a'], q['b'], tok)
            if short in built:
                pool[q['name']] = built[short]      # the long name the conditions use
                pool.setdefault(short, built[short])  # and the short alias
                made[q['name']] = (q['a'], q['b'], tok)
    if log is not None:
        if made:
            log(f'  [manufacture] rebuilt {len(made)} interaction term(s) from their parents through laz_corr.materialise: ' +
                ', '.join(f'{k} = {v[0]} {v[2].strip("_")} {v[1]}' for k, v in list(made.items())[:4]) + (' …' if len(made) > 4 else ''))
        if refused:
            log(f'  [manufacture] {len(refused)} interaction term(s) NOT rebuildable — a parent is absent from this pool: ' +
                ', '.join(f'{k} (needs {"+".join(v)})' for k, v in list(refused.items())[:4]))
    return (len(made), refused)

def laz_rescore__run(sports, frames_dir, out_dir='.', stride=1, workers=None, log=print, min_matches=None):
    """[v191 R1] RE-SCORE UNDER CURRENT TRUTH.

    Every ledger on disk was produced by whichever engine ran that day — including builds whose guards did not
    exist yet. This re-arms every harvested strategy's CONDITION CHAIN against the CURRENT pool: the cleansed
    frame (abrupt endings removed, tracked status era), the h2h lineage door, the truncation and outcome-agreement
    guards, the owner's feature library, and the current settlement rule. A strategy whose terms no longer exist,
    or whose terms a guard refuses, simply does not arm and is reported by name. The result replaces
    mode3_<sport>.parquet, so --export-mini afterwards is current-truth by construction.

    Sports run in ASCENDING order of unique matches (after cleanse), so the smallest answer arrives first and a
    failure on a large sport costs nothing already earned. Each sport is written as it completes."""
    import os as _os, glob as _glob, time as _time
    import pyarrow.parquet as _pq
    ST = _m('laz_startup'); BK = _m('laz_book')
    _OW = _m('laz_owner')   # prepare() resolves the frame through the owner paths, not the argument
    if _OW is not None:
        try:
            _OW.LAZ_OWNER['paths']['parquet_dir'] = _os.path.abspath(frames_dir)
            _os.environ['LAZ_PARQUET_DIR'] = _os.path.abspath(frames_dir)
        except Exception:
            pass
    order = []
    for sp in sports:
        fp = _os.path.join(frames_dir, f'AB_{sp}.parquet')
        if not _os.path.exists(fp):
            log(f'[rescore] {sp}: no frame — skipped'); continue
        try:
            n = int(_pq.ParquetFile(fp).metadata.num_rows)
        except Exception:
            n = 1 << 60
        order.append((n, sp))
    order.sort()
    log(f'[rescore] order (smallest frame first): {[sp for _, sp in order]}')
    done = []
    _stamp_p = _os.path.join(out_dir, 'rescore_state.json')
    _state = _laz_json_read(_stamp_p) if _os.path.exists(_stamp_p) else {}
    for _n, sport in order:
        t0 = _time.time()
        # [v192 K11] RESUME. A sport re-scored against this frame, by this engine, with this stride is not redone.
        # The key is the frame's identity plus the engine version, so new data or a new engine re-scores it again.
        try:
            _fp = _os.path.join(frames_dir, f'AB_{sport}.parquet'); _st = _os.stat(_fp)
            _key = f'{_st.st_mtime_ns}|{_st.st_size}|{globals().get("LAZ_ENGINE_VERSION", "?")}|stride{int(stride or 1)}'
        except Exception:
            _key = None
        if _key and _state.get(sport, {}).get('key') == _key and _os.path.exists(_os.path.join(out_dir, f'mode3_{sport}.parquet')):
            _p = _state[sport]
            log(f"[rescore] {sport}: already re-scored against this frame by {globals().get('LAZ_ENGINE_VERSION', '?')} ({_p.get('strategies')} strategies, {_p.get('bets'):,} bets, {_p.get('when', '')}) — SKIPPED. Delete rescore_state.json to force.")
            done.append(dict(sport=sport, skipped=True, **{k: _p.get(k) for k in ('strategies', 'bets', 'unarmed')}))
            continue
        pats = [f'mode3_{sport}_legs.csv', f'batch*_mode3_{sport}_legs.csv', f'*/mode3_{sport}_legs.csv', f'*/batch*_mode3_{sport}_legs.csv']
        files = sorted({f for pat in pats for f in _glob.glob(_os.path.join(out_dir, pat))})
        if not files:
            log(f'[rescore] {sport}: no legs csv anywhere — nothing to re-score'); continue
        legs = pd.concat([pd.read_csv(f) for f in files], ignore_index=True).drop_duplicates('strategy_name', keep='last')
        legs = legs[legs['conditions'].astype(str).str.strip().ne('')]
        _left = [sp for _, sp in order][[sp for _, sp in order].index(sport) + 1:]
        log(f'[rescore] {sport}: {len(legs)} distinct strategies from {len(files)} legs file(s) — re-arming against the current pool' + (f' · {len(_left)} sport(s) after this: {_left}' if _left else ' · last sport'))
        try:
            M3 = _m('laz_mode3')
            book = BK.ensure_csv(M3.book_path(), log=log) if BK is not None else pd.DataFrame()
            d, pool, ctx, man = ST.prepare(sport, books=[book], stride=stride, log=log, workers=workers)
        except Exception as e:
            log(f'[rescore] {sport}: prepare FAILED — {type(e).__name__}: {str(e)[:110]}'); continue
        try:   # [v192 M1] rebuild the interaction terms these strategies need, before arming
            laz_rescore__manufacture(pool, legs['conditions'].astype(str), log=log, _sport_hint=sport)
            rows, ledgers = M3.ledgers_from_legs(legs, d, pool, ctx, sport, log=log)
        except Exception as e:
            log(f'[rescore] {sport}: re-arm FAILED — {type(e).__name__}: {str(e)[:110]}'); continue
        armed = {str(r.get('strategy_name')) for r in rows}
        try:   # [v192 V2] credentials: which of these were validated on a definition this engine no longer uses
            _prev = _os.path.join(out_dir, 'automated_bet_mini_implementation.parquet')
            if _os.path.exists(_prev):
                _I = pd.read_parquet(_prev)
                if 'definition_hashes' in _I.columns:
                    _src3 = laz_sidecar___engine_source().split('\n'); _tab3 = laz_featdoc__provenance()
                    _moved = []
                    for _nm, _dh in zip(_I['strategy_name'].astype(str), _I['definition_hashes'].astype(str)):
                        _pin = {kv.split('=')[0]: ('', kv.split('=')[1]) for kv in _dh.split('|') if '=' in kv}
                        _ok3, _ch3 = laz_featdoc__check_credentials(_pin, _src3, _tab3)
                        if _ch3:
                            _moved.append((_nm, sorted(_ch3)))
                    if _moved:
                        pd.DataFrame(dict(strategy_name=[a for a, _ in _moved], terms_changed=['|'.join(b) for _, b in _moved])).to_csv(_os.path.join(out_dir, f'{sport}_superseded_credentials.csv'), index=False)
                        log(f'[rescore] {sport}: {len(_moved)} strategies were validated on a definition this engine NO LONGER USES — re-scored here, listed in {sport}_superseded_credentials.csv (e.g. {_moved[0][0]}: {_moved[0][1][:3]})')
                    else:
                        log(f'[rescore] {sport}: every previously validated strategy still matches its credentials (no builder has changed under them)')
        except Exception as _e:
            log(f'[rescore] {sport}: credential check skipped ({type(_e).__name__}: {str(_e)[:60]})')
        # [v192 K10] a legs csv can carry a blank/NaN name (a truncated write); coerce and drop it rather than
        # dying in sorted() on the report line after the re-score has already succeeded.
        _names = {str(x) for x in legs['strategy_name'].dropna().astype(str) if str(x).strip() and str(x) != 'nan'}
        lost = sorted(_names - {str(a) for a in armed})
        if lost:
            pd.DataFrame(dict(sport=sport, strategy_name=lost)).to_csv(_os.path.join(out_dir, f'{sport}_rescore_unarmed.csv'), index=False)
            log(f'[rescore] {sport}: {len(lost)} strategies DID NOT ARM under current truth (terms missing or refused by a guard) -> {sport}_rescore_unarmed.csv')
        _strat = {str(r.get('strategy_name')): r for r in rows}
        _SF = ('base', 'conditions', 'tier', 'odds', 'oos_win', 'oos_roi', 'is_win', 'is_roi', 'bets', 'n_is', 'n_oos', 'market', 'band', 'single_only', 'combo_tier', 'origin', 'stars')
        _lr = []
        for _nm, _L in ledgers.items():
            _n2 = len(_L['mid'])
            if not _n2:
                continue
            _df = pd.DataFrame(dict(strategy_name=str(_nm), mid=np.asarray(_L['mid']).astype(str), stride=int(stride or 0), ts=pd.to_datetime(np.asarray(_L['ts'])), won=np.asarray(_L['won']).astype(bool), price=np.asarray(_L.get('price', [np.nan] * _n2), float), side=np.asarray(_L.get('side', [''] * _n2)).astype(str), is_oos=np.asarray(_L.get('is_oos', [True] * _n2)).astype(bool), league=np.asarray(_L.get('league', [''] * _n2)).astype(str)))
            _r = _strat.get(str(_nm), {})
            for _f in _SF:
                _v = _r.get(_f) if hasattr(_r, 'get') else None
                if _v is not None and (not (isinstance(_v, float) and _v != _v)):
                    _df[_f] = _v if isinstance(_v, (str, int, float, bool)) else str(_v)
            _lr.append(_df)
        if not _lr:
            log(f'[rescore] {sport}: nothing armed — the previous ledger is left untouched'); continue
        LD = pd.concat(_lr, ignore_index=True, sort=False)
        LD['rescored'] = True
        LD.to_parquet(_os.path.join(out_dir, f'mode3_{sport}.parquet'), index=False)          # replaces the old truth
        pd.DataFrame(rows).to_csv(_os.path.join(out_dir, f'mode3_{sport}_legs.csv'), index=False)
        for stale in _glob.glob(_os.path.join(out_dir, f'batch*_mode3_{sport}*')):
            _os.replace(stale, stale + '.prerescore')
        log(f'[rescore] {sport}: {LD.strategy_name.nunique()} strategies · {len(LD):,} bets re-scored in {_time.time() - t0:.0f}s -> mode3_{sport}.parquet (batch ledgers renamed .prerescore)')
        done.append(dict(sport=sport, strategies=int(LD.strategy_name.nunique()), bets=int(len(LD)), unarmed=len(lost), seconds=round(_time.time() - t0, 1)))
        if _key:   # [v192 K11] record success so a later run skips this sport
            try:
                _state[sport] = dict(key=_key, strategies=int(LD.strategy_name.nunique()), bets=int(len(LD)), unarmed=len(lost), when=pd.Timestamp.now().strftime('%Y-%m-%d %H:%M'))
                _laz_json_write(_stamp_p + '.tmp', _state); _os.replace(_stamp_p + '.tmp', _stamp_p)
            except Exception as _e:
                log(f'[rescore] {sport}: state not written ({type(_e).__name__}) — a rerun will redo this sport')
    log(f'[rescore] done: {done}')
    return done

# ═══ [v192 W1] laz_deploybook — the production workbook. Everything a person or a system needs to implement the
# validated strategies, and nothing that is not validated: it is built from automated_bet_mini* only. ═══
laz_deploybook__INK = '1A1D23'; laz_deploybook__ACC = '1F4E79'; laz_deploybook__GOOD = '1E7B4D'
laz_deploybook__WARN = 'B23A00'; laz_deploybook__LINE = 'D6DAE0'; laz_deploybook__BAND = 'F7F8FA'

laz_deploybook__SPORT_COLOUR = {'football': '2E7D32', 'efootball': '00897B', 'basketball': 'EF6C00', 'ebasketball': 'F9A825',
                                'tennis': '6A1B9A', 'etennis': '8E24AA', 'tabletennis': '3949AB', 'esports': 'C62828'}

def laz_deploybook__cover(xw, I, B, S, sport_dash, log=None):
    """[v200 B3] THE COVER — the bundle in one screen. KPI tiles, a sport-by-sport table with data bars, two
    native Excel charts (strategies and OOS ROI per sport) that recalculate from the sheet, and a colour key.
    Arial throughout; every rate a percent stored as a fraction so Excel formats it; live formulas for the
    tiles so the numbers cannot drift from the table beneath them."""
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.chart import BarChart, Reference
    from openpyxl.formatting.rule import DataBarRule, ColorScaleRule
    from openpyxl.utils import get_column_letter
    INK, ACC, GOOD, WARN, MID = laz_deploybook__INK, laz_deploybook__ACC, laz_deploybook__GOOD, laz_deploybook__WARN, '5B6472'
    ws = xw.book.create_sheet('00_COVER', 0)
    ws.sheet_view.showGridLines = False
    for col, w in zip('ABCDEFGHIJKL', (2, 22, 16, 16, 16, 16, 16, 16, 16, 16, 16, 2)):
        ws.column_dimensions[col].width = w
    # title block
    ws.merge_cells('B2:K2'); ws['B2'] = 'LAZARUS ENGINE — DEPLOYMENT BOOK'
    ws['B2'].font = Font(name='Aptos Narrow', size=22, bold=True, color=INK); ws.row_dimensions[2].height = 34
    ws.merge_cells('B3:K3')
    ws['B3'] = f"Validated strategies only · owner bar n_is ≥ 100, n_oos ≥ 100, ROI > 0, measured on the bets that ship · engine {globals().get('LAZ_ENGINE_VERSION', '?')} · {pd.Timestamp.now():%d %b %Y %H:%M}"
    ws['B3'].font = Font(name='Aptos Narrow', size=10, color=MID)
    for c in 'BCDEFGHIJK':
        ws[f'{c}4'].fill = PatternFill('solid', fgColor=ACC); ws.row_dimensions[4].height = 4
    # KPI tiles — live formulas against the sport table below, never hardcoded results
    # the dashboard carries a TOTAL row; on the cover the tiles ARE the total, so it must not be double-counted
    sport_dash = sport_dash[~sport_dash['sport'].astype(str).str.upper().isin(['TOTAL', 'ALL LEAGUES', 'ALL'])].reset_index(drop=True)
    n_sports = int(len(sport_dash))
    t0 = 24                                     # [v204 F2] sport table header row — moved down: the reading key
                                                #  grew to seven rows and was overwriting the table's header
    oos = B[B['is_oos'].astype(bool)] if 'is_oos' in B.columns else B
    # [v201 X4] LITERAL VALUES, NOT FORMULAS. openpyxl writes a formula with no cached result, so Excel shows it
    # correctly on open while pandas, previewers and any verification script read None — the owner's check
    # reported empty tiles on a correct workbook. The book is regenerated on every export, so a stored value
    # cannot go stale, and it reads the same everywhere. Each figure is computed from the exported bets, the
    # same rows the sport table beneath is built from.
    _n_str = int(len(I)); _n_bet = int(len(B)); _n_oos = int(len(oos))
    _win = float((oos['db_outcome'] == 'Win').mean()) if _n_oos else 0.0
    _roi = float(oos['db_profit'].mean()) if _n_oos else 0.0
    _pro = float(oos['db_profit'].sum()) if _n_oos else 0.0
    tiles = [('STRATEGIES', _n_str, '#,##0', ACC),
             ('BETS PLACED', _n_bet, '#,##0', ACC),
             ('OOS BETS', _n_oos, '#,##0', ACC),
             ('OOS WIN RATE', round(_win, 4), '0.0%', GOOD if _win >= 0.5 else WARN),
             ('OOS ROI / BET', round(_roi, 4), '0.0%', GOOD if _roi > 0 else WARN),
             ('OOS PROFIT (1u flat)', round(_pro, 2), '#,##0.0', GOOD if _pro > 0 else WARN)]
    for i, (lab, f, fmt, col) in enumerate(tiles):
        c1 = get_column_letter(2 + i * 1 + (i // 3) * 0); r = 6 if i < 3 else 10
        col_letter = get_column_letter(2 + (i % 3) * 3)
        ws.merge_cells(f'{col_letter}{r}:{get_column_letter(2 + (i % 3) * 3 + 2)}{r}')
        ws.merge_cells(f'{col_letter}{r + 1}:{get_column_letter(2 + (i % 3) * 3 + 2)}{r + 1}')
        ws[f'{col_letter}{r}'] = lab; ws[f'{col_letter}{r}'].font = Font(name='Aptos Narrow', size=9, bold=True, color=MID)
        ws[f'{col_letter}{r}'].alignment = Alignment(horizontal='center')
        v = ws[f'{col_letter}{r + 1}']; v.value = f; v.number_format = fmt
        v.font = Font(name='Aptos Narrow', size=20, bold=True, color=col); v.alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[r + 1].height = 32
        for cc in range(2 + (i % 3) * 3, 2 + (i % 3) * 3 + 3):
            for rr in (r, r + 1):
                ws.cell(row=rr, column=cc).fill = PatternFill('solid', fgColor='F7F8FA')
                ws.cell(row=rr, column=cc).border = Border(top=Side(style='thin', color=laz_deploybook__LINE), bottom=Side(style='thin', color=laz_deploybook__LINE))
    # key
    # [v204 F2] A VERDICT LINE. A cover that only shows totals makes the reader do the judging. This states
    # what the bundle IS, in one sentence, with the numbers that decide it.
    _ready = int(sum(1 for _x in (I.get('rt_columns'), ) for _ in [0])) if False else int(
        ((I.get('rt_columns', pd.Series(dtype=str)).astype(str).str.len() > 2) &
         (I.get('live_expression', pd.Series(dtype=str)).astype(str).str.len() > 2)).sum()) if 'rt_columns' in I.columns else len(I)
    _verdict = (f'{len(I)} strategies cleared the bar (≥100 in-sample bets, ≥100 out-of-sample, profit on the bets they ship). '
                f'{_ready} carry a full production recipe. Out of sample they returned '
                f'{100 * (float(oos["db_profit"].mean()) if len(oos) else 0):.1f}% per bet across {len(oos):,} bets.')
    # row 13 sits below the second tile band (rows 10-11), so it is free; merge FIRST, then write the anchor —
    # writing a cell that is already part of another merge raises 'MergedCell object attribute value is read-only'.
    for _rng in list(ws.merged_cells.ranges):
        if _rng.min_row <= 13 <= _rng.max_row:
            ws.unmerge_cells(str(_rng))
    ws.merge_cells('B13:K13')
    ws['B13'].value = _verdict
    ws['B13'].font = Font(name='Aptos Narrow', size=11, bold=True, color=(GOOD if (len(oos) and float(oos['db_profit'].mean()) > 0) else WARN))
    ws['B13'].alignment = Alignment(wrap_text=True, vertical='center'); ws.row_dimensions[13].height = 32
    ws['B14'] = 'HOW TO READ'; ws['B14'].font = Font(name='Aptos Narrow', size=11, bold=True, color=INK)
    for i, (k, v) in enumerate([
            ('00_GO_LIVE', 'every strategy, READY or BLOCKED, with what to bet, when it arms, the minimum price, and the formula to build it'),
            ('S_ sheets', 'one page per strategy for the sport named in LAZ_BOOK_SPORT — what it bets, what it did, and its league split'),
            ('40_EXCLUDED', 'every strategy that did NOT make it, with the reason. Read this before trusting the ones that did.'),
            ('OOS', 'out of sample: the later half of the data by match start, never used to choose the strategy. The only number to trust.'),
            ('green / red', 'READY vs BLOCKED, and every ROI column shaded red→green so a weak strategy shows without reading a figure'),
            ('flat stakes', 'every ROI here assumes ONE unit per bet at or above the minimum price. No staking plan is modelled.'),
            ('not included', 'stake sizing, bankroll rules and whether a market is open at placement — the production stack owns those')]):
        ws[f'B{15 + i}'] = k; ws[f'B{15 + i}'].font = Font(name='Aptos Narrow', size=9, bold=True, color=ACC)
        ws.merge_cells(f'C{15 + i}:K{15 + i}'); ws[f'C{15 + i}'] = v; ws[f'C{15 + i}'].font = Font(name='Aptos Narrow', size=9, color=INK)
    # sport table
    heads = ['sport', 'strategies', 'bets', 'oos bets', 'oos wins', 'oos profit (1u)', 'oos win rate', 'oos roi / bet']
    for j, h in enumerate(heads):
        c = ws.cell(row=t0, column=2 + j, value=h.upper())
        c.font = Font(name='Aptos Narrow', size=9, bold=True, color='FFFFFF'); c.fill = PatternFill('solid', fgColor=ACC)
        c.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
    ws.row_dimensions[t0].height = 28
    for i, (_, r) in enumerate(sport_dash.iterrows()):
        rr = t0 + 1 + i; sp = str(r['sport'])
        so = oos[oos['sport'].astype(str) == sp] if 'sport' in oos.columns else oos.iloc[0:0]
        sb = B[B['sport'].astype(str) == sp] if 'sport' in B.columns else B.iloc[0:0]
        vals = [sp, int(r.get('strategies', 0)), int(len(sb)), int(len(so)), int((so['db_outcome'] == 'Win').sum()) if len(so) else 0,
                round(float(so['db_profit'].sum()), 2) if len(so) else 0.0,
                (round(float((so['db_outcome'] == 'Win').mean()), 4) if len(so) else 0.0), (round(float(so['db_profit'].mean()), 4) if len(so) else 0.0)]
        for j, v in enumerate(vals):
            c = ws.cell(row=rr, column=2 + j, value=v); c.font = Font(name='Aptos Narrow', size=10, color=INK)
            c.alignment = Alignment(horizontal='left' if j == 0 else 'right')
            if j in (1, 2, 3, 4): c.number_format = '#,##0'
            if j == 5: c.number_format = '#,##0.0'
            if j in (6, 7): c.number_format = '0.0%'
            c.fill = PatternFill('solid', fgColor='F7F8FA' if i % 2 else 'FFFFFF')
        ws.cell(row=rr, column=2).fill = PatternFill('solid', fgColor=laz_deploybook__SPORT_COLOUR.get(sp, 'E0E0E0'))
        ws.cell(row=rr, column=2).font = Font(name='Aptos Narrow', size=10, bold=True, color='FFFFFF')
    last = t0 + n_sports
    ws.conditional_formatting.add(f'C{t0 + 1}:C{last}', DataBarRule(start_type='min', end_type='max', color=ACC))
    ws.conditional_formatting.add(f'I{t0 + 1}:I{last}', ColorScaleRule(start_type='min', start_color='FBE9E2', mid_type='num', mid_value=0, mid_color='FFFFFF', end_type='max', end_color='CDE9D9'))
    # charts, native and live
    ch = BarChart(); ch.type = 'col'; ch.style = 10; ch.title = 'Validated strategies per sport'; ch.y_axis.title = 'strategies'
    ch.add_data(Reference(ws, min_col=3, min_row=t0, max_row=last), titles_from_data=True)
    ch.set_categories(Reference(ws, min_col=2, min_row=t0 + 1, max_row=last)); ch.legend = None; ch.height = 7.5; ch.width = 15
    ws.add_chart(ch, f'B{last + 3}')
    ch2 = BarChart(); ch2.type = 'col'; ch2.style = 12; ch2.title = 'OOS ROI per bet, by sport'; ch2.y_axis.title = 'roi'; ch2.y_axis.number_format = '0%'
    ch2.add_data(Reference(ws, min_col=9, min_row=t0, max_row=last), titles_from_data=True)
    ch2.set_categories(Reference(ws, min_col=2, min_row=t0 + 1, max_row=last)); ch2.legend = None; ch2.height = 7.5; ch2.width = 15
    ws.add_chart(ch2, f'G{last + 3}')
    ws.freeze_panes = None
    # [v201 X4] A FORMULA HAS NO VALUE UNTIL SOMETHING CALCULATES IT. openpyxl writes the tile formulas with no
    # cached result, so Excel shows them correctly on open but pandas, previewers and any script read None —
    # the owner's verification script reported empty tiles on a correct workbook. A comment beside each tile
    # carries the computed figure so the sheet is checkable without opening Excel, and the workbook is
    # recalculated after writing when LibreOffice is available.
    try:
        from openpyxl.comments import Comment
        _tot = dict(strategies=int(len(I)), bets=int(len(B)), oos=int(len(oos)),
                    win=(float((oos['db_outcome'] == 'Win').mean()) if len(oos) else 0.0),
                    roi=(float(oos['db_profit'].mean()) if len(oos) else 0.0),
                    profit=(float(oos['db_profit'].sum()) if len(oos) else 0.0))
        for i, key in enumerate(('strategies', 'bets', 'oos', 'win', 'roi', 'profit')):
            r = 7 if i < 3 else 11
            cl = get_column_letter(2 + (i % 3) * 3)
            v = _tot[key]
            ws[f'{cl}{r}'].comment = Comment(f'computed from the exported bets: {v:,.4f}'.rstrip('0').rstrip('.'), 'LazarusEV')
    except Exception:
        pass
    if log is not None:
        log(f'  [deploybook] cover: {n_sports} sports, 6 live KPI tiles, 2 charts · totals {int(len(I))} strategies / {int(len(B)):,} bets')

def laz_deploybook__style(ws, n_cols, n_rows, money_cols=(), pct_cols=(), wide=None, title=None):
    """[v199 B1] Make a sheet READABLE: a real header, frozen panes, banded rows, sensible widths, number
    formats, and colour that carries meaning rather than decoration. A workbook nobody wants to open is a
    workbook nobody checks, and an unchecked bundle is how a wrong number reaches production."""
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    hdr_fill = PatternFill('solid', fgColor=laz_deploybook__ACC)
    hdr_font = Font(color='FFFFFF', bold=True, size=10, name='Aptos Narrow')
    band = PatternFill('solid', fgColor=laz_deploybook__BAND)
    thin = Side(style='thin', color=laz_deploybook__LINE)
    for c in range(1, n_cols + 1):
        cell = ws.cell(row=1, column=c)
        cell.fill = hdr_fill; cell.font = hdr_font
        cell.alignment = Alignment(horizontal='left', vertical='center', wrap_text=True)
    ws.row_dimensions[1].height = 30
    ws.freeze_panes = 'A2'
    if n_rows and n_cols:
        ws.auto_filter.ref = f'A1:{get_column_letter(n_cols)}{n_rows + 1}'
    for r in range(2, n_rows + 2):
        if r % 2 == 0:
            for c in range(1, n_cols + 1):
                ws.cell(row=r, column=c).fill = band
    for c in range(1, n_cols + 1):
        L = get_column_letter(c)
        head = str(ws.cell(row=1, column=c).value or '')
        w = 44 if (wide and head in wide) else (26 if len(head) > 18 else 15)
        ws.column_dimensions[L].width = w
        fmt = '#,##0.00"%"' if head in pct_cols else ('#,##0.00' if head in money_cols else None)
        if fmt:
            for r in range(2, n_rows + 2):
                ws.cell(row=r, column=c).number_format = fmt
        for r in range(2, n_rows + 2):
            ws.cell(row=r, column=c).border = Border(bottom=thin)
            ws.cell(row=r, column=c).alignment = Alignment(vertical='top', wrap_text=(w > 30))
    return ws

def laz_deploybook__colour_rules(ws, n_rows, cols, ready_col=None, roi_cols=()):
    """Colour that means something: READY green / BLOCKED red, profit green, loss red."""
    from openpyxl.formatting.rule import CellIsRule, ColorScaleRule
    from openpyxl.utils import get_column_letter
    green = dict(start_color='E3F3EA', end_color='E3F3EA', fill_type='solid')
    red = dict(start_color='FBE9E2', end_color='FBE9E2', fill_type='solid')
    from openpyxl.styles import PatternFill, Font
    if ready_col and ready_col in cols:
        L = get_column_letter(cols.index(ready_col) + 1); rng = f'{L}2:{L}{n_rows + 1}'
        ws.conditional_formatting.add(rng, CellIsRule(operator='equal', formula=['"READY"'],
            fill=PatternFill(**green), font=Font(color=laz_deploybook__GOOD, bold=True)))
        ws.conditional_formatting.add(rng, CellIsRule(operator='equal', formula=['"BLOCKED"'],
            fill=PatternFill(**red), font=Font(color=laz_deploybook__WARN, bold=True)))
    for rc in roi_cols:
        if rc in cols:
            L = get_column_letter(cols.index(rc) + 1); rng = f'{L}2:{L}{n_rows + 1}'
            ws.conditional_formatting.add(rng, ColorScaleRule(
                start_type='min', start_color='FBE9E2', mid_type='num', mid_value=0, mid_color='FFFFFF',
                end_type='max', end_color='CDE9D9'))

def laz_deploybook__one_to_one(xw, I, B, sport, log=None):
    """[v199 B2] ONE SHEET PER STRATEGY for the sport the owner names — everything about that strategy on a
    page: what it bets, when it arms, how it settles, what it made, and its performance by league and by month.
    LAZ_BOOK_SPORT=<sport> selects it; the whole bundle stays in the other sheets either way."""
    K = I[I['sport'].astype(str).str.lower() == str(sport).lower()]
    if not len(K):
        if log is not None:
            log(f'  [deploybook] no validated strategies for {sport} — no one-to-one sheets written')
        return 0
    from openpyxl.styles import Font, PatternFill, Alignment
    made = 0
    for _, r in K.iterrows():
        nm = str(r.get('strategy_name'))[:24].replace('/', '_').replace(':', '_').replace('[', '(').replace(']', ')')
        sh = f'S_{made + 1:02d}_{nm}'[:31]
        bets = B[B['strategy_id'] == r.get('strategy_id')] if 'strategy_id' in B.columns else B.iloc[0:0]
        oos = bets[bets['is_oos'].astype(bool)] if 'is_oos' in bets.columns and len(bets) else bets
        head = [('STRATEGY', str(r.get('strategy_name'))), ('SPORT', str(r.get('sport'))),
                ('READY TO PLACE', 'YES' if str(r.get('rt_columns', '')).strip() and str(r.get('live_expression', '')).strip() else 'NO — missing a production recipe'),
                ('', ''), ('WHAT TO BET', ''),
                ('market', str(r.get('market'))), ('side', str(r.get('side'))),
                ('minimum price', str(r.get('min_odds_req'))),
                ('settle', 'final margin vs the posted handicap' if str(r.get('market')) == 'handicap' else 'final total vs the posted line' if str(r.get('market')) == 'totals' else 'final result == the backed side'),
                ('one bet per', 'MATCH — never twice in the same match'),
                ('', ''), ('WHEN IT ARMS', ''), ('conditions (all must be true)', str(r.get('conditions'))),
                ('', ''), ('HOW TO BUILD IT', ''),
                ('warehouse columns', str(r.get('rt_columns', ''))),
                ('live expression', str(r.get('live_expression', ''))),
                ('applies to', str(r.get('applies_to', ''))),
                ('definition hashes', str(r.get('definition_hashes', ''))),
                ('validated under', str(r.get('validated_under', ''))),
                ('', ''), ('WHAT IT DID (out of sample, the honest number)', ''),
                ('bets', int(len(oos))),
                ('win rate %', round(100 * (oos['db_outcome'] == 'Win').mean(), 2) if len(oos) else None),
                ('roi % per bet', round(100 * oos['db_profit'].mean(), 2) if len(oos) else None),
                ('profit (flat 1 unit)', round(float(oos['db_profit'].sum()), 2) if len(oos) else None),
                ('average price', round(float(oos['bet_placement_odds'].mean()), 3) if len(oos) else None),
                ('claimed at discovery %', r.get('claimed_oos_roi'))]
        pd.DataFrame(head, columns=['item', 'value']).to_excel(xw, sheet_name=sh, index=False)
        ws = xw.book[sh]
        ws.sheet_properties.tabColor = laz_deploybook__SPORT_COLOUR.get(str(sport).lower(), 'E0E0E0')
        ws.column_dimensions['A'].width = 34; ws.column_dimensions['B'].width = 96
        for i, (k, _v) in enumerate(head, start=2):
            c = ws.cell(row=i, column=1)
            if k and not _v and k.isupper():
                c.font = Font(bold=True, color='FFFFFF', size=11)
                c.fill = PatternFill('solid', fgColor=laz_deploybook__ACC)
                ws.cell(row=i, column=2).fill = PatternFill('solid', fgColor=laz_deploybook__ACC)
            else:
                c.font = Font(bold=True, color=laz_deploybook__INK, size=10)
            ws.cell(row=i, column=2).alignment = Alignment(wrap_text=True, vertical='top')
        ws.cell(row=1, column=1).value = 'ITEM'; ws.cell(row=1, column=2).value = 'VALUE'
        laz_deploybook__style(ws, 2, len(head))
        if len(oos) and 'league' in oos.columns:
            lg = oos.groupby('league', dropna=False).agg(bets=('db_profit', 'size'),
                 win_pct=('db_outcome', lambda x: round(100 * (x == 'Win').mean(), 1)),
                 roi_pct=('db_profit', lambda x: round(100 * x.mean(), 1))).reset_index().sort_values('bets', ascending=False)
            lg.to_excel(xw, sheet_name=sh, index=False, startrow=len(head) + 3)
        made += 1
        if made >= 60:
            break
    if log is not None:
        log(f'  [deploybook] {made} one-to-one strategy sheets for {sport} (LAZ_BOOK_SPORT)')
    return made

def laz_deploybook___terms(cond):
    import re as _re
    out = []
    for atom in str(cond).split(' AND '):
        mm = _re.match(r'\s*([A-Za-z_][A-Za-z0-9_:.]*)\s*(>=|<=|==|>|<)\s*(\S+)', atom)
        if mm:
            out.append((mm.group(1), mm.group(2), mm.group(3)))
    return out

def laz_deploybook__write(out_dir='.', log=print, path=None, B=None, I=None):
    """automated_bet_mini* + FEATURE_REGISTRY -> LAZARUS_DEPLOYMENT_BOOK.xlsx.

    01_Dashboard          one line per sport and the totals, plus the run's provenance
    05_IMPLEMENTATION     one row per validated strategy: id, number, market, outcome, min odds, tier, conditions,
                          IS/OOS metrics, and the atoms split out so a system can read them without parsing
    06_FEATURE_LINEAGE    every term used by a validated strategy: kind, inputs, builder site, coverage, status
    22_FEATURES_DEFINITIONS  the formula line for each of those terms, straight from the engine source
    30_STRATEGY_PERFORMANCE / 31_LEAGUE_PERFORMANCE   as exported
    40_EXCLUDED / 41_FLAGGED / 42_UNARMED             what did not make it, and why
    """
    import os as _os
    def _rd(n, kind='parquet'):
        f = _os.path.join(out_dir, n)
        if not _os.path.exists(f):
            return pd.DataFrame()
        try:
            return pd.read_parquet(f) if kind == 'parquet' else pd.read_csv(f)
        except Exception:
            return pd.DataFrame()
    B = B if B is not None else _rd('automated_bet_mini.parquet')
    I = I if I is not None else _rd('automated_bet_mini_implementation.parquet')
    S = _rd('strategy_performance.parquet'); G = _rd('league_level_strategy_performance.parquet')
    R = _rd('FEATURE_REGISTRY.parquet'); E = _rd('excluded_strategies.csv', 'csv'); F = _rd('flagged_strategies.csv', 'csv')
    if not len(I):
        log('[deploybook] no implementation sheet — run --export-mini first'); return None
    UN = pd.concat([_rd(f, 'csv') for f in _os.listdir(out_dir) if f.endswith('_rescore_unarmed.csv')] or [pd.DataFrame()], ignore_index=True)
    # 05 — implementation, with the atoms split out
    IMP = I.copy()
    atoms = IMP['conditions'].astype(str).apply(laz_deploybook___terms)
    IMP['n_conditions'] = atoms.apply(len)
    for i in range(int(max(atoms.apply(len), default=0))):
        IMP[f'term_{i+1}'] = atoms.apply(lambda a, i=i: a[i][0] if len(a) > i else '')
        IMP[f'op_{i+1}'] = atoms.apply(lambda a, i=i: a[i][1] if len(a) > i else '')
        IMP[f'value_{i+1}'] = atoms.apply(lambda a, i=i: a[i][2] if len(a) > i else '')
    used = sorted({t for a in atoms for t, _o, _v in a})
    # 06 / 22 — lineage and definitions for exactly those terms
    if len(R):
        LIN = R[R['term'].isin(used)].drop_duplicates(['term', 'sport']).copy()
        miss = sorted(set(used) - set(LIN['term']))
        if miss:
            LIN = pd.concat([LIN, pd.DataFrame(dict(term=miss, sport='', status='NOT IN REGISTRY — rerun prepare() for this sport', kind='', inputs='', builder_site='', formula='', dtype='', coverage=None, first_seen='', last_seen='', engine_version='', wanted_by=''))], ignore_index=True)
        DEF = LIN[['term', 'sport', 'kind', 'inputs', 'builder_site', 'formula']].copy()
        # every strategy that references the term, not the first one
        _pairs = [(t, nm) for a, nm in zip(atoms, IMP['strategy_name'].astype(str)) for t, _o, _v in a]
        _by = {}
        for t, nm in _pairs:
            _by.setdefault(t, set()).add(nm)
        DEF['used_by_n'] = DEF['term'].map(lambda t: len(_by.get(t, ())))
        DEF['used_by_strategies'] = DEF['term'].map(lambda t: '|'.join(sorted(_by.get(t, ()))))
        # a frame column has no formula in the engine BECAUSE it comes from the extraction — say so
        _fc = DEF['kind'].astype(str).eq('frame') | DEF['builder_site'].astype(str).eq('frame column')
        DEF.loc[_fc, 'formula'] = 'EXTRACTION COLUMN — supplied by the warehouse (AB_<sport>.parquet), not computed by the engine'
        DEF.loc[_fc, 'inputs'] = DEF.loc[_fc, 'inputs'].fillna('(raw feed)')
        LIN.loc[LIN['builder_site'].astype(str).eq('frame column'), 'formula'] = 'EXTRACTION COLUMN — from the warehouse'
        DEF = DEF.sort_values(['used_by_n', 'term'], ascending=[False, True])
    else:
        LIN = pd.DataFrame(dict(term=used)); DEF = LIN.copy()
    # 01 — dashboard
    dash = I.groupby('sport', as_index=False).agg(strategies=('strategy_id', 'size'), median_oos_win_pct=('oos_win', 'median'), median_oos_roi_pct=('oos_roi', 'median'), min_n_oos=('n_oos', 'min'))
    if len(B):
        def _agg(D, suff):
            a = D.groupby('sport', as_index=False).agg(**{f'bets{suff}': ('db_outcome', 'size'), f'wins{suff}': ('db_outcome', lambda x: int((x == 'Win').sum())), f'profit{suff}': ('db_profit', 'sum')})
            # [v198 X2] ONE UNIT: PERCENT. This sheet carried median_oos_roi as a percent (28.30) beside
            # roi_all as a fraction (0.0598) with nothing to say so, and the owner reasonably read them as
            # contradicting each other. Every rate on this sheet is now a percent, and the column name says so.
            a[f'win_rate{suff}_pct'] = (100.0 * a[f'wins{suff}'] / a[f'bets{suff}']).round(2)
            a[f'roi{suff}_pct'] = (100.0 * a[f'profit{suff}'] / a[f'bets{suff}']).round(2)
            return a
        dash = dash.merge(_agg(B, '_all'), on='sport', how='left')   # every rate below is a PERCENT
        # OOS ONLY is the number to judge on: IS is where the thresholds were fitted
        if 'is_oos' in B.columns and B['is_oos'].notna().any():
            dash = dash.merge(_agg(B[B['is_oos'].astype(bool)], '_oos'), on='sport', how='left')
        dash = dash.merge(B.groupby('sport', as_index=False).agg(first_bet=('timestamp', 'min'), last_bet=('timestamp', 'max')), on='sport', how='left')
    tot = dict(sport='TOTAL', strategies=int(len(I)), bets_all=int(len(B)), wins_all=int((B['db_outcome'] == 'Win').sum()) if len(B) else 0, profit_all=float(B['db_profit'].sum()) if len(B) else 0.0)
    if tot['bets_all']:
        tot['win_rate_all_pct'] = round(100.0 * tot['wins_all'] / tot['bets_all'], 2); tot['roi_all_pct'] = round(100.0 * tot['profit_all'] / tot['bets_all'], 2)
    if len(B) and 'is_oos' in B.columns and B['is_oos'].notna().any():
        _o = B[B['is_oos'].astype(bool)]
        tot['bets_oos'] = int(len(_o)); tot['wins_oos'] = int((_o['db_outcome'] == 'Win').sum())
        tot['profit_oos'] = float(_o['db_profit'].sum())
        if len(_o):
            tot['win_rate_oos_pct'] = round(100.0 * tot['wins_oos'] / len(_o), 2); tot['roi_oos_pct'] = round(100.0 * tot['profit_oos'] / len(_o), 2)
    dash = pd.concat([dash, pd.DataFrame([tot])], ignore_index=True)
    prov = pd.DataFrame([dict(item='engine_version', value=str(globals().get('LAZ_ENGINE_VERSION', '?'))),
                         dict(item='generated', value=pd.Timestamp.now().strftime('%Y-%m-%d %H:%M')),
                         dict(item='source', value='automated_bet_mini.parquet — validated strategies only'),
                         dict(item='terms used', value=len(used)), dict(item='excluded', value=int(len(E))),
                         dict(item='flagged for review', value=int(len(F))), dict(item='did not re-arm', value=int(len(UN)))])
    fp = path or _os.path.join(out_dir, 'LAZARUS_DEPLOYMENT_BOOK.xlsx')
    with pd.ExcelWriter(fp, engine='openpyxl') as xw:
        try:   # [v204 F1] Aptos Narrow throughout, set on the workbook's Normal style so pandas-written sheets
            # inherit it too — styling each cell after the fact misses anything written by to_excel.
            _nrm = xw.book._named_styles['Normal']
            _nrm.font.name = 'Aptos Narrow'; _nrm.font.sz = 10
        except Exception:
            pass
        # [v197 D2] 00_GO_LIVE — everything needed to place these bets, on one row per strategy, in the order
        # a production engineer works: WHAT to bet, WHEN to arm it, WHAT PRICE to demand, HOW to settle it, and
        # WHETHER it is ready. Nothing here requires opening the engine or any other sheet.
        _rdy, _blk = [], []
        for _, r in IMP.iterrows():
            miss = []
            if not str(r.get('rt_columns', '')).strip():
                miss.append('no warehouse columns recorded for its terms')
            if not str(r.get('live_expression', '')).strip():
                miss.append('no live expression recorded')
            if not str(r.get('min_odds_req', '')).strip() or str(r.get('min_odds_req')) in ('nan', 'None'):
                miss.append('no minimum price')
            _rdy.append('READY' if not miss else 'BLOCKED')
            _blk.append('; '.join(miss))
        GL = pd.DataFrame(dict(
            ready=_rdy, blocked_because=_blk,
            strategy=IMP.get('strategy_name'), sport=IMP.get('sport'),
            market=IMP.get('market'), bet_on=IMP.get('side'),
            arm_when=IMP.get('conditions'),
            min_price=IMP.get('min_odds_req'),
            settle_rule=[('final margin vs the posted handicap' if str(m) == 'handicap'
                          else 'final total vs the posted line' if str(m) == 'totals'
                          else 'final result == the backed side') for m in IMP.get('market', pd.Series([''] * len(IMP)))],
            one_bet_per='match (never per tick — same match, same side, same 120s window is ONE bet)',
            warehouse_columns=IMP.get('rt_columns'),
            live_expression=IMP.get('live_expression'),
            applies_to_sport=IMP.get('applies_to'),
            measured_bets_oos=IMP.get('n_oos'), measured_roi_oos=IMP.get('oos_roi'),
            measured_win_oos=IMP.get('oos_win'),
            claimed_roi_at_discovery=IMP.get('claimed_oos_roi'),
            engine_version=IMP.get('validated_under'),
            definition_hashes=IMP.get('definition_hashes')))
        GL = GL.sort_values(['ready', 'measured_roi_oos'], ascending=[True, False])
        GL.to_excel(xw, sheet_name='00_GO_LIVE', index=False)
        try:
            laz_deploybook__cover(xw, I, B, S, dash, log=log)
        except Exception as _ce:
            log(f'  [deploybook] cover not written ({type(_ce).__name__}: {str(_ce)[:70]})')
        laz_deploybook__style(xw.book['00_GO_LIVE'], len(GL.columns), len(GL),
                              pct_cols=('measured_roi_oos', 'measured_win_oos', 'claimed_roi_at_discovery'),
                              wide=('arm_when', 'warehouse_columns', 'live_expression', 'blocked_because', 'settle_rule', 'one_bet_per'))
        laz_deploybook__colour_rules(xw.book['00_GO_LIVE'], len(GL), list(GL.columns),
                                     ready_col='ready', roi_cols=('measured_roi_oos',))
        # 02_HOW_TO_READ — the rules that are not obvious from a column name
        pd.DataFrame([
            dict(item='ready', meaning='READY = every term has warehouse columns, a live expression and a minimum price. BLOCKED = something is missing; blocked_because says what.'),
            dict(item='arm_when', meaning='Place the bet on the FIRST tick where every condition is true. Conditions are joined by AND. Each is `term OP number`.'),
            dict(item='min_price', meaning='Do not place below this price. The measured ROI assumes it.'),
            dict(item='one_bet_per', meaning='ONE bet per match. If the conditions are true again later in the same match, do not bet again.'),
            dict(item='measured_*_oos', meaning='Out-of-sample: the second half of the data by match start time, never used to choose the strategy. This is the number to trust.'),
            dict(item='claimed_roi_at_discovery', meaning='What it scored on the sample it was found on. A big gap to measured_roi_oos means it generalises poorly.'),
            dict(item='definition_hashes', meaning='What each term MEANT when this was validated. If a later engine changes a builder, the hash changes and the strategy must be re-scored before use.'),
            dict(item='warehouse_columns', meaning='The rt_* columns production must read to compute this strategy terms.'),
            dict(item='live_expression', meaning='The exact expression to evaluate from those columns.'),
            dict(item='settle_rule', meaning='How the bet is decided. A handicap PUSH (exact line) returns the stake and is not a win.'),
            dict(item='where the money is', meaning='measured_roi_oos is per bet, flat stake. 30_STRATEGY_PERFORMANCE has bets, wins, profit; 31_LEAGUE_PERFORMANCE splits it by league.'),
            dict(item='what is NOT here', meaning='Stake sizing, bankroll rules and market-open checks. The production stack owns those; a bet whose market is closed is refused at placement.'),
        ]).to_excel(xw, sheet_name='02_HOW_TO_READ', index=False)
        _D = dash.dropna(how='all')
        _D.to_excel(xw, sheet_name='01_Dashboard', index=False)
        laz_deploybook__style(xw.book['01_Dashboard'], len(_D.columns), len(_D),
                              pct_cols=tuple(c for c in _D.columns if str(c).endswith('_pct')),
                              money_cols=('profit_all', 'profit_oos'))
        laz_deploybook__colour_rules(xw.book['01_Dashboard'], len(_D), list(_D.columns),
                                     roi_cols=tuple(c for c in _D.columns if 'roi' in str(c)))
        prov.to_excel(xw, sheet_name='01_Dashboard', index=False, startrow=len(dash.dropna(how='all')) + 3)
        IMP.to_excel(xw, sheet_name='05_IMPLEMENTATION', index=False)
        laz_deploybook__style(xw.book['05_IMPLEMENTATION'], len(IMP.columns), len(IMP),
                              pct_cols=('oos_roi', 'is_roi', 'oos_win', 'is_win'),
                              wide=('conditions', 'rt_columns', 'live_expression', 'provenance_desc'))
        laz_deploybook__colour_rules(xw.book['05_IMPLEMENTATION'], len(IMP), list(IMP.columns), roi_cols=('oos_roi',))
        _bs = _os.environ.get('LAZ_BOOK_SPORT')
        if _bs:
            laz_deploybook__one_to_one(xw, I, B, _bs, log=log)
        LIN.to_excel(xw, sheet_name='06_FEATURE_LINEAGE', index=False)
        DEF.to_excel(xw, sheet_name='22_FEATURES_DEFINITIONS', index=False)
        (S if len(S) else pd.DataFrame()).to_excel(xw, sheet_name='30_STRATEGY_PERFORMANCE', index=False)
        (G if len(G) else pd.DataFrame()).to_excel(xw, sheet_name='31_LEAGUE_PERFORMANCE', index=False)
        (E if len(E) else pd.DataFrame()).to_excel(xw, sheet_name='40_EXCLUDED', index=False)
        (F if len(F) else pd.DataFrame()).to_excel(xw, sheet_name='41_FLAGGED', index=False)
        (UN if len(UN) else pd.DataFrame()).to_excel(xw, sheet_name='42_DID_NOT_REARM', index=False)
    _nr = sum(1 for x in _rdy if x == 'READY')
    # [v218 R1] NAME THE BLOCKED ONES IN THE LOG. A count alone makes a reader open a file to find out whether
    # anything is wrong; naming them means a clean run is obviously clean and a real problem is obviously real.
    _blk_names = [str(GL.iloc[_i]['strategy']) for _i in range(len(GL)) if _rdy[_i] != 'READY']
    if _blk_names:
        log(f'[deploybook] BLOCKED from production ({len(_blk_names)}): ' + ', '.join(_blk_names[:8])
            + (' ...' if len(_blk_names) > 8 else '') + ' -- see 00_GO_LIVE.blocked_because for the reason on each')
    else:
        log('[deploybook] every strategy in this bundle is READY to place -- none blocked')
    try:   # [v201 X4] give every formula a cached value, so the file reads correctly outside Excel too
        import subprocess as _sp, shutil as _sh
        _so = _sh.which('soffice') or _sh.which('libreoffice')
        if _so:
            _sp.run([_so, '--headless', '--convert-to', 'xlsx', '--outdir', _os.path.dirname(fp) or '.', fp],
                    capture_output=True, timeout=180)
    except Exception:
        pass
    log(f'[deploybook] {_os.path.basename(fp)} · {len(I)} strategies · {_nr} READY to place, {len(I) - _nr} BLOCKED (see 00_GO_LIVE.blocked_because) · {len(used)} distinct terms · 11 sheets')
    return fp

def laz_mini__build(sports, frames_dir, out_dir='.', log=print, engine_version='v188'):
    """Reads mode3_<sport>.parquet (the bet ledger of the newest run) + mode3_<sport>_legs.csv (the validated
    pool) + the sport frame, and writes FOUR parquets to out_dir:
      automated_bet_mini.parquet                 one row per bet, all sports, timestamp ASC
      automated_bet_mini_implementation.parquet  one row per strategy: id, nr, name, definition, metrics
      strategy_performance.parquet               per strategy: n_bets, wins, win_rate, roi, profit ...
      league_level_strategy_performance.parquet  per strategy x league: n_bets, win_rate, roi
    Columns absent from a sport's frame (market_status, selection_status_*, match_name) are null for that sport."""
    import hashlib, os as _os, glob as _glob
    import pyarrow.parquet as _pq
    rows_all, impl_all, excl_all, flag_all = [], [], [], []
    _sport_errors = {}
    for sport in sports:
        try:   # [v192 E2] ONE SPORT MUST NOT KILL THE BUNDLE. A single sport raised at the very last step
            # of a 50-minute run and took the whole export with it, after every sport had already been
            # harvested and screened. A sport that fails is now reported by name and the rest still export.
            # [v188 M2] HARVEST every ledger this sport ever wrote — the plain run, every batch<b>_ run, and any
            # sub-directory (a crashed run still leaves the ledgers it had written). Ledgers are concatenated and the
            # bets deduplicated on (strategy, match, side, tick); legs come from every matching legs csv.
            fr_p = _os.path.join(frames_dir, f'AB_{sport}.parquet')
            pats = [f'mode3_{sport}.parquet', f'batch*_mode3_{sport}.parquet', f'*/mode3_{sport}.parquet', f'*/batch*_mode3_{sport}.parquet']
            led_files = sorted({f for pat in pats for f in _glob.glob(_os.path.join(out_dir, pat))})
            legs_files = sorted({f for pat in pats for f in _glob.glob(_os.path.join(out_dir, pat.replace('.parquet', '_legs.csv')))})
            if not led_files or not _os.path.exists(fr_p):
                log(f'[mini] {sport}: skipped ({"no ledger on disk" if not led_files else "no frame"})'); continue
            _parts = []
            for f in led_files:
                try:
                    _t = pd.read_parquet(f); _t['_source'] = _os.path.basename(f); _parts.append(_t)
                except Exception as e:
                    log(f'[mini] {sport}: {_os.path.basename(f)} unreadable ({type(e).__name__}) — skipped')
            L = pd.concat(_parts, ignore_index=True) if _parts else pd.DataFrame()
            _lg = []
            for f in legs_files:
                try:
                    _t = pd.read_csv(f); _t['_source'] = _os.path.basename(f); _lg.append(_t)
                except Exception:
                    pass
            legs = pd.concat(_lg, ignore_index=True).drop_duplicates('strategy_name', keep='last') if _lg else pd.DataFrame()
            if len(L):
                L = L.drop_duplicates(['strategy_name', 'mid', 'side', 'ts'], keep='first')
            log(f'[mini] {sport}: harvested {len(led_files)} ledger file(s) -> {len(L):,} distinct bets · {len(legs)} validated legs from {len(legs_files)} legs file(s)')
            if len(legs) and 'strategy_name' in legs.columns:
                # [v188 M2] THE SCREEN. A leg reaches production only if it is in the validated pool AND clears every
                # bar below. Everything refused is written to <sport>_excluded_strategies.csv with its reason — the
                # list is part of the deliverable, not a silence.
                _sc = legs.copy()
                _sc['implied'] = 100.0 / pd.to_numeric(_sc.get('oos_odds', _sc.get('odds')), errors='coerce')
                _sc['over_price'] = pd.to_numeric(_sc['oos_win'], errors='coerce') - _sc['implied']
                _why = {}
                def _mark(mask, reason):
                    for nm in _sc.loc[mask.fillna(False), 'strategy_name'].astype(str):
                        _why.setdefault(nm, reason)
                # [v191 M3] the TERM screen first: a condition naming a live-certainty, clock-divided, full-match-rank,
                # market-certainty or settlement term is refused whatever its numbers say. LAZ_MINI_TERMS=off disables.
                _mode = _os.environ.get('LAZ_MINI_TERMS', 'on')
                if _mode != 'off':
                    _scr = _sc['conditions'].astype(str).apply(laz_mini__screen_terms)
                    _dn = _scr.apply(lambda x: x[0]); _sf = _scr.apply(lambda x: x[1])
                    _mark(_dn.apply(bool), 'NOT IMPLEMENTABLE')
                    for _nm, _h in zip(_sc['strategy_name'].astype(str), _dn):
                        if _h and _why.get(_nm) == 'NOT IMPLEMENTABLE':
                            _why[_nm] = 'NOT IMPLEMENTABLE (reads the future or the result): ' + ','.join(_h[:4])
                    if _mode == 'strict':
                        _mark(_sf.apply(bool), 'LIVE PRICE LEVEL (strict)')
                        for _nm, _h in zip(_sc['strategy_name'].astype(str), _sf):
                            if _h and _why.get(_nm) == 'LIVE PRICE LEVEL (strict)':
                                _why[_nm] = 'LIVE PRICE LEVEL (strict): ' + ','.join(_h[:4])
                    _nsoft = int((_sf.apply(bool) & ~_sc['strategy_name'].astype(str).isin(set(_why))).sum())
                    if _nsoft:
                        log(f'  [mini] {sport}: {_nsoft} kept strategies use a live price level — implementable, flagged in uses_live_level (LAZ_MINI_TERMS=strict would refuse them)')
                # [v191 M3d] A HIGH WIN RATE IS NOT A REASON TO REFUSE A BET. A 99% winner at 1.49 that you can
                # actually place is money. What disqualifies a strategy is that the bet could not be placed: the match
                # was already over when it fired (entry_prog), or the quote it was priced at had stopped existing
                # (n_playable_seconds <= 0 -> 'Obsolete'). Those are tested below and refused on the evidence.
                # >=95% OOS win and >=40 points over the implied price are recorded as REVIEW FLAGS, not refusals:
                # they mark the strategies most worth checking against a real placed bet before you scale the stake.
                # LAZ_MINI_REFUSE_HIGHWIN=1 restores the old behaviour if you ever want it.
                _extreme = (pd.to_numeric(_sc['oos_win'], errors='coerce') >= 95) | (_sc['over_price'] >= 40)
                if bool(_extreme.any()) and _os.environ.get('LAZ_MINI_REFUSE_HIGHWIN', '0') != '1':
                    # [v191] a high win rate is NOT a refusal: a 99% winner you can place is money, and the win rate
                    # cannot separate that from a leak. The re-score under current truth is the proof; this is a note.
                    _fl = _sc.loc[_extreme, ['strategy_name', 'oos_win', 'over_price', 'n_oos', 'conditions']].copy()
                    _fl.insert(0, 'sport', sport)
                    _fl['note'] = 'extreme edge — KEPT; verify against a real placed bet before scaling the stake'
                    flag_all.append(_fl)
                    log(f'  [mini] {sport}: {int(_extreme.sum())} strategies carry an extreme edge — KEPT and listed in flagged_strategies.csv')
                if _os.environ.get('LAZ_MINI_REFUSE_HIGHWIN', '0') == '1':
                    _mark(pd.to_numeric(_sc['oos_win'], errors='coerce') >= 95, 'OOS win >= 95% (refuse-highwin mode)')
                    _mark(_sc['over_price'] >= 40, '>= 40 points over the implied price (refuse-highwin mode)')
                # [v196 R1] MEASURE THE BAR ON THE LEDGER, NOT ON THE DISCOVERY SAMPLE.
                #
                # THE DEFECT. `oos_roi` and `n_oos` in the legs file are what the strategy scored WHEN IT WAS
                # FOUND — on a strided, windowed sample. The ledger holds what it actually did across the whole
                # frame after the re-score. On the owner's 9 Sep bundle those disagreed badly: one football leg
                # claimed +196.7% on 217 out-of-sample bets and the ledger showed -44.5% on 3,311. Not a
                # duplication artefact — 1,478 bets across 1,478 distinct matches, zero duplicates. The
                # strategy simply looked good on a sample and lost money on everything.
                #
                # 104 of 625 strategies claimed profit and lost. Three whole sports flipped sign: basketball
                # +32.8 -> -8.6, eBasketball +42.0 -> -6.2, esports +40.6 -> -7.9. The bar was checking the
                # certificate instead of the result.
                #
                # From here the bar reads the LEDGER. The discovery figures are kept alongside as
                # `claimed_oos_roi` / `claimed_n_oos` so the gap is visible rather than silently overwritten —
                # a large gap is itself a finding about how well that strategy generalises.
                try:
                    _oo = L[L['is_oos'].astype(bool)] if 'is_oos' in L.columns else L
                    _g = _oo.groupby('strategy_name')
                    _real_n = _g.size()
                    _real_roi = _g.apply(lambda x: 100.0 * (x['won'].astype(float) * x['price'].astype(float) - 1).mean(), include_groups=False) \
                                if {'won', 'price'} <= set(_oo.columns) else None
                    _nm = _sc['strategy_name'].astype(str)
                    _sc['claimed_oos_roi'] = pd.to_numeric(_sc['oos_roi'], errors='coerce')
                    _sc['claimed_n_oos'] = pd.to_numeric(_sc['n_oos'], errors='coerce')
                    _mn = _nm.map(_real_n)
                    _sc['n_oos'] = _mn.where(_mn.notna(), _sc['claimed_n_oos'])
                    if _real_roi is not None:
                        _mr = _nm.map(_real_roi)
                        _sc['oos_roi'] = _mr.where(_mr.notna(), _sc['claimed_oos_roi'])
                        _flip = int(((_sc['claimed_oos_roi'] > 0) & (_sc['oos_roi'] <= 0)).sum())
                        if _flip:
                            log(f'  [mini] {sport}: {_flip} strategies scored positive when found and NEGATIVE on the full ledger — the bar now uses the ledger')
                except Exception as _re_:
                    log(f'  [mini] {sport}: could not recompute the bar from the ledger ({type(_re_).__name__}) — falling back to the discovery figures, WHICH MAY OVERSTATE')
                _mark(pd.to_numeric(_sc['oos_roi'], errors='coerce') <= 0, 'OOS ROI <= 0 (measured on the ledger)')
                _mark(pd.to_numeric(_sc['is_roi'], errors='coerce') <= 0, 'IS ROI <= 0')
                # [v193 O1] THE OWNER BAR IS THE BAR — n_is >= 100 AND n_oos >= 100 AND OOS ROI > 0.
                #
                # THE DEFECT THIS FIXES. The volume floors carried an escape hatch: a strategy was only refused
                # if its measured n was below the floor AND fewer than 2x the floor bets had been harvested.
                # A strategy with 98 OOS bets and 250 harvested slips therefore passed a floor of 100. The owner
                # stated the bar plainly — "n_is >= 100, n_oos >= 100, ROI > 0, else they are not validated" —
                # and the export was checking something looser. The harvest count is EVIDENCE ABOUT A DIFFERENT
                # POPULATION (every slip ever written for that leg, across runs and machines); it cannot stand in
                # for the measured out-of-sample count that the bar is about.
                #
                # The hatch is gone. LAZ_MINI_HARVEST_RELIEF=1 restores the old behaviour for a deliberate
                # experiment, and says so in the reason text so it can never be mistaken for a clean pass.
                _mn_o = int(_os.environ.get('LAZ_MINI_MIN_OOS', 100)); _mn_i = int(_os.environ.get('LAZ_MINI_MIN_IS', 100))
                _bets = L.groupby('strategy_name').size()   # bets harvested for this leg, across every run
                _sc['_harvested'] = _sc['strategy_name'].astype(str).map(_bets).fillna(0)
                _relief = _os.environ.get('LAZ_MINI_HARVEST_RELIEF') == '1'
                _n_o = pd.to_numeric(_sc['n_oos'], errors='coerce').fillna(0)
                _n_i = pd.to_numeric(_sc['n_is'], errors='coerce').fillna(0)
                _mark((_n_o < _mn_o) & ((_sc['_harvested'] < 2 * _mn_o) if _relief else True), f'n_oos below the OWNER BAR ({_mn_o})' + (' and too few harvested bets' if _relief else ''))
                _mark((_n_i < _mn_i) & ((_sc['_harvested'] < 2 * _mn_i) if _relief else True), f'n_is below the OWNER BAR ({_mn_i})' + (' and too few harvested bets' if _relief else ''))
                if 'verdict' in _sc.columns:
                    _mark(~_sc['verdict'].astype(str).str.lower().isin(['pass', 'ok', 'validated', 'true', '1', 'accept', 'accepted', '']), 'verdict is not PASS')
                # [v191] placeability is not re-tested here: the production stack refuses a bet whose market is not open,
                # and a RE-SCORED ledger was armed under the current pool. Nothing is refused for a high win rate.
                # [v191] placeability is not re-tested here: the production stack refuses a bet whose market is not open,
                # and a RE-SCORED ledger was armed under the current pool. Nothing is refused for a high win rate.
                try:   # [v192 P2] the provenance gate: every term of a deployable strategy must have a production recipe
                    _tab = laz_provenance__derive(sport, {}, None, log=None)   # frame columns are not needed to READ the merged table
                    _okn, _bad = laz_provenance__check(zip(_sc['strategy_name'].astype(str), _sc['conditions'].astype(str)), table=_tab, log=log)
                    for _nm, _terms in _bad.items():
                        _why.setdefault(_nm, 'NO PRODUCTION RECIPE for ' + ','.join(_terms[:4]) + ' — write the FEATURE_PROVENANCE entry or the builder before deploying')
                except Exception as _e:
                    log(f'  [mini] provenance gate skipped ({type(_e).__name__}: {str(_e)[:60]})')
                _keep = set(_sc['strategy_name'].astype(str)) - set(_why)
                if _why:
                    excl_all.append(pd.DataFrame(dict(sport=sport, strategy_name=list(_why), reason=[_why[k] for k in _why])))
                    log(f'[mini] {sport}: {len(_why)} strategies EXCLUDED by the screen · {len(_keep)} remain' + (f' · e.g. {list(_why.items())[0]}' if _why else ''))
                legs = legs[legs['strategy_name'].astype(str).isin(_keep)]
                L = L[L['strategy_name'].isin(_keep)]
            if not len(L):
                log(f'[mini] {sport}: ledger has no rows for the validated pool'); continue
            need = ['match_id', 'ts', 'h_score', 'a_score', 'phase', 'prog', 'minute', 'league_time_progress', 'league', 'match_name', 'market_status', 'selection_status_home_odds', 'selection_status_draw_odds', 'selection_status_away_odds', 'selection_status_total_goals_over', 'selection_status_total_goals_under', 'home_odds', 'draw_odds', 'away_odds', 'total_goals_over', 'total_goals_under', 'total_points_over', 'total_points_under', 'point_spread_home', 'point_spread_away', 'point_spread_handicap', 'goal_spread_home', 'goal_spread_away', 'maps_handicap_home', 'maps_handicap_away', 'maps_handicap_handicap'] + [f'map_{_n}_winner_{_s}' for _n in range(1, 7) for _s in ('home', 'away')]   # [v246-SPR]
            have = _pq.ParquetFile(fr_p).schema_arrow.names
            F = pd.read_parquet(fr_p, columns=[c for c in need if c in have]).sort_values(['match_id', 'ts'], kind='stable').reset_index(drop=True)
            F['ts'] = pd.to_datetime(F['ts']).astype('datetime64[ns]'); F['match_id'] = F['match_id'].astype(str)   # [AmunEV V2.10 FIX B] the frame is [us], the ledger [ns] (or the reverse) — pandas refuses to merge them; both to [ns]
            L = L.copy(); L['ts'] = pd.to_datetime(L['ts']).astype('datetime64[ns]'); L['mid'] = L['mid'].astype(str)
            L['min_odds_req'] = pd.to_numeric(L['band'].astype(str).str.split('-').str[0], errors='coerce').fillna(1.4) if 'band' in L.columns else 1.4
            _mk_of = dict(zip(legs['strategy_name'].astype(str), legs['market'].astype(str))) if len(legs) and 'market' in legs.columns else {}   # [v246-SPR]
            _bs_of = dict(zip(legs['strategy_name'].astype(str), legs['base'].astype(str))) if len(legs) and 'base' in legs.columns else {}
            L['odds_col'] = [laz_mini___odds_col(sport, sd, F.columns, market=_mk_of.get(str(nm)), base=_bs_of.get(str(nm))) for sd, nm in zip(L['side'], L['strategy_name'])]
            nr_map = dict(zip(legs['strategy_name'].astype(str), legs['strategy_no'])) if len(legs) and 'strategy_no' in legs.columns else {}
            # the id is the STRATEGY (sport, base, market, conditions); the side is per BET (a lead_ml base backs whoever leads)
            L['strategy_id'] = ['S' + hashlib.sha1(f"{sport}|{b}|{m}|{c}".encode()).hexdigest()[:10].upper() for b, m, c in zip(L['base'], L['market'], L['conditions'])]
            P = L.merge(F, left_on=['mid', 'ts'], right_on=['match_id', 'ts'], how='left', suffixes=('', '_f'))
            out = pd.DataFrame(dict(match_id=P['mid'].values, timestamp=P['ts'].values))
            out['match_name'] = P['match_name'].values if 'match_name' in P.columns else None
            out['sport'] = sport
            out['bet_strategy'] = P['strategy_name'].values; out['strategy_id'] = P['strategy_id'].values; out['strategy_nr'] = P['strategy_name'].map(nr_map).values
            out['combination_tier'] = P['combo_tier'].values if 'combo_tier' in P.columns else None
            out['league'] = P['league_f'].values if 'league_f' in P.columns else (P['league'].values if 'league' in P.columns else None)
            out['bet_outcome'] = P['side'].astype(str).str.lower().map(laz_mini__SIDE_LABEL).fillna(P['side'].astype(str)).values
            out['min_odds_req'] = P['min_odds_req'].values; out['bet_placement_odds'] = P['price'].values; out['betsite_probability'] = (1.0 / P['price']).values
            hs = pd.to_numeric(P['h_score'], errors='coerce') if 'h_score' in P.columns else pd.Series(np.nan, index=P.index)
            as_ = pd.to_numeric(P['a_score'], errors='coerce') if 'a_score' in P.columns else pd.Series(np.nan, index=P.index)
            out['db_betplacement_scores'] = [f'{int(a)}-{int(b)}' if pd.notna(a) and pd.notna(b) else None for a, b in zip(hs, as_)]
            out['phase'] = P['phase'].values if 'phase' in P.columns else None
            out['is_oos'] = P['is_oos'].values if 'is_oos' in P.columns else None
            # [v191 M4] VECTORISED. The per-bet Python loop cost hours on a million-bet ledger. Same definitions:
            #   last_obs_*      = the last row of the match whose odds column for THIS bet's side is a real quote (>1.0)
            #   n_playable_secs = seconds from entry to the first tick at/after it where that quote falls below
            #                     min_odds_req, or the market/selection status stops being open; the last valid tick
            #                     if that never happens. merge_asof(direction='forward', by=match) does it in one pass.
            n = len(P)
            ss_cols = [c for c in F.columns if c.startswith('selection_status_')]
            P = P.reset_index(drop=True); P['_row'] = np.arange(n)
            n_play = np.full(n, np.nan); last_ts = np.full(n, np.datetime64('NaT'), dtype='datetime64[ns]')
            last_ph = np.array([None] * n, dtype=object); last_sc = np.array([None] * n, dtype=object)
            last_ms = np.array([None] * n, dtype=object); last_ss = {c: np.array([None] * n, dtype=object) for c in ss_cols}
            for oc in sorted({c for c in P['odds_col'].dropna().unique() if c in F.columns}):
                sel = P['odds_col'] == oc
                if not sel.any():
                    continue
                q = pd.to_numeric(F[oc], errors='coerce')
                V = F.loc[q > 1.0, ['match_id', 'ts'] + [c for c in ('phase', 'h_score', 'a_score', 'market_status') + tuple(ss_cols) if c in F.columns]]
                LV = V.groupby('match_id', sort=False).tail(1).set_index('match_id')
                B = P.loc[sel, ['_row', 'mid', 'ts', 'min_odds_req', 'market']].copy()
                idx = B['_row'].to_numpy()
                last_ts[idx] = LV['ts'].reindex(B['mid']).to_numpy()
                if 'phase' in LV.columns: last_ph[idx] = LV['phase'].reindex(B['mid']).to_numpy()
                if {'h_score', 'a_score'} <= set(LV.columns):
                    _h = pd.to_numeric(LV['h_score'].reindex(B['mid']), errors='coerce'); _a = pd.to_numeric(LV['a_score'].reindex(B['mid']), errors='coerce')
                    last_sc[idx] = np.where(_h.notna().to_numpy() & _a.notna().to_numpy(), pd.Series(_h.fillna(0).astype('int64').astype(str).to_numpy()) + '-' + pd.Series(_a.fillna(0).astype('int64').astype(str).to_numpy()), None)
                if 'market_status' in LV.columns: last_ms[idx] = LV['market_status'].reindex(B['mid']).to_numpy()
                for c in ss_cols: last_ss[c][idx] = LV[c].reindex(B['mid']).to_numpy()
                sc_col = f'selection_status_{oc}'
                for (thr, mkt), grp in B.groupby(['min_odds_req', 'market'], sort=False):
                    dead = q < float(thr)
                    if str(mkt).lower() == 'moneyline' and 'market_status' in F.columns:
                        _st = F['market_status']; dead = dead | (_st.notna() & (_st.astype(str).str.lower() != 'open'))
                    elif sc_col in F.columns:
                        _st = F[sc_col]; dead = dead | (_st.notna() & (_st.astype(str).str.lower() != 'open'))
                    # [v192 E1] merge_asof REFUSES null keys — "Merge keys contain null values on right side" killed
                    # the whole export after every sport had been screened. A tick with no match_id or no timestamp
                    # cannot anchor a playable-seconds lookup, so drop those rows explicitly and report the count
                    # rather than letting pandas abort the run at the last step.
                    D = F.loc[dead.fillna(False), ['match_id', 'ts']].rename(columns={'ts': 'dead_ts'})
                    _nD = len(D)
                    D = D.dropna(subset=['match_id', 'dead_ts']).sort_values('dead_ts', kind='stable')
                    if len(D) < _nD:
                        log(f'  [mini] {sport}: {_nD - len(D):,} tick(s) had a null match_id or timestamp and cannot anchor a playable-seconds lookup — skipped')
                    g = grp.dropna(subset=['mid', 'ts']).sort_values('ts', kind='stable')
                    if len(D):
                        mg = pd.merge_asof(g, D, left_on='ts', right_on='dead_ts', left_by='mid', right_by='match_id', direction='forward')
                    else:
                        mg = g.assign(dead_ts=pd.NaT)
                    end = mg['dead_ts'].fillna(pd.Series(last_ts[mg['_row'].to_numpy()], index=mg.index))
                    n_play[mg['_row'].to_numpy()] = (pd.to_datetime(end) - pd.to_datetime(mg['ts'])).dt.total_seconds().to_numpy()
            P = P.drop(columns=['_row'])
            _noc = int(P['odds_col'].isna().sum())
            if _noc:
                log(f'  [mini] {sport}: {_noc:,} of {n:,} bets have no odds column for their side ({sorted(set(P.loc[P.odds_col.isna(), "side"].astype(str)))[:6]}) — n_playable_seconds and the last-observation columns are null for those rows')
            # [v191 M3c] WHERE THE BETS ARE PLACED — measured, not inferred from a name. `prog` (or minute/nominal)
            # at the entry tick says how far into the match the bet goes on. A strategy whose bets sit at prog >= 0.99
            # is placing after the match is effectively over: not placeable, whatever the column names say. This is the
            # test that catches a pre-fix full-match rank or a collapsed remaining-time divisor, and it catches them by
            # behaviour. LAZ_MINI_MAX_ENTRY_PROG overrides the 0.99 bar.
            _pg = None
            for _c in ('prog', 'league_time_progress'):
                if _c in P.columns and pd.to_numeric(P[_c], errors='coerce').notna().mean() > 0.5:
                    _pg = pd.to_numeric(P[_c], errors='coerce'); break
            if _pg is None and 'phase' in P.columns:      # quarter sports: the clock is in phase, the length in league
                _lg = P['league_f'] if 'league_f' in P.columns else (P['league'] if 'league' in P.columns else pd.Series([None] * len(P), index=P.index))
                _pg = pd.Series([laz_mini__entry_prog(a, b, sport) for a, b in zip(P['phase'], _lg)], index=P.index)
                log(f'  [mini] {sport}: entry position read from phase+league on {_pg.notna().mean():.0%} of bets (quarter sports carry the clock in `phase` and the length in `league`)')
            if (_pg is None or _pg.notna().mean() < 0.5) and 'minute' in P.columns:
                _mn = pd.to_numeric(P['minute'], errors='coerce'); _nom = float(np.nanpercentile(_mn.dropna(), 97)) if _mn.notna().any() else 0.0
                _pg = _mn / _nom if _nom > 0 else _pg
            out['entry_prog'] = _pg.to_numpy() if _pg is not None else np.nan
            out['n_playable_seconds'] = n_play
            out['playable_categorization'] = np.where(pd.Series(n_play).fillna(1e9).values <= 10, 'Obsolete', 'Playable')
            out['last_obs_timestamp'] = last_ts; out['last_obs_phase'] = last_ph; out['db_lastobs_scores'] = last_sc
            won = P['won'].astype(bool).values
            out['db_outcome'] = np.where(won, 'Win', 'Lose'); out['db_profit'] = np.where(won, P['price'].values - 1.0, -1.0)
            out['market_status'] = last_ms
            for c in ('selection_status_home_odds', 'selection_status_draw_odds', 'selection_status_away_odds', 'selection_status_total_goals_over', 'selection_status_total_goals_under'):
                out[c] = last_ss.get(c, [None] * n)
            try:   # [v188 M2] the owner's rule across everything harvested: same match + side + tick (<120 s) on >=90% of bets = one strategy
                _rws = [dict(strategy_name=nm, oos_roi=float(legs.loc[legs.strategy_name == nm, 'oos_roi'].iloc[0]) if (legs.strategy_name == nm).any() else 0.0, bets=int((L.strategy_name == nm).sum()), origin='book') for nm in sorted(set(L['strategy_name'].astype(str)))]
                _lds = {nm: dict(mid=L.loc[L.strategy_name == nm, 'mid'].values, ts=L.loc[L.strategy_name == nm, 'ts'].values, side=L.loc[L.strategy_name == nm, 'side'].values) for nm in [r['strategy_name'] for r in _rws]}
                _kept, _kl, _dd = _m('laz_mode3').dedupe_by_firing(_rws, _lds, log, sport)   # [v191] sibling reached through the resolver, per the build convention
                _names = {r['strategy_name'] for r in _kept}
                if _dd['removed']:
                    excl_all.append(pd.DataFrame(dict(sport=sport, strategy_name=[a for a, b, c, d in _dd['pairs']], reason=[f'duplicate firing of {b} ({c}/{d} bets coincide)' for a, b, c, d in _dd['pairs']])))
                out = out[out['bet_strategy'].isin(_names)]; legs = legs[legs['strategy_name'].astype(str).isin(_names)]
                L = L[L['strategy_name'].astype(str).isin(_names)]   # [v191] the dedupe must reach the implementation sheet too
            except Exception as _e:
                log(f'[mini] {sport}: dedupe skipped ({type(_e).__name__}: {str(_e)[:70]})')
            rows_all.append(out)
            keep = [c for c in ('strategy_id', 'strategy_name', 'base', 'market', 'side', 'conditions', 'min_odds_req', 'combo_tier', 'is_win', 'oos_win', 'is_roi', 'oos_roi', 'n_is', 'n_oos', 'bets', 'odds', 'origin') if c in L.columns]
            imp = L.drop_duplicates('strategy_name')[keep].copy(); imp.insert(0, 'sport', sport)
            imp['strategy_nr'] = imp['strategy_name'].map(nr_map); imp['bet_outcome'] = imp['side'].astype(str).str.lower().map(laz_mini__SIDE_LABEL).fillna(imp['side']); imp['engine_version'] = engine_version
            imp['uses_live_level'] = imp['conditions'].astype(str).apply(lambda c: ','.join(laz_mini__screen_terms(c)[1][:4]))
            try:   # [v192 V2] the credentials this strategy was validated under
                # [v197 P6] THE FULL TABLE, NOT JUST THE HAND-WRITTEN 46. This read laz_featdoc__provenance()
                # alone — the hand-written entries — so rt_columns and live_expression were blank for roughly
                # half of every bundle. A production engineer holding that sheet could not implement those
                # strategies. laz_provenance__derive merges the hand-written table with the entries derived from
                # the frame, the genome registry, the builder line and manufactured parentage.
                _src2 = laz_sidecar___engine_source().split('\n')
                _tab2 = laz_provenance__derive(sport, {}, None, log=None) or laz_featdoc__provenance()
                _pins = imp['conditions'].astype(str).apply(lambda c: laz_featdoc__pin_conditions(c, _src2, _tab2))
                imp['element_ids'] = _pins.apply(lambda d: '|'.join(v[0] for v in d.values()))
                imp['definition_hashes'] = _pins.apply(lambda d: '|'.join(f'{k}={v[1]}' for k, v in d.items()))
                imp['validated_under'] = str(globals().get('LAZ_ENGINE_VERSION', '?'))
                # [v192 V3] THE RECIPE TRAVELS WITH THE STRATEGY. rt_columns, live_expression and applies_to were in
                # FEATURE_REGISTRY and in the workbook's lineage sheets — correct, but not where a production
                # engineer reads. Anyone handed automated_bet_mini_implementation.parquet alone can now implement
                # every term of every strategy without opening the engine or any other file.
                def _recipe(c, key):
                    out = []
                    for t in sorted(laz_mini__terms_of(c)):
                        e = _tab2.get(t) or {}
                        v = ('|'.join(e.get('rt', [])) if key == 'rt' else str(e.get(key, '')))
                        if v:
                            out.append(f'{t}: {v}')
                    return ' ;; '.join(out)
                imp['rt_columns'] = imp['conditions'].astype(str).apply(lambda c: _recipe(c, 'rt'))
                imp['live_expression'] = imp['conditions'].astype(str).apply(lambda c: _recipe(c, 'live'))
                imp['provenance_desc'] = imp['conditions'].astype(str).apply(lambda c: _recipe(c, 'desc'))
                imp['applies_to'] = imp['conditions'].astype(str).apply(
                    lambda c: '|'.join(sorted({laz_featdoc__sport_of(t, _src2) or '?' for t in laz_mini__terms_of(c)})))
            except Exception as _e:
                log(f'  [mini] credentials not pinned ({type(_e).__name__}: {str(_e)[:60]}) — a later builder change will NOT be detectable for these strategies')
            try:
                imp['median_entry_prog'] = imp['strategy_name'].map(out.groupby('bet_strategy')['entry_prog'].median()).round(3)
                imp['playable_share'] = imp['strategy_name'].map(out.groupby('bet_strategy')['playable_categorization'].apply(lambda x: float((x != 'Obsolete').mean()))).round(3)
                imp['review_flag'] = np.where(pd.to_numeric(imp['oos_win'], errors='coerce') >= 95, 'HIGH WIN >=95% — verify against a real placed bet', np.where((pd.to_numeric(imp['oos_win'], errors='coerce') - 100.0 / pd.to_numeric(imp['odds'], errors='coerce')) >= 40, '>=40 pts over implied — verify against a real placed bet', ''))
            except Exception:
                pass
            if len(legs) and 'selection_rule' in legs.columns:
                imp['selection_rule'] = imp['strategy_name'].map(dict(zip(legs['strategy_name'].astype(str), legs['selection_rule'])))
            impl_all.append(imp)
            log(f'[mini] {sport}: {len(out):,} bets from {len(imp)} validated strategies · status columns {"present" if "market_status" in F.columns else "ABSENT in this frame (null)"}')
        except Exception as _se:
            import traceback as _tb
            _sport_errors[sport] = f'{type(_se).__name__}: {str(_se)[:120]}'
            log(f'[mini] {sport}: FAILED — {_sport_errors[sport]}. The other sports still export; this one is missing from the bundle.')
            log('[mini]   ' + _tb.format_exc().strip().splitlines()[-3][:160])
    if not rows_all:
        log('[mini] nothing to export'); return None
    B = pd.concat(rows_all, ignore_index=True).sort_values('timestamp', kind='stable').reset_index(drop=True)
    I = pd.concat(impl_all, ignore_index=True)
    I = I.rename(columns={'strategy_nr': 'strategy_no_sport'})   # the per-sport number from the legs file, kept
    I = I.sort_values(['sport', 'strategy_name'], kind='stable').reset_index(drop=True)
    I['strategy_nr'] = range(1, len(I) + 1)                          # the GLOBAL number: unique across sports, version control
    B = B.drop(columns=['strategy_nr']).merge(I[['strategy_id', 'strategy_nr']].drop_duplicates('strategy_id'), on='strategy_id', how='left')
    _orphan = int((~B['strategy_id'].isin(set(I['strategy_id']))).sum())
    if _orphan:
        log(f'[mini] {_orphan:,} bets had no documented strategy (a ledger row whose leg was screened out) — REMOVED')
        B = B[B['strategy_id'].isin(set(I['strategy_id']))].reset_index(drop=True)
    B = B[B['strategy_nr'].notna()].reset_index(drop=True)
    # [v198 X1] RECONCILE EVERY PUBLISHED FIGURE AGAINST THE BETS THAT ACTUALLY SHIP.
    #
    # THE DEFECT, found by the owner reading the workbook. Basketball had ONE strategy, so its median ROI must
    # equal that strategy's ROI. The sheet said 28.3%; the bets said 0.39 profit over 122 bets = 0.32%. The bet
    # counts disagreed too: 146 against 122.
    #
    # Same price column, DIFFERENT POPULATIONS. The bar was measured on the harvested ledger; the bundle holds
    # only what survives dedupe, the entry screen and playability. A strategy was judged on 146 bets and shipped
    # with 122 — and the 24 dropped were not a random sample, so the two numbers could differ by any amount.
    # A strategy could pass the bar on bets it does not deliver.
    #
    # From here the bar is measured on B, the exported rows. A strategy whose SHIPPED bets fail is removed with
    # them, and n_oos / oos_roi / oos_win are recomputed from the survivors — so the workbook, the parquets and
    # the ledger are the same arithmetic on the same rows and cannot disagree.
    # [v205 M1-M3] THREE DEFECTS FOUND BY AUDITING THE BUNDLE BEFORE REAL MONEY. Each one INFLATES measured
    # performance, so each one would have cost money in production.
    try:
        _n0 = len(B)
        # M1 — A BET BELOW ITS OWN MINIMUM PRICE COULD NOT HAVE BEEN PLACED. 195 of 1,340 bets were recorded at
        # a price under min_odds_req (one at 1.02 against a 1.40 minimum). Production refuses those, so counting
        # them in the ROI credits the strategy with money it could never have won. Removed.
        if {'bet_placement_odds', 'min_odds_req'} <= set(B.columns):
            _bo = pd.to_numeric(B['bet_placement_odds'], errors='coerce').astype('float64')
            _mo = pd.to_numeric(B['min_odds_req'], errors='coerce').astype('float64')
            _under = (_mo - _bo) > 1e-6
            if _under.any():
                log(f'[mini] {int(_under.sum()):,} bets were priced BELOW their own minimum and could not have been placed — removed')
                B = B[~_under].reset_index(drop=True)
        # M2 WITHDRAWN [v206]. I removed 278 "duplicate" bets where one strategy fired twice on the same match,
        # a median of ten seconds apart. That was WRONG and the owner corrected it.
        #
        # `collapse_to_matches` is a MEASUREMENT rule inside the search: counting every qualifying tick drifts a
        # strategy's win rate toward the fraction of TIME spent in a state rather than the fraction of MATCHES
        # won (93.7% against 85.2% on football lead_ml). It exists so a strategy is SCORED per match.
        #
        # It was never a rule that production may place only one bet per match. Two firings ten seconds apart
        # are two real, separately placeable bets at two prices — the market moved between them. Removing the
        # second discards a bet the system would genuinely have taken, which understates both the volume and
        # the profit. A search-time measurement rule must not be applied to the deliverable.
        #
        # What IS true and stays visible: bets on one match share ONE settlement, so they are CORRELATED. That
        # is a staking and exposure question for the production stack, not a reason to delete the bet. The
        # go-live sheet says so rather than the ledger silently dropping rows.
        # M3 — A MATCH MAY NOT BE IN BOTH HALVES. 27 matches appeared in a strategy's in-sample AND out-of-sample
        # sets, so the honest number was measured partly on matches the strategy was fitted on. The IS/OOS split
        # is BY MATCH; a match is assigned to whichever half its FIRST bet falls in, and every other bet on that
        # match follows it.
        if {'strategy_id', 'match_id', 'is_oos'} <= set(B.columns):
            _key = B['strategy_id'].astype(str) + '|' + B['match_id'].astype(str)
            _first = B.assign(_k=_key).groupby('_k')['is_oos'].transform('first')
            _moved = int((B['is_oos'].astype(bool) != _first.astype(bool)).sum())
            if _moved:
                log(f'[mini] {_moved:,} bets were on matches straddling the in/out-of-sample boundary — each match assigned to ONE half by its first bet')
                B['is_oos'] = _first.astype(bool)
        if len(B) != _n0:
            log(f'[mini] ledger {_n0:,} -> {len(B):,} bets after the placeability, one-bet-per-match and split checks')
    except Exception as _me:
        log(f'[mini] MONEY CHECKS FAILED ({type(_me).__name__}: {str(_me)[:70]}) — the ledger MAY contain unplaceable or duplicated bets')
    # [v201 X3] ONE ROW PER STRATEGY. strategy_id is a hash of sport+base+market+conditions, so two rows sharing
    # an id are the SAME strategy exported twice under different names — 503 rows for 439 real strategies on the
    # owner's 9 Sep bundle. It inflates the count, makes the implementation sheet ambiguous (whose bets are
    # whose?), and would have a production system place the same bet twice. The best-performing name is kept.
    try:
        if 'strategy_id' in I.columns and I['strategy_id'].duplicated().any():
            _dup = int(len(I) - I['strategy_id'].nunique())
            _keepcol = 'oos_roi' if 'oos_roi' in I.columns else 'n_oos'
            I = I.sort_values(_keepcol, ascending=False).drop_duplicates('strategy_id', keep='first').reset_index(drop=True)
            I['strategy_nr'] = range(1, len(I) + 1)
            B = B.drop(columns=[c for c in ('strategy_nr',) if c in B.columns]).merge(
                I[['strategy_id', 'strategy_nr']], on='strategy_id', how='inner')
            log(f'[mini] {_dup} duplicate strategies removed — identical sport, base, market and conditions under different names; the best-scoring name kept')
    except Exception as _de:
        log(f'[mini] duplicate check skipped ({type(_de).__name__}) — the sheet MAY contain the same strategy twice')
    try:
        _o = B[B['is_oos'].astype(bool)] if 'is_oos' in B.columns else B
        if len(_o) and 'strategy_id' in _o.columns and 'strategy_id' in I.columns:
            _mn_bar = int(_os.environ.get('LAZ_MINI_MIN_OOS', 100))
            _gg = _o.groupby('strategy_id')
            _fn, _fr = _gg.size(), _gg['db_profit'].mean() * 100.0
            # [v202 X5] A STRATEGY WITH NO OUT-OF-SAMPLE BETS IS NOT VALIDATED. Some rows had zero bets in the
            # OOS half of the ledger: they kept their discovery figures, so `n_oos` described one population and
            # the bets described another, and the owner's check could not reconcile them. There is nothing to
            # verify for such a strategy — it has never been tested out of sample on the data that shipped — so
            # it is refused rather than published with a number that cannot be checked.
            _seen = set(_fn.index)
            _none = sorted(set(I['strategy_id']) - _seen)
            _bad = sorted(set(_fn[_fn < _mn_bar].index) | set(_fr[_fr <= 0].index) | set(_none))
            if _none:
                log(f'[mini] {len(_none)} strategies have NO out-of-sample bets in the exported ledger — nothing to validate, removed')
            if _bad:
                _nm = I.set_index('strategy_id')['strategy_name'].to_dict()
                excl_all.append(pd.DataFrame(dict(sport='(final reconciliation)',
                    strategy_name=[_nm.get(k, k) for k in _bad],
                    reason=[('NO out-of-sample bets in the exported ledger — nothing to validate' if k in set(_none)
                             else f'FAILS THE BAR ON THE BETS IT SHIPS: {int(_fn.get(k, 0))} oos bets, {float(_fr.get(k, float("nan"))):+.1f}% roi — it passed on the harvested ledger, which contains bets that dedupe and the entry screen removed') for k in _bad])))
                log(f'[mini] RECONCILIATION: {len(_bad)} strategies passed on the harvested ledger but FAIL on the bets they actually ship — removed')
                I = I[~I['strategy_id'].isin(_bad)].reset_index(drop=True)
                B = B[~B['strategy_id'].isin(_bad)].reset_index(drop=True)
                I['strategy_nr'] = range(1, len(I) + 1)
                B = B.drop(columns=['strategy_nr']).merge(I[['strategy_id', 'strategy_nr']].drop_duplicates('strategy_id'), on='strategy_id', how='left')
                _o = B[B['is_oos'].astype(bool)] if 'is_oos' in B.columns else B
                _gg = _o.groupby('strategy_id'); _fn, _fr = _gg.size(), _gg['db_profit'].mean() * 100.0
            _fw = _gg['db_outcome'].apply(lambda x: 100.0 * (x == 'Win').mean())
            # no fillna: every survivor HAS ledger bets, so a blank here would be a defect, not a default
            I['n_oos'] = I['strategy_id'].map(_fn)
            I['oos_roi'] = I['strategy_id'].map(_fr).round(2)
            I['oos_win'] = I['strategy_id'].map(_fw).round(2)
            log(f'[mini] every published figure is computed from the {len(B):,} exported bets — sheet, parquet and ledger cannot disagree')
    except Exception as _xe:
        log(f'[mini] RECONCILIATION FAILED ({type(_xe).__name__}: {str(_xe)[:70]}) — the sheet MAY DISAGREE with the bets')
    S = B.groupby(['strategy_id', 'bet_strategy', 'sport'], as_index=False).agg(n_bets=('db_outcome', 'size'), wins=('db_outcome', lambda x: int((x == 'Win').sum())), profit=('db_profit', 'sum'), avg_odds=('bet_placement_odds', 'mean'), first_bet=('timestamp', 'min'), last_bet=('timestamp', 'max'), playable_share=('playable_categorization', lambda x: float((x == 'Playable').mean())))
    S['win_rate'] = S['wins'] / S['n_bets']; S['roi'] = S['profit'] / S['n_bets']
    G = B.groupby(['strategy_id', 'bet_strategy', 'sport', 'league'], as_index=False, dropna=False).agg(n_bets=('db_outcome', 'size'), wins=('db_outcome', lambda x: int((x == 'Win').sum())), profit=('db_profit', 'sum'))
    G['win_rate'] = G['wins'] / G['n_bets']; G['roi'] = G['profit'] / G['n_bets']
    if _sport_errors:
        log(f'[mini] {len(_sport_errors)} sport(s) FAILED and are NOT in this bundle: ' + ', '.join(f'{k} ({v})' for k, v in _sport_errors.items()))
    if flag_all:
        pd.concat(flag_all, ignore_index=True).to_csv(_os.path.join(out_dir, 'flagged_strategies.csv'), index=False)
        log('[mini] flagged_strategies.csv · extreme-edge strategies KEPT and listed for verification')
    if excl_all:
        _E = pd.concat(excl_all, ignore_index=True).drop_duplicates(['sport', 'strategy_name'])
        _E.to_csv(_os.path.join(out_dir, 'excluded_strategies.csv'), index=False)
        log(f'[mini] excluded_strategies.csv · {len(_E)} strategies refused, with reasons')
    for name, df in (('automated_bet_mini', B), ('automated_bet_mini_implementation', I), ('strategy_performance', S), ('league_level_strategy_performance', G)):
        df.to_parquet(_os.path.join(out_dir, f'{name}.parquet'), index=False)
        log(f'[mini] wrote {name}.parquet · {len(df):,} rows x {len(df.columns)} cols')
    try:   # [v192 W1] the workbook a person or a production system implements from
        laz_deploybook__write(out_dir=out_dir, log=log)
    except Exception as _e:
        log(f'[deploybook] not written: {type(_e).__name__}: {str(_e)[:80]}')
    return dict(bets=int(len(B)), strategies=int(len(I)), sports=sorted(B['sport'].unique().tolist()))

def laz_frames__load(sport, stride=1, allow_rebuild=False, log=print, columns=None):
    """THE ONLY WAY TO OPEN A FRAME. Returns (df, lineage, feature_names)."""
    OW = laz_frames___owner()
    sport = OW.canon(sport) if hasattr(OW, 'canon') else sport
    path, how = OW.resolve_frame(sport, allow_rebuild=allow_rebuild, log=log)
    if how != 'assigned':
        raise laz_frames__FrameMissing(f'{sport}: parquet not present at {path} (status {how})')
    import time as _tmL; _tL = {}; _t0L = _tmL.time()   # [AmunEV V2.16] step timings: the first load of every sport took ~2.5 min between two log lines and no one could say where
    cols, feat = laz_frames__columns_for(sport)
    if columns:
        cols = [c for c in cols if c in columns]
    _tL['columns'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    # [v192 E3] CLEANSE ONCE, ON WHOLE MATCHES — not once per 100,000-row batch.
    # THE DEFECT: the status-era filter, the cleanse and the slice ran INSIDE the batch loop — 46 times on
    # eBasketball, 63 on football, 50 on tennis. Memory was the visible symptom; the real damage is that a
    # batch is 100,000 ROWS, not whole matches, so a match straddling two batches was judged TWICE on two
    # fragments. The rule is defined on WHOLE matches and every log line said so while the code did the
    # opposite. eBasketball's 46 differing keep-counts (49, 50, 52, 54, 57 ...) are that fragmentation.
    # Rows are now read, narrowed to float32 and concatenated first; the filters run ONCE on the whole frame.
    P = []
    for b in pq.ParquetFile(path).iter_batches(batch_size=100000, columns=cols):
        x = b.to_pandas()
        del b
        for c in x.columns:
            if x[c].dtype == 'float64':
                x[c] = x[c].astype('float32')
        P.append(x)
        del x
    gc.collect()
    _tL['read'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    if not P:
        raise laz_frames__FrameMissing(f'{sport}: {path} contains no rows')
    d = pd.concat(P, ignore_index=True) if len(P) > 1 else P[0]
    P.clear()
    del P
    gc.collect()
    _tL['concat'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    d, _erep = laz_cleanse__status_era(d, sport, log=log)
    _tL['status_era'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    d, _crep = laz_cleanse__apply(d, sport, log=log)
    _tL['cleanse'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    d, _srep = laz_slice__apply(d, sport, log=log)
    _tL['slice'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    if stride > 1:
        d = d.iloc[::stride].copy()
    if 'match_id' in d.columns:
        d['match_id'] = d['match_id'].astype('category')
    gc.collect()
    if 'match_id' in d.columns and str(d['match_id'].dtype) == 'category':
        d['match_id'] = d['match_id'].astype(str)
    if 'ts' not in d.columns and 'timestamp' in d.columns:
        d['ts'] = pd.to_datetime(d.timestamp, errors='coerce')
    if 'ts' in d.columns:
        d['ts'] = pd.to_datetime(d.ts, errors='coerce')
    d['match_id'] = d.match_id.astype(str)
    try:
        _C = OW.LAZ_OWNER.get('combination', {}).get('status_columns', {})
        _stat = [c for grp in _C.values() for c in grp if c in d.columns]
        if _stat and 'ts' in d.columns:
            _has = d[_stat].notna().any(axis=1)
            if _has.any() and (not _has.all()):
                _t0 = d.loc[_has, 'ts'].min()
                _n0 = len(d)
                _m0 = d.match_id.nunique()
                _keep = (d.ts >= _t0).values
                d.drop(index=d.index[~_keep], inplace=True)
                d.reset_index(drop=True, inplace=True)
                del _keep
                gc.collect()
                log(f'  [frame] {sport}: status columns {_stat} begin {str(_t0)[:16]} — restricted {_n0:,}->{len(d):,} ticks · {_m0:,}->{d.match_id.nunique():,} matches')
            elif _has.all():
                log(f'  [frame] {sport}: status columns {_stat} present throughout')
        elif not _stat:
            log(f'  [frame] {sport}: NO status columns — market-open cannot be verified on this frame')
    except Exception as _e:
        log(f'  [frame] status window: {type(_e).__name__}: {_e}')
    _tL['ts+status'] = _tmL.time() - _t0L; _t0L = _tmL.time()
    d.sort_values(['match_id', 'ts'], inplace=True)
    d.reset_index(drop=True, inplace=True)
    gc.collect()
    _tL['sort'] = _tmL.time() - _t0L
    log(f'  [frame] {sport}: load timings — ' + ' · '.join(f'{k} {v:.1f}s' for k, v in _tL.items()) + f' · total {sum(_tL.values()):.1f}s')
    lin = laz_frames__lineage(sport)
    lin['rows'] = len(d)
    lin['matches'] = int(d.match_id.nunique())
    lin['stride'] = stride
    log(f'  [frame] {sport}: {len(d):,} ticks · {lin['matches']:,} matches · from {lin['source_table']}')
    return (d, lin, feat)

def laz_frames__available():
    """Which sports have their assigned parquet present."""
    OW = laz_frames___owner()
    return {sp: OW.frame_exists(sp) for sp in OW.LAZ_OWNER['frames']}
# ==========================================================================
# LAZ_BRAIN MODULE: laz_buildframe
# §laz_buildframe   <- grep this anchor to land here
# ==========================================================================
"""laz_buildframe.py — CSV IN, ENGINE-READY PARQUET OUT.

The engine expects a frame carrying specific columns. Until now those frames
were built elsewhere and the engine could only complain that one was missing.
This builds them from raw CSV, derives every column the cascade needs, and
reports what it could NOT derive rather than writing a frame that fails later.

WHAT IT DERIVES, and from what:

  match_id      the match key, from whatever the CSV calls it
  ts            tick timestamp, parsed to datetime
  h_score/a_score   running score
  home_odds/away_odds/draw_odds   live prices
  final_result  the settled outcome, forward-filled from the LAST tick of the
                match to every tick of it — a SETTLEMENT column, denied to the
                condition pool by the causality guard and used only to grade
  prog          elapsed 0-1 within the match: minute/nominal where a clock
                exists, tick position where it does not
  tg            running total
  minute        wall clock where the sport has one
  pm_fav        prematch favourite, from the FIRST quoted prices
  open_line     the first posted totals line, if the CSV carries one

WHAT IT REFUSES TO INVENT

A column with no source in the CSV is reported missing, never fabricated. A
frame that silently lacks total_goals_handicap will simply have no totals
market; a frame that silently GUESSES one produces a book that cannot be bet.
"""
import os, re, glob
import numpy as np, pandas as pd
laz_buildframe__ALIASES = {'match_id': ['match_id', 'matchid', 'id', 'fixture_id', 'game_id', 'event_id'], 'ts': ['ts', 'timestamp', 'time', 'datetime', 'tick_ts', 'created_at'], 'h_score': ['h_score', 'home_score', 'score_home', 'hs', 'home_goals', 'home_points'], 'a_score': ['a_score', 'away_score', 'score_away', 'as', 'away_goals', 'away_points'], 'home_odds': ['home_odds', 'home_price', 'odds_home', 'h_odds', 'home'], 'away_odds': ['away_odds', 'away_price', 'odds_away', 'a_odds', 'away'], 'draw_odds': ['draw_odds', 'draw_price', 'odds_draw', 'd_odds', 'draw'], 'final_result': ['final_result', 'final_winner', 'result', 'winner', 'outcome', 'ft_result'], 'minute': ['minute', 'min', 'match_minute', 'elapsed_minute', 'clock'], 'league': ['league', 'competition', 'tournament', 'league_name'], 'phase': ['phase', 'period', 'stage', 'half', 'quarter_phase'], 'total_goals_handicap': ['total_goals_handicap', 'tg_handicap', 'goals_line', 'total_line', 'line'], 'total_goals_over': ['total_goals_over', 'tg_over', 'over_price', 'over_odds'], 'total_goals_under': ['total_goals_under', 'tg_under', 'under_price', 'under_odds'], 'sets': ['sets', 'set_no', 'set_number', 'total_sets'], 'q1_h': ['q1_h', 'q1_home', 'quarter1_home'], 'q1_a': ['q1_a', 'q1_away', 'quarter1_away'], 'market_status': ['market_status', 'status', 'market_state']}
laz_buildframe__NOMINAL = {'football': 90.0, 'efootball': None, 'basketball': None, 'ebasketball': None, 'tennis': None, 'tabletennis': None, 'etennis': None, 'esports': None}

def laz_buildframe___pick(df, canonical):
    """Find a CSV column for a canonical name. Case- and space-insensitive."""
    low = {re.sub('[^a-z0-9]', '', str(c).lower()): c for c in df.columns}
    for cand in laz_buildframe__ALIASES.get(canonical, [canonical]):
        k = re.sub('[^a-z0-9]', '', cand.lower())
        if k in low:
            return low[k]
    return None

def laz_buildframe__inspect_csv(path, nrows=5000, log=print):
    """What a CSV can and cannot supply, BEFORE committing to a full read."""
    if str(path).lower().endswith('.parquet'):   # [v246-BF1] the raw _games tables are parquet, not csv
        d = pd.read_parquet(path)
        d = d.head(nrows) if nrows else d
    else:
        d = pd.read_csv(path, nrows=nrows, low_memory=False)
    found = {}
    missing = []
    for c in laz_buildframe__ALIASES:
        col = laz_buildframe___pick(d, c)
        if col:
            found[c] = col
        else:
            missing.append(c)
    log(f'[buildframe] {os.path.basename(path)}: {len(d.columns)} columns · {len(found)} of {len(laz_buildframe__ALIASES)} canonical resolved')
    if missing:
        log(f'[buildframe]   not present: {missing}')
    return (found, missing, d.columns.tolist())

def laz_buildframe__build(csv_path, sport, out_path=None, chunksize=500000, log=print):
    """Read the CSV, derive the engine's columns, write the parquet.

    Returns (out_path, report). The report names every column that could not
    be derived and why, so a thin frame is a KNOWN limitation rather than a
    surprise nine minutes into a run.
    """
    OW = _m('laz_owner')
    LG = _m('laz_log')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    out_path = out_path or os.path.join((OW.LAZ_OWNER['paths'].get('parquet_dir') if OW else '.') or '.', f'AB_{sp}.parquet')
    found, missing, cols = laz_buildframe__inspect_csv(csv_path, log=log)
    need = ['match_id', 'ts', 'h_score', 'a_score', 'home_odds', 'away_odds']
    lack = [c for c in need if c not in found]
    if lack:
        log(f'[buildframe] CANNOT BUILD {sp}: no source for {lack}')
        log(f'[buildframe]   csv columns were: {cols[:25]}')
        return (None, dict(ok=False, missing_required=lack, csv_columns=cols))
    if str(csv_path).lower().endswith('.parquet'):   # [v246-BF1]
        _raw = pd.read_parquet(csv_path)
        g = pd.DataFrame()
        for canon, src in found.items():
            g[canon] = _raw[src]
        # [v246-MAP] CARRY THE MARKET COLUMNS: the canonical spine alone dropped every
        # map/spread/totals/halves price at birth (esports: 180 raw -> 22 built). Every
        # populated non-canonical column flows; the quarantine decides what builders read.
        _mapped = set(found.values()) | {'id', 'match_name', 'sport'}
        for _mc in _raw.columns:
            if _mc in _mapped or _mc in g.columns:
                continue
            _s = _raw[_mc]
            if str(_s.dtype) == 'object' or str(_s.dtype).startswith('str'):
                _s = _s.replace('', np.nan)
            if _s.notna().any():
                g[_mc] = _s
        parts = [g]
    else:
        parts = []
        for ch in pd.read_csv(csv_path, chunksize=chunksize, low_memory=False):
            g = pd.DataFrame()
            for canon, src in found.items():
                g[canon] = ch[src]
            _mapped = set(found.values()) | {'id', 'match_name', 'sport'}   # [v246-MAP]
            for _mc in ch.columns:
                if _mc in _mapped or _mc in g.columns:
                    continue
                _s = ch[_mc]
                if str(_s.dtype) == 'object' or str(_s.dtype).startswith('str'):
                    _s = _s.replace('', np.nan)
                if _s.notna().any():
                    g[_mc] = _s
            parts.append(g)
    d = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
    if not len(d):
        return (None, dict(ok=False, reason='csv produced no rows'))
    log(f'[buildframe] read {len(d):,} rows · {d.match_id.nunique():,} matches')
    d['match_id'] = d['match_id'].astype(str)
    d['ts'] = pd.to_datetime(d['ts'], errors='coerce')
    d = d.dropna(subset=['ts']).sort_values(['match_id', 'ts']).reset_index(drop=True)
    num = lambda c: pd.to_numeric(d[c], errors='coerce') if c in d.columns else pd.Series(np.nan, index=d.index)
    hs, as_ = (num('h_score'), num('a_score'))
    d['h_score'] = hs
    d['a_score'] = as_
    d['tg'] = hs + as_
    if 'final_result' in d.columns:
        d['final_result'] = d.groupby('match_id')['final_result'].transform(lambda z: z.ffill().bfill()).astype(str).str.lower().str.replace('_team', '', regex=False)
    elif str(sp).lower() in ('tennis', 'tabletennis', 'esports', 'etennis'):
        # [v246-BF3] the owner's odds-inference rule for the no-verifiable-ending sports: the winner is the
        # side priced <= 1.35 on the last row with both prices valid > 1.0; below the threshold the match is
        # UNSETTLEABLE (empty), never marked a draw from the last score.
        _valid = d[(d['home_odds'] > 1) & (d['away_odds'] > 1)]
        _lv = _valid.groupby('match_id').tail(1).set_index('match_id')
        _sh = _lv[['home_odds', 'away_odds']].min(axis=1)
        _win = _sh.where(_sh <= 1.35).dropna()
        _w = _win.to_frame('s')
        _w['final_result'] = np.where(_lv.loc[_w.index, 'home_odds'] <= _lv.loc[_w.index, 'away_odds'], 'home', 'away')
        d['final_result'] = d['match_id'].map(_w['final_result']).fillna('').astype(str)
        log(f'[buildframe] final_result: odds-inference at <=1.35 — {len(_w):,} settleable, {int(d.match_id.nunique()) - len(_w):,} unsettleable (excluded, never proxy-settled)')
    else:
        last = d.groupby('match_id')[['h_score', 'a_score']].transform('last')
        d['final_result'] = np.where(last.h_score > last.a_score, 'home', np.where(last.a_score > last.h_score, 'away', 'draw'))
        log('[buildframe] final_result derived from the last tick score')
    d['final_tg'] = d.groupby('match_id')['tg'].transform('last')
    nom = laz_buildframe__NOMINAL.get(sp)
    EV = _m('laz_everything')
    if 'minute' in d.columns and num('minute').notna().any():
        d['minute'] = num('minute')
    _cel = None
    try:
        _cel = EV.causal_elapsed(d, sport) if EV is not None and hasattr(EV, 'causal_elapsed') else None
    except Exception as _pe:
        log(f'[buildframe] causal_elapsed: {type(_pe).__name__}: {str(_pe)[:50]}')
    if _cel is not None:
        d['prog'] = np.asarray(_cel, float)
        log('[buildframe] prog = minute / NOMINAL length (causal)')
    else:
        log(f'[buildframe] prog NOT derived — {sport} has no clock; the tick-position fallback is removed (it read the match final length)')
    ho, ao = (num('home_odds'), num('away_odds'))
    d['home_odds'] = ho
    d['away_odds'] = ao
    if 'draw_odds' in d.columns:
        d['draw_odds'] = num('draw_odds')
    fh = ho.groupby(d.match_id).transform('first')
    fa = ao.groupby(d.match_id).transform('first')
    d['pm_fav'] = np.where(fh <= fa, 'home', 'away')
    if 'total_goals_handicap' in d.columns:
        d['total_goals_handicap'] = num('total_goals_handicap')
        d['open_line'] = d.groupby('match_id')['total_goals_handicap'].transform('first')
    for c in ('total_goals_over', 'total_goals_under', 'q1_h', 'q1_a', 'sets'):
        if c in d.columns:
            d[c] = num(c)
    os.makedirs(os.path.dirname(out_path) or '.', exist_ok=True)
    d.to_parquet(out_path, index=False)
    rep = dict(ok=True, path=out_path, rows=len(d), matches=int(d.match_id.nunique()), columns=sorted(d.columns.tolist()), derived=['tg', 'final_result', 'final_tg', 'prog', 'pm_fav'], not_available=missing)
    log(f'[buildframe] WROTE {out_path} · {len(d):,} rows · {rep['matches']:,} matches · {len(d.columns)} columns')
    if missing:
        log(f'[buildframe]   absent from source (NOT fabricated): {missing}')
    return (out_path, rep)

def laz_buildframe__build_all(csv_dir='.', pattern='*.csv', log=print):
    """Build every sport whose CSV can be matched by name."""
    HINT = {'football': 'football', 'efootball': 'efootball', 'ebasketball': 'ebasketball', 'basketball': 'basketball', 'tabletennis': 'tabletennis', 'tennis': 'tennis', 'etennis': 'etennis', 'esports': 'esports'}
    out = {}
    files = sorted(glob.glob(os.path.join(csv_dir, pattern)))
    log(f'[buildframe] {len(files)} csv in {csv_dir}')
    for sp, hint in HINT.items():
        cand = [f for f in files if hint.replace('_', '') in os.path.basename(f).lower().replace('_', '').replace(' ', '')]
        if sp == 'tennis':
            cand = [f for f in cand if 'table' not in os.path.basename(f).lower() and (not os.path.basename(f).lower().startswith('etennis'))]
        if not cand:
            log(f'[buildframe] {sp}: no csv matched')
            continue
        p, rep = laz_buildframe__build(cand[0], sp, log=log)
        out[sp] = rep
    return out
# ==========================================================================
# LAZ_BRAIN MODULE: laz_ensure
# §laz_ensure   <- grep this anchor to land here
# ==========================================================================
"""laz_ensure.py — THE FIRST THING THE ENGINE DOES.

Before any mode runs, before a task is even chosen:

    1  is there a parquet for this sport?
    2  if not, is there a CSV? -> build the parquet from it
    3  does the parquet carry every column the modes need?
    4  if not, and the column is DERIVABLE -> derive it and rewrite the frame
    5  if it is not derivable, say so plainly and name what will not run

Nothing downstream should ever discover a missing column nine minutes into a
search. Mode 1 and Mode 3 both need columns that raw data does not carry —
prog, tg, final_result, pm_fav, open_line — and a frame lacking them cannot
run either mode at all.

WHAT IS DERIVABLE AND WHAT IS NOT

Derivable, because it is arithmetic over columns already present:
    tg            h_score + a_score
    final_tg      the last tg of the match, broadcast to every tick
    final_result  the last score of the match, broadcast (SETTLEMENT — the
                  causality guard denies it to the condition pool)
    prog          minute/max(minute) where a clock exists, else tick position
    pm_fav        the side with the shorter FIRST price
    open_line     the first posted totals line
    drift_h/a     price / that match's first price

NOT derivable, and never invented:
    total_goals_handicap, total_goals_over/under   a totals market either was
                                                   quoted or it was not
    market_status, selection_status_*              market state is observed
    q1_h/q1_a, sets                                period structure is observed
    league, phase                                  metadata is observed

A frame missing a non-derivable column loses the market or feature that needs
it, and this module says which — rather than the engine reporting a smaller
book for reasons nobody can see.
"""
import os, glob, re
import numpy as np, pandas as pd
laz_ensure__REQUIRED_CORE = ['match_id', 'ts', 'h_score', 'a_score', 'home_odds', 'away_odds']
laz_ensure__REQUIRED_DERIVED = ['tg', 'final_tg', 'final_result', 'prog', 'pm_fav']
laz_ensure__OPTIONAL_MARKET = ['draw_odds', 'total_goals_handicap', 'total_goals_over', 'total_goals_under', 'open_line', 'market_status', 'total_goals_market_active']
laz_ensure__OPTIONAL_STRUCT = ['minute', 'league', 'phase', 'sets', 'set1_winner', 'q1_h', 'q1_a', 'h1_h', 'h1_a']
laz_ensure__DERIVABLE = {'tg': 'h_score + a_score', 'final_tg': 'last tg of the match, broadcast to every tick', 'final_result': 'last score of the match, broadcast (settlement only)', 'prog': 'minute / max(minute) per match, else tick position 0-1', 'pm_fav': 'side with the shorter FIRST price of the match', 'open_line': 'first total_goals_handicap of the match', 'drift_h': 'home_odds / first home_odds of the match', 'drift_a': 'away_odds / first away_odds of the match'}

def laz_ensure___log(log, msg):
    if log:
        log(msg)

def laz_ensure__audit_frame(path, log=None):
    """What this parquet has, what it is missing, and what can be fixed."""
    import pyarrow.parquet as pq
    names = set(pq.ParquetFile(path).schema_arrow.names)
    if 'ts' not in names and 'timestamp' in names:
        names = names | {'ts'}
    miss_core = [c for c in laz_ensure__REQUIRED_CORE if c not in names]
    miss_der = [c for c in laz_ensure__REQUIRED_DERIVED if c not in names]
    miss_mkt = [c for c in laz_ensure__OPTIONAL_MARKET if c not in names]
    miss_str = [c for c in laz_ensure__OPTIONAL_STRUCT if c not in names]
    laz_ensure___log(log, f'[ensure] {os.path.basename(path)}: {len(names)} columns')
    if miss_core:
        laz_ensure___log(log, f'[ensure]   MISSING REQUIRED (cannot build): {miss_core}')
    if miss_der:
        laz_ensure___log(log, f'[ensure]   missing but DERIVABLE: {miss_der}')
    if miss_mkt:
        laz_ensure___log(log, f'[ensure]   market columns absent (that market will not run): {miss_mkt}')
    if miss_str:
        laz_ensure___log(log, f'[ensure]   structure columns absent (those features skipped): {miss_str}')
    return dict(columns=sorted(names), missing_core=miss_core, missing_derived=miss_der, missing_market=miss_mkt, missing_struct=miss_str, can_run=not miss_core)
laz_ensure___FRAME_CACHE = {}

def laz_ensure___read_frame(path):
    """D21: ensure() read the whole parquet FOUR times (derive, h2h, totals, settlement) —
    87.9 s on efootball's 215-column frame. The frame is cached against (path, mtime,
    size); a stage that rewrites the file refreshes the cache, so the next stage reads
    from memory. One read, not four."""
    # [v187 memory] pandas 3 has Copy-on-Write on always: a shallow copy shares the
    # buffers until either side writes, so the two deep copies here (one into the cache,
    # one out of it) doubled peak RSS on the 215-column efootball frame for nothing.
    # copy(deep=False) still gives the caller its own attrs and its own object.
    try:
        st = os.stat(path)
        key = (path, st.st_mtime_ns, st.st_size)
    except Exception:
        return pd.read_parquet(path)
    hit = laz_ensure___FRAME_CACHE.get(path)
    if hit is not None and hit[0] == key:
        return hit[1].copy(deep=False)
    laz_ensure___FRAME_CACHE.clear()
    d = pd.read_parquet(path)
    laz_ensure___FRAME_CACHE[path] = (key, d.copy(deep=False))
    return d

laz_ensure___DEFER = {'on': False, 'pending': {}, 'n': 0}   # [v187 O2] ensure() defers every rewrite and writes each parquet ONCE

def laz_ensure___safe_rewrite(d, path, log=None, what=''):
    """Write a frame back to its parquet ONLY if it still carries every core
    column it had. A core column stored as the pandas index is restored to a
    column first. A rewrite that would lose one is refused and said."""
    import pyarrow.parquet as pq
    if d.index.name and d.index.name not in d.columns:
        d = d.reset_index()
    before = set(pq.ParquetFile(path).schema_arrow.names)
    after = set(d.columns)
    lost = [c for c in before if c in laz_ensure__REQUIRED_CORE and c not in after]
    if lost:
        laz_ensure___log(log, f'[ensure] REFUSED to rewrite {os.path.basename(path)} ({what}): it would lose {lost}')
        return False
    if laz_ensure___DEFER.get('on'):
        # [v187 O2] the mutated frame becomes THE cached frame under the file's current key, so every later
        # read_frame() inside this ensure() sees it; the file is written once at the end (was: up to four
        # full serialisations of a multi-GB frame on a first run).
        try:
            st = os.stat(path)
            laz_ensure___FRAME_CACHE.clear()
            laz_ensure___FRAME_CACHE[path] = ((path, st.st_mtime_ns, st.st_size), d.copy(deep=False))
        except Exception:
            laz_ensure___FRAME_CACHE.pop(path, None)
        laz_ensure___DEFER['pending'][path] = d
        laz_ensure___DEFER['n'] += 1
        laz_ensure___log(log, f'[ensure]   rewrite of {os.path.basename(path)} deferred ({what}) — written once when ensure() finishes')
        return True
    d.to_parquet(path, index=False)
    try:
        st = os.stat(path)
        laz_ensure___FRAME_CACHE.clear()
        laz_ensure___FRAME_CACHE[path] = ((path, st.st_mtime_ns, st.st_size), d.copy(deep=False))
    except Exception:
        laz_ensure___FRAME_CACHE.pop(path, None)
    return True

def laz_ensure___flush_deferred(log=None):
    """[v187 O2] write every deferred frame once; refresh the cache key to the new file."""
    n = 0
    for path, d in list(laz_ensure___DEFER['pending'].items()):
        d.to_parquet(path, index=False)
        n += 1
        try:
            st = os.stat(path)
            laz_ensure___FRAME_CACHE.clear()
            laz_ensure___FRAME_CACHE[path] = ((path, st.st_mtime_ns, st.st_size), d.copy(deep=False))
        except Exception:
            laz_ensure___FRAME_CACHE.pop(path, None)
        laz_ensure___log(log, f'[ensure]   wrote {os.path.basename(path)} once · {len(d.columns)} columns ({laz_ensure___DEFER["n"]} rewrites coalesced)')
    laz_ensure___DEFER.update(on=False, pending={}, n=0)
    return n
laz_ensure__DERIVED_STAMPED = ('prog', 'tg', 'final_tg', 'final_result', 'pm_fav')

def laz_ensure___deriv_sig(col):
    """A signature of the code that derives `col`: the source of the functions involved."""
    import hashlib, inspect
    parts = []
    try:
        parts.append(inspect.getsource(laz_ensure__derive_into))
    except Exception:
        parts.append('derive_into')
    if col == 'prog':
        try:
            EV = _m('laz_everything')
            for fn in ('causal_elapsed', 'clock_per_row', 'nominal', 'nominal_from_frame'):
                if EV is not None and hasattr(EV, fn):
                    parts.append(inspect.getsource(getattr(EV, fn)))
            GN = _m('laz_genome')
            if GN is not None and hasattr(GN, '_phase_minute'):
                parts.append(inspect.getsource(GN._phase_minute))
            if EV is not None:
                parts.append(repr(sorted(getattr(EV, 'CLOCKLESS', ()))))
        except Exception as e:
            parts.append(f'prog:{type(e).__name__}')
    return hashlib.blake2b('\n'.join(parts).encode('utf-8'), digest_size=8).hexdigest()

def laz_ensure___stamp_path(path):
    return path[:-8] + '.derived.json' if path.endswith('.parquet') else path + '.derived.json'

def laz_ensure___read_stamps(path):
    try:
        import json
        return _laz_json_read(laz_ensure___stamp_path(path))
    except Exception:
        return {}

def laz_ensure___write_stamps(path, cols):
    try:
        import json
        st = laz_ensure___read_stamps(path)
        st.update({c: laz_ensure___deriv_sig(c) for c in cols})
        st['_engine'] = str((_m('laz_owner').LAZ_OWNER.get('version') if _m('laz_owner') else '') or '')
        _laz_json_write(laz_ensure___stamp_path(path), st, indent=1)
    except Exception:
        pass

def laz_ensure__stale_derived(path, present):
    """Derived columns PRESENT in the parquet whose stamp does not match the running engine."""
    st = laz_ensure___read_stamps(path)
    return [c for c in laz_ensure__DERIVED_STAMPED if c in present and st.get(c) != laz_ensure___deriv_sig(c)]

laz_ensure__ESPORTS = ('efootball', 'efbig', 'ebasketball', 'etennis', 'esports', 'tabletennis')

def laz_ensure___settlement_rule2(sport):
    """[v187 F7] Which tick settles a match: 'last' or 'running_max'.

    frame_validator measured scores DECREASING on ~1% of ticks and last-tick settlement
    disagreeing with the running max on ~2.5% of matches, and wrote 'settlement MUST use
    the running max' — but only into a log line that mode 3 never reaches, while every
    derivation here (final_tg, final_result, final_winner) kept taking the LAST tick and
    laz_totals fell back to the MAX. This makes the choice explicit, owner-controlled and
    printed on every run:
      1. env LAZ_SETTLEMENT_FINAL=last|running_max                (one-off override)
      2. LAZ_OWNER['rules']['settlement_final'] = 'running_max' | 'last'
         or a dict per sport, e.g. {'football': 'last', 'efootball': 'running_max'}
      3. default: running_max for the e-sports (a decrease can only be a feed glitch —
         no VAR, no correction), last for the real sports (a chalked-off goal is a real
         decrease and the last tick is the truth).
    Whatever the rule, derive_into logs how often the two disagree on THIS frame, so a
    wrong default is visible in the log rather than in a withdrawn book."""
    sp = str(sport).lower()
    env = os.environ.get('LAZ_SETTLEMENT_FINAL', '').strip().lower()
    if env in ('last', 'running_max'):
        return (env, 'env LAZ_SETTLEMENT_FINAL')
    OW = _m('laz_owner')
    r = None
    try:
        r = OW.rule('settlement_final', None) if OW is not None else None
    except Exception:
        r = None
    if isinstance(r, dict):
        r = r.get(sp, r.get('default'))
    if isinstance(r, str) and r.lower() in ('last', 'running_max'):
        return (r.lower(), "LAZ_OWNER['rules']['settlement_final']")
    if sp in laz_ensure__ESPORTS:
        return ('running_max', 'default for e-sports (no VAR: a decrease is a feed glitch)')
    return ('last', 'default for real sports (a chalked-off goal is a real decrease)')

def laz_ensure__settlement_rule(sport):
    return laz_ensure___settlement_rule2(sport)[0]

def laz_ensure__final_score(series, match_id, rule):
    """The settling value of `series` per match, broadcast to every tick."""
    g = series.groupby(match_id)
    return g.transform('max') if rule == 'running_max' else g.transform('last')

def laz_ensure__leader_family(d, sport, log=None):
    """[v192 K5] THE LEADER/LOSER FAMILY, derived wherever the extraction does not carry it.

    eFootball's frame carries leading_team_rt / losing_team_rt / leader_odds_rt / loser_odds_rt / pm_ratio /
    favourite_Prematch. eBasketball's does not — and 40+ library terms that reference them therefore could not be
    built, which is 40+ terms of the owner's library silently unavailable on that sport. Every one is computable
    from the columns eBasketball DOES carry, at the tick, with no lookahead:

        leading_team_rt = 'home' if h_score > a_score else 'away' if a_score > h_score else 'draw'  (this tick)
        losing_team_rt  = the other side, '' while level
        leader_odds_rt  = the live price of whoever leads now;  loser_odds_rt = the price of whoever trails
        pm_ratio        = prematch favourite price / prematch underdog price (first tick of the match)
        favourite_Prematch = 'home'/'away' by the first tick's prices

    Causal by construction: every value is a function of THIS tick and the match's first tick.
    """
    out = {}
    if not {'h_score', 'a_score'} <= set(d.columns):
        return (out, 'no scores')
    hs = pd.to_numeric(d['h_score'], errors='coerce'); as_ = pd.to_numeric(d['a_score'], errors='coerce')
    lead = np.where(hs > as_, 'home', np.where(as_ > hs, 'away', 'draw'))
    lose = np.where(hs > as_, 'away', np.where(as_ > hs, 'home', ''))
    if 'leading_team_rt' not in d.columns:
        out['leading_team_rt'] = lead
    if 'losing_team_rt' not in d.columns:
        out['losing_team_rt'] = lose
    ho = pd.to_numeric(d.get('home_odds'), errors='coerce') if 'home_odds' in d.columns else None
    ao = pd.to_numeric(d.get('away_odds'), errors='coerce') if 'away_odds' in d.columns else None
    if ho is not None and ao is not None:
        if 'leader_odds_rt' not in d.columns:
            out['leader_odds_rt'] = np.where(hs > as_, ho, np.where(as_ > hs, ao, np.nan))
        if 'loser_odds_rt' not in d.columns:
            out['loser_odds_rt'] = np.where(hs > as_, ao, np.where(as_ > hs, ho, np.nan))
        if 'match_id' in d.columns and ('pm_ratio' not in d.columns or 'favourite_Prematch' not in d.columns):
            g = d.groupby('match_id', sort=False)
            h0 = ho.groupby(d['match_id'], sort=False).transform('first')
            a0 = ao.groupby(d['match_id'], sort=False).transform('first')
            fav = np.where(h0 <= a0, 'home', 'away')
            with np.errstate(invalid='ignore', divide='ignore'):
                ratio = np.where(h0 <= a0, a0 / h0, h0 / a0)
            if 'favourite_Prematch' not in d.columns:
                out['favourite_Prematch'] = fav
            if 'pm_ratio' not in d.columns:
                out['pm_ratio'] = ratio
    if log is not None and out:
        log(f'[ensure]   leader/loser family: derived {sorted(out)} — {len(out)} columns the library needs and this extraction did not carry')
    return (out, '')

def laz_ensure__settle_handicap(d, sport, log=None):
    """[v195 H1] THE HANDICAP SETTLEMENT — the market the engine has never been able to search.

    WHY IT DID NOT EXIST. Every base the engine finds is settled by the MONEYLINE rule: did the backed side win
    the match. A spread bet does not ask that. It asks whether the backed side beat the POSTED LINE, and the
    engine had no way to compute that, so `point_spread_home`/`away` — populated on 99.3% of basketball matches
    and 86.8% of eBasketball's 41,780, live for essentially the whole game — was unsearchable. The coverage
    report of 9 Sep 2026 measured it as the widest untouched market in the data.

    THE RULE. With a line H posted against the home side (H negative means home is favoured and must win by
    more than |H|):

        home covers  <=>  (final_home - final_away) + H  >  0
        away covers  <=>  (final_home - final_away) + H  <  0
        push         <=>  exactly 0 — the stake is returned, and a push is NOT a win

    A push is settled as a LOSS OF NOTHING, not a win: `y = 0` with `price = 1.0`, so it contributes a bet with
    zero profit rather than inflating a win rate. Treating a push as a win is the single easiest way to
    manufacture a fake edge on this market.

    THE LINE MUST BE THE ONE POSTED AT THE BET'S TICK, never the closing line: a line that moved after the bet
    is information the bettor did not have. `point_spread_handicap` is carried per tick and used as-is.

    Returns (y, price, side, valid) aligned to d, or None when the sport carries no spread columns."""
    need = ('point_spread_home', 'point_spread_away', 'point_spread_handicap')
    if not all(c in d.columns for c in need):
        if log is not None:
            log(f'  [settle] {sport}: no handicap market on this frame ({[c for c in need if c not in d.columns]}) — the spread cannot be searched')
        return None
    num = lambda c: pd.to_numeric(d[c], errors='coerce').to_numpy(dtype='float64')
    ph, pa, H = num('point_spread_home'), num('point_spread_away'), num('point_spread_handicap')
    fh = num('hp_final_h_score') if 'hp_final_h_score' in d.columns else None
    if fh is None:
        # the final margin, per match, from the last tick of the cleansed frame
        g = d.groupby('match_id', observed=True)
        fin_h = g['h_score'].transform('last').to_numpy(dtype='float64')
        fin_a = g['a_score'].transform('last').to_numpy(dtype='float64')
    else:
        fin_h, fin_a = fh, num('ap_final_a_score')
    adj = (fin_h - fin_a) + H                      # the home side's margin AFTER the posted line
    home_covers = adj > 0
    push = adj == 0
    # back whichever side the market prices as more attractive at this tick; the sweep then conditions on it
    back_home = ph <= pa
    price = np.where(back_home, ph, pa)
    won = np.where(back_home, home_covers, ~home_covers & ~push)
    y = np.where(push, 0.0, won.astype('float64'))
    price = np.where(push, 1.0, price)             # a push returns the stake: zero profit, not a win
    side = np.where(back_home, 'home', 'away')
    valid = np.isfinite(price) & (price > 1.0) & np.isfinite(H) & np.isfinite(adj)
    if log is not None:
        n = int(valid.sum())
        log(f'  [settle] {sport}: handicap market settled on {n:,} ticks · {int(push[valid].sum()):,} pushes (stake returned, never a win) · '
            f'home covers on {100 * float(home_covers[valid].mean()):.1f}% of them')
    return (y, price, side, valid)

def laz_ensure__phase_clock(d, sport, log=None):
    """[v192 K4] Basketball and eBasketball carry the clock inside `phase`, with the match length in the league
    name: '3rd Quarter, 15 minutes' + '... 4 x 5 mins' = minute 15 of 20. The library wants `minute`, `q` and
    `prog`; without them ~30 terms per sport cannot be built and dozens of strategies cannot arm. Derived here,
    once, into the frame — causal by construction (every value comes from the tick's own phase string)."""
    import re as _re
    if 'phase' not in d.columns:
        return ({}, 'no phase column')
    ph = d['phase'].astype('object').fillna('').map(lambda x: '' if x is None or x != x else str(x))
    lg = (d['league'].astype('object').fillna('').map(lambda x: '' if x is None or x != x else str(x)) if 'league' in d.columns else pd.Series([''] * len(d), index=d.index))
    key = pd.DataFrame(dict(ph=ph, lg=lg)).drop_duplicates()
    qm, mm, tm = {}, {}, {}
    for a, b in zip(key['ph'].astype(str), key['lg'].astype(str)):
        a = '' if a in ('nan', 'None') else a; b = '' if b in ('nan', 'None') else b
        q = _re.search(r'([1-4])(?:st|nd|rd|th)\s+quarter', a, _re.I)
        mi = _re.search(r'(\d+(?:\.\d+)?)\s*min', a, _re.I)
        tot = _re.search(r'(\d+)\s*[x\u00d7]\s*(\d+(?:\.\d+)?)\s*min', b + ' ' + a, _re.I)
        qm[(a, b)] = float(q.group(1)) if q else np.nan
        mm[(a, b)] = float(mi.group(1)) if mi else np.nan
        tm[(a, b)] = float(tot.group(1)) * float(tot.group(2)) if tot else np.nan
    kk = list(zip(ph, lg))
    out = {}
    _q = np.array([qm[k] for k in kk], dtype='float64')
    _mi = np.array([mm[k] for k in kk], dtype='float64')
    _t = np.array([tm[k] for k in kk], dtype='float64')
    if np.isfinite(_q).any():
        out['q'] = _q
    if np.isfinite(_mi).any():
        out['minute'] = _mi
    with np.errstate(invalid='ignore', divide='ignore'):
        prog = np.where(np.isfinite(_t) & (_t > 0), _mi / _t, np.where(np.isfinite(_q), (_q - 0.5) / 4.0, np.nan))
    if np.isfinite(prog).any():
        out['prog'] = np.clip(prog, 0.0, 1.25)
    if log is not None and out:
        log(f'[ensure]   phase clock: derived {sorted(out)} from the phase text ({float(np.isfinite(prog).mean()):.0%} of ticks) — the library needs these')
    return (out, '')

def laz_ensure__derive_into(path, log=None):
    """Add every DERIVABLE column the frame lacks, and rewrite it in place.

    Reads once, writes once. A frame already complete is left untouched so
    this is safe to call at the start of every run.
    """
    a = laz_ensure__audit_frame(path, log=log)
    if a['missing_core']:
        laz_ensure___log(log, f'[ensure] cannot derive: required columns absent {a['missing_core']}')
        return (False, a)
    todo = [c for c in a['missing_derived'] if c in laz_ensure__DERIVABLE]
    _stale = laz_ensure__stale_derived(path, set(a.get('columns') or []))
    for c in _stale:
        if c not in todo:
            todo.append(c)
    if _stale:
        laz_ensure___log(log, f'[ensure]   STALE derived columns (written by different derivation code): {_stale} — re-deriving')
    if 'prog' not in todo:
        todo.append('prog')
    if not todo:
        laz_ensure___log(log, '[ensure] frame already carries every derivable column')
        return (True, a)
    laz_ensure___log(log, f'[ensure] deriving {todo} — each is arithmetic over columns already present')
    d = laz_ensure___read_frame(path)
    num = lambda c: pd.to_numeric(d[c], errors='coerce') if c in d.columns else pd.Series(np.nan, index=d.index)
    d['match_id'] = d['match_id'].astype(str)
    if 'ts' not in d.columns and 'timestamp' in d.columns:
        d['ts'] = pd.to_datetime(d['timestamp'], errors='coerce')
    if 'ts' in d.columns:
        d['ts'] = pd.to_datetime(d['ts'], errors='coerce')
    d = d.sort_values(['match_id', 'ts']).reset_index(drop=True)
    hs, as_ = (num('h_score'), num('a_score'))
    ho, ao = (num('home_odds'), num('away_odds'))
    if 'tg' in todo:
        d['tg'] = hs + as_
    _sp_r = os.path.basename(path).replace('AB_', '').replace('.parquet', '')
    try:   # [v192 K5] the leader/loser family, before the library asks for it
        _lf, _ = laz_ensure__leader_family(d, _sp_r, log=log)
        for _k, _v in _lf.items():
            d[_k] = _v
    except Exception as _e:
        laz_ensure___log(log, f'[ensure]   leader family skipped: {type(_e).__name__}: {str(_e)[:60]}')
    try:   # [v192 K4] the phase clock, before the settlement rule reads prog
        _pc, _pcw = laz_ensure__phase_clock(d, _sp_r, log=log)
        for _k, _v in _pc.items():
            if _k not in d.columns or pd.to_numeric(d[_k], errors='coerce').notna().mean() < 0.5:
                d[_k] = _v; todo.add(_k) if hasattr(todo, 'add') else None
    except Exception as _e:
        laz_ensure___log(log, f'[ensure]   phase clock skipped: {type(_e).__name__}: {str(_e)[:60]}')
    _srule, _ssrc = laz_ensure___settlement_rule2(_sp_r)
    try:
        _tgs = hs + as_
        _g = _tgs.groupby(d.match_id)
        _last, _mx = (_g.transform('last'), _g.transform('max'))
        _dis = (~np.isclose(_last.fillna(-1).values, _mx.fillna(-1).values)).astype(bool)
        _dis_m = float(pd.Series(_dis).groupby(d.match_id.values).any().mean()) if len(d) else 0.0
        laz_ensure___log(log, f'[ensure]   settlement rule = {_srule} ({_ssrc}); last-tick vs running-max disagree on {_dis_m:.2%} of matches')
        if _dis_m > 0.0 and _srule == 'last':
            laz_ensure___log(log, '[ensure]   NOTE those matches settle on the LAST tick under this rule — set LAZ_SETTLEMENT_FINAL=running_max if this feed has no VAR')
    except Exception as _e:
        laz_ensure___log(log, f'[ensure]   settlement agreement check skipped: {type(_e).__name__}: {str(_e)[:60]}')
    if 'final_tg' in todo:
        d['final_tg'] = laz_ensure__final_score(hs + as_, d.match_id, _srule)
    if 'final_result' in todo:
        if 'final_winner' in d.columns and d['final_winner'].notna().any():
            d['final_result'] = d['final_winner'].astype(str).str.lower().str.replace('_team', '', regex=False)
            laz_ensure___log(log, '[ensure]   final_result taken from the recorded final_winner, NOT derived')
        else:
            OWc = _m('laz_owner')
            _sp = os.path.basename(path).replace('AB_', '').replace('.parquet', '')
            _draws = _sp in tuple(_m('laz_owner').LAZ_OWNER.get('draw_sports', ()) if _m('laz_owner') else ('football', 'efootball', 'efbig'))
            lh = laz_ensure__final_score(hs, d.match_id, _srule)
            la = laz_ensure__final_score(as_, d.match_id, _srule)
            d['final_result'] = np.where(lh > la, 'home', np.where(la > lh, 'away', 'draw' if _draws else 'home'))
            laz_ensure___log(log, f'[ensure]   final_result DERIVED from the {_srule} score (no recorded settlement; draws {('allowed' if _draws else 'impossible')} in {_sp})')
            laz_ensure___log(log, '[ensure]   VERIFY THIS against a known result before betting from it')
    if 'prog' in todo:
        _EVe = _m('laz_everything')
        _sp_e = os.path.basename(path).replace('AB_', '').replace('.parquet', '')
        _cel = None
        try:
            _cel = _EVe.causal_elapsed(d, _sp_e) if _EVe is not None and hasattr(_EVe, 'causal_elapsed') else None
        except Exception as _pe:
            laz_ensure___log(log, f'[ensure]   causal_elapsed: {type(_pe).__name__}: {str(_pe)[:50]}')
        if _cel is not None:
            d['prog'] = np.asarray(_cel, float)
            laz_ensure___log(log, '[ensure]   prog = minute / NOMINAL length (causal; laz_everything.causal_elapsed)')
        elif 'prog' in d.columns:
            d = d.drop(columns=['prog'])
            laz_ensure___log(log, f'[ensure]   prog REMOVED from the frame — {_sp_e} has no clock; the stored prog was tick position / total ticks (row count, forward-looking)')
        else:
            laz_ensure___log(log, f'[ensure]   prog NOT derived — {_sp_e} has no clock (laz_genome.CLOCK); the tick-position fallback read the match final length and is removed')
    if 'pm_fav' in todo:
        fh = ho.groupby(d.match_id).transform('first')
        fa = ao.groupby(d.match_id).transform('first')
        d['pm_fav'] = np.where(fh <= fa, 'home', 'away')
    if 'open_line' in todo and 'total_goals_handicap' in d.columns:
        d['open_line'] = num('total_goals_handicap').groupby(d.match_id).transform('first')
    if 'drift_h' in todo:
        d['drift_h'] = ho / ho.groupby(d.match_id).transform('first')
    if 'drift_a' in todo:
        d['drift_a'] = ao / ao.groupby(d.match_id).transform('first')
    if not laz_ensure___safe_rewrite(d, path, log, 'derived columns'):
        return (False, laz_ensure__audit_frame(path, log=None))
    laz_ensure___write_stamps(path, [c for c in todo if c in d.columns])
    laz_ensure___log(log, f'[ensure] rewrote {os.path.basename(path)} · now {len(d.columns)} columns')
    return (True, laz_ensure__audit_frame(path, log=None))

def laz_ensure__search_paths():
    """Every directory the engine will look in for a parquet, in order.
    Set LAZ_OWNER['paths']['parquet_search'] to control it."""
    OW = _m('laz_owner')
    P = OW.LAZ_OWNER.get('paths', {}) or {} if OW else {}
    out = []
    for d in [P.get('parquet_dir')] + list(P.get('parquet_search') or []) + ['AB_frames', 'frames', 'parquets', '.', os.getcwd()]:
        if not d:
            continue
        d = os.path.abspath(d)
        if d not in out and os.path.isdir(d):
            out.append(d)
    return out

def laz_ensure__source_parquet(sport):
    """[v247] The raw source export for a sport — LAZ_OWNER['frames'][sport]['source_parquet'], e.g. AB_basketball_games.parquet.
    Returns (path, mtime) or None. The source carries the NEW market columns (first-half result, quarter spreads,
    second-half moneyline, away totals: 35 on basketball/eBasketball, 12 on esports) that the frame built from CSV never had."""
    OW = _m('laz_owner')
    fr = ((OW.LAZ_OWNER.get('frames', {}) or {}) if OW else {}).get(str(sport).lower(), {}) or {}
    fn = fr.get('source_parquet')
    if not fn:
        return None
    for d in laz_ensure__search_paths():
        p = os.path.join(d, fn)
        if os.path.exists(p):
            return (p, os.path.getmtime(p))
    return None

def laz_ensure__frame_from_source(sport, src, dst, log=None):
    """[v247] Build AB_<sport>.parquet from AB_<sport>_games.parquet: timestamp -> ts (kept as well), every column carried,
    sorted by (match_id, ts). ensure() then derives final_winner / prog / minute / q and joins h2h exactly as it does today."""
    import pyarrow.parquet as pq, pyarrow as pa
    d = pq.read_table(src).to_pandas()
    if 'ts' not in d.columns and 'timestamp' in d.columns:
        d['ts'] = pd.to_datetime(d['timestamp'], errors='coerce')
    if 'match_id' in d.columns and 'ts' in d.columns:
        d = d.sort_values(['match_id', 'ts'], kind='mergesort').reset_index(drop=True)
    pq.write_table(pa.Table.from_pandas(d, preserve_index=False), dst)
    laz_ensure___log(log, f'[ensure] {sport}: frame BUILT FROM SOURCE {os.path.basename(src)} -> {os.path.basename(dst)} · {len(d):,} rows · {len(d.columns)} columns (every source column carried; the new markets are in)')
    return dst

def laz_ensure__find_parquet(sport, log=None):
    """The BEST existing frame for this sport — the one with the most columns.

    [v247] THE SOURCE WINS when it is newer than the frame, when the frame is absent, or when LAZ_FRAME_SOURCE=games:
    the frame is rebuilt from AB_<sport>_games.parquet so the new market columns reach the pool. Set LAZ_FRAME_SOURCE=frame
    to keep the existing frame regardless.

    Searching one directory only is how a 99-column frame came to be rebuilt
    from CSV as 14: parquet_dir had resolved to the wrong place, nothing was
    found, and the rebuild was the correct response to a wrong question.
    """
    import pyarrow.parquet as pq
    best = None
    for d in laz_ensure__search_paths():
        p = os.path.join(d, f'AB_{sport}.parquet')
        if not os.path.exists(p):
            continue
        try:
            n = len(pq.ParquetFile(p).schema_arrow.names)
        except Exception:
            continue
        if best is None or n > best[1]:
            best = (p, n)
    # [v247] the source export
    _src = laz_ensure__source_parquet(sport)
    _mode = str(os.environ.get('LAZ_FRAME_SOURCE', 'auto')).lower()
    if _src and _mode != 'frame':
        _rebuild = (best is None) or (_mode == 'games') or (_src[1] > os.path.getmtime(best[0]) + 60)
        if _rebuild:
            _dst = best[0] if best else os.path.join(os.path.dirname(_src[0]), f'AB_{sport}.parquet')
            try:
                laz_ensure__frame_from_source(sport, _src[0], _dst, log=log)
                best = (_dst, len(pq.ParquetFile(_dst).schema_arrow.names))
            except Exception as _fe:
                laz_ensure___log(log, f'[ensure] {sport}: source rebuild FAILED {type(_fe).__name__}: {str(_fe)[:80]} — using the existing frame')
        elif log:
            laz_ensure___log(log, f'[ensure] {sport}: source {os.path.basename(_src[0])} is older than the frame — frame kept (LAZ_FRAME_SOURCE=games to force)')
    if best and log:
        laz_ensure___log(log, f'[ensure] {sport}: best existing frame {best[0]} ({best[1]} columns)')
    return best

def laz_ensure__csv_for(sport):
    """The CSV named in LAZ_OWNER for this sport, resolved against csv_dir."""
    OW = _m('laz_owner')
    if OW is None:
        return None
    spec = (OW.LAZ_OWNER.get('frames', {}) or {}).get(sport) or {}
    name = spec.get('csv')
    if not name:
        return None
    cdir = (OW.LAZ_OWNER.get('paths', {}) or {}).get('csv_dir') or os.getcwd()
    for d in (cdir, os.getcwd(), '.'):
        p = os.path.join(d, name)
        if os.path.exists(p):
            return p
    return None

def laz_ensure__find_csv(sport, csv_dir='.'):
    """A CSV whose name plausibly holds this sport."""
    sp = str(sport).lower()
    hint = {'efootball': 'efootball', 'football': 'football', 'ebasketball': 'ebasketball', 'basketball': 'basketball', 'tabletennis': 'tabletennis', 'tennis': 'tennis', 'etennis': 'etennis', 'esports': 'esports'}.get(sp, sp)
    cands = []
    for f in sorted(glob.glob(os.path.join(csv_dir, '*.csv')) + glob.glob(os.path.join(csv_dir, '*.parquet'))):   # [v246-BF2] discover the raw _games.parquet tables too
        b = os.path.basename(f).lower().replace('_', '').replace(' ', '').replace('-', '')
        if hint.replace('_', '') in b:
            cands.append(f)
    if sp == 'tennis':
        cands = [f for f in cands if 'table' not in os.path.basename(f).lower() and (not os.path.basename(f).lower().startswith('etennis'))]
    if sp == 'football':
        cands = [f for f in cands if not os.path.basename(f).lower().startswith('efootball') and 'efootball' not in os.path.basename(f).lower()]
    if sp == 'basketball':
        cands = [f for f in cands if 'ebasketball' not in os.path.basename(f).lower()]   # [v246-BF5] 'basketball' is a substring of 'ebasketball' — never let the eBasketball table (or its h2h file) build the basketball frame
    if sp == 'ebasketball':
        cands = [f for f in cands if 'h2h' not in os.path.basename(f).lower()]   # [v246-BF5] the h2h player table is not frame material
    if sp == 'etennis':
        cands = [f for f in cands if 'table' not in os.path.basename(f).lower()]   # [v246-BF5] 'etennis' is a substring of 'tablETENNIS' — never let the table-tennis table build the etennis frame
    if sp == 'tennis':
        cands = [f for f in cands if 'etennis' not in os.path.basename(f).lower()]   # [v246-BF5] the AB_ prefix defeats the legacy startswith('etennis') guard — exclude eTennis anywhere in the name
    return sorted(cands, key=lambda p: -os.path.getsize(p))[0] if cands else None

def laz_ensure___ensure_impl(sport, csv_dir='.', log=None):
    _OWc = _m('laz_owner')
    sport = _OWc.canon(sport) if _OWc is not None and hasattr(_OWc, 'canon') else sport
    'THE ENTRY POINT. Parquet -> else CSV -> build -> derive -> report.\n\n    Returns (ready, report). `ready` False means no mode can run this sport,\n    and the report says exactly why.\n    '
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    path = OW.frame_path(sp) if OW is not None else None
    rep = dict(sport=sp, parquet=path, built_from_csv=None, derived=[], ready=False)
    best = laz_ensure__find_parquet(sp, log=None)
    if best:
        path, ncol = best
        rep['parquet'] = path
        laz_ensure___log(log, f'[ensure] {sp}: parquet present at {path} ({ncol} columns)')
    else:
        c = laz_ensure__csv_for(sp) or laz_ensure__find_csv(sp, csv_dir)
        if c:
            laz_ensure___log(log, f'[ensure] {sp}: no parquet in {laz_ensure__search_paths()} — building from {os.path.basename(c)}')
        if not c:
            laz_ensure___log(log, f'[ensure] {sp}: NO parquet and NO csv in {csv_dir} — this sport cannot run')
            rep['reason'] = 'no parquet and no csv'
            return (False, rep)
        BF = _m('laz_buildframe')
        if BF is None:
            rep['reason'] = 'laz_buildframe unreachable'
            return (False, rep)
        path, br = BF.build(c, sp, out_path=path, log=log)
        rep['built_from_csv'] = c
        if not path:
            rep['reason'] = f'csv could not build: {br}'
            return (False, rep)
        rep['parquet'] = path
    try:
        H2 = _m('laz_h2h')
        if H2 is not None and sp in (getattr(H2, 'SOURCES', {}) or {}):
            import pandas as _pd
            _d = laz_ensure___read_frame(path)
            _cols = H2.attach(_d, sp, log=lambda x: laz_ensure___log(log, x))
            _new = [c for c in _cols if c not in _d.columns]
            if _new:
                for c in _new:
                    _d[c] = _cols[c]
                if not laz_ensure___safe_rewrite(_d, path, log, 'h2h join'):
                    raise RuntimeError('rewrite refused')
                laz_ensure___log(log, f'[ensure] {sp}: +{len(_new)} h2h/player columns JOINED INTO the parquet ({os.path.getsize(path) // 1000000} MB) — no run reads the h2h source again')
                rep['h2h_joined'] = _new
            elif _cols:
                laz_ensure___log(log, f'[ensure] {sp}: h2h columns already in the parquet ({len(_cols)})')
            else:
                laz_ensure___log(log, f'[ensure] {sp}: h2h source present but no match_id joined — columns NOT added')
    except Exception as _e:
        laz_ensure___log(log, f'[ensure] {sp}: h2h join {type(_e).__name__}: {str(_e)[:80]}')
    try:
        import pandas as _pd
        _d = laz_ensure___read_frame(path)
        _cols = set(_d.columns)
        _added = []
        import re as _re
        for _gls in ('total_goals_over', 'total_goals_under', 'total_goals_handicap', 'total_goals_market_active'):
            if _gls in _cols:
                continue
            _leg = _gls[len('total_goals_'):]
            _cand = [c for c in _cols if _re.fullmatch('total_[a-z]+_' + _re.escape(_leg), c) and c != _gls]
            if _cand:
                _d[_gls] = _d[sorted(_cand)[0]]
                _added.append(f'{_gls}<-{sorted(_cand)[0]}')
        if _added:
            if laz_ensure___safe_rewrite(_d, path, log, 'totals aliases'):
                laz_ensure___log(log, f'[ensure] {sp}: totals aliased {_added} from the points columns — the totals base will run')
    except Exception as _e:
        laz_ensure___log(log, f'[ensure] {sp}: totals alias {type(_e).__name__}: {str(_e)[:80]}')
    try:
        import pandas as _pd, numpy as _np
        _d = laz_ensure___read_frame(path)
        _cols = set(_d.columns)
        if 'final_winner' not in _cols:
            _alias = next((c for c in ('final_result', 'match_winner', 'winner', 'won_by', 'result', 'match_result') if c in _cols), None)
            _nodraw = str(sp).lower() in ('basketball', 'ebasketball', 'tennis', 'tabletennis', 'etennis', 'esports')
            if _alias:
                _v = _d[_alias].astype(str).str.lower().str.replace('_team', '', regex=False)
                _d['final_winner'] = _np.where(_v.isin(['home', 'h', '1']), 'home', _np.where(_v.isin(['away', 'a', '2']), 'away', _np.where(_v.isin(['draw', 'd', 'x']), 'draw', _v)))
                laz_ensure___safe_rewrite(_d, path, log, 'settlement alias')
                laz_ensure___log(log, f'[ensure] {sp}: final_winner MAPPED from {_alias} (never derived when an alias exists)')
            elif {'h_score', 'a_score', 'match_id'} <= _cols:
                # [AmunEV V2.18 — THE OWNER'S SETTLEMENT RULE, 17 Sep, restored on his instruction 22 Sep] "We either use the scores, or the
                # last observable and validated odds row, and if it is <= 1.35 we believe it" — measured by the owner at 99.5-100% accurate
                # (laz_settlement__INFER_THRESHOLD). The score decides where it is not level; a level (or absent) score is settled by the
                # last row with both prices valid: the side at or below the threshold won. Neither -> UNSETTLED (excluded, never a draw
                # in a no-draw sport, never a loss). In a sport with draws a level final score is a draw unless the last validated row
                # names a side at the threshold. V2.17 (finished-state-only settlement) is REVERTED.
                _hs = _pd.to_numeric(_d['h_score'], errors='coerce'); _as = _pd.to_numeric(_d['a_score'], errors='coerce')
                _srule = laz_ensure__settlement_rule(sp)
                _last_h = laz_ensure__final_score(_hs, _d['match_id'], _srule); _last_a = laz_ensure__final_score(_as, _d['match_id'], _srule)
                _thr = float(globals().get('laz_settlement__INFER_THRESHOLD', 1.35) or 1.35)
                _mid = _d['match_id'].astype(str)
                _sc = _pd.Series(_np.where(_last_h > _last_a, 'home', _np.where(_last_a > _last_h, 'away', ('draw' if not _nodraw else None))), index=_d.index, dtype=object)
                _fw = _sc.copy(); _by = _pd.Series(_np.where(_sc.notna(), 'score', ''), index=_d.index, dtype=object)
                _n_odds = 0
                if {'home_odds', 'away_odds'} <= _cols:
                    _ho = _pd.to_numeric(_d['home_odds'], errors='coerce'); _ao = _pd.to_numeric(_d['away_odds'], errors='coerce')
                    _okp = _ho.notna() & _ao.notna() & (_ho > 1.0) & (_ao > 1.0)
                    _lh = _ho.where(_okp).groupby(_mid).transform('last'); _la = _ao.where(_okp).groupby(_mid).transform('last')
                    _side = _pd.Series(_np.where(_lh <= _thr, 'home', _np.where(_la <= _thr, 'away', None)), index=_d.index, dtype=object)
                    _level = (_last_h == _last_a) | _last_h.isna() | _last_a.isna()
                    _use = _level & _side.notna()
                    _fw[_use] = _side[_use]; _by[_use] = f'odds_inference<={_thr:g}'
                    _n_odds = int(_mid[_use].nunique())
                _n_all = int(_mid.nunique()); _n_sc = int(_mid[(_by == 'score')].nunique()); _n_unset = int(_mid[_fw.isna()].nunique())
                _d['final_winner'] = _fw.astype(object); _d['settled_by'] = _by.astype(object)
                laz_ensure___safe_rewrite(_d, path, log, 'settlement derived')
                laz_ensure___log(log, f'[ensure] {sp}: SETTLEMENT (owner rule) — score: {_n_sc:,} matches · last validated odds row <= {_thr:g}: {_n_odds:,} matches · UNSETTLED {_n_unset:,} of {_n_all:,} (excluded, never a draw, never a loss)')
                laz_ensure___log(log, f'[ensure] {sp}: final_winner DERIVED from the {_srule} recorded score per match' + (' — a no-draw sport: 0 rows settle as draw' if _nodraw else ' — a sport with draws: a level final score is a draw'))
            else:
                laz_ensure___log(log, f'[ensure] {sp}: NOT READY — no settlement column. Looked for final_winner, final_result, match_winner, winner, won_by, result. Frame has: {sorted(_cols)[:40]}')
                rep['reason'] = 'no settlement column'
                rep['ready'] = False
                return (False, rep)
    except Exception as _e:
        laz_ensure___log(log, f'[ensure] {sp}: settlement check {type(_e).__name__}: {str(_e)[:80]}')
    ok, a = laz_ensure__derive_into(path, log=log)
    rep.update(audit=a, derived=a.get('missing_derived') or [])
    rep['ready'] = bool(ok and a.get('can_run'))
    if not rep['ready']:
        laz_ensure___log(log, f'[ensure] {sp}: NOT READY — {a.get('missing_core')}')
    else:
        laz_ensure___log(log, f'[ensure] {sp}: READY')
    return (rep['ready'], rep)

def laz_ensure__ensure(sport, csv_dir='.', log=None):
    """[v187 O2] One write per sport: every rewrite inside is deferred (the mutated frame stays the
    cached frame) and flushed in a finally — so no exit path, early return or exception can leave a
    rewrite pending or the deferral switched on for the next call."""
    laz_ensure___DEFER.update(on=True, pending={}, n=0)
    try:
        return laz_ensure___ensure_impl(sport, csv_dir=csv_dir, log=log)
    finally:
        laz_ensure___flush_deferred(log)

def laz_ensure__ensure_all(sports, csv_dir='.', log=None):
    out = {}
    for sp in sports:
        LG = _m('laz_log')
        r = LG.guard(f'ensure {sp}', laz_ensure__ensure, sp, csv_dir, log, default=(False, dict(sport=sp, reason='exception'))) if LG is not None else laz_ensure__ensure(sp, csv_dir, log)
        out[sp] = r[1] if isinstance(r, tuple) else r
    ready = [s for s, v in out.items() if v.get('ready')]
    laz_ensure___log(log, f'[ensure] READY: {ready}')
    notready = [s for s, v in out.items() if not v.get('ready')]
    if notready:
        laz_ensure___log(log, f'[ensure] NOT READY: {notready}')
    return out
