# LAZ_BRAIN MODULE: laz_h2h
# §laz_h2h   <- grep this anchor to land here
# ==========================================================================
"""laz_h2h.py — THE HEAD-TO-HEAD AND FORM SOURCE.

I declared 13 terms NOT BUILDABLE — wall_pair, h2h_exp, leader_fuel, elo_diff,
rest_lead, ovr_h and the rest — on the grounds that no frame carried the data.
That was wrong twice over.

FIRST: the registry said `source_table='public.h2h_player_performance'` from
the beginning. I read that line in this session and did not follow it.

SECOND: the files are on disk as h2h_player_performance.parquet (380 MB) and
ebasketball_h2h_plaer_table.parquet (64 MB), and every parquet reader fails on
them — because they are CSV with a .parquet extension. The first bytes are
`"game_number","match_id",...`. A reader error is not an absent file.

WHAT THEY CARRY, per player per match:

  elo             player_betsson_elo · opponnent_betsson_elo
                  betsson_home_player_elo · betsson_away_player_elo
                  cur50games_homeplayer_elo
  head to head    h2h_l10g · h2h_winrate_l10g · h2h_avggoals_scored_l10g
                  h2h_avggoals_conceded_l10g · h2h_avg_matchggoals_l10g
  form            winrate_l5g/l10g/l20g · avggoals_scored_5/10/20
                  avggoals_conceded_5/10/20 · avg_matchgoals_5/10/20
  fatigue         total_games · win_last_games_flag · win_last2games_flag

Two rows per match — one per player, distinguished by `sidepick`. They pivot to
home/away columns keyed on match_id, which is how they join a tick frame.
"""
import os, glob
import numpy as np, pandas as pd

def laz_h2h___laz_home():
    """The directory this run writes to. Defaults to the CURRENT directory,
    never the container the engine was built in. _laz_home() shipped inside
    the single file and every write failed on the operator's machine with
    FileNotFoundError after the search had already run."""
    import os as _o
    OW = _m('laz_owner') if '_m' in globals() else None
    if OW is not None:
        d = (getattr(OW, 'LAZ_OWNER', {}).get('paths', {}) or {}).get('output_dir')
        if d:
            return d
    return _o.environ.get('LAZ_HOME') or _o.getcwd()
laz_h2h__SOURCES = {'efootball': ('h2h_player_performance.parquet', 'h2h_player_performance.csv'), 'ebasketball': ('ebasketball_h2h_player_performance.parquet', 'ebasketball_h2h_player_performance.csv', 'ebasketball_h2h_plaer_table.parquet')}   # h2h files exist for eFootball and eBasketball ONLY (owner, 2026-09-06); real basketball has none · [v246-H2HCSV] the reader sniffs content (PAR1 vs CSV) — either name lands
laz_h2h__SEARCH = [__import__('os').environ.get('LAZ_UPLOADS', '.'), laz_h2h___laz_home(), '.']
laz_h2h__PLAYER_COLS = ['player_betsson_elo', 'opponnent_betsson_elo', 'total_games', 'cur50games_homeplayer_elo', 'win_last2games_flag', 'win_last_games_flag', 'avg_matchgoals_lastgame', 'winrate_l5g', 'avggoals_scored_5', 'avggoals_conceded_5', 'avg_matchgoals_5', 'winrate_l10g', 'avggoals_scored_10', 'avggoals_conceded_10', 'avg_matchgoals_10', 'winrate_l20g', 'avggoals_scored_20', 'avggoals_conceded_20', 'avg_matchgoals_20', 'h2h_l10g', 'h2h_winrate_l10g', 'h2h_avggoals_scored_l10g', 'h2h_avggoals_conceded_l10g', 'h2h_avg_matchggoals_l10g']
laz_h2h__MATCH_COLS = ['betsson_home_player_elo', 'betsson_away_player_elo']
laz_h2h___CACHE = {}

def laz_h2h__search_dirs():
    """Where the h2h files may live: LAZ_UPLOADS, the engine home, the frames
    directory and its search list, and the cwd. The old list had only the
    first two and the cwd, so a file sitting in AB_frames was 'not found' and
    reported as 'not registered'."""
    OW = _m('laz_owner')
    P = OW.LAZ_OWNER.get('paths', {}) or {} if OW else {}
    ds = [os.environ.get('LAZ_UPLOADS', '.'), laz_h2h___laz_home(), P.get('parquet_dir') or '', P.get('csv_dir') or '', '.']
    for x in P.get('parquet_search') or []:
        ds.append(x)
    out = []
    for d in ds:
        if d and d not in out:
            out.append(d)
    return out

def laz_h2h__locate(sport, log=None):
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    _own = (OW.LAZ_OWNER.get('h2h_files', {}) or {}).get(sp) if OW else None
    names = (_own,) + tuple(laz_h2h__SOURCES.get(sp, ())) if _own else laz_h2h__SOURCES.get(sp)
    if not names:   # [AmunEV V2.21] any sport: <sport>_h2h_player_performance.parquet / .csv in the frames folder is picked up by name
        names = (f'{sp}_h2h_player_performance.parquet', f'{sp}_h2h_player_performance.csv')
        if not any(os.path.exists(os.path.join(d, n)) for d in laz_h2h__search_dirs() for n in names):
            names = None
    if not names:
        if log:
            log(f'[h2h] no h2h source is defined for {sport} (SOURCES has {sorted(laz_h2h__SOURCES)})')
        return None
    dirs = laz_h2h__search_dirs()
    for name in names:
        if os.path.isabs(name) and os.path.exists(name):
            if log:
                log(f'[h2h] {sport}: {name}')
            return name
        for d in dirs:
            p = os.path.join(d, name)
            if os.path.exists(p):
                if log:
                    log(f'[h2h] {sport}: reading {p}')
                return p
    if log:
        log(f'[h2h] {sport}: none of {list(names)} found in {dirs} — put the file in AB_frames or set LAZ_UPLOADS')
    return None

def laz_h2h___read(path, log=None):
    """These are CSV whatever the extension says. Sniff, never assume."""
    with open(path, 'rb') as f:
        head = f.read(4)
    if head == b'PAR1':
        return pd.read_parquet(path)
    if log:
        log(f'[h2h] {os.path.basename(path)} is CSV despite the .parquet name — reading as CSV')
    return pd.read_csv(path, low_memory=False)

def laz_h2h__load(sport, usecols=None, log=None):
    """Per-match home/away h2h and form, pivoted from the two player rows."""
    sp = str(sport).lower()
    if sp in laz_h2h___CACHE:
        return laz_h2h___CACHE[sp]
    p = laz_h2h__locate(sport, log=log)
    if p is None:
        laz_h2h___CACHE[sp] = None
        return None
    want = None
    LG = _m('laz_log')

    def _do():
        d = laz_h2h___read(p, log=log)
        d = laz_h2h___strip_result_family(d, sp, log=log)   # [v187 H1]
        d = d.copy()
        d.columns = [str(c).lower() for c in d.columns]
        d['match_id'] = d['match_id'].astype(str)
        side = d['sidepick'].astype(str).str.lower() if 'sidepick' in d.columns else None
        if side is None:
            return None
        keys = {'match_id', 'sidepick'}
        h = d[side.str.contains('home')].drop_duplicates('match_id', keep='last').set_index('match_id')
        a = d[side.str.contains('away')].drop_duplicates('match_id', keep='last').set_index('match_id')
        _idx = sorted(set(h.index) | set(a.index))
        _cols = {}
        for c in [c for c in d.columns if c not in keys]:
            if c in h.columns:
                _cols['hp_' + c] = h[c].reindex(_idx)
            if c in a.columns:
                _cols['ap_' + c] = a[c].reindex(_idx)
        # [AmunEV V2.21] the library reads home_player_wr (283 references) and away_player_wr (146): the table's total_player_wr
        # under the pivot's prefixes. It was never aliased, so every one of those terms reported 'frame lacks its inputs'.
        _alias = {'hp_actual_score': 'home_player_actual_score', 'ap_actual_score': 'away_player_actual_score', 'hp_total_games': 'home_player_total_games', 'ap_total_games': 'away_player_total_games',
                  'hp_total_player_wr': 'home_player_wr', 'ap_total_player_wr': 'away_player_wr', 'hp_player_betsson_elo': 'home_player_elo', 'ap_player_betsson_elo': 'away_player_elo'}
        for k_, v_ in _alias.items():
            if k_ in _cols and v_ not in _cols:
                _cols[v_] = _cols[k_]
        for c in ('betsson_home_player_elo', 'betsson_away_player_elo'):
            if c in h.columns:
                _cols[c] = h[c].reindex(_idx)
        out = pd.concat(_cols, axis=1) if _cols else pd.DataFrame(index=_idx)
        out.index = _idx
        return out
    out = LG.guard(f'h2h load {sport}', _do) if LG is not None else _do()
    if out is not None and log:
        log(f'[h2h] {sport}: {len(out):,} matches · {len(out.columns)} h2h/form columns from {os.path.basename(p)}')
    laz_h2h___CACHE[sp] = out
    return out

def laz_h2h__rest_features(d, sport, log=None):
    """FATIGUE / RHYTHM — the operator's rule made executable.

    eFootball and eBasketball players play 20-50 matches a day. The gap between a
    player's PREVIOUS match and THIS one, and how that gap compares with their own
    usual rhythm, is information: a player who normally takes 3-6 minutes between
    games and suddenly returns after two hours is in a different state; a player on
    a streak may chain matches faster; a losing player may pause.

    Every value here is computed from matches STRICTLY BEFORE the current one, by
    player, ordered by timestamp:

      hp_rest_min       minutes from the END of the player's previous match (its last
                        quote) to the START of this one (its first quote)
      hp_rest_vs_usual  hp_rest_min / the player's median rest over their previous
                        10 matches (1.0 = usual rhythm; 5.0 = five times the usual pause)
      hp_rest_after_loss  hp_rest_min when the previous match was LOST, else NaN —
                        the pause a loss produces
      hp_games_today    matches the player has ALREADY PLAYED in the last 24h before
                        this one (parallels count_games_last_24_hours from the h2h file)
      hp_rest_trend     rest_min minus the player's rest before THAT previous match —
                        is the pause lengthening or shortening
    and the same five for ap_. Causal by construction: the current match's own
    timestamps are used only for ITS start; everything else is history.
    """
    try:
        _p = laz_h2h__locate(sport)
        if not _p:
            return {}
        H = laz_h2h___read(_p)
    except Exception as _re:
        if log:
            log(f'[h2h] rest_features: cannot read the h2h file: {type(_re).__name__}')
        return {}
    if H is None or not len(H):
        return {}
    if 'ts' not in d.columns:
        return {}
    H = H.copy()
    H.columns = [str(c).lower() for c in H.columns]
    if 'match_id' not in H.columns:
        return {}
    H['match_id'] = H['match_id'].astype(str)
    pc = next((c for c in ('player_name', 'player', 'name') if c in H.columns), None)
    if pc is None or 'sidepick' not in H.columns:
        return {}
    t = pd.to_datetime(d['ts'], errors='coerce')
    mid = d['match_id'].astype(str)
    span = pd.DataFrame({'match_id': mid, 't0': t, 't1': t}).groupby('match_id').agg(t0=('t0', 'min'), t1=('t1', 'max')).reset_index()
    P = H[['match_id', pc, 'sidepick']].merge(span, on='match_id', how='inner')
    P['side'] = P['sidepick'].astype(str).str.lower().str[:4]
    P = P.sort_values([pc, 't0']).reset_index(drop=True)
    g = P.groupby(pc, sort=False)
    prev_t1 = g['t1'].shift(1)
    P['rest_min'] = (P['t0'] - prev_t1).dt.total_seconds() / 60.0
    P['rest_prev'] = g['rest_min'].shift(1)
    P['rest_trend'] = P['rest_min'] - P['rest_prev']
    usual = g['rest_min'].transform(lambda x: x.shift(1).rolling(10, min_periods=3).median())
    P['rest_vs_usual'] = P['rest_min'] / usual.replace(0, np.nan)
    wl = next((c for c in ('win_last_games_flag',) if c in H.columns), None)
    if wl is not None:
        P = P.merge(H[['match_id', pc, wl]].drop_duplicates(['match_id', pc]), on=['match_id', pc], how='left')
        P['rest_after_loss'] = np.where(pd.to_numeric(P[wl], errors='coerce') == 0, P['rest_min'], np.nan)
    else:
        P['rest_after_loss'] = np.nan

    def _g24(x):
        t0 = x['t0'].values.astype('datetime64[ns]').astype('int64') / 1000000000.0
        out = np.zeros(len(x))
        for i in range(len(x)):
            out[i] = int(((t0[:i] > t0[i] - 86400) & (t0[:i] < t0[i])).sum())
        return pd.Series(out, index=x.index)
    P['games_today'] = g.apply(_g24).reset_index(level=0, drop=True) if len(P) else np.nan
    out = {}
    for side, pre in (('home', 'hp_'), ('away', 'ap_')):
        Q = P[P['side'] == side].drop_duplicates('match_id').set_index('match_id')
        for c, nm in (('rest_min', 'rest_min'), ('rest_vs_usual', 'rest_vs_usual'), ('rest_after_loss', 'rest_after_loss'), ('games_today', 'games_today'), ('rest_trend', 'rest_trend')):
            out[pre + nm] = mid.map(Q[c]).astype(float).values
    if log:
        log(f'[h2h] {sport}: rest/rhythm features built for {int(np.isfinite(out.get('hp_rest_min', np.full(1, np.nan))).sum()):,} ticks (hp_/ap_ rest_min, rest_vs_usual, rest_after_loss, games_today, rest_trend)')
    return out

laz_h2h__RESULT_FAMILY = ('final_outcome', 'new_win_flag', 'actual_score', 'final_h_score', 'final_a_score', 'player_actual_score', 'initial_home_odds', 'initial_draw_odds', 'initial_away_odds', 'prob_home_win', 'prob_draw', 'prob_away_win')   # [V2.23] win_last_games_flag / win_last2games_flag are HISTORICAL (== the previous match(es) 97.5-99.5%, == this match 54%: chance) and stay admitted, as audit360's settlement-doors test requires; the opening prices and prob_* stay refused on the owner's instruction   # [V2.20] win_last2games_flag added on the owner's instruction 22 Sep: it describes the match being viewed
# [v187 H1] LINEAGE, traced on the real files (2026-09-06): each h2h row is one side of one match, and these six
# columns are THAT match's result — new_win_flag is the winner flag (exactly one 1 per match), final_outcome the
# same fact as a label, actual_score is ELO's outcome term S in {0,1} (not a score), final_h/a_score the final.
# They are the INPUT to the lagged form columns (winrate_l5g reconstructs from the lagged rolling-5 at 99.3%) and
# must never be features of the match they belong to. Refused by name at load; the >=92% agreement door remains
# as the mechanism that catches a renamed copy.

def laz_h2h___strip_result_family(h, sport, log=None):
    drop = [c for c in h.columns if c.lower() in laz_h2h__RESULT_FAMILY or any(c.lower().endswith('_' + x) for x in laz_h2h__RESULT_FAMILY)]
    if drop and log is not None:
        log(f'[h2h] {sport}: {len(drop)} column(s) REFUSED by LINEAGE — the result of the match they belong to: {drop}')
    return h.drop(columns=drop) if drop else h

def laz_h2h__attach(d, sport, log=None):
    """Map the per-match h2h table onto a tick frame. Returns the new columns."""
    H = laz_h2h__load(sport, log=log)
    if H is None or not len(H):
        return {}
    mid = d['match_id'].astype(str)
    hit = float(mid.isin(H.index).mean())
    if log:
        log(f'[h2h] {sport}: {hit:.1%} of ticks matched to an h2h row')
    if hit < 0.05:
        if log:
            log('[h2h] match_id does not join — h2h columns not attached')
        return {}
    out = {}
    for c in H.columns:
        v = mid.map(H[c])
        try:
            out[c] = pd.to_numeric(v, errors='raise').astype(float).values
        except Exception:
            out[c] = v.astype(str).where(v.notna(), None).values
    try:
        _fwcol = next((c for c in ('final_winner', 'final_result') if c in d.columns), None)
        if _fwcol is not None:
            _fw = d[_fwcol].astype(str).str.lower().str.replace('_team', '', regex=False).values
            _res = []
            for _c, _v in list(out.items()):
                _sides = ['home'] if _c.startswith(('hp_', 'home_player_')) else ['away'] if _c.startswith(('ap_', 'away_player_')) else ['home', 'away']
                try:
                    _x = np.asarray(_v, float)
                except Exception:
                    continue
                _ok = np.isfinite(_x) & np.isin(_fw, ['home', 'away'])
                if _ok.sum() < 100:
                    continue
                _xv = _x[_ok]
                _thr = 0.5 if set(np.unique(_xv[:2000])).issubset({0.0, 1.0}) else float(np.nanmedian(_xv))
                _hi = _xv > _thr if _thr != 0.5 else _xv >= 1.0
                if _hi.sum() < 30 or (~_hi).sum() < 30:
                    continue
                for _side in _sides:
                    _won = _fw[_ok] == _side
                    _agree = float(np.mean(_hi == _won))
                    if _agree >= 0.92 or _agree <= 0.08:
                        _res.append((_c, round(_agree, 3)))
                        out.pop(_c, None)
                        break
            if _res:
                _msg = f'[h2h] {sport}: {len(_res)} column(s) REFUSED as SETTLEMENT — they agree with the match result at >=92%: ' + ', '.join((f'{c} ({a:.0%})' for c, a in _res[:6]))
                (log or print)(_msg)
    except Exception as _se:
        if log:
            log(f'[h2h] settlement guard: {type(_se).__name__}: {str(_se)[:50]}')
    return out
# ==========================================================================
# LAZ_BRAIN MODULE: laz_library
# §laz_library   <- grep this anchor to land here
# OBJECTIVE : THE TOTAL CONDITION POOL
# PURPOSE   : Guarantee that every hunt operates on EVERY condition any sport has ever found useful, not just the columns its own frame happens to carry.
# HOW       : Loads the 235 harvested conditions, classifies each as NATIVE / UNIVERSAL / DERIVED / SPORT-SPECIFIC, then rebuilds what it can in the target frame: natives used directly where present, DERIVED terms reconstructed from their registered parents, and natives ABSENT from this frame mapped to the universal mechanism carrying the same meaning. Sport-specific terms are refused, never faked.
# VALUE     : Football's pool went 46 -> 77 conditions: +14 derived rebuilt from parentage, +17 natives mapped to universal equivalents, 14 refused (all q1_*, correctly, football has no quarters). Before this, a condition discovered in eFootball — u_margin_rate, line_gap, leader_wr_l5 — was invisible to football unless football independently rediscovered it, and 235 harvested conditions sat in a CSV nothing read.
# IF SKIPPED: Each sport searches only its own vocabulary and cross-sport discoveries are lost.
# ==========================================================================
"""laz_library.py — THE TOTAL CONDITION POOL. Every condition, every sport.

THE DEFECT THIS CLOSES

laz_hunt built its pool from: frame columns + 24 universal concepts +
interactions found IN THAT RUN. So a condition discovered in eFootball —
u_margin_rate, line_gap, leader_wr_l5, X_pm_ratio__x__u_trend — was invisible
to football's search unless football happened to rediscover it independently.

235 distinct conditions were harvested from 753 strategies, 221 of them
adaptable to any scoring sport. They were sitting in a CSV that nothing read.

WHAT THIS DOES

  1 LOADS every harvested condition with its lineage and resolution time.
  2 CLASSIFIES each as NATIVE (a frame column), UNIVERSAL (already sport-
    agnostic), DERIVED (manufactured, rebuildable from parents), or
    SPORT-SPECIFIC (refused — q1_* has no football analogue).
  3 REBUILDS what it can in any frame:
      · a native column present in this frame is used directly
      · a DERIVED condition is rebuilt from its parents if BOTH are available
      · a native column ABSENT from this frame is mapped to its universal
        equivalent where one exists, so the MECHANISM transfers even when the
        column does not
  4 RETURNS the total pool, so laz_hunt always operates on everything known.

THE RULE: the pool is the UNION of what this frame carries and what every
other sport has ever found useful, minus what cannot exist here.
"""
import numpy as np, pandas as pd, os, re, json

def laz_library___laz_home():
    """The directory this run writes to. Defaults to the CURRENT directory,
    never the container the engine was built in. _laz_home() shipped inside
    the single file and every write failed on the operator's machine with
    FileNotFoundError after the search had already run."""
    import os as _o
    OW = _m('laz_owner') if '_m' in globals() else None
    if OW is not None:
        d = (getattr(OW, 'LAZ_OWNER', {}).get('paths', {}) or {}).get('output_dir')
        if d:
            return d
    return _o.environ.get('LAZ_HOME') or _o.getcwd()
laz_library__LIB_CSV = os.environ.get('LAZ_LIBRARY', __import__('os').path.join(laz_library___laz_home(), 'CONDITION_LIBRARY.csv'))
laz_library__NATIVE_TO_UNIVERSAL = {'min_since_goal': 'u_since_score', 'since_score': 'u_since_score', 'minute': 'u_elapsed', 'prog': 'u_elapsed', 'frac': 'u_elapsed', 'remain': 'u_remain', 'sets': 'u_elapsed', 'lead': 'u_margin', 'sd': 'u_margin', 'live_lead': 'u_margin', 'h_score': 'u_margin', 'lead_per_remaining': 'u_margin_rate', 'margin_rate': 'u_margin_rate', 'tg': 'u_total', 'run_tot': 'u_total', 'pace': 'u_pace', 'pace_ratio': 'u_pace', 'vf_backed': 'u_vf', 'imp_home': 'u_vf', 'imp_away': 'u_vf', 'overround': 'u_overround', 'pm_ratio': 'u_ratio_open', 'open_line': 'u_price_open', 'u_open': 'u_price_open', 'drift_from_open': 'u_drift', 'price_drift_open': 'u_drift', 'l_move': 'u_trend', 'dog_odds_vol': 'u_vol', 'bk_vol': 'u_vol', 'lead_changes': 'u_lead_flips', 'time_in_lead': 'u_time_in_lead', 'imbal': 'u_ratio', 'price_spread': 'u_ratio'}

def laz_library__load(path=None):
    p = path or laz_library__LIB_CSV
    if not os.path.exists(p):
        return pd.DataFrame()
    d = pd.read_csv(p)
    if 'term' not in d.columns and d.columns[0].lower() in ('unnamed: 0', 'index'):
        d = d.rename(columns={d.columns[0]: 'term'})
    return d

def laz_library__classify(term, frame_cols, universal_names):
    t = str(term)
    tl = t.lower()
    if tl.startswith('x_'):
        return 'DERIVED'
    if t in universal_names or tl in [u.lower() for u in universal_names]:
        return 'UNIVERSAL'
    if t in frame_cols:
        return 'NATIVE_PRESENT'
    if tl in laz_library__NATIVE_TO_UNIVERSAL:
        return 'NATIVE_MAPPABLE'
    return 'NATIVE_ABSENT'

def laz_library__build_total_pool(d, existing_pool, universal_names, sport, lib=None, log=None):
    """THE TOTAL POOL. Everything this frame carries plus everything any sport
    has found useful, rebuilt where possible."""
    _LA = _m('laz_lookahead')
    lib = lib if lib is not None else laz_library__load()
    pool = dict(existing_pool)
    cols = set(d.columns)
    added_native = 0
    rebuilt = 0
    mapped = 0
    refused = []
    if not len(lib):
        return (pool, dict(added=0, note='library empty'))
    for _, r in lib.iterrows():
        t = str(r.get('term', ''))
        if not t or t in pool:
            continue
        if 'adaptable' in lib.columns and r.get('adaptable') in (False, 'False'):
            refused.append(t)
            continue
        kind = laz_library__classify(t, cols, universal_names)
        if kind == 'NATIVE_PRESENT':
            v = pd.to_numeric(d[t], errors='coerce')
            if v.notna().mean() > 0.4 and v.nunique() > 3:
                pool[t] = v.values.astype(float)
                added_native += 1
        elif kind == 'DERIVED':
            tl = t.lower()
            if tl not in _LA.PARENTAGE:
                pp = _LA.parse_parents(tl)
                if pp:
                    _LA.register_derived(tl, pp)
            par = _LA.PARENTAGE.get(tl, ())
            if len(par) == 2:
                a, b = par
                A = pool.get(a) if a in pool else pd.to_numeric(d[a], errors='coerce').values if a in cols else None
                B = pool.get(b) if b in pool else pd.to_numeric(d[b], errors='coerce').values if b in cols else None
                if A is None or B is None:
                    A = A if A is not None else pool.get(laz_library__NATIVE_TO_UNIVERSAL.get(a, ''))
                    B = B if B is not None else pool.get(laz_library__NATIVE_TO_UNIVERSAL.get(b, ''))
                if A is not None and B is not None:
                    A = np.asarray(A, float)
                    B = np.asarray(B, float)
                    if '__minus__' in tl:
                        v = A - B
                    elif '__over__' in tl:
                        with np.errstate(divide='ignore', invalid='ignore'):
                            v = np.where(np.abs(B) > 1e-09, A / B, np.nan)
                    else:
                        v = A * B
                    if np.nanstd(v[~np.isnan(v)] if (~np.isnan(v)).any() else np.array([0.0])) > 0:
                        pool[t] = v
                        rebuilt += 1
                        _LA.register_derived(t, [a, b])
        elif kind == 'NATIVE_MAPPABLE':
            u = laz_library__NATIVE_TO_UNIVERSAL[t.lower()]
            if u in pool and f'{t}__as__{u}' not in pool:
                pool[f'{t}__as__{u}'] = pool[u]
                mapped += 1
    rep = dict(added_native=added_native, rebuilt_derived=rebuilt, mapped_to_universal=mapped, refused=len(refused), total=len(pool))
    if log:
        log(f'[library] +{added_native} native · +{rebuilt} derived rebuilt · +{mapped} mapped to universal · {len(refused)} refused (sport-specific) -> TOTAL POOL {len(pool)}')
    return (pool, rep)

def laz_library__dump(path=__import__('os').path.join(laz_library___laz_home(), 'CONDITION_LIBRARY_FULL.csv')):
    """Write the library with classification, lineage and resolution time."""
    _LA = _m('laz_lookahead')
    _TR = _m('laz_transfer')
    lib = laz_library__load()
    if not len(lib):
        return None
    rows = []
    for _, r in lib.iterrows():
        t = str(r.get('term', ''))
        tl = t.lower()
        if tl.startswith('x_') and tl not in _LA.PARENTAGE:
            pp = _LA.parse_parents(tl)
            if pp:
                _LA.register_derived(tl, pp)
        rows.append(dict(term=t, uses=r.get('uses'), sports_seen=r.get('sports'), validated_uses=r.get('validated'), adaptable=bool(_TR.transferable(t)), resolves_at=_LA.resolves_at(tl), parents='|'.join(_LA.PARENTAGE.get(tl, ())), universal_equivalent=laz_library__NATIVE_TO_UNIVERSAL.get(tl, ''), kind='DERIVED' if tl.startswith('x_') else 'UNIVERSAL' if tl.startswith('u_') else 'NATIVE'))
    D = pd.DataFrame(rows).sort_values('uses', ascending=False)
    D.to_csv(path, index=False)
    return D
