def causality_guard___genome_live_terms():
    """Every term the genome records as live and resolving at tick 0 — the
    builders, the ported brain features, the model score, the drift terms.
    ONE source: a term documented as causal in the genome is certified here,
    so Mode 5 and the hunt see the same vocabulary the sweep does. Before
    this, L3 refused grind_form, model_edge, dp_lead_open, even implied."""
    try:
        import sys as _sys
        GN = _sys.modules.get('laz_genome')
        if GN is None:
            _rm = globals().get('_m')
            GN = _rm('laz_genome') if callable(_rm) else None
        if GN is None:
            return set()
        try:
            GN.bootstrap()
        except Exception as _e:
            pass
        return {k for k, v in GN.GENOME.items() if 'live' in str(v.get('causality', '')).lower()}
    except Exception:
        return set()

def causality_guard___certified(sport):
    """Certified features for a sport, plus the production-book terms which
    are sport-agnostic live state, plus every genome term recorded as live."""
    _rm = globals().get('_m')
    _OWm = _rm('laz_owner') if callable(_rm) else None
    try:
        sport = _OWm.canon(sport) if _OWm is not None else sport
    except Exception as _ce:
        # [HARD-FIX SILENT] recorded, not hidden: this swallow can leave a stale
        # value that changes a result. laz_sink__report lists it at exit.
        laz_sink__swallow('causality_guard:certified:sport', _ce)
    _home = os.getcwd()
    try:
        if _OWm is not None:
            _home = _OWm.LAZ_OWNER['paths'].get('output_dir') or _home
    except Exception as _he:
        # [HARD-FIX SILENT] recorded, not hidden: this swallow can leave a stale
        # value that changes a result. laz_sink__report lists it at exit.
        laz_sink__swallow('causality_guard:certified:home', _he)
    f = os.path.join(_home, f'causal_{sport}.csv')
    if os.path.exists(f):
        d = pd.read_csv(f)
        return set(d[d.verdict == 'CERTIFIED'].feature.astype(str)) | set(causality_guard__PRODUCTION_TERMS) | set(causality_guard__LIVE_COUNTERS) | causality_guard___genome_live_terms()
    ALIAS = {'efbig': 'efootball', 'ef': 'efootball', 'tt': 'tabletennis'}
    _k = str(sport).lower()
    e = causality_guard__CERTIFIED_EMBEDDED.get(_k) or causality_guard__CERTIFIED_EMBEDDED.get(ALIAS.get(_k, _k))
    return set(e or ()) | set(causality_guard__PRODUCTION_TERMS) | set(causality_guard__LIVE_COUNTERS) | causality_guard___genome_live_terms()

def causality_guard__check_term(term, sport, entry_cp, certified=None):
    """Returns (ok:bool, reason:str). Default is DENY."""
    t = str(term).strip()
    tl = t.lower()
    base = re.sub('^(bk_|op_|gap_|PT(bk|op|gap|base)_|PT_(hp|ap)_)', '', t)
    if tl in causality_guard__HARD_DENY:
        return (False, 'L1 hard deny: settlement or match-end field')
    if laz_tutorial__is_settlement_column(tl):
        return (False, 'L1 hard deny: live-price-level leak or settlement flag (Tutorial 6 §1.2 — the class, not the feature)')   # [v247-TUT-B1] wired, not just defined
    try:
        _EVc = _m('laz_everything')
        _OWc = _m('laz_owner')
        _spc = _OWc.canon(sport) if _OWc is not None and hasattr(_OWc, 'canon') else str(sport).lower()
        if _EVc is not None and _spc in getattr(_EVc, 'CLOCKLESS', ()):
            _fam = ('prog', 'u_elapsed', 'u_remain', 'u_margin_rate', 'u_pace', 'u_drought', 'frac', 'league_time_progress', 'league_minutes')
            import re as _re
            _parts = [p for p in _re.split('__(?:minus|over|x)__|^x_', tl) if p]
            if tl in _fam or any((p in _fam for p in _parts)):
                return (False, f'L1 hard deny: {sport} has no clock — the elapsed family cannot be defined on it')
    except Exception as _ce:
        pass
    if tl in causality_guard__STATE_SCOPED:
        return (True, 'L2-state: RECORD of a past event, legal ONLY where validate_state() confirms the event had occurred at the armed tick. Build-time validation is mandatory.')
    _ra = causality_guard__resolves_at(tl)
    if _ra == 'event':
        _ra = None   # an event term is gated per ROW at L2 (validate_state), never by a fraction of the match
    if _ra is not None and entry_cp is not None and (float(entry_cp) < float(_ra)):
        return (False, f'L1b checkpoint: {t} resolves at {_ra} of the match, entry is at {float(entry_cp):.3f}')
    if any((s in tl for s in causality_guard__DENY_SUBSTR)):
        return (False, f'L1 hard deny: matches forbidden pattern')
    for pre, (minc, why) in causality_guard__SCOPED.items():
        if tl.startswith(pre) or base.lower().startswith(pre) or f'_{pre}' in tl or (f'_{pre}' in base.lower()):
            if entry_cp is None:
                return (False, f'L2 scope: {pre}* requires an entry checkpoint and none was supplied')
            if float(entry_cp) < minc:
                return (False, f'L2 scope VIOLATION: {pre}* needs entry >= {minc}, got {entry_cp}. {why}')
            return (True, f'L2 scope OK: entry {entry_cp} >= {minc}')
    if t in causality_guard__DERIVED or base in causality_guard__DERIVED:
        inputs = causality_guard__DERIVED.get(t, causality_guard__DERIVED.get(base, []))
        if certified is None:
            certified = causality_guard___certified(sport)
        for inp in inputs:
            ok, why = causality_guard__check_term(inp, sport, entry_cp, certified)
            if not ok:
                return (False, f'DERIVED {t} inherits from {inp}: {why}')
        return (True, f'derived by construction from {inputs} (all legal at this entry)')
    for pre, stem in causality_guard__DERIVED_PREFIX.items():
        if t.startswith(pre):
            return (True, f'derived pair feature ({pre}*) built from {stem}* columns')
    if certified is None:
        certified = causality_guard___certified(sport)
    if certified is None:
        return (False, f'L3 structural: no causal_{sport}.csv exists - the audit has never been run for this sport')
    if t in certified or base in certified:
        return (True, 'L3 certified by structural audit')
    if t in causality_guard__PLAYER_TABLE_OK or base in causality_guard__PLAYER_TABLE_OK:
        return (True, 'player-history table, proven as-of-match-date (excludes the current game)')
    return (False, f'L3 structural: term not on the certified list for {sport} (default is DENY)')

def causality_guard__assert_causal(condition_string, sport, entry_cp):
    """Raises LookaheadError on the first illegal term. Call before RECORDING a strategy."""
    cert = causality_guard___certified(sport)
    bad = []
    for t in causality_guard___terms(condition_string):
        ok, why = causality_guard__check_term(t, sport, entry_cp, cert)
        if not ok:
            bad.append((t, why))
    if bad:
        raise causality_guard__LookaheadError(f'[{sport} entry={entry_cp}] ' + ' | '.join((f'{t}: {w}' for t, w in bad)))
    return True

def causality_guard__audit_book(df, sport_col='sport', cond_col='conditions', entry_col='entry'):
    """Retroactive audit of an existing book. Returns the book plus a verdict column."""
    out = []
    cache = {}
    for _, r in df.iterrows():
        sp = str(r.get(sport_col, '')) or 'unknown'
        if sp not in cache:
            cache[sp] = causality_guard___certified(sp)
        cp = r.get(entry_col, None)
        bad = []
        for t in causality_guard___terms(r.get(cond_col, '')):
            ok, why = causality_guard__check_term(t, sp, cp, cache[sp])
            if not ok:
                bad.append(f'{t} -> {why}')
        out.append('PASS' if not bad else 'REFUSED: ' + '; '.join(bad))
    d = df.copy()
    d['causality_guard'] = out
    return d
