def laz_pca__manifest(sport):
    # [V2.1-PCA-PROD] the frozen PCA transforms for a sport ({pc_<i>: {terms, mu, sdv, w, n_fit}}), or {}.
    import os as _o, json as _j
    OW = _m('laz_owner') if globals().get('_m') else None
    _home = (OW.LAZ_OWNER['paths'].get('output_dir') if OW else None) or _o.getcwd()
    _fp = _o.path.join(_home, f'laz_pca_{sport}.json')
    if _o.path.exists(_fp):
        try:
            with open(_fp) as _fh:
                return _j.load(_fh)
        except Exception:
            return {}
    return {}


