                    _sdv = _pcmf.get('sdv') or []
                    _w = _pcmf.get('w') or []
                    _parts = ' + '.join(f'((out[{g!r}] - {_mu[j]:.9g}) / {_sdv[j]:.9g}) * {_w[j]:.9g}' for j, g in enumerate(_pcmf.get('terms') or []))
