laz_arming___SPECS = [None]


def laz_arming__specs():
    """[v243] memoised spec store (load_specs reads disk/embedded JSON — never per leg)."""
    if laz_arming___SPECS[0] is None:
        SP = _m('laz_specs')
        laz_arming___SPECS[0] = (SP.load_specs() if SP is not None else {}) or {}
    return laz_arming___SPECS[0]


def laz_specs__arming_fields(spec):
    """[v243] the five arming-rule fields for a spec: base — the hole that left 61 spec
    strategies undeployable. Emitted per strategy row so production never guesses."""
    spec = spec or {}
    return dict(extra_mask=spec.get('extra_mask'), win_col=spec.get('win_col'),
                win_value=spec.get('win_value'), odds_col=spec.get('odds_col'),
                payout_odds_col=spec.get('payout_odds_col'))


def laz_arming__spec_fields_for(base_name):
    """[v243] the arming fields for a spec: base name, or None for a non-spec base."""
    bn = str(base_name)
    if not bn.startswith('spec:'):
        return None
    return laz_specs__arming_fields(laz_arming__specs().get(bn[5:], {}))


def laz_arming__price_cols_for(market):
    """[v243] the price column(s) that carry a market's prices."""
    mk = str(market or 'moneyline').lower()
    if mk in ('totals', 'total_goals_handicap'):
        return ('total_goals_over', 'total_goals_under')
    if mk in ('total_points_handicap',):
        return ('total_points_over', 'total_points_under')
    if mk in ('spread', 'handicap'):
        return ('point_spread_home', 'point_spread_away')
    if mk == 'h1_result':
        return ('first_half_result_home', 'first_half_result_draw', 'first_half_result_away')
    if mk == 'h1_totals':
        return ('first_half_total_goals_over', 'first_half_total_goals_under')
    if mk == 'btts':
        return ('both_teams_to_score_yes', 'both_teams_to_score_no')
    if mk == 'double_chance':
        return ('double_chance_1x', 'double_chance_x2', 'double_chance_12')
    if mk == 'set_winner_mkt':
        return ('set_1_winner_home', 'set_1_winner_away', 'set_2_winner_home', 'set_2_winner_away')
    if mk == 'games_totals':
        return ('match_games_over', 'match_games_under')
    if mk == 'set_games_totals':
        return ('set_1_games_over', 'set_1_games_under')   # [v246-SMK3]
    return ('home_odds', 'away_odds', 'draw_odds')


def laz_arming__ladder_for(market, px):
    """[v243] the price ladder per market: moneyline keeps the shared book ladder; every
    other market gets edges from ITS OWN populated price distribution (the shared ladder
    was market-blind — ENGINE_GUIDE's known gap). Edges = 18 quantiles of the market's
    finite prices above 1.0, plus the open cap."""
    import numpy as _np
    mk = str(market or 'moneyline').lower()
    if mk == 'moneyline':
        return None
    v = _np.asarray(px, float)
    v = v[_np.isfinite(v) & (v > 1.0)]
    if len(v) < 200:
        return None
    qs = _np.unique(_np.nanquantile(v, _np.linspace(0.02, 0.98, 18)))
    return [float(x) for x in qs] + [1000000000.0]


def laz_arming__contract(sport, engine_sha=''):
    """[v243 Phase 3] ARMING_CONTRACT_<sport>: the ten-step arming rule as data, per base
    its needs/market/tie rule, per spec base its five arming fields, and the market
    windows. Production's evaluator is generated from this — with NO pre-loop gates."""
    REG = _m('laz_registry')
    out = dict(
        sport=str(sport).lower(), engine_sha=engine_sha,
        order=['1. gates before any strategy runs: NONE (LA-12-P2)',
               '2. side resolution: the base fn, its needs, its tie rule',
               '3. price for the side: the market price column',
               '4. band test: band_lo <= price <= band_hi (inclusive both ends)',
               '5. min_odds_req',
               '6. conditions: all must hold; a NULL term value fails the condition',
               '7. eligibility: the match is in the search population',
               '8. first qualifying tick per (match, strategy); nothing after it',
               '9. playability: market_status and selection_status open at the arming tick',
               '10. the market window: period markets arm inside their open window only'],
        bases={}, spec_arming={}, market_windows={},
        rules=dict(band='inclusive both ends', null_term='fails the condition',
                   first_tick='first qualifying tick per (match, strategy)',
                   gates_before_loop='NONE'))
    for name, bs in ((getattr(REG, 'BASES', None) or {}) if REG is not None else {}).items():
        if not isinstance(bs, dict) or 'fn' not in bs:
            continue
        out['bases'][name] = dict(needs=list(bs.get('needs') or ()), market=bs.get('market', 'moneyline'),
                                  tie_rule=bs.get('tie_rule'), backs=bs.get('backs', ''))
    _dead = 0
    for sn, spc in (laz_arming__specs() or {}).items():
        if not spc.get('win_col') or not spc.get('odds_col'):
            _dead += 1   # can never arm (laz_specs__arm returns None without both) — excluded
            continue
        out['spec_arming']['spec:' + str(sn)] = laz_specs__arming_fields(spc)
    if _dead:
        out['dead_spec_entries'] = _dead   # metadata/dead entries, reported not emitted
    for (sp, mk), win in laz_arming__MARKET_WINDOWS.items():
        if sp == str(sport).lower():
            out['market_windows'][mk] = win
    return out


def laz_arming__prove(contract, sport):
    """[v243] the arming contract is complete: every base has needs + market; every spec
    base has win_col + odds_col; the order has all ten steps. Fails by name."""
    bad = []
    for name, b in contract['bases'].items():
        if b.get('market') is None:
            bad.append(f'base {name}: no market')
    for name, f in contract['spec_arming'].items():
        if f.get('odds_col') and not f.get('win_col'):
            bad.append(f'{name}: arming-capable but no win_col')
        # entries with no odds_col are metadata entries, not arming bases — not checked
    if len(contract['order']) != 10:
        bad.append(f"order has {len(contract['order'])} steps (need 10)")
    ok = not bad
    return ok, (f'{sport}: contract complete — {len(contract["bases"])} bases · '
                f'{len(contract["spec_arming"])} spec arming rules · {len(contract["market_windows"])} market windows'
                if ok else '; '.join(bad[:8]))

