# [v241b] SELF-CONTAINED phase machinery (audit360/audit_full's CLASS 3e: no cross-section
# name reads). Identical logic to laz_genome___phase_norm/phase_series/at_phase_end.
laz_quarantine___UNKNOWN_PHASE = {'', 'NAN', 'NONE', 'NULL', 'UNKNOWN'}


def laz_quarantine___phase_norm(v):
    x = str(v).upper().strip().split(',')[0].replace(' ', '').replace('QUARTER', 'Q').replace('HALF', 'H')
    import re as _re
    m = _re.match(r'^(\\d)(ST|ND|RD|TH)?Q$|^Q(\\d)$', x)
    if m:
        return 'Q' + (m.group(1) or m.group(3))
    m = _re.match(r'^(\\d)(ST|ND|RD|TH)?H$|^H(\\d)$', x)
    if m:
        return '1H' if (m.group(1) or m.group(3)) == '1' else '2H'
    if x.startswith('HT') or 'HALFT' in x:
        return 'HT'
    if x.startswith('OT') or 'OVERT' in x or x.startswith('ET'):
        return 'OT'
    if x in ('FT', 'FULLTIME', 'END', 'FINISHED'):
        return 'FT'
    return x


def laz_quarantine___phase_series(M, phase):
    import pandas as _pd, numpy as _np
    ph = _pd.Series([laz_quarantine___phase_norm(x) for x in _np.asarray(phase)])
    ph = ph.where(~ph.isin(laz_quarantine___UNKNOWN_PHASE))
    return ph.groupby(_np.asarray(M)).ffill().fillna('').values


def laz_quarantine___at_phase_end(v, M, phase, done_phases):
    '''[v241b] the value of v at the first tick whose phase is beyond done_phases —
    anchored on the observed phase change; NaN before, held after. Self-contained copy of
    the genome's semantics (no cross-section name read).'''
    import numpy as _np, pandas as _pd
    v = _np.asarray(v, float)
    Ma = _np.asarray(M)
    ph = laz_quarantine___phase_series(Ma, phase)
    out = _np.full(len(v), _np.nan)
    done = set(done_phases)
    for m, idx in _pd.Series(_np.arange(len(v))).groupby(Ma).indices.items():
        idx = _np.asarray(idx)
        p = ph[idx]
        seen_done = _np.cumsum(_np.isin(p, list(done))) > 0
        hit = _np.where(seen_done & ~_np.isin(p, list(done)))[0]
        if len(hit):
            k = idx[hit[0] - 1] if hit[0] > 0 else idx[hit[0]]
            out[idx[hit[0]:]] = v[k]
    return out


def laz_quarantine___at_boundary(v, M, phase, done_phases):
    '''[v246-MAP] the value at the FIRST tick after the done phase group — for sports whose
    result posts at the transition (esports map scores). NaN before, held after.'''
    import numpy as _np, pandas as _pd
    v = _np.asarray(v, float)
    Ma = _np.asarray(M)
    ph = laz_quarantine___phase_series(Ma, phase)
    out = _np.full(len(v), _np.nan)
    done = set(done_phases)
    for m, idx in _pd.Series(_np.arange(len(v))).groupby(Ma).indices.items():
        idx = _np.asarray(idx)
        p = ph[idx]
        seen_done = _np.cumsum(_np.isin(p, list(done))) > 0
        hit = _np.where(seen_done & ~_np.isin(p, list(done)))[0]
        if len(hit):
            out[idx[hit[0]:]] = v[idx[hit[0]]]
    return out


def laz_quarantine___final(v, M):
    '''[v246-MAP] the last value of v per match (the final map score).'''
    import numpy as _np, pandas as _pd
    return _pd.Series(_np.asarray(v, float)).groupby(_np.asarray(M)).transform('last').values


def laz_quarantine__done_for(sport, kind):
    return laz_quarantine__DONE.get(kind, {}).get(str(sport).lower())


def laz_quarantine__period_or(pool, name, n):
    """[v241 LA-11] a period term comes from the REBUILT pool, or it is NaN — never the
    original frame column. No guards, only construction."""
    import numpy as _npq
    if pool is not None and name in pool:
        return pool[name]
    return _npq.full(n, _npq.nan)


def laz_quarantine__view(d, sport):
    """[v241 Phase 1] the frame builders may see: OUTCOME columns physically absent,
    original period columns physically absent, period terms rebuilt by at_phase_end
    (NaN before the observed transition, the period's final value after — anchored on
    the phase change itself, so it needs no clock and cannot leak)."""
    import numpy as _np, pandas as _pd
    drop = [c for c in d.columns if c in laz_quarantine__OUTCOME or c in laz_quarantine__PERIOD_COLS]
    dv = d.drop(columns=drop, errors='ignore')
    sp = str(sport).lower()
    if 'phase' in d.columns and 'h_score' in d.columns and 'a_score' in d.columns:
        M = d['match_id'].values
        ph = d['phase'].values
        hs = _pd.to_numeric(d['h_score'], errors='coerce').values
        as_ = _pd.to_numeric(d['a_score'], errors='coerce').values
        _done_ht = laz_quarantine__done_for(sp, 'ht')
        if _done_ht:
            hth = laz_quarantine___at_phase_end(hs, M, ph, _done_ht)
            hta = laz_quarantine___at_phase_end(as_, M, ph, _done_ht)
            dv['ht_h'] = hth
            dv['ht_a'] = hta
            dv['ht_diff'] = _np.abs(hth - hta)
            dv['h1_h'] = hth
            dv['h1_a'] = hta
        _done_q1 = laz_quarantine__done_for(sp, 'q1')
        if _done_q1:
            q1h = laz_quarantine___at_phase_end(hs, M, ph, _done_q1)
            q1a = laz_quarantine___at_phase_end(as_, M, ph, _done_q1)
            dv['q1_h'] = q1h
            dv['q1_a'] = q1a
            dv['q1_tot'] = q1h + q1a
            dv['q1_lead'] = _np.abs(q1h - q1a)
            dv['q1_margin'] = q1h - q1a
        _done_h1 = laz_quarantine__done_for(sp, 'h1')
        if _done_h1:
            h1h = laz_quarantine___at_phase_end(hs, M, ph, _done_h1)
            h1a = laz_quarantine___at_phase_end(as_, M, ph, _done_h1)
            dv['h1_h'] = h1h
            dv['h1_a'] = h1a
            dv['ht_h'] = h1h
            dv['ht_a'] = h1a
            dv['ht_diff'] = _np.abs(h1h - h1a)
        _done_h2 = laz_quarantine__done_for(sp, 'h2')
        if _done_h2:
            dv['h2_h'] = laz_quarantine___at_phase_end(hs, M, ph, _done_h2)
            dv['h2_a'] = laz_quarantine___at_phase_end(as_, M, ph, _done_h2)
        _done_s2 = laz_quarantine__done_for(sp, 's2')
        if _done_s2 and 'home_team_set2_score' in d.columns and 'away_team_set2_score' in d.columns:
            # [v246-SMK] set-2 winner from the per-set SCORE columns, visible only once set 2 has
            # observably closed (the set count reached 2). NaN before — never early.
            _s2h = _pd.to_numeric(d['home_team_set2_score'], errors='coerce').values
            _s2a = _pd.to_numeric(d['away_team_set2_score'], errors='coerce').values
            _sets_now = _pd.to_numeric(d['h_score'], errors='coerce').values + _pd.to_numeric(d['a_score'], errors='coerce').values if 'h_score' in d.columns else _np.full(len(dv), _np.nan)
            _s2w = _np.empty(len(dv), dtype=object); _s2w[:] = None
            _dec = (_sets_now >= 2) & _np.isfinite(_s2h) & _np.isfinite(_s2a)
            _s2w[_dec & (_s2h > _s2a)] = 'home'
            _s2w[_dec & (_s2a > _s2h)] = 'away'
            dv['set2_winner'] = _s2w
        _done_s1 = laz_quarantine__done_for(sp, 's1')
        if _done_s1:
            s1h = laz_quarantine___at_phase_end(hs, M, ph, _done_s1)
            s1a = laz_quarantine___at_phase_end(as_, M, ph, _done_s1)
            _s1w = _np.empty(len(dv), dtype=object); _s1w[:] = None   # [v246-NP2] numpy 2 refuses str-vs-nan promotion in np.where — object array, None = undecided
            _s1w[s1h > s1a] = 'home'; _s1w[s1a > s1h] = 'away'
            dv['set1_winner'] = _s1w
        _done_m1 = laz_quarantine__done_for(sp, 'm1')
        if _done_m1:
            if sp == 'esports':
                # [v246-MAP] CAUSAL ONLY: the map result is knowable at the boundary and never
                # before — no final/fw fills here (they filled pre-boundary ticks and
                # prove_causal rightly refuses that). The RESOLVED label (for settlement) is
                # built at measure time in laz_mode3__find, not in the builder view.
                _b1h = laz_quarantine___at_boundary(hs, M, ph, _done_m1)
                _b1a = laz_quarantine___at_boundary(as_, M, ph, _done_m1)
                _m1w = _np.empty(len(dv), dtype=object); _m1w[:] = None   # [v246-NP2]
                _m1w[(_b1h > _b1a) & _np.isfinite(_b1h) & _np.isfinite(_b1a)] = 'home'
                _m1w[(_b1a > _b1h) & _np.isfinite(_b1h) & _np.isfinite(_b1a)] = 'away'
                dv['set1_winner'] = _m1w
                dv['set1_winner_n'] = _np.where(_m1w == 'home', 1.0, _np.where(_m1w == 'away', 0.0, _np.nan))   # [v246-MAP] pool-safe twin
            else:
                m1h = laz_quarantine___at_phase_end(hs, M, ph, _done_m1)
                m1a = laz_quarantine___at_phase_end(as_, M, ph, _done_m1)
                _m1w = _np.empty(len(dv), dtype=object); _m1w[:] = None   # [v246-NP2]
                _m1w[m1h > m1a] = 'home'; _m1w[m1a > m1h] = 'away'
                dv['set1_winner'] = _m1w
        _done_m2 = laz_quarantine__done_for(sp, 'm2')
        if _done_m2:
            # [v246-MAP] CAUSAL ONLY — boundary read, no fills (see the m1 note).
            _b2h = laz_quarantine___at_boundary(hs, M, ph, _done_m2)
            _b2a = laz_quarantine___at_boundary(as_, M, ph, _done_m2)
            _b1h = laz_quarantine___at_boundary(hs, M, ph, _done_m1) if _done_m1 else _np.full(len(dv), _np.nan)
            _b1a = laz_quarantine___at_boundary(as_, M, ph, _done_m1) if _done_m1 else _np.full(len(dv), _np.nan)
            _d2h = _b2h - _b1h   # map 2's own result: maps through map 2 minus maps through map 1
            _d2a = _b2a - _b1a
            _m2w = _np.empty(len(dv), dtype=object); _m2w[:] = None
            _m2w[(_d2h > _d2a) & _np.isfinite(_d2h) & _np.isfinite(_d2a)] = 'home'
            _m2w[(_d2a > _d2h) & _np.isfinite(_d2h) & _np.isfinite(_d2a)] = 'away'
            dv['map2_winner_n'] = _np.where(_m2w == 'home', 1.0, _np.where(_m2w == 'away', 0.0, _np.nan))   # [v246-MAP] pool-safe twin
            dv['map2_winner'] = _m2w
    return dv


def laz_quarantine__prove_structure(d_view, sport):
    """[v241 prove_quarantine] structural: no OUTCOME column and no ORIGINAL period
    column may be present in the frame the builders receive. Fails the build by name."""
    bad = [c for c in d_view.columns if c in laz_quarantine__OUTCOME]
    if bad:
        return False, f'BREACHED by outcome columns in the builder frame: {bad}'
    leaked = [c for c in d_view.columns
              if c in laz_quarantine__PERIOD_COLS and c not in laz_quarantine___REBUILT]
    if leaked:
        return False, f'BREACHED by original period columns in the builder frame: {leaked}'
    return True, (f'{sport}: 0 outcome columns and 0 original period columns in the builder frame '
                  f'(quarantine holds; period terms are at_phase_end constructions)')


def laz_quarantine__prove_causal(d_view, sport, sample=50):
    """[v241 prove_period] every rebuilt period term is NaN on the first tick of every
    sampled match (the period has not observably ended there). The 630/76 class of
    future-reads is impossible by construction."""
    import numpy as _np, pandas as _pd
    terms = [t for t in laz_quarantine___REBUILT if t in d_view.columns]
    if not terms:
        return True, f'{sport}: no rebuilt period terms on this frame — nothing to prove'
    first_ix = d_view.groupby('match_id', sort=False).head(1).index
    bad = {}
    for t in terms:
        v = _pd.to_numeric(d_view[t], errors='coerce')
        n_bad = int(v.loc[first_ix].notna().sum())
        if n_bad:
            bad[t] = n_bad
    if bad:
        return False, f'period terms defined BEFORE their phase transition on match-first ticks: {bad}'
    return True, f'{sport}: {len(terms)} rebuilt period terms NaN on every match-first tick (sampled)'


def laz_startup___augment_missing(d, sport, missing, pool, log, chunk=None, n_matches=40, keep_frac=0.6, workers=None):
    """[v187 F16] Build `missing` terms with the legacy `_laz_augment_frame` (the owner's feature
    library), test each one for lookahead the way the truncation guard does, and admit the survivors
    into `pool`. Returns (built_names, refused_names, note). Reads the legacy function through
    globals() so the LAZ_BRAIN region has no static dependency on the legacy region."""
    aug = globals().get('_laz_augment_frame')
    if aug is None:
        return ([], [], 'legacy feature library NOT LOADED — run_m5 must execute the whole engine file, not from the marker')
    built, refused, errs = [], [], 0
    import warnings as _wn
    chunk = int(chunk or __import__('os').environ.get('LAZ_LIB_CHUNK') or 40)   # [v187 D5] the library walks EVERY tick per call; fewer calls matter more than memory
    rng = np.random.default_rng(0)
    mids = pd.unique(d['match_id'].values)
    samp = set(rng.choice(mids, size=min(n_matches, len(mids)), replace=False).tolist())
    _in = d['match_id'].isin(samp).values
    sub = d.loc[_in]
    _cc = sub.groupby('match_id').cumcount().values
    _n = sub.groupby('match_id')['match_id'].transform('size').values
    _keep = _cc < np.maximum(1, np.floor(_n * keep_frac))
    _pos = np.flatnonzero(_keep)          # positions of the kept rows WITHIN sub (augment keeps row order, resets the index)
    trunc = sub.loc[_keep]
    _all = [t for t in missing if t not in pool]
    # [v192 K1] the cache: anything whose stamp still matches is loaded, tested by the truncation door below like
    # any other term, and never rebuilt. Only the rest goes to the builders.
    _sc_keys = pd.DataFrame(dict(__mid=d['match_id'].astype(str).values, __ts=pd.to_datetime(d['ts']).values)) if {'match_id', 'ts'} <= set(d.columns) else None
    _cached, _all = laz_sidecar__load(sport, _all, len(d), log=log, keys=_sc_keys)
    _fresh_built = {}
    # [v192 K1c] THE NEGATIVE CACHE. Most of `missing` is terms this builder cannot produce on this frame — the
    # extraction does not carry their inputs. Asking for them again costs a full frame walk per chunk and returns
    # nothing. Once recorded against the same key, they are skipped until the frame, the builder or the engine
    # changes — at which point they are asked again, because the answer may have changed.
    _lib0, _man0, _junk0, _ = laz_sidecar__classify(_all, set(d.columns))   # [v192 K3] manufactured names and parse artefacts are not library work — never ask for them
    if _man0 or _junk0:
        log(f'  [sidecar] {sport}: {len(_man0)} manufactured names and {len(_junk0)} parse artefacts removed from the library request (they are not library work)')
    _all = _lib0
    _neg = laz_sidecar__load_negative(sport, len(d))
    if _neg:
        _skip = [t for t in _all if t in _neg]
        _all = [t for t in _all if t not in _neg]
        if _skip and log is not None:
            log(f'  [sidecar] {sport}: {len(_skip)} terms this frame cannot produce are SKIPPED (recorded last run; a new frame or builder asks again)')
    try:   # [v187 D5] the two SMALL calls once, for every term: the truncation test never touches the full frame
        with _wn.catch_warnings():
            _wn.simplefilter('ignore', pd.errors.PerformanceWarning)   # the legacy builder inserts columns one at a time; advisory only
            _door = set(_all) | set(_cached)   # [v192 K1b] cached terms take the truncation door too: the sample must build them
            f_sub = aug(sub.copy(deep=False), sport, needed=_door, verbose=False)
            f_trunc = aug(trunc.copy(deep=False), sport, needed=_door, verbose=False)
    except Exception as e:
        return ([], [], f'legacy library failed on the sample: {type(e).__name__}: {str(e)[:90]}')
    _t0 = time.time()
    if _cached:
        # cached terms take the SAME door: truncated twin from the sample, compared before they enter the pool
        try:
            for _t, _v in _cached.items():
                if _t not in f_sub.columns:
                    continue
                _a = pd.to_numeric(f_sub[_t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)[_pos]
                _b = pd.to_numeric(f_trunc[_t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)
                if len(_a) != len(_b) or not np.allclose(np.nan_to_num(_a, nan=-1e300), np.nan_to_num(_b, nan=-1e300), rtol=1e-06, atol=1e-09):
                    refused.append(_t); continue
                if np.isfinite(_v).sum() >= 100:
                    pool[_t] = _v; built.append(_t)
        except Exception as _e:
            log(f'  [sidecar] cached terms could not be door-tested ({type(_e).__name__}) — rebuilding them')
            _all = list(_cached) + _all; _cached = {}
    _par = laz_startup___augment_parallel(d, sport, _all, workers, log=log) if (workers or 0) > 1 else None
    if _par is not None:
        # [v188 P1b] SELF-CHECK, every run: the workers' values for the sample rows must equal the ONE-CORE build of
        # those same rows (f_sub, already computed above for the truncation test). A mismatch means a term is not
        # per-match after all: the whole parallel result is discarded and the serial path below rebuilds it.
        _bad = []
        try:
            _sub_pos = np.flatnonzero(_in)
            for _t, _v in _par.items():
                if _t not in f_sub.columns:
                    continue
                _a = pd.to_numeric(f_sub[_t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)
                _b = _v[_sub_pos].astype(np.float64)
                if len(_a) != len(_b) or not np.allclose(np.nan_to_num(_a, nan=-1e300), np.nan_to_num(_b, nan=-1e300), rtol=1e-06, atol=1e-09):
                    _bad.append(_t)
            log(f'  [startup]   library self-check on {int(_in.sum()):,} sample rows: {len(_par) - len(_bad)} of {len(_par)} terms match the one-core build' + (f' · MISMATCH {_bad[:6]}' if _bad else ' · OK'))
        except Exception as _e:
            _bad = ['<self-check failed>']
            log(f'  [startup]   library self-check could not run: {type(_e).__name__}: {str(_e)[:70]}')
        if _bad:
            laz_workers__map.no_silent_serial('library self-check', f'the workers\' values differ from the one-core build on the sample rows for {_bad[:8]} — the whole library would be rebuilt on one core (~4 min per 100k rows)', log)   # [v246-STOP]
            log('  [startup]   parallel library DISCARDED by the self-check — rebuilding on one core')
            _par = None
    if _par is not None:
        log(f'  [startup]   legacy library built on {int(workers)} workers in {time.time() - _t0:.0f}s ({len(_par)} of {len(_all)} terms produced)')
        for t, v in _par.items():
            if np.isfinite(v).sum() < 100:
                continue
            try:
                a = pd.to_numeric(f_sub[t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)[_pos]
                b = pd.to_numeric(f_trunc[t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)
                same = len(a) == len(b) and np.allclose(np.nan_to_num(a, nan=-1e300), np.nan_to_num(b, nan=-1e300), rtol=1e-06, atol=1e-09)
            except Exception:
                same = False
            if not same:
                refused.append(t)
                continue
            pool[t] = v
            built.append(t); _fresh_built[t] = v
        laz_sidecar__save(sport, _fresh_built, len(d), log=log, _keys=_sc_keys)
        _abs = [t for t in _all if t not in _par]
        if len(_par) or not _all:   # [v192 K6] never record absence from a build that failed outright — a transient failure must not blacklist a term
            laz_sidecar__save_negative(sport, _abs, len(d), log=log)
        laz_sidecar__gap_report(sport, _abs, d.columns, log=log)
        return (built, refused, f'parallel x{int(workers)}')
    if (workers or 0) > 1:
        log('  [startup]   legacy library on ONE core (the parallel path was not used) — expect ~4 min per 100k rows')
    if not _all and not _cached:
        return ([], [], 'nothing to build')
    for i in range(0, len(_all), chunk):
        want = _all[i:i + chunk]
        try:
            with _wn.catch_warnings():
                _wn.simplefilter('ignore', pd.errors.PerformanceWarning)
                _cols = laz_startup___lib_cols(d, want)   # [v192 K8] narrow the frame to what this chunk can read
                full = aug(d[_cols].copy(deep=False), sport, needed=set(want), verbose=False)
        except Exception as e:
            errs += 1
            log(f'  [startup]   legacy library chunk failed: {type(e).__name__}: {str(e)[:90]}')
            continue
        for t in want:
            if t not in full.columns:
                continue
            v = pd.to_numeric(full[t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)
            if np.isfinite(v).sum() < 100:
                continue
            try:
                a = pd.to_numeric(f_sub[t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)[_pos]   # [v187 F16b] positional, not by index
                b = pd.to_numeric(f_trunc[t], errors='coerce').to_numpy(dtype=np.float64, na_value=np.nan)
                if len(a) != len(b):
                    same = False
                    refused.append(t)
                    continue
                same = np.allclose(np.nan_to_num(a, nan=-1e300), np.nan_to_num(b, nan=-1e300), rtol=1e-06, atol=1e-09)
            except Exception:
                same = False
            if not same:
                refused.append(t)
                continue
            pool[t] = v.astype(np.float32)
            built.append(t); _fresh_built[t] = v.astype(np.float32)
        del full
    laz_sidecar__save(sport, _fresh_built, len(d), log=log, _keys=_sc_keys)
    if not errs:
        _abs = [t for t in _all if t not in _fresh_built and t not in refused]
        laz_sidecar__save_negative(sport, _abs, len(d), log=log)
        laz_sidecar__gap_report(sport, _abs, d.columns, log=log)
    note = f'{errs} chunk error(s)' if errs else ''
    return (built, refused, note)

laz_startup___PREPARE_MEMO = {}
def laz_startup__prepare(sport, books=None, stride=1, log=print, workers=None, light=False):
    stride = 1   # [v240 Rule 2] stride is 1, always — the engine evaluates every tick production will see, in the order production sees them; any requested stride is discarded at load
    # [v220 speed S1b] facade is a pure passthrough; the memo lives INSIDE __impl, keyed on the
    # CONTENT of the loaded frame (see the S1b block there). LAZ_PREPARE_CACHE=0 disables.
    return laz_startup__prepare__impl(sport, books=books, stride=stride, log=log, workers=workers, light=light)

def laz_startup___stamp(stage, sport, extra=''):
    # [AmunEv v1 SPEED] always-on stage timer -> laz_stage_timings.log in cwd, with rss. Fires even when
    # the caller passed log=lambda x: None (BaseFinder and the runner do). A silent gap names itself.
    try:
        import time as _t, datetime as _dt
        _rss = (_m('laz_log').rss_mb() if _m('laz_log') is not None else -1)
        with open(os.path.join(os.getcwd(), 'laz_stage_timings.log'), 'a') as _f:
            _f.write(f'{_dt.datetime.now().strftime("%H:%M:%S")}  {sport:12} {stage:32} rss {_rss:>6.0f} MB  {extra}\n')
    except Exception:
        pass


def laz_startup__prepare__impl(sport, books=None, stride=1, log=print, workers=None, light=False):
    # [AmunEV V2.7 — THE 54-MINUTE BASKETBALL BUILD, FOUND] prepare() has three parallel-or-serial forks — the legacy library
    # (`if (workers or 0) > 1`), the genome (`int(workers or 1)`), the sweep index (`bool(_mm and (workers or 0) > 1)`) —
    # and NONE resolved workers=None to the owner's count: None stayed None, and every caller that omitted the argument
    # (the runner's pre-build, the release step, the reclaim) built the WHOLE pool on ONE core with the log silenced.
    # 20 Sep basketball: 54 min serial, then Mode 3 rebuilt it in parallel with warm caches in 5. Since the memo fix Mode 3
    # REUSES the pre-build, so the one-core build was the only build. Resolved here, at the one door every search passes
    # through: None -> LAZ_OWNER['search']['workers'] (clipped to the machine's cores), and the count is logged.
    if not workers:
        try:
            workers = int(laz_workers__count(None, 10 ** 6))
        except Exception:
            workers = 1
    workers = max(1, int(workers))
    log(f'  [startup] prepare {sport}: workers={workers} (' + ('from LAZ_OWNER[search][workers]' if workers > 1 else 'ONE CORE — set LAZ_OWNER[search][workers] or pass --workers') + ')')
    laz_startup___stamp('prepare START', sport, f'books={"yes" if books else "no"} light={light} workers={workers}')   # [AmunEv v1 SPEED]
    # [v247 D1] THE OWNER'S RULE, ENFORCED AT THE ONE DOOR EVERY SEARCH PASSES THROUGH.
    # Stride is 1. Not "1 by default" — 1, and anything else is refused here with the caller
    # named, so a stride can never reach the frame again from any mode, any runner, any flag.
    if int(stride or 1) != 1:
        import inspect as _insp
        _caller = _insp.stack()[1].function if len(_insp.stack()) > 1 else '?'
        raise ValueError(f'[D1] stride={stride} refused by prepare() — the engine runs at stride 1 only (caller: {_caller}). '
                         f'The stride parameter is retained in signatures for API compatibility and accepts the value 1 alone.')
    laz_startup___REFUSED_ONCE.clear()
    'Build EVERYTHING for one sport. Returns (d, pool, ctx, manifest).'
    FRM = _m('laz_frames')
