def laz_startup__prepare_all(sports, books=None, stride=1, log=print):
    out = {}
    for sp in sports:
        try:
            out[sp] = laz_startup__prepare(sp, books=books, stride=stride, log=log)
        except Exception as e:
            log(f'  [startup] {sp}: FAILED {type(e).__name__} {str(e)[:60]}')
    return out
