def laz_genome__load_embedded():
    """THE GENOME TRAVELS INSIDE THE ENGINE.

    bootstrap() read genome_handwritten.py and genome_trusted.json from disk.
    Neither ships in the single file, so on any machine but the build one the
    registry stayed empty and rebuild_all had nothing to build — silently,
    because a missing file returns 0 rather than raising. Same failure as the
    strategy stores, same fix: carry the data as JSON parsed at load.
    """
    n = 0
    try:
        for t, v in json.loads(laz_genome__HANDWRITTEN_TXT).items():
            arith, inp, sp = (list(v) + ['', 'all'])[:3]
            laz_genome__register(t, arith, inp, sports=sp, provenance='hand-written from first principles')
            n += 1
    except Exception as e:
        LG = _m('laz_log')
        if LG is not None:
            LG.line(f'genome handwritten payload: {type(e).__name__}: {e}', stg='genome')
    try:
        for r in json.loads(laz_genome__TRUSTED_TXT):
            if r['term'] in laz_genome__GENOME:
                continue
            laz_genome__register(r['term'], r['arithmetic'], ','.join(r.get('refs') or []), provenance=f'{r.get('recovered_from')} @ {r.get('provenance')}')
            n += 1
    except Exception as e:
        LG = _m('laz_log')
        if LG is not None:
            LG.line(f'genome trusted payload: {type(e).__name__}: {e}', stg='genome')
    return n

def laz_genome__load_universal():
    """The universal family, from laz_featdoc.UNIVERSAL_ARITHMETIC.

    These carry more strategies than any other group and were documented in
    laz_featdoc but never registered here — so `u_pace` came back "assumed
    universal", a hole exactly where the most-used terms live. Two stores of
    truth is one too many.
    """
    FD = _m('laz_featdoc')
    n = 0
    for t, a in (getattr(FD, 'UNIVERSAL_ARITHMETIC', {}) or {}).items():
        if t in laz_genome__GENOME and laz_genome__GENOME[t].get('provenance', '').startswith('hand-written'):
            continue
        laz_genome__register(t, a, 'h_score,a_score,home_odds,away_odds,elapsed,match_id', provenance='universal family, laz_featdoc')
        n += 1
    return n

def laz_genome__load_recovered(path=__import__('os').path.join(laz_genome___laz_home(), 'genome_trusted.json')):
    """The 90 recovered from code AND validated against inputs that exist."""
    if not os.path.exists(path):
        return 0
    n = 0
    for r in _laz_json_read(path):
        if r['term'] in laz_genome__GENOME:
            continue
        laz_genome__register(r['term'], r['arithmetic'], ','.join(r.get('refs') or []), provenance=f'{r.get('recovered_from')} @ {r.get('provenance')}')
        n += 1
    return n

def laz_genome__load_columns():
    """Raw frame columns need no arithmetic — they ARE the primitive."""
    import pyarrow.parquet as pq
    OW = _m('laz_owner')
    n = 0
    d = (OW.LAZ_OWNER['paths'].get('parquet_dir') if OW else None) or __import__('os').path.join(laz_genome___laz_home(), 'frames')
    if not os.path.isdir(d):
        return 0
    for f in sorted(os.listdir(d)):
        if not f.endswith('.parquet'):
            continue
        sp = f.replace('AB_', '').replace('.parquet', '')
        try:
            names = pq.ParquetFile(os.path.join(d, f)).schema_arrow.names
        except Exception:
            continue
        for c in names:
            if c in laz_genome__GENOME:
                continue
            _cz = 'live'
            try:
                _CGr = _m('causality_guard')
                if _CGr is not None:
                    _okr, _whyr = _CGr.check_term(c, sp, 1.01)
                    if not _okr and ('L1' in _whyr or 'forbidden' in _whyr.lower()):
                        _cz = 'SETTLEMENT — denied by the causality guard'
            except Exception as _re:
                pass
            laz_genome__register(c, f'read directly from the frame column `{c}`', c, kind='column', provenance=f'present in AB_{sp}.parquet', causality=_cz)
            n += 1
    return n

def laz_genome__bootstrap(log=None):
    """Populate the genome. Idempotent."""
    e = laz_genome__load_embedded()
    a = laz_genome__load_handwritten()
    u = laz_genome__load_universal()
    b = laz_genome__load_recovered()
    c = laz_genome__load_columns()
    a += e
    _BRAIN = {'elo_edge': 'player_betsson_elo - opponnent_betsson_elo', 'elo_ratio': 'player_betsson_elo / opponnent_betsson_elo', 'cur_elo_edge': 'cur50games_homeplayer_elo - opponnent_betsson_elo', 'elo_velocity': 'cur50games_homeplayer_elo - player_betsson_elo', 'form_x_class': 'cur50games_homeplayer_elo * player_betsson_elo / 1e6', 'streak_quality': 'winrate_l5g * total_player_wr', 'form_accel': '(winrate_l5g - winrate_l10g) - (winrate_l10g - winrate_l20g)', 'form_gradient': 'winrate_l5g - winrate_l20g', 'scoring_accel': 'avggoals_scored_5 - avggoals_scored_20', 'dominance': 'net_goals_20 * total_player_wr', 'h2h_net10': 'h2h_avggoals_scored_l10g - h2h_avggoals_conceded_l10g', 'h2h_vs_general': 'h2h_winrate_l10g - total_player_wr', 'h2h_confidence': 'h2h_winrate_l10g * h2h_l10g', 'h2h_trend': 'h2h_winrate_l5g - h2h_winrate_l10g', 'load24': 'count_games_last_24_hours', 'load_x_skill': 'count_games_last_24_hours * total_player_wr', 'grind_form': 'count_games_last_24_hours * wr_vs_base5', 'gift': 'wr_vs_base20 * backed odds', 'elo_vs_price': 'elo_edge/100 - implied', 'wr_vs_base5': 'winrate_l5g - total_player_wr', 'wr_vs_base10': 'winrate_l10g - total_player_wr', 'wr_vs_base20': 'winrate_l20g - total_player_wr', 'net_goals_5': 'avggoals_scored_5 - avggoals_conceded_5', 'net_goals_10': 'avggoals_scored_10 - avggoals_conceded_10', 'net_goals_20': 'avggoals_scored_20 - avggoals_conceded_20', 'goal_ratio_5': 'avggoals_scored_5 / avggoals_conceded_5', 'goal_ratio_10': 'avggoals_scored_10 / avggoals_conceded_10', 'goal_ratio_20': 'avggoals_scored_20 / avggoals_conceded_20'}
    _BRAIN.update({'model_p': 'gradient-boosted P(backed side wins) from the 36 player-form inputs — laz_model_<sport>.joblib', 'model_edge': 'model_p - implied (1/odds)', 'ev_career': 'total_player_wr * odds', 'ev_l20': 'winrate_l20g * odds', 'ev_l5': 'winrate_l5g * odds', 'ev_h2h': 'h2h_winrate_l10g * odds', 'misprice_career': 'total_player_wr - implied', 'misprice_l20': 'winrate_l20g - implied', 'misprice_l5': 'winrate_l5g - implied', 'misprice_h2h': 'h2h_winrate_l10g - implied'})
    for _t, _ar in _BRAIN.items():
        for _sfx, _lab in (('', 'the backed player'), ('_hp', 'the home player'), ('_ap', 'the away player')):
            _nm = _t + _sfx
            if _nm not in laz_genome__GENOME:
                laz_genome__register(_nm, _ar + f'  [{_lab}; from the h2h columns joined at ensure]', _ar, sports=('efootball', 'ebasketball'), kind='player-form feature', provenance='ported from v76_89 laz_brain_features', resolves_at=0.0, causality='live (pre-match history)')
    for _tag, _cp in (('q1h', 0.125), ('q1e', 0.25), ('q2h', 0.375), ('q2e', 0.5), ('h1h', 0.25), ('h1e', 0.5), ('h2h', 0.75)):
        for _pre, _ar in (('lead_', 'sign(h_score - a_score) at elapsed >= %s, held after' % _cp), ('lead_margin_', '|h_score - a_score| at elapsed >= %s, held after' % _cp), ('fav_lead_', '+1 opening favourite leads / -1 underdog leads at elapsed >= %s' % _cp)):
            _nm = _pre + _tag
            if _nm not in laz_genome__GENOME:
                laz_genome__register(_nm, _ar, 'h_score, a_score, elapsed, opening odds', sports=('football', 'efootball', 'esports') if _tag.startswith('h') else ('basketball', 'ebasketball'), kind='checkpoint feature', provenance='operator adaptation of the first-goal family to quarter/half sports', resolves_at=float(_cp), causality='live from the checkpoint')
    for _tag, _cp, _lab in (('1he', 0.5, 'end of the first half (phase change)'), ('m15', 0.167, "15'"), ('m30', 0.333, "30'"), ('m60', 0.667, "60'"), ('m75', 0.833, "75'")):
        for _pre, _ar in (('lead_', 'sign(h_score - a_score) at %s, held after' % _lab), ('lead_margin_', '|h_score - a_score| at %s, held after' % _lab), ('fav_lead_', '+1 opening favourite leads / -1 underdog leads at %s' % _lab)):
            _nm = _pre + _tag
            if _nm not in laz_genome__GENOME:
                laz_genome__register(_nm, _ar, 'h_score, a_score, phase / elapsed, opening odds', sports=('football', 'efootball', 'esports'), kind='checkpoint feature', provenance='the quarter-sport family brought back to football', resolves_at=float(_cp), causality='live from the checkpoint')
    _TSE = {'goal sports': ['secs_since_goal', 'secs_since_fav_scored', 'secs_since_dog_scored', 'secs_since_lead_1_up', 'secs_since_lead_2_up', 'secs_since_lead_3_up', 'goal_rate_last_120s', 'goal_rate_last_300s'], 'quarter sports': ['secs_since_lead_5_up', 'secs_since_lead_10_up', 'secs_since_lead_15_up', 'run_points', 'run_secs', 'pts_last_60s', 'pts_last_120s', 'backed_pts_last_60s', 'opp_pts_last_60s', 'lead_delta_last_60s', 'lead_delta_last_120s', 'secs_since_lead_peak', 'lead_from_peak', 'secs_since_any_score', 'secs_since_quarter_start'], 'set sports': ['secs_since_game_backed', 'secs_since_game_opp', 'secs_since_set_won', 'secs_in_set', 'games_last_300s', 'games_last_600s', 'games_run_backed', 'games_run_opp', 'set_lead_backed'], 'objective sports': ['secs_since_map_won', 'secs_in_map', 'rounds_last_120s', 'round_lead_delta_120s'], 'all': ['secs_since_start', 'mins_since_start', 'secs_since_line_moved', 'secs_since_price_moved', 'secs_since_backed_scored', 'secs_since_opp_scored', 'secs_since_lead_overturned', 'secs_since_tie', 'secs_since_run_started', 'secs_lead_held', 'lead_change_last_300s']}
    _TSE_DESC = {'goal sports': 'goal sport event, wall seconds since it last happened', 'quarter sports': 'points sport event (run / drought / lead erosion / pace), wall seconds or points', 'set sports': 'set sport event (game / set / streak / pace), wall seconds or games', 'objective sports': 'esports event (map / round), wall seconds or rounds', 'all': 'universal event, wall seconds since it last happened'}
    for _sc, _names in _TSE.items():
        for _t in _names:
            if _t in laz_genome__BUILDERS and _t not in laz_genome__GENOME:
                laz_genome__register(_t, f'{_TSE_DESC[_sc]} (laz_genome BUILDERS[{_t!r}]; history only — the event is in the past, the clock is the row timestamp)', 'h_score, a_score, ts, the market columns, and the base side', sports=_sc, kind='time_since_event', causality='live (seconds since a PAST event; never a row count)', provenance='fix pass 4 — operator rule: no tick element, adapted per sport family')
    _nb = 0
    for _t in list(laz_genome__BUILDERS):
        if _t.startswith('_') and _t.endswith('_REMOVED'):
            laz_genome__BUILDERS.pop(_t, None)
            continue
        if _t not in laz_genome__GENOME:
            laz_genome__register(_t, f'executable builder (see BUILDERS[{_t!r}])', 'see builder', provenance='builder registered at bootstrap — arithmetic in code')
            _nb += 1
    if log:
        log(f'[genome] {len(laz_genome__GENOME)} elements · {a} hand-written · {u} universal · {b} recovered+validated · {c} raw columns · {_nb} builders registered')
    return len(laz_genome__GENOME)

def laz_genome__describe(term):
    """Everything known about one element."""
    g = laz_genome__GENOME.get(laz_genome__canon(term)) or laz_genome__GENOME.get(term)
    if g is None:
        SP = _m('laz_specs')
        t = str(term)
        if SP is not None and hasattr(SP, 'load_conditions'):
            try:
                C = SP.load_conditions()
                base = t[4:] if t.startswith('eng_') else t
                if base in C:
                    return dict(element=t, kind='engine spec condition', arithmetic=str(C[base]), source_columns=','.join(sorted(set(re.findall("f\\['(\\w+)'\\]", str(C[base]))))), sports='where the source columns exist', provenance='laz_specs engine_conditions.json', resolves_at=0.0, causality='live (the condition is a live-column test)')
            except Exception:
                pass
        PR = _m('laz_promote')
        CR = _m('laz_corr')
        trip = None
        prov = ''
        if PR is not None:
            rec = PR.load().get(t)
            if rec:
                trip = (rec['parent_a'], rec['parent_b'], rec.get('operator', ''))
                prov = 'promotion store (recorded at creation)'
        if trip is None and CR is not None:
            sl = (getattr(CR, 'SHORT_TO_LONG', {}) or {}).get(t)
            if sl:
                trip = (sl[0], sl[1], {'__minus__': 'difference', '__over__': 'ratio', '__x__': 'product'}.get(sl[2], sl[2]))
                prov = 'manufactured this process'
            elif hasattr(CR, 'parse_long') and t.startswith('X_'):
                pl = CR.parse_long(t)
                if pl:
                    trip = (pl[0], pl[1], {'__minus__': 'difference', '__over__': 'ratio', '__x__': 'product'}.get(pl[2], pl[2]))
                    prov = 'decomposed from the long-form name'
        if trip:
            a, b, op = trip
            da = laz_genome__describe(a)
            db = laz_genome__describe(b)
            form = {'difference': f'{a} - {b}', 'ratio': f'np.where(np.abs({b})>1e-9, {a}/{b}, np.nan)', 'product': f'{a} * {b}'}.get(op, f'{a} {op} {b}')
            ra = da.get('resolves_at', 0.0) or 0.0
            rb = db.get('resolves_at', 0.0) or 0.0
            res = max(float(ra) if isinstance(ra, (int, float)) else 0.0, float(rb) if isinstance(rb, (int, float)) else 0.0)
            prim = sorted(set(str(da.get('source_columns', '')).split(',')) | set(str(db.get('source_columns', '')).split(',')) - {''})
            return dict(element=t, kind=f'manufactured ({op}, order {(2 if t.startswith(('ix2', 'X_X')) else 1)})', arithmetic=form, source_columns=','.join(prim), parent_a=a, parent_b=b, operator=op, parent_a_arithmetic=str(da.get('arithmetic', ''))[:120], parent_b_arithmetic=str(db.get('arithmetic', ''))[:120], resolves_at=res, causality=f'inherits the LATER parent — not knowable before {res} elapsed' if res else 'live at every tick', provenance=prov, rebuild_steps=f'1. build {a} = {str(da.get('arithmetic', ''))[:60]} | 2. build {b} = {str(db.get('arithmetic', ''))[:60]} | 3. {form}')
        return dict(element=term, kind='UNKNOWN', arithmetic='not in the genome — no source found in any transcript, version or frame')
    FD = _m('laz_featdoc')
    out = dict(g)
    if FD is not None and hasattr(FD, 'rebuild_recipe'):
        LG = _m('laz_log')
        r = LG.guard('rebuild_recipe', FD.rebuild_recipe, term) if LG else None
        if r:
            out['rebuild_steps'] = ' | '.join(r.get('steps') or [])
    return out

def laz_genome__report(sport, pool=None, log=None):
    """Per sport: what the stacks demand, what is buildable, and why not."""
    RC = _m('laz_recovered')
    demanded = {}
    if RC is not None:
        for n, v in (RC.load() or {}).items():
            for c in v.get('conditions') or []:
                t = re.split('\\s*(?:>=|<=|>|<|==|!=)\\s*', str(c))[0].strip()
                if t:
                    demanded[t] = demanded.get(t, 0) + 1
    rows = []
    for t, n in sorted(demanded.items(), key=lambda z: -z[1]):
        ct = laz_genome__canon(t)
        g = laz_genome__GENOME.get(ct)
        ok, why = laz_genome__applies(t, sport)
        in_pool = bool(pool is not None and (t in pool or ct in pool))
        rows.append(dict(term=t, canonical=ct, demanded=n, in_pool=in_pool, applies=ok, reason=why, kind=(g or {}).get('kind', 'UNKNOWN'), arithmetic=(g or {}).get('arithmetic', '')[:120], status='built' if in_pool else 'not applicable' if not ok else 'unbuildable' if (g or {}).get('kind') == 'unbuildable' else 'documented but not built'))
    R = pd.DataFrame(rows)
    if log and len(R):
        c = R.status.value_counts().to_dict()
        log(f'[genome] {sport}: {len(R)} terms demanded · {c}')
        for s in ('unbuildable', 'not applicable'):
            ex = R[R.status == s].head(4)
            for _, x in ex.iterrows():
                log(f'[genome]   {s}: {x.term} — {(x.reason if s == 'not applicable' else x.arithmetic[:70])}')
    return R

def laz_genome__to_frame():
    """The whole genome as a documentation table."""
    return pd.DataFrame([laz_genome__describe(t) for t in sorted(laz_genome__GENOME)])

def laz_genome___sport_seconds(C):
    """Nominal match length in SECONDS from the one clock: laz_everything.nominal (per-row
    where leagues differ, the frame's measured length, the rulebook last). None/NaN on a
    clockless sport. D13: this held its own dict that contradicted the measured table."""
    EV = _m('laz_everything')
    sp = str(C.get('sport', '') or getattr(C['d'], 'attrs', {}).get('sport', '')).lower()
    try:
        nr = EV.clock_per_row(C['d'], sp) if EV is not None else None
        if nr is not None and np.isfinite(np.asarray(nr, float)).any():
            return np.asarray(nr, float) * 60.0
        nm = EV.nominal(sp, C['d']) if EV is not None else None
        return float(nm) * 60.0 if nm else np.nan
    except Exception as _e:
        return np.nan

def laz_genome___wall_secs(C):
    """Wall seconds since the match's FIRST quote — causal, and independent of how
    often the scraper polled. Operator rule: nothing built from the NUMBER OF ROWS in
    a match may be a condition, because that number is the scrape interval, not the match."""
    if '_secs' in C:
        return C['_secs']
    d = C['d']
    M = C['M']
    if 'ts' in d.columns:
        t = pd.to_datetime(d['ts'], errors='coerce')
        t0 = t.groupby(pd.Series(M)).transform('min')
        s = (t - t0).dt.total_seconds().values.astype(float)
    else:
        s = np.full(len(M), np.nan)
    C['_secs'] = s
    return s

def laz_genome___secs_since_change(v, M, secs):
    """Wall seconds since v last changed within the match (0 on the tick it changes)."""
    sv = pd.Series(v)
    chg = (sv != sv.groupby(M).shift(1)).astype(int)
    grp = chg.groupby(M).cumsum()
    start = pd.Series(secs).groupby([pd.Series(M), grp]).transform('first').values
    return np.asarray(secs, float) - start

def laz_genome___secs_in_state(state, M, secs):
    """Wall seconds accumulated while `state` was True, up to this tick (causal)."""
    st = np.asarray(state, bool)
    s = np.asarray(secs, float)
    dt = pd.Series(s).groupby(M).diff().fillna(0.0).values
    return pd.Series(np.where(st, dt, 0.0)).groupby(M).cumsum().values

def laz_genome___trail_agg(v, M, secs, window_s, agg='std'):
    """Trailing-WINDOW aggregate measured in SECONDS, not rows. For every tick, the
    aggregate over same-match ticks with secs in (secs_i - window_s, secs_i]. A
    rolling(N) over rows was N scrape intervals — 100 s at 5 s polling, 25 s at 2.5 s —
    for the same feature name. Operator rule: nothing depends on the polling rate."""
    v = np.asarray(v, float)
    s = np.asarray(secs, float)
    M = np.asarray(M)
    n = len(v)
    out = np.full(n, np.nan)
    if n == 0:
        return out
    order = np.lexsort((s, M))
    vs = v[order]
    ss = s[order]
    ms = M[order]
    bounds = np.flatnonzero(np.r_[True, ms[1:] != ms[:-1], True])
    res = np.full(n, np.nan)
    for a, b in zip(bounds[:-1], bounds[1:]):
        sv = vs[a:b]
        st = ss[a:b]
        lo = np.searchsorted(st, st - window_s, side='right')
        for i in range(len(sv)):
            w = sv[lo[i]:i + 1]
            w = w[np.isfinite(w)]
            if len(w) == 0:
                continue
            if agg == 'std':
                res[a + i] = np.std(w) if len(w) >= 3 else np.nan
            elif agg == 'median':
                res[a + i] = np.median(w)
            elif agg == 'mean':
                res[a + i] = np.mean(w)
            elif agg == 'min':
                res[a + i] = np.min(w)
            elif agg == 'max':
                res[a + i] = np.max(w)
            elif agg == 'first':
                res[a + i] = w[0]
    out[order] = res
    return out

def laz_genome___value_secs_ago(v, M, secs, lag_s):
    """The value at the latest same-match tick at least lag_s seconds BEFORE this one;
    NaN if the match has not yet run that long. Replaces shift(N) — N rows ago is N
    scrape intervals ago, which is not a duration."""
    v = np.asarray(v, float)
    s = np.asarray(secs, float)
    M = np.asarray(M)
    n = len(v)
    out = np.full(n, np.nan)
    if n == 0:
        return out
    order = np.lexsort((s, M))
    vs = v[order]
    ss = s[order]
    ms = M[order]
    bounds = np.flatnonzero(np.r_[True, ms[1:] != ms[:-1], True])
    res = np.full(n, np.nan)
    for a, b in zip(bounds[:-1], bounds[1:]):
        st = ss[a:b]
        j = np.searchsorted(st, st - lag_s, side='right') - 1
        ok = j >= 0
        res[a:b][ok] = vs[a:b][j[ok]]
    out[order] = res
    return out

def laz_genome___secs_since_event(mask, M, secs):
    """Wall seconds since the LAST same-match tick on which `mask` was True; NaN if it
    has not happened in this match. History only: the event is in the past."""
    m = np.asarray(mask, bool)
    s = np.asarray(secs, float)
    t_ev = pd.Series(np.where(m, s, np.nan)).groupby(pd.Series(M)).ffill().values
    return s - t_ev

def laz_genome___first_reach(v, thr, M):
    """True on the FIRST same-match tick where v >= thr within the current excursion
    (v resets the excursion when it falls below thr). Marks 'the lead reached N'."""
    v = np.asarray(v, float)
    above = v >= thr
    prev = pd.Series(above.astype(int)).groupby(pd.Series(M)).shift(1).fillna(0).values.astype(bool)
    return above & ~prev

def laz_genome___cum_changes(v, M):
    """Cumulative count of changes of v within the match (0 on the first tick)."""
    return pd.Series(laz_genome___chg_mask(v, M).astype(float)).groupby(pd.Series(M)).cumsum().values

def laz_genome___chg_mask(v, M):
    """True on the tick where v differs from the previous same-match tick."""
    sv = pd.Series(np.asarray(v, float))
    return (sv != sv.groupby(pd.Series(M)).shift(1)).values & sv.notna().values & sv.groupby(pd.Series(M)).shift(1).notna().values

def laz_genome___side_scored(C, who):
    """True on the tick a given side's score increased. who: fav/dog (by current price),
    backed/opp (by the base's side)."""
    M = C['M']
    hs = np.asarray(C['d']['h_score'], float) if 'h_score' in C['d'].columns else None
    as_ = np.asarray(C['d']['a_score'], float) if 'a_score' in C['d'].columns else None
    if hs is None or as_ is None:
        return np.zeros(len(M), bool)
    hup = (pd.Series(hs).diff().values > 0) & (pd.Series(M).shift(1).values == M)
    aup = (pd.Series(as_).diff().values > 0) & (pd.Series(M).shift(1).values == M)
    if who == 'fav':
        fav_home = np.asarray(C['ho'], float) <= np.asarray(C['ao'], float)
        return np.where(fav_home, hup, aup)
    if who == 'dog':
        fav_home = np.asarray(C['ho'], float) <= np.asarray(C['ao'], float)
        return np.where(fav_home, aup, hup)
    sd = np.asarray(C.get('side', []), dtype=object) if C.get('side') is not None else None
    if sd is None or len(sd) != len(M):
        return np.zeros(len(M), bool)
    bh = sd == 'home'
    return np.where(bh, hup, aup) if who == 'backed' else np.where(bh, aup, hup)

def laz_genome___lead_overturned(sd, M):
    """True on the tick the lead CHANGED HANDS (sign flipped through or across zero)."""
    v = np.sign(np.asarray(sd, float))
    nz = pd.Series(np.where(v != 0, v, np.nan)).groupby(pd.Series(M))
    last_nz = nz.shift(1).groupby(pd.Series(M)).ffill().values
    return (v != 0) & np.isfinite(last_nz) & (last_nz != v)

def laz_genome___run_started(sd, M):
    """True on the tick the lead started moving in its CURRENT direction (a new run)."""
    d = pd.Series(np.asarray(sd, float)).groupby(pd.Series(M)).diff().values
    ds = np.sign(np.nan_to_num(d, nan=0.0))
    pds = pd.Series(ds).groupby(pd.Series(M)).shift(1).values
    return (ds != 0) & (ds != np.nan_to_num(pds, nan=0.0))

def laz_genome___col(C, name):
    """A frame column as float, NaN-filled if absent."""
    d = C['d']
    return pd.to_numeric(d[name], errors='coerce').values if name in d.columns else np.full(len(C['M']), np.nan)

def laz_genome___backed_score(C):
    sd_ = C.get('side')
    hs = laz_genome___col(C, 'h_score')
    as_ = laz_genome___col(C, 'a_score')
    if sd_ is None:
        return hs
    return np.where(np.asarray(sd_).astype(str) == 'away', as_, hs)

def laz_genome___opp_score(C):
    sd_ = C.get('side')
    hs = laz_genome___col(C, 'h_score')
    as_ = laz_genome___col(C, 'a_score')
    if sd_ is None:
        return as_
    return np.where(np.asarray(sd_).astype(str) == 'away', hs, as_)

def laz_genome___backed_sets(C):
    """Sets lead for the backed side where the frame carries per-side sets, else NaN."""
    d = C['d']
    sd_ = C.get('side')
    hs = next((c for c in ('h_sets', 'home_sets', 'sets_h') if c in d.columns), None)
    as_ = next((c for c in ('a_sets', 'away_sets', 'sets_a') if c in d.columns), None)
    if hs is None or as_ is None or sd_ is None:
        return np.full(len(C['M']), np.nan)
    h = laz_genome___col(C, hs)
    a = laz_genome___col(C, as_)
    return np.where(np.asarray(sd_).astype(str) == 'away', a - h, h - a)

def laz_genome___run_points(sd, M):
    """Points (or games) scored in the CURRENT one-sided run: |lead now - lead when the
    run started|. A run starts when the lead moves in a new direction."""
    sd = np.asarray(sd, float)
    start = laz_genome___run_started(sd, M)
    at = pd.Series(np.where(start, sd, np.nan)).groupby(pd.Series(M)).ffill().values
    return np.abs(sd - at)

def laz_genome___phase_change(C):
    """True on the tick the phase label changes (a new quarter / half)."""
    d = C['d']
    if 'phase' not in d.columns:
        return np.zeros(len(C['M']), bool)
    ph = d['phase'].astype(str).str.strip().str.upper().values
    pv = pd.Series(ph).groupby(pd.Series(C['M'])).shift(1).values
    return (ph != pv) & pd.notna(pv) & (ph != '') & (ph != 'NAN')

def laz_genome___since_change(v, M, el):
    """Elapsed fraction since v last changed within the match — the age of the current state."""
    s = pd.Series(v)
    chg = (s != s.groupby(M).shift(1)).astype(int)
    grp = chg.groupby(M).cumsum()
    start = pd.Series(el).groupby([pd.Series(M), grp]).transform('first').values
    return np.asarray(el, float) - start

def laz_genome___run_len(sd, M):
    """Length of the current run: ticks since the lead last changed hands or was level."""
    s = pd.Series(np.sign(sd))
    chg = (s != s.groupby(M).shift(1)).astype(int)
    grp = chg.groupby(M).cumsum()
    return pd.Series(np.ones(len(s))).groupby([pd.Series(M), grp]).cumsum().values

def laz_genome___changes_within(tot, M, el, window_frac):
    """How many times the total changed in the last window (as an elapsed fraction)."""
    t = pd.Series(tot)
    chg = (t != t.groupby(M).shift(1)).astype(float)
    out = np.zeros(len(t))
    e = np.asarray(el, float)
    Ma = np.asarray(M)
    for m, idx in pd.Series(np.arange(len(t))).groupby(Ma).indices.items():
        idx = np.asarray(idx)
        ee = e[idx]
        cc = chg.values[idx]
        cs = np.concatenate([[0], np.cumsum(cc)])
        lo = np.searchsorted(ee, ee - window_frac, side='left')
        out[idx] = cs[np.arange(len(idx)) + 1] - cs[lo]
    return out

def laz_genome___at_checkpoint(v, M, el, cp):
    """The value of v at the FIRST tick of the match where elapsed >= cp, carried
    forward from there; NaN before it. A checkpoint feature can only be read
    after its checkpoint — that is what makes it causal, and the genome records
    resolves_at=cp so the guard holds it until then."""
    v = np.asarray(v, float)
    e = np.asarray(el, float)
    Ma = np.asarray(M)
    out = np.full(len(v), np.nan)
    for m, idx in pd.Series(np.arange(len(v))).groupby(Ma).indices.items():
        idx = np.asarray(idx)
        hit = np.where(e[idx] >= cp)[0]
        if len(hit):
            k = idx[hit[0]]
            out[idx[hit[0]:]] = v[k]
    return out

def laz_genome___fav_of(C):
    """+1 where the leader (sign of sd) is the OPENING favourite, -1 where the
    opening underdog leads, 0 level. Opening = the match's first quotes."""
    ho0 = pd.Series(C['ho']).groupby(C['M']).transform('first').values
    ao0 = pd.Series(C['ao']).groupby(C['M']).transform('first').values
    fav = np.where(ho0 < ao0, 1, np.where(ho0 > ao0, -1, 0))
    lead = np.sign(C['sd'])
    return np.where(lead == 0, 0, np.where(lead == fav, 1, -1)).astype(float)
laz_genome___PHASE_ORDER = ('Q1', 'Q2', 'HT', 'Q3', 'Q4', 'OT', '1H', '2H', '1ST', '2ND', 'FT')

def laz_genome___phase_norm(v):
    """'1STQ,15MINUTES' -> 'Q1'; '2NDQ,33MINUTES' -> 'Q2'; 'HT' -> 'HT'; '1H' / '2H' as they are.
    The phase token is whatever precedes the first comma; ordinals (1ST/2ND/3RD/4TH)
    map to quarter numbers; a trailing minute token is ignored here (see _phase_minute)."""
    x = str(v).upper().strip().split(',')[0].replace(' ', '').replace('QUARTER', 'Q').replace('HALF', 'H')
    import re as _re
    m = _re.match(r'^(\\d)(ST|ND|RD|TH)?Q$|^Q(\\d)$', x)
    if m:
        return 'Q' + (m.group(1) or m.group(3))
    m = _re.match(r'^(\\d)(ST|ND|RD|TH)?H$|^H(\\d)$', x)
    if m:
        return '1H' if (m.group(1) or m.group(3)) == '1' else '2H'
    if x.startswith('HT') or 'HALFT' in x:
        return 'HT'
    if x.startswith('OT') or 'OVERT' in x or x.startswith('ET'):
        return 'OT'
    if x in ('FT', 'FULLTIME', 'END', 'FINISHED'):
        return 'FT'
    return x

def laz_genome___phase_minute(v):
    """The minute token after the comma, if any: '2NDQ,33MINUTES' -> 33.0; NaN otherwise."""
    import re as _re
    m = _re.search(',\\s*(\\d+(?:\\.\\d+)?)\\s*MIN', str(v).upper())
    return float(m.group(1)) if m else np.nan
laz_genome___UNKNOWN_PHASE = {'', 'NAN', 'NONE', 'NULL', 'UNKNOWN'}

def laz_genome___phase_series(M, phase):
    """Normalised phase per tick, with blanks / NAN forward-filled from the last
    known phase WITHIN the match. A blank tick inside Q1 is still Q1 — without
    this, the end-of-quarter reader fired at the blank."""
    ph = pd.Series([laz_genome___phase_norm(x) for x in np.asarray(phase)])
    ph = ph.where(~ph.isin(laz_genome___UNKNOWN_PHASE))
    return ph.groupby(np.asarray(M)).ffill().fillna('').values

def laz_genome___at_phase_end(v, M, phase, done_phases):
    """The value of v at the FIRST tick whose phase is beyond `done_phases`
    (e.g. Q1 ended = first tick that is not Q1). Anchored on the observed phase
    change, so it needs no clock and cannot leak: the transition has happened
    when it is read. NaN before, held after."""
    v = np.asarray(v, float)
    Ma = np.asarray(M)
    ph = laz_genome___phase_series(Ma, phase)
    out = np.full(len(v), np.nan)
    done = set(done_phases)
    for m, idx in pd.Series(np.arange(len(v))).groupby(Ma).indices.items():
        idx = np.asarray(idx)
        p = ph[idx]
        seen_done = np.cumsum(np.isin(p, list(done))) > 0
        hit = np.where(seen_done & ~np.isin(p, list(done)))[0]
        if len(hit):
            k = idx[hit[0] - 1] if hit[0] > 0 else idx[hit[0]]
            out[idx[hit[0]:]] = v[k]
    return out
laz_genome___QI = {'Q1': 0, 'Q2': 1, 'HT': 2, 'Q3': 2, 'Q4': 3, 'OT': 4, '1H': 0, '2H': 1}

def laz_genome__phase_elapsed(d, log=None):
    """A finer elapsed fraction for frames whose frac is a per-quarter step.
    From the phase column's minute token: within each quarter, wall minutes
    since the quarter began over the frame's MEDIAN wall length of that
    quarter (a constant, like the sport's nominal length), clipped 0-1, then
    (quarter_index + progress) / 4. None when there is no minute token or no
    quarter structure. Used ONLY by the midpoint checkpoints."""
    if 'phase' not in d.columns:
        return None
    M = d['match_id'].values
    ph = laz_genome___phase_series(M, d['phase'].values)
    mins = np.array([laz_genome___phase_minute(x) for x in d['phase'].values], float)
    if not np.isfinite(mins).any():
        return None
    q = np.array([laz_genome___QI.get(p, np.nan) for p in ph], float)
    if not np.isfinite(q).any():
        return None
    df = pd.DataFrame(dict(M=M, q=q, mn=mins))
    df['mn'] = df.groupby('M').mn.ffill()
    df['qstart'] = df.groupby(['M', 'q']).mn.transform('min')
    lens = df.dropna(subset=['q', 'mn']).groupby(['M', 'q']).mn.agg(lambda x: x.max() - x.min())
    med_len = lens.groupby(level='q').median().to_dict()
    typical = df.q.map(med_len).replace(0, np.nan)
    prog = ((df.mn - df.qstart) / typical).clip(0, 1).fillna(0).values
    el = np.where(np.isfinite(q), (q + prog) / 4.0, np.nan)
    if log:
        log(f'[phase] played-time proxy from the minute token: median wall minutes per quarter {dict(((int(k), round(float(v), 1)) for k, v in med_len.items() if np.isfinite(k)))} — midpoint checkpoints use this')
    return np.clip(el, 0, 1)

def laz_genome__phase_report(d, el, log=None):
    """Says what the phase column holds and what frac reads at each phase change —
    the check that decides whether frac is the played clock (Q1 -> Q2 at ~0.25)
    or wall time. Informational; printed once per frame."""
    if 'phase' not in d.columns:
        if log:
            log('[phase] no phase column — quarter-end checkpoints use the elapsed fraction only')
        return None
    Ma = d['match_id'].values
    ph = laz_genome___phase_series(Ma, d['phase'].values)
    e = np.asarray(el, float)
    vals = pd.Series(ph).value_counts().to_dict()
    rows = []
    for m, idx in pd.Series(np.arange(len(d))).groupby(Ma).indices.items():
        idx = np.asarray(idx)
        p = ph[idx]
        for k in range(1, len(idx)):
            if p[k] != p[k - 1]:
                rows.append((p[k - 1], p[k], e[idx[k]]))
    if not rows:
        if log:
            log(f'[phase] values {vals} — no phase changes observed within matches')
        return None
    R = pd.DataFrame(rows, columns=['from', 'to', 'frac_at_change'])
    med = R.groupby(['from', 'to']).frac_at_change.median().round(3).to_dict()
    try:
        mins = np.array([laz_genome___phase_minute(x) for x in d['phase'].values])
        mm = []
        for m, idx in pd.Series(np.arange(len(d))).groupby(Ma).indices.items():
            idx = np.asarray(idx)
            p = ph[idx]
            for k in range(1, len(idx)):
                if p[k] != p[k - 1] and np.isfinite(mins[idx[k]]):
                    mm.append((p[k - 1], p[k], mins[idx[k]]))
        if mm:
            MM = pd.DataFrame(mm, columns=['from', 'to', 'minute']).groupby(['from', 'to']).minute.median().round(1).to_dict()
            if log:
                log(f'[phase] the minute token at each change {MM} — a Q1->Q2 above 12 (NBA) / 10 (FIBA) is WALL minutes, not played')
    except Exception:
        pass
    q1 = med.get(('Q1', 'Q2'))
    h1 = med.get(('1H', 'HT'), med.get(('1H', '2H')))
    ref = (q1, 0.25) if q1 is not None else (h1, 0.5) if h1 is not None else (None, None)
    verdict = 'frac is the PLAYED clock' if ref[0] is not None and abs(ref[0] - ref[1]) <= 0.06 else f'frac is NOT the played clock (phase change at {ref[0]}, expected ~{ref[1]})' if ref[0] is not None else 'no quarter/half change seen'
    if log:
        log(f'[phase] values {vals} · median frac at phase change {med} — {verdict}')
    return med

def laz_genome___ctx_arrays(d, ctx):
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else np.full(len(d), np.nan)
    hs, as_ = (num('h_score'), num('a_score'))
    ho, ao = (num('home_odds'), num('away_odds'))
    el = np.asarray(ctx.get('el'), float) if isinstance(ctx, dict) and ctx.get('el') is not None else np.full(len(d), 0.5)
    sd = hs - as_
    line = num('total_goals_handicap') if 'total_goals_handicap' in d.columns else num('total_points_handicap') if 'total_points_handicap' in d.columns else np.full(len(d), np.nan)
    back = np.where(sd >= 0, ho, ao)
    opp = np.where(sd >= 0, ao, ho)
    lead = np.where(sd > 0, ho, np.where(sd < 0, ao, np.nan))
    lose = np.where(sd > 0, ao, np.where(sd < 0, ho, np.nan))
    return dict(d=d, M=d['match_id'].values, hs=hs, as_=as_, sd=sd, tot=hs + as_, sport=ctx.get('sport') if isinstance(ctx, dict) else None, el_fine=ctx.get('el_fine') if isinstance(ctx, dict) else None, side=np.asarray(ctx.get('side'), dtype=object) if isinstance(ctx, dict) and ctx.get('side') is not None else None, ho=ho, ao=ao, do=num('draw_odds'), el=el, line=line, back=back, opp=opp, lead=lead, lose=lose, num=num)

def laz_genome___f(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).transform('first').values

def laz_genome___cmx(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).cummax().values

def laz_genome___cmn(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).cummin().values

def laz_genome___df(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).diff().fillna(0.0).values

def laz_genome___rk(v, M):
    """EXPANDING percentile rank: the value's rank among the match's values SEEN SO FAR.
    The previous body ranked against the WHOLE match — every future tick included — so
    `price_rank_in_match <= 0.25` meant 'among the lowest quarter of prices this match will
    EVER have', knowable only at the end. On the operator's ALL workbook 4,666 of 8,079 legs
    (58%) conditioned on it; the efootball draw cluster at 97% on 3.4 odds was this."""
    return pd.Series(np.asarray(v, float)).groupby(M).expanding().rank(pct=True).reset_index(level=0, drop=True).sort_index().values
