def laz_genome___ffill(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).ffill().values

def laz_genome___chg_grp(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).apply(lambda z: (z.diff().fillna(0) != 0).cumsum()).reset_index(drop=True).values

def laz_genome__build(term, d, ctx, sport=None, log=None):
    """Construct one element. Returns (array, reason). array None means the
    reason says why — never a plausible zero."""
    t = laz_genome__canon(term)
    ok, why = laz_genome__applies(t, sport) if sport else (True, '')
    if not ok:
        return (None, f'not applicable: {why}')
    g = laz_genome__GENOME.get(t)
    if g and g.get('kind') == 'unbuildable':
        return (None, g['arithmetic'])
    if t in d.columns:
        _CGg = _m('causality_guard')
        if _CGg is not None and sport:
            try:
                _okc, _whyc = _CGg.check_term(t, sport, 1.01)
                if not _okc and ('L1' in _whyc or 'forbidden' in _whyc.lower()):
                    return (None, f'DENIED by the causality guard: {_whyc[:70]}')
            except Exception as _ge:
                pass
        return (pd.to_numeric(d[t], errors='coerce').values, 'raw frame column')
    fn = laz_genome__BUILDERS.get(t)
    if fn is None:
        if (g or {}).get('kind') == 'column':
            return (None, f"column absent from this sport's frame ({(g or {}).get('provenance', '')})")
        return (None, f'documented but no builder: {(g or {}).get('arithmetic', 'unknown')[:90]}')
    C = laz_genome___ctx_arrays(d, ctx)
    LG = _m('laz_log')
    import warnings as _w
    with _w.catch_warnings(), np.errstate(divide='ignore', invalid='ignore'):
        _w.simplefilter('ignore', RuntimeWarning)
        v = LG.guard(f'genome.build {t}', fn, C) if LG else fn(C)
    if v is None:
        return (None, 'builder raised')
    v = np.asarray(v, float)
    if np.isfinite(v).sum() <= 100:
        return (None, 'built but fewer than 100 finite values on this frame')
    return (v, 'built')
laz_genome___RB_CTX = [None]

def laz_genome___rebuild_chunk(terms):
    """One worker's share of rebuild_all. Under the DISK pool each built array is written to
    the pool folder by the worker and only (term, path, shape, reason) comes back — no arrays
    through the pipe, no parent-side spike. On efootball at 16 GB that spike (6 workers x ~1 GB
    returning at once, on top of the frame, the h2h join and the brain features) was the kill.
    Under RAM the array itself is returned, as before."""
    d, ctx, sport, disk = laz_genome___RB_CTX[0]
    out = []
    for t in terms:
        try:
            v, why = laz_genome__build(t, d, ctx, sport)
            if v is None:
                out.append((t, None, None, why))
                continue
            a = np.ascontiguousarray(np.asarray(v, np.float32))
            if disk:
                import os as _os, uuid as _uu
                path = _os.path.join(disk, f'g_{_uu.uuid4().hex}.f32')
                a.tofile(path)
                out.append((t, path, a.shape, why))
                del a
            else:
                out.append((t, a, None, why))
        except Exception as e:
            out.append((t, None, None, f'builder raised {type(e).__name__}'))
    return out

def laz_genome__rebuild_all(d, ctx, pool=None, sport=None, log=None, workers=None):
    """Construct every applicable element the pool lacks. Reports every class."""
    laz_genome__bootstrap()
    H2 = _m('laz_h2h')
    if H2 is not None:
        LGh = _m('laz_log')
        add = LGh.guard('h2h attach', H2.attach, d, sport, log, default={}) if LGh else H2.attach(d, sport, log=log)
        _new = {k: v for k, v in (add or {}).items() if k not in d.columns}
        if _new:
            d = pd.concat([d, pd.DataFrame(_new, index=d.index)], axis=1)
        if add and log:
            log(f'[genome] +{len(add)} h2h/elo/form columns attached to the frame')
    built = {}
    notapp = []
    nobuild = []
    thin = []
    nocol = []
    _terms = [t for t in list(laz_genome__BUILDERS) + [k for k in laz_genome__GENOME if k not in laz_genome__BUILDERS] if not (pool is not None and (laz_genome__canon(t) in pool or t in pool))]

    def _sort(t, v, why):
        ct = laz_genome__canon(t)
        if v is not None:
            built[ct] = v
        elif why.startswith('not applicable'):
            notapp.append((t, why))
        elif 'column absent' in why:
            nocol.append((t, why))
        elif 'no builder' in why:
            nobuild.append((t, why))
        else:
            thin.append((t, why))
    _nw = int(workers or 1)
    if _nw > 1 and len(_terms) >= 2 * _nw:
        try:
            import multiprocessing as _mp
            _disk = getattr(pool, '_dir', None) if pool is not None and hasattr(pool, '_dir') else None
            laz_genome___RB_CTX[0] = (d, ctx, sport, _disk)
            _chunks = [_terms[i::_nw] for i in range(_nw)]
            if True:
                for _r in laz_workers__map(laz_genome___rebuild_chunk, _chunks, _nw, label='genome', log=log):
                    if _r is None: continue
                    for t, v, shape, why in _r:
                        if isinstance(v, str):
                            try:
                                v = np.memmap(v, dtype=np.float32, mode='r', shape=tuple(shape))
                            except Exception as _me:
                                v = None
                                why = f'memmap open failed: {type(_me).__name__}'
                        _sort(t, v, why)
                    del _r
            if log:
                log(f'[genome] {len(_terms)} elements built across {_nw} workers')
        except Exception as _pe:
            laz_workers__map.no_silent_serial('genome', f'{type(_pe).__name__}: {_pe}', log)   # [v246-STOP]
            if log:
                log(f'[genome] parallel build unavailable ({type(_pe).__name__}: {str(_pe)[:60]}) — sequential')
            for t in _terms:
                v, why = laz_genome__build(t, d, ctx, sport)
                _sort(t, v, why)
    else:
        for t in _terms:
            v, why = laz_genome__build(t, d, ctx, sport)
            _sort(t, v, why)
    if log:
        log(f'[genome] {sport}: +{len(built)} built · {len(notapp)} not applicable to this sport · {len(nocol)} columns this frame lacks · {len(nobuild)} documented without a builder · {len(thin)} unbuildable or too thin')
        for t, w in notapp[:3]:
            log(f'[genome]   not applicable: {t} — {w[:70]}')
        for t, w in thin[:3]:
            log(f'[genome]   thin: {t} — {w[:70]}')
    return (built, dict(not_applicable=notapp, no_builder=nobuild, thin=thin, column_absent=nocol))

def laz_genome__documentation(sports=('football', 'efootball', 'ebasketball', 'basketball', 'tennis', 'tabletennis', 'etennis', 'esports'), log=None):
    """THE DELIVERABLE — one row per element, reconstructable from that row.

    Anyone reading a row must be able to rebuild the element without opening
    source: its arithmetic, its inputs to primitives, which sports it applies
    to and why not for the rest, when it resolves, and where it came from.
    """
    laz_genome__bootstrap()
    FD = _m('laz_featdoc')
    RC = _m('laz_recovered')
    used = {}
    if RC is not None:
        for n, v in (RC.load() or {}).items():
            for c in v.get('conditions') or []:
                t = re.split('\\s*(?:>=|<=|>|<|==|!=)\\s*', str(c))[0].strip()
                if t:
                    used.setdefault(t, []).append(n)
    rows = []
    for t in sorted(laz_genome__GENOME):
        g = laz_genome__GENOME[t]
        ok = {}
        why = {}
        for sp in sports:
            a, r = laz_genome__applies(t, sp)
            ok[sp] = a
            why[sp] = r
        steps = ''
        if FD is not None and hasattr(FD, 'rebuild_recipe'):
            LG = _m('laz_log')
            rr = LG.guard('recipe', FD.rebuild_recipe, t, default=None) if LG else None
            if rr:
                steps = ' | '.join(rr.get('steps') or [])
        rows.append(dict(element=t, kind=g.get('kind'), aliases='|'.join(g.get('aliases') or []), arithmetic=g.get('arithmetic'), source_columns=g.get('source_columns'), has_builder=bool(laz_genome__canon(t) in laz_genome__BUILDERS), sports_applicable='|'.join((s for s in sports if ok[s])), excluded_from='|'.join((f'{s}({why[s]})' for s in sports if not ok[s]))[:300], resolves_at=g.get('resolves_at'), causality=g.get('causality'), provenance=g.get('provenance'), rebuild_steps=steps[:400], demanded_by=len(used.get(t, [])), first_used_by='|'.join(sorted(used.get(t, []))[:4])))
    D = pd.DataFrame(rows).sort_values(['demanded_by', 'element'], ascending=[False, True])
    if log:
        log(f'[genome] documentation: {len(D)} elements · {int(D.has_builder.sum())} with a builder · {int((D.kind == 'unbuildable').sum())} declared unbuildable')
    return D

def laz_genome__to_excel(path=None, log=print):
    WB = _m('laz_workbook')
    OW = _m('laz_owner')
    path = path or os.path.join((OW.LAZ_OWNER['paths'].get('output_dir') if OW else '.') or '.', 'LAZ_GENOME.xlsx')
    D = laz_genome__documentation(log=log)
    b = WB.Book(path, 'LAZARUS GENOME', 'every element the engine knows: arithmetic, inputs, sports, provenance — enough to rebuild any of them without reading source')
    nb = int((~D.has_builder & (D.kind != 'unbuildable') & (D.kind != 'column')).sum())
    b.dashboard([('Elements documented', len(D)), ('  with an executable builder', int(D.has_builder.sum())), ('  raw frame columns', int((D.kind == 'column').sum())), ('  declared NOT buildable (data absent)', int((D.kind == 'unbuildable').sum())), ('  documented, builder still to write', nb), ('', ''), ('Terms demanded by the recovered stacks', int((D.demanded_by > 0).sum())), ('Most demanded', f'{D.iloc[0].element} ({int(D.iloc[0].demanded_by)} stacks)')])
    b.table(D, 'GENOME', title='EVERY ELEMENT — arithmetic, inputs, sports, provenance, rebuild steps')
    b.table(D[D.kind == 'unbuildable'], 'NOT_BUILDABLE', title='DECLARED UNBUILDABLE — the data no frame carries, named rather than invented')
    b.method([('Reading a row', 'arithmetic is the formula, source_columns its inputs, rebuild_steps the ordered derivation from frame columns.'), ('sports_applicable', 'where the quantity exists. excluded_from carries the structural reason — a set term has no meaning in football.'), ('has_builder', 'False means the arithmetic is documented but the executable form is not written. The element is reconstructable by hand, not by the engine.'), ('Why 95 recoveries were rejected', '`spread` — the most demanded term, in 347 stacks — was recovered automatically as np.mean([len(v_) for v_ in idx.values()]), a local variable from an unrelated function. A name in a list is not a recovery.'), ('Refusal', 'Deriving final_result from the last tick score disagreed with the recorded final_winner on 46% of tabletennis rows. The genome never fabricates a quantity it has no source for.')])
    return b.save(log)
