"""laz_brain_features.py — THE 46 DERIVED PLAYER-FORM FEATURES, ported verbatim.

ABSORBED from LazarusEV_Engine_v76_89_Mac16.laz_brain_features. The function
reads the h2h player columns UNPREFIXED for one player — that engine's frame
had one player per row. Ours carries both players per row as hp_* and ap_*.
The port runs the ORIGINAL BODY, unchanged, twice: once with the home player's
columns exposed under their bare names, once with the away player's; then
selects per row by the backed side. The 46 features are then available three
ways: <f>_hp, <f>_ap, and <f> (the backed player's).

325 corpus strategies condition on these — grind_form, wr_vs_base5,
form_gradient, elo_velocity, cur_elo_edge, h2h_trend, load24 — and could not
be placed until now.
"""
import numpy as np, pandas as pd

def laz_brain_features___brain_one(d, odds=None):
    """The 46 derived features. Each is a comparison the raw export cannot make, and
    the strongest of them -- cur_elo_edge, current form-rating minus the OPPONENT's
    rating -- existed in no file until it was constructed here."""
    import numpy as _np
    import pandas as _pd

    def n(c):
        return _pd.to_numeric(d[c], errors='coerce') if c in d.columns else None
    F = {}
    elo, oelo, cur = (n('player_betsson_elo'), n('opponnent_betsson_elo'), n('cur50games_homeplayer_elo'))
    wr, w5, w10, w20 = (n('total_player_wr'), n('winrate_l5g'), n('winrate_l10g'), n('winrate_l20g'))
    if elo is not None and oelo is not None:
        F['elo_edge'] = elo - oelo
        F['elo_ratio'] = elo / oelo.replace(0, _np.nan)
    if cur is not None:
        if oelo is not None:
            F['cur_elo_edge'] = cur - oelo
        if elo is not None:
            F['elo_velocity'] = cur - elo
            F['form_x_class'] = cur * elo / 1000000.0
    if wr is not None:
        for lbl, v in (('5', w5), ('10', w10), ('20', w20)):
            if v is not None:
                F[f'wr_vs_base{lbl}'] = v - wr
        if w5 is not None:
            F['streak_quality'] = w5 * wr
    if w5 is not None and w10 is not None and (w20 is not None):
        F['form_accel'] = w5 - w10 - (w10 - w20)
        F['form_gradient'] = w5 - w20
    for lbl in ('5', '10', '20'):
        s, c = (n(f'avggoals_scored_{lbl}'), n(f'avggoals_conceded_{lbl}'))
        if s is not None and c is not None:
            F[f'net_goals_{lbl}'] = s - c
            F[f'goal_ratio_{lbl}'] = s / c.replace(0, _np.nan)
    if n('avggoals_scored_5') is not None and n('avggoals_scored_20') is not None:
        F['scoring_accel'] = n('avggoals_scored_5') - n('avggoals_scored_20')
    if 'net_goals_20' in F and wr is not None:
        F['dominance'] = F['net_goals_20'] * wr
    h10, h5 = (n('h2h_winrate_l10g'), n('h2h_winrate_l5g'))
    hgs, hgc = (n('h2h_avggoals_scored_l10g'), n('h2h_avggoals_conceded_l10g'))
    if hgs is not None and hgc is not None:
        F['h2h_net10'] = hgs - hgc
    if h10 is not None:
        if wr is not None:
            F['h2h_vs_general'] = h10 - wr
        if n('h2h_l10g') is not None:
            F['h2h_confidence'] = h10 * n('h2h_l10g')
        if h5 is not None:
            F['h2h_trend'] = h5 - h10
    load = n('count_games_last_24_hours')
    if load is not None:
        F['load24'] = load
        if wr is not None:
            F['load_x_skill'] = load * wr
        if 'wr_vs_base5' in F:
            F['grind_form'] = load * F['wr_vs_base5']
    if odds is not None:
        imp = _np.where(_np.isfinite(odds) & (odds > 1.0), 1.0 / odds, _np.nan)
        for lbl, v in (('career', wr), ('l20', w20), ('l5', w5), ('h2h', h10)):
            if v is not None:
                F[f'ev_{lbl}'] = v * odds
                F[f'misprice_{lbl}'] = v - imp
        if 'wr_vs_base20' in F:
            F['gift'] = F['wr_vs_base20'] * odds
        if 'elo_edge' in F:
            F['elo_vs_price'] = F['elo_edge'] / 100.0 - imp
    return _pd.DataFrame(F, index=d.index)
laz_brain_features__LAZ_PRODUCTION_TABLES = {'efootball': dict(player_history='public.h2h_player_performance', matches='efootball_matches', live_conditions='rt_efootball_betting_conditions', join_key='match_id', side_column='sidepick', note='one row per player per match; sidepick says which side the row describes'), 'ebasketball': dict(player_history='ebasketball_h2h_player_performance', matches='ebasketball_games', live_conditions='rt_allsports_betting_conditions', join_key='match_id', side_column='sidepick', note='same shape as eFootball; no draw exists in this code')}
laz_brain_features__LAZ_PRODUCTION_EQUIVALENCE = {'cur_elo_edge': ('cur50games_homeplayer_elo - opponnent_betsson_elo', 'h.cur50games_homeplayer_elo - h.opponnent_betsson_elo', 'BOTH VALUES COME FROM THE HOME PLAYER ROW. opponnent_betsson_elo is the opponent rating AS RECORDED ON THAT ROW -- not the away row own player_betsson_elo. Taking it from the away row gives a different number and every CombinA strategy would fire on something it was never measured on.'), 'elo_edge': ('player_betsson_elo - opponnent_betsson_elo', 'h.player_betsson_elo - h.opponnent_betsson_elo', 'same row, both values'), 'form_x_class': ('cur50games_homeplayer_elo * player_betsson_elo / 1e6', 'h.cur50games_homeplayer_elo * h.player_betsson_elo / 1000000.0', 'the divisor keeps the scale readable; it must be applied in production too'), 'wr_vs_base20': ('winrate_l20g - total_player_wr', 'h.winrate_l20g - h.total_player_wr', 'form against the player OWN career rate, not against the field'), 'h2h_net5': ('h2h_avggoals_scored_l5g - h2h_avggoals_conceded_l5g', 'h.h2h_avggoals_scored_l5g - h.h2h_avggoals_conceded_l5g', ''), 'h2h_vs_form': ('h2h_winrate_l10g - winrate_l20g', 'h.h2h_winrate_l10g - h.winrate_l20g', ''), 'last_game_leak': ('goals_conceded_lastgame - avggoals_conceded_5', 'h.goals_conceded_lastgame - h.avggoals_conceded_5', ''), 'last_game_shock': ('(goals_scored_lastgame - avggoals_scored_5) - (goals_conceded_lastgame - avggoals_conceded_5)', '(h.goals_scored_lastgame - h.avggoals_scored_5) - (h.goals_conceded_lastgame - h.avggoals_conceded_5)', ''), 'exp_x_elo': ('log10(max(total_games,10)) * player_betsson_elo / 1000', 'LOG(10, GREATEST(h.total_games, 10)) * h.player_betsson_elo / 1000.0', 'log-scaled: 1600 on 2,000 games is a different claim from 1600 on 40'), 'dp_lead_open': ('1/lead_odds_now - 1/lead_odds_at_kickoff', '1.0/c.leader_odds - 1.0/f.first_leader_odds', 'the kickoff price is the FIRST tick of the match, carried forward. In production it must be captured at kickoff and held, not re-read.'), 'implied': ('1 / lead_odds', '1.0 / c.leader_odds', ''), 'trailer': ('(h_score - a_score) < 0', 'CASE WHEN c.h_score < c.a_score THEN 1 ELSE 0 END', ''), 'model_p': ('model.predict_proba(X)[:, 1]', 'NOT PRODUCIBLE IN SQL', 'The fitted model must be deployed. Load laz_model_<sport>.joblib and score the 36 features in the ORDER given by LAZ_MODEL_MANIFEST_<sport>.json. A gradient booster reads by position; the same columns reordered is a different model, which is what the fingerprint exists to catch.'), 'model_edge': ('model_p - 1/lead_odds', 'NOT PRODUCIBLE IN SQL', 'follows model_p')}

def laz_brain_features___view(d, prefix):
    """The frame with one player's hp_/ap_ columns exposed under the bare names
    the original function reads."""
    cols = {c[len(prefix):]: c for c in d.columns if str(c).startswith(prefix)}
    v = pd.DataFrame(index=d.index)
    for bare, full in cols.items():
        v[bare] = d[full]
    for c in ('betsson_home_player_elo', 'betsson_away_player_elo', 'home_odds', 'away_odds', 'match_id', 'ts'):
        if c in d.columns:
            v[c] = d[c]
    return v

def laz_brain_features__score_model(d, out, sport, side, log=None):
    """model_p and model_edge from the sport's gradient-boosted scorer, IF the
    model file and sklearn are present. 553 corpus strategies condition on
    model_edge. sklearn is NOT a core dependency: absent, the columns are not
    built and the log says so; nothing else changes.

    The score is a FEATURE — a live, pre-match number a strategy may condition
    on — never a strategy. It sits under the causality guard like any term.
    model_p is the backed side's win probability; model_edge = model_p - implied."""
    import os, json
    OW = _m('laz_owner')
    home = (OW.LAZ_OWNER['paths'].get('output_dir') if OW else '.') or '.'
    mf = os.path.join(home, f'laz_model_{sport}.joblib')
    man = os.path.join(home, f'LAZ_MODEL_MANIFEST_{sport}.json')
    if not (os.path.exists(mf) and os.path.exists(man)):
        if log:
            log(f'[model] no scorer for {sport} (laz_model_{sport}.joblib / manifest not in {home}) — model_p not built')
        return {}
    try:
        import joblib
        M = joblib.load(mf)
        feats = _laz_json_read(man)['features']
    except Exception as e:
        if log:
            log(f'[model] {sport}: {type(e).__name__}: {str(e)[:80]} — sklearn/joblib needed for model_p; not built')
        return {}
    res = {}
    for sfx, odds_col in (('_hp', 'home_odds'), ('_ap', 'away_odds')):
        X = np.column_stack([np.asarray(out.get(f + sfx, np.full(len(d), np.nan)), float) for f in feats])
        ok = np.isfinite(X).all(axis=1)
        p = np.full(len(d), np.nan)
        if ok.any():
            try:
                p[ok] = M.predict_proba(X[ok])[:, 1]
            except Exception as e:
                if log:
                    log(f'[model] predict {type(e).__name__}: {str(e)[:60]}')
                return {}
        odds = pd.to_numeric(d[odds_col], errors='coerce').values if odds_col in d.columns else np.full(len(d), np.nan)
        imp = np.where(np.isfinite(odds) & (odds > 1), 1.0 / odds, np.nan)
        res['model_p' + sfx] = p
        res['model_edge' + sfx] = p - imp
    if side is not None:
        res['model_p'] = np.where(side == 'away', res['model_p_ap'], res['model_p_hp'])
        res['model_edge'] = np.where(side == 'away', res['model_edge_ap'], res['model_edge_hp'])
    else:
        res['model_p'] = res['model_p_hp']
        res['model_edge'] = res['model_edge_hp']
    if log:
        log(f'[model] {sport}: model_p / model_edge scored on {int(np.isfinite(res['model_p']).sum()):,} rows (manifest fingerprint {_laz_json_read(man).get('fingerprint')})')
    return res

def laz_brain_features__build(d, ctx=None, log=None):
    """Returns {feature: array} for the 46 features x (hp, ap, backed)."""
    out = {}
    if not any((str(c).startswith('hp_') for c in d.columns)):
        if log:
            log('[brain] no hp_/ap_ columns on this frame — player-form features not built')
        return out
    side = None
    if isinstance(ctx, dict) and ctx.get('side') is not None:
        side = np.asarray(ctx['side']).astype(str)
    ho = pd.to_numeric(d['home_odds'], errors='coerce') if 'home_odds' in d.columns else None
    ao = pd.to_numeric(d['away_odds'], errors='coerce') if 'away_odds' in d.columns else None
    LG = _m('laz_log')
    try:
        H = laz_brain_features___brain_one(laz_brain_features___view(d, 'hp_'), odds=ho)
        A = laz_brain_features___brain_one(laz_brain_features___view(d, 'ap_'), odds=ao)
    except Exception as e:
        if log:
            log(f'[brain] {type(e).__name__}: {str(e)[:80]}')
        return out
    for c in H.columns:
        hv = pd.to_numeric(H[c], errors='coerce').values
        av = pd.to_numeric(A[c], errors='coerce').values if c in A.columns else np.full(len(d), np.nan)
        out[c + '_hp'] = hv
        out[c + '_ap'] = av
        out[c] = np.where(side == 'away', av, hv) if side is not None else hv
    if log:
        log(f'[brain] +{len(H.columns)} player-form features x3 (hp, ap, backed) = {len(out)}')
    sport = (ctx.get('sport') if isinstance(ctx, dict) else None) or getattr(d, 'attrs', {}).get('sport')
    if not sport and log:
        log('[model] sport unknown to the feature builder (ctx carries no sport) — scorer not run')
    if sport:
        try:
            out.update(laz_brain_features__score_model(d, out, str(sport).lower(), side, log=log))
        except Exception as e:
            if log:
                log(f'[model] {type(e).__name__}: {str(e)[:80]}')
    return out
