def laz_everything__sport_features(d, ctx, sport):
    """PER-SPORT terms the cross-sport builders cannot define.

    These blocked 61 basketball stacks, 156 ebasketball and 46 tennis. Each is
    built from columns the frame already carries — q1_lead, point_spread_*,
    pair_*, sets, set1_winner — which were sitting unused because the recovered
    stacks name them under the ORIGINAL engine's names.

    Quarter and set terms carry their resolution time: a q1 quantity is final
    only once the first quarter has ended, and laz_lookahead gates it there
    rather than the strategy being discarded.
    """
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else np.full(len(d), np.nan)
    el = np.asarray(ctx.get('el'), float) if isinstance(ctx, dict) and ctx.get('el') is not None else np.full(len(d), 0.5)
    hs, as_ = (num('h_score'), num('a_score'))
    sd = hs - as_
    tot = hs + as_
    mid = d['match_id'].values
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    out = {}
    res = {}

    def put(k, v, resolves=None):
        v = np.asarray(v, float)
        if np.isfinite(v).sum() > 100:
            out[k] = v
            if resolves:
                res[k] = resolves
    if sp in ('basketball', 'ebasketball'):
        q1l = num('q1_lead')
        q1t = num('q1_tot')
        psh = num('point_spread_handicap')
        tph = num('total_points_handicap')
        put('q1_margin', np.abs(q1l), 0.25)
        put('ebb_q1_margin', np.abs(q1l), 0.25)
        put('seg_margin', np.abs(sd) - np.abs(q1l), 0.25)
        put('q2seg_margin', np.abs(sd) - np.abs(q1l), 0.5)
        put('ebb_q2seg_margin', np.abs(sd) - np.abs(q1l), 0.5)
        put('ebb_q2seg_won', (np.sign(sd - q1l) == np.sign(q1l)).astype(float), 0.5)
        put('seg_wins', (np.sign(q1l) != 0).astype(float) + (np.sign(q1l) == np.sign(sd - q1l)).astype(float), 0.25)
        put('lead_net', sd)
        put('fav', (num('point_spread_home') <= num('point_spread_away')).astype(float))
        put('lead_is_dog', np.where(sd > 0, (num('point_spread_home') > num('point_spread_away')).astype(float), np.where(sd < 0, (num('point_spread_away') > num('point_spread_home')).astype(float), np.nan)))
        with np.errstate(invalid='ignore', divide='ignore'):
            put('tp_vel_n', np.where(el > 0.02, tot / np.maximum(el, 0.02), np.nan) / np.maximum(tph, 1e-09))
            put('u_vel', np.where(el > 0.02, tot / np.maximum(el, 0.02), np.nan))
        put('scored_any', (tot > 0).astype(float))
        put('line_flat', np.abs(tph - pd.Series(tph).groupby(mid).transform('first').values))
        put('ebb_qhalf_b', (el <= 0.5).astype(float))
        p5 = num('pair_h2h5') if 'pair_h2h5' in d.columns else np.full(len(d), np.nan)
        pc = num('pair_conc5') if 'pair_conc5' in d.columns else np.full(len(d), np.nan)
        put('pair_p5', np.nanmean(np.vstack([p5, pc]), axis=0))
        put('wall_min', np.minimum(np.abs(tph - tot), np.nan_to_num(p5, nan=np.inf)))
    if sp in ('tennis', 'tabletennis', 'etennis'):
        _st = num('sets')
        _s1 = pd.Series(np.where(_st >= 1, np.sign(sd), np.nan)).groupby(mid).transform(lambda z: z.ffill()).values
        s1w = num('set1_winner')
        if not np.isfinite(s1w).any():
            s1w = (_s1 > 0).astype(float)
        _s = num('sets')
        bk = num('bk_sets')
        op = num('op_sets')
        if not np.isfinite(bk).any():
            bk = _s
            op = np.zeros(len(d))
        put('s1w_sd', np.where(np.isfinite(s1w), np.sign(s1w - 0.5), np.nan), 0.34)
        put('s1w_pre', s1w, 0.34)
        put('ten_set_no', np.nan_to_num(bk, nan=0) + np.nan_to_num(op, nan=0))
        put('set_event', num('set_event') if 'set_event' in d.columns else bk + op)
        put('anchor', num('dog_anchor') if 'dog_anchor' in d.columns else np.full(len(d), np.nan))
        put('ten_o', np.where(sd >= 0, num('home_odds'), num('away_odds')))
        put('ten_pm_ratio', (lambda h, a: np.where(a > 0, h / a, np.nan))(pd.Series(num('home_odds')).groupby(mid).transform('first').values, pd.Series(num('away_odds')).groupby(mid).transform('first').values))
        put('jump_s1w', (lambda u: u / np.maximum(pd.Series(u).groupby(mid).transform('first').values, 1e-09))(np.where(sd >= 0, num('home_odds'), num('away_odds'))))
    if 'ts' in d.columns:
        _t = pd.to_datetime(d['ts'], errors='coerce').astype('int64') / 1000000000.0
        _chg = pd.Series(tot).groupby(mid).diff().fillna(0) != 0
        _grp = _chg.groupby(mid).cumsum()
        _tfirst = pd.Series(_t).groupby([pd.Series(mid).values, _grp.values]).transform('first')
