laz_everything__CLOCKLESS = set()   # [v240 Rule 1] CLOCKLESS deleted — no quarter-index fallback anywhere; elapsed is timestamp arithmetic where a real clock exists, and DOES NOT EXIST where it does not (never a fabricated index)
laz_everything___NOM_CACHE = {}
laz_everything___CLK_CACHE = {}

def laz_everything__clock_from_parquet(sport):
    """Read the league column STRAIGHT FROM THE PARQUET.

    laz_startup.prepare() drops `league` and `phase` — they are strings and the
    pool is numeric — so the clock cannot be read off the prepared frame. It is
    read from the source parquet instead and cached per sport.
    """
    OW = _m('laz_owner')
    if OW is None:
        return None
    _k = OW.canon(sport) if hasattr(OW, 'canon') else str(sport).lower()
    if _k in laz_everything___CLK_CACHE:
        return laz_everything___CLK_CACHE[_k]
    try:
        import pyarrow.parquet as pq
        path = OW.frame_path(sport)
        if not path or not os.path.exists(path):
            return None
        names = set(pq.ParquetFile(path).schema_arrow.names)
        if 'league' not in names:
            return None
        lg = pq.read_table(path, columns=['league']).to_pandas()['league'].astype(str)
        u = lg.value_counts()
        vals = {}
        for name, cnt in u.items():
            t = str(name).lower()
            m = re.search('(\\d+)\\s*[x\\u00d7]\\s*(\\d+)', t)
            if m:
                vals[name] = float(m.group(1)) * float(m.group(2))
                continue
            m = re.search('(\\d+)\\s*min', t)
            if m:
                vals[name] = float(m.group(1))
        if not vals:
            return None
        w = sum((u[k] for k in vals))
        med = sum((vals[k] * u[k] for k in vals)) / max(w, 1)
        laz_everything___CLK_CACHE[_k] = dict(per_league=vals, weighted=float(med), distinct=sorted({v for v in vals.values()}), coverage=float(w / len(lg)))
        del lg, u
        return laz_everything___CLK_CACHE[_k]
    except Exception:
        laz_everything___CLK_CACHE[_k] = None
        return None

def laz_everything__clock_per_row(d, sport):
    """Per-ROW match length for a mixed-league frame.

    eFootball carries 6, 8, 10 and 12-minute leagues in one frame, so a single
    median would misdate every match that is not 9 minutes. The league column
    is dropped by prepare(), so match_id -> league is read once from the
    parquet and mapped onto the prepared frame.
    """
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    if sp in laz_everything__CLOCKLESS:
        return None
    c = laz_everything__clock_from_parquet(sport)
    if not c:
        return None
    if c.get('coverage', 0) < 0.5:
        return None
    if len(c['distinct']) < 2:
        return None
    try:
        import pyarrow.parquet as pq
        path = OW.frame_path(sport)
        t = pq.read_table(path, columns=['match_id', 'league']).to_pandas()
        t['mins'] = t['league'].astype(str).map(c['per_league'])
        mp = t.dropna(subset=['mins']).groupby('match_id')['mins'].first()
        del t
        v = d['match_id'].astype(str).map({str(k): float(x) for k, x in mp.items()}).astype(float).values
        return v if np.isfinite(v).mean() > 0.5 else None
    except Exception:
        return None

def laz_everything__clock_from_league(d):
    """PER MATCH match length, parsed from the LEAGUE NAME.

    The virtual sports state it outright and it VARIES BY LEAGUE, so no single
    constant per sport is correct:

        "eBasketball H2H GG League - 4 x 5 mins"   -> 4 x 5  = 20
        "eBasketball Euroleague Battle - 4 x 5"    -> 4 x 5  = 20
        "eFootball Battle - 8 mins play"           ->          8
        "eFootball GT Leagues - 12 mins play"      ->         12
        "eFootball Battle - Volta League 6 mins"   ->          6

    I had eBasketball at 40 from the real-world rulebook, then 24 from a
    per-match phase median. Both wrong: it is 4 x 5 = 20, and the phase counter
    simply keeps running past the whistle. eFootball is not one number either —
    6, 8, 10 and 12 minute leagues all appear in the same frame.

    Returns a per-ROW array so a mixed-league frame is handled correctly.
    """
    if d is None or 'league' not in getattr(d, 'columns', []):
        return None
    lg = d['league'].astype(str)
    u = pd.Series(lg.unique())

    def parse(name):
        t = str(name).lower()
        m = re.search('(\\d+)\\s*[x\\u00d7]\\s*(\\d+)', t)
        if m:
            return float(m.group(1)) * float(m.group(2))
        m = re.search('(\\d+)\\s*min', t)
        if m:
            return float(m.group(1))
        return np.nan
    mp = {n: parse(n) for n in u}
    v = lg.map(mp).astype(float).values
    return v if np.isfinite(v).sum() > 0 else None

def laz_everything__nominal_from_frame(d, sport=None):
    """Match length. The league name first — it is STATED there and it varies
    by league — then the phase column, then the constant."""
    c = laz_everything__clock_from_parquet(sport)
    if c and c.get('coverage', 0) >= 0.5:
        return c['weighted']
    v = laz_everything__clock_from_league(d)
    if v is not None and np.isfinite(v).sum() > 100:
        return float(np.nanmedian(v))
    if d is None or 'phase' not in getattr(d, 'columns', []):
        return None
    try:
        m = d['phase'].astype(str).str.extract('(\\d+)\\s*minute')[0].astype(float)
        if m.notna().sum() < 200:
            return None
        pm = pd.DataFrame(dict(mid=d['match_id'].values, m=m.values)).dropna().groupby('mid').m.max()
        v = float(pm.median())
        return v if v > 0 else None
    except Exception:
        return None

def laz_everything__causal_elapsed(d, sport, tick_sec=None, log=None):
    """THE ONE ELAPSED. Share of the match played, computable AT THE TICK.

    D18: every previous elapsed divided by a MATCH-LEVEL FINAL AGGREGATE —
    `transform('size')` (the match's final tick count) or `transform('max')`
    (its final minute). The value at tick 20 therefore CHANGED depending on
    what happened after tick 20 (measured: 0.21 / 0.35 / 0.70 for the same
    tick as the history was truncated). Production cannot compute that number
    at placement time because the match has not ended. 1,177 of 4,742 book
    strategies conditioned on it, through prog, u_elapsed, u_remain,
    u_margin_rate, u_pace and u_drought.

    This divides by the NOMINAL length instead — per-row where leagues differ
    (eFootball 6/8/10/12 min), the frame's measured length next, the rulebook
    constant last — which is knowable at kickoff. On a CLOCKLESS sport it
    returns None: the engine has already said there is no clock there, and the
    old tick-position fallback was precisely the fabrication that leaked.

    Returns a float array in [0, 1.2] (extra time runs past 1.0), or None.
    """
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    if sp in laz_everything__CLOCKLESS:
        return None
    n = len(d)
    mid = d['match_id'].values
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else None
    nom_row = None
    try:
        nom_row = laz_everything__clock_per_row(d, sport)
    except Exception as _e:
        nom_row = None
    nom = None
    try:
        nom = laz_everything__nominal(sport, d)
    except Exception as _e:
        nom = None
    denom = None
    if nom_row is not None and np.isfinite(np.asarray(nom_row, float)).sum() > 0:
        denom = np.asarray(nom_row, float)
        if nom is not None:
            denom = np.where(np.isfinite(denom), denom, float(nom))
    elif nom is not None:
        denom = np.full(n, float(nom))
    if denom is None:
        return None
    mn = num('minute')
    if (mn is None or np.isfinite(mn).mean() <= 0.5) and 'phase' in d.columns:
        try:
            GN = _m('laz_genome')
            if GN is not None and hasattr(GN, '_phase_minute'):
                _pm = pd.Series(d['phase']).astype(str).map(GN._phase_minute).astype(float)
                _pm = _pm.groupby(mid).ffill().values
                if np.isfinite(_pm).mean() > 0.5:
                    mn = _pm
        except Exception as _pe:
            pass
    if mn is not None and np.isfinite(mn).mean() > 0.5:
        with np.errstate(divide='ignore', invalid='ignore'):
            el = mn / np.maximum(denom, 1e-09)
        return np.clip(el, 0, 1.2)
    if 'ts' in d.columns:
        ts = pd.to_datetime(d['ts'], errors='coerce')
        t0 = ts.groupby(mid).transform('min')
        secs = (ts - t0).dt.total_seconds().values
        with np.errstate(divide='ignore', invalid='ignore'):
            el = secs / np.maximum(denom * 60.0, 1e-09)
        return np.clip(el, 0, 1.2)
    return None

def laz_everything__nominal(sport, d=None):
    """Derived from the frame first, rulebook constant only as a fallback."""
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    if sp in laz_everything__CLOCKLESS:
        return None
    if sp in laz_everything___NOM_CACHE:
        return laz_everything___NOM_CACHE[sp]
    v = laz_everything__nominal_from_frame(d, sp)
    if v is None:
        v = laz_everything__NOMINAL_MINUTES.get(sp)
    laz_everything___NOM_CACHE[sp] = v
    return v

def laz_everything__build(d, ctx, pool=None, log=None, sport=None):
    """Add every buildable missing term. Returns {name: array}."""
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else np.full(len(d), np.nan)
    hs, as_ = (num('h_score'), num('a_score'))
    C = dict(el=np.asarray(ctx.get('el'), float) if isinstance(ctx, dict) and ctx.get('el') is not None else np.full(len(d), 0.5), sd=hs - as_, tot=hs + as_, ho=num('home_odds'), ao=num('away_odds'), do=num('draw_odds'), nom=laz_everything__nominal(sport, d), nom_row=laz_everything__clock_per_row(d, sport))
    import time as _tm
    out = {}
    laz_everything___GB_MEMO.clear()   # [AmunEv v1 SPEED] fresh memo per build; the frame is the same for every lambda below
    _t_build0 = _tm.time(); _slow = []
    for name, fn in laz_everything__BUILDERS.items():
        if pool is not None and name in pool:
            continue
        try:
            _t1 = _tm.time()
            r = fn(pool or {}, C)
            if r is None:
                continue
            v = np.asarray(r, np.float32)
            if np.isfinite(v).sum() > 100:
                if pool is not None and hasattr(pool, '_dir'):   # [AmunEv v1 SPEED] a DISK pool: write now, hold a memmap handle, not RAM
                    pool[name] = v; out[name] = pool[name]; del v
                else:
                    out[name] = v
            _dt = _tm.time() - _t1
            if _dt > 2.0:
                _slow.append((name, _dt))
        except Exception:
            pass
    try:
        _sf = laz_everything__sport_features(d, dict(el=C['el']), sport)
        for _k, _v in (_sf or {}).items():
            if pool is None or _k not in pool:
                out[_k] = _v
    except Exception:
        pass
    try:
        _lg = laz_everything__league_flags(d, sport)
        for _k, _v in (_lg or {}).items():
            if pool is None or _k not in pool:
                out[_k] = _v
    except Exception:
        pass
    _M = d['match_id'].values
    C2 = dict(C, hs=hs, as_=as_, line=num('total_goals_handicap') if 'total_goals_handicap' in d.columns else num('total_points_handicap') if 'total_points_handicap' in d.columns else np.full(len(d), np.nan))
    if log:
        log(f'[everything] BUILDERS: {len(out)} built in {_tm.time() - _t_build0:.0f}s' + (' · slow: ' + ', '.join(f'{n} {t:.0f}s' for n, t in sorted(_slow, key=lambda z: -z[1])[:6]) if _slow else ''))   # [AmunEv v1 SPEED]
    _t_cross0 = _tm.time(); _slow = []
    for _n, _f in laz_everything__CROSS.items():
        if pool is not None and _n in pool:
            continue
        try:
            _t1 = _tm.time()
            _v = np.asarray(_f(C2, _M), float)
            if np.isfinite(_v).sum() > 100:
                if pool is not None and hasattr(pool, '_dir'):   # [AmunEv v1 SPEED]
                    pool[_n] = _v; out[_n] = pool[_n]; del _v
                else:
                    out[_n] = _v
            _dt = _tm.time() - _t1
            if _dt > 2.0:
                _slow.append((_n, _dt))
        except Exception:
            pass
    if log:
        log(f'[everything] CROSS: done in {_tm.time() - _t_cross0:.0f}s · groupby memo hits {len(laz_everything___GB_MEMO)} distinct ops' + (' · slow: ' + ', '.join(f'{n} {t:.0f}s' for n, t in sorted(_slow, key=lambda z: -z[1])[:6]) if _slow else ''))   # [AmunEv v1 SPEED]
    try:
        lp = np.where(C['sd'] > 0, C['ho'], np.where(C['sd'] < 0, C['ao'], np.nan))
        s = pd.Series(lp)
        g = s.groupby(d['match_id'])
        out['spread'] = (g.cummax() - g.cummin()).values
        opp = np.where(C['sd'] > 0, C['ao'], C['ho'])
        o0 = pd.Series(opp).groupby(d['match_id']).transform('first').values
        out['recovery_x'] = np.where(o0 > 0, opp / o0, np.nan)
    except Exception:
        pass
    try:
        t = pd.Series(C['tot'])
        chg = t.groupby(d['match_id']).diff().fillna(0) != 0
        grp = chg.groupby(d['match_id']).cumsum()
        idx = pd.Series(np.arange(len(d)))
        first = idx.groupby([d['match_id'].values, grp.values]).transform('first')
        out['min_since_goal'] = (idx - first).values * 1.0
    except Exception:
        pass
    try:
        _full, _skip = laz_everything__build_full(d, dict(el=C['el']), pool, sport, log=None)
        for _k, _v in _full.items():
            if pool is None or _k not in pool:
                out[_k] = _v
    except Exception as _e:
        if log:
            log(f'[full] {type(_e).__name__}: {str(_e)[:60]}')
    LA = _m('laz_lookahead')
    F = laz_everything__features()
    reg = 0
    if LA is not None:
        for name in out:
            r = (F.get(name) or {}).get('resolves_at')
            try:
                if r and float(r) > 0:
                    LA.register_resolves_at(name, float(r))
                    reg += 1
                else:
                    LA.register_derived(name, ['h_score', 'a_score', 'home_odds', 'away_odds'])
            except Exception:
                pass
    if log:
        _c = laz_everything__clock_from_parquet(sport)
        if _c:
            _txt = f'clock from LEAGUE NAME: {'/'.join((f'{x:g}' for x in _c['distinct'][:6]))}min (weighted {_c['weighted']:.1f}, {_c['coverage'] * 100:.0f}% of rows)'
        elif C.get('nom'):
            _txt = f'clock {C['nom']:g}min (phase-derived)'
        else:
            _txt = 'CLOCKLESS — minute terms not built'
        log(f'[everything] +{len(out)} recovered terms for {sport or 'sport'} ({_txt}) · {reg} carry a declared resolves_at')
    return out

def laz_everything__adapt_all(d, ctx, pool, sport, log=None):
    """Build the recovered terms AND report how many stacks each sport unlocks."""
    E = laz_everything__build(d, ctx, pool, log=log, sport=sport)
    pool.update(E)
    RC = _m('laz_recovered')
    if RC is None:
        return (pool, None)
    C = RC.coverage(pool)
    if log:
        mine = C[C.sport.astype(str).str.lower().isin([str(sport).lower(), 'none', 'nan'])]
        log(f'[everything] {sport}: {int(C.applies.sum())} of {len(C)} stacks armable ({int(mine.applies.sum())} tagged for this sport or untagged)')
    return (pool, C)
laz_everything__NON_TRANSFERABLE = {'set1_winner': 'set structure — football and basketball have no sets', 's1w_sd': 'set structure', 's1w_pre': 'set structure', 'sets': 'set structure', 'set_margin': 'set structure', 'total_sets': 'set structure', 'min_per_set': 'set structure', 'ten_set_no': 'set structure', 'jump_s1w': 'set structure', 'q1_lead': 'quarter structure — football and racquet sports have no quarters', 'q1_margin': 'quarter structure', 'q1_tot': 'quarter structure', 'q1_total': 'quarter structure', 'q1_fav': 'quarter structure', 'seg_wins': 'quarter structure', 'q4_moneyline': 'quarter structure', 'ebb_qhalf_b': 'quarter structure', 'ebb_q1_margin': 'quarter structure', 'first_goal_prog': 'goal event — racquet sports score points, not goals', 'minute_fgs': 'goal event', 'fgs_side': 'goal event', 'fgs_fav_or_underdog': 'goal event', 'early_first_goal': 'goal event', 'total_goals_handicap': 'goals market — no goals market in racquet sports', 'tg_under_result': 'goals market', 'tg_over_result': 'goals market', 'minute': 'wall clock — tennis, tabletennis and esports have no clock', 'ten_mins': 'wall clock', 'league_minutes': 'wall clock'}
laz_everything__FAMILY = {'football': 'goal', 'efootball': 'goal', 'efbig': 'goal', 'basketball': 'quarter', 'ebasketball': 'quarter', 'tennis': 'set', 'tabletennis': 'set', 'etennis': 'set', 'esports': 'objective'}

def laz_everything__transferable(term, sport):
    """(ok, reason). A term is transferable unless its meaning depends on a
    structure this sport does not have."""
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    fam = laz_everything__FAMILY.get(sp, 'goal')
    t = str(term).lower()
    r = laz_everything__NON_TRANSFERABLE.get(t)
    if r is None:
        return (True, 'universal quantity')
    if 'set structure' in r and fam == 'set':
        return (True, 'native to this sport')
    if 'quarter structure' in r and fam == 'quarter':
        return (True, 'native to this sport')
    if ('goal event' in r or 'goals market' in r) and fam == 'goal':
        return (True, 'native to this sport')
    if 'wall clock' in r and fam in ('goal', 'quarter'):
        return (True, 'this sport has a clock')
    return (False, r)

def laz_everything__adapt_report(sport, pool, log=None):
    """What was adapted into this sport's pool and what was refused, with the
    reason for each refusal. Returned as a frame so it reaches the workbook."""
    rows = []
    for t in sorted(set(list(pool) + list(laz_everything__NON_TRANSFERABLE))):
        ok, why = laz_everything__transferable(t, sport)
        rows.append(dict(sport=sport, term=t, in_pool=bool(t in pool), transferable=ok, reason=why, status='adapted' if ok and t in pool else 'refused' if not ok else 'transferable but absent'))
    R = pd.DataFrame(rows)
    if log:
        a = int((R.status == 'adapted').sum())
        r = int((R.status == 'refused').sum())
        m = int((R.status == 'transferable but absent').sum())
        log(f'[adapt] {sport}: {a} adapted · {r} refused (sport structure) · {m} transferable but not built')
        for _, x in R[R.status == 'refused'].head(6).iterrows():
            log(f'[adapt]   refused {x.term}: {x.reason}')
    return R
laz_everything__FULL_DERIVED = {'leader_odds_rt': lambda C, M: np.where(C['sd'] > 0, C['ho'], np.where(C['sd'] < 0, C['ao'], np.nan)), 'loser_odds_rt': lambda C, M: np.where(C['sd'] > 0, C['ao'], np.where(C['sd'] < 0, C['ho'], np.nan)), 'leader_price': lambda C, M: np.where(C['sd'] > 0, C['ho'], np.where(C['sd'] < 0, C['ao'], np.nan)), 'trailer_price': lambda C, M: np.where(C['sd'] > 0, C['ao'], np.where(C['sd'] < 0, C['ho'], np.nan)), 'fav_odds_rt': lambda C, M: np.minimum(C['ho'], C['ao']), 'dog_odds_rt': lambda C, M: np.maximum(C['ho'], C['ao']), 'is_favorite': lambda C, M: (np.where(C['sd'] > 0, C['ho'], C['ao']) <= np.where(C['sd'] > 0, C['ao'], C['ho'])).astype(float), 'is_favourite': lambda C, M: (np.where(C['sd'] > 0, C['ho'], C['ao']) <= np.where(C['sd'] > 0, C['ao'], C['ho'])).astype(float), 'lead_is_dog': lambda C, M: (np.where(C['sd'] > 0, C['ho'], C['ao']) > np.where(C['sd'] > 0, C['ao'], C['ho'])).astype(float), 'fb_prog': lambda C, M: C['el'], 'ef_prog': lambda C, M: C['el'], 'tt_prog': lambda C, M: C['el'], 'bb_prog': lambda C, M: C['el'], 'remain': lambda C, M: 1.0 - C['el'], 'time_left': lambda C, M: 1.0 - C['el'], 'q': lambda C, M: np.where(np.isfinite(C['el']), np.clip(np.nan_to_num(C['el'] * 4, nan=0).astype(int) + 1, 1, 4), np.nan).astype(float), 'period': lambda C, M: np.where(np.isfinite(C['el']), np.clip(np.nan_to_num(C['el'] * 4, nan=0).astype(int) + 1, 1, 4), np.nan).astype(float), 'half': lambda C, M: np.where(np.isfinite(C['el']), np.where(C['el'] < 0.5, 1.0, 2.0), np.nan), 'imbal': lambda C, M: np.abs(C['sd']) / np.maximum(C['tot'], 1.0), 'ht_diff': lambda C, M: C['sd'], 'margin_rate': lambda C, M: C['sd'] / np.maximum(C['el'], 0.02), 'score_rate': lambda C, M: C['tot'] / np.maximum(C['el'], 0.02), 'both_scored': lambda C, M: ((C['hs'] > 0) & (C['as_'] > 0)).astype(float), 'clean_sheet': lambda C, M: ((C['hs'] == 0) | (C['as_'] == 0)).astype(float), 'imp_home': lambda C, M: 1.0 / np.where(C['ho'] > 1, C['ho'], np.nan), 'imp_away': lambda C, M: 1.0 / np.where(C['ao'] > 1, C['ao'], np.nan), 'imp_sum': lambda C, M: 1.0 / np.where(C['ho'] > 1, C['ho'], np.nan) + 1.0 / np.where(C['ao'] > 1, C['ao'], np.nan), 'price_gap': lambda C, M: np.abs(C['ho'] - C['ao']), 'price_rank_in_match': lambda C, M: (lambda u: laz_everything___rank_in_match(u, M))(np.where(C['sd'] >= 0, C['ho'], C['ao'])), 'opp_velocity': lambda C, M: laz_everything___diff_in_match(np.where(C['sd'] >= 0, C['ao'], C['ho']), M), 'u_velocity': lambda C, M: laz_everything___diff_in_match(np.where(C['sd'] >= 0, C['ho'], C['ao']), M), 'lead_vs_line': lambda C, M: C['sd'] - C['line'], 'need_vs_expected': lambda C, M: C['line'] - C['tot'] - C['tot'] / np.maximum(C['el'], 0.02) * (1 - C['el']), 'tot_vs_line': lambda C, M: C['tot'] - C['line'], 'line_gap': lambda C, M: np.abs(C['line'] - C['tot'])}

def laz_everything___rank_in_match(v, M):
    s = pd.Series(np.asarray(v, float))
    return s.groupby(M).expanding().rank(pct=True).reset_index(level=0, drop=True).sort_index().values

def laz_everything___diff_in_match(v, M):
    return pd.Series(np.asarray(v, float)).groupby(M).diff().fillna(0.0).values

def laz_everything___ctx_full(d, ctx):
    """The context FULL_DERIVED builders read — factored out so the startup truncation guard
    can rebuild any of them on a truncated sample with the same inputs."""
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else np.full(len(d), np.nan)
    hs, as_ = (num('h_score'), num('a_score'))
    line = num('total_goals_handicap') if 'total_goals_handicap' in d.columns else num('total_points_handicap') if 'total_points_handicap' in d.columns else np.full(len(d), np.nan)
    el = np.asarray(ctx.get('el'), float) if isinstance(ctx, dict) and ctx.get('el') is not None else np.full(len(d), np.nan)
    return dict(el=el, hs=hs, as_=as_, sd=hs - as_, tot=hs + as_, ho=num('home_odds'), ao=num('away_odds'), do=num('draw_odds'), line=line)

def laz_everything__build_full(d, ctx, pool=None, sport=None, log=None):
    """Every derivable term the stacks demand. Reports what it cannot build."""
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else np.full(len(d), np.nan)
    C = laz_everything___ctx_full(d, ctx)
    M = d['match_id'].values
    out = {}
    skipped = []
    for name, fn in laz_everything__FULL_DERIVED.items():
        if pool is not None and name in pool:
            continue
        try:
            v = np.asarray(fn(C, M), float)
            if np.isfinite(v).sum() > 100:
                out[name] = v
            else:
                skipped.append((name, 'no finite values on this frame'))
        except Exception as e:
            skipped.append((name, f'{type(e).__name__}: {str(e)[:40]}'))
    if log:
        log(f'[full] +{len(out)} derived terms for {sport}')
        if skipped:
            log(f'[full] not buildable here: {[n for n, _ in skipped][:8]}')
    return (out, skipped)
