def laz_recovered__load(path=laz_recovered__PATH):
    """Every strategy with a condition stack, from BOTH sources.

    MASTER_INDEX is authoritative: 1,789 strategies, each carrying its stack,
    its source LINE, how it was built and which container it was written into.
    It reaches four populations the registry never did:

        LIVE              463  already returned by laz_registry()
        CONTAINER ONLY    596  no name/sport key, so the registry sweep skips it
        PLACEMENT BOOK    717  CSV text after the last executable statement —
                               invisible to any namespace walk
        UNREACHABLE        13  MLQ03-MLQ15, container rebound at line 89,344,
                               including MLQ05 annotated "BEST RISK PROFILE"

    The recovered-container set is merged under it for anything it misses.
    """
    if not laz_recovered___CACHE:
        for _t in (laz_recovered__BOOK_STACKS_JSON_TXT, laz_recovered__MASTER_INDEX_JSON_TXT, laz_recovered__RECOVERED_JSON_TXT):
            for _k, _v in json.loads(_t).items():
                laz_recovered___CACHE.setdefault(_k, _v)
        for _k, _v in json.loads(laz_recovered__PRODUCTION_JSON_TXT).items():
            laz_recovered___CACHE[_k] = _v
        if os.path.exists(laz_recovered__MASTER_INDEX):
            laz_recovered___CACHE.update(_laz_json_read(laz_recovered__MASTER_INDEX))
        if os.path.exists(path):
            for k, v in _laz_json_read(path).items():
                laz_recovered___CACHE.setdefault(k, v)
        if os.path.exists(laz_recovered__BOOK_STACKS):
            for k, v in _laz_json_read(laz_recovered__BOOK_STACKS).items():
                v = dict(v)
                v.setdefault('sport', None)
                laz_recovered___CACHE.setdefault(k, v)
        if os.path.exists(laz_recovered__PRODUCTION):
            for k, v in _laz_json_read(laz_recovered__PRODUCTION).items():
                v = dict(v)
                v['sport'] = v.get('sport', 'efootball')
                laz_recovered___CACHE[k] = v
    return laz_recovered___CACHE

def laz_recovered__terms_of(strategy):
    """The bare condition terms, comparator and threshold stripped."""
    out = []
    for c in strategy.get('conditions') or []:
        t = re.split('\\s*(?:>=|<=|>|<|==|!=)\\s*', str(c))[0].strip()
        if t:
            out.append(t)
    return out

def laz_recovered__is_lookahead(strategy):
    """Terms that make a strategy UNSAFE — not merely time-gated.

    q1_lead and friends are legal CONDITIONS. They cannot be mixed with a tick
    that has not reached the end of the first quarter, but that is a GATE on
    elapsed time, not a reason to discard the strategy. The engine already
    rejects an early-armed bet per-bet in verify_chain, so excluding them at
    registry level threw away 32 legitimate strategies to avoid a problem that
    was already solved downstream.

    Returns terms that are genuinely unknowable at any tick — settlement.
    """
    CG = _m('causality_guard')
    bad = []
    for x in laz_recovered__terms_of(strategy):
        xl = str(x).lower()
        if CG is not None:
            if xl in getattr(CG, 'HARD_DENY', ()) or any((p in xl for p in getattr(CG, 'DENY_SUBSTR', ()))):
                bad.append(x)
    return bad

def laz_recovered__gated_at(strategy):
    """The earliest elapsed point at which this strategy may arm, or None."""
    CG = _m('causality_guard')
    if CG is None or not hasattr(CG, 'resolves_at'):
        return None
    r = [CG.resolves_at(t) for t in laz_recovered__terms_of(strategy)]
    r = [float(x) for x in r if x and x != 'event']   # event terms carry no fixed fraction; the per-row state rule gates them
    return max(r) if r else None

def laz_recovered__by_status(status=None):
    """Filter on how a strategy is currently reachable."""
    L = laz_recovered__load()
    if status is None:
        import collections
        return collections.Counter((str(v.get('status_now', '?')).split(' —')[0] for v in L.values()))
    return {k: v for k, v in L.items() if str(v.get('status_now', '')).startswith(status)}

def laz_recovered__for_sport(sport, armable_only=True, allow_lookahead=False):
    """Every recovered strategy for a sport, with its stack."""
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    out = {}
    for n, s in laz_recovered__load().items():
        if str(s.get('sport', '')).lower() != sp:
            continue
        if armable_only and (not s.get('conditions')):
            continue
        if not allow_lookahead and laz_recovered__is_lookahead(s):
            continue
        out[n] = s
    return out

def laz_recovered__build_mask(strategy, pool):
    """Apply a recovered condition stack to a pool. Returns (mask, unresolved).

    Unresolved terms are REPORTED, never silently dropped — a stack applied
    with a missing term is a different strategy than the one recorded.
    """
    if not pool:
        return (None, ['empty pool'])
    n = len(next(iter(pool.values())))
    m = np.ones(n, bool)
    un = []
    for c in strategy.get('conditions') or []:
        mm = re.match('^\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*(>=|<=|>|<|==|!=)\\s*(-?[\\d.eE+]+)\\s*$', str(c))
        if not mm:
            un.append(str(c))
            continue
        term, op, val = (mm.group(1), mm.group(2), float(mm.group(3)))
        v = pool.get(term)
        if v is None:
            un.append(term)
            continue
        v = np.asarray(v, float)
        with np.errstate(invalid='ignore'):
            r = v >= val if op == '>=' else v <= val if op == '<=' else v > val if op == '>' else v < val if op == '<' else v == val if op == '==' else v != val
        m &= np.nan_to_num(r, nan=False).astype(bool)
    return (m, un)

def laz_recovered__coverage(pool, sport=None):
    """How many recovered stacks this pool can actually apply."""
    rows = []
    for n, s in laz_recovered__for_sport(sport, allow_lookahead=True).items() if sport else laz_recovered__load().items():
        m, un = laz_recovered__build_mask(s, pool)
        rows.append(dict(name=n, sport=s.get('sport'), family=s.get('family'), terms=len(laz_recovered__terms_of(s)), unresolved=len(un), applies=len(un) == 0, bets=int(m.sum()) if m is not None and (not un) else 0, recorded_wr=s.get('wr'), recorded_odds=s.get('odds'), recorded_roi=s.get('roi'), lookahead='|'.join(laz_recovered__is_lookahead(s)) or None))
    return pd.DataFrame(rows)

def laz_recovered__register(reg=None, log=print):
    """Attach every recovered strategy to laz_registry as a named stack."""
    reg = reg or _m('laz_registry')
    if reg is None:
        return 0
    if not hasattr(reg, 'RECOVERED'):
        reg.RECOVERED = {}
    n = 0
    la = 0
    for name, s in laz_recovered__load().items():
        bad = laz_recovered__is_lookahead(s)
        reg.RECOVERED[name] = dict(conditions=s.get('conditions') or [], terms=laz_recovered__terms_of(s), sport=s.get('sport'), family=s.get('family'), container=s.get('container'), recorded=dict(n=s.get('n'), wr=s.get('wr'), odds=s.get('odds'), roi=s.get('roi'), ci=s.get('ci'), perm_p=s.get('p'), dd=s.get('dd')), lookahead_terms=bad or None, lookahead_risk='resolves_at 0.25 — not known before Q1 ends' if bad else None, armable_before_q1=not bad)
        n += 1
        la += bool(bad)
    log(f'  [recovered] {n} strategies registered · {la} flagged for Q1 lookahead · sports {sorted({str(v['sport']) for v in reg.RECOVERED.values()})}')
    return n
