laz_registry___SEED_PATH = __import__('os').path.join(laz_registry___laz_home(), 'legacy_seeds.json')

def laz_registry__legacy_seeds(base=None):
    if not _os.path.exists(laz_registry___SEED_PATH):
        return {}
    d = _laz_json_read(laz_registry___SEED_PATH)
    if base is None:
        return d
    return [p for p in d['specs'] if p.get('base_hint') == base]

def laz_registry__author_cuts(param=None):
    """The values years of engine development chose. Test these FIRST."""
    if not _os.path.exists(laz_registry___SEED_PATH):
        return {}
    d = _laz_json_read(laz_registry___SEED_PATH)['cut_points']
    return d.get(param, []) if param else d

def laz_registry__seed_thresholds(feature_like):
    """Author cut points relevant to a feature, mapped by name."""
    c = laz_registry__author_cuts()
    f = str(feature_like).lower()
    out = []
    if 'odd' in f or 'price' in f or f.startswith('_o'):
        out += c.get('odds_min', []) + c.get('odds_hi', []) + c.get('thr', [])
    if 'minute' in f or 'prog' in f or 'frac' in f:
        out += c.get('minute_max', []) + c.get('minute_min', [])
    if 'dog' in f:
        out += c.get('pm_dog_min', [])
    if 'goal' in f or 'pair' in f:
        out += c.get('pair_g5_max', []) + c.get('gap_abs', [])
    if 'band' in f:
        out += c.get('band_lo', []) + c.get('band_hi', [])
    return sorted(set(out))

def laz_registry__bases_for(sport, include_blocked=False):
    return {k: v for k, v in laz_registry__BASES.items() if (v['sports'] == 'all' or sport in v['sports']) and (include_blocked or 'blocked_by' not in v)}

def laz_registry__factories_for(sport):
    return {k: v for k, v in laz_registry__FACTORIES.items() if v['sports'] == 'all' or sport in v['sports']}

def laz_registry__markets_for(sport, allow_untested=False):
    ok = {'CLEARED'} | ({'UNTESTED'} if allow_untested else set())
    return {k: v for k, v in laz_registry__MARKETS.items() if v['status'] in ok}

def laz_registry__coverage(sport):
    return dict(sport=sport, bases=len(laz_registry__bases_for(sport)), factories=len(laz_registry__factories_for(sport)), markets_cleared=len(laz_registry__markets_for(sport)), markets_blocked=sum((1 for v in laz_registry__MARKETS.values() if v['status'] == 'BLOCKED')))
laz_registry__RECOVERED = {}

def laz_registry__recovered_for(sport, allow_lookahead=False):
    """Recovered stacks for a sport, lookahead-flagged ones excluded by default."""
    out = {}
    for k, v in laz_registry__RECOVERED.items():
        if str(v.get('sport', '')).lower() != str(sport).lower():
            continue
        if not allow_lookahead and v.get('lookahead_terms'):
            continue
        out[k] = v
    return out
