def laz_promote___path():
    OW = _m('laz_owner')
    d = (OW.LAZ_OWNER.get('paths', {}) or {}).get('output_dir') if OW else None
    return os.path.join(d or os.getcwd(), laz_promote__STORE)

def laz_promote__load(path=None):
    p = path or laz_promote___path()
    if not os.path.exists(p):
        try:
            return json.loads(laz_promote__PROMOTED_TXT)
        except Exception:
            return {}
    try:
        return _laz_json_read(p)
    except Exception:
        return {}

def laz_promote__terms_in(conditions):
    out = []
    for c in str(conditions).split(' AND '):
        m = re.match('^\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*(>=|<=|>|<|==|!=)', c.strip())
        if m:
            out.append(m.group(1))
    return out

def laz_promote___known(term):
    """A manufactured term, whether short-form from this run or long-form from
    any earlier one. Registers long names on sight so they become promotable."""
    CR = _m('laz_corr')
    if CR is None:
        return None
    t = (getattr(CR, 'SHORT_TO_LONG', {}) or {}).get(term)
    if t is not None:
        return t
    if str(term).startswith('X_') and hasattr(CR, 'register_long'):
        if CR.register_long(term):
            return (getattr(CR, 'SHORT_TO_LONG', {}) or {}).get(term)
    return None

def laz_promote___ancestry(term, depth=0, seen=None, log=None):
    """Every ancestor of a manufactured term, to primitives.

    Returns (ancestors, ok, reason). ok=False means the lineage could not be
    resolved, which is a REFUSAL — not a pass.
    """
    CR = _m('laz_corr')
    seen = seen or set()
    if term in seen:
        return ([], False, f'cycle in parentage at {term}')
    if depth > 12:
        return ([], False, f'parentage deeper than 12 at {term}')
    seen = seen | {term}
    trip = laz_promote___known(term)
    if trip is None:
        return ([term], True, 'primitive or base condition')
    a, b, op = trip
    aa, ok1, r1 = laz_promote___ancestry(a, depth + 1, seen, log)
    bb, ok2, r2 = laz_promote___ancestry(b, depth + 1, seen, log)
    if not ok1:
        return ([], False, r1)
    if not ok2:
        return ([], False, r2)
    return ([term] + aa + bb, True, 'resolved')

def laz_promote___is_settlement(term):
    CG = _m('causality_guard')
    if CG is None:
        return False
    t = str(term).lower()
    return t in getattr(CG, 'HARD_DENY', ()) or any((p in t for p in getattr(CG, 'DENY_SUBSTR', ())))

def laz_promote___resolves(term):
    LA = _m('laz_lookahead')
    if LA is None:
        return None
    try:
        return LA.resolves_at(term)
    except Exception:
        return None

def laz_promote__vet(term, log=None):
    """(ok, record, reason). A promoted term must survive every check here."""
    CR = _m('laz_corr')
    trip = laz_promote___known(term)
    if trip is None:
        return (False, None, 'not a manufactured term')
    a, b, op = trip
    anc, ok, why = laz_promote___ancestry(term, log=log)
    if not ok:
        return (False, None, f'REFUSED: {why}')
    bad = [x for x in anc if laz_promote___is_settlement(x)]
    if bad:
        return (False, None, f'REFUSED: settlement ancestor {bad[:3]}')
    ra, rb = (laz_promote___resolves(a), laz_promote___resolves(b))
    if 'event' in (str(ra), str(rb)):
        res = 'event'
    else:
        vals = [v for v in (ra, rb) if isinstance(v, (int, float))]
        if len(vals) < 2:
            return (False, None, f'REFUSED: parent resolution unknown ({a}={ra}, {b}={rb})')
        res = max(vals)
    FORM = {'__minus__': f'{a} - {b}', '__over__': f'np.where(np.abs({b})>1e-9, {a}/{b}, np.nan)', '__x__': f'{a} * {b}'}
    OPN = {'__minus__': 'difference', '__over__': 'ratio', '__x__': 'product'}
    prim = sorted({x for x in anc if (getattr(CR, 'SHORT_TO_LONG', {}) or {}).get(x) is None})
    return (True, dict(element=term, kind='manufactured (promoted)', operator=OPN[op], parent_a=a, parent_b=b, arithmetic=FORM[op], meaning=f'the {OPN[op]} of {a} and {b}', primitives='|'.join(prim), ancestry='|'.join(sorted(set(anc))), resolves_at=res, causality=f'inherits the LATER parent — not knowable before {res} elapsed' if res else 'live at every tick', order=2 if str(term).startswith('ix2') else 1), 'promoted')

def laz_promote__promote(book, sport=None, log=print, path=None):
    """Persist every manufactured term used by an accepted strategy."""
    p = path or laz_promote___path()
    store = laz_promote__load(p)
    added = 0
    refused = []
    if book is None or not len(book):
        return (store, 0, [])
    col = 'conditions' if 'conditions' in book.columns else None
    if col is None:
        return (store, 0, [])
    used = {}
    for _, r in book.iterrows():
        for t in laz_promote__terms_in(r[col]):
            if str(t).startswith(('ix_', 'ix2_', 'X_')):
                used.setdefault(t, []).append(str(r.get('strategy_name') or ''))
    for t, by in used.items():
        if t in store:
            store[t].setdefault('used_by', [])
            store[t]['used_by'] = sorted(set(store[t]['used_by'] + by))[:20]
            continue
        ok, rec, why = laz_promote__vet(t, log=log)
        if not ok:
            refused.append((t, why))
            continue
        anc, aok, _ = laz_promote___ancestry(t)
        for x in anc:
            if x == t or x in store or laz_promote___known(x) is None:
                continue
            xok, xrec, _ = laz_promote__vet(x, log=None)
            if xok:
                xrec.update(sport=sport, used_by=[f'ancestor of {t}'], first_seen=pd.Timestamp.now('UTC').strftime('%Y-%m-%d'))
                store[x] = xrec
                added += 1
        rec.update(sport=sport, used_by=sorted(set(by))[:20], first_seen=pd.Timestamp.now('UTC').strftime('%Y-%m-%d'))
        store[t] = rec
        added += 1
    try:
        with open(p, 'w') as f:
            json.dump(store, f, indent=1)
    except Exception as e:
        if log:
            log(f'[promote] write failed: {type(e).__name__}: {e}')
    if log:
        log(f'[promote] {len(used)} manufactured terms in accepted chains · +{added} promoted · {len(refused)} refused · store now {len(store)}')
        for t, w in refused[:5]:
            log(f'[promote]   {t}: {w}')
        for t in list(store)[-3:]:
            r = store[t]
            log(f'[promote]   kept {t} = {r['arithmetic'][:60]} · resolves_at {r['resolves_at']}')
    return (store, added, refused)

def laz_promote__rebuild(pool, d=None, ctx=None, log=None):
    """Rebuild every promoted term into a pool, deepest parent first.

    A promoted term is only usable if BOTH its parents can be rebuilt, so the
    store is walked by order: first-order terms first, then second.
    """
    store = laz_promote__load()
    if not store:
        return {}
    built = {}
    missing = []
    for order in (1, 2, 3):
        for t, r in store.items():
            if r.get('order') != order or t in pool or t in built:
                continue
            a, b = (r['parent_a'], r['parent_b'])
            va = pool.get(a, built.get(a))
            vb = pool.get(b, built.get(b))
            if va is None or vb is None:
                missing.append((t, f'parent absent: {(a if va is None else b)}'))
                continue
            A = np.asarray(va, float)
            B = np.asarray(vb, float)
            op = r['operator']
            with np.errstate(divide='ignore', invalid='ignore'):
                v = A - B if op == 'difference' else A * B if op == 'product' else np.where(np.abs(B) > 1e-09, A / B, np.nan)
            if np.isfinite(v).sum() > 100:
                built[t] = v
        pool = {**pool, **built}
    if log:
        log(f'[promote] rebuilt {len(built)} promoted conditions from the store' + (f' · {len(missing)} could not be rebuilt' if missing else ''))
        for t, w in missing[:3]:
            log(f'[promote]   {t}: {w}')
    return built

def laz_promote__audit(book, pool_keys=None, log=print):
    """CAN EVERY LEG ACTUALLY BE REBUILT? Answered per leg, not asserted.

    For each strategy: take every term in its chain, resolve it to primitives
    through the promotion store and the genome, and report any term whose
    lineage dies. A leg that cannot be rebuilt is not a strategy you can bet —
    it is a threshold against a name nothing can compute.

    This is the check to run before trusting a book in production.
    """
    store = laz_promote__load()
    GN = _m('laz_genome')
    CR = _m('laz_corr')
    base = set(pool_keys or [])
    if GN is not None:
        GN.bootstrap()
        base |= set(getattr(GN, 'GENOME', {}) or {})
    rows = []
    for _, r in (book if book is not None else pd.DataFrame()).iterrows():
        terms = laz_promote__terms_in(r.get('conditions', ''))
        missing = []
        for t in terms:
            if t in base or t in store:
                continue
            if laz_promote___known(t) is not None:
                anc, ok, why = laz_promote___ancestry(t)
                gaps = [x for x in anc if x not in base and x not in store and (laz_promote___known(x) is None)]
                if not ok:
                    missing.append(f'{t}: {why}')
                elif gaps:
                    missing.append(f'{t}: ancestor absent {gaps[:2]}')
                continue
            missing.append(f'{t}: no source')
        rows.append(dict(strategy_name=r.get('strategy_name'), n_terms=len(terms), rebuildable=not missing, missing='; '.join(missing)[:200], conditions=str(r.get('conditions'))[:160]))
    A = pd.DataFrame(rows)
    if log and len(A):
        ok = int(A.rebuildable.sum())
        log(f'[audit] {ok}/{len(A)} legs fully rebuildable from the shipped files')
        bad = A[~A.rebuildable]
        for _, x in bad.head(5).iterrows():
            log(f'[audit]   {x.strategy_name}: {x.missing[:110]}')
        if len(bad) > 5:
            log(f'[audit]   ... {len(bad) - 5} more')
    return A

def laz_promote___primitives_of(rec, store, _memo=None, _path=None):
    """Every frame column this recipe ultimately rests on.

    [v220 fix P2] memoized + cycle-guarded. The ix2/ix3 chains share subtrees
    heavily; the un-memoized re-walk is EXPONENTIAL in shared depth - observed as a
    12-hour hang after efootball batch 1 (combine -> transfer -> transferable ->
    this walk, 16 Sep 2026). The per-call memo makes it linear; the path set also
    refuses a cyclic store instead of looping. Pure set-union: output identical."""
    if _memo is None:
        _memo = {}
    if _path is None:
        _path = set()
    out = set(str(rec.get('primitives') or '').split('|')) - {''}
    for parent in (rec.get('parent_a'), rec.get('parent_b')):
        if not parent or parent in _path:
            continue
        if parent in _memo:
            out |= _memo[parent]
        elif parent in store:
            _path.add(parent)
            _sub = laz_promote___primitives_of(store[parent], store, _memo, _path)
            _path.discard(parent)
            _memo[parent] = _sub
            out |= _sub
        else:
            out.add(parent)
    return out

def laz_promote__transferable(term, pool, sport, store=None, log=None):
    """(ok, reason) — can this recipe be rebuilt from THIS sport's pool?

    The test is mechanical: every primitive the recipe needs must be present.
    No name list, no sport whitelist — the lineage either lands or it does not.
    """
    store = store if store is not None else laz_promote__load()
    rec = store.get(term)
    if rec is None:
        return (False, 'not in the promotion store')
    GN = _m('laz_genome')
    have = set(pool)
    prim = laz_promote___primitives_of(rec, store)
    missing = sorted((p for p in prim if p not in have))
    if missing:
        if GN is not None:
            still = []
            for p_ in missing:
                ok, why = GN.applies(p_, sport)
                if not ok:
                    return (False, f'{p_} not applicable: {why[:70]}')
                still.append(p_)
            if still:
                return (False, f'primitives absent from this frame: {still[:3]}')
        else:
            return (False, f'primitives absent: {missing[:3]}')
    return (True, 'every primitive present')

def laz_promote__transfer(pool, sport, log=None):
    """Rebuild every promoted recipe this sport can support, wherever it came
    from. Returns (built, report). Each carries origin_sport so a strategy
    using a foreign-origin term stays visible."""
    store = laz_promote__load()
    if not store:
        return ({}, {})
    M5 = _m('laz_mode5')
    built = {}
    refused = []
    native = 0
    foreign = 0
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    for order in (1, 2, 3):
        for t, rec in store.items():
            if rec.get('order') != order or t in pool or t in built:
                continue
            ok, why = laz_promote__transferable(t, {**pool, **built}, sp, store, log=None)
            if not ok:
                refused.append((t, rec.get('sport'), why))
                continue
            a, b = (rec['parent_a'], rec['parent_b'])
            va = pool.get(a, built.get(a))
            vb = pool.get(b, built.get(b))
            if va is None or vb is None:
                refused.append((t, rec.get('sport'), f'parent not yet built: {(a if va is None else b)}'))
                continue
            A = np.asarray(va, float)
            B = np.asarray(vb, float)
            op = rec['operator']
            with np.errstate(divide='ignore', invalid='ignore'):
                v = A - B if op == 'difference' else A * B if op == 'product' else np.where(np.abs(B) > 1e-09, A / B, np.nan)
            if np.isfinite(v).sum() <= 100:
                refused.append((t, rec.get('sport'), 'built but fewer than 100 finite values here'))
                continue
            built[t] = v
            if str(rec.get('sport')) == sp:
                native += 1
            else:
                foreign += 1
                if M5 is not None:
                    M5.remember(dict(kind='transfer', sport=sp, origin_sport=rec.get('sport'), tried=t, why="recipe rebuilt from this sport's own primitives", arithmetic=rec.get('arithmetic'), expected='must clear the gate here on its own data'))
        pool = {**pool, **built}
    if log:
        log(f'[transfer] {sport}: {len(built)} recipes rebuilt · {native} native · {foreign} from other sports · {len(refused)} refused')
        for t, src, why in refused[:4]:
            log(f'[transfer]   {t} (from {src}): {why[:80]}')
        for t in list(built)[:3]:
            r = store[t]
            log(f'[transfer]   {t} <- {r.get('sport')} :: {r['arithmetic'][:60]}')
    return (built, dict(native=native, foreign=foreign, refused=refused))
# ==========================================================================
# LAZ_BRAIN MODULE: laz_transfer
# §laz_transfer   <- grep this anchor to land here
# OBJECTIVE : CONDITION ADAPTATION ACROSS SPORTS
# PURPOSE   : 24 universal concepts buildable in any scoring sport, transferring the MECHANISM never the column.
# HOW       : u_remain, u_margin_rate, u_pace, u_since_score, u_drift, u_vf, u_time_in_lead and 17 more, each derived from whatever clock and score the frame carries. NON_TRANSFERABLE refuses ht_*/q1_*/set1_* rather than faking an analogue.
# VALUE     : tennis and tabletennis were judged with 5-7 conditions against football's 24, and eTennis with NONE — so 'no edge' was never a fair test. Adding these produced tabletennis 89.1% and tennis 76.2% where four earlier methods found nothing. u_margin_rate (margin per unit of time remaining) underpins SIX of the top eleven strategies in the final book, including eFootball at 93.7%.
# IF SKIPPED: A sport without a vocabulary reads identically to a sport without an edge.
# ==========================================================================
"""laz_transfer.py — ADAPT CONDITIONS ACROSS SPORTS. Only what is adaptable.

THE GAP THIS CLOSES

  score_state   football 7 · efootball 14 · eBasketball 43 · tennis 0 · tabletennis 0 · etennis 0
  form_history  efootball 21 · eBasketball 29 · everything else 0
  price_motion  one condition in the entire project outside eFootball

tennis and tabletennis were judged with 5-7 conditions against football's 24.
eTennis had NONE, so "no edge there" was never a fair test.

WHAT TRANSFERS AND WHAT DOES NOT

  TRANSFERABLE — the concept exists in every scoring sport, only the unit
  changes: time remaining, score margin, margin per unit of time left, time
  since the last score, price drift from open, price volatility, vig-free
  implied, favourite/underdog ratio, projected total against the line.

  NOT TRANSFERABLE — refuse these rather than fake them:
    ht_* / half-time         a tennis match has no half
    q1_lead / quarter        football has no quarters
    min_since_goal (literal) tabletennis has no goals; the ADAPTED form is
                             "points since the last score", which is different
                             and is built separately
    corner/card/possession   sport-specific events with no analogue
    set1_winner              only racquet sports have sets

  The rule: transfer the MECHANISM, never the column. `remain` in football is
  "share of match left"; in tennis it is "sets needed over sets available".
  Same idea, different arithmetic, and a wrong analogue is worse than none.
"""
import numpy as np, pandas as pd
laz_transfer__UNIVERSAL = {'u_remain': 'share of the contest still to play', 'u_elapsed': 'share already played', 'u_margin': 'score margin from the BACKED side', 'u_margin_abs': 'absolute margin', 'u_margin_rate': 'margin per unit of time remaining — decisiveness', 'u_total': 'combined score so far', 'u_pace': 'combined score per unit elapsed', 'u_since_score': 'SECONDS since the last score change (wall clock; never ticks)', 'u_drought': 'ticks since the last score, over the time remaining', 'u_price': 'live price of the backed side', 'u_price_open': 'that side price at the first valid tick', 'u_drift': 'live price over its own opening price', 'u_drift_opp': 'the same for the opposing side', 'u_drift_gap': 'backed drift minus opposing drift — who the market is leaving', 'u_trend': 'price change against the previous tick', 'u_vol': 'rolling price volatility', 'u_vf': 'vig-free implied probability of the backed side', 'u_overround': 'book overround', 'u_ratio': 'opposing price over backed price', 'u_ratio_open': 'the same at kickoff — prematch shape', 'u_ratio_shift': 'live ratio over prematch ratio', 'u_fav_backed': 'is the backed side the prematch favourite', 'u_lead_flips': 'how many times the lead has changed', 'u_time_in_lead': 'share of WALL TIME the backed side has led (never ticks)'}
laz_transfer__NON_TRANSFERABLE = ('ht_', 'q1_', 'q2_', 'q3_', 'q4_', 'half', 'quarter', 'corner', 'card', 'possession', 'set1_', 'sets_won', 'minute_fgs', 'first_goal')

def laz_transfer__transferable(name):
    n = str(name).lower()
    return not any((k in n for k in laz_transfer__NON_TRANSFERABLE))

def laz_transfer__build(d, backed_is_home, score_h='h_score', score_a='a_score', price_h='home_odds', price_a='away_odds', draw='draw_odds', elapsed=None, match='match_id', sport=None):
    """Build every universal condition this frame can support. Returns (df, names)."""
    out = {}
    H = np.asarray(backed_is_home, bool)
    num = lambda c: pd.to_numeric(d[c], errors='coerce') if c in d.columns else pd.Series(np.nan, index=d.index)
    g = d[match]
    hs, as_ = (num(score_h), num(score_a))
    ho, ao = (num(price_h), num(price_a))
    dr = num(draw)
    el = None
    try:
        _EVt = _m('laz_everything')
        if _EVt is not None and hasattr(_EVt, 'causal_elapsed'):
            _sp_t = str(sport) if sport else None
            _ce = _EVt.causal_elapsed(d, _sp_t) if _sp_t else None
            if _ce is not None:
                el = pd.Series(np.asarray(_ce, float), index=d.index)
    except Exception as _te:
        el = None
    if el is None and elapsed and (elapsed in d.columns):
        _cand = pd.to_numeric(d[elapsed], errors='coerce')
        if _cand.max() <= 1.5:
            el = _cand
    _have_clock = el is not None
    if not _have_clock:
        el = pd.Series(np.nan, index=d.index)
    el = el.clip(0, 1.2)
    out['u_elapsed'] = el.values
    out['u_remain'] = (1 - el).clip(0.01, 1).values
    mar = pd.Series(np.where(H, hs - as_, as_ - hs), index=d.index)
    out['u_margin'] = mar.values
    out['u_margin_abs'] = mar.abs().values
    out['u_margin_rate'] = (mar / (1 - el).clip(0.02, 1)).values
    tot = hs + as_
    out['u_total'] = tot.values
    out['u_pace'] = (tot / el.clip(0.02, 1)).values
    chg = tot.groupby(g).diff().fillna(0) != 0
    grp = chg.groupby(g).cumsum()
    if 'ts' in d.columns:
        _tsec = pd.to_datetime(d['ts'], errors='coerce')
        _sec = (_tsec - _tsec.groupby(g).transform('min')).dt.total_seconds()
        ss = _sec - _sec.groupby([g, grp]).transform('first')
    else:
        ss = pd.Series(np.nan, index=d.index)
    out['u_since_score'] = ss.values
    out['u_drought'] = (ss / (1 - el).clip(0.02, 1)).values
    pb = pd.Series(np.where(H, ho, ao), index=d.index)
    po = pd.Series(np.where(H, ao, ho), index=d.index)
    out['u_price'] = pb.values
    ob = pb.groupby(g).transform('first')
    oo = po.groupby(g).transform('first')
    out['u_price_open'] = ob.values
    out['u_drift'] = (pb / ob.replace(0, np.nan)).values
    out['u_drift_opp'] = (po / oo.replace(0, np.nan)).values
    out['u_drift_gap'] = (pb / ob.replace(0, np.nan) - po / oo.replace(0, np.nan)).values
    out['u_trend'] = ((pb - pb.groupby(g).shift(1)) / pb.groupby(g).shift(1).replace(0, np.nan) * 100).values
    out['u_vol'] = pb.groupby(g).transform(lambda s: s.rolling(10, min_periods=3).std()).values
    ib, io = (1 / pb, 1 / po)
    idr = (1 / dr).replace([np.inf, -np.inf], 0).fillna(0)
    out['u_vf'] = (ib / (ib + io + idr)).values
    out['u_overround'] = (ib + io + idr).values
    out['u_ratio'] = (po / pb.replace(0, np.nan)).values
    out['u_ratio_open'] = (oo / ob.replace(0, np.nan)).values
    out['u_ratio_shift'] = (po / pb.replace(0, np.nan) / (oo / ob.replace(0, np.nan)).replace(0, np.nan)).values
    out['u_fav_backed'] = (ob <= oo).astype(float).values
    sgn = np.sign(mar)
    out['u_lead_flips'] = (sgn.groupby(g).diff().fillna(0) != 0).groupby(g).cumsum().values
    if 'ts' in d.columns:
        _dt = _sec.groupby(g).diff().fillna(0.0)
        out['u_time_in_lead'] = (pd.Series(np.where(mar > 0, _dt, 0.0), index=d.index).groupby(g).cumsum() / _sec.clip(lower=1.0)).values
    else:
        out['u_time_in_lead'] = np.full(len(d), np.nan)
    keep = [k for k, v in out.items() if np.isfinite(np.asarray(v, float)[~np.isnan(np.asarray(v, float))]).all() and np.nanstd(np.asarray(v, float)) > 0]
    if keep:
        _new = pd.DataFrame({k: out[k] for k in keep}, index=d.index)
        for k in keep:
            if k in d.columns:
                d.drop(columns=[k], inplace=True)
        d = pd.concat([d, _new], axis=1)
    return (d, keep)
