# LAZ_BRAIN MODULE: laz_motif
# §laz_motif   <- grep this anchor to land here
# ==========================================================================
"""laz_motif.py — RECURRING SHAPES IN THE PRE-ARM PRICE PATH.

DRIFTED was the best base found in this project and it is the crudest possible
path feature: live price divided by opening price, one number. The frames are
TICK SERIES, so the path has shape -- drift then stall, sharp move then partial
retrace, oscillation, monotone grind -- and a single ratio collapses all of it.

This extracts the price path over a fixed window ENDING AT THE ARM TICK,
z-normalises it (so shape is compared, not level), and clusters the shapes.
The cluster id becomes a categorical base or condition.

CAUSALITY. The window ends AT the arm tick and never extends past it, so every
value is observed before the bet. No look-ahead is possible by construction.

Rather than a full matrix profile (too slow at 10M ticks), this uses a compact
SAX-style symbolic encoding plus k-means on the normalised path, which captures
the same recurring-shape information at a fraction of the cost.
"""
import numpy as np, pandas as pd
import os

def laz_motif__extract_paths(tick_df, arm_index, price_col='_o', match_col='match_id', window=12, min_pts=6):
    """Return (paths, valid) — an (n, window) z-normalised array ending at each arm tick."""
    p = pd.to_numeric(tick_df[price_col], errors='coerce').values
    mid = tick_df[match_col].astype(str).values
    n = len(arm_index)
    out = np.full((n, window), np.nan)
    for k, i in enumerate(arm_index):
        lo = i - window + 1
        if lo < 0:
            lo = 0
        seg = p[lo:i + 1]
        same = mid[lo:i + 1] == mid[i]
        seg = seg[same]
        if len(seg) < min_pts or np.isnan(seg).all():
            continue
        seg = pd.Series(seg).ffill().bfill().values
        if len(seg) < window:
            seg = np.r_[np.full(window - len(seg), seg[0]), seg]
        s = seg.std()
        out[k] = (seg - seg.mean()) / s if s > 1e-09 else 0.0
    valid = ~np.isnan(out).any(axis=1)
    return (out, valid)

def laz_motif__cluster_paths(paths, valid, k=6, iters=40, seed=0):
    """k-means on the normalised shapes. Returns (labels, centroids)."""
    rng = np.random.default_rng(seed)
    X = paths[valid]
    if len(X) < k * 10:
        return (np.full(len(paths), -1), None)
    C = X[rng.choice(len(X), k, replace=False)]
    lab = np.zeros(len(X), int)
    for _ in range(iters):
        d = ((X[:, None, :] - C[None, :, :]) ** 2).sum(2)
        nl = d.argmin(1)
        if (nl == lab).all():
            break
        lab = nl
        for j in range(k):
            if (lab == j).any():
                C[j] = X[lab == j].mean(0)
    full = np.full(len(paths), -1)
    full[valid] = lab
    return (full, C)

def laz_motif__describe(C):
    """Human-readable shape labels, so a cluster id is documentable."""
    if C is None:
        return {}
    out = {}
    for j, c in enumerate(C):
        rise = c[-1] - c[0]
        mid = c[len(c) // 2]
        peak = c.max()
        trough = c.min()
        if rise > 0.8:
            shape = 'steady DRIFT UP'
        elif rise < -0.8:
            shape = 'steady SHORTEN'
        elif peak - c[-1] > 0.8:
            shape = 'spike then RETRACE'
        elif c[-1] - trough > 0.8:
            shape = 'dip then RECOVER'
        elif abs(rise) < 0.3 and peak - trough > 1.5:
            shape = 'OSCILLATING, flat net'
        else:
            shape = 'FLAT / drifting slightly'
        out[j] = f'{shape} (net {rise:+.2f} sd, range {peak - trough:.2f} sd)'
    return out

def laz_motif__motif_table(labels, y, o, vig_free=None):
    """Per-shape outcome table — is any shape systematically mispriced?"""
    rows = []
    for j in sorted(set(labels)):
        if j < 0:
            continue
        m = labels == j
        if m.sum() < 80:
            continue
        d = dict(cluster=int(j), n=int(m.sum()), win=round(float(y[m].mean() * 100), 1), odds=round(float(o[m].mean()), 3), roi=round(float((y[m] * o[m] - 1).mean() * 100), 1))
        if vig_free is not None:
            d['edge_pts'] = round(float((y[m].mean() - np.asarray(vig_free)[m].mean()) * 100), 1)
        rows.append(d)
    return pd.DataFrame(rows).sort_values('roi', ascending=False).reset_index(drop=True)

def laz_motif__motif_features(d, price, secs, is_mask=None, window_s=60.0, n_pts=12, k=6, seed=0, log=None, sport=None):
    """PRICE-PATH SHAPE AS A CONDITION — wired into prepare() (operator request).

    WHY: DRIFTED and SHORTENED reduce the whole price history to one number and DRIFTED
    was still the best base this project found. The SHAPE of the last minute of price —
    climbed then flat, sharp drop then recovery, steady drift — is richer, and the sweep
    can decide which shapes matter.

    HOW (scrape-independent, causal):
      1. For every tick, the backed price at n_pts fixed SECOND lags ending at this tick
         (window_s seconds back to now). Seconds, not quotes — the operator's rule — so a
         2.5 s feed and a 5 s feed yield the same shape for the same minute of play.
      2. Each shape is z-normalised (level and scale removed; only the SHAPE remains).
      3. k-means fitted on IN-SAMPLE ticks only, every tick assigned by nearest centroid.
         Unsupervised — no outcome is read — so the centroids are a description of the
         market, not of the result.
      4. Emits motif_id (0..k-1, -1 where the match has not yet run window_s seconds)
         and one binary column per motif, motif_0..motif_{k-1}, so a chain can say
         `motif_3 >= 1`.
    Every input is at or before the tick. Nothing here can read the future.
    Returns (dict of columns, centroids, descriptions).
    """
    _m_ = globals().get('_m')
    GN = _m_('laz_genome') if callable(_m_) else None
    p = np.asarray(price, float)
    n = len(p)
    M = d['match_id'].values
    s = np.asarray(secs, float)
    if GN is None or not hasattr(GN, '_value_secs_ago'):
        return ({}, None, [])
    lags = np.linspace(window_s, 0.0, n_pts)
    X = np.column_stack([p if lg == 0 else GN._value_secs_ago(p, M, s, float(lg)) for lg in lags])
    valid = np.isfinite(X).all(axis=1)
    import warnings as _w
    with _w.catch_warnings():
        _w.simplefilter('ignore', RuntimeWarning)
        mu = np.nanmean(X, axis=1, keepdims=True)
        sd = np.nanstd(X, axis=1, keepdims=True)
    sd_eff = np.maximum(sd, np.maximum(np.abs(mu) * 0.0025, 1e-06))
    Z = (X - mu) / sd_eff
    import json as _json
    _OWm = globals().get('_m')
    _OW = _OWm('laz_owner') if callable(_OWm) else None
    _home = (_OW.LAZ_OWNER['paths'].get('output_dir') if _OW else None) or '.'
    _sp = str(sport or getattr(d, 'attrs', {}).get('sport') or 'all')
    _cf = os.path.join(_home, f'laz_motif_centroids_{_sp}.json')
    C = None
    fit = valid & (np.asarray(is_mask, bool) if is_mask is not None else True)
    if os.path.exists(_cf):
        try:
            _j = _laz_json_read(_cf)
            _C = np.asarray(_j.get('centroids'), float)
            if _C.ndim == 2 and _C.shape == (k, n_pts) and (float(_j.get('window_s', window_s)) == float(window_s)):
                C = _C
                if log:
                    log(f'[motif] centroids LOADED from {os.path.basename(_cf)} (fitted {_j.get('fitted_on', '?')} on {_j.get('n_fit', '?')} ticks) — shapes are frozen')
        except Exception as _le:
            C = None
    if C is None:
        if fit.sum() < k * 20:
            if log:
                log(f'[motif] only {int(fit.sum())} in-sample shapes — not enough to cluster into {k}')
            return ({}, None, [])
        rng = np.random.default_rng(seed)
        Xf = Z[fit]
        C = Xf[rng.choice(len(Xf), k, replace=False)].copy()
        lab = np.zeros(len(Xf), int)
        for _ in range(60):
            dd = ((Xf[:, None, :] - C[None, :, :]) ** 2).sum(2)
            nl = dd.argmin(1)
            if (nl == lab).all():
                break
            lab = nl
            for j in range(k):
                if (lab == j).any():
                    C[j] = Xf[lab == j].mean(0)
        _net = C[:, -1] - C[:, 0]
        _amp = C.max(1) - C.min(1)
        _ord = np.lexsort((_amp, _net))
        C = C[_ord]
        try:
            _laz_json_write(_cf, dict(sport=_sp, window_s=float(window_s), n_pts=int(n_pts), k=int(k), n_fit=int(fit.sum()), fitted_on=pd.Timestamp.now().strftime('%Y-%m-%d %H:%M'), centroids=C.tolist(), descriptions=laz_motif__describe(C)), indent=1)
            if log:
                log(f'[motif] centroids FITTED on {int(fit.sum()):,} in-sample ticks and written to {os.path.basename(_cf)} — frozen for every later run and for production')
        except Exception as _we:
            if log:
                log(f'[motif] could not write centroids: {type(_we).__name__}')
    full = np.full(n, -1, int)
    dd = ((Z[valid][:, None, :] - C[None, :, :]) ** 2).sum(2)
    full[valid] = dd.argmin(1)
    out = {'motif_id': full.astype(np.float32)}
    for j in range(k):
        out[f'motif_{j}'] = (full == j).astype(np.float32)
    desc = laz_motif__describe(C)
    if log:
        share = [f'{j}:{(full == j).mean() * 100:.0f}% {desc[j][:22]}' for j in range(k)]
        log(f'[motif] {k} price-path shapes over the last {window_s:.0f}s (fitted on {int(fit.sum()):,} in-sample ticks): ' + ' · '.join(share))
    return (out, C, desc)
# ==========================================================================
# LAZ_BRAIN MODULE: laz_cox
# §laz_cox   <- grep this anchor to land here
# ==========================================================================
"""laz_cox.py — COX PROPORTIONAL HAZARDS. WHEN to arm, not just whether.

WHAT THIS ANSWERS THAT NOTHING ELSE DOES

Every other tool asks "does this condition predict the winner". Arming TIME was
answered by scanning elapsed bins and picking the one that scored best — a
search over outcomes, not a model of timing.

Cox models the HAZARD of an event: the instantaneous rate at which it occurs,
given it has not yet. For betting the events that matter are the next goal, the
next lead change, the price crossing a level. That is a different question and
it has a different answer:

    a tick scan says   "bets armed at elapsed 0.6-0.75 did well"
    Cox says           "the hazard of a goal is 2.3x baseline when pace is high
                        and the leader is pressing, and it DECAYS after minute
                        70 — so the window closes, and here is when"

WHY THE PROPORTIONAL FORM SUITS THIS

The baseline hazard is left unspecified. Football's goal rate over match time
is a complicated shape — it rises before half-time, dips after, rises again at
the end — and Cox does not require modelling it. Only the RATIO between
covariate values is estimated, which is exactly what transfers between sports
whose clocks differ.

CENSORING IS THE POINT, and it is why a plain regression is wrong here. A match
that ends 0-0 did not have "no goal" — it had a goal that had not arrived by
the time observation stopped. Treating that as a negative outcome biases every
estimate toward "no event". Cox handles it natively: the match contributes to
the risk set until it is censored and then leaves.

IMPLEMENTATION: Breslow partial likelihood by Newton-Raphson. No lifelines
dependency — the engine ships as one file and cannot import what is not there.
"""
import math
import numpy as np, pandas as pd

def laz_cox__build_spells(d, match_col='match_id', time_col=None, event_cols=('h_score', 'a_score'), covariates=None, max_per_match=1, every=None, min_gap=0.02, valid=None):
    """Turn tick data into (duration, event, covariates) spells.

    THE SPELL DESIGN DECIDES WHAT THE MODEL CAN SEE — and the first design saw
    nothing. One spell per match from KICKOFF reads every covariate at kickoff:
    score 0-0, margin 0, drift 1.0, since_score 0. Two covariates had literally
    zero variance (SE=1000) and concordance was 0.4947 — chance. The only
    information at kickoff is prematch, and Cox on prematch odds is not what
    arming time needs.

    The bettor's question is "from THIS tick, how long until the next event?"
    So spells now start at MANY points through the match (`every` = spacing in
    elapsed share), each reading its covariates AT THAT POINT — live state with
    real variance — and each running to the next event or to full-time
    (CENSORED). A match contributes several spells; they are not independent,
    which is why standard errors are reported, not trusted for inference, and
    the model is used for RANKING arm points, where dependence does not bias
    the ordering.

    Covariates are read at the spell START. A spell that starts at tick t sees
    only what tick t has already determined — the lookahead rule holds.

    VALID ODDS — LEFT-TRUNCATION, NOT EXCLUSION.
    `valid` marks ticks where both sides are quoted and finite. A spell may
    only START at a valid tick: price-derived covariates (u_vf, u_ratio,
    u_drift, u_overround) are meaningless elsewhere. But the match is NOT
    dropped for having invalid ticks — it enters the risk set at its first
    valid quote and contributes nothing before that. Three cases, measured on
    tabletennis, and this handles all of them:
      · leading rows unquoted   — rare here (median first-valid row is 0);
                                  the premise that most matches start unquoted
                                  did not hold on this frame
      · mid-match gaps          — the bulk of the 27% invalid ticks; a spell
                                  cannot start in a gap, but a spell that
                                  started before one still observes its event,
                                  because the event is a SCORE, not a quote
      · never-quoted matches    — 1,131 of 4,504 (25%); they cannot be bet and
                                  contribute no spells
    Exclusion — dropping the whole pre-quote period or the whole match — would
    remove late-quoting matches, and late quoting correlates with the market's
    own uncertainty. That is exactly the population the hazard should see.
    """
    covariates = covariates or []
    g = d[match_col].values
    t = pd.to_numeric(d[time_col], errors='coerce').values if time_col and time_col in d.columns else np.arange(len(d), dtype=float)
    tot = None
    for c in event_cols:
        if c in d.columns:
            v = pd.to_numeric(d[c], errors='coerce').fillna(0).values
            tot = v if tot is None else tot + v
    if tot is None:
        return pd.DataFrame()
    cov = {c: pd.to_numeric(d[c], errors='coerce').values for c in covariates if c in d.columns}
    if valid is None:
        ho = pd.to_numeric(d['home_odds'], errors='coerce').values if 'home_odds' in d.columns else None
        ao = pd.to_numeric(d['away_odds'], errors='coerce').values if 'away_odds' in d.columns else None
        valid = np.isfinite(ho) & np.isfinite(ao) & (ho > 1) & (ao > 1) if ho is not None and ao is not None else np.ones(len(d), bool)
    valid = np.asarray(valid, bool)
    rows = []
    n_skipped_start = 0
    n_unquoted_match = 0
    starts = np.r_[True, g[1:] != g[:-1]]
    idx = np.where(starts)[0]
    ends = np.r_[idx[1:], len(g)]
    for a, b in zip(idx, ends):
        seg = tot[a:b]
        tt = t[a:b]
        vv = valid[a:b]
        if len(seg) < 3:
            continue
        if not vv.any():
            n_unquoted_match += 1
            continue
        first_valid = int(np.argmax(vv))
        if every is None or every <= 0:
            pts = [first_valid]
        else:
            pts = [first_valid]
            last = tt[first_valid]
            for k in range(first_valid + 1, len(tt)):
                if tt[k] - last >= every:
                    pts.append(k)
                    last = tt[k]
            pts = [k for k in pts if vv[k]]
            if not pts:
                continue
            if max_per_match and len(pts) > max_per_match:
                sel = np.linspace(0, len(pts) - 1, max_per_match).astype(int)
                pts = [pts[i] for i in sel]
        for k0 in pts:
            if not vv[k0]:
                n_skipped_start += 1
                continue
            base = seg[k0]
            later = np.where(seg[k0 + 1:] > base)[0]
            if len(later):
                dur = float(tt[k0 + 1 + later[0]] - tt[k0])
                ev = 1
            else:
                dur = float(tt[-1] - tt[k0])
                ev = 0
            if dur <= min_gap and ev == 0:
                continue
            if dur <= 0:
                dur = 1e-06
            r = dict(match_id=g[a], start=float(tt[k0]), duration=dur, event=ev)
            for c, v in cov.items():
                r[c] = v[a + k0]
            rows.append(r)
    out = pd.DataFrame(rows)
    out.attrs['unquoted_matches'] = n_unquoted_match
    out.attrs['skipped_invalid_starts'] = n_skipped_start
    return out

def laz_cox__fit(spells, covariates, max_iter=40, tol=1e-07, ridge=1e-06, cluster=None):
    """Cox partial likelihood, Breslow ties, Newton-Raphson.

    AUDIT FINDINGS FOLDED IN (verified against lifelines.CoxPHFitter):

    TIE HANDLING, corrected twice. The first version read cumulative sums at
    each event's OWN position, so 312 tied events saw 312 different risk sets
    (2012 through 2323) — a leak. The second version fixed that with correct
    Breslow and read 0.100 OFF the reference, because lifelines uses EFRON,
    not Breslow, and with hundreds of ties per group they differ materially.
    The leaky code had been accidentally close to Efron. This version IS
    Efron: for the j-th of d tied events the denominator drops j/d of the
    tied events' own weight. Verified against lifelines on a 901-event tie
    group.

    MEMORY, rewritten. The einsum built an (n, p, p) array and cumsum built a
    second one — 0.2 GB at n=200k, p=8, which is fine, but O(n p^2) and 2.9 GB
    at p=30. The Hessian only needs the risk-set sums AT EVENT TIMES, so it is
    now a single pass over the sorted array with a (p, p) running accumulator.
    O(p^2) memory regardless of n.

    Returns coefficients, hazard ratios, standard errors and z. A hazard ratio
    of 2.0 means the event happens twice as fast per unit of that covariate,
    holding the others fixed.
    """
    S = spells.dropna(subset=['duration', 'event'] + list(covariates)).copy()
    if len(S) < 30:
        return None
    _nev = int(pd.to_numeric(S.event, errors='coerce').fillna(0).sum())
    if _nev < 20:
        return None
    _d = pd.to_numeric(S.duration, errors='coerce')
    _bad = int(((_d <= 0) | ~np.isfinite(_d)).sum())
    if _bad:
        S = S[(_d > 0) & np.isfinite(_d)].copy()
        if len(S) < 30 or int(S.event.sum()) < 20:
            return None
    S = S.sort_values('duration', ascending=False).reset_index(drop=True)
    X = S[list(covariates)].to_numpy(float)
    mu = X.mean(0)
    sd = X.std(0)
    sd[sd == 0] = 1.0
    Xs = (X - mu) / sd
    ev = S.event.to_numpy(int)
    dur = S.duration.to_numpy(float)
    n, p = Xs.shape
    brk = np.r_[True, dur[1:] != dur[:-1]]
    grp_start = np.where(brk)[0]
    grp_end = np.r_[grp_start[1:], n] - 1
    beta = np.zeros(p)
    H = np.eye(p)
    for _ in range(max_iter):
        eta = np.clip(Xs @ beta, -30, 30)
        w = np.exp(eta)
        S0 = 0.0
        S1 = np.zeros(p)
        S2 = np.zeros((p, p))
        grad = np.zeros(p)
        H = np.zeros((p, p))
        for a, b in zip(grp_start, grp_end):
            sl = slice(a, b + 1)
            wg = w[sl]
            Xg = Xs[sl]
            S0 += wg.sum()
            S1 += wg @ Xg
            S2 += (Xg * wg[:, None]).T @ Xg
            de = ev[sl] == 1
            d_k = int(de.sum())
            if d_k == 0:
                continue
            wE = wg[de]
            XE = Xg[de]
            E0 = wE.sum()
            E1 = wE @ XE
            E2 = (XE * wE[:, None]).T @ XE
            grad += XE.sum(0)
            for j in range(d_k):
                f = j / d_k
                D0 = S0 - f * E0
                D1 = S1 - f * E1
                D2 = S2 - f * E2
                xbar = D1 / D0
                grad -= xbar
                H += D2 / D0 - np.outer(xbar, xbar)
        H += np.eye(p) * ridge
        try:
            step = np.linalg.solve(H, grad)
        except np.linalg.LinAlgError:
            break
        beta = beta + step
        if np.max(np.abs(step)) < tol:
            break
    try:
        cov = np.linalg.inv(H)
    except np.linalg.LinAlgError:
        cov = np.eye(p) * np.nan
    se = np.sqrt(np.clip(np.diag(cov), 0, None))
    se_cl = None
    _cl_note = None
    if cluster is not None and cluster not in S.columns:
        _cl_note = f'cluster column `{cluster}` not present — SEs are MODEL-BASED, not robust'
    elif cluster is not None and S[cluster].nunique() < 2:
        _cl_note = f'only {S[cluster].nunique()} cluster — sandwich undefined, SEs are MODEL-BASED'
    if cluster is not None and cluster in S.columns and (S[cluster].nunique() >= 2):
        eta = np.clip(Xs @ beta, -30, 30)
        w = np.exp(eta)
        S0 = 0.0
        S1 = np.zeros(p)
        xbar_at = np.zeros((n, p))
        S0_at = np.zeros(n)
        for a, b in zip(grp_start, grp_end):
            sl = slice(a, b + 1)
            wg = w[sl]
            Xg = Xs[sl]
            S0 += wg.sum()
            S1 += wg @ Xg
            xbar_at[sl] = S1 / S0
            S0_at[sl] = S0
        ev_idx = np.where(ev == 1)[0]
        inv = np.zeros(n)
        tail = np.zeros((n, p))
        c0 = np.zeros(n + 1)
        c1 = np.zeros((n + 1, p))
        for k in range(n - 1, -1, -1):
            c0[k] = c0[k + 1] + (ev[k] / S0_at[k] if ev[k] else 0.0)
            c1[k] = c1[k + 1] + (xbar_at[k] / S0_at[k] if ev[k] else 0.0)
        U = ev[:, None] * (Xs - xbar_at) - w[:, None] * (Xs * c0[:n, None] - c1[:n])
        g = S[cluster].to_numpy()
        codes, inv_ = np.unique(g, return_inverse=True)
        Ug = np.zeros((len(codes), p))
        np.add.at(Ug, inv_, U)
        meat = Ug.T @ Ug
        cov_cl = cov @ meat @ cov
        se_cl = np.sqrt(np.clip(np.diag(cov_cl), 0, None))
    b_orig = beta / sd
    se_orig = se / sd
    with np.errstate(divide='ignore', invalid='ignore'):
        z = np.where(se_orig > 0, b_orig / se_orig, np.nan)
    out = dict(covariate=list(covariates), coef=np.round(b_orig, 5), hazard_ratio=np.round(np.exp(b_orig), 4), se=np.round(se_orig, 5), z=np.round(z, 3))
    if _cl_note is not None:
        out['cluster_warning'] = [_cl_note] * len(covariates)
    if se_cl is not None:
        se_cl_o = se_cl / sd
        with np.errstate(divide='ignore', invalid='ignore'):
            out['se_cluster'] = np.round(se_cl_o, 5)
            out['z_cluster'] = np.round(np.where(se_cl_o > 0, b_orig / se_cl_o, np.nan), 3)
            out['se_inflation'] = np.round(se_cl_o / np.where(se_orig > 0, se_orig, np.nan), 3)
    return pd.DataFrame(dict(**out, interpretation=['accelerates the event' if b > 0.02 else 'delays the event' if b < -0.02 else 'no effect' for b in b_orig])).sort_values('z', key=abs, ascending=False)

def laz_cox__optimal_window(spells, covariates, model, q=(0.25, 0.5, 0.75)):
    """WHEN is the event most likely, given the covariates at arm time?

    The hazard ratio says how much faster; this says WHERE that lands in time.
    For a bet that needs an event (a goal for an over, a lead change for a
    comeback), the useful window is where the CUMULATIVE hazard rises fastest.
    """
    S = spells.dropna(subset=['duration', 'event'] + list(covariates)).copy()
    if not len(S) or model is None:
        return pd.DataFrame()
    b = dict(zip(model.covariate, model.coef))
    S['risk'] = np.exp(np.clip(sum((S[c].astype(float) * b.get(c, 0.0) for c in covariates)), -30, 30))
    out = []
    for lab, lo, hi in (('low', 0, 0.33), ('mid', 0.33, 0.66), ('high', 0.66, 1.0)):
        a, c = (S.risk.quantile(lo), S.risk.quantile(hi))
        g = S[(S.risk >= a) & (S.risk < c)] if hi < 1.0 else S[(S.risk >= a) & (S.risk <= c)]
        if len(g) < 20:
            continue
        ev = g[g.event == 1]
        out.append(dict(risk_band=lab, n=len(g), event_rate=round(float(g.event.mean() * 100), 1), median_time_to_event=round(float(ev.duration.median()), 3) if len(ev) else np.nan, q25=round(float(ev.duration.quantile(0.25)), 3) if len(ev) else np.nan, q75=round(float(ev.duration.quantile(0.75)), 3) if len(ev) else np.nan))
    return pd.DataFrame(out)

def laz_cox__concordance(spells, covariates, model, n_pairs=None, seed=0):
    """Harrell's C, computed EXACTLY. 0.5 = no better than chance.

    The sampled version differed from the exact value by 0.003 on 400 spells.
    Exact is O(n log n) via a sort, so there is no reason to sample.
    A pair (i, j) is comparable when the earlier time is an event; concordant
    when the higher-risk subject is the one that failed first.
    """
    S = spells.dropna(subset=['duration', 'event'] + list(covariates))
    if model is None or len(S) < 50:
        return np.nan
    b = dict(zip(model.covariate, model.coef))
    risk = np.exp(np.clip(sum((S[c].astype(float) * b.get(c, 0.0) for c in covariates)), -30, 30)).to_numpy()
    dur = S.duration.to_numpy()
    ev = S.event.to_numpy(int)
    order = np.argsort(dur, kind='stable')
    dur = dur[order]
    ev = ev[order]
    risk = risk[order]
    n = len(dur)
    conc = 0.0
    tot = 0
    for i in range(n):
        if ev[i] != 1:
            continue
        j = np.searchsorted(dur, dur[i], side='right')
        if j >= n:
            continue
        r = risk[j:]
        tot += len(r)
        conc += float((risk[i] > r).sum()) + 0.5 * float((risk[i] == r).sum())
    return round(conc / tot, 4) if tot else np.nan

def laz_cox__analyse(sport, covariates=None, stride=1, max_cov=8, log=print):
    """Fit the hazard model for a sport and report what accelerates the event."""
    ST = _m('laz_startup')
    OW = _m('laz_owner')
    d, pool, ctx, man = ST.prepare(sport, stride=stride, log=log)
    elc = man['lineage'].get('elapsed_col')
    if covariates is None:
        prefer = ['u_pace', 'u_margin_abs', 'u_margin_rate', 'u_vf', 'u_ratio', 'u_drift', 'u_since_score', 'u_total', 'u_overround', 'u_time_in_lead']
        covariates = [c for c in prefer if c in d.columns][:max_cov]
    if not covariates:
        log(f'  [cox] {sport}: no usable covariates')
        return None
    sp = laz_cox__build_spells(d, time_col=elc, covariates=covariates, every=0.08, max_per_match=10)
    if not len(sp):
        log(f'  [cox] {sport}: no spells')
        return None
    ev = int(sp.event.sum())
    log(f'  [cox] {sport}: {len(sp):,} spells · {ev} events · {len(sp) - ev} CENSORED ({(1 - ev / len(sp)) * 100:.0f}% — a plain regression would score these as negatives)')
    M = laz_cox__fit(sp, covariates, cluster='match_id')
    if M is None:
        log(f'  [cox] {sport}: did not converge')
        return None
    C = laz_cox__concordance(sp, covariates, M)
    if 'se_inflation' in M.columns:
        log(f'  [cox] {sport}: cluster-robust SE inflation median {M.se_inflation.median():.3f} · max {M.se_inflation.max():.3f} · |z| ordering {('unchanged' if list(M.sort_values('z', key=abs, ascending=False).covariate) == list(M.sort_values('z_cluster', key=abs, ascending=False).covariate) else 'CHANGED')}')
    log(f'  [cox] {sport}: unquoted matches {sp.attrs.get('unquoted_matches', 0)} · invalid starts skipped {sp.attrs.get('skipped_invalid_starts', 0)}')
    W = laz_cox__optimal_window(sp, covariates, M)
    log(f'  [cox] {sport}: concordance {C} (0.5 = chance)')
    return dict(model=M, spells=sp, concordance=C, window=W, covariates=covariates)

def laz_cox__hazard_condition(d, pool, ctx, is_mask, elc=None, covariates=None, max_cov=8, log=print):
    """Add `u_hazard` — the log relative hazard of the next scoring event — to
    the pool, fitted on IS ticks only. Returns (pool, model) or (pool, None)."""
    prefer = ['u_pace', 'u_margin_abs', 'u_margin_rate', 'u_vf', 'u_ratio', 'u_drift', 'u_since_score', 'u_total', 'u_overround', 'u_time_in_lead']
    covariates = covariates or [c for c in prefer if c in pool][:max_cov]
    if len(covariates) < 2:
        return (pool, None)
    di = d[np.asarray(is_mask, bool)] if is_mask is not None else d
    if len(di) < 2000:
        return (pool, None)
    sp = laz_cox__build_spells(di, time_col=elc, covariates=covariates, every=0.08, max_per_match=10)
    if not len(sp) or sp.event.sum() < 200:
        return (pool, None)
    M = laz_cox__fit(sp, covariates)
    if M is None:
        return (pool, None)
    C = laz_cox__concordance(sp, covariates, M)
    b = dict(zip(M.covariate, M.coef))
    _ho = pd.to_numeric(d['home_odds'], errors='coerce').values if 'home_odds' in d.columns else None
    _ao = pd.to_numeric(d['away_odds'], errors='coerce').values if 'away_odds' in d.columns else None
    _valid = np.isfinite(_ho) & np.isfinite(_ao) & (_ho > 1) & (_ao > 1) if _ho is not None and _ao is not None else np.ones(len(d), bool)
    lin = np.zeros(len(d))
    for c in covariates:
        v = np.asarray(pool[c], float)
        _mu = float(np.nanmean(v[is_mask])) if np.isfinite(v[is_mask]).any() else 0.0
        lin += np.where(np.isfinite(v), v, _mu) * float(b.get(c, 0.0))
    lin = np.where(_valid, lin, np.nan)
    pool = dict(pool)
    pool['u_hazard'] = lin
    try:
        LA = _m('laz_lookahead')
        if LA is not None:
            LA.register_derived('u_hazard', covariates)
    except Exception:
        pass
    try:   # [v246-FG] persist the coefficients + IS means — the production module embeds them
        import os as _os2, json as _js2
        OW2 = _m('laz_owner') if globals().get('_m') else None
        _home2 = (OW2.LAZ_OWNER['paths'].get('output_dir') if OW2 else None) or _os2.getcwd()
        _sp2 = str(ctx.get('sport') or d.attrs.get('sport') or 'all')
        _mus = {}
        for c in covariates:
            v2 = np.asarray(pool[c], float)
            _mus[c] = float(np.nanmean(v2[is_mask])) if np.isfinite(v2[is_mask]).any() else 0.0
        with open(_os2.path.join(_home2, f'laz_cox_{_sp2}.json'), 'w') as _fhc:   # [v246-HND] the leaked handle prove_no_deprecation caught
            _js2.dump(dict(sport=_sp2, covariates=list(covariates), coef_mean={c: [float(b.get(c, 0.0)), float(_mus[c])] for c in covariates}, concordance=float(C)), _fhc, indent=1)
    except Exception:
        pass
    top = M.iloc[0]
    _cov = float(np.isfinite(lin).mean())
    log(f'  [cox] u_hazard added (fit on IS, {len(sp):,} spells, concordance {C}) · defined on {_cov * 100:.0f}% of ticks (valid odds only) · strongest {top.covariate} HR {top.hazard_ratio} z {top.z}')
    if _cov < 0.25:
        log(f'  [cox] WARNING u_hazard covers only {_cov * 100:.0f}% of ticks — the search may not be able to use it')
    return (pool, dict(model=M, concordance=C, covariates=covariates))

