def laz_specs__load_specs(path=None):
    """The 111 engine specs. Disk copy if present; else the EMBEDDED copy.
    Both JSONs were read from disk only, so in any directory but the build
    one every eng_* condition came back UNKNOWN and no spec could arm. The
    engine now carries them, like every other store."""
    import os as _o
    path = path or _o.path.join(laz_specs___laz_home(), 'engine_specs.json')
    if _o.path.exists(path):
        return _laz_json_read(path)
    try:
        return json.loads(laz_specs__SPECS_TXT)
    except Exception:
        return {}

def laz_specs___load_specs_disk(path=__import__('os').path.join(laz_specs___laz_home(), 'engine_specs.json')):
    if not os.path.exists(path):
        return {}
    return _laz_json_read(path)

def laz_specs__needed(spec):
    c = set()
    if spec.get('extra_mask'):
        c |= set(re.findall("f\\['([^']+)'\\]", spec['extra_mask']))
    for k in ('odds_col', 'payout_odds_col', 'win_col'):
        if spec.get(k):
            c.add(spec[k])
    return c

def laz_specs__runnable(d, specs=None):
    """Which engine specs can be armed on this frame, after derive()."""
    specs = specs or laz_specs__load_specs()
    have = set(d.columns)
    return {n: v for n, v in specs.items() if v.get('odds_col') and laz_specs__needed(v) <= have}

def laz_specs__arm(d, spec, ctx=None):
    """(side, price, outcome, valid) for one engine spec. side is the label the
    win_col must equal; for win_value specs the outcome is that literal."""
    num = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else np.full(len(d), np.nan)
    oc = spec['odds_col']
    wc = spec['win_col']
    wv = spec.get('win_value')
    px = num(spec.get('payout_odds_col') or oc)
    if wc is None or wc not in d.columns:
        return (None, None, None, None)
    col = d[wc].astype(str).values
    if wv:
        y = (col == str(wv)).astype(float)
        side = np.full(len(d), str(wv), dtype=object)
    else:
        side = np.where(pd.isna(d[wc]), None, col)
        fr = (d['final_result'] if 'final_result' in d.columns else pd.Series('', index=d.index)).astype(str).str.replace('_team', '', regex=False).values
        y = (np.asarray(fr).astype(str) == pd.Series(col).astype(str).str.lower().to_numpy(dtype=object)).astype(float)
    m = np.ones(len(d), bool)
    if spec.get('extra_mask'):
        try:
            m = np.asarray(eval(spec['extra_mask'], {'f': d, 'np': np, 'pd': pd}), bool)
        except Exception as _me:
            return (None, None, None, None)
    valid = m & np.isfinite(px) & (px > 1.0) & ~pd.isna(side)
    return (side, px, y, valid)

def laz_specs__load_conditions(path=None):
    import os as _o
    path = path or _o.path.join(laz_specs___laz_home(), 'engine_conditions.json')
    if _o.path.exists(path):
        return _laz_json_read(path)
    try:
        return json.loads(laz_specs__CONDITIONS_TXT)
    except Exception:
        return {}

def laz_specs___load_conditions_disk(path=__import__('os').path.join(laz_specs___laz_home(), 'engine_conditions.json')):
    if not os.path.exists(path):
        return {}
    return _laz_json_read(path)

def laz_specs__build_conditions(d, ctx=None, conds=None, log=None):
    """Evaluate every engine condition that this frame can support.
    Returns {name: float array of 0/1/nan}."""
    conds = conds or laz_specs__load_conditions()
    have = set(d.columns)
    out = {}
    skipped = 0
    for name, code in conds.items():
        need = set(re.findall("f\\['([^']+)'\\]", code))
        if not need or not need <= have:
            skipped += 1
            continue
        try:
            v = eval(code, {'f': d, 'np': np, 'pd': pd})
            a = np.asarray(v)
            if a.dtype == bool or a.dtype.kind in 'biufO':
                arr = pd.Series(a).astype(np.float32).values
                if np.isfinite(arr).sum() > 200 and 0 < np.nanmean(arr) < 1:
                    out['eng_' + name] = arr
        except Exception:
            skipped += 1
    if log:
        log(f'[engine-cond] {len(out)} of {len(conds)} engine conditions armed ({skipped} unavailable)')
    return out
