laz_featdoc__OPS = {'__minus__': ('difference', 'A - B'), '__over__': ('ratio', 'np.where(np.abs(B) > 1e-9, A / B, np.nan)'), '__x__': ('product', 'A * B')}

def laz_featdoc__split_derived(name):
    """Split a manufactured name into (left, op, right), respecting NESTING.

    materialise() names a term X_{A}__op__{B} where A and B may themselves be
    X_-prefixed. A naive "last operator" split produced garbage nodes like
    `u_pace__minus__u_time_in_lead` and `X_u_elapsed`, neither of which is a
    real term. The correct split is the operator at which the number of open
    X_ prefixes balances — the same problem as matching brackets.

    Each `X_` opens a nesting level and each operator closes one, so we scan
    left to right tracking the balance and split at the first operator that
    returns it to zero.
    """
    n = str(name)
    if not n.lower().startswith('x_'):
        return None
    body = n[2:]
    toks = []
    i = 0
    while i < len(body):
        if body[i:i + 2] == 'X_':
            toks.append(('OPEN', i, 2))
            i += 2
            continue
        m = re.match('__(?:minus|over|x)__', body[i:])
        if m:
            toks.append(('OP', i, m.end(), m.group(0)))
            i += m.end()
            continue
        i += 1
    bal = 0
    for t in toks:
        if t[0] == 'OPEN':
            bal += 1
        else:
            if bal == 0:
                pos, end, op = (t[1], t[2], t[3])
                left, right = (body[:pos], body[pos + len(op):])
                if left and right:
                    return (left, op, right)
            bal -= 1
    for t in toks:
        if t[0] == 'OP':
            pos, op = (t[1], t[3])
            left, right = (body[:pos], body[pos + len(op):])
            if left and right:
                return (left, op, right)
    return None

def laz_featdoc___resolve_via_sibling(key):
    """Resolution time from laz_lookahead, whether standalone or embedded."""
    import sys as _s
    m = _s.modules.get('laz_lookahead')
    if m is not None:
        try:
            return m.resolves_at(key)
        except Exception:
            return 'unknown'
    g = globals()
    if 'resolves_at' in g and 'PARENTAGE' in g:
        try:
            return g['resolves_at'](key)
        except Exception:
            return 'unknown'
    try:
        __import__('laz_lookahead')
        return _s.modules['laz_lookahead'].resolves_at(key)
    except Exception:
        return 'unknown'

def laz_featdoc__document_feature_lines(name, depth=0, seen=None):
    """Walk a term to PRIMITIVES and emit the full rebuild for every node."""
    seen = seen or set()
    n = str(name)
    key = n.lower()
    ind = '   ' * depth
    if key in seen:
        return [f'{ind}{n}  (already documented above)']
    seen.add(key)
    L = []
    parts = laz_featdoc__split_derived(n)
    if parts:
        a, op, b = parts
        oname, ofml = laz_featdoc__OPS[op]
        L.append(f'{ind}{n}')
        L.append(f'{ind}   TYPE      : DERIVED — the {oname} of two terms')
        L.append(f'{ind}   FORMULA   : A = {a}')
        L.append(f'{ind}               B = {b}')
        L.append(f'{ind}               {n} = {ofml}')
        L.append(f"{ind}   RESOLVES  : the LATER of A and B — a derived term inherits its parents' resolution")
        L.append(f'{ind}   BUILD A:')
        L += laz_featdoc__document_feature_lines(a, depth + 2, seen)
        L.append(f'{ind}   BUILD B:')
        L += laz_featdoc__document_feature_lines(b, depth + 2, seen)
        return L
    p = laz_featdoc__PRIMITIVES.get(key)
    if p:
        L.append(f'{ind}{n}')
        L.append(f'{ind}   TYPE      : UNIVERSAL PRIMITIVE (constructed, exists in no frame)')
        L.append(f'{ind}   MEANING   : {p['meaning']}')
        L.append(f'{ind}   FORMULA   : {p['formula']}')
        L.append(f'{ind}   REQUIRES  : {p['requires']}')
        L.append(f'{ind}   RESOLVES  : {p['resolves']}')
        if p['note']:
            L.append(f'{ind}   NOTE      : {p['note']}')
        deps = [x.strip() for x in str(p['requires']).replace(' and ', ',').split(',')]
        deps = [x for x in deps if x.lower() in laz_featdoc__PRIMITIVES and x.lower() != key]
        for dpn in deps:
            if dpn.lower() in seen:
                L.append(f'{ind}   BUILD {dpn}: (already documented above)')
            else:
                L.append(f'{ind}   BUILD {dpn}:')
                L += laz_featdoc__document_feature_lines(dpn, depth + 2, seen)
        return L
    r = laz_featdoc___resolve_via_sibling(key)
    nat = laz_featdoc__NATIVES.get(n) or laz_featdoc__NATIVES.get(key)
    if nat is None:
        for pre, desc in laz_featdoc__NATIVE_PATTERNS:
            if key.startswith(pre.lower()) or key.endswith(pre.lower()):
                nat = (desc, f'pd.to_numeric(d["{n}"], errors="coerce")', str(r))
                break
    if nat is None:
        nat = (f'Native frame column `{n}`. Read directly from the feed; its exact construction is defined by the data provider. NOT YET GIVEN A SPECIFIC DEFINITION — add it to laz_featdoc.NATIVES.', f'pd.to_numeric(d["{n}"], errors="coerce")', str(r))
    L.append(f'{ind}{n}')
    L.append(f'{ind}   TYPE      : NATIVE FRAME COLUMN — read from the parquet')
    if nat:
        L.append(f'{ind}   MEANING   : {nat[0]}')
        L.append(f'{ind}   HOW BUILT : {nat[1]}')
    L.append(f'{ind}   FORMULA   : pd.to_numeric(d["{n}"], errors="coerce")')
    L.append(f'{ind}   RESOLVES  : {r}' + ('  — MASK TO NaN at every tick before this elapsed share' if isinstance(r, float) and r > 0 else ''))
    return L

def laz_featdoc__document_condition(cond):
    """A full condition: the comparison plus the complete build of its term."""
    c = str(cond).strip()
    m = re.match('^([\\d.\\-eE]+)\\s*<=\\s*(.+?)\\s*<=\\s*([\\d.\\-eE]+)$', c)
    if m:
        term, test = (m.group(2), f'{m.group(1)} <= {m.group(2)} <= {m.group(3)}  (a BAND — a middle pocket neither >= nor <= can express)')
    else:
        p = c.rsplit(' ', 2)
        term = p[0] if len(p) == 3 else c
        test = c
    out = [f'CONDITION: {test}', '']
    out += laz_featdoc__document_feature_lines(term)
    return '\n'.join(out)

def laz_featdoc__document_all(terms):
    out = []
    for t in terms:
        out.append('=' * 100)
        out.append(laz_featdoc__document_condition(t))
        out.append('')
    return '\n'.join(out)
laz_featdoc__PRIMITIVES = {'h_score', 'a_score', 'home_odds', 'away_odds', 'draw_odds', 'ts', 'match_id', 'minute', 'tg', 'final_result', 'final_winner', 'total_goals_handicap', 'total_goals_over', 'total_goals_under', 'point_spread_handicap', 'sets', 'q1_h', 'q1_a', 'h1_h', 'h1_a', 'phase', 'league', 'open_line', 'pm_fav'}
laz_featdoc__UNIVERSAL_ARITHMETIC = {'u_time_in_lead': 'share of observed ticks the backed side has led: (margin>0).groupby(match_id).cumsum() / (groupby(match_id).cumcount()+1). Resolves at tick 0.', 'u_elapsed': "match progress normalised 0-1 by laz_frames from the sport's elapsed column (prog / frac / derived). Resolves at tick 0.", 'u_margin': 'h_score - a_score signed to the BACKED side: +ve when the backed side leads.', 'u_total': 'h_score + a_score, the running total at this tick.', 'u_pace': 'u_total / max(u_elapsed, 0.02) — goals per unit of elapsed match.', 'u_since_score': 'ticks since u_total last changed, per match.', 'u_vf': 'vig-free implied probability of the backed side: (1/backed_price) / (1/home_odds + 1/away_odds).', 'u_ratio': 'backed_price / opposing_price at this tick.', 'u_drift': 'backed_price / backed_price_at_first_tick_of_this_match.', 'u_overround': "1/home_odds + 1/away_odds — the book's margin at this tick.", 'u_open': "the backed side's price at the FIRST tick of the match.", 'u_lead_flips': 'count of sign changes in u_margin so far, per match.'}

def laz_featdoc___split_manufactured(name):
    """X_a__op__b decomposes into (a, op, b). The engine manufactures these in
    the interaction stage; the name IS the arithmetic."""
    import re as _re
    n = str(name)
    if not n.startswith('X_'):
        return None
    body = n[2:]
    for tok, sym in (('__minus__', '-'), ('__over__', '/'), ('__x__', '*'), ('__plus__', '+')):
        if tok in body:
            i = body.index(tok)
            return (body[:i], sym, body[i + len(tok):])
    return None

def laz_featdoc__document_feature(name, depth=0, seen=None, log=None):
    """Walk a term to primitives. Returns a dict with the full derivation.

    Every level records: what it is, the arithmetic that produces it, its
    parents, its source columns, and when it resolves. A term reachable only
    through parents still bottoms out at columns that exist in the frame.
    """
    import re as _re
    seen = seen or set()
    n = str(name)
    out = dict(feature=n, depth=depth, kind=None, arithmetic=None, parents=[], source_columns=[], resolves_at=None, notes=None)
    if n in seen:
        out.update(kind='cycle', notes='already on this derivation path')
        return out
    seen = seen | {n}
    LA = _m('laz_lookahead')
    CG = _m('causality_guard')
    CT = _m('laz_catalogue')
    out['resolves_at'] = LA.resolves_at(n) if LA is not None else None
    if CG is not None and hasattr(CG, 'resolves_at'):
        g = CG.resolves_at(n)
        if g == 'event':
            out['notes'] = 'event-gated: NaN until the event has happened on the row (validate_state), never a fraction of the match'
        elif g:
            out['notes'] = f'time-gated: not determined before {g} elapsed'
    if n in laz_featdoc__PRIMITIVES:
        out.update(kind='primitive', arithmetic=f'read directly from the frame column `{n}`', source_columns=[n])
        return out
    parts = laz_featdoc___split_manufactured(n)
    if parts:
        a, op, b = parts
        pa = laz_featdoc__document_feature(a, depth + 1, seen, log)
        pb = laz_featdoc__document_feature(b, depth + 1, seen, log)
        out.update(kind='manufactured (interaction stage)', arithmetic=f'({a}) {op} ({b})', parents=[pa, pb], source_columns=sorted(set(pa['source_columns']) | set(pb['source_columns'])))
        return out
    if n in laz_featdoc__UNIVERSAL_ARITHMETIC:
        out.update(kind='universal', arithmetic=laz_featdoc__UNIVERSAL_ARITHMETIC[n])
        cols = sorted({c for c in laz_featdoc__PRIMITIVES if c in laz_featdoc__UNIVERSAL_ARITHMETIC[n]})
        out['source_columns'] = cols or ['h_score', 'a_score', 'home_odds', 'away_odds']
        return out
    par = []
    if LA is not None:
        par = list((getattr(LA, 'PARENTAGE', {}) or {}).get(n.lower(), ()) or ())
    if par:
        kids = [laz_featdoc__document_feature(p, depth + 1, seen, log) for p in par]
        CR = _m('laz_corr')
        _op = None
        _trip = (getattr(CR, 'SHORT_TO_LONG', {}) or {}).get(name) if CR is not None else None
        if _trip is None and CR is not None and hasattr(CR, 'parse_long'):
            _trip = CR.parse_long(name)
        if _trip:
            _a, _b, _o = _trip
            _op = {'__minus__': f'{_a} - {_b}', '__over__': f'np.where(np.abs({_b})>1e-9, {_a}/{_b}, np.nan)', '__x__': f'{_a} * {_b}'}.get(_o)
        out.update(kind='derived (registered lineage)', arithmetic=_op or f'built from {', '.join(par)} (operator not recorded)', parents=kids, source_columns=sorted({c for k in kids for c in k['source_columns']}))
        return out
    if CT is not None:
        e = (CT.load().get('feature', {}) or {}).get(n) or (CT.load().get('condition', {}) or {}).get(n) or {}
        f = e.get('formula') or e.get('code') or e.get('definition')
        if f:
            cols = [c for c in e.get('columns') or [] if c]
            out.update(kind='catalogued', arithmetic=str(f)[:400], source_columns=cols or [n])
            return out
    out.update(kind='UNDOCUMENTED', arithmetic='no formula found — this term cannot be rebuilt from the workbook', source_columns=[n])
    if log:
        log(f'[featdoc] UNDOCUMENTED term: {n}')
    return out

def laz_featdoc__flatten_feature(doc, rows=None, path=''):
    """One row per derivation step, for a spreadsheet."""
    rows = rows if rows is not None else []
    rows.append(dict(feature=doc['feature'], depth=doc['depth'], kind=doc['kind'], arithmetic=doc['arithmetic'], source_columns='|'.join(doc['source_columns']), resolves_at=doc['resolves_at'], notes=doc['notes'], derivation_path=path or doc['feature']))
    for p in doc['parents']:
        laz_featdoc__flatten_feature(p, rows, path=(path or doc['feature']) + ' <- ' + p['feature'])
    return rows

def laz_featdoc__rebuild_recipe(name, log=None):
    """Plain-English steps to rebuild a term from frame columns, deepest first."""
    d = laz_featdoc__document_feature(name, log=log)
    rows = laz_featdoc__flatten_feature(d)
    steps = []
    for r in sorted(rows, key=lambda z: -z['depth']):
        if r['kind'] == 'primitive':
            continue
        steps.append(f'{r['feature']} = {r['arithmetic']}')
    seen = set()
    ordered = []
    for s in steps:
        if s in seen:
            continue
        seen.add(s)
        ordered.append(s)
    return dict(feature=name, steps=ordered, primitives=sorted({c for r in rows for c in (r['source_columns'] or '').split('|') if c}), resolves_at=d['resolves_at'], undocumented=[r['feature'] for r in rows if r['kind'] == 'UNDOCUMENTED'])
# ==========================================================================
# LAZ_BRAIN MODULE: laz_hpap
# §laz_hpap   <- grep this anchor to land here
# OBJECTIVE : CONDITION CREATION
# PURPOSE   : Turn paired hp_/ap_ columns into relationships oriented to the BACKED side.
# HOW       : 78 features: matchup cross, projection vs line, form gradient, h2h residual, shock, load asymmetry, all as bk_/op_/gap_.
# VALUE     : Orientation alone took qualifying stacks from 28 to 4,168 — a home-oriented feature describes the wrong player on half the bets.
# IF SKIPPED: Half the signal averages against itself.
# ==========================================================================
"""laz_hpap.py — the hp_/ap_ FEATURE FACTORY.

THE WASTE THIS FIXES
    The frame carries 64 hp_/ap_ columns and build_masks() cuts quantile
    thresholds on each one INDEPENDENTLY. But they are PAIRED: every hp_X has an
    ap_X twin. "hp_avggoals_scored_5 >= 62.6" is a statement about one player in
    isolation. It is nearly meaningless, because whether 62.6 is good depends
    entirely on who they are playing. The information lives in the RELATIONSHIP.

    Everything below is built from hp_/ap_ ONLY, oriented to the BACKED side
    (bk_) and the OPPONENT (op_), so the feature describes the player being
    bet on rather than whoever happens to be at home.

SEVEN FAMILIES

 1 MATCHUP CROSS   my attack meets THEIR defence, not their attack.
     atk_vs_def   = bk_scored_N  - op_conceded_N     (do I score on this guy?)
     def_vs_atk   = op_scored_N  - bk_conceded_N     (does he score on me?)
     two_way_edge = atk_vs_def + def_vs_atk          (net, both ends)
   This is the single most obvious thing the raw columns cannot say, because
   scored and conceded are never compared across the two players.

 2 PROJECTION vs THE MARKET   the columns already imply a scoreline. Say it.
     exp_bk = (bk_scored_N + op_conceded_N)/2
     exp_op = (op_scored_N + bk_conceded_N)/2
     exp_margin = exp_bk - exp_op        -> compare to the POSTED SPREAD
     exp_total  = exp_bk + exp_op        -> compare to the POSTED LINE
   Two independent estimates of the same quantity. The gap is the misprice, and
   it is built with no price input at all on the projection side.

 3 FORM GRADIENT   l5 vs l10 vs l20 is a TRAJECTORY, not three numbers.
     wr_slope   = wr_l5 - wr_l20         (rising or fading)
     sc_slope, cc_slope                  (scoring / leaking trend)
     accord     = do l5, l10, l20 agree on direction? (-3..+3)
   A player at 60% who is climbing is not the same object as one who is falling
   to 60%, and until now both read as 0.60.

 4 H2H vs GENERAL   the matchup-specific residual.
     h2h_residual = h2h_winrate_l10g - winrate_l10g
   Does this player over- or under-perform against THIS opponent relative to
   their own general level? That is a matchup effect the market rarely prices,
   and it cannot be seen from either column alone.
     h2h_conf     = (h2h_wr - 0.5) * h2h_games   -- rate alone is noise

 5 VOLATILITY   |l5 - l20| across scored/conceded/winrate. High spread = an
   unreliable read; a 70% l5 off a 50% l20 is one hot streak, not a level.

 6 SHOCK   lastgame vs the 5-game average. A player coming off an outlier.
     sc_shock = goals_scored_lastgame - avggoals_scored_5

 7 LOAD & EXPERIENCE   games in the last 24h, career games, and the ASYMMETRY
   between the two players -- fatigue only matters relative to the opponent.
"""
import numpy as np, pandas as pd
laz_hpap__HORIZONS = (5, 10, 20)

def laz_hpap__build(t, backed_is_home):
    """Returns (frame_with_features, list_of_new_names). hp_/ap_ only."""
    t = t.copy()
    H = np.asarray(backed_is_home, bool)
    new = []

    def g(c):
        return pd.to_numeric(t[c], errors='coerce') if c in t.columns else pd.Series(np.nan, index=t.index)

    def pair(stem, name):
        h, a = (g('hp_' + stem), g('ap_' + stem))
        if h.isna().all() and a.isna().all():
            return (None, None)
        bk = pd.Series(np.where(H, h, a), index=t.index)
        op = pd.Series(np.where(H, a, h), index=t.index)
        return (bk, op)

    def put(k, v):
        t[k] = v
        new.append(k)
    sc, cc, wr, mg = ({}, {}, {}, {})
    for N in laz_hpap__HORIZONS:
        sc[N] = pair(f'avggoals_scored_{N}', f'sc{N}')
        cc[N] = pair(f'avggoals_conceded_{N}', f'cc{N}')
        wr[N] = pair(f'winrate_l{N}g', f'wr{N}')
        mg[N] = pair(f'avg_matchgoals_{N}', f'mg{N}')
    for N in laz_hpap__HORIZONS:
        (bs, os_), (bc, oc) = (sc[N], cc[N])
        if bs is None or bc is None:
            continue
        put(f'atk_vs_def_{N}', bs - oc)
        put(f'def_vs_atk_{N}', os_ - bc)
        put(f'two_way_{N}', bs - oc - (os_ - bc))
        put(f'atk_ratio_{N}', bs / oc.replace(0, np.nan))
    for N in laz_hpap__HORIZONS:
        (bs, os_), (bc, oc) = (sc[N], cc[N])
        if bs is None or bc is None:
            continue
        eb = (bs + oc) / 2.0
        eo = (os_ + bc) / 2.0
        put(f'exp_margin_{N}', eb - eo)
        put(f'exp_total_{N}', eb + eo)
    sp = g('point_spread_handicap')
    ln = g('total_points_handicap')
    if 'exp_margin_10' in t.columns:
        put('margin_vs_spread', t['exp_margin_10'] + sp)
    if 'exp_total_10' in t.columns:
        put('total_vs_line', t['exp_total_10'] - ln)
    for lbl, dd in (('wr', wr), ('sc', sc), ('cc', cc), ('mg', mg)):
        if dd[5][0] is None or dd[20][0] is None:
            continue
        b5, o5 = dd[5]
        b10, o10 = dd[10]
        b20, o20 = dd[20]
        put(f'bk_{lbl}_slope', b5 - b20)
        put(f'op_{lbl}_slope', o5 - o20)
        put(f'{lbl}_slope_gap', b5 - b20 - (o5 - o20))
        put(f'bk_{lbl}_vol', (b5 - b20).abs())
        acc = np.sign(b5 - b10).fillna(0) + np.sign(b10 - b20).fillna(0) + np.sign(b5 - b20).fillna(0)
        put(f'bk_{lbl}_accord', acc)
    for N in (5, 10):
        bh, oh = pair(f'h2h_winrate_l{N}g', f'h2hwr{N}')
        bn, on = pair(f'h2h_l{N}g', f'h2hn{N}')
        if bh is None:
            continue
        put(f'bk_h2hwr_{N}', bh)
        put(f'op_h2hwr_{N}', oh)
        put(f'h2h_conf_{N}', (bh - 0.5) * bn)
        if wr[10][0] is not None:
            put(f'h2h_residual_{N}', bh - wr[10][0])
            put(f'h2h_resid_gap_{N}', bh - wr[10][0] - (oh - wr[10][1]))
        bs, os_ = pair(f'h2h_avggoals_scored_l{N}g', 'x')
        bc, oc = pair(f'h2h_avggoals_conceded_l{N}g', 'y')
        if bs is not None and bc is not None:
            put(f'h2h_two_way_{N}', bs - oc - (os_ - bc))
    bl, ol = pair('goals_scored_lastgame', 'x')
    bcl, ocl = pair('goals_conceded_lastgame', 'y')
    if bl is not None and sc[5][0] is not None:
        put('bk_sc_shock', bl - sc[5][0])
        put('op_sc_shock', ol - sc[5][1])
        put('sc_shock_gap', bl - sc[5][0] - (ol - sc[5][1]))
    if bcl is not None and cc[5][0] is not None:
        put('bk_cc_shock', bcl - cc[5][0])
    bw, ow = pair('win_last_games_flag', 'x')
    b2, o2 = pair('win_last2games_flag', 'y')
    if bw is not None and b2 is not None:
        put('bk_streak', bw + b2)
        put('op_streak', ow + o2)
        put('streak_gap', bw + b2 - (ow + o2))
    bg, og = pair('count_games_last_24_hours', 'x')
    if bg is not None:
        put('bk_load24', bg)
        put('op_load24', og)
        put('load_gap', bg - og)
        put('load_sum', bg + og)
    bt, ot = pair('total_player_wr', 'x')
    if bt is not None:
        put('bk_career', bt)
        put('op_career', ot)
        put('career_gap', bt - ot)
        for N in laz_hpap__HORIZONS:
            if wr[N][0] is None:
                continue
            put(f'bk_vs_base_{N}', wr[N][0] - bt)
            put(f'op_vs_base_{N}', wr[N][1] - ot)
            put(f'vs_base_gap_{N}', wr[N][0] - bt - (wr[N][1] - ot))
    for N in laz_hpap__HORIZONS:
        if wr[N][0] is not None:
            put(f'wr_gap_{N}', wr[N][0] - wr[N][1])
    return (t, new)
