legacy_features__LEGACY_CUTS = {}
legacy_features__POOL_CUTS = {}

def legacy_features___load_cuts():
    """The cut tables travel INSIDE the engine.

    These were module-level json.load(open(...)) calls, which is_library()
    rejects — so legacy_features was silently DROPPED from every build and
    _m('legacy_features') returned None. The 360 audit caught it; four build
    guards did not, because the module simply was not there to fail.

    Same fix as the genome and the book: carry the data as JSON, parse on
    first use, and still prefer a file on disk if the operator supplies one.
    """
    import json as _j, os as _o
    global LEGACY_CUTS, POOL_CUTS
    for _name, _txt, _file in (('LEGACY_CUTS', legacy_features__LEGACY_CUTS_TXT, 'legacy_conditions.json'), ('POOL_CUTS', legacy_features__POOL_CUTS_TXT, 'pool_conditions.json')):
        _v = {}
        try:
            _v = _j.loads(_txt)
        except Exception:
            _v = {}
        _p = _o.path.join(legacy_features___laz_home(), _file)
        if _o.path.exists(_p):
            try:
                _v = {**_v, **_j.load(open(_p))}
            except Exception:
                pass
        globals()[_name] = _v
    return (legacy_features__LEGACY_CUTS, legacy_features__POOL_CUTS)

def legacy_features__tick_dynamics(frame, cols=None):
    if not legacy_features__LEGACY_CUTS and (not legacy_features__POOL_CUTS):
        legacy_features___load_cuts()
    'Price trend / momentum / volatility per match, from the tick series.'
    import pyarrow.parquet as pq
    nmm = set(pq.ParquetFile(frame).schema_arrow.names)
    TS = 'ts' if 'ts' in nmm else 'timestamp'
    need = [c for c in ('match_id', TS, 'h_score', 'a_score', 'home_odds', 'away_odds', 'draw_odds', 'total_goals_handicap', 'total_goals_handicap_ffill') if c in nmm]
    d = pq.read_table(frame, columns=need).to_pandas()
    if TS != 'ts':
        d = d.rename(columns={TS: 'ts'})
    d = d.sort_values(['match_id', 'ts']).reset_index(drop=True)
    g = d.groupby('match_id', sort=False)
    ho = pd.to_numeric(d.home_odds, errors='coerce')
    ao = pd.to_numeric(d.away_odds, errors='coerce')
    sd = pd.to_numeric(d.h_score, errors='coerce') - pd.to_numeric(d.a_score, errors='coerce')
    lead_home = sd > 0
    fav = pd.Series(np.where(ho <= ao, ho, ao), index=d.index)
    dog = pd.Series(np.where(ho <= ao, ao, ho), index=d.index)
    lose = pd.Series(np.where(lead_home, ao, ho), index=d.index)
    out = pd.DataFrame({'match_id': d.match_id, 'ts': d.ts})
    for nm, ser in (('fav', fav), ('dog', dog), ('loser', lose)):
        s = ser.groupby(d.match_id)
        prev = s.shift(1)
        first = s.transform('first')
        out[f'{nm}_odds_trend'] = (ser - prev) / prev.replace(0, np.nan) * 100
        out[f'{nm}_odds_momentum_pct'] = (ser - first) / first.replace(0, np.nan) * 100
        out[f'{nm}_odds_vol'] = s.transform(lambda x: x.rolling(8, min_periods=3).std())
    med = lose.groupby(d.match_id).transform('median')
    hi = (lose > med).astype(int)
    grp = (hi != hi.groupby(d.match_id).shift(1)).cumsum()
    out['consec_loser_odds_high'] = hi.groupby([d.match_id, grp]).cumsum()
    lc = next((c for c in ('total_goals_handicap_ffill', 'total_goals_handicap') if c in d.columns), None)
    if lc:
        ln = pd.to_numeric(d[lc], errors='coerce')
        s = ln.groupby(d.match_id)
        out['total_line_vel'] = ln - s.shift(1)
        out['line_flat'] = s.transform(lambda x: x.rolling(10, min_periods=3).std())
        out['line_drift_from_open'] = ln - s.transform('first')
    return (out, [c for c in out.columns if c not in ('match_id', 'ts')])

def legacy_features__armed_extras(t):
    """Need / projection / tendency, computed on the armed table."""
    t = t.copy()
    new = []
    g = lambda c: pd.to_numeric(t[c], errors='coerce') if c in t.columns else pd.Series(np.nan, index=t.index)

    def put(k, v):
        t[k] = v
        new.append(k)
    hs, as_ = (g('h_score'), g('a_score'))
    sd = hs - as_
    tot = g('tg') if 'tg' in t.columns else g('run_tot') if 'run_tot' in t.columns else hs + as_
    el = next((g(c) for c in ('prog', 'frac', 'prog_t') if c in t.columns), pd.Series(0.5, index=t.index))
    line = next((g(c) for c in ('total_goals_handicap_ffill', 'total_goals_handicap', 'open_line') if c in t.columns), pd.Series(np.nan, index=t.index))
    put('sd_abs', sd.abs())
    put('prog_score', tot / line.replace(0, np.nan))
    put('pace_ratio', tot / el.clip(0.02, 1) / line.replace(0, np.nan))
    put('need_frac', sd.abs() / (line - tot).clip(0.1, None))
    put('proj_gap_n', tot / el.clip(0.02, 1) - line)
    for w in (5, 10, 20):
        a, b = (f'hp_winrate_l{w}g', f'ap_winrate_l{w}g')
        if a in t.columns and b in t.columns:
            put(f'player_tend_{w}', pd.concat([g(a), g(b)], axis=1).max(axis=1))
    if 'u_open' in t.columns:
        put('u_flat', (line - g('u_open')).abs())
    return (t, [c for c in new if pd.to_numeric(t[c], errors='coerce').notna().mean() > 0.35])

def legacy_features__screen_split(T, cols, is_mask, min_n=150):
    """IS/OOS-SPLIT SCREENING of a feature family.

    Screening a family on the pooled sample lets OOS outcomes decide which
    families enter the pool at all. Every candidate is scored on IS and the OOS
    figure is reported alongside WITHOUT being used to rank -- a family whose
    sign flips between halves is a period effect, not a mechanism.
    """
    import numpy as _np, pandas as _pd
    y = T['_won'].values.astype(float)
    o = T['_o'].values.astype(float)
    rows = []
    for c in cols:
        if c not in T.columns:
            continue
        v = _pd.to_numeric(T[c], errors='coerce')
        if v.notna().mean() < 0.4:
            continue
        cuts = legacy_features__candidate_cuts(c) or [(op, q) for q in _np.nanquantile(v.dropna(), [0.2, 0.5, 0.8]) for op in ('>=', '<=')]
        for op, q in cuts:
            m = _np.nan_to_num(v >= q if op == '>=' else v <= q if op == '<=' else v == q, nan=False).astype(bool)
            if (m & is_mask).sum() < min_n or (m & ~is_mask).sum() < min_n // 2:
                continue
            rI = (y[m & is_mask] * o[m & is_mask] - 1).mean() * 100
            rO = (y[m & ~is_mask] * o[m & ~is_mask] - 1).mean() * 100
            rows.append(dict(condition=f'{c} {op} {q:g}', bets=int(m.sum()), IS_win=round(y[m & is_mask].mean() * 100, 1), OOS_win=round(y[m & ~is_mask].mean() * 100, 1), IS_roi=round(rI, 1), OOS_roi=round(rO, 1), sign_agrees=(rI > 0) == (rO > 0)))
    d = _pd.DataFrame(rows)
    return d.sort_values('IS_roi', ascending=False) if len(d) else d

def legacy_features__candidate_cuts(col):
    """The author-chosen cut points for a column, if the engine has any."""
    out = []
    for src in (legacy_features__LEGACY_CUTS, legacy_features__POOL_CUTS):
        for op, val in src.get(col, []):
            o = '>=' if op in ('>=', '>') else '<=' if op in ('<=', '<') else '=='
            out.append((o, float(val)))
    return out
