# ==========================================================================
# LAZ_BRAIN MODULE: laz_families
# §laz_families   <- grep this anchor to land here
# OBJECTIVE : EVERY STRATEGY BELONGS TO A FAMILY
# PURPOSE   : Mode 1 optimises all families and Mode 5 picks one, so an unassigned strategy is invisible to both.
# HOW       : Assignment by MECHANISM in priority order — a period-gated term outranks everything because the gate governs when the bet may exist; a manufactured lead term is MANUFACTURED whatever its parents describe.
# VALUE     : 1,418 assignments across 16 families. MARGIN_RATE has the best median ROI in the book at +37.3% and is entirely book-created with no legacy ancestors.
# IF SKIPPED: Families cannot be optimised or explored.
# ==========================================================================
"""laz_families.py — ROUND 3: EVERY STRATEGY BELONGS TO A FAMILY.

A family is what a strategy IS, not where it came from. Mode 1 optimises "all
families for that sport" and Mode 5 picks one to explore, so an unassigned
strategy is invisible to both. The taxonomy is declared in LAZ_OWNER; this
assigns to it and refuses to invent a new one.

ASSIGNMENT IS BY MECHANISM, in priority order. A strategy led by a manufactured
condition is MANUFACTURED whatever its parents describe, because that is what
must be rebuilt first. A period-gated term outranks everything else, because
the gate governs when the bet may exist at all.
"""
import re
import numpy as np, pandas as pd

def laz_families___laz_home():
    """The directory this run writes to. Defaults to the CURRENT directory,
    never the container the engine was built in. _laz_home() shipped inside
    the single file and every write failed on the operator's machine with
    FileNotFoundError after the search had already run."""
    import os as _o
    OW = _m('laz_owner') if '_m' in globals() else None
    if OW is not None:
        d = (getattr(OW, 'LAZ_OWNER', {}).get('paths', {}) or {}).get('output_dir')
        if d:
            return d
    return _o.environ.get('LAZ_HOME') or _o.getcwd()

def laz_families___owner():
    return _m('laz_owner')

def laz_families___terms(cond):
    out = []
    for x in str(cond).split(' AND '):
        x = x.strip()
        m = re.match('^([\\d.\\-eE]+)\\s*<=\\s*(.+?)\\s*<=\\s*([\\d.\\-eE]+)$', x)
        t = (m.group(2) if m else x.rsplit(' ', 2)[0]).strip()
        if t and (not t.replace('.', '').replace('-', '').isdigit()):
            out.append(t)
    return out
laz_families__RULES = [('PERIOD_WINNER', lambda t, b, c: any((x.lower().startswith(('q1_', 'h1_', 'ht_', 'set1_')) for x in t)) or str(b) in ('q1_winner', 'h1_winner', 'set1_winner')), ('WALL_UNDER', lambda t, b, c: str(b) == 'wall_under' or 'wall' in str(c).lower() or any(('total_goals_under' in x for x in t))), ('MANUFACTURED', lambda t, b, c: bool(t) and str(t[0]).lower().startswith('x_')), ('MARGIN_RATE', lambda t, b, c: any(('margin_rate' in x.lower() or 'lead_per_remaining' in x.lower() for x in t))), ('DRIFT', lambda t, b, c: str(b) in ('DRIFTED', 'SHORTENED') or any(('drift' in x.lower() or 'anchor' in x.lower() for x in t))), ('PREMATCH_DOG', lambda t, b, c: str(b) in ('pm_underdog', 'dog_leading', 'DogUpSet1') or any((x.lower().startswith(('pm_dog', 'dog_')) for x in t))), ('PREMATCH_FAV', lambda t, b, c: str(b) in ('pm_favourite', 'fav_trailing', 'fgs_favourite') or any((x.lower().startswith(('pm_fav', 'prematch_fav')) for x in t))), ('LIVE_TRAILER', lambda t, b, c: str(b) == 'trail_ml' or any(('loser' in x.lower() or 'trail' in x.lower() for x in t))), ('LINE', lambda t, b, c: bool(t) and all(('handicap' in x.lower() or 'open_line' in x.lower() or 'line_gap' in x.lower() or ('total_goals_over' in x.lower()) or ('u_open' in x.lower()) or ('l_move' in x.lower()) for x in t))), ('CLOCK', lambda t, b, c: bool(t) and all((x.lower() in ('minute', 'hour', 'prog', 'frac', 'remain', 'u_elapsed', 'u_remain', 'sets', 'period', 'quarter') or x.lower().startswith(('u_elapsed', 'u_remain')) for x in t))), ('PACE_TOTAL', lambda t, b, c: any(('pace' in x.lower() or 'proj' in x.lower() or 'u_total' in x.lower() or ('tg' == x.lower()) or ('req_rate' in x.lower()) for x in t))), ('FORM_H2H', lambda t, b, c: any(('h2h' in x.lower() or '_wr' in x.lower() or 'elo' in x.lower() or ('winrate' in x.lower()) or ('games_24h' in x.lower()) for x in t))), ('MARKET_SHAPE', lambda t, b, c: any(('overround' in x.lower() or 'ratio' in x.lower() or 'imbal' in x.lower() or ('vf_' in x.lower()) or ('imp_' in x.lower()) or ('spread' in x.lower()) or ('odds' in x.lower()) for x in t))), ('LIVE_LEADER', lambda t, b, c: str(b) in ('lead_ml', 'q4_moneyline', 'late') or any(('lead' in x.lower() or 'u_margin' in x.lower() or 'score' in x.lower() for x in t)))]

def laz_families__classify(conditions, base=None, note=''):
    """Return (family, why)."""
    OW = laz_families___owner()
    fams = OW.LAZ_OWNER['families']
    t = laz_families___terms(conditions)
    for fam, test in laz_families__RULES:
        try:
            hit = test(t, base, f'{conditions} {note}')
        except Exception:
            hit = False
        if hit:
            if fam not in fams:
                return ('UNCLASSIFIED', f'rule produced {fam}, not in the declared taxonomy')
            lead = t[0] if t else '(no term)'
            return (fam, f'led by `{lead}`, base `{base}`')
    return ('UNCLASSIFIED', 'no rule matched')

def laz_families__assign(book, cond_col='conditions', base_col='base'):
    """Assign every row. Returns the book with family and family_reason."""
    fams = []
    whys = []
    for _, r in book.iterrows():
        f, w = laz_families__classify(r.get(cond_col, ''), r.get(base_col))
        fams.append(f)
        whys.append(w)
    b = book.copy()
    b['family'] = fams
    b['family_reason'] = whys
    return b

def laz_families__assign_legacy(seeds_json=__import__('os').path.join(laz_families___laz_home(), 'legacy_seeds.json')):
    """The 663 engine specs, mapped onto the same taxonomy."""
    import json, os
    if not os.path.exists(seeds_json):
        return pd.DataFrame()
    d = _laz_json_read(seeds_json)
    rows = []
    for p in d['specs']:
        name = p.get('name', '')
        bh = p.get('base_hint')
        mk = p.get('market', 'moneyline')
        pseudo = f'{name} {p.get('family', '')} {mk}'
        f, w = laz_families__classify(pseudo, bh, note=mk)
        if f == 'UNCLASSIFIED':
            f = 'LEGACY'
            w = 'engine legacy spec, no mechanism recoverable from the name'
        rows.append(dict(name=name, engine_family=p.get('family'), market=mk, base_hint=bh, family=f, family_reason=w))
    return pd.DataFrame(rows)

def laz_families__report(book):
    g = book.groupby('family').agg(n=('family', 'size'))
    if 'oos_win' in book.columns:
        g['best_oos'] = book.groupby('family').oos_win.max()
        g['med_odds'] = book.groupby('family').odds.median()
        g['med_roi'] = book.groupby('family').oos_roi.median()
    return g.sort_values('n', ascending=False)
