"""laz_ratio.py — TIER, PORTFOLIO, ROLE, RATIO — and the five analyses that INFORM.

ABSORBED from LazarusEV_Engine_v117_MERGED (laz_ratio): ratio, required_odds,
grade. Measured there across 137 validated strategies: worst-fold ROI rises
monotonically with ratio = paid_odds x win_rate and with nothing else.

EXTENDED here: the portfolios are the ELEVEN TIER WINDOWS, so a strategy's
tier and its portfolio are the same fact. Five ROLES sit beside the tier.
Five analyses — isotonic calibration, drawdown survival, sequential stopping,
Benjamini-Hochberg ordering, measured leg correlation — each ADD A COLUMN, A
RANK OR A STOPPING POINT.

THE RULE: nothing in this module rejects, drops or gates a strategy. The gate
is n>=100 IS, n>=100 OOS, OOS ROI>=15, odds>=floor, no forward term — and it
lives in laz_cascades.accept(). Interval gating (Wilson) was tried for five
days, removed strategies that perform in production, and is banned by name.
"""
import numpy as np, pandas as pd
laz_ratio__FIT_TOLERANCE = 0.15
laz_ratio__SIX_STAR_MARGIN = 6.0

def laz_ratio__ratio(win_rate, odds):
    """paid / breakeven. Above 1 is +EV and the margin IS the number."""
    wr = float(win_rate)
    if wr > 1.0:
        wr /= 100.0
    return float(odds) * wr

def laz_ratio__required_odds(win_rate):
    """Minimum odds that make a win rate survivable: breakeven x 1.4.

    A VARIANCE rule, not an EV rule. At p=0.20 a 95th-percentile losing run is
    31 bets; the payout has to be large enough that recovery is a small number
    of wins, not a season. Measured across the ladder, breakeven x 1.4 holds
    'wins to recover' near 5-6 at every strike rate, which is the trade the
    operator actually makes.
    """
    wr = float(win_rate)
    if wr > 1.0:
        wr /= 100.0
    wr = max(wr, 0.01)
    return round(1.0 / wr * 1.4, 2)

def laz_ratio__grade(portfolio, ratio, odds, tolerance=None):
    """CORE_FIT / ADEQUATE / MARGINAL / SUB_EV."""
    tol = laz_ratio__FIT_TOLERANCE if tolerance is None else tolerance
    P = laz_ratio__portfolios().get(portfolio)
    if P is None or laz_ratio__ratio != laz_ratio__ratio or odds != odds:
        return 'UNPLACED'
    if laz_ratio__ratio <= 1.0:
        return 'SUB_EV'
    if odds >= P['min_odds'] and laz_ratio__ratio >= P['min_ratio']:
        return 'CORE_FIT'
    if odds >= P['min_odds'] * (1 - tol) and laz_ratio__ratio >= P['min_ratio'] * (1 - tol):
        return 'ADEQUATE'
    return 'MARGINAL'

def laz_ratio__portfolios():
    OW = _m('laz_owner')
    T = OW.LAZ_OWNER['combination']['tiers'] if OW else {}
    out = {}
    for name, sp in T.items():
        lo = float(sp.get('min_win', 0))
        hi = float(sp.get('max_win', 100))
        target = (lo + hi) / 2.0
        out[name] = dict(wr_lo=lo, wr_hi=hi, target_wr=target, min_odds=round(100.0 / max(lo, 1.0) * 1.4, 2) if lo < 95 else 1.05, min_ratio=round(1.02 + 0.3 * (1 - lo / 100.0), 2), max_legs=sp.get('max_legs'), role='stacks to %s' % sp.get('max_legs') if sp.get('max_legs') else 'singles only')
    return out

def laz_ratio__portfolio_of(win_rate):
    wr = float(win_rate)
    wr = wr * 100 if wr <= 1.0 else wr
    P = laz_ratio__portfolios()
    best = None
    for name, p in P.items():
        if p['wr_lo'] <= wr < p['wr_hi'] or (p['wr_hi'] >= 100 and p['wr_lo'] <= wr <= p['wr_hi']):
            if best is None or p['wr_lo'] > P[best]['wr_lo']:
                best = name
    return best

def laz_ratio__grade_row(win_rate, odds):
    """CORE_FIT / ADEQUATE / MARGINAL / SUB_EV — a grade, never a filter."""
    P = laz_ratio__portfolios()
    name = laz_ratio__portfolio_of(win_rate)
    if name is None:
        return 'UNPLACED'
    p = P[name]
    r = laz_ratio__ratio(win_rate, odds)
    o = float(odds)
    if r != r or o != o:
        return 'UNPLACED'
    if r <= 1.0:
        return 'SUB_EV'
    if o >= p['min_odds'] and r >= p['min_ratio']:
        return 'CORE_FIT'
    if o >= p['min_odds'] * (1 - laz_ratio__FIT_TOLERANCE) and r >= p['min_ratio'] * (1 - laz_ratio__FIT_TOLERANCE):
        return 'ADEQUATE'
    return 'MARGINAL'

def laz_ratio__role_of(rec, segments=None, fold_win=None, fold_slips=0, drift=None):
    """One of ANVIL / GLASS / SPARK / BINDER / LONER / STEADY / UNASSIGNED.
    Precedence GLASS > LONER > BINDER > ANVIL > SPARK, from LAZ_OWNER['roles'].
    Informs; never gates."""
    OW = _m('laz_owner')
    R = OW.LAZ_OWNER['combination'].get('roles', {}) if OW else {}
    w = float(rec.get('oos_win') or 0)
    n = int(rec.get('bets') or 0)
    roi = float(rec.get('oos_roi') or 0)
    r = laz_ratio__ratio(w, float(rec.get('odds') or 0))
    hits = []
    g = R.get('GLASS', {})
    if w >= g.get('min_recorded_win', 80) and drift is not None and (drift <= g.get('drift_pts', -10)):
        hits.append(('GLASS', g.get('prec', 1)))
    if fold_win is not None and fold_slips >= R.get('LONER', {}).get('min_slips', 30):
        l = R.get('LONER', {})
        if w >= l.get('min_single_win', 80) and fold_win - w <= l.get('fold_minus_single_pts', -15) and (r >= l.get('min_ratio', 1.05)):
            hits.append(('LONER', l.get('prec', 2)))
        b = R.get('BINDER', {})
        if fold_win - w >= b.get('fold_minus_single_pts', 10) and r >= b.get('min_ratio', 1.05):
            hits.append(('BINDER', b.get('prec', 3)))
    a = R.get('ANVIL', {})
    if segments and n >= a.get('min_bets', 300) and (r >= a.get('min_ratio', 1.05)):
        vals = [v for v in segments.values() if v == v]
        if vals and max(vals) - min(vals) <= 2 * a.get('segment_tolerance_pts', 3.0):
            hits.append(('ANVIL', a.get('prec', 4)))
    s = R.get('SPARK', {})
    if roi >= s.get('min_oos_roi', 40) and s.get('bets_lo', 100) <= n < s.get('bets_hi', 200) and (r >= s.get('min_ratio', 1.2)):
        hits.append(('SPARK', s.get('prec', 5)))
    if hits:
        return sorted(hits, key=lambda h: h[1])[0][0]
    if segments is None and fold_win is None and (drift is None):
        return 'UNASSIGNED'
    return 'STEADY'

def laz_ratio__spec(rec, **kw):
    """tier · portfolio · role · ratio · required_odds · fit — one line per strategy."""
    CB = _m('laz_combina')
    w = float(rec.get('oos_win') or 0)
    o = float(rec.get('odds') or 0)
    tier = CB.tier_of(w)[0] if CB else None
    return dict(tier=tier, portfolio=laz_ratio__portfolio_of(w), role=laz_ratio__role_of(rec, **kw), ratio=round(laz_ratio__ratio(w, o), 3), required_odds=laz_ratio__required_odds(w), fit_grade=laz_ratio__grade_row(w, o))

def laz_ratio__isotonic(price, won, min_n=100, bands=6):
    """Monotone fit of hit rate vs price over a strategy's OWN ledger. Needs
    >=min_n bets (the IS/OOS rule); below it returns 'insufficient'. Adds
    calib_slope, calib_at_floor, calib_at_ceiling, price_band_best. Informs."""
    p = np.asarray(price, float)
    y = np.asarray(won, float)
    ok = np.isfinite(p) & np.isfinite(y)
    p = p[ok]
    y = y[ok]
    if len(p) < min_n:
        return dict(calib='insufficient')
    q = np.quantile(p, np.linspace(0, 1, bands + 1))
    q[-1] += 1e-09
    idx = np.clip(np.searchsorted(q, p, side='right') - 1, 0, bands - 1)
    rate = np.array([y[idx == b].mean() if (idx == b).any() else np.nan for b in range(bands)])
    r = rate.copy()
    w_ = np.array([(idx == b).sum() for b in range(bands)], float)
    i = 0
    while i < len(r) - 1:
        if r[i] < r[i + 1]:
            m = (r[i] * w_[i] + r[i + 1] * w_[i + 1]) / max(w_[i] + w_[i + 1], 1)
            r[i] = r[i + 1] = m
            w_[i] = w_[i + 1] = w_[i] + w_[i + 1]
            i = max(i - 1, 0)
        else:
            i += 1
    best = int(np.nanargmax(r * ((q[:-1] + q[1:]) / 2))) if np.isfinite(r).any() else 0
    return dict(calib='fit', calib_slope=round(float((r[-1] - r[0]) / max(q[-1] - q[0], 1e-09)), 4), calib_at_floor=round(100 * float(r[0]), 1), calib_at_ceiling=round(100 * float(r[-1]), 1), price_band_best=f'{q[best]:.2f}-{q[best + 1]:.2f}', price_band_best_hit=round(100 * float(r[best]), 1))

def laz_ratio__drawdown_survival(profit):
    """Every drawdown episode's depth and bets-to-recovery. dd_p95_recovery_bets
    replaces 'max drawdown' with '95% of drawdowns recover within N bets'."""
    pr = np.asarray(profit, float)
    pr = pr[np.isfinite(pr)]
    if not len(pr):
        return dict(dd_episodes=0)
    cum = np.cumsum(pr)
    peak = np.maximum.accumulate(cum)
    dd = cum - peak
    episodes = []
    start = None
    for i, d in enumerate(dd):
        if d < 0 and start is None:
            start = i
        if d >= 0 and start is not None:
            episodes.append((float(dd[start:i].min()), i - start))
            start = None
    open_len = len(dd) - start if start is not None else 0
    lens = [e[1] for e in episodes]
    return dict(dd_episodes=len(episodes), dd_max=round(float(dd.min()), 2), dd_p95_recovery_bets=int(np.percentile(lens, 95)) if lens else 0, dd_median_recovery_bets=int(np.median(lens)) if lens else 0, dd_open=bool(start is not None), dd_open_bets=int(open_len))

def laz_ratio__should_stop(novel_so_far, attempts_so_far, target, recent_novel, recent_attempts, pool_has_more):
    """Stop when the target is met AND recent yield has fallen below the run's
    own rate. If the pool still has more and yield holds, continue. A stopping
    rule for the SEARCH — never a verdict on a strategy."""
    if target is None or target <= 0:
        return (False, 'no target')
    if novel_so_far < target:
        return (False, f'{novel_so_far}/{target} novel')
    overall = novel_so_far / max(attempts_so_far, 1)
    recent = recent_novel / max(recent_attempts, 1)
    if pool_has_more and recent >= 0.5 * overall:
        return (False, f'target reached — continuing while yield holds ({recent:.2%} vs run {overall:.2%})')
    return (True, f'target reached ({novel_so_far}/{target}) and yield has fallen ({recent:.2%} vs run {overall:.2%})')

def laz_ratio__bh_qvalues(pvals):
    """q-values from BH. Adds q_value and fdr_rank. Never filters."""
    p = np.asarray(pvals, float)
    n = len(p)
    order = np.argsort(p)
    ranked = p[order]
    q = np.empty(n)
    prev = 1.0
    for i in range(n - 1, -1, -1):
        prev = min(prev, ranked[i] * n / (i + 1))
        q[order[i]] = prev
    return (np.clip(q, 0, 1), np.argsort(np.argsort(q)) + 1)

def laz_ratio__pair_phi(slips, min_shared=30):
    """PHI COEFFICIENT between two strategies' outcomes on the slips they shared — a real 2x2
    association measure. D52: the previous body returned 2*p-1 where p was the joint-win rate:
    two INDEPENDENT 90% legs scored 0.62 and read as strong association where phi is 0.
    Phi = (n11*n00 - n10*n01) / sqrt(n1.*n0.*n.1*n.0), in [-1, 1], 0 = independent."""
    import itertools
    out = {}
    if slips is None or not len(slips) or 'legs' not in slips.columns:
        return out
    lwcol = next((c for c in ('leg_won', 'won_legs', 'legs_won') if c in slips.columns), None)
    if lwcol is None:
        return out
    pairs = {}
    for _, r in slips.iterrows():
        legs = str(r['legs']).split('|')
        lw = r[lwcol]
        try:
            lwv = [int(x) for x in (str(lw).split('|') if isinstance(lw, str) else list(lw))]
        except Exception:
            continue
        if len(lwv) != len(legs) or len(legs) < 2:
            continue
        for (i1, a), (i2, b) in itertools.combinations(enumerate(legs), 2):
            k = tuple(sorted((a, b)))
            wa, wb = (lwv[i1], lwv[i2]) if k == (a, b) else (lwv[i2], lwv[i1])
            c = pairs.setdefault(k, [0, 0, 0, 0])
            c[2 * wa + wb] += 1
    for k, (n00, n01, n10, n11) in pairs.items():
        n = n00 + n01 + n10 + n11
        if n < min_shared:
            continue
        den = np.sqrt(float((n11 + n10) * (n01 + n00) * (n11 + n01) * (n10 + n00)))
        out[k] = round(float((n11 * n00 - n10 * n01) / den), 3) if den > 0 else 0.0
    return out

