# ── DEPTH RULES ──────────────────────────────────────────────────────────────────────────────────────
# Each takes the depth ladder L = [dict(depth, n_is, n_oos, oos_win, oos_roi, is_roi, odds) …] for one strategy and
# returns (chosen_depth or None, verdict_text). The journal records every rule's verdict; the sweep's own greedy
# result is 'greedy_stack'. A strategy ships at the depth the MAJORITY of applicable rules choose; ties go shallower.
def laz_propose___dr_first_valid(L):
    v = [r for r in L if r['n_is'] >= 100 and r['n_oos'] >= 100 and r['oos_roi'] > 0]
    return (v[0]['depth'], 'shallowest depth that clears the gate') if v else (None, 'no depth clears')
def laz_propose___dr_best_roi(L):
    v = [r for r in L if r['n_oos'] >= 100]
    return (max(v, key=lambda r: r['oos_roi'])['depth'], 'max OOS ROI at n_oos>=100') if v else (None, 'none')
def laz_propose___dr_best_win(L):
    v = [r for r in L if r['n_oos'] >= 100]
    return (max(v, key=lambda r: r['oos_win'])['depth'], 'max OOS win at n_oos>=100') if v else (None, 'none')
def laz_propose___dr_marginal_2pt(L):
    c = None; prev = None
    for r in L:
        if r['n_oos'] < 100:
            break
        if prev is None or r['oos_win'] - prev['oos_win'] >= 2.0:
            c = r['depth']
        else:
            break
        prev = r
    return (c, 'stop when the next condition adds < 2 win pts')
def laz_propose___dr_marginal_roi(L):
    c = None; prev = None
    for r in L:
        if r['n_oos'] < 100:
            break
        if prev is None or r['oos_roi'] > prev['oos_roi']:
            c = r['depth']
        else:
            break
        prev = r
    return (c, 'stop when OOS ROI stops rising')
def laz_propose___dr_volume_half(L):
    base = L[0]['n_oos'] if L else 0
    v = [r for r in L if r['n_oos'] >= max(100, base * 0.5) and r['oos_roi'] > 0]
    return (v[-1]['depth'], 'deepest depth keeping >= 50% of depth-1 volume') if v else (None, 'none')
def laz_propose___dr_is_oos_agree(L):
    v = [r for r in L if r['n_oos'] >= 100 and abs(r['oos_win'] - r.get('is_win', r['oos_win'])) <= 5.0]
    return (v[-1]['depth'], 'deepest depth where IS and OOS win agree within 5 pts') if v else (None, 'IS/OOS diverge at every depth')
def laz_propose___dr_odds_stable(L):
    v = [r for r in L if r['n_oos'] >= 100 and abs(r['odds'] - L[0]['odds']) / max(L[0]['odds'], 1e-9) <= 0.15]
    return (v[-1]['depth'], 'deepest depth whose mean odds stay within 15% of depth 1') if v else (None, 'odds drift')
def laz_propose___dr_max_three(L):
    v = [r for r in L if r['depth'] <= 3 and r['n_oos'] >= 100 and r['oos_roi'] > 0]
    return (max(v, key=lambda r: r['oos_roi'])['depth'], 'best ROI at depth <= 3 (production simplicity)') if v else (None, 'none')
def laz_propose___dr_stackable_75(L):
    v = [r for r in L if r['n_oos'] >= 100 and r['oos_win'] >= 75]
    return (v[0]['depth'], 'shallowest depth reaching the 75% stackable floor') if v else (None, 'never stackable')
def laz_propose___dr_ultra_90(L):
    v = [r for r in L if r['n_oos'] >= 100 and r['oos_win'] >= 90]
    return (v[0]['depth'], 'shallowest depth reaching Ultra (90%)') if v else (None, 'never Ultra')
def laz_propose___dr_roi_15(L):
    v = [r for r in L if r['n_oos'] >= 100 and r['oos_roi'] >= 15]
    return (v[0]['depth'], 'shallowest depth at the 15% stacking floor') if v else (None, 'never 15%')
def laz_propose___dr_ev_per_bet(L):
    v = [r for r in L if r['n_oos'] >= 100]
    return (max(v, key=lambda r: (r['oos_win'] / 100) * r['odds'] - 1)['depth'], 'max expected value per bet') if v else (None, 'none')
def laz_propose___dr_profit_total(L):
    v = [r for r in L if r['n_oos'] >= 100]
    return (max(v, key=lambda r: r['n_oos'] * ((r['oos_win'] / 100) * r['odds'] - 1))['depth'], 'max total OOS profit (edge x volume)') if v else (None, 'none')
def laz_propose___dr_no_drop(L):
    c = None
    for r in L:
        if r['n_oos'] < 100 or r['oos_roi'] <= 0:
            break
        c = r['depth']
    return (c, 'deepest depth before any gate fails')
def laz_propose___dr_parsimony(L):
    v = [r for r in L if r['n_oos'] >= 100 and r['oos_roi'] > 0]
    if not v:
        return (None, 'none')
    best = max(v, key=lambda r: r['oos_roi'])['oos_roi']
    w = [r for r in v if r['oos_roi'] >= best - 2.0]
    return (w[0]['depth'], 'shallowest depth within 2 ROI pts of the best')
laz_propose__DEPTH_RULES = [('first_valid', laz_propose___dr_first_valid), ('best_roi', laz_propose___dr_best_roi), ('best_win', laz_propose___dr_best_win),
                            ('marginal_2pt', laz_propose___dr_marginal_2pt), ('marginal_roi', laz_propose___dr_marginal_roi), ('volume_half', laz_propose___dr_volume_half),
                            ('is_oos_agree', laz_propose___dr_is_oos_agree), ('odds_stable', laz_propose___dr_odds_stable), ('max_three', laz_propose___dr_max_three),
                            ('stackable_75', laz_propose___dr_stackable_75), ('ultra_90', laz_propose___dr_ultra_90), ('roi_15', laz_propose___dr_roi_15),
                            ('ev_per_bet', laz_propose___dr_ev_per_bet), ('profit_total', laz_propose___dr_profit_total), ('no_drop', laz_propose___dr_no_drop), ('parsimony', laz_propose___dr_parsimony)]

def laz_propose__assess_depths(ladder):
    """Apply every depth rule to one strategy's ladder. Returns dict(rule -> (depth, why)) plus the majority choice."""
    out = {}
    for name, fn in laz_propose__DEPTH_RULES:
        try:
            out[name] = fn(ladder)
        except Exception as e:
            out[name] = (None, f'{type(e).__name__}')
    votes = [v[0] for v in out.values() if v[0] is not None]
    chosen = None
    if votes:
        from collections import Counter
        c = Counter(votes); top = max(c.values()); chosen = min(k for k, v in c.items() if v == top)
    out['__chosen__'] = (chosen, f'{len(votes)} of {len(laz_propose__DEPTH_RULES)} rules voted; majority {chosen}, ties shallower')
    return out


# ── THE CONTEXT every builder receives ───────────────────────────────────────────────────────────────
def laz_propose__context(sport, d, pool, ctx):
    """One dict of primitives, timestamp-based, that every feature/base/strategy builder reads. Built once per sport."""
    sp = str(sport).lower(); fam = laz_propose__FAMILY.get(sp, 'quarter')
    n = len(d); C = dict(sport=sp, family=fam, n=n)
    g = lambda c: pd.to_numeric(d[c], errors='coerce').values if c in d.columns else None
    C['g'] = g
    C['mid'] = pd.factorize(d['match_id'])[0]
    ts = pd.to_datetime(d['ts'] if 'ts' in d.columns else d['timestamp'], errors='coerce').values.astype('datetime64[ns]').astype('int64')
    C['ts'] = ts
    t0 = pd.Series(ts).groupby(C['mid']).transform('min').values
    C['elapsed_s'] = (ts - t0) / 1e9
    OW = _m('laz_owner'); nominal = float(((OW.LAZ_OWNER.get('match_seconds', {}) or {}) if OW else {}).get(sp, 0) or 0)
    C['nominal'] = nominal
    C['el'] = np.asarray(ctx.get('el'), float) if ctx.get('el') is not None else (C['elapsed_s'] / nominal if nominal else np.full(n, np.nan))
    C['remain_s'] = np.clip(nominal - C['elapsed_s'], 0, None) if nominal else np.full(n, np.nan)
    C['hs'], C['as'] = g('h_score'), g('a_score')
    C['ho'], C['ao'], C['do'] = g('home_odds'), g('away_odds'), g('draw_odds')
    C['sd'] = None if C['hs'] is None or C['as'] is None else C['hs'] - C['as']
    C['tot'] = None if C['hs'] is None else C['hs'] + C['as']
    C['ph'] = laz_propose___phases(d)
    # [AmunEV V2.13] the period clock (directive 2b/2c): period index, % of the period, % of the half, half index — past-only
    try:
        _lper, _lmin = laz_propose___league_format(sport, d)
        C['league_periods'] = _lper; C['league_period_min'] = _lmin
        _nom_s = float(nominal) if nominal else None
        C['period_idx'], C['prog_period'], C['prog_half'], C['half_idx'] = laz_propose___period_clock(C['mid'], C['ph'], C['elapsed_s'], C['family'], _nom_s, _lper)
    except Exception:
        C['league_periods'] = C['league_period_min'] = None
        C['period_idx'] = C['prog_period'] = C['prog_half'] = C['half_idx'] = None
    mid = C['mid']
    if C['ho'] is not None and C['ao'] is not None:
        C['imp_h'] = 1 / np.where(C['ho'] > 1, C['ho'], np.nan); C['imp_a'] = 1 / np.where(C['ao'] > 1, C['ao'], np.nan)
        C['open_h'] = pd.Series(C['ho']).groupby(mid).transform('first').values; C['open_a'] = pd.Series(C['ao']).groupby(mid).transform('first').values
        C['pm_fav'] = np.where(C['open_h'] <= C['open_a'], 'home', 'away')
        C['drift_h'] = C['ho'] / C['open_h']; C['drift_a'] = C['ao'] / C['open_a']
        C['imp_d'] = 1 / np.where(C['do'] > 1, C['do'], np.nan) if C['do'] is not None else None
    same = mid == np.roll(mid, 1); same[0] = False
    if C['sd'] is not None:
        sgn = np.sign(np.nan_to_num(C['sd'])); prev = np.roll(sgn, 1); prev[0] = 0
        C['lead_change'] = same & (sgn != prev) & (sgn != 0)
        C['score_change'] = same & (np.nan_to_num(C['tot']) != np.roll(np.nan_to_num(C['tot']), 1))
        C['home_scored'] = same & (np.nan_to_num(C['hs']) > np.roll(np.nan_to_num(C['hs']), 1))
        C['away_scored'] = same & (np.nan_to_num(C['as']) > np.roll(np.nan_to_num(C['as']), 1))
        C['secs_since_lead_change'] = laz_propose___secs_since_event(ts, mid, C['lead_change'])
        C['secs_since_score'] = laz_propose___secs_since_event(ts, mid, C['score_change'])
        C['lead_changes_300'] = laz_propose___count_window(ts, mid, C['lead_change'], 300)
        C['scores_120'] = laz_propose___count_window(ts, mid, C['score_change'], 120)
        C['scores_300'] = laz_propose___count_window(ts, mid, C['score_change'], 300)
        # the FIRST scorer, fixed from the goal event (owner's leader-as-intended)
        fs = np.full(n, np.nan); cur = None; v = np.nan
        for i in range(n):
            if mid[i] != cur:
                cur = mid[i]; v = np.nan
            if np.isnan(v) and C['score_change'][i] and C['sd'][i] != 0:
                v = 1.0 if C['sd'][i] > 0 else 0.0
            fs[i] = v
        C['first_scorer_home'] = fs
        C['ho_at_last_score'] = laz_propose___held_since(mid, C['score_change'], C['ho']) if C['ho'] is not None else None
        C['sd_at_last_score'] = laz_propose___held_since(mid, C['score_change'], C['sd'])
    # period boundaries (observed transitions) — per family
    ph = C['ph']; hs, as_ = C['hs'], C['as']
    if hs is not None:
        if fam == 'quarter':
            for key, inper in (('q1', np.isin(ph, ['q1'])), ('h1', np.isin(ph, ['q1', 'q2', 'ht'])), ('q3', np.isin(ph, ['q1', 'q2', 'ht', 'q3']))):
                if key + '_h' in pool:
                    C[key + '_h'], C[key + '_a'] = np.asarray(pool[key + '_h'], float), np.asarray(pool[key + '_a'], float)
                else:
                    C[key + '_h'], C[key + '_a'] = laz_propose___boundary(hs, as_, mid, inper)
            C['q2_h'] = C['h1_h'] - C['q1_h']; C['q2_a'] = C['h1_a'] - C['q1_a']
        elif fam == 'goal':
            if 'h1_h' in pool:
                C['h1_h'], C['h1_a'] = np.asarray(pool['h1_h'], float), np.asarray(pool['h1_a'], float)
            else:
                C['h1_h'], C['h1_a'] = laz_propose___boundary(hs, as_, mid, np.isin(ph, ['1h', 'ht']))
        elif fam == 'racquet':
            for k in (1, 2, 3):
                gh, ga = g(f'home_team_set{k}_score'), g(f'away_team_set{k}_score')
                C[f'games{k}_h'], C[f'games{k}_a'] = gh, ga
                # set k winner, observed at the transition out of set k (sets won increments)
                inper = np.isin(ph, [f's{j}' for j in range(1, k + 1)])
                C[f's{k}_h'], C[f's{k}_a'] = laz_propose___boundary(hs, as_, mid, inper)
            C['cur_set'] = pd.Series(ph).astype(str).str.extract(r's(\d)')[0].astype(float).values
        elif fam == 'esports':
            for k in (1, 2):
                inper = np.isin(ph, [f'm{j}' for j in range(1, k + 1)])
                C[f'm{k}_h'], C[f'm{k}_a'] = laz_propose___boundary(hs, as_, mid, inper)
            C['cur_map'] = pd.Series(ph).astype(str).str.extract(r'm(\d)')[0].astype(float).values
        C['fin_h'] = pd.Series(hs).groupby(mid).transform('last').values; C['fin_a'] = pd.Series(as_).groupby(mid).transform('last').values
    return C

