# ── BASES: (name, outcome, needs, fn(C) -> side array, min_price, hypothesis, evidence, expected) ──────
def _b(name, outcome, fn, minp, hyp, ev, exp): return dict(name=name, outcome=outcome, fn=fn, min_price=minp, hypothesis=hyp, evidence=ev, expected=exp)
def _lead(C, lo=0.0, hi=1.2, k=0): return np.where((C['el'] >= lo) & (C['el'] <= hi) & (C['sd'] > k), 'home', np.where((C['el'] >= lo) & (C['el'] <= hi) & (C['sd'] < -k), 'away', None))
def _trail(C, lo=0.0, hi=1.2, k=0): return np.where((C['el'] >= lo) & (C['el'] <= hi) & (C['sd'] < -k), 'home', np.where((C['el'] >= lo) & (C['el'] <= hi) & (C['sd'] > k), 'away', None))
def _fav(C, lo=0.0, hi=1.2): return np.where((C['el'] >= lo) & (C['el'] <= hi), C['pm_fav'], None)
def _dog(C, lo=0.0, hi=1.2): return np.where((C['el'] >= lo) & (C['el'] <= hi), np.where(C['pm_fav'] == 'home', 'away', 'home'), None)
def _period_lead(C, hk, ak, lo=0.0, hi=1.2):
    m = (C['hs'] - C[hk]) - (C['as'] - C[ak]); return np.where((C['el'] >= lo) & (C['el'] <= hi) & (m > 0), 'home', np.where((C['el'] >= lo) & (C['el'] <= hi) & (m < 0), 'away', None))
def _total_side(C, pace_key, line_col, margin=3.0):
    line = C['g'](line_col); p = C[pace_key] if pace_key in C else None
    if line is None or p is None: return np.full(C['n'], None, dtype=object)
    return np.where(p > line + margin, 'over', np.where(p < line - margin, 'under', None))
