# ── SETTLEMENT per outcome kind: (spec, C, side) -> (price, y, ok). The period's OBSERVED end score decides. ──
def laz_propose__settle(spec, C, side, fw):
    n = C['n']; g = C['g']; kind = spec['kind']; per = spec['period']
    side = np.asarray(side, dtype=object)
    ho, ao, do = g(spec.get('h')), g(spec.get('a')), (g(spec['d']) if spec.get('d') else None)
    hcap = g(spec['hcap']) if spec.get('hcap') else None
    nan = np.full(n, np.nan)
    # the period's home/away score at its observed end
    def period_scores():
        if per == 'match':
            return C['fin_h'], C['fin_a']
        if per == 'h1':
            return C['h1_h'], C['h1_a']
        if per == 'h2':
            return C['fin_h'] - C['h1_h'], C['fin_a'] - C['h1_a']
        if per == 'q1':
            return C['q1_h'], C['q1_a']
        if per == 'q2':
            return C['q2_h'], C['q2_a']
        if per == 'q3':
            return C['q3_h'] - C['h1_h'], C['q3_a'] - C['h1_a']
        if per == 'q4':
            return C['fin_h'] - C['q3_h'], C['fin_a'] - C['q3_a']
        if per in ('s1', 's2', 's3'):
            k = int(per[1]); gh, ga = C.get(f'games{k}_h'), C.get(f'games{k}_a')
            if gh is None:
                return nan, nan
            # the set's final games, observed at the transition out of the set
            inper = np.isin(C['ph'], [f's{j}' for j in range(1, k + 1)])
            return laz_propose___boundary(gh, ga, C['mid'], inper)
        if per in ('m1', 'm2'):
            k = int(per[1]); return (C[f'm{k}_h'] - (C.get(f'm{k-1}_h', 0) if k > 1 else 0)), (C[f'm{k}_a'] - (C.get(f'm{k-1}_a', 0) if k > 1 else 0))
        if per in ('m1h1', 'm1h2'):
            return nan, nan   # round-level half scores are not on the frame; registered, not settleable
        return nan, nan
    sh, sa = period_scores()
    # price by side
    price = np.where(side == 'home', ho if ho is not None else nan, np.where(side == 'away', ao if ao is not None else nan, np.where(side == 'draw', do if do is not None else nan, nan)))
    if kind in ('total', 'set_total', 'games_total', 'map_total', 'team_total'):
        price = np.where(side == 'over', ho if ho is not None else nan, np.where(side == 'under', ao if ao is not None else nan, nan))
    if kind in ('any_set_nil', 'overtime', 'btts', 'clean_sheet', 'win_to_nil', 'straight_sets', 'deciding_set', 'correct_score', 'odd_even', 'set_odd_even'):
        price = np.where(np.isin(side, ['yes', 'odd']), ho if ho is not None else nan, np.where(np.isin(side, ['no', 'even']), ao if ao is not None else nan, nan))
    # settle
    y = np.full(n, np.nan); push = np.zeros(n, bool)
    if kind in ('result', 'set_winner', 'map_winner', 'map_half'):
        win = np.where(sh > sa, 'home', np.where(sa > sh, 'away', 'draw'))
        y = np.where(pd.isna(side), np.nan, (win == side).astype(float))
        if per == 'match' and fw is not None:
            fwv = np.asarray(fw).astype(str)
            y = np.where(pd.isna(side), np.nan, (fwv == side.astype(str)).astype(float))
    elif kind == 'dnb':
        win = np.where(sh > sa, 'home', np.where(sa > sh, 'away', 'draw'))
        y = np.where(pd.isna(side), np.nan, (win == side).astype(float)); push = win == 'draw'
    elif kind in ('spread', 'set_spread', 'games_spread', 'map_spread'):
        adj = (sh - sa) + (hcap if hcap is not None else 0)
        y = np.where(side == 'home', (adj > 0).astype(float), np.where(side == 'away', (adj < 0).astype(float), np.nan)); push = adj == 0
    elif kind == 'spread3':
        adj = (sh - sa) + (hcap if hcap is not None else 0)
        y = np.where(side == 'home', (adj > 0).astype(float), np.where(side == 'away', (adj < 0).astype(float), np.where(side == 'draw', (adj == 0).astype(float), np.nan)))
    elif kind in ('total', 'set_total', 'games_total', 'map_total'):
        tot = sh + sa
        y = np.where(side == 'over', (tot > hcap).astype(float), np.where(side == 'under', (tot < hcap).astype(float), np.nan)) if hcap is not None else y; push = (tot == hcap) if hcap is not None else push
    elif kind == 'team_total':
        t = sh if spec.get('team') == 'home' else sa
        y = np.where(side == 'over', (t > hcap).astype(float), np.where(side == 'under', (t < hcap).astype(float), np.nan)) if hcap is not None else y; push = (t == hcap) if hcap is not None else push
    elif kind == 'first_scorer':
        fs = C.get('first_scorer_home')
        fin = np.where(C['fin_h'] > C['fin_a'], 'home', np.where(C['fin_a'] > C['fin_h'], 'away', 'draw'))
        y = np.where(pd.isna(side), np.nan, (fin == side).astype(float))   # priced by the moneyline; the side is the first scorer; wins if that side wins the match
    elif kind == 'btts':
        both = (C['fin_h'] > 0) & (C['fin_a'] > 0)
        y = np.where(side == 'yes', both.astype(float), np.where(side == 'no', (~both).astype(float), np.nan))
    elif kind == 'clean_sheet':
        cs = (C['fin_a'] == 0) if spec.get('team') == 'home' else (C['fin_h'] == 0)
        y = np.where(side == 'yes', cs.astype(float), np.where(side == 'no', (~cs).astype(float), np.nan))
    elif kind == 'win_to_nil':
        w = (C['fin_h'] > C['fin_a']) & (C['fin_a'] == 0) if spec.get('team') == 'home' else (C['fin_a'] > C['fin_h']) & (C['fin_h'] == 0)
        y = np.where(side == 'yes', w.astype(float), np.where(side == 'no', (~w).astype(float), np.nan))
    elif kind == 'straight_sets':
        w = (C['fin_h'] > 0) & (C['fin_a'] == 0) if spec.get('team') == 'home' else (C['fin_a'] > 0) & (C['fin_h'] == 0)
        y = np.where(side == 'yes', w.astype(float), np.where(side == 'no', (~w).astype(float), np.nan))
    elif kind == 'deciding_set':
        w = (C['fin_h'] + C['fin_a']) >= 3 if C['sport'] != 'tabletennis' else (C['fin_h'] + C['fin_a']) >= 5
        w = w & (np.abs(C['fin_h'] - C['fin_a']) == 1)
        y = np.where(side == 'yes', w.astype(float), np.where(side == 'no', (~w).astype(float), np.nan))
    elif kind == 'correct_score':
        sc = spec.get('score', (0, 0)); w = (C['fin_h'] == sc[0]) & (C['fin_a'] == sc[1])
        y = np.where(side == 'yes', w.astype(float), np.where(side == 'no', (~w).astype(float), np.nan))
    elif kind == 'any_set_nil':
        # any set won 6-0 (tennis) / 11-0 style — approximated: any set's loser games == 0 where recorded
        w = np.zeros(n, bool)
        for k in (1, 2, 3):
            gh, ga = C.get(f'games{k}_h'), C.get(f'games{k}_a')
            if gh is not None:
                inper = np.isin(C['ph'], [f's{j}' for j in range(1, k + 1)])
                eh, ea = laz_propose___boundary(gh, ga, C['mid'], inper)
                w |= ((eh > 0) & (ea == 0)) | ((ea > 0) & (eh == 0))
        y = np.where(side == 'yes', w.astype(float), np.where(side == 'no', (~w).astype(float), np.nan))
    elif kind in ('odd_even', 'set_odd_even'):
        tot = sh + sa; odd = (np.nan_to_num(tot) % 2) == 1
        y = np.where(side == 'odd', odd.astype(float), np.where(side == 'even', (~odd).astype(float), np.nan))
    elif kind == 'overtime':
        y = np.full(n, np.nan)   # needs a round count the frame does not carry
    y = np.where(push, 0.0, y); price = np.where(push, 1.0, price)
    ok = ~pd.isna(side) & np.isfinite(price) & (price > 1.0) & np.isfinite(y)
    return price, np.asarray(y, float), ok

# [v247 ALL-MODES] THE ONE-STOP STORE. prepare() calls enrich() once per sport (memoised with the pool), which runs
# the generative registry AND the reclamation and leaves everything any mode needs in laz_propose__LAST[sport]:
#   pool      the features are already IN the pool prepare() returns — Mode 1, 3, 5, BaseFinder, Hunt all see them
#   bases     the proposed bases, priced and settled on their outcome's period — every mode appends them to its own
#   seeds     the proposed strategies AND the reclaimed legacy strategies at every depth prefix — every mode seeds from them
#   rows      the propositions ledger (outcomes/features/bases/strategies/depth rules with status)
#   journal   the reclamation journal rows
# No mode-local name is referenced here (the audit's earlier finding); min_n comes from rules.min_n_is.
def laz_propose___enrich_impl(sport, d, pool, ctx, log=print):
    sp = str(sport).lower()
    out = dict(bases=[], seeds=[], rows=[], journal=[])
    try:
        _OWe = _m('laz_owner')
        _min_n = int(((_OWe.LAZ_OWNER.get('rules', {}) or {}) if _OWe else {}).get('min_n_is', 100) or 100)
    except Exception:
        _min_n = 100
    try:
        _B, _S, _R = laz_propose__generate(sp, d, pool, ctx, ctx.get('fw'), min_n=_min_n, log=log)
        out['bases'], out['seeds'], out['rows'] = _B, _S, _R
    except Exception as _e:
        log(f'  [propose] enrich/generate {sp}: {type(_e).__name__}: {str(_e)[:80]}')
    try:
        _side, _price, _fw = ctx.get('side'), ctx.get('price'), ctx.get('fw')
        if _side is not None and _price is not None and _fw is not None:
            _arm = ~pd.isna(np.asarray(_side, dtype=object)) & ~np.isnan(np.asarray(_price, float)) & laz_outcomes__valid(_fw)
            laz_reclaim__inventory(sp, pool=pool, d_cols=set(d.columns), log=log)
            _rs, _J, _ = laz_reclaim__seeds(sp, pool, _arm, ctx.get('el'), _min_n, log=log)
            out['seeds'] = list(out['seeds']) + list(_rs); out['journal'] = _J
    except Exception as _e:
        log(f'  [propose] enrich/reclaim {sp}: {type(_e).__name__}: {str(_e)[:80]}')
    laz_propose__LAST[sp] = out
    log(f"  [propose] {sp}: ONE-STOP — pool +{sum(1 for r in out['rows'] if r.get('kind') == 'feature' and r.get('status') == 'IN_POOL')} features · {len(out['bases'])} bases · {len(out['seeds'])} seeds (proposed + reclaimed, every depth prefix) · available to every mode")
    return out

