def laz_quarantine__is_state(name):
    """True for a name the review classes as STATE or EVENT — never a settlement column, whatever a frozenset says."""
    v = laz_quarantine__VERDICTS.get(str(name).lower())
    return bool(v and v['cls'] in ('STATE', 'EVENT'))

def laz_quarantine__report(log=print):
    from collections import Counter
    c = Counter(v['cls'] for v in laz_quarantine__VERDICTS.values())
    u = Counter(v['use'] for v in laz_quarantine__VERDICTS.values() if v['cls'] in ('STATE', 'EVENT'))
    _n_state_wired = sum(1 for k in laz_quarantine__VERDICTS if laz_quarantine__is_state(k))   # self-check: the wrapper agrees with the table
    log(f"  [quarantine] review: {len(laz_quarantine__VERDICTS)} names · {dict(c)} · of the STATE/EVENT ones: {dict(u)} · is_state() confirms {_n_state_wired}")
    return laz_quarantine__VERDICTS

