        _ix_make = int(ix_make) if ix_make else _ix_top
        log(f'  [mode3] GATE: n>={int(_oc.get('min_bets', min_n))} both halves · OOS ROI>={float(((_m('laz_owner').LAZ_OWNER.get('rules', {}) or {}) if _m('laz_owner') else {}).get('min_oos_roi', 0.0)):.1f}% (rules.min_oos_roi; combination.min_roi={float(_oc.get('min_roi', 15.0)):.0f}% is the STACKING floor only) · odds>={laz_mode3___min_odds()} · stackable at win>={float(_oc.get('min_win', min_win)) * 100:.0f}%')
        log(f'  [mode3] manufacturing budget: ' + (f'top {_ix_top} pairs' if _ix_top else 'UNCAPPED') + f' · materialise {_ix_make or 'all'}' + f' · second order {int(_oc.get('second_order_parents', 64))} parents')
        _EV = _m('laz_everything')
