def laz_mode5__summarise(sport=None, log=print):
    """What is new, what was disproved, what should be promoted."""
    E = laz_mode5__recall(sport)
    if not E:
        return pd.DataFrame()
    res = [e for e in E if e.get('kind') == 'result']
    ins = [e for e in E if e.get('kind') == 'insight']
    rows = [dict(finding='hypotheses tested', value=len(res)), dict(finding='expectations that HELD', value=sum((1 for e in res if e.get('expectation_held')))), dict(finding='expectations DISPROVED', value=sum((1 for e in res if not e.get('expectation_held')))), dict(finding='conditions profiled', value=len(ins))]
    for e in res[-5:]:
        rows.append(dict(finding=f'tried: {str(e.get('tried'))[:70]}', value=f'{('held' if e.get('expectation_held') else 'DISPROVED')} — {str(e.get('learned'))[:90]}'))
    S = pd.DataFrame(rows)
    if log:
        log('[mode5] SUMMARY')
        for _, r in S.iterrows():
            log(f'  {str(r.finding)[:64]:66s} {r.value}')
    return S

def laz_mode5__learned(sport=None, path=laz_mode5__BRAIN):
    """The brain as a frame: what was tried, whether the expectation held,
    what was learned. This is Mode 5's memory across runs."""
    E = laz_mode5__recall(sport, path)
    if not E:
        return pd.DataFrame()
    rows = []
    for e in E:
        rows.append(dict(ts=e.get('ts'), kind=e.get('kind'), sport=e.get('sport'), tried=e.get('tried') or e.get('condition'), why=e.get('why'), expectation_held=e.get('expectation_held'), learned=e.get('learned') or e.get('reading'), modules='|'.join(e.get('modules') or []), result=str(e.get('result'))[:200] if e.get('result') else None))
    return pd.DataFrame(rows)

def laz_mode5__parse_chain(conditions):
    """'a >= 1.5 AND b <= 3' -> [(term, op, value), ...]. Mode 5 mutates chains,
    so it must be able to take one apart."""
    import re as _re
    out = []
    for c in str(conditions).split(' AND '):
        c = c.strip()
        if not c:
            continue
        m = _re.match('^([A-Za-z_][A-Za-z0-9_]*)\\s*(>=|<=|>|<|==|!=)\\s*(-?[\\d.eE+]+)$', c)
        if m:
            out.append((m.group(1), m.group(2), float(m.group(3))))
    return out

def laz_mode5__apply_chain(chain, pool):
    """Apply [(term, op, value)] to a pool. Returns (mask, unresolved).
    Unresolved terms are REPORTED, never silently dropped — a chain applied
    with a missing term is a different strategy from the one recorded."""
    if not pool:
        return (None, ['empty pool'])
    n = len(next(iter(pool.values())))
    m = np.ones(n, bool)
    un = []
    for term, op, val in chain or []:
        v = pool.get(term)
        if v is None:
            un.append(term)
            continue
        v = np.asarray(v, float)
        with np.errstate(invalid='ignore'):
            r = v >= val if op == '>=' else v <= val if op == '<=' else v > val if op == '>' else v < val if op == '<' else v == val if op == '==' else v != val
        m &= np.nan_to_num(r, nan=False).astype(bool)
    return (m, un)

def laz_mode5__variants(conditions, pool, widen=(0.9, 0.95, 1.05, 1.1), log=None):
    """Mutations of a chain — each threshold nudged in turn.

    This is how Mode 5 explores AROUND a finding rather than only testing whole
    strategies: if a chain works at `u_pace >= 1.83`, does it work better at
    1.74 or 1.92, and is the edge a cliff or a slope? The answer is insight
    even when no variant beats the original.
    """
    base = laz_mode5__parse_chain(conditions)
    out = []
    for i, (t, op, v) in enumerate(base):
        for w in widen:
            ch = list(base)
            ch[i] = (t, op, round(v * w, 6))
            m, un = laz_mode5__apply_chain(ch, pool)
            if un:
                continue
            out.append(dict(variant=' AND '.join((f'{a} {b} {c}' for a, b, c in ch)), mutated_term=t, factor=w, new_value=round(v * w, 6), n=int(m.sum()) if m is not None else 0))
    V = pd.DataFrame(out)
    if log and len(V):
        log(f'[mode5] {len(V)} chain variants from {len(base)} terms')
    return V
