import os, sys, json, types
import numpy as np, pandas as pd

def laz_spawn__can_fork():
    try:
        import multiprocessing as mp
        mp.get_context('fork')
        return os.name != 'nt'
    except Exception:
        return False

def laz_spawn__mode():
    """'fork' where the platform has it and the owner has not forced spawn; else 'spawn'."""
    OW = _m('laz_owner')
    S = OW.LAZ_OWNER.get('search', {}) or {} if OW else {}
    forced = str(S.get('workers_mode', 'auto')).lower()
    if forced == 'spawn' or os.environ.get('LAZ_FORCE_SPAWN'):
        return 'spawn'
    return 'fork' if laz_spawn__can_fork() else 'spawn'
laz_spawn___SLIM = ('y', 'price', 'side', 'armable', 'ism', 'el', 'vf', 'GOK', 'fw')
laz_spawn___SCALARS = ('sport', 'days', 'target', 'known_sport', 'min_roi', 'min_bets', 'ladder', 'min_n', 'rounds', 'min_win', 'woe_subbins', 'first_rung', 'n_perm', 'gate_win', 'is_mask', 'reset_book', 'ix_parents', 'ix_top', 'ix_make', 'tick_seeds', 'base_seeds', 'rec_seeds', 'man', 'register', 'book')

def laz_spawn__write_state(P, engine_path, sport):
    """Parent: everything a spawn worker needs, on disk. Returns the manifest path."""
    OW = _m('laz_owner')
    home = (OW.LAZ_OWNER['paths'].get('output_dir') if OW else '.') or '.'
    d = P['d']
    pool = P['pool']
    index = P.get('index')
    arrs = {k: np.asarray(P[k]) for k in laz_spawn___SLIM if P.get(k) is not None}
    for c in ('match_id', 'ts', 'league'):
        if c in d.columns:
            arrs['frame__' + c] = d[c].values

    def _plain(v):
        a = np.asarray(v)
        if a.dtype.kind in 'biufM':
            return a
        return np.asarray(['' if x is None else str(x) for x in a], dtype=str)
    npz = os.path.join(home, f'laz_worker_{sport}.npz')
    np.savez(npz, **{k: _plain(v) for k, v in arrs.items()})
    pdir = os.path.join(home, f'laz_pool_{sport}')
    os.makedirs(pdir, exist_ok=True)
    pmap = {}
    for k, v in pool.items():
        if isinstance(v, np.memmap):
            pmap[k] = (v.filename, str(v.dtype), list(v.shape))
        else:
            a = np.ascontiguousarray(np.asarray(v, np.float32))
            path = os.path.join(pdir, f'spawn_{abs(hash(k)) % 10 ** 9}_{''.join((c if c.isalnum() or c in '_-' else '_' for c in k))[:150]}.f32')
            a.tofile(path)
            pmap[k] = (path, 'float32', list(a.shape))
    imap = {}
    try:
        if index is not None:
            for k in list(index.keys()):
                si = index[k] if not isinstance(index, dict) else index.get(k)
                if si is None:
                    continue
                if isinstance(si.order, np.memmap) and isinstance(si.vs, np.memmap):
                    imap[k] = (si.order.filename, si.vs.filename, list(si.order.shape))
    except Exception:
        imap = {}
    import pickle as _pk
    sc = {}
    for k in laz_spawn___SCALARS:
        v = P.get(k)
        try:
            _pk.dumps(v, protocol=4)
            sc[k] = v
        except Exception:
            sc[k] = None
    man = dict(engine=os.path.abspath(engine_path), npz=npz, pool=pmap, index=imap, scalars=laz_spawn___jsonable(sc), ctx_keys=[k for k in (P.get('ctx') or {}).keys()] if isinstance(P.get('ctx'), dict) else [])
    mp_ = os.path.join(home, f'laz_worker_{sport}.json')
    _laz_json_write(mp_, man, default=str)
    bp = os.path.join(os.path.dirname(os.path.abspath(engine_path)) or '.', 'laz_boot.py')
    open(bp, 'w').write(laz_spawn__BOOT_SRC)
    return mp_
laz_spawn___BOOT_B64 = ''
import zlib as _zl, base64 as _b6
laz_spawn__BOOT_SRC = _zl.decompress(_b6.b64decode(laz_spawn___BOOT_B64)).decode('utf-8')

def laz_spawn___jsonable(o):
    import pickle, base64
    return base64.b64encode(pickle.dumps(o, protocol=4)).decode('ascii')

def laz_spawn___unjson(s):
    import pickle, base64
    return pickle.loads(base64.b64decode(s))

def laz_spawn__boot(manifest_path):
    """Worker initialiser: load the engine, re-open the state, populate laz_mode3._PAR."""
    man = _laz_json_read(manifest_path)
    if 'lazarus_engine' not in sys.modules:
        ep = man['engine']
        lines = open(ep, encoding='utf-8', errors='replace').readlines()
        start = next((i for i, l in enumerate(lines) if l.startswith('# ####')), 0)
        mod = types.ModuleType('lazarus_engine')
        sys.modules['lazarus_engine'] = mod
        ns = mod.__dict__
        ns['__fi' + 'le__'] = ep
        exec('import math,gc,json,re,os,sys,itertools,datetime,hashlib,time\nimport numpy as np\nimport pandas as pd\n', ns)
        exec(compile('\n' * start + ''.join(lines[start:]), 'e', 'exec'), ns)
    ns = sys.modules['lazarus_engine'].__dict__
    m_ = ns['_m']
    z = np.load(man['npz'], allow_pickle=False)
    P = {k: z[k] if z[k].dtype.kind in 'biufM' else np.where(z[k] == '', None, z[k]).astype(object) for k in z.files if not k.startswith('frame__')}
    fr = {k[7:]: z[k] for k in z.files if k.startswith('frame__')}
    P['d'] = pd.DataFrame(fr)
    if 'ts' in P['d'].columns:
        P['d']['ts'] = pd.to_datetime(P['d']['ts'])
    pool = {}
    for k, (path, dt, shape) in man['pool'].items():
        pool[k] = np.memmap(path, dtype=dt, mode='r', shape=tuple(shape))
    P['pool'] = pool
    V = m_('laz_vector')
    idx = {}
    for k, (op, vp, shape) in man['index'].items():
        si = V.SweepIndex.__new__(V.SweepIndex)
        si.order = np.memmap(op, dtype=np.int32, mode='r', shape=tuple(shape))
        si.vs = np.memmap(vp, dtype=np.float64, mode='r', shape=tuple(shape))
        si.v = pool.get(k)
        si._cache = {}
        si._maxcache = 64
        idx[k] = si
    P['index'] = idx if idx else None
    P.update(laz_spawn___unjson(man['scalars']))
    P['ctx'] = {k: P.get(k) for k in ('side', 'price', 'y', 'vf', 'el', 'GOK', 'fw') if P.get(k) is not None}
    P['rpool'] = {}
    P['log'] = None
    M3 = m_('laz_mode3')
    M3._PAR.clear()
    M3._PAR.update(P)
