laz_book__FIELDS = ['strategy_name', 'sport', 'base', 'conditions', 'odds', 'oos_win', 'oos_roi', 'bets', 'tier', 'single_only', 'market', 'min_odds', 'resolves_at', 'first_seen', 'runs_seen', 'origin_mode', 'origin_file', 'engine_version', 'arm_window', 'rebuildable', 'missing_fields', 'placeable', 'unresolved_terms', 'band']

def laz_book___home():
    OW = _m('laz_owner')
    d = (OW.LAZ_OWNER.get('paths', {}) or {}).get('output_dir') if OW else None
    return d or os.getcwd()

def laz_book___path():
    return os.path.join(laz_book___home(), laz_book__STORE)

def laz_book__key(rec):
    """The BET SET identity — survives renaming between runs."""
    try:
        return f'{int(rec.get('bets'))}|{round(float(rec.get('oos_win')), 2)}|{round(float(rec.get('odds')), 4)}'
    except Exception:
        return None

def laz_book__load(log=None):
    """Everything the engine knows: the embedded copy, plus anything added
    since this build. The embedded copy is the floor, never the ceiling."""
    book = {}
    _rename = {'Ultima': 'Ultra'}
    try:
        book.update(json.loads(laz_book__EMBEDDED_TXT))
    except Exception as e:
        if log:
            log(f'[book] embedded store: {type(e).__name__}: {e}')
    p = laz_book___path()
    if os.path.exists(p):
        try:
            disk = _laz_json_read(p)
            for k, v in disk.items():
                if k in book:
                    book[k]['runs_seen'] = max(book[k].get('runs_seen', 1), v.get('runs_seen', 1))
                else:
                    book[k] = v
        except Exception as e:
            if log:
                log(f'[book] {laz_book__STORE}: {type(e).__name__}: {e}')
    for v in book.values():
        if v.get('tier') in _rename:
            v['tier'] = _rename[v['tier']]
    if log:
        bysport = {}
        for v in book.values():
            bysport[v.get('sport')] = bysport.get(v.get('sport'), 0) + 1
        log(f'[book] {len(book)} strategies carried by the engine · {bysport}')
    return book

def laz_book__ensure_csv(path, log=None):
    """[v187 F8] The search reads ENGINE_BOOK.csv. In a clean directory it did not exist and
    mode 3 died on FileNotFoundError while the engine carried every strategy inside itself.
    If the file is absent it is written from the embedded book (plus anything added since)."""
    # [v187 F8b] the CSV is a VIEW of the book: rebuild it whenever the book of record (LAZ_BOOK.json) is newer,
    # or the previous run's strategies never reach the next run's leg pool (found by the batch carry-forward).
    try:
        _store = laz_book___path()
        _stale = (not os.path.exists(path)) or (os.path.exists(_store) and os.path.getmtime(_store) > os.path.getmtime(path))
    except Exception:
        _stale = not os.path.exists(path)
    if not _stale:
        return pd.read_csv(path)
    bk = laz_book__load(log=None)
    df = pd.DataFrame(list(bk.values()))
    _say = log if callable(log) else print
    try:
        os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
        df.to_csv(path, index=False)
        _say(f'[book] {os.path.basename(path)} not found — materialised {len(df):,} strategies from the embedded book at {path}')
    except Exception as e:
        _say(f'[book] could not write {path}: {type(e).__name__}: {str(e)[:80]} — using the embedded book in memory')
    return df

laz_book__SELECTION_RULE = 'v187_is_only_floor'   # [v187 F13] the rule that selected a strategy travels with it

def laz_book__add(frame, sport, origin='mode3', version='', log=None):
    """Append every strategy in `frame`. Existing ones get runs_seen +1 —
    a strategy the engine finds again is more trusted, not a duplicate."""
    if frame is None or not len(frame):
        return (laz_book__load(log=None), 0, 0)
    book = laz_book__load()
    new = 0
    seen = 0
    today = pd.Timestamp.now('UTC').strftime('%Y-%m-%d')
    OWc = _m('laz_owner')
    _canon = OWc.canon if OWc is not None and hasattr(OWc, 'canon') else lambda x: str(x).lower()
    sport = _canon(sport) if str(sport).lower() != 'unknown' else 'unknown'
    for _, r in frame.iterrows():
        k = laz_book__key(r)
        if k is None:
            continue
        if k in book:
            b = book[k]
            b['runs_seen'] = int(b.get('runs_seen', 1)) + 1
            b['last_seen'] = today
            b['selection_rule'] = laz_book__SELECTION_RULE   # [v187 F13] re-found under this rule
            for f in ('odds', 'oos_win', 'oos_roi', 'bets', 'n_is', 'n_oos', 'is_win', 'band'):
                if f in r.index and pd.notna(r.get(f)):
                    try:
                        b[f] = float(r.get(f)) if f not in ('band',) else str(r.get(f))
                    except Exception:
                        b[f] = r.get(f)
            src = str(r.get('origin_file') or origin)
            b['origins'] = sorted(set((b.get('origins') or [b.get('origin_file') or '']) + [src]))
            for f in ('base', 'conditions', 'tier', 'market', 'min_odds'):
                if b.get(f) in (None, '', float('nan')) and f in r.index and pd.notna(r.get(f)):
                    b[f] = r.get(f)
            b['rebuildable'] = bool(b.get('conditions') and b.get('base'))
            b['missing_fields'] = '' if b['rebuildable'] else ' '.join((f for f in ('conditions', 'base') if not b.get(f)))
            try:
                _pl, _why = laz_book__placeable(b)
                b['placeable'] = bool(_pl)
                b['placeable_why'] = _why if not _pl else ''
            except Exception as _pe:
                pass
            try:
                _w = float(b.get('oos_win') or 0)
                _CBt = _m('laz_combina')
                _t = _CBt.tier_of(_w)[0] if _CBt is not None else None
                if _t:
                    b['tier'] = _t
                elif str(b.get('tier')) == 'single_only':
                    b['tier'] = None
            except Exception as _te:
                pass
            seen += 1
            continue
        rec = {f: r.get(f) if f in r.index else None for f in laz_book__FIELDS}
        rec.update(sport=str(sport), origin_mode=origin, engine_version=str(version), first_seen=today, last_seen=today, runs_seen=1, bet_key=k, origins=[str(r.get('origin_file') or origin)])
        rec = {kk: None if isinstance(vv, float) and vv != vv or str(vv).lower() in ('nan', 'none', '') else vv for kk, vv in rec.items()}
        if not rec.get('tier'):
            try:
                w = float(rec.get('oos_win') or 0)
                OW2 = _m('laz_owner')
                T2 = OW2.LAZ_OWNER['combination']['tiers'] if OW2 else {}
                best2 = None
                for n_, sp_ in T2.items():
                    if w >= sp_['min_win'] and (best2 is None or sp_['min_win'] > T2[best2]['min_win']):
                        best2 = n_
                rec['tier'] = best2 or 'single_only'
            except Exception:
                rec['tier'] = 'single_only'
        rec['rebuildable'] = bool(rec.get('conditions') and rec.get('base'))
        rec['missing_fields'] = '' if rec['rebuildable'] else ' '.join((f for f in ('conditions', 'base') if not rec.get(f)))
        for f in ('odds', 'oos_win', 'oos_roi', 'bets'):
            try:
                rec[f] = float(rec[f]) if rec[f] is not None else None
            except Exception:
                rec[f] = None
        book[k] = {kk: None if isinstance(vv, float) and vv != vv else vv for kk, vv in rec.items()}
        book[k]['selection_rule'] = laz_book__SELECTION_RULE   # [v187 F13] new entry, found under this rule
        try:
            _ok, _bad = laz_book__placeable(book[k])
            book[k]['placeable'] = bool(_ok)
            book[k]['unresolved_terms'] = '|'.join(_bad)
        except Exception:
            book[k]['placeable'] = bool(book[k].get('rebuildable'))
        new += 1
    try:
        with open(laz_book___path(), 'w') as f:
            json.dump(book, f, indent=1, default=str)
    except Exception as e:
        if log:
            log(f'[book] write failed: {type(e).__name__}: {e}')
    if log:
        log(f'[book] {sport}: +{new} NEW · {seen} seen again (runs_seen incremented) · the engine now carries {len(book)} strategies')
    return (book, new, seen)

def laz_book__for_sport(sport, min_win=None, min_roi=None):
    """Every known strategy for a sport, as a frame — base, conditions, all."""
    OW = _m('laz_owner')
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    rows = [v for v in laz_book__load().values() if (OW.canon(v.get('sport', '')) if OW is not None and hasattr(OW, 'canon') else str(v.get('sport', '')).lower()) == sp]
    B = pd.DataFrame(rows)
    if len(B):
        if min_win is not None:
            B = B[pd.to_numeric(B.oos_win, errors='coerce') >= min_win]
        if min_roi is not None:
            B = B[pd.to_numeric(B.oos_roi, errors='coerce') >= min_roi]
        B = B.sort_values('oos_roi', ascending=False)
    return B

def laz_book__placeable(rec):
    """STRICTER than rebuildable. Every term in the chain must resolve to a
    frame column, a genome element, or an engine spec condition. rebuildable
    only said the TEXT was present; a random record passed that and then
    failed on a term the genome had never heard of."""
    GN = _m('laz_genome')
    PR = _m('laz_promote')
    if GN is None or PR is None or (not rec.get('conditions')) or (not rec.get('base')):
        return (False, ['no base or conditions'])
    try:
        GN.bootstrap()
    except Exception:
        pass
    bad = []
    for term in PR.terms_in(rec['conditions']):
        d = GN.describe(term)
        if d.get('kind') == 'UNKNOWN':
            CR = _m('laz_corr')
            if CR is not None and hasattr(CR, 'parse_long') and str(term).startswith(('X_', 'ix_', 'ix2_')):
                if CR.parse_long(term) or term in getattr(CR, 'SHORT_TO_LONG', {}):
                    continue
            bad.append(term)
    return (not bad, bad)

def laz_book__audit_placeable(log=None):
    """Recompute placeable for every record and persist it."""
    book = laz_book__load()
    n = 0
    for k, v in book.items():
        ok, bad = laz_book__placeable(v)
        v['placeable'] = bool(ok)
        v['unresolved_terms'] = '|'.join(bad)
        n += int(ok)
    try:
        with open(laz_book___path(), 'w') as f:
            json.dump(book, f, indent=1, default=str)
    except Exception as e:
        if log:
            log(f'[book] write failed: {type(e).__name__}')
    if log:
        log(f'[book] placeable: {n}/{len(book)} — every term resolves to a column, genome element or engine spec')
    return (n, len(book))

def laz_book__known_keys(sport=None):
    """Bet-set keys for the register to suppress on."""
    OW = _m('laz_owner')
    out = set()
    for k, v in laz_book__load().items():
        if sport is None:
            out.add(k)
            continue
        a = OW.canon(v.get('sport', '')) if OW is not None and hasattr(OW, 'canon') else str(v.get('sport', '')).lower()
        b = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
        if a == b:
            out.add(k)
    return out

def laz_book__reset(sport=None, log=None):
    """THE RESET BUTTON.

    Clears the SUPPRESSION register so the engine re-derives from scratch and
    you can watch it rediscover what it already knows. THE BOOK IS NOT
    DELETED — every strategy stays, and rediscovering one increments its
    runs_seen rather than adding a duplicate.

    Use it to prove the book is still reachable, or after changing settings
    when you want the full search again rather than only the novel remainder.
    """
    RG = _m('laz_register')
    if RG is not None:
        if sport is None:
            RG._REG.clear()
            RG._RESET['*'] = True
        else:
            RG._REG.pop(str(sport).lower(), None)
            RG._RESET[str(sport).lower()] = True
    hist = os.path.join(laz_book___home(), 'laz_seed_history.jsonl')
    moved = None
    if os.path.exists(hist):
        moved = hist + '.' + pd.Timestamp.now('UTC').strftime('%Y%m%d%H%M%S')
        try:
            os.rename(hist, moved)
        except Exception as e:
            if log:
                log(f'[book] seed history: {type(e).__name__}')
                moved = None
    n = len(laz_book__known_keys(sport))
    if log:
        log(f'[book] RESET{(' for ' + str(sport) if sport else '')}: suppression cleared · {n} strategies REMAIN in the book · seed history archived' + (f' to {os.path.basename(moved)}' if moved else ''))
    return n

def laz_book__summary(log=None):
    B = pd.DataFrame(list(laz_book__load().values()))
    if not len(B):
        if log:
            log('[book] empty')
        return B
    S = B.groupby('sport').agg(strategies=('bet_key', 'count'), best_roi=('oos_roi', 'max'), best_win=('oos_win', 'max'), rediscovered=('runs_seen', lambda s: int((pd.to_numeric(s, errors='coerce') > 1).sum()))).reset_index().sort_values('strategies', ascending=False)
    if log:
        log(f'[book] {len(B)} strategies across {len(S)} sports')
        for _, r in S.iterrows():
            log(f'[book]   {r['sport']:14s} {int(r.strategies):>5} strategies · best ROI {r.best_roi} · best win {r.best_win}% · {int(r.rediscovered)} rediscovered')
    return S

def laz_book__revalidate(sport, d=None, pool=None, ctx=None, log=None, limit=None):
    """Re-measure every placeable strategy for one sport under today's gate."""
    ST = _m('laz_startup')
    CAS = _m('laz_cascades')
    RC = _m('laz_recovered')
    OW = _m('laz_owner')
    if ST is None or CAS is None or RC is None:
        return None
    C = OW.LAZ_OWNER.get('combination', {}) or {} if OW else {}
    floor = float(C.get('min_odds', 1.4))
    book = laz_book__load()
    sp = OW.canon(sport) if OW is not None and hasattr(OW, 'canon') else str(sport).lower()
    mine = {k: v for k, v in book.items() if (OW.canon(v.get('sport', '')) if OW is not None and hasattr(OW, 'canon') else str(v.get('sport', '')).lower()) == sp and v.get('placeable')}
    if not mine:
        if log:
            log(f'[revalidate] {sport}: no placeable strategies to re-measure')
        return None
    if d is None:
        d, pool, ctx, man = ST.prepare(sport, stride=1, log=lambda x: None)
    y = ctx['y']
    price = ctx['price']
    ism = ctx.get('ism')
    if ism is None:
        ism = pd.Series(d['match_id']).map(d.groupby('match_id')['ts'].min()).values
    armable = ~pd.isna(ctx['side']) & ~np.isnan(price)
    u = np.sort(np.unique(np.asarray(ism)[armable]))
    c50 = u[max(1, int(len(u) * 0.5)) - 1]
    IS = armable & (np.asarray(ism) <= c50)
    OOS = armable & (np.asarray(ism) > c50)
    rows = []
    ok = 0
    n = 0
    for k, v in list(mine.items())[:limit]:
        n += 1
        mask, missing = RC.build_mask(dict(conditions=str(v.get('conditions', '')).split(' AND ')), pool)
        if missing or mask is None:
            v['validated_current'] = False
            v['validation_reason'] = f'terms unavailable on this frame: {missing[:3]}'
            rows.append(dict(strategy=v.get('strategy_name'), verdict='NOT MEASURABLE', reason=v['validation_reason']))
            continue
        m = mask & armable & (price >= floor)
        acc, rec = CAS.accept(y, price, m, m & IS, m & OOS, min_n=100, min_odds=floor)
        v['measured_n_is'] = int((m & IS).sum())
        v['measured_n_oos'] = int((m & OOS).sum())
        v['measured_oos_win'] = round(float(rec.get('oos_win')), 2) if rec and rec.get('oos_win') is not None else None
        v['measured_oos_roi'] = round(float(rec.get('oos_roi')), 2) if rec and rec.get('oos_roi') is not None else None
        v['measured_odds'] = round(float(rec.get('odds')), 4) if rec and rec.get('odds') is not None else None
        v['validated_current'] = bool(acc)
        if acc:
            ok += 1
            v['validation_reason'] = 'passes the current gate'
        else:
            _r = v.get('measured_oos_roi')
            v['validation_reason'] = f'n_is={v['measured_n_is']} n_oos={v['measured_n_oos']} oos_roi={_r} — fails n>=100 / ROI>=15 / odds>={floor}'
        v['drift_roi'] = None if v.get('measured_oos_roi') is None or v.get('oos_roi') is None else round(float(v['measured_oos_roi']) - float(v['oos_roi']), 1)
        rows.append(dict(strategy=v.get('strategy_name'), verdict='PASS' if acc else 'FAIL', recorded_roi=v.get('oos_roi'), measured_roi=v.get('measured_oos_roi'), drift=v.get('drift_roi'), reason=v['validation_reason']))
    try:
        with open(laz_book___path(), 'w') as f:
            json.dump(book, f, indent=1, default=str)
    except Exception as e:
        if log:
            log(f'[revalidate] write failed: {type(e).__name__}')
    R = pd.DataFrame(rows)
    if log:
        log(f"[revalidate] {sport}: {ok}/{n} pass TODAY'S gate (n>=100 both halves · OOS ROI>=15% · odds>={floor})")
        if len(R) and 'drift' in R.columns:
            _d = pd.to_numeric(R.drift, errors='coerce').dropna()
            if len(_d):
                log(f'[revalidate]   ROI drift vs recorded: median {_d.median():+.1f} pts · worst {_d.min():+.1f} · best {_d.max():+.1f}')
        for _, x in R[R.verdict != 'PASS'].head(4).iterrows():
            log(f'[revalidate]   FAIL {str(x.strategy)[:30]}: {str(x.reason)[:80]}')
    return R
# ==========================================================================
# LAZ_BRAIN MODULE: laz_naming
# §laz_naming   <- grep this anchor to land here
# OBJECTIVE : IDENTITY ON DISK
# PURPOSE   : strategy_name, sport and odds_interval belong to the strategy, not to one consumer.
# HOW       : apply() names every row, recovers sport from the frame, and derives an odds interval from the band or, failing that, from the measured odds marked (inferred).
# VALUE     : Names were generated inside the exporter and never written back, so Mode 2 wrote twelve 1-to-1 sheets all called `None`, each overwriting the last — eleven silently lost.
# IF SKIPPED: Strategies cannot be referred to, filtered or placed.
# ==========================================================================
"""laz_naming.py — EVERY STRATEGY CARRIES ITS IDENTITY ON DISK.

strategy_name, sport, odds_interval, min_odds and max_odds were being generated
inside the exporter and never written back, so ENGINE_BOOK.csv had no names.
Mode 2 then wrote twelve 1-to-1 sheets all called `None`, each overwriting the
last — eleven sheets silently lost.

Identity belongs to the strategy, not to one consumer of it.
"""
import re
import numpy as np, pandas as pd
laz_naming__FALLBACK_EDGES = [1.0, 1.25, 1.32, 1.38, 1.44, 1.5, 1.58, 1.68, 1.8, 1.95, 2.15, 2.45, 2.9, 4.0, 99]

def laz_naming__odds_interval(row):
    b = str(row.get('band', 'nan'))
    if b not in ('nan', 'None', '') and '-' in b:
        p = b.split('-')
        try:
            return f'{float(p[0]):.2f}-{float(p[-1]):.2f}'
        except Exception:
            pass
    o = pd.to_numeric(pd.Series([row.get('odds')]), errors='coerce').iloc[0]
    if pd.isna(o):
        return 'unbanded'
    for a, c in zip(laz_naming__FALLBACK_EDGES[:-1], laz_naming__FALLBACK_EDGES[1:]):
        if a <= o < c:
            return f'{a:.2f}-{c:.2f} (inferred)'
    return 'unbanded'

def laz_naming__strategy_name(i, row):
    sp = str(row.get('sport', '?'))[:3].upper()
    bs = str(row.get('base') or 'lead')[:6].upper().replace('NAN', 'LEAD')
    iv = str(row.get('min_odds', '')).replace('.', '')
    c0 = str(row.get('conditions', '')).split(' AND ')[0].rsplit(' ', 2)[0][:14]
    c0 = re.sub('[^A-Za-z0-9]', '', c0).upper()[:12] or 'BASE'
    return f'LZ_{sp}_{bs}_{iv}_{c0}_{i + 1:03d}'
laz_naming__MIN_ODDS_HARD = 1.4

def laz_naming__enforce_floor(book, floor=laz_naming__MIN_ODDS_HARD, log=None):
    """THE FLOOR APPLIES TO THE BOOK ON DISK, not only at export.

    ENGINE_BOOK.csv held 38 strategies below 1.40 — minimum 1.181 — because the
    floor was checked when the workbook was written and nowhere else. A file
    that violates a standing rule is a file that will eventually be read by
    something that does not re-check.

    Judged on MEAN ODDS achieved, which is what the bet actually returns.
    Removed rows are not deleted from the record: the ledger keeps them.
    """
    o = pd.to_numeric(book.get('odds'), errors='coerce')
    keep = o.notna() & (o >= floor)
    n = int((~keep).sum())
    if n and log:
        log(f'  [floor] {n} strategies below {floor} removed from the book (retained in the ledger)')
    return (book[keep].reset_index(drop=True), book[~keep].reset_index(drop=True))

def laz_naming__apply(book, frame_map=None, floor=None, log=None):
    """Give every row a name, a sport and an odds interval. Idempotent.

    If `floor` is given the odds floor is enforced HERE, so the book on disk
    never carries a strategy the rules exclude.
    """
    B = book.copy().reset_index(drop=True)
    if 'sport' not in B.columns:
        B['sport'] = np.nan
    B['sport'] = B['sport'].astype(object)
    miss = B.sport.isna() | B.sport.astype(str).str.lower().isin(['nan', 'none', ''])
    if miss.any() and frame_map and ('frame' in B.columns):
        inv = {v: k for k, v in frame_map.items()}
        B.loc[miss, 'sport'] = B.loc[miss, 'frame'].map(lambda f: inv.get(str(f), np.nan))
    B['sport'] = B['sport'].fillna('unattributed').astype(str).str.lower()
    B['odds_interval'] = B.apply(laz_naming__odds_interval, axis=1)
    B['min_odds'] = B.odds_interval.str.split('-').str[0].astype(float)
    B['max_odds'] = B.odds_interval.str.replace(' (inferred)', '', regex=False).str.split('-').str[-1].astype(float)
    B['strategy_name'] = [laz_naming__strategy_name(i, r) for i, r in B.iterrows()]
    lead = ['strategy_name', 'sport', 'odds_interval', 'min_odds', 'max_odds', 'base', 'band']
    B = B[[c for c in lead if c in B.columns] + [c for c in B.columns if c not in lead]]
    if floor is not None:
        B, _ = laz_naming__enforce_floor(B, floor=floor, log=log)
    return B
# ==========================================================================
# LAZ_BRAIN MODULE: laz_register
# §laz_register   <- grep this anchor to land here
# ==========================================================================
"""laz_register.py — THE ENGINE ACCUMULATES A BOOK INSTEAD OF REDISCOVERING ONE.

THE PROBLEM, MEASURED
Four tabletennis runs on the same frame: 192, 172, 179, 174 legs. Largely
the same strategies, rediscovered each time. Every run starts blind — same
frame, same gate, same greedy search — so the strongest chains surface first,
every time.

The promoted-conditions store makes it worse in a specific way. Conditions
are promoted BECAUSE they appeared in accepted strategies, so each run begins
holding the last run's answers. The pool grew 166 -> 317, which reads like
diversity and is closer to a feedback loop.

WHAT THIS DOES
  1  KNOWN BET SETS. At startup, every strategy already known for this sport
     is loaded and its BET SET registered — the (match_id, ts) pairs from the
     ledger, or (n, idx0, idx_last, win, odds) where no ledger survives.
     Names change between runs; bet sets do not.
  2  SUPPRESSION AT SEARCH TIME. A chain converging on a known bet set is not
     re-derived. It is logged as `already known` and the attempt budget moves
     on. THE BOOK KEEPS IT — only the search effort is redirected.
  3  NEAR-MISS SUPPRESSION. Exact matching is too weak: a chain overlapping a
     known strategy on 95% of bets is the same strategy with a nudged
     threshold. The operator's redundancy rule applies — redundant only on
     SAME MATCH AND SAME TICK AND SAME SIDE. Same fixtures at a different
     moment is a SECOND OPPORTUNITY and is kept.
  4  SEED ROTATION. The freed budget must go somewhere new. Seeds that
     produced known strategies are deprioritised; seeds that produced nothing
     are prioritised — unexplored, not proven barren, since the pool has
     changed. Recovered-stack order rotates so the budget reaches different
     stacks each run.
  5  THE BRAIN IS READ. laz_mode5_brain.jsonl records what was tried and what
     failed, and no mode read it. Conditions profiled with no lift on this
     sport are deprioritised as seeds; failed transfers are not retried
     unless the pool changed.

WHAT MUST NOT HAPPEN
  Never suppress a strategy FROM THE BOOK. Never suppress on name or
  condition text — the bet set decides. The register is read once in the
  parent and inherited under fork; a worker never writes it.
"""
import os, json, glob, hashlib
import numpy as np, pandas as pd
laz_register__SEED_HISTORY = 'laz_seed_history.jsonl'

def laz_register___home():
    OW = _m('laz_owner')
    d = (OW.LAZ_OWNER.get('paths', {}) or {}).get('output_dir') if OW else None
    return d or os.getcwd()

def laz_register__bet_key(rec):
    """A stable identity for a strategy that survives renaming."""
    n = rec.get('bets')
    w = rec.get('oos_win')
    o = rec.get('odds')
    try:
        return (int(n), round(float(w), 2), round(float(o), 4))
    except Exception:
        return None

def laz_register__ledger_key(mid, ts, side=None):
    """Hash of the sorted (match_id, ts[, side]) pairs — the bet set itself."""
    try:
        pairs = sorted(zip(map(str, mid), map(str, ts), map(str, side if side is not None else [''] * len(mid))))
        return hashlib.blake2b('|'.join((f'{a}@{b}:{c}' for a, b, c in pairs)).encode(), digest_size=12).hexdigest()
    except Exception:
        return None
laz_register___REG = {}
laz_register___RESET = {}

def laz_register__load(sport, log=None):
    """Every strategy already known for this sport, keyed by bet set."""
    sp = str(sport).lower()
    home = laz_register___home()
    if sp in laz_register___REG:
        return laz_register___REG[sp]
    known = {'keys': set(), 'ledgers': {}, 'sources': {}}
    if laz_register___RESET.get(sp) or laz_register___RESET.get('*'):
        laz_register___REG[sp] = known
        if log:
            log(f'[register] {sp}: RESET — suppression disabled for this run; the book is untouched')
        return known
    BK = _m('laz_book')
    if BK is not None:
        for _k in BK.known_keys(sp):
            try:
                _b, _w, _o = _k.split('|')
                known['keys'].add((int(_b), float(_w), float(_o)))
                known['sources'][_k] = 'LAZ_BOOK'
            except Exception:
                pass
        if log and known['keys']:
            log(f'[register] {len(known['keys'])} from the engine book')
    cands = [os.path.join(home, 'ENGINE_BOOK.csv')]
    cands += glob.glob(os.path.join(home, f'mode3_{sp}_legs*.csv'))
    cands += glob.glob(os.path.join(home, f'mode1_{sp}*.csv'))
    cands += glob.glob(os.path.join(home, f'mode5_{sp}*.csv'))
    OW = _m('laz_owner')
    aliases = {sp}
    if OW is not None and hasattr(OW, 'canon'):
        for a in ('efbig', 'efootball', 'tabletennis', 'tennis', 'ebasketball', 'basketball', 'esports', 'etennis', 'football'):
            if OW.canon(a) == OW.canon(sp):
                aliases.add(a)
    for f in cands:
        if not os.path.exists(f):
            continue
        try:
            B = pd.read_csv(f, low_memory=False)
        except Exception as e:
            if log:
                log(f'[register] {os.path.basename(f)}: {type(e).__name__}: {e}')
                continue
        if 'sport' in B.columns:
            B = B[B.sport.astype(str).str.lower().isin(aliases)]
        n0 = len(known['keys'])
        for _, r in B.iterrows():
            k = laz_register__bet_key(r)
            if k:
                known['keys'].add(k)
                known['sources'][k] = os.path.basename(f)
        if log and len(known['keys']) > n0:
            log(f'[register] {os.path.basename(f)}: +{len(known['keys']) - n0} known strategies')
    laz_register___REG[sp] = known
    if log:
        log(f'[register] {sp}: {len(known['keys'])} known bet sets loaded — the search will not re-derive them')
    return known

def laz_register__is_known(sport, rec):
    k = laz_register__bet_key(rec)
    return bool(k and k in laz_register__load(sport)['keys'])

def laz_register__near_known(sport, rec, ledger=None, max_overlap=0.6):
    """Near-miss test through the operator's redundancy rule: same match AND
    same tick AND same side. Returns (is_near, overlap, against)."""
    RD = _m('laz_redundancy')
    K = laz_register__load(sport)
    if ledger is None or RD is None or (not K['ledgers']):
        return (False, 0.0, None)
    try:
        L = pd.DataFrame(ledger) if isinstance(ledger, dict) else ledger
        best = (0.0, None)
        for kk, kl in K['ledgers'].items():
            ov = float(RD.overlap(L, pd.DataFrame(kl), 0))
            if ov > best[0]:
                best = (ov, kk)
        return (best[0] >= max_overlap, best[0], best[1])
    except Exception:
        return (False, 0.0, None)

def laz_register__remember_ledger(sport, rec, ledger):
    """Called by the PARENT after merge, so near-miss checks improve next run."""
    k = laz_register__bet_key(rec)
    if k and ledger is not None:
        K = laz_register__load(sport)
        K['ledgers'][k] = {c: list(np.asarray(ledger[c])[:2000]) for c in ('mid', 'ts', 'side') if c in ledger}

def laz_register___hist_path():
    return os.path.join(laz_register___home(), laz_register__SEED_HISTORY)

def laz_register__seed_history(sport):
    p = laz_register___hist_path()
    out = {}
    if not os.path.exists(p):
        return out
    for ln in _laz_read_lines(p):
        try:
            e = json.loads(ln)
        except Exception:
            continue
        if str(e.get('sport')) != str(sport).lower():
            continue
        out[e['seed']] = e
    return out

def laz_register__record_seed(sport, seed_id, outcome, n_found=0, n_known=0):
    """Append one seed's outcome. Never overwrite."""
    try:
        with open(laz_register___hist_path(), 'a') as f:
            f.write(json.dumps(dict(sport=str(sport).lower(), seed=str(seed_id), outcome=outcome, found=int(n_found), known=int(n_known), ts=pd.Timestamp.now('UTC').strftime('%Y-%m-%dT%H:%M:%S'))) + '\n')
    except Exception:
        pass

def laz_register__order_seeds(sport, seed_ids, log=None):
    """Prioritise seeds that produced NOTHING last time; deprioritise seeds
    that produced only KNOWN strategies. Untried seeds go first of all."""
    H = laz_register__seed_history(sport)

    def rank(sid):
        e = H.get(str(sid))
        if e is None:
            return (0, 0)
        if e['outcome'] == 'nothing':
            return (1, 0)
        if e['outcome'] == 'novel':
            return (2, -e['found'])
        return (3, e['known'])
    out = sorted(seed_ids, key=rank)
    if log and H:
        c = {k: sum((1 for s in seed_ids if (H.get(str(s)) or {}).get('outcome') == k)) for k in ('nothing', 'novel', 'known')}
        log(f'[register] seed order: {len(seed_ids) - sum(c.values())} untried first · {c['nothing']} unexplored next · {c['novel']} productive · {c['known']} known-only last')
    return out

def laz_register__rotate(seed_ids, sport):
    """Rotate recovered-stack order by run count so the budget reaches
    different stacks each run. 727 are usable on eFootball and the budget
    only ever reached the first few hundred, in the same order every time."""
    p = laz_register___hist_path()
    n = 0
    if os.path.exists(p):
        with open(p) as f:
            n = sum((1 for _ in f))
    if not seed_ids:
        return seed_ids
    k = n * 97 % len(seed_ids)
    return list(seed_ids[k:]) + list(seed_ids[:k])

def laz_register__brain_hints(sport, log=None):
    """What Mode 5 learned that Modes 1 and 3 should act on."""
    M5 = _m('laz_mode5')
    if M5 is None or not hasattr(M5, 'recall'):
        return dict(dead_conditions=set(), failed_transfers=set())
    E = M5.recall(sport)
    dead = set()
    failed = set()
    for e in E:
        if e.get('kind') == 'insight' and (e.get('residual') or 0) <= 0:
            dead.add(str(e.get('condition')))
        if e.get('kind') == 'transfer' and e.get('expectation_held') is False:
            failed.add(str(e.get('tried')))
    if log:
        if not E:
            log(f'[register] brain: no entries for {sport} — nothing to act on')
        else:
            log(f'[register] brain: {len(E)} entries · {len(dead)} conditions with no lift deprioritised · {len(failed)} failed transfers not retried')
    return dict(dead_conditions=dead, failed_transfers=failed)

def laz_register__report(sport, attempts, novel, known_hits, log=None):
    ratio = known_hits / max(attempts, 1)
    verdict = 'SATURATED — identical inputs give identical chains; rotate seeds or change settings' if novel == 0 and attempts > 0 else 'SATURATING at these settings' if ratio > 0.5 and novel < 5 else 'still learning'
    msg = f'[register] {sport}: {attempts} attempts · {novel} NOVEL · {known_hits} landed on known strategies ({ratio:.0%}) — {verdict}'
    if log:
        log(msg)
    return dict(attempts=attempts, novel=novel, known=known_hits, ratio=ratio)
