    b.dashboard([('Strategies', len(S)), ('  of which 3+ stars', int((S.stars_n >= 3).sum())), ('Total bets', int(pd.to_numeric(S.bets, errors='coerce').sum()) if 'bets' in S.columns else ''), ('Mean OOS ROI', round(float(pd.to_numeric(S.oos_roi, errors='coerce').mean()), 1)), ('Mean OOS win rate', f'{float(pd.to_numeric(S.oos_win, errors='coerce').mean()):.1f}%'), ('', ''), ('Best strategy', best.get('strategy_name', '')), ('   stars / ROI / win', f'{WB.star_text(best.stars_n)} · {best.oos_roi:+.1f}% · {best.oos_win:.1f}%'), ('   conditions', str(best.get('conditions', ''))[:90]), ('', ''), ('Families represented', len(fam)), ('   largest', f'{fam.index[0]} ({fam.iloc[0]})' if len(fam) else ''), ('Origins', ', '.join((f'{k} {v}' for k, v in S.origin.value_counts().items())) if 'origin' in S.columns else '')], legend=laz_books___fam_legend())
    lead = ['strategy_name', 'sport', 'family', 'origin', 'base', 'odds_interval', 'bets', 'per_day', 'n_is', 'n_oos', 'is_win', 'oos_win', 'odds', 'is_roi', 'oos_roi', 'perm_p', 'bh_pass', 'conditions']
    T = S[[c for c in lead if c in S.columns]].sort_values('oos_roi', ascending=False)
