# ==========================================================================
# LAZ_BRAIN MODULE: laz_combine_all
# §laz_combine_all   <- grep this anchor to land here
# ==========================================================================
"""laz_combine_all.py — COMBINA ACROSS EVERY SPORT, IN TIME WINDOWS.

A per-sport combine can never form a cross-sport slip: an Ultra tabletennis
leg at 12:00:10 and an Ultra tennis leg at 12:00:40 are exactly the pair the
placement rule exists for, and they lived in different runs. And loading
every frame at once for one combine would exhaust memory.

So: walk the calendar in windows of N days. For each window, load every
sport's ARMS from mode3_<sport>.parquet (small), slice every sport's FRAME to
that window through pyarrow filters (small), build one price series, run the
same simulate() once over the union, and keep the placed slips. Same rules —
same-match per market, the tier caps, Satoro, never_combine per sport, the
hold, the 60-second window — applied to legs from any sport together.

Nothing is invented. The arms are the sweep's own ledgers; the prices are the
frames' own quotes at the placement instant.
"""
import os, numpy as np, pandas as pd
laz_combine_all__SPORTS = ('etennis', 'esports', 'tabletennis', 'basketball', 'tennis', 'football', 'efootball', 'ebasketball')

def laz_combine_all___out(name):
    OW = _m('laz_owner')
    home = (OW.LAZ_OWNER['paths'].get('output_dir') if OW else '.') or '.'
    return os.path.join(home, name)

def laz_combine_all___frame_slice(sport, t0, t1, log=None):
    """The sport's frame between t0 and t1 only, via pyarrow filters."""
    import pyarrow.parquet as pq, pyarrow.compute as pc
    OW = _m('laz_owner')
    path = OW.frame_path(sport) if OW and hasattr(OW, 'frame_path') else None
    if not path or not os.path.exists(path):
        return None
    names = pq.ParquetFile(path).schema_arrow.names
    tcol = 'ts' if 'ts' in names else 'timestamp' if 'timestamp' in names else None
    if tcol is None:
        return None
    want = [c for c in ('match_id', tcol, 'home_odds', 'away_odds', 'total_goals_under', 'total_goals_over', 'final_winner') if c in names]
    try:
        T = pq.read_table(path, columns=want, filters=[(tcol, '>=', pd.Timestamp(t0)), (tcol, '<', pd.Timestamp(t1))])
    except Exception as e:
        if log:
            log(f'[all] {sport}: frame slice {type(e).__name__}: {str(e)[:60]}')
        return None
    d = T.to_pandas()
    if tcol != 'ts':
        d['ts'] = pd.to_datetime(d[tcol], errors='coerce')
    d['match_id'] = sport + ':' + d['match_id'].astype(str)
    return d

def laz_combine_all___arms(sport, t0, t1, log=None):
    """Every arm of every strategy of the sport inside the window, from the one parquet."""
    p = laz_combine_all___out(f'mode3_{sport}.parquet')
    if not os.path.exists(p):
        return (None, None, None, None)
    L = pd.read_parquet(p)
    L['ts'] = pd.to_datetime(L['ts'], errors='coerce')
    L = L[(L.ts >= pd.Timestamp(t0)) & (L.ts < pd.Timestamp(t1))]
    if not len(L):
        return (None, None, None, None)
    CB = _m('laz_combina')
    OW = _m('laz_owner')
    C = OW.LAZ_OWNER['combination'] if OW else {}
    tiers = C.get('tiers', {})
    mot = C.get('min_odds_by_tier', {})
    ladder0 = 1.4
    S = L.drop_duplicates('strategy_name')
    tier_by_leg = {}
    floors = {}
    market_by_leg = {}
    sport_by_leg = {}
    for _, r in S.iterrows():
        nm = sport + ':' + str(r.strategy_name)
        w = float(r.get('oos_win') or 0)
        t, _ = CB.tier_of(w, tiers)
        tier_by_leg[nm] = (t, w)
        floors[nm] = float(mot.get(t, ladder0)) if t else ladder0
        market_by_leg[nm] = str(r.get('market') or 'moneyline')
        sport_by_leg[nm] = sport
    A = pd.DataFrame(dict(leg=sport + ':' + L['strategy_name'].astype(str), match_id=sport + ':' + L['mid'].astype(str), ts=L['ts'].values, won=L['won'].astype(bool).values, odds=L['price'].astype(float).values, side=L['side'].astype(str).values if 'side' in L.columns else '', floor=[floors.get(sport + ':' + str(x), ladder0) for x in L['strategy_name']]))
    return (A, tier_by_leg, floors, (market_by_leg, sport_by_leg))
laz_combine_all__BET_BOOK = 'LAZ_BETS.parquet'

def laz_combine_all__merge_from(other_dir, log=print):
    """FLEET MERGE. Pull another machine's results into this folder:
       - its mode3_<sport>.parquet: rows appended, then deduplicated on
         (strategy_name, mid, ts) so a re-copy never doubles a bet
       - its LAZ_BOOK.json: strategies added through laz_book.add, which
         dedupes on bet set — nothing doubles, nothing is lost
    Run on the machine that will do --combine-all, once per other machine."""
    import shutil, json
    BK = _m('laz_book')
    OW = _m('laz_owner')
    other = os.path.abspath(other_dir)
    here = os.path.abspath(laz_combine_all___out(''))
    if other == here:
        log('[merge] other dir is this dir — nothing to do')
        return
    n_rows = 0
    n_sports = 0
    for f in sorted(os.listdir(other)):
        if f.startswith('mode3_') and f.endswith('.parquet'):
            src = os.path.join(other, f)
            dst = laz_combine_all___out(f)
            L = pd.read_parquet(src)
            if os.path.exists(dst):
                H = pd.read_parquet(dst)
                A = pd.concat([H, L], ignore_index=True, sort=False)
                key = [c for c in ('strategy_name', 'mid', 'ts') if c in A.columns]
                A = A.drop_duplicates(subset=key, keep='last') if key else A
                n_rows += len(A) - len(H)
            else:
                A = L
                n_rows += len(L)
            A.to_parquet(dst, index=False)
            n_sports += 1
            log(f'[merge] {f}: {len(L):,} rows from {other} -> {len(A):,} here')
    bp = os.path.join(other, 'LAZ_BOOK.json')
    added = 0
    if os.path.exists(bp) and BK is not None:
        B = _laz_json_read(bp)
        rows = []
        for k, v in B.items():
            if isinstance(v, dict) and v.get('conditions'):
                rows.append(v)
        if rows:
            D = pd.DataFrame(rows)
            for sp, G in D.groupby(D.get('sport', pd.Series(['unknown'] * len(D)))):
                try:
                    _, n, _ = BK.add(G, str(sp), origin='fleet', version='merged', log=None)
                    added += n
                except Exception as e:
                    log(f'[merge] book {sp}: {type(e).__name__}: {str(e)[:60]}')
    log(f'[merge] DONE: {n_sports} sport parquets · +{n_rows:,} bet rows · +{added} strategies into the book from {other}')

def laz_combine_all__build_bet_book(sports=None, log=print):
    """ONE PARQUET OF EVERY BET EVERY STRATEGY PLACED, ACROSS SPORTS — the
    operator's design. Columns: sport, strategy_name, match_id, ts, league,
    side, market, price, won, is_oos, tier, oos_win, odds, base, conditions,
    stride. Built from each sport's mode3_<sport>.parquet; combine-all walks
    THIS file window by window and drops each window when it is reported."""
    CB = _m('laz_combina')
    OW = _m('laz_owner')
    C = OW.LAZ_OWNER['combination'] if OW else {}
    tiers = C.get('tiers', {})
    parts = []
    for sp in sports or laz_combine_all__SPORTS:
        p = laz_combine_all___out(f'mode3_{sp}.parquet')
        if not os.path.exists(p):
            continue
        L = pd.read_parquet(p)
        keep = [c for c in ('strategy_name', 'mid', 'ts', 'won', 'price', 'side', 'is_oos', 'league', 'oos_win', 'odds', 'base', 'conditions', 'market', 'stride') if c in L.columns]
        L = L[keep].copy()
        L['sport'] = sp
        L['strategy_name'] = sp + ':' + L['strategy_name'].astype(str)
        L = L.rename(columns={'mid': 'match_id'})
        L['match_id'] = sp + ':' + L['match_id'].astype(str)
        L['tier'] = [CB.tier_of(float(w or 0), tiers)[0] for w in L.get('oos_win', pd.Series([0] * len(L)))]
        parts.append(L)
    if not parts:
        log('[bets] no mode3_<sport>.parquet found')
        return None
    B = pd.concat(parts, ignore_index=True, sort=False)
    B['ts'] = pd.to_datetime(B['ts'], errors='coerce')
    B = B.sort_values('ts').reset_index(drop=True)
    B.to_parquet(laz_combine_all___out(laz_combine_all__BET_BOOK), index=False)
    log(f'[bets] {laz_combine_all__BET_BOOK}: {len(B):,} bets · {B.strategy_name.nunique():,} strategies · {B.sport.nunique()} sports · {B.ts.min().date()} .. {B.ts.max().date()} · tiers {B.tier.value_counts().to_dict()}')
    return B

def laz_combine_all___arms_from_book(B, sport, t0, t1):
    """One sport's arms inside the window, from the bet book."""
    CB = _m('laz_combina')
    OW = _m('laz_owner')
    C = OW.LAZ_OWNER['combination'] if OW else {}
    mot = C.get('min_odds_by_tier', {})
    ladder0 = 1.4
    L = B[(B.sport == sport) & (B.ts >= pd.Timestamp(t0)) & (B.ts < pd.Timestamp(t1))]
    if not len(L):
        return (None, None, None, None)
    S = L.drop_duplicates('strategy_name')
    tier_by_leg = {r.strategy_name: (r.tier, float(r.oos_win or 0)) for r in S.itertuples()}
    floors = {r.strategy_name: float(mot.get(r.tier, ladder0)) if r.tier else ladder0 for r in S.itertuples()}
    market_by_leg = {r.strategy_name: str(getattr(r, 'market', 'moneyline') or 'moneyline') for r in S.itertuples()}
    sport_by_leg = {r.strategy_name: sport for r in S.itertuples()}
    A = pd.DataFrame(dict(leg=L.strategy_name.values, match_id=L.match_id.values, ts=L.ts.values, won=L.won.astype(bool).values, odds=L.price.astype(float).values, side=L.side.astype(str).values if 'side' in L else '', floor=[floors.get(n, ladder0) for n in L.strategy_name]))
    return (A, tier_by_leg, floors, (market_by_leg, sport_by_leg))

def laz_combine_all__run(sports=None, start=None, end=None, window_days=3, log=print, workers=None):
    CB = _m('laz_combina')
    OW = _m('laz_owner')
    C = OW.LAZ_OWNER['combination'] if OW else {}
    sports = list(sports or laz_combine_all__SPORTS)
    _have = [sp for sp in sports if os.path.exists(laz_combine_all___out(f'mode3_{sp}.parquet'))]
    _missing = [sp for sp in sports if sp not in _have]
    if not _have:
        log('[all] no mode3_<sport>.parquet for any requested sport — generate first')
        return None
    log(f'[all] sports in this combine: {_have}' + (f' · not yet generated, left out: {_missing}' if _missing else ''))
    if C.get('all_require_every_sport', False) and _missing:
        log(f'[all] REFUSED by all_require_every_sport=True — {_missing} have not generated')
        return None
    sports = _have
    lo = hi = None
    for sp in sports:
        p = laz_combine_all___out(f'mode3_{sp}.parquet')
        if os.path.exists(p):
            t = pd.to_datetime(pd.read_parquet(p, columns=['ts'])['ts'], errors='coerce')
            lo = min(lo, t.min()) if lo is not None else t.min()
            hi = max(hi, t.max()) if hi is not None else t.max()
    if lo is None:
        log('[all] no mode3_<sport>.parquet found — generate first')
        return None
    t0 = pd.Timestamp(start) if start else lo.normalize()
    t_end = pd.Timestamp(end) if end else (hi + pd.Timedelta(days=1)).normalize()
    log(f'[all] combining {len(sports)} sports across {t0.date()} .. {t_end.date()} in {window_days}-day windows · hold {C.get('hold_sec', 5)}s · window {C.get('window_sec', 60)}s')
    placed = []
    nwin = 0
    hold = float(C.get('hold_sec', 5.0))
    wsec = float(C.get('window_sec', 60.0))
    B = laz_combine_all__build_bet_book(sports, log=log)
    if B is None:
        return None
    import gc
    while t0 < t_end:
        t1 = min(t0 + pd.Timedelta(days=window_days), t_end)
        nwin += 1
        As = []
        TB = {}
        FL = {}
        MB = {}
        SB = {}
        ser = {}
        for sp in sports:
            got = laz_combine_all___arms_from_book(B, sp, t0, t1)
            if got[0] is None:
                continue
            A, tb, fl, (mb, sb) = got
            As.append(A)
            TB.update(tb)
            FL.update(fl)
            MB.update(mb)
            SB.update(sb)
            d = laz_combine_all___frame_slice(sp, t0, t1, log=log)
            if d is not None and len(d):
                ser.update(CB.price_series_both(d))
        if not As:
            t0 = t1
            continue
        A = pd.concat(As, ignore_index=True).sort_values('ts').reset_index(drop=True)
        try:
            P, E = CB.simulate(A, FL, ser, {}, MB, TB, sport=None, sport_by_leg=SB, window_sec=wsec, hold_sec=hold, log=lambda x: None)
        except Exception as e:
            log(f'[all] window {t0.date()}..{t1.date()}: simulate {type(e).__name__}: {str(e)[:70]}')
            t0 = t1
            continue
        n = len(P) if P is not None else 0
        if n:
            P = P.copy()
            P['window_start'] = t0
            P['n_sports'] = P.legs.astype(str).map(lambda s: len({l.split(':')[0] for l in s.split('|')}))
            placed.append(P)
        log(f'[all] {t0.date()}..{t1.date()}: {len(A):,} arms from {len(As)} sports · {n} slips placed' + (f' · {int((P.n_sports > 1).sum())} cross-sport' if n else ''))
        del As, A, ser, TB, FL, MB, SB
        if 'E' in dir():
            del E
        gc.collect()
        t0 = t1
    if not placed:
        log('[all] nothing placed')
        return None
    PL = pd.concat(placed, ignore_index=True)
    PL.to_csv(laz_combine_all___out('combina_ALL_sim_placed.csv'), index=False)
    xs = int((PL.n_sports > 1).sum())
    log(f'[all] DONE: {len(PL):,} slips over {nwin} windows · {xs:,} cross-sport · hit {100 * PL.won.mean():.1f}% · P&L {float((PL.won * PL.payout_mult - 1).sum()):+.1f} on {len(PL)} staked')
    rows = []
    for sp in sports:
        p = laz_combine_all___out(f'mode3_{sp}.parquet')
        if os.path.exists(p):
            S = pd.read_parquet(p).drop_duplicates('strategy_name')
            S = S.drop(columns=[c for c in ('mid', 'ts', 'won', 'price', 'side', 'is_oos') if c in S.columns])
            S['strategy_name'] = sp + ':' + S['strategy_name'].astype(str)
            S['sport'] = sp
            rows.append(S)
    if rows:
        XL = _m('laz_xl')
        if XL is not None:
            try:
                path = XL.write(pd.concat(rows, ignore_index=True, sort=False), 'ALL', 3, log=log, path=laz_combine_all___out(f'LAZARUS_ALL_COMBINA_{pd.Timestamp.now('UTC').strftime('%Y%m%d_%H%M')}.xlsx'), combina=dict(summary=None, placed=PL, pairs=None, breakage=None))
                log(f'[all] workbook {path}')
            except Exception as e:
                log(f'[all] workbook: {type(e).__name__}: {str(e)[:80]}')
    return PL
