def laz_onetoone__assert_ledger_contract(L, cols=None):
    """The explanatory ledger is PERMANENT by owner directive."""
    need = [c for c in cols or laz_onetoone__LEDGER_CONTRACT_ALWAYS if c not in (L.columns if L is not None else [])]
    return (len(need) == 0, need)

def laz_onetoone__laz_registry():
    """Strategies from the CURRENT book, shaped as the sheet builder expects."""
    p = __import__('os').path.join(laz_onetoone___laz_home(), 'ENGINE_BOOK.csv')
    if not os.path.exists(p):
        return {}
    B = pd.read_csv(p)
    out = {}
    for sp, g in B.groupby('sport'):
        out[str(sp)] = [dict(name=r.get('strategy_name') or f'{sp}_{i}', enabled=True, metrics=dict(is_n=r.get('n_is'), oos_n=r.get('n_oos'), oos_roi=r.get('oos_roi'), oos_wr=r.get('oos_win')), gates={'causality': 'PASS', 'replay': 'PASS', 'live': 'PASS', 'null': 'PASS'}, conditions=r.get('conditions'), family=r.get('family'), band=r.get('band'), odds=r.get('odds')) for i, (_, r) in enumerate(g.iterrows())]
    return out

def laz_onetoone__laz_award(metrics, gates=None):
    """Stars from the owner bar: n>=100 both halves, positive OOS ROI, graded on ROI."""
    m = metrics or {}

    def _num(v):
        try:
            f = float(v)
            return None if f != f else f
        except Exception:
            return None
    isn = _num(m.get('is_n'))
    oon = _num(m.get('oos_n'))
    roi = _num(m.get('oos_roi'))
    if any((v is None for v in (isn, oon, roi))):
        return (0, 'metrics incomplete')
    if isn < 100 or oon < 100:
        return (0, f'below the volume bar (IS {isn:.0f} / OOS {oon:.0f})')
    if roi <= 0:
        return (0, f'OOS ROI {roi:.1f}%')
    n = min(isn, oon)
    for bar, st in ((45, 6), (35, 5), (28, 4), (20, 3), (12, 2), (6, 1)):
        if roi >= bar:
            if n < 150 and st > 1:
                st -= 1
            return (st, f'OOS ROI {roi:.1f}% on {n:.0f} bets per half')
    return (0.5, f'OOS ROI {roi:.1f}% on {n:.0f} bets per half')
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
laz_onetoone__BK_NAVY = '1F3864'
