def laz_onetoone___bk_title(ws, text, sub, ncol, row=1):
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=max(ncol, 2))
    c = ws.cell(row, 1, text)
    c.font = Font(bold=True, size=15, color='FFFFFF')
    c.fill = PatternFill('solid', fgColor=laz_onetoone__BK_NAVY)
    c.alignment = Alignment(vertical='center')
    ws.row_dimensions[row].height = 26
    ws.merge_cells(start_row=row + 1, start_column=1, end_row=row + 1, end_column=max(ncol, 2))
    c = ws.cell(row + 1, 1, sub)
    c.font = Font(size=10, italic=True, color='333333')
    c.alignment = Alignment(wrap_text=True, vertical='top')
    ws.row_dimensions[row + 1].height = max(30, 14 * (1 + len(sub) // 120))
    return row + 3

def laz_onetoone___bk_section(ws, row, text, ncol):
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=max(ncol, 2))
    c = ws.cell(row, 1, text)
    c.font = Font(bold=True, size=12, color='FFFFFF')
    c.fill = PatternFill('solid', fgColor=laz_onetoone__BK_DARK)
    ws.row_dimensions[row].height = 19
    return row + 1
from openpyxl.utils import get_column_letter

def laz_onetoone___bk_note(ws, row, text, ncol, colour=laz_onetoone__BK_BLUE, height=32):
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=max(ncol, 2))
    c = ws.cell(row, 1, text)
    c.font = Font(size=10, color='FFFFFF')
    c.fill = PatternFill('solid', fgColor=colour)
    c.alignment = Alignment(wrap_text=True, vertical='center')
    ws.row_dimensions[row].height = height
    return row + 2

def laz_onetoone___bk_table(ws, row, headers, rows, widths, wrapcols=(), colour_col=None):
    for j, h in enumerate(headers, 1):
        c = ws.cell(row, j, h)
        c.font = Font(bold=True, size=10, color='FFFFFF')
        c.fill = PatternFill('solid', fgColor=laz_onetoone__BK_BLUE)
        c.border = laz_onetoone__BK_BOX
        c.alignment = Alignment(horizontal='center', wrap_text=True, vertical='center')
    ws.row_dimensions[row].height = 28
    for i, rv in enumerate(rows):
        r = row + 1 + i
        for j, v in enumerate(rv, 1):
            c = ws.cell(r, j, v)
            c.border = laz_onetoone__BK_BOX
            c.font = Font(size=10)
            if j in wrapcols:
                c.alignment = Alignment(wrap_text=True, vertical='top')
            if colour_col and j == colour_col and isinstance(v, (int, float)):
                c.fill = PatternFill('solid', fgColor='E8F5EC' if v > 0 else 'FCEAE8')
    for j, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(j)].width = w
    return row + len(rows) + 2

def laz_onetoone___bk_backlink(ws, col):
    """Places the back-link clear of any merged title band. Writing into a merged range raises
    'MergedCell object attribute value is read-only', which is how this was caught."""
    merged_max = 0
    for rng in ws.merged_cells.ranges:
        if rng.min_row <= 1 <= rng.max_row:
            merged_max = max(merged_max, rng.max_col)
    col = max(col, merged_max + 2)
    c = ws.cell(1, col, '← Dashboard')
    c.hyperlink = "#'Dashboard'!A1"
    c.font = Font(size=10, color='0563C1', underline='single', bold=True)

def laz_onetoone___lz_say(msg):
    """M01: these seven diagnostics used print(), so they reached the terminal
    but NOT laz_log._SINK — and dump() writes _SINK. The operator pastes the
    .log and the [ledger][WARN] line was simply not in it."""
    _LG = _m('laz_log')
    if _LG is not None:
        try:
            _LG.line(str(msg), stg='book')
            return
        except Exception as _e:
            pass
    laz_onetoone___lz_say(msg, flush=True)

def laz_onetoone__build_one_to_one_sheets(wb, T, ledgers, sport=None, verbose=True):
    """Full v48-detail per-bet sheet for every validated strategy. Called inside the per-sport loop.

    Carries: tier banner, five-segment evidence block, numbered conditions, entry/stake/settlement
    rules, the raw engine spec, and the complete bet ledger with the LITERAL phase text from the
    triggering row, live running P&L and rolling win-rate formulas, WIN/LOSS fill and a frozen
    header."""
    if T is None or not len(T) or (not ledgers):
        return 0
    seg = ['is', 'oos', 'fwd', 'bwd', 'frz']
    segl = ['IS', 'OOS', 'FORWARD', 'BACKWARD', 'FREEZE']
    _G = {'causality': 'PASS', 'replay': 'PASS', 'live': 'PASS', 'null': 'PASS'}
    if 'name' in T.columns:
        _awarded = set()
        for _sp2, _V2 in laz_onetoone__laz_registry().items():
            for _x2 in _V2:
                if not _x2.get('enabled'):
                    continue
                _st2, _ = laz_onetoone__laz_award(_x2.get('metrics') or {}, gates=_x2.get('gates') or _G)
                if _st2:
                    _awarded.add(_x2['name'])
        _keep = T['name'].isin(_awarded)
        if 'tier' in T.columns:
            _keep = _keep | T['tier'].astype(str).str.upper().str.startswith('TIER')
        if _keep.any():
            _dropped = int((~_keep).sum())
            T = T[_keep]
            if verbose and _dropped:
                laz_onetoone___lz_say(f'[book]   {sport}: {_dropped} row(s) withheld — neither awarded nor Tier 1-5. They are in the ledger with what they unlock.')
    val = T
    if all((c in T.columns for c in ('is_n', 'oos_n', 'oos_roi'))):
        _isn = pd.to_numeric(T['is_n'], errors='coerce')
        _oon = pd.to_numeric(T['oos_n'], errors='coerce')
        _roi = pd.to_numeric(T['oos_roi'], errors='coerce')
        _bar = (_isn >= laz_onetoone__LAZ_SHEET_BAR['is_n']) & (_oon >= laz_onetoone__LAZ_SHEET_BAR['oos_n']) & (_roi >= laz_onetoone__LAZ_SHEET_BAR['oos_roi'])
        if _bar.any():
            val = T[_bar]
            if verbose:
                laz_onetoone___lz_say(f'[book]   {sport}: {int(_bar.sum())} of {len(T)} clear the sheet bar (IS>={laz_onetoone__LAZ_SHEET_BAR['is_n']}, OOS>={laz_onetoone__LAZ_SHEET_BAR['oos_n']}, ROI>={laz_onetoone__LAZ_SHEET_BAR['oos_roi']}%)')
        elif 'tier' in T.columns:
            val = T[T.tier != 'NOT VALIDATED']
    elif 'tier' in T.columns:
        val = T[T.tier != 'NOT VALIDATED']
    if sport is not None and 'sport' in val.columns:
        val = val[val.sport == sport]
    GREENF = PatternFill('solid', fgColor='E8F5EC')
    REDF = PatternFill('solid', fgColor='FCEAE8')
    made = 0
    _extra_rows = []
    _known = set(val['name'].astype(str)) if 'name' in val.columns else set()
    for _k, _payload in ledgers.items():
        _sp, _nm = _k if isinstance(_k, tuple) and len(_k) == 2 else (sport, _k)
        if sport is not None and _sp != sport:
            continue
        if str(_nm) in _known:
            continue
        _org = _payload[0] if isinstance(_payload, (tuple, list)) and len(_payload) == 3 else ''
        if _org != 'laz_registry':
            continue
        _sp_rec = _payload[1] if isinstance(_payload, (tuple, list)) and len(_payload) == 3 else {}
        if isinstance(_sp_rec, dict) and _sp_rec.get('metrics') and (not laz_onetoone__laz_meets_sheet_bar(_sp_rec)):
            continue
        _L = _payload[2] if isinstance(_payload, (tuple, list)) and len(_payload) == 3 else None
        if _L is None or not len(_L):
            continue
        _extra_rows.append({'name': _nm, 'sport': _sp, 'tier': 'TIER 2', 'n_bets': len(_L), 'origin': 'laz_registry'})
    if _extra_rows:
        val = pd.concat([val, pd.DataFrame(_extra_rows)], ignore_index=True)
        if verbose:
            laz_onetoone___lz_say(f'[book]   {sport}: +{len(_extra_rows)} REGISTERED ledger(s) added to the sheet queue (not present in the tiering table)')
    OW = _m('laz_owner')
    _cap = (OW.LAZ_OWNER.get('report', {}) or {}).get('one_to_one', 25) if OW else 25
    if 'stars' in val.columns:
        val = val.sort_values([c for c in ('stars', 'oos_roi', 'n_bets', 'bets') if c in val.columns], ascending=False)
    elif 'oos_roi' in val.columns:
        val = val.sort_values('oos_roi', ascending=False)
    _total = len(val)
