    for t, d in (('Mixed', 'cross-tier ladders · cap set by the weakest leg'), ('Satoro', '3 legs · 1-2 Unchained + any tier'), ('Bankai', '2 legs · Ultra and Alpha only')):
        c = ws.cell(r, 1, t)
