# LAZ_BRAIN MODULE: laz_spec_sheet
# §laz_spec_sheet   <- grep this anchor to land here
# ==========================================================================
"""laz_spec_sheet.py — THE IMPLEMENTATION SHEET.

One row per strategy, carrying everything needed to RE-CREATE and PLACE it in
real time without reading any other file. Not a summary — a specification.

WHAT EACH ROW CARRIES

  IDENTITY     name · sport · base · market · side · rung · origin · tier
  ARMING       the full condition stack, one condition per column so a live
               engine can evaluate them without parsing a string, PLUS the
               single AND-joined text for a human
  EACH TERM    its formula, its source columns, the tick at which it resolves,
               and whether it is a live value or a record of a past event
  SETTLEMENT   what is backed, at what price column, graded against what
  MEASURED     n IS · n OOS · win IS · win OOS · odds · ROI IS · ROI OOS ·
               bets · per-day · the reconciliation gap between stated ROI and
               win x odds, which is the check that catches a fabricated
               settlement
  PLACEMENT    min odds floor, tier cap, whether it can stack at all, market
               status columns to watch, and the hold window
  LINEAGE      frame · source table · generated date · gate · causality rules

WHY THE PER-TERM DETAIL MATTERS

A condition reading `u_pace >= 1.83` is not implementable by itself. A live
system needs to know that u_pace is (h_score+a_score)/max(elapsed,0.02), that
it is built from h_score, a_score and the elapsed column, that it is knowable
at every tick, and that elapsed is normalised 0-1 by the frame loader. Without
that the number is a magic constant.
"""
import os, re, json
import numpy as np, pandas as pd

def laz_spec_sheet___laz_home():
    """The directory this run writes to. Defaults to the CURRENT directory,
    never the container the engine was built in. _laz_home() shipped inside
    the single file and every write failed on the operator's machine with
    FileNotFoundError after the search had already run."""
    import os as _o
    OW = _m('laz_owner') if '_m' in globals() else None
    if OW is not None:
        d = (getattr(OW, 'LAZ_OWNER', {}).get('paths', {}) or {}).get('output_dir')
        if d:
            return d
    return _o.environ.get('LAZ_HOME') or _o.getcwd()

def laz_spec_sheet___safe_resolves(LA, term):
    try:
        return LA.resolves_at(term)
    except Exception:
        return None

def laz_spec_sheet___feat():
    p = __import__('os').path.join(laz_spec_sheet___laz_home(), 'everything_features.json')
    return _laz_json_read(p) if os.path.exists(p) else {}

def laz_spec_sheet___cat():
    CT = _m('laz_catalogue')
    return (CT.load() if CT else {}) or {}

def laz_spec_sheet__terms_of(conditions):
    out = []
    for c in str(conditions).split(' AND '):
        c = c.strip()
        if not c:
            continue
        m = re.match('^([A-Za-z_][A-Za-z0-9_]*)\\s*(>=|<=|>|<|==|!=)\\s*(-?[\\d.eE+]+)$', c)
        if m:
            out.append((m.group(1), m.group(2), float(m.group(3)), c))
        else:
            out.append((c.split(' ')[0], '?', np.nan, c))
    return out

def laz_spec_sheet__document_term(term):
    """Formula, sources, resolution time and kind for one condition term."""
    F = laz_spec_sheet___feat()
    C = laz_spec_sheet___cat().get('feature', {})
    f = F.get(term) or {}
    c = C.get(term) or {}
    LA = _m('laz_lookahead')
    CG = _m('causality_guard')
    r = f.get('resolves_at') or c.get('resolves_at')
    if r is None and LA is not None:
        LG = _m('laz_log')
        r = LG.guard('resolves_at', LA.resolves_at, term) if LG is not None else laz_spec_sheet___safe_resolves(LA, term)
    kind = 'live'
    if CG is not None:
        tl = str(term).lower()
        if tl in getattr(CG, 'STATE_SCOPED', {}):
            kind = 'state-record (event must have occurred)'
        elif CG.resolves_at(term) == 'event':
            kind = 'event-gated (per row: the event must have happened)'
        elif CG.resolves_at(term):
            kind = f'resolves at {CG.resolves_at(term)} elapsed'
    return dict(formula=f.get('formula') or c.get('formula') or c.get('code') or '', definition=f.get('definition') or c.get('definition') or c.get('legend') or '', source_columns=f.get('source_columns') or '|'.join(c.get('columns') or []), units=f.get('units') or '', tier=f.get('tier') or '', resolves_at=r, kind=kind, universal_equivalent=f.get('universal_equivalent') or '')

def laz_spec_sheet__build(book, sport=None, log=print):
    """One fully documented row per strategy, plus a term dictionary."""
    OW = _m('laz_owner')
    CB = _m('laz_combina')
    B = book.copy()
    if sport and 'sport' in B.columns:
        B = B[B.sport.astype(str).str.lower() == str(sport).lower()]
    tiers = OW.LAZ_OWNER['combination']['tiers'] if OW else {}
    mot = OW.LAZ_OWNER['combination'].get('min_odds_by_tier', {}) if OW else {}
    status = OW.LAZ_OWNER['combination'].get('status_columns', {}) if OW else {}
    rows = []
    termset = {}
    maxc = 0
    for _, r in B.iterrows():
        ts = laz_spec_sheet__terms_of(r.get('conditions', ''))
        maxc = max(maxc, len(ts))
    for _, r in B.iterrows():
        w = pd.to_numeric(pd.Series([r.get('oos_win')]), errors='coerce').iloc[0]
        od = pd.to_numeric(pd.Series([r.get('odds')]), errors='coerce').iloc[0]
        roi = pd.to_numeric(pd.Series([r.get('oos_roi')]), errors='coerce').iloc[0]
        tier, cap = CB.tier_of(w, tiers) if CB and w == w else (None, 0)
        implied = (w / 100.0 * od - 1) * 100 if w == w and od == od else np.nan
        mk = str(r.get('market') or 'moneyline')
        row = dict(strategy=r.get('strategy_name'), sport=r.get('sport'), base=r.get('base'), market=mk, side=r.get('side'), rung=r.get('rung') or r.get('band'), origin=r.get('origin'), family=r.get('family'), tier=tier or 'below Gamma (single bet only)', max_legs_in_a_stack=cap, can_stack=bool(cap >= 2), conditions=r.get('conditions'), n_conditions=len(laz_spec_sheet__terms_of(r.get('conditions', ''))), backed='over/under vs the arm-tick line' if 'total' in mk else 'the side named by the base', price_column='total_goals_under / _over' if 'total' in mk else 'home_odds / away_odds', graded_against='final_tg vs the line AT THE ARM TICK' if 'total' in mk else 'final_result', n_is=r.get('n_is'), n_oos=r.get('n_oos'), bets=r.get('bets'), per_day=r.get('per_day'), win_is=r.get('is_win'), win_oos=w, odds=od, roi_is=r.get('is_roi'), roi_oos=roi, implied_roi_from_win_x_odds=round(implied, 1) if implied == implied else np.nan, reconciliation_gap=round(roi - implied, 1) if roi == roi and implied == implied else np.nan, min_odds_floor=mot.get(tier, 1.4), hold_seconds=OW.LAZ_OWNER['combination'].get('hold_sec', 5.0) if OW else 5.0, combination_window_sec=OW.LAZ_OWNER['combination'].get('window_sec', 30.0) if OW else 30.0, market_status_columns='|'.join(status.get(mk, ()) or status.get('any', ())), one_bet_per_match=True, frame=r.get('lineage_frame'), source_table=r.get('source_table'), generated=r.get('generated'), gate=r.get('gate'), causality=r.get('causality'), perm_p=r.get('perm_p'), bh_pass=r.get('bh_pass'))
        for i, (t, op, val, raw) in enumerate(laz_spec_sheet__terms_of(r.get('conditions', '')), 1):
            row[f'cond{i}_term'] = t
            row[f'cond{i}_op'] = op
            row[f'cond{i}_value'] = val
            if t not in termset:
                termset[t] = laz_spec_sheet__document_term(t)
        rows.append(row)
    S = pd.DataFrame(rows)
    T = pd.DataFrame([dict(term=k, **v) for k, v in sorted(termset.items())])
    log(f'  [spec] {len(S)} strategies documented · {len(T)} distinct terms · max {maxc} conditions')
    return (S, T)

def laz_spec_sheet__to_excel(book, path=None, sport=None, log=print):
    WB = _m('laz_workbook')
    OW = _m('laz_owner')
    path = path or os.path.join(OW.LAZ_OWNER['paths']['output_dir'] if OW else '.', f'LAZ_IMPLEMENTATION{('_' + sport if sport else '')}.xlsx')
    S, T = laz_spec_sheet__build(book, sport=sport, log=log)
    b = WB.Book(path, 'LAZARUS IMPLEMENTATION SHEET', 'every strategy, every condition, every term — enough to re-create and place in real time', sport=sport or '')
    stack = int(S.can_stack.sum()) if len(S) else 0
    b.dashboard([('Strategies documented', len(S)), ('  stackable (tier Gamma or better)', stack), ('  single bet only', len(S) - stack), ('Distinct condition terms', len(T)), ('Max conditions in one strategy', int(S.n_conditions.max()) if len(S) else 0), ('', ''), ('Worst reconciliation gap', f'{S.reconciliation_gap.abs().max():.1f} pts' if len(S) and S.reconciliation_gap.notna().any() else 'n/a'), ('   (stated ROI vs win x odds — catches a fabricated settlement)', '')])
    b.table(S, 'STRATEGIES', title='EVERY STRATEGY — identity, arming, settlement, measurement, placement, lineage', stars_from=('n_is', 'n_oos', 'roi_oos'), colour_scale=['roi_oos'], tier_col='tier')
    b.table(T, 'TERMS', title='EVERY CONDITION TERM — formula, source columns, when it resolves')
    b.method([('How to place one', 'Arm when EVERY cond{i} holds at the same tick. Back what `backed` names, at `price_column`. One bet per match — the FIRST tick that satisfies the chain.'), ('Settlement', 'Grade against `graded_against`. For totals that is the final total versus the line AT THE ARM TICK, not the line at settlement — the line drifts.'), ('reconciliation_gap', 'stated OOS ROI minus (win rate x odds - 1). Anything above a few points means the settlement does not match the price, which is how two defects were caught.'), ('can_stack', 'False means the strategy is below the 75% Gamma floor. It is a valid single bet and cannot join a combination.'), ('resolves_at', '0 means knowable at every tick. 0.25 means not until the first quarter ends — the bet may not arm before that point.'), ('kind', '"live" is a current value. "state-record" means it describes a past event and is only legal where that event has occurred.')])
    return b.save(log)
