import os, sys, subprocess, tempfile, json, re, base64, zlib   # [v192 S1] `datetime` removed for the same reason as laz_production
laz_audit___BLOB = None
laz_audit__SCRIPTS = {}

def laz_audit___load_scripts():
    if not laz_audit__SCRIPTS:
        laz_audit__SCRIPTS.update(json.loads(zlib.decompress(base64.b64decode(laz_audit___BLOB)).decode('utf-8')))
    return laz_audit__SCRIPTS
laz_audit__KINDS = ['audit360', 'audit_full', 'prove_stride', 'prove_rejections', 'prove_reclaim', 'prove_generative', 'prove_causal_elapsed', 'prove_checkpoints', 'prove_derived_freshness', 'prove_end_to_end', 'prove_fixpass2', 'prove_flow_handoffs', 'prove_fork_lineage', 'prove_no_signal', 'prove_register_loop', 'prove_rung_split', 'prove_settlement_doors', 'prove_settlement_legacy', 'prove_tandem', 'prove_truncation_guard', 'verify_h2h_causality', 'prove_no_deprecation', 'prove_cleanse', 'prove_workers', 'prove_docs', 'prove_feature_registry', 'prove_synth', 'prove_index', 'prove_provenance', 'prove_lineage_contracts', 'prove_manufacture', 'prove_build_integrity', 'prove_owner_bar', 'prove_market_gate', 'prove_handicap_settlement']
laz_audit___HEAVY = ('prove_end_to_end',)
laz_audit___KINDS_OLD = ['audit360', 'audit_full', 'prove_causal_elapsed', 'prove_checkpoints', 'prove_fixpass2', 'prove_flow_handoffs', 'prove_fork_lineage', 'prove_register_loop', 'prove_rung_split', 'prove_settlement_doors', 'prove_settlement_legacy', 'prove_tandem', 'verify_h2h_causality']

def laz_audit___engine_path():
    OW = _m('laz_owner')
    p = (OW.LAZ_OWNER.get('audit', {}) or {}).get('engine_path') if OW else None
    if p and os.path.exists(p):
        return p
    for c in (os.environ.get('LAZ_ENGINE'), sys.argv[0] if sys.argv and sys.argv[0].endswith('.py') else None):
        if c and os.path.exists(c) and ('LazarusEV_Engine' in os.path.basename(c)):
            return os.path.abspath(c)
    home = (OW.LAZ_OWNER['paths'].get('output_dir') if OW else '.') or '.'
    cands = sorted([f for f in os.listdir(home) if f.startswith('LazarusEV_Engine') and f.endswith('.py')], key=lambda f: os.path.getmtime(os.path.join(home, f)), reverse=True)
    return os.path.join(home, cands[0]) if cands else None

def laz_audit___materialise(kinds, where):
    os.makedirs(where, exist_ok=True)
    for k in kinds:
        with open(os.path.join(where, k + '.py'), 'w', encoding='utf-8') as f:
            f.write(laz_audit__SCRIPTS[k])
laz_audit___SUCCESS = {'prove_stride': ('STRIDE: ALL PASS',), 'prove_rejections': ('REJECTIONS: ALL PASS',), 'prove_reclaim': ('RECLAIM: ALL PASS',), 'prove_generative': ('GENERATIVE: ALL PASS',), 'prove_handicap_settlement': ('HANDICAP SETTLEMENT: ALL PASS',), 'prove_market_gate': ('MARKET GATE: ALL PASS',), 'prove_owner_bar': ('OWNER BAR: ALL PASS',), 'prove_build_integrity': ('BUILD INTEGRITY: ALL PASS',), 'prove_manufacture': ('MANUFACTURE: ALL PASS',), 'prove_lineage_contracts': ('LINEAGE CONTRACTS: ALL PASS',), 'prove_provenance': ('PROVENANCE: ALL PASS',), 'prove_index': ('INDEX: ALL PASS',), 'prove_synth': ('SYNTH: ALL PASS',), 'prove_synth': ('SYNTH: ALL PASS',), 'prove_feature_registry': ('FEATURE REGISTRY: ALL PASS',), 'prove_docs': ('DOCS: ALL PASS',), 'prove_workers': ('WORKERS: ALL PASS',), 'prove_cleanse': ('CLEANSE: ALL PASS',), 'prove_no_deprecation': ('NO DEPRECATION: ALL PASS',), 'audit360': ('VERDICT: SHIP (',), 'audit_full': ('VERDICT: SHIP (',), 'prove_checkpoints': ('ALL PASS',), 'prove_rung_split': ('identical sets: True',), 'prove_causal_elapsed': ('D18 PROOF: PASS',), 'prove_fixpass2': ('FIX PASS 2: ALL PASS',), 'prove_settlement_doors': ('settlement columns IN THE POOL: NONE',), 'prove_settlement_legacy': ('in the POOL after prepare : NONE',), 'prove_flow_handoffs': ('FAILED 0',), 'prove_tandem': ('DISAGREE',), 'prove_fork_lineage': ('inherits it',), 'prove_register_loop': ('DID NOT SURVIVE',), 'verify_h2h_causality': ('PASS — every column is historical',)}
laz_audit___FAILURE = {'prove_tandem': ('DISAGREE',), 'prove_register_loop': ('DID NOT SURVIVE',)}

def laz_audit___verdict(kind, out, rc):
    if kind in laz_audit___FAILURE:
        return rc == 0
    toks = laz_audit___SUCCESS.get(kind)
    if not toks:
        return rc == 0
    return any((t in out for t in toks)) and 'Traceback' not in out

def laz_audit__run(kind, engine=None, args=(), log=print, timeout=600, where=None):
    """Run one embedded audit / proof / verifier against the shipped engine. Returns (ok, text).
    [AmunEV V2.9] `where` = a folder already prepared by run_all (the scripts, the engine and the runner in it) — one
    folder PER PROOF, so proofs can run side by side without sharing a working directory."""
    laz_audit___load_scripts()
    if kind not in laz_audit__SCRIPTS:
        return (False, f'unknown audit {kind!r}; have {sorted(laz_audit__SCRIPTS)}')
    eng = engine or laz_audit___engine_path()
    if eng is None and kind not in ('verify_h2h_causality',):
        return (False, 'engine file not found — set LAZ_OWNER["audit"]["engine_path"] or LAZ_ENGINE')
    if where is None:
        where = os.path.join(tempfile.gettempdir(), 'laz_audit_' + __import__('datetime').datetime.now().strftime('%Y%m%d'))
        laz_audit___materialise(list(laz_audit__SCRIPTS), where)
        if eng:
            import shutil
            shutil.copy(eng, os.path.join(where, 'LazarusEV_Engine_v186_ABSORB.py'))
            try:
                shutil.copy(os.path.join(os.path.dirname(eng), 'run_m5.py'), os.path.join(where, 'run_m5.py'))
            except Exception:
                pass
    _args = [os.path.abspath(a) if isinstance(a, str) and os.path.exists(a) else a for a in args]
    cmd = [sys.executable, os.path.join(where, kind + '.py')] + ([os.path.join(where, 'LazarusEV_Engine_v186_ABSORB.py')] if kind in ('audit360', 'audit_full') else _args)
    try:
        # [v187 A1] a SEALED environment: the proofs plant their own frames, so no frame/home variable of the
        # caller may reach them (--smoke set LAZ_PARQUET_DIR to real slices and the gate then judged real
        # frames instead of its plants: two false CRITICALs). Only LAZ_ENGINE and the interpreter pass through.
        _env = {k: v for k, v in os.environ.items() if not (k.startswith('LAZ_') or k.startswith('LAZARUS_'))}
        _env['LAZ_ENGINE'] = os.environ.get('LAZ_ENGINE', eng)
        _env['OMP_NUM_THREADS'] = '1'
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=where, env=_env)
    except subprocess.TimeoutExpired:
        return (False, f'{kind}: timed out after {timeout}s')
    out = (r.stdout or '') + (r.stderr or '')
    ok = laz_audit___verdict(kind, out, r.returncode)
    if log:
        log(f'[audit] {kind}: {('PASS' if ok else 'FAIL')}')
    return (ok, out)

def laz_audit__run_all(engine=None, kinds=None, log=print):
    """Every audit and proof. Returns dict kind -> (ok, text)."""
    OW = _m('laz_owner')
    A = OW.LAZ_OWNER.get('audit', {}) or {} if OW else {}
    laz_audit___load_scripts()
    ks = kinds or A.get('kinds') or [k for k in laz_audit__SCRIPTS if k != 'verify_h2h_causality' and (k not in laz_audit___HEAVY or A.get('end_to_end', False))]
    # [AmunEV V2.12 — THE BATTERY, FAST] (a) a FULL battery that passed on these exact bytes — engine sha + runner sha + python/pandas/
    # numpy versions — is not re-run: same inputs, same verdict, the rule the audit360/audit_full gate already follows. One changed byte
    # in either file runs all of it. LAZ_AUDIT_ALWAYS=1 forces. (b) up to cores-2 processes (max 6; LAZ_AUDIT_WORKERS overrides) instead
    # of the search default of 4. (c) the slowest proofs start first (each proof's time is recorded in laz_memory_audit_timings.json), so
    # the battery ends when its longest proof ends, not after it queued behind the short ones.
    _full = (kinds is None) and not A.get('kinds')
    _bstamp = None; _envk = ''; _odir = os.getcwd(); _esh = _rsh = None
    try:
        import hashlib as _hb, sys as _sysb, pandas as _pdb, numpy as _npb
        _engb = engine or laz_audit___engine_path()
        _rb = os.path.join(os.path.dirname(_engb), 'run_m5.py') if _engb else None
        def _sha16(_p):
            with open(_p, 'rb') as _fh:
                return _hb.sha256(_fh.read()).hexdigest()[:16]
        _esh = _sha16(_engb) if _engb and os.path.exists(_engb) else None
        _rsh = _sha16(_rb) if _rb and os.path.exists(_rb) else 'none'
        _envk = f'py{_sysb.version_info[0]}.{_sysb.version_info[1]}-pandas{_pdb.__version__}-numpy{_npb.__version__}'
        _odir = ((OW.LAZ_OWNER.get('paths', {}) or {}).get('output_dir') if OW else None) or os.getcwd()
        _bstamp = os.path.join(_odir, f'laz_battery_passed_{_esh}_{_rsh}.json') if _esh else None
        if _full and _bstamp and os.path.exists(_bstamp) and os.environ.get('LAZ_AUDIT_ALWAYS', '0') != '1':
            with open(_bstamp) as _bf:
                _rec = json.load(_bf)
            if _rec.get('env') == _envk and set(_rec.get('kinds', [])) >= set(ks):
                if log:
                    log(f'[audit] the full battery PASSED on this exact engine {_esh} + runner {_rsh} ({_envk}) at {_rec.get("passed_at")} — not re-run (LAZ_AUDIT_ALWAYS=1 forces)')
                return {k: (True, f'VERDICT: SHIP — cached PASS from {_rec.get("passed_at")} on these exact bytes · ALL PASS') for k in ks}
    except Exception:
        _bstamp = None
    _times = {}
    try:
        with open(os.path.join(_odir, 'laz_memory_audit_timings.json')) as _tf:
            _times = json.load(_tf)
    except Exception:
        _times = {}
    # [AmunEV V2.15] on a NEW engine the boot gate has just run audit360 + audit_full (~6 min); the full battery ran both AGAIN.
    # If this sha's gate stamp is on disk from today, those two are taken as PASS from it and not re-run.
    _cached = {}
    try:
        _gst = os.path.join(_odir, f'laz_audit_passed_{_esh}.json') if _esh else None
        if _full and _gst and os.path.exists(_gst) and os.environ.get('LAZ_AUDIT_ALWAYS', '0') != '1':
            with open(_gst) as _gf:
                _grec = json.load(_gf)
            import datetime as _dtg
            _gage = (_dtg.datetime.now() - _dtg.datetime.fromisoformat(_grec.get('passed_at'))).total_seconds() / 3600.0
            if _gage <= 24.0:
                for _gk in _grec.get('kinds', []):
                    if _gk in ks:
                        _cached[_gk] = (True, f'VERDICT: SHIP — PASSED by the boot gate {_gage:.1f}h ago on this exact engine · ALL PASS')
                if _cached:
                    ks = [k for k in ks if k not in _cached]
                    if log:
                        log(f'[audit] {", ".join(sorted(_cached))} PASSED by the boot gate on this engine — not re-run in the battery')
    except Exception:
        _cached = {}
    _heavy_first = ('audit360', 'prove_no_signal', 'prove_generative', 'prove_provenance', 'prove_synth', 'prove_workers', 'prove_end_to_end', 'audit_full', 'prove_truncation_guard', 'prove_index')
    _order = sorted(ks, key=lambda k: (-float(_times.get(k, 0.0)), (_heavy_first.index(k) if k in _heavy_first else len(_heavy_first))))
    # [AmunEV V2.9 — THE 16-MINUTE BATTERY] 35 proofs ran ONE AFTER ANOTHER, each copying the 14.5 MB engine and reloading it
    # (13.5 s a load = 8 min of loading alone). Now: the engine is copied once and hard-linked into ONE FOLDER PER PROOF (its own
    # cwd, so no two proofs share a working directory), and the proofs run side by side.
    _n = 1
    if os.environ.get('LAZ_AUDIT_SERIAL', '0') != '1' and len(ks) > 1:
        try:
            _n = int(os.environ.get('LAZ_AUDIT_WORKERS', '0') or 0) or int(A.get('workers') or 0) or min(6, max(1, (os.cpu_count() or 2) - 2))
        except Exception:
            _n = 1
        _n = max(1, min(int(_n), len(ks), os.cpu_count() or 1))
    eng = engine or laz_audit___engine_path()
    _res = dict(_cached)
    if not ks:
        return _res
    if _n <= 1 or not eng:
        for k in ks:
            _res[k] = laz_audit__run(k, engine=engine, log=log)
        _ok_gate = all(_res.get(k, (False, ''))[0] for k in ('audit360', 'audit_full') if k in _res) and any(k in _res for k in ('audit360', 'audit_full'))
    else:
        import shutil, time as _tm
        from concurrent.futures import ThreadPoolExecutor
        _root = os.path.join(tempfile.gettempdir(), 'laz_audit_' + __import__('datetime').datetime.now().strftime('%Y%m%d_%H%M%S'))
        os.makedirs(_root, exist_ok=True)
        _eng1 = os.path.join(_root, 'LazarusEV_Engine_v186_ABSORB.py'); shutil.copy(eng, _eng1)
        _run1 = os.path.join(os.path.dirname(eng), 'run_m5.py')
        _dirs = {}
        for k in ks:
            _w = os.path.join(_root, k); laz_audit___materialise(list(laz_audit__SCRIPTS), _w)
            for _src, _nm in ((_eng1, 'LazarusEV_Engine_v186_ABSORB.py'), (_run1, 'run_m5.py')):
                if os.path.exists(_src):
                    try:
                        os.link(_src, os.path.join(_w, _nm))
                    except Exception:
                        shutil.copy(_src, os.path.join(_w, _nm))
            _dirs[k] = _w
        if log:
            log(f'[audit] {len(ks)} proofs on {_n} processes, slowest first (one folder each under {_root})')
        _t0 = _tm.time()
        def _one(k):
            _t = _tm.time(); r = laz_audit__run(k, engine=engine, log=None, where=_dirs[k]); return (k, r, _tm.time() - _t)
        with ThreadPoolExecutor(max_workers=_n) as _ex:
            for k, r, _dt in _ex.map(_one, _order):
                _res[k] = r
                _times[k] = round(float(_dt), 1)
                if log:
                    log(f'[audit]   {k:28} {"PASS" if r[0] else "FAIL"}  {_dt:5.0f}s')
        if log:
            log(f'[audit] battery done in {_tm.time() - _t0:.0f}s · {sum(1 for v in _res.values() if v[0])} PASS · {sum(1 for v in _res.values() if not v[0])} FAIL')
        _res = {**_cached, **{k: _res[k] for k in ks if k in _res}}
        try:
            with open(os.path.join(_odir, 'laz_memory_audit_timings.json'), 'w') as _tf:
                json.dump(_times, _tf, indent=1)
        except Exception:
            pass
        _ok_gate = all(_res.get(k, (False, ''))[0] for k in ('audit360', 'audit_full') if k in _res and k not in _cached) and any(k in _res and k not in _cached for k in ('audit360', 'audit_full'))
    if _ok_gate:
        laz_audit___write_pass_stamp(eng, [k for k in ('audit360', 'audit_full') if k in _res], log=log)   # the sport will not run them again today
    if _full and _bstamp and _res and all(v[0] for v in _res.values()) and set(_res) >= (set(ks) | set(_cached)):
        try:
            import datetime as _dtb
            with open(_bstamp, 'w') as _bf:
                json.dump(dict(engine=_esh, runner=_rsh, env=_envk, kinds=sorted(_res), passed_at=_dtb.datetime.now().isoformat(timespec='seconds')), _bf, indent=1)
            if log:
                log(f'[audit] full battery PASS recorded for engine {_esh} + runner {_rsh} — later runs on these exact files skip it')
        except Exception:
            pass
    return _res

def laz_audit___write_pass_stamp(eng, kinds, log=None):
    """[AmunEV V2.9] the day's pass stamp for audit360/audit_full — written by the gate AND by a passing battery."""
    try:
        import hashlib as _h, datetime as _dt
        OW = _m('laz_owner')
        _sha = None
        if eng and os.path.exists(eng):
            with open(eng, 'rb') as _ef:
                _sha = _h.sha256(_ef.read()).hexdigest()[:16]
        if not _sha:
            return
        _stamp = os.path.join(((OW.LAZ_OWNER['paths'].get('output_dir') if OW else None) or os.getcwd()), f'laz_audit_passed_{_sha}.json')
        with open(_stamp, 'w') as _sf:
            json.dump(dict(sha=_sha, kinds=list(kinds), passed_at=_dt.datetime.now().isoformat(timespec='seconds')), _sf)
        if log:
            log(f'[audit] pass stamp written for {_sha}: the sport run will not repeat audit360 + audit_full today')
    except Exception:
        pass

def laz_audit__gate(engine=None, log=print):
    """The pre-run gate: audits that must SHIP before a sport runs. Honours
    LAZ_OWNER['audit']['run_on_start'] and ['fail_blocks_run']. Returns True to proceed."""
    OW = _m('laz_owner')
    A = OW.LAZ_OWNER.get('audit', {}) or {} if OW else {}
    if not A.get('run_on_start', True):
        return True
    # [AmunEv v1 SPEED] A PASS IS A PASS FOR THE DAY. The gate audits the SOURCE; the source does not
    # change between sports. A stamp keyed on the engine file's sha256 records a PASS; the same sha on
    # the same day skips the 4 minutes. A different sha, a different day, LAZ_AUDIT_ALWAYS=1, or
    # LAZ_OWNER['audit']['pass_valid_hours'] = 0 runs it again.
    _kinds = A.get('gate_kinds', ['audit360', 'audit_full'])
    _stamp = None
    try:
        import hashlib as _h, datetime as _dt
        _eng = engine or laz_audit___engine_path()
        _sha = _h.sha256(open(_eng, 'rb').read()).hexdigest()[:16] if _eng and os.path.exists(_eng) else None
        _stamp = os.path.join((OW.LAZ_OWNER['paths'].get('output_dir') or os.getcwd()), f'laz_audit_passed_{_sha}.json') if _sha else None
        _hours = float(A.get('pass_valid_hours', 24) or 0)
        if _stamp and os.path.exists(_stamp) and os.environ.get('LAZ_AUDIT_ALWAYS', '0') != '1' and _hours > 0:
            with open(_stamp) as _sf:
                _rec = json.load(_sf)
            _age_h = (_dt.datetime.now() - _dt.datetime.fromisoformat(_rec.get('passed_at'))).total_seconds() / 3600.0
            if _age_h <= _hours and set(_rec.get('kinds', [])) >= set(_kinds):
                log(f"[audit] {' + '.join(_kinds)} PASSED {_age_h:.1f}h ago on this exact engine (sha {_sha}) — skipped (LAZ_AUDIT_ALWAYS=1 to force)")
                return True
    except Exception as _se:
        log(f'[audit] pass-stamp check: {type(_se).__name__}: {str(_se)[:60]} — running the gate')
    res = laz_audit__run_all(engine=engine, kinds=_kinds, log=log)
    if _stamp and all(ok for ok, _ in res.values()):
        try:
            with open(_stamp, 'w') as _sf:
                json.dump(dict(sha=_sha, kinds=list(_kinds), passed_at=_dt.datetime.now().isoformat(timespec='seconds')), _sf)
        except Exception:
            pass
    bad = [k for k, (ok, _) in res.items() if not ok]
    if bad:
        for k in bad:
            v = [l for l in res[k][1].splitlines() if 'VERDICT' in l or 'HIGH' in l or 'CRITICAL' in l][:6]
            log(f'[audit] {k} did not SHIP: ' + ' | '.join((x.strip()[:80] for x in v)))
            for l in res[k][1].strip().splitlines()[-12:]:
                log(f'[audit]     {l.rstrip()[:150]}')
            if k == 'audit360':
                for pk in ('prove_settlement_doors', 'prove_settlement_legacy'):
                    _ok, _o = laz_audit__run(pk, engine=engine, log=None)
                    log(f'[audit]   {pk}: {('PASS' if _ok else 'FAIL')}')
                    if not _ok:
                        for l in _o.strip().splitlines()[-15:]:
                            log(f'[audit]       {l.rstrip()[:150]}')
        if A.get('fail_blocks_run', True):
            log('[audit] run BLOCKED — fix the findings or set LAZ_OWNER["audit"]["fail_blocks_run"]=False')
            return False
    return True
